// bootstrap/src/compiler.rs
// T27 → Zig Compiler Core (Lexer + Parser + Codegen)
//
// This module contains the core compiler logic extracted for reusability.
// It can be used by both CLI and HTTP server contexts.

use std::default::Default;

use serde::Serialize;

// ============================================================================
// AST Node Types (from parser.t27)
// ============================================================================

#[derive(Debug, Clone, PartialEq, Serialize)]
pub enum NodeKind {
    Module,
    UseDecl,
    ConstDecl,
    EnumDecl,
    EnumVariant,
    StructDecl,
    FnDecl,
    InvariantBlock,
    TestBlock,
    BenchBlock,
    ExprLiteral,
    ExprIdentifier,
    ExprEnumValue,
    ExprCall,
    ExprFieldAccess,
    ExprSwitch,
    ExprBinary,
    ExprUnary,
    ExprReturn,
    ExprIndex,
    ExprIf,
    ExprStructLit,
    ExprArrayLiteral,
    ExprTuple,
    ExprCast,
    ExprRange, // start..end
    // Statement nodes for fn bodies
    StmtLocal,  // const x = expr; or var x: T = expr;
    StmtAssign, // x = expr; or x.field = expr;
    StmtIf,     // if (...) { ... } else if (...) { ... } else { ... }
    StmtWhile,  // while (cond) { ... }
    StmtFor,    // for (iter) |capture| { ... }
    StmtForRange, // for i in start..end { ... }
    StmtBreak,
    StmtContinue,
    StmtExpr, // bare expression statement: func(a, b);
}

#[derive(Debug, Clone, Serialize)]
#[allow(dead_code)]
pub struct Node {
    pub kind: NodeKind,
    pub name: String,
    pub value: String,
    pub extra_type: String,
    pub extra_field: String,
    pub extra_size: String,
    pub extra_kind: String,
    pub extra_op: String,
    pub extra_pragma: String,
    pub extra_pub: bool,
    pub extra_mutable: bool,
    pub extra_return_type: String,
    pub params: Vec<(String, String)>,
    pub line: u32,
    pub children: Vec<Node>,
}

impl Default for Node {
    fn default() -> Self {
        Self {
            kind: NodeKind::ExprLiteral,
            name: String::new(),
            value: String::new(),
            extra_type: String::new(),
            extra_field: String::new(),
            extra_size: String::new(),
            extra_kind: String::new(),
            extra_op: String::new(),
            extra_pragma: String::new(),
            extra_pub: false,
            extra_mutable: false,
            extra_return_type: String::new(),
            params: Vec::new(),
            line: 0,
            children: Vec::new(),
        }
    }
}

impl Node {
    pub fn new(kind: NodeKind) -> Self {
        Self {
            kind,
            name: String::new(),
            value: String::new(),
            extra_type: String::new(),
            extra_field: String::new(),
            extra_size: String::new(),
            extra_kind: String::new(),
            extra_op: String::new(),
            extra_pragma: String::new(),
            extra_pub: false,
            extra_mutable: false,
            extra_return_type: String::new(),
            params: Vec::new(),
            line: 0,
            children: Vec::new(),
        }
    }

    #[allow(dead_code)]
    pub fn with_child(mut self, child: Node) -> Self {
        self.children.push(child);
        self
    }
}

// ============================================================================
// Lexer (minimal implementation)
// ============================================================================

#[derive(Debug, Clone, PartialEq)]
pub enum TokenKind {
    /// `?` -- the optional-type marker (`?u64`) and Rust's error-propagation
    /// postfix. The lexer DISCARDED it as an unrecognised character, so `?u64`
    /// reached the backend as `u64`: an optional silently became a
    /// non-optional. 287 occurrences across the corpus, and
    /// `t27_array_type_to_zig` has handled a leading `?` since W561 -- the
    /// character never got there (W581).
    Question,
    /// A string literal that reached end-of-input without a closing quote.
    /// Distinct from `String` so the parser can reject it instead of treating
    /// the rest of the file as its contents (W577).
    UnterminatedString,
    // Keywords
    KwPub,
    KwConst,
    KwFn,
    KwEnum,
    KwStruct,
    KwTest,
    KwInvariant,
    KwBench,
    KwModule,
    KwIf,
    KwElse,
    KwFor,
    KwWhile,
    KwSwitch,
    KwReturn,
    KwVar,
    KwUsing,
    KwVoid,
    KwTrue,
    KwFalse,
    KwUse,
    KwOr,
    KwAnd,
    KwTry,
    KwBreak,
    KwContinue,
    KwIn,
    KwPragma,

    // Literals
    Ident,
    Number,
    String,
    CharLiteral,

    // Operators
    Plus,
    Minus,
    Star,
    Slash,
    Percent,
    Amp,
    Pipe,
    Caret,
    Tilde,
    Lt,
    Gt,
    Lte,
    Gte,
    Eq,
    Neq,

    // Delimiters
    Colon,
    Comma,
    Equals,
    LParen,
    RParen,
    LBrace,
    RBrace,
    LBracket,
    RBracket,
    Dot,
    Bang,

    // Multi-char
    Arrow,
    FatArrow,
    Power,
    DotDot,
    PlusPlus,
    ShiftLeft,
    ShiftRight,
    PlusEquals,
    // Only += existed. -=, *=, |=, &=, ^= lexed as two tokens and the parser died
    // on the bare '='. Among the 348 specs that do not generate, 6 use -=, 4 use *=
    // and 1 uses |= -- including specs/base/types.t27 at pack_trit line 172.
    MinusEquals,
    StarEquals,
    PipeEquals,
    AmpEquals,
    CaretEquals,
    SlashEquals,
    PercentEquals,
    PlusPercent,
    MinusPercent,
    StarPercent,

    // Special
    Semicolon,
    Eof,
}

impl Copy for TokenKind {}

#[derive(Debug, Clone)]
pub struct Token {
    pub kind: TokenKind,
    pub lexeme: String,
    pub line: usize,
    pub col: usize,
}

#[derive(Debug, Clone)]
pub struct Lexer {
    /// Shared, never mutated after construction. This was a `Vec<u8>`, so every
    /// `Parser::save_state` -- which clones the lexer -- copied the ENTIRE
    /// source. Checkpoints were rare enough for that not to show until W568
    /// added one per bracketed expression, at which point parsing the corpus's
    /// 23-million-line benchmark specs went quadratic and timed out. Sharing
    /// the buffer makes a checkpoint a refcount bump.
    source: std::rc::Rc<[u8]>,
    pos: usize,
    line: usize,
    col: usize,
    /// Characters the lexer did not recognise and DISCARDED, with the line each
    /// was on. Recording them changes nothing about lexing; it makes the silent
    /// drop measurable, which W581 needs before deciding whether the right
    /// change is to reject them or to lex them.
    pub dropped: Vec<(char, usize)>,
}

impl Lexer {
    pub fn new(source: &str) -> Self {
        Self {
            source: source.as_bytes().into(),
            pos: 0,
            line: 1,
            col: 1,
            dropped: Vec::new(),
        }
    }

    fn peek(&self) -> u8 {
        if self.pos < self.source.len() {
            self.source[self.pos]
        } else {
            0
        }
    }

    fn peek_offset(&self, offset: usize) -> u8 {
        let new_pos = self.pos + offset;
        if new_pos < self.source.len() {
            self.source[new_pos]
        } else {
            0
        }
    }

    fn advance(&mut self) {
        let ch = self.peek();
        if ch == b'\n' {
            self.line += 1;
            self.col = 1;
        } else {
            self.col += 1;
        }
        self.pos += 1;
    }

    fn skip_whitespace_and_comments(&mut self) {
        loop {
            // Skip whitespace
            while self.pos < self.source.len() {
                let ch = self.peek();
                if ch != b' ' && ch != b'\t' && ch != b'\n' && ch != b'\r' {
                    break;
                }
                self.advance();
            }

            // [BUG 2 FIX] Skip // line comments
            if self.pos + 1 < self.source.len()
                && self.source[self.pos] == b'/'
                && self.source[self.pos + 1] == b'/'
            {
                while self.pos < self.source.len() && self.peek() != b'\n' {
                    self.advance();
                }
                continue; // loop back to skip more whitespace/comments
            }

            // W661: `#` starts a line comment.
            //
            // Specs annotate struct fields with their source-language defaults:
            //
            //     category : ?CommandCategory  # default: null,
            //     search   : ?[]const U8       # default: null,
            //     verbose  : Bool              # default: false,
            //
            // `#` was not a comment, so the field parser read `# default: null,`
            // as a FIELD, and every struct with these annotations grew a phantom
            // `default` member -- one per annotated field, all with the same
            // name. The symptom is three identical declarations in the emitted
            // Verilog and `'helpoptions_default' has already been declared`,
            // which reads as a missing dedup in the emitter. It is not: the
            // emitter is faithfully lowering fields that should never have been
            // parsed.
            //
            // `#` is not a pragma marker here -- `pragma` is a keyword
            // (TokenKind::KwPragma) -- and it carries no other meaning in the
            // language. Measured over the spec tree: 42 occurrences in struct
            // field positions across 8 specs, plus a file with a `.t27`
            // extension whose contents are Markdown headings. Both become
            // comments, which is what they always were in intent.
            //
            // This runs AFTER string and char literals are lexed, so a `#`
            // inside `"# nextpnr-compatible XDC"` or `'#'` is untouched.
            if self.pos < self.source.len() && self.source[self.pos] == b'#' {
                while self.pos < self.source.len() && self.peek() != b'\n' {
                    self.advance();
                }
                continue;
            }

            // Skip /* ... */ block comments
            if self.pos + 1 < self.source.len()
                && self.source[self.pos] == b'/'
                && self.source[self.pos + 1] == b'*'
            {
                self.advance(); // consume /
                self.advance(); // consume *
                let mut depth = 1;
                while depth > 0 && self.pos < self.source.len() {
                    if self.pos + 1 < self.source.len()
                        && self.source[self.pos] == b'*'
                        && self.source[self.pos + 1] == b'/'
                    {
                        self.advance();
                        self.advance();
                        depth -= 1;
                    } else if self.pos + 1 < self.source.len()
                        && self.source[self.pos] == b'/'
                        && self.source[self.pos + 1] == b'*'
                    {
                        self.advance();
                        self.advance();
                        depth += 1;
                    } else {
                        self.advance();
                    }
                }
                continue;
            }

            // Skip ; line comments (old t27 comment style: ; at column 1 followed by space)
            if self.pos < self.source.len() && self.peek() == b';' && self.col == 1 {
                let next = self.peek_offset(1);
                if next == b' ' || next == b'\t' {
                    while self.pos < self.source.len() && self.peek() != b'\n' {
                        self.advance();
                    }
                    continue;
                }
            }

            break;
        }
    }

    fn check_keyword(&self, ident: &str) -> TokenKind {
        match ident {
            "pub" => TokenKind::KwPub,
            "const" => TokenKind::KwConst,
            // #1401: `let` is an accepted synonym for `const` (immutable local
            // binding). Downstream specs (e.g. tri-net) write `let x = ...;`
            // in function bodies; without this alias the lexer emitted a bare
            // Ident, `parse_body_stmt` fell through to expression parsing, and
            // the entire binding was dropped from generated Rust/C/Zig
            // (undeclared-identifier E0425, 2609 sites / 93% of Rust errors).
            // `const` semantics (extra_mutable=false) match the `let` the Rust
            // emitter already produces; `let mut` has no spec-level source form
            // yet (use `var` for a mutable local), so this maps to immutable.
            "let" => TokenKind::KwConst,
            "fn" => TokenKind::KwFn,
            "enum" => TokenKind::KwEnum,
            "struct" => TokenKind::KwStruct,
            "test" => TokenKind::KwTest,
            "invariant" => TokenKind::KwInvariant,
            "bench" => TokenKind::KwBench,
            "module" => TokenKind::KwModule,
            "if" => TokenKind::KwIf,
            "else" => TokenKind::KwElse,
            "for" => TokenKind::KwFor,
            "while" => TokenKind::KwWhile,
            "or" => TokenKind::KwOr,
            "and" => TokenKind::KwAnd,
            "try" => TokenKind::KwTry,
            "switch" => TokenKind::KwSwitch,
            "return" => TokenKind::KwReturn,
            "var" => TokenKind::KwVar,
            "using" => TokenKind::KwUsing,
            "use" => TokenKind::KwUse,
            "pragma" => TokenKind::KwPragma,
            "void" => TokenKind::KwVoid,
            "true" => TokenKind::KwTrue,
            "false" => TokenKind::KwFalse,
            "break" => TokenKind::KwBreak,
            "continue" => TokenKind::KwContinue,
            "in" => TokenKind::KwIn,
            _ => TokenKind::Ident,
        }
    }

    /// The source this lexer is reading. Shared, so this is a refcount bump.
    pub(crate) fn source_bytes(&self) -> std::rc::Rc<[u8]> {
        std::rc::Rc::clone(&self.source)
    }

    pub fn next_token(&mut self) -> Token {
        // [BUG 2 + BUG 9 FIX] Combined whitespace and comment skipping
        self.skip_whitespace_and_comments();

        if self.pos >= self.source.len() {
            return Token {
                kind: TokenKind::Eof,
                lexeme: String::new(),
                line: self.line,
                col: self.col,
            };
        }

        let ch = self.peek();
        let start_line = self.line;
        let start_col = self.col;

        // [BUG 9 FIX] Semicolons are ALWAYS statement terminators — no comment logic
        if ch == b';' {
            self.advance();
            return Token {
                kind: TokenKind::Semicolon,
                lexeme: String::from(";"),
                line: start_line,
                col: start_col,
            };
        }

        // [BUG 3 FIX] String literal "..."
        if ch == b'"' {
            self.advance(); // consume opening "
            let mut s = String::new();
            while self.pos < self.source.len() && self.peek() != b'"' {
                if self.peek() == b'\\' {
                    self.advance(); // skip backslash
                    if self.pos < self.source.len() {
                        let escaped = self.peek();
                        match escaped {
                            b'n' => s.push('\n'),
                            b't' => s.push('\t'),
                            b'\\' => s.push('\\'),
                            b'"' => s.push('"'),
                            _ => {
                                s.push('\\');
                                s.push(escaped as char);
                            }
                        }
                        self.advance();
                    }
                } else {
                    s.push(self.peek() as char);
                    self.advance();
                }
            }
            if self.pos < self.source.len() {
                self.advance(); // consume closing "
            } else {
                // W577: no closing quote. The lexer used to return a String
                // token holding the REST OF THE FILE, so the parser saw one
                // giant literal, reached Eof and reported success -- a
                // truncation the completeness check cannot even see, because
                // the input really was consumed. Mark it so the parser can
                // refuse.
                return Token {
                    kind: TokenKind::UnterminatedString,
                    lexeme: s,
                    line: start_line,
                    col: start_col,
                };
            }
            return Token {
                kind: TokenKind::String,
                lexeme: s,
                line: start_line,
                col: start_col,
            };
        }

        // Single-quoted literal: a character 'c' / '\n', OR a string 'abc'.
        //
        // W604: this used to consume EXACTLY ONE character after the opening
        // quote and then look for a closing one. Given `'{"model": "x"}'` it
        // produced CharLiteral("{") and left the rest -- including the closing
        // brace -- as loose tokens, which ended the enclosing module. That cost
        // 77% of `specs/igla/coder/weights.t27` (1,622 of 2,109 lines) and the
        // corpus contains **120 multi-character single-quoted literals** in 10
        // specs, 85 of them in `dataset.t27` alone. Same class as W575's `1e6`:
        // a mis-lexed VALUE, no error, no diagnostic.
        //
        // Both forms are real -- 69 genuine char literals across 19 specs -- so
        // the fix is to scan to the closing quote and decide by CONTENT, not to
        // pick one meaning. An unterminated quote is an ERROR rather than
        // silent garbage, which is W577's rule applied one layer down.
        if ch == b'\'' {
            self.advance(); // consume opening '
            let mut val = String::new();
            let mut closed = false;
            while self.pos < self.source.len() {
                let c = self.peek();
                if c == b'\n' {
                    break; // a quote never spans a line; report it unterminated
                }
                if c == b'\\' {
                    val.push('\\');
                    self.advance();
                    if self.pos < self.source.len() {
                        val.push(self.peek() as char);
                        self.advance();
                    }
                    continue;
                }
                if c == b'\'' {
                    self.advance();
                    closed = true;
                    break;
                }
                val.push(c as char);
                self.advance();
            }
            let kind = if !closed {
                TokenKind::UnterminatedString
            } else if val.chars().count() == 1 || (val.starts_with('\\') && val.chars().count() == 2)
            {
                TokenKind::CharLiteral
            } else {
                TokenKind::String
            };
            return Token {
                kind,
                lexeme: val,
                line: start_line,
                col: start_col,
            };
        }

        // Multi-char operators
        if self.pos + 1 < self.source.len() {
            let two = [self.source[self.pos], self.source[self.pos + 1]];

            if two == [b'-', b'>'] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::Arrow,
                    lexeme: String::from("->"),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'=', b'>'] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::FatArrow,
                    lexeme: String::from("=>"),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'*', b'*'] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::Power,
                    lexeme: String::from("**"),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'<', b'='] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::Lte,
                    lexeme: String::from("<="),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'>', b'='] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::Gte,
                    lexeme: String::from(">="),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'=', b'='] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::Eq,
                    lexeme: String::from("=="),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'!', b'='] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::Neq,
                    lexeme: String::from("!="),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'<', b'<'] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::ShiftLeft,
                    lexeme: String::from("<<"),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'>', b'>'] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::ShiftRight,
                    lexeme: String::from(">>"),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'+', b'+'] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::PlusPlus,
                    lexeme: String::from("++"),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'+', b'='] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::PlusEquals,
                    lexeme: String::from("+="),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'-', b'='] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::MinusEquals,
                    lexeme: String::from("-="),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'*', b'='] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::StarEquals,
                    lexeme: String::from("*="),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'/', b'='] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::SlashEquals,
                    lexeme: String::from("/="),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'|', b'='] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::PipeEquals,
                    lexeme: String::from("|="),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'%', b'='] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::PercentEquals,
                    lexeme: String::from("%="),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'&', b'='] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::AmpEquals,
                    lexeme: String::from("&="),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'^', b'='] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::CaretEquals,
                    lexeme: String::from("^="),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'+', b'%'] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::PlusPercent,
                    lexeme: String::from("+%"),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'-', b'%'] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::MinusPercent,
                    lexeme: String::from("-%"),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'*', b'%'] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::StarPercent,
                    lexeme: String::from("*%"),
                    line: start_line,
                    col: start_col,
                };
            }

            if two == [b'.', b'.'] {
                self.advance();
                self.advance();
                return Token {
                    kind: TokenKind::DotDot,
                    lexeme: String::from(".."),
                    line: start_line,
                    col: start_col,
                };
            }
        }

        // Identifier or keyword (including @builtins)
        if ch.is_ascii_alphabetic() || ch == b'_' || ch == b'@' {
            let mut ident = String::new();

            while self.pos < self.source.len() {
                let c = self.peek();
                if c.is_ascii_alphanumeric() || c == b'_' || c == b'@' {
                    ident.push(c as char);
                    self.advance();
                } else {
                    break;
                }
            }

            let kind = self.check_keyword(&ident);
            return Token {
                kind,
                lexeme: ident,
                line: start_line,
                col: start_col,
            };
        }

        // [BUG 6 FIX] Number literal with full hex digit support (a-f, A-F)
        if ch.is_ascii_digit() {
            let mut number = String::new();
            let mut is_hex = false;

            while self.pos < self.source.len() {
                let c = self.peek();
                // Don't consume '.' if it's part of a '..' range operator
                let is_dot_not_range = c == b'.'
                    && (self.pos + 1 >= self.source.len() || self.source[self.pos + 1] != b'.');
                if c.is_ascii_digit()
                    || is_dot_not_range
                    || c == b'x'
                    || c == b'X'
                    || c == b'b'
                    || c == b'B'
                    || c == b'_'
                {
                    if c == b'x' || c == b'X' {
                        is_hex = true;
                    }
                    number.push(c as char);
                    self.advance();
                } else if is_hex && ((b'a'..=b'f').contains(&c) || (b'A'..=b'F').contains(&c)) {
                    number.push(c as char);
                    self.advance();
                } else {
                    break;
                }
            }

            // W575: a decimal EXPONENT. `1e6` lexed as the number `1` followed
            // by the identifier `e6`, and `2.5e-3` as `2.5`, `e`, `-`, `3` --
            // so `f(1e6, 2.5e-3)` parsed as a FOUR-argument call. 486
            // occurrences across 62 specs, found by `t27c check-calls`
            // reporting an arity mismatch that turned out to be a lexer bug.
            //
            // Only consumed when a digit actually follows (after an optional
            // sign), so `0x1e` stays hex and an identifier like `e6` on its own
            // is untouched.
            if !is_hex && self.pos < self.source.len() {
                let c = self.peek();
                if c == b'e' || c == b'E' {
                    let mut ahead = self.pos + 1;
                    let signed = ahead < self.source.len()
                        && (self.source[ahead] == b'+' || self.source[ahead] == b'-');
                    if signed {
                        ahead += 1;
                    }
                    if ahead < self.source.len() && self.source[ahead].is_ascii_digit() {
                        number.push(c as char);
                        self.advance();
                        if signed {
                            number.push(self.peek() as char);
                            self.advance();
                        }
                        while self.pos < self.source.len() && self.peek().is_ascii_digit() {
                            number.push(self.peek() as char);
                            self.advance();
                        }
                    }
                }
            }

            let type_suffixes: &[&[u8]] = &[
                b"u8",
                b"u16",
                b"u32",
                b"u64",
                b"usize",
                b"i8",
                b"i16",
                b"i32",
                b"i64",
                b"isize",
                b"f16",
                b"f32",
                b"f64",
                b"comptime_int",
            ];
            for suffix in type_suffixes.iter() {
                let end = self.pos + suffix.len();
                if end <= self.source.len() && &self.source[self.pos..end] == *suffix {
                    let next = if end < self.source.len() {
                        self.source[end]
                    } else {
                        0u8
                    };
                    if !next.is_ascii_alphanumeric() && next != b'_' {
                        // The suffix was consumed and DISCARDED, so `1u64` and
                        // `1` reached the AST identically and the Zig shift
                        // path re-invented a width from the literal's
                        // magnitude: `(1u64 << mant_bits)` became
                        // `(@as(u32, 1) << ...)`. Kept in the lexeme here and
                        // split back off at the two ExprLiteral sites, so
                        // `value` is unchanged and only `extra_type` is new.
                        number.push_str(std::str::from_utf8(suffix).unwrap_or(""));
                        self.pos = end;
                        self.col += suffix.len();
                    }
                    break;
                }
            }

            return Token {
                kind: TokenKind::Number,
                lexeme: number,
                line: start_line,
                col: start_col,
            };
        }

        // Multi-char tokens.
        //
        // W65 R-CODEGEN-EMIT (issue #937) fix: `self.peek()` returns the
        // byte at `self.pos`, which here still points at the FIRST `&` /
        // `|` (the lookahead character is at `self.pos + 1`). The old
        // condition `ch == b'&' && self.peek() == b'&'` was therefore
        // tautologically true for any single `&` and produced a bogus
        // `&&` token (lexeme "&&") for plain bitwise AND. That made the
        // parser route every `&` into `parse_expr_and` (logical AND with
        // `extra_op = "and"`), and the Verilog/C/Rust backends then
        // emitted `&&` -- a 1-bit logical AND -- where the source wrote
        // a bitwise mask. Same root cause for `||`. Use `peek_offset(1)`
        // for true lookahead.
        if ch == b'&' && self.peek_offset(1) == b'&' {
            self.advance();
            self.advance();
            return Token {
                kind: TokenKind::Amp,
                lexeme: "&&".to_string(),
                line: start_line,
                col: start_col,
            };
        }
        if ch == b'|' && self.peek_offset(1) == b'|' {
            self.advance();
            self.advance();
            return Token {
                kind: TokenKind::Pipe,
                lexeme: "||".to_string(),
                line: start_line,
                col: start_col,
            };
        }

        // Single char tokens
        let kind = match ch {
            b':' => TokenKind::Colon,
            b',' => TokenKind::Comma,
            b'=' => TokenKind::Equals,
            b'(' => TokenKind::LParen,
            b')' => TokenKind::RParen,
            b'{' => TokenKind::LBrace,
            b'}' => TokenKind::RBrace,
            b'[' => TokenKind::LBracket,
            b']' => TokenKind::RBracket,
            b'.' => TokenKind::Dot,
            b'!' => TokenKind::Bang,
            b'+' => TokenKind::Plus,
            b'-' => TokenKind::Minus,
            b'*' => TokenKind::Star,
            b'/' => TokenKind::Slash,
            b'%' => TokenKind::Percent,
            b'&' => TokenKind::Amp,
            b'|' => TokenKind::Pipe,
            b'^' => TokenKind::Caret,
            b'~' => TokenKind::Tilde,
            b'<' => TokenKind::Lt,
            b'>' => TokenKind::Gt,
            b'?' => TokenKind::Question,
            _ => {
                // Unknown character -- skip and recurse. Recorded so the drop
                // can be counted (W581); the behaviour is unchanged.
                self.dropped.push((ch as char, self.line));
                self.advance();
                return self.next_token();
            }
        };

        self.advance();

        Token {
            kind,
            lexeme: String::from_utf8_lossy(&[ch]).to_string(),
            line: start_line,
            col: start_col,
        }
    }

    #[allow(dead_code)]
    pub fn tokenize(&mut self) -> Vec<Token> {
        let mut tokens = Vec::new();
        loop {
            let tok = self.next_token();
            if tok.kind == TokenKind::Eof {
                break;
            }
            tokens.push(tok);
        }
        tokens
    }
}

// ============================================================================
// Parser (recursive descent, minimal)
// ============================================================================

pub struct Parser {
    lexer: Lexer,
    current: Token,
    peek: Token,
    pending_pragma: String,
    /// While parsing a PARENTHESIS-LESS `if`/`while` condition, `Name {` opens
    /// the branch body, not a struct literal. Rust has the same ambiguity and
    /// resolves it the same way (W578).
    no_struct_literal: u32,
    /// Suppress `..` as a binary operator while a RANGE BOUND is being parsed.
    ///
    /// `parse_for_range` parses its start bound with the full expression
    /// grammar, and that grammar carries `..` in the comparison chain (for
    /// slices). So `for i in 0..8` came back as ONE ExprBinary, the
    /// `current.kind != DotDot` test below it never fired, and every range
    /// loop was built as the COLLECTION form. `StmtForRange` was unreachable:
    /// 0 nodes across 746 tracked specs against 383 `StmtFor`, and with it
    /// `gen_c_for_range_stmt` and `gen_verilog_for_range_stmt` were dead code.
    no_range: u32,
    /// W633: tokens DISCARDED by top-level drop-recovery. The parser resyncs
    /// past an unrecognised declaration and reaches EOF, so
    /// `parse_ast_strict`'s "did we reach EOF?" check reports "consumed all"
    /// -- for input that was consumed AND THROWN AWAY. Counting them is what
    /// makes that population visible. See T42.
    dropped_top_level_tokens: usize,
    // W883 prototype: nested `fn` declarations, hoisted to module level.
    hoisted_fns: Vec<Node>,
    // W898 (0005): inside a braceless-clause VALUE, an `and` that opens the next
    // clause must terminate the expression instead of becoming a logical AND.
    in_bdd_clause_value: bool,
    last_line: usize,
    bdd_last_was_assertion: bool,
    bdd_role_preset: bool,
    bdd_first_col_preset: Option<usize>,
    /// W634: WHERE they were dropped -- `(line, lexeme)` per token. Counting
    /// told us 55,563 tokens vanish; only reading them can say whether any of
    /// it is content a theorem depends on. See T43.
    dropped_spans: Vec<(u32, String)>,
    /// W699: WHICH recovery threw each token away, parallel to `dropped_spans`.
    ///
    /// The head token of a dropped run says what the parser stopped ON. It does
    /// not say which of the four recovery channels did the dropping, and the two
    /// are different questions: `given` is the fourth-largest head in the corpus
    /// and only 43 of its 2 453 tokens came from the fn arm that names it.
    dropped_channels: Vec<&'static str>,
    /// Set by `restore_bdd_fallback` for the duration of its resync, so the
    /// tokens a WHOLE-BLOCK fallback discards are distinguishable from an
    /// ordinary top-level resync. Both call the same function.
    in_bdd_fallback: bool,
    /// W699 rung 9: WHY the last whole-block fallback fired, and on WHICH clause.
    ///
    /// The channel says a braceless block gave up -- 93% of everything the
    /// parser discards. It does not say which of the eight `restore_bdd_fallback`
    /// call sites fired, and those are eight different defects sharing one name.
    /// Set immediately before each call; read inside it.
    bdd_fail_why: &'static str,
    bdd_fail_clause: String,
    /// One record per whole-block fallback: `(line, why, clause)`. Far smaller
    /// than the token log -- 1 484 events against 30 408 tokens -- so no cap.
    bdd_fallbacks: Vec<(u32, &'static str, String)>,
}

#[derive(Clone)]
struct ParserCheckpoint {
    lexer: Lexer,
    current: Token,
    peek: Token,
    pending_pragma: String,
}

/// Identifiers a nested fn uses that are neither its parameters nor its own
/// locals. Builtin scalar type names are excluded: `@as(f32, ..)` carries `f32`
/// as a bare identifier argument.
fn free_idents_of(decl: &Node) -> Vec<String> {
    const BUILTIN_TYPES: &[&str] = &[
        "f32", "f64", "u8", "u16", "u32", "u64", "usize", "i8", "i16", "i32",
        "i64", "isize", "bool", "void", "true", "false",
    ];
    let mut bound: Vec<String> = decl.params.iter().map(|p| p.0.clone()).collect();
    let mut free: Vec<String> = Vec::new();
    fn walk(n: &Node, bound: &mut Vec<String>, free: &mut Vec<String>) {
        if n.kind == NodeKind::StmtLocal && !n.name.is_empty() {
            bound.push(n.name.clone());
        }
        if n.kind == NodeKind::ExprIdentifier
            && !n.name.is_empty()
            && !n.name.starts_with('@')
            && !bound.iter().any(|b| b == &n.name)
            && !free.iter().any(|f| f == &n.name)
        {
            free.push(n.name.clone());
        }
        for c in &n.children {
            walk(c, bound, free);
        }
    }
    for c in &decl.children {
        walk(c, &mut bound, &mut free);
    }
    free.retain(|f| !BUILTIN_TYPES.contains(&f.as_str()));
    free
}

impl Parser {
    pub fn new(mut lexer: Lexer) -> Self {
        let first = lexer.next_token();
        let second = lexer.next_token();
        Self {
            lexer,
            current: first,
            peek: second,
            pending_pragma: String::new(),
            no_struct_literal: 0,
            no_range: 0,
            dropped_top_level_tokens: 0,
            hoisted_fns: Vec::new(),
            in_bdd_clause_value: false,
            last_line: 0,
            bdd_last_was_assertion: false,
            bdd_role_preset: false,
            bdd_first_col_preset: None,
            dropped_spans: Vec::new(),
            dropped_channels: Vec::new(),
            in_bdd_fallback: false,
            bdd_fail_why: "unset",
            bdd_fail_clause: String::new(),
            bdd_fallbacks: Vec::new(),
        }
    }

    /// Save the current parser state so it can be restored later. Used for
    /// lookahead that needs to inspect more than one token ahead.
    /// Is every line strictly between `from` and `to` a comment?
    ///
    /// The braceless-block boundary asks whether a statement is ADJACENT to the
    /// previous one, and asked it as `line <= last_line + 1`. A comment line
    /// therefore read as a gap and the whole body went to the top-level
    /// discard, silently. It reproduces in nine lines:
    ///
    ///     invariant has_comment
    ///         // a comment between the header and the body
    ///         const a = f(1);          <- discarded
    ///
    /// The rule this expresses is about a BLANK line -- the comment beside it
    /// says "a blank line before the const meant module scope to every reader"
    /// -- and a comment is not blank. A reader sees it as part of the block.
    fn only_comment_lines_between(&self, from: usize, to: usize) -> bool {
        if to <= from + 1 {
            return true;
        }
        let src = self.lexer.source_bytes();
        let text = String::from_utf8_lossy(&src);
        let lines: Vec<&str> = text.lines().collect();
        for i in from..(to - 1) {
            match lines.get(i).map(|l| l.trim()) {
                Some(l) if !l.is_empty() && l.starts_with("//") => {}
                // A blank line, or a line this cannot read, keeps the old
                // boundary: not adjacent.
                _ => return false,
            }
        }
        true
    }

    fn save_state(&self) -> ParserCheckpoint {
        ParserCheckpoint {
            lexer: self.lexer.clone(),
            current: self.current.clone(),
            peek: self.peek.clone(),
            pending_pragma: self.pending_pragma.clone(),
        }
    }

    fn restore_state(&mut self, checkpoint: ParserCheckpoint) {
        self.lexer = checkpoint.lexer;
        self.current = checkpoint.current;
        self.peek = checkpoint.peek;
        self.pending_pragma = checkpoint.pending_pragma;
    }

    fn advance(&mut self) {
        self.last_line = self.current.line;
        self.current = self.peek.clone();
        self.peek = self.lexer.next_token();
    }

    fn check(&self, kind: TokenKind) -> bool {
        self.current.kind == kind
    }

    #[allow(dead_code)]
    fn check_peek(&self, kind: TokenKind) -> bool {
        self.peek.kind == kind
    }

    fn expect(&mut self, kind: TokenKind) -> Result<(), String> {
        if !self.check(kind) {
            return Err(format!(
                "Expected {:?}, got {:?} ('{}') at line {}:{}",
                kind, self.current.kind, self.current.lexeme, self.current.line, self.current.col
            ));
        }
        self.advance();
        Ok(())
    }

    // [BUG 7 FIX] Brace-skip: count { } nesting to skip over body contents
    fn skip_brace_body(&mut self) -> Result<(), String> {
        // current token should be AFTER the opening LBrace was consumed
        let mut depth: i32 = 1;
        while depth > 0 {
            if self.current.kind == TokenKind::Eof {
                return Err("Unexpected EOF inside brace body".to_string());
            }
            if self.current.kind == TokenKind::LBrace {
                depth += 1;
            } else if self.current.kind == TokenKind::RBrace {
                depth -= 1;
                if depth == 0 {
                    // Don't advance past the closing brace — caller expects current == RBrace
                    return Ok(());
                }
            }
            // W646: this body is being SKIPPED, so every token in it is
            // discarded. T42's counter lived only in `skip_to_next_top_level`,
            // making 55,563 a lower bound over one of four discard channels.
            // See T56.
            // W899: the counter incremented here but the SPAN was never
            // recorded, so `parse-complete --show` printed "nothing discarded"
            // for a file the corpus mode charged 2,438 tokens. Both accounts
            // must see every channel.
            self.dropped_top_level_tokens += 1;
            if self.dropped_spans.len() < 20000 {
                self.dropped_spans
                    .push((self.current.line as u32, self.current.lexeme.clone()));
                // W699 rung 8: a braced statement INSIDE a braceless block that
                // fell back is not an independent finding -- it is the same
                // event, reached through a second function. Measured before
                // splitting them: 4 514 of 4 602 `brace-body` tokens sit in
                // specs that also have a fallback, and reading the channel as a
                // defect class of its own sent me looking for work that is
                // already counted once.
                self.dropped_channels.push(if self.in_bdd_fallback {
                    "brace-body/in-fallback"
                } else {
                    "brace-body"
                });
            }
            self.advance();
        }
        Ok(())
    }

    // Skip everything to the next semicolon, handling nested braces, brackets, and parens
    fn skip_to_semicolon(&mut self) -> Result<(), String> {
        let mut bracket_depth: i32 = 0;
        let mut paren_depth: i32 = 0;
        while self.current.kind != TokenKind::Eof {
            // Only treat ; as terminator when not inside brackets or parens
            if self.current.kind == TokenKind::Semicolon && bracket_depth == 0 && paren_depth == 0 {
                self.advance();
                return Ok(());
            }
            // W902 (0008): a LINE-LEADING const/var at depth 0 is the next
            // declaration, not expression tail. is_top_level_start excludes
            // const/var on purpose (they appear inside keyword blocks), so a
            // semicolon-less `const A = 10` followed by `const B = 5` sent this
            // loop through B, the next fn, and everything to EOF -- the corpus's
            // single largest discard (2,438 tokens) traced here. Same-line
            // `[]const u8` shapes stay intact (W568): the line test spares them.
            // W903 panel: the stop's first version fired on var, on INDENTED
            // const inside keyword-test bodies (hoisting a test-local binding
            // to module scope), and on the wrapped tail of a pointer type
            // (`const P = *` newline `const u8;` minted a module const named
            // u8). v2 narrows it to what the corpus shape actually is: a
            // COLUMN-1 `const` opening a real declaration head
            // (`const Ident :` or `const Ident =`). Everything else keeps the
            // old swallow -- now COUNTED, which is the honesty that matters.
            if bracket_depth == 0
                && paren_depth == 0
                && self.current.line > self.last_line
            {
                // W903 v3: a line-leading TOP-LEVEL opener (test/fn/...) ends
                // the skip -- without this, the skip after a bad const ran
                // THROUGH `test t` into its body and the recovery minted
                // module consts from test-local bindings. And a line-leading
                // const/var counts only with a DECLARATION HEAD after it
                // (`Ident :` / `Ident =`): the wrapped pointer type
                // `const P = *` newline `const u8;` has no head and stays
                // swallowed instead of minting a module const named u8.
                if self.is_top_level_start() {
                    return Ok(());
                }
                if self.current.kind == TokenKind::KwConst
                    || self.current.kind == TokenKind::KwVar
                {
                    let look = self.save_state();
                    self.advance();
                    let head = self.current.kind == TokenKind::Ident && {
                        self.advance();
                        matches!(self.current.kind, TokenKind::Colon | TokenKind::Equals)
                    };
                    self.restore_state(look);
                    if head {
                        return Ok(());
                    }
                }
            }
            // W902: this loop was the FOURTH discard channel T56 counted --
            // and the only one still invisible to both accounts. Record.
            self.dropped_top_level_tokens += 1;
            if self.dropped_spans.len() < 20000 {
                self.dropped_spans
                    .push((self.current.line as u32, self.current.lexeme.clone()));
                self.dropped_channels.push("clause-junk");
            }
            if self.current.kind == TokenKind::LBrace {
                self.advance();
                self.skip_brace_body()?;
                if self.current.kind == TokenKind::RBrace {
                    self.advance();
                }
            } else if self.current.kind == TokenKind::LBracket {
                bracket_depth += 1;
                self.advance();
            } else if self.current.kind == TokenKind::RBracket {
                bracket_depth -= 1;
                self.advance();
            } else if self.current.kind == TokenKind::LParen {
                paren_depth += 1;
                self.advance();
            } else if self.current.kind == TokenKind::RParen {
                paren_depth -= 1;
                self.advance();
            } else {
                self.advance();
            }
        }
        Ok(())
    }

    // Check if the current token starts a new top-level declaration.
    // This is conservative: we only include keywords that unambiguously start
    // a new top-level form, excluding const/var which can appear inside
    // keyword-style test/invariant/bench blocks.
    fn is_top_level_start(&self) -> bool {
        matches!(
            self.current.kind,
            TokenKind::KwPub
                | TokenKind::KwFn
                | TokenKind::KwEnum
                | TokenKind::KwStruct
                | TokenKind::KwTest
                | TokenKind::KwInvariant
                | TokenKind::KwBench
                | TokenKind::KwUse
                | TokenKind::KwUsing
                | TokenKind::KwModule
                | TokenKind::RBrace
                | TokenKind::Eof
        )
    }

    // Skip tokens until we reach a top-level keyword (for keyword-style test/invariant/bench)
    // Handles nested braces, brackets, and parens so we don't stop inside nested groups
    #[allow(dead_code)]
    fn skip_to_next_top_level(&mut self) {
        let mut paren_depth: i32 = 0;
        let mut bracket_depth: i32 = 0;
        loop {
            if self.current.kind == TokenKind::Eof {
                break;
            }
            // Handle brace groups by using skip_brace_body
            if self.current.kind == TokenKind::LBrace {
                self.advance();
                let _ = self.skip_brace_body();
                if self.current.kind == TokenKind::RBrace {
                    self.advance();
                }
                continue;
            }
            if self.current.kind == TokenKind::LParen {
                paren_depth += 1;
                self.advance();
                continue;
            }
            if self.current.kind == TokenKind::RParen {
                paren_depth -= 1;
                self.advance();
                continue;
            }
            if self.current.kind == TokenKind::LBracket {
                bracket_depth += 1;
                self.advance();
                continue;
            }
            if self.current.kind == TokenKind::RBracket {
                bracket_depth -= 1;
                self.advance();
                continue;
            }
            // Only check for top-level start when not inside nested groups
            if paren_depth == 0 && bracket_depth == 0 && self.is_top_level_start() {
                break;
            }
            self.dropped_top_level_tokens += 1;
            if self.dropped_spans.len() < 20000 {
                self.dropped_spans
                    .push((self.current.line as u32, self.current.lexeme.clone()));
                // W699: `restore_bdd_fallback` resyncs through this same
                // function, and "a whole braceless block fell back" is a
                // different finding from "a top-level item was skipped".
                self.dropped_channels.push(if self.in_bdd_fallback {
                    "bdd-block-fallback"
                } else {
                    "top-level-resync"
                });
            }
            self.advance();
        }
    }

    /// W633: how many tokens this parse threw away during top-level recovery.
    pub(crate) fn dropped_top_level_tokens(&self) -> usize {
        self.dropped_top_level_tokens
    }

    /// Refuse an unterminated string wherever it appears. The token carries the
    /// rest of the file as its lexeme, so any construct that accepts it would
    /// silently absorb everything after the opening quote.
    fn reject_unterminated_string(&self) -> Result<(), String> {
        if self.current.kind == TokenKind::UnterminatedString {
            return Err(format!(
                "unterminated string literal opened at line {}:{}",
                self.current.line, self.current.col
            ));
        }
        Ok(())
    }

    pub fn parse(&mut self) -> Result<Node, String> {
        // W577: an unterminated string literal carries the REST OF THE FILE as
        // its lexeme. Every construct that accepts a string then absorbs
        // everything after the opening quote, reaches Eof, and reports success
        // -- a truncation the completeness check cannot see, because the input
        // really was consumed. There are too many places a string can be
        // accepted to guard each one, so the whole token stream is checked once
        // up front. The lexer shares its source buffer, so this clone is a
        // refcount bump (W569).
        for t in [&self.current, &self.peek] {
            if t.kind == TokenKind::UnterminatedString {
                return Err(format!(
                    "unterminated string literal opened at line {}:{}",
                    t.line, t.col
                ));
            }
        }
        {
            let mut scan = self.lexer.clone();
            loop {
                let t = scan.next_token();
                match t.kind {
                    TokenKind::Eof => break,
                    TokenKind::UnterminatedString => {
                        return Err(format!(
                            "unterminated string literal opened at line {}:{}",
                            t.line, t.col
                        ));
                    }
                    _ => {}
                }
            }
        }

        let mut module = Node::new(NodeKind::Module);

        // [BUG 4 FIX] Parse optional module declaration
        //
        // `pub module test;` -- visibility on a module declaration. `pub` is a
        // modifier the declaration parser already reads for fn/struct/const,
        // and a module is the one declaration where it was not accepted, so
        // the file stopped on the `module` keyword itself. A module has no
        // visibility to record here, so the modifier is consumed and dropped;
        // when modules gain visibility this is where it goes.
        if self.current.kind == TokenKind::KwPub && self.peek.kind == TokenKind::KwModule {
            self.advance(); // consume 'pub'
        }
        if self.current.kind == TokenKind::KwModule {
            self.advance(); // consume 'module'
                            // Module name can contain hyphens: e.g. "tritype-base"
            let mut mod_name = String::new();
            if self.current.kind == TokenKind::Ident {
                // A module name is one or more `::`-separated SEGMENTS, each of
                // which may itself be hyphenated: `module tritype-base;`,
                // `module github::issues { }`, `module a::b::c;`.
                //
                // The path form was read up to its first segment and no
                // further, so `module github::auth {` left the parser looking
                // at a colon at module level. Nine specs on master declare a
                // path-qualified module and none of them parsed. The name is a
                // NAME -- the repair is to read all of it, not to give `::` a
                // meaning.
                //
                // BOTH colons are required before either is consumed. A single
                // `:` after a module name is not a path, and swallowing it
                // would turn a real error into a stranger one further down.
                loop {
                    mod_name.push_str(&self.current.lexeme);
                    self.advance();
                    // Consume hyphenated parts: - ident - ident ...
                    while self.current.kind == TokenKind::Minus {
                        mod_name.push('-');
                        self.advance(); // consume -
                        if self.current.kind == TokenKind::Ident
                            || self.current.kind == TokenKind::Number
                        {
                            mod_name.push_str(&self.current.lexeme);
                            self.advance();
                        }
                    }
                    if self.current.kind != TokenKind::Colon
                        || self.peek.kind != TokenKind::Colon
                    {
                        break;
                    }
                    self.advance(); // consume first :
                    self.advance(); // consume second :
                    mod_name.push_str("::");
                    if self.current.kind != TokenKind::Ident {
                        // `module a::` with nothing after it. The name keeps the
                        // separator so the shape is visible rather than tidied
                        // away, and the caller meets the real token next.
                        break;
                    }
                }
            }
            module.name = mod_name;
            if self.current.kind == TokenKind::Semicolon {
                self.advance(); // consume ;
            } else if self.current.kind == TokenKind::LBrace {
                // Brace-style module: module Name { ... }
                self.advance(); // consume {
                self.parse_module_body(&mut module)?;
                self.expect(TokenKind::RBrace)?;
                // W577: this used to `return` here, so anything AFTER the
                // closing brace was discarded without a word.
                // `specs/nn/attention.t27` closes `module SacredAttention {` at
                // line 639 and opens `module AttentionQKGainAblation;` at 640,
                // and the parser reported success having read 70 of the file's
                // declarations and none of the remaining 282 lines. Fall
                // through instead: the trailing declarations, including any
                // further module headers, are read by the body loop below.
                self.parse_module_body(&mut module)?;
                if self.current.kind == TokenKind::Ident
                    && self.current.lexeme == "endmodule"
                {
                    self.advance();
                }
                return Ok(module);
            }
        }

        self.parse_module_body(&mut module)?;

        // W458: semicolon-style modules close with `endmodule`; consume it so
        // it is not parsed as a stray top-level expression statement.
        // W577 said a stray `}` here must not look like a clean EOF -- 29 specs
        // were silently truncated that way for years. W914 keeps that promise
        // with ACCOUNTING instead of a hard error: master's brace-closing spec
        // fixes (#2186) leave balancing `}` tokens that our clause lowerings
        // meet at module level in flat files; each is recorded as a dropped
        // token and the body loop CONTINUES, so nothing after it is lost and
        // nothing is silent.
        loop {
            if self.current.kind == TokenKind::Ident && self.current.lexeme == "endmodule" {
                self.advance();
                continue;
            }
            if self.current.kind == TokenKind::RBrace {
                self.dropped_top_level_tokens += 1;
                if self.dropped_spans.len() < 20000 {
                    self.dropped_spans
                        .push((self.current.line as u32, self.current.lexeme.clone()));
                    self.dropped_channels.push("stray-brace");
                }
                self.advance();
                self.parse_module_body(&mut module)?;
                continue;
            }
            break;
        }

        Ok(module)
    }


    fn parse_module_body(&mut self, module: &mut Node) -> Result<(), String> {
        self.reject_unterminated_string()?;
        while self.current.kind != TokenKind::Eof
            && self.current.kind != TokenKind::RBrace
            && !(self.current.kind == TokenKind::Ident
                && self.current.lexeme == "endmodule")
        {
            self.reject_unterminated_string()?;

            // W579: a Rust-style ATTRIBUTE, `#[test]` / `#[derive(...)]`.
            // Three specs carry Rust source verbatim; the attribute parsed as
            // an expression statement and the `fn` after it was then
            // "unexpected token after expression statement: KwFn" -- 825
            // assertion clauses. Skipped bracket-balanced, so a multi-line
            // attribute cannot run away.
            // The lexer drops `#` as an unknown character, so the attribute
            // arrives as a bare bracket group -- which is meaningless at module
            // level and can only be this.
            if self.current.kind == TokenKind::LBracket {
                let mut depth = 0i32;
                loop {
                    match self.current.kind {
                        TokenKind::LBracket => depth += 1,
                        TokenKind::RBracket => depth -= 1,
                        TokenKind::Eof => break,
                        _ => {}
                    }
                    self.advance();
                    if depth == 0 {
                        break;
                    }
                }
                continue;
            }

            // W580: `spec Name { ... }` -- the form SOUL.md documents in
            // section 2.3 and 8 specs use, worth 245 assertion clauses. It was
            // never implemented: `spec` lexes as a plain identifier, so the
            // header parsed as an expression statement and the `{` after it
            // was "unexpected token after expression statement". Treat it as a
            // module body, which is what the document describes.
            if self.current.kind == TokenKind::Ident
                && self.current.lexeme == "spec"
                && self.peek.kind == TokenKind::Ident
            {
                let checkpoint = self.save_state();
                self.advance(); // consume 'spec'
                self.advance(); // consume the name
                if self.current.kind == TokenKind::LBrace {
                    self.advance(); // consume {
                    self.parse_module_body(module)?;
                    if self.current.kind == TokenKind::RBrace {
                        self.advance();
                    }
                    continue;
                }
                self.restore_state(checkpoint);
            }

            // W577: a file may declare SEVERAL modules.
            // `specs/nn/attention.t27` appends
            // `module AttentionQKGainAblation;` at line 640 of 922 -- the
            // parser stopped there and discarded 282 lines while reporting
            // success. Consume the extra header and keep reading; the backends
            // emit one file per spec regardless, so the declarations merge.
            if self.current.kind == TokenKind::KwModule {
                self.advance(); // consume 'module'
                while matches!(
                    self.current.kind,
                    TokenKind::Ident | TokenKind::Minus | TokenKind::Number
                ) {
                    self.advance(); // the (possibly hyphenated) name
                }
                if self.current.kind == TokenKind::Semicolon
                    || self.current.kind == TokenKind::LBrace
                {
                    self.advance();
                }
                continue;
            }

            // Parse use/using statements into UseDecl nodes
            if self.current.kind == TokenKind::KwUse || self.current.kind == TokenKind::KwUsing {
                self.advance(); // consume 'use'/'using'
                                // Collect the full path: e.g. "base::types" or just "datalog_solve"
                let mut full_path = String::new();
                let mut alias_name = String::new();
                if self.current.kind == TokenKind::Ident {
                    let first_ident = self.read_hyphenated_ident();
                    full_path.push_str(&first_ident);

                    // Check for aliased import: using name: @import("path");
                    if self.current.kind == TokenKind::Colon && self.peek.kind != TokenKind::Colon {
                        alias_name = first_ident.clone();
                        self.advance(); // consume :
                                        // Skip @import("path") or any expression until ;
                                        // The value after : can be @import("...") or any expression
                        if self.current.kind == TokenKind::Ident {
                            // Could be @import(...) or a plain identifier
                            self.advance(); // consume @import or ident
                            if self.current.kind == TokenKind::LParen {
                                // Consume (...) call
                                self.advance(); // consume (
                                let mut paren_depth = 1;
                                while paren_depth > 0 && self.current.kind != TokenKind::Eof {
                                    if self.current.kind == TokenKind::LParen {
                                        paren_depth += 1;
                                    }
                                    if self.current.kind == TokenKind::RParen {
                                        paren_depth -= 1;
                                        if paren_depth == 0 {
                                            break;
                                        }
                                    }
                                    self.advance();
                                }
                                if self.current.kind == TokenKind::RParen {
                                    self.advance(); // consume )
                                }
                            }
                        }
                        full_path = alias_name.clone();
                    } else {
                        // Parse :: separated segments
                        loop {
                            if self.current.kind == TokenKind::Colon {
                                self.advance();
                                if self.current.kind == TokenKind::Colon {
                                    self.advance();
                                }
                                full_path.push_str("::");
                            } else {
                                break;
                            }
                            if self.current.kind == TokenKind::Ident {
                                full_path.push_str(&self.read_hyphenated_ident());
                            } else {
                                break;
                            }
                        }
                    }
                }
                // W630: braced import list -- `use a::b::{X, Y, Z};`. The `::`
                // loop above breaks when the token after `::` is not an Ident,
                // so `full_path` ends in `::` and the `{ … };` was left to be
                // parsed as a module-level expression: "Unexpected token in
                // expression: LBrace". It is sugar for N single imports, and
                // that is exactly what it lowers to here -- one UseDecl per
                // name, each with the shared prefix -- so `use_resolve` sees
                // the shape it already understands. See T38.
                if self.current.kind == TokenKind::LBrace && full_path.ends_with("::") {
                    let checkpoint = self.save_state();
                    let prefix = full_path.trim_end_matches("::").to_string();
                    self.advance(); // consume `{`
                    let mut names: Vec<String> = Vec::new();
                    let mut ok = true;
                    loop {
                        if self.current.kind == TokenKind::RBrace {
                            self.advance();
                            break;
                        }
                        if self.current.kind != TokenKind::Ident {
                            ok = false;
                            break;
                        }
                        names.push(self.current.lexeme.clone());
                        self.advance();
                        if self.current.kind == TokenKind::Comma {
                            self.advance();
                        } else if self.current.kind != TokenKind::RBrace {
                            ok = false;
                            break;
                        }
                    }
                    if ok && !names.is_empty() {
                        if self.current.kind == TokenKind::Semicolon {
                            self.advance();
                        }
                        for n in names {
                            let mut node = Node::new(NodeKind::UseDecl);
                            node.value = format!("{}::{}", prefix, n);
                            node.name = n;
                            module.children.push(node);
                        }
                        continue;
                    }
                    // Same safety contract the rest of this parser carries: any
                    // shape this cannot model restores the checkpoint, so a
                    // file that parsed before still parses.
                    self.restore_state(checkpoint);
                }
                if self.current.kind == TokenKind::Semicolon {
                    self.advance();
                }
                // Extract the last segment as the import name
                let import_name = if !alias_name.is_empty() {
                    alias_name
                } else {
                    full_path
                        .rsplit("::")
                        .next()
                        .unwrap_or(&full_path)
                        .to_string()
                };
                let mut use_node = Node::new(NodeKind::UseDecl);
                use_node.name = import_name; // e.g. "types" or alias
                use_node.value = full_path; // e.g. "base::types" or alias
                module.children.push(use_node);
                continue;
            }

            if self.current.kind == TokenKind::KwPragma {
                self.parse_pragma()?;
                continue;
            }

            // W458: allow bare expression / assignment statements at module
            // level so functions with array parameters can be called from the
            // module body (e.g. `read_mem(rom_array, idx);`). These are emitted
            // as Verilog statements inside the module.
            let is_top_level_decl = matches!(
                self.current.kind,
                TokenKind::KwPub
                    | TokenKind::KwConst
                    | TokenKind::KwVar
                    | TokenKind::KwFn
                    | TokenKind::KwEnum
                    | TokenKind::KwStruct
                    | TokenKind::KwTest
                    | TokenKind::KwInvariant
                    | TokenKind::KwBench
            );
            if is_top_level_decl {
                match self.parse_top_level_decl() {
                    Ok(decl) => {
                        module.children.push(decl);
                        // W883: functions hoisted out of the just-parsed item
                        // land beside it at module level.
                        for h in self.hoisted_fns.drain(..) {
                            module.children.push(h);
                        }
                    }
                    Err(e) => {
                        // A malformed declaration is a HARD error: the old
                        // skip-to-next-decl recovery silently DROPPED whole
                        // fns/tests from the module (t27#1940).
                        return Err(e);
                    }
                }
            } else if self.is_top_level_start() {
                // Stray top-level keyword (e.g. `module` inside a module, or an
                // unhandled `use`): the top-level parser produces the error.
                if let Err(e) = self.parse_top_level_decl() {
                    return Err(e);
                }
            } else {
                match self.parse_body_stmt() {
                    Ok(stmt) => {
                        module.children.push(stmt);
                    }
                    Err(e) => {
                        return Err(format!(
                            "parse error at module level near line {}: {}",
                            self.current.line, e
                        ));
                    }
                }
            }
        }

        Ok(())
    }

    /// Parse `pragma name = "value";` at module top level and store it as the
    /// pending pragma to be applied to the next module-level declaration.
    fn parse_pragma(&mut self) -> Result<(), String> {
        self.advance(); // consume 'pragma'

        if self.current.kind != TokenKind::Ident {
            return Err(format!(
                "Expected identifier after 'pragma', got {:?}",
                self.current.kind
            ));
        }
        let pragma_name = self.current.lexeme.clone();
        self.advance();

        if self.current.kind != TokenKind::Equals {
            return Err(format!(
                "Expected '=' after pragma name, got {:?}",
                self.current.kind
            ));
        }
        self.advance();

        if self.current.kind != TokenKind::String {
            return Err(format!(
                "Expected string literal after pragma '=', got {:?}",
                self.current.kind
            ));
        }
        let pragma_value = self.current.lexeme.clone();
        self.advance();

        // W457/W459: ram_style and rom_style are supported; store the full
        // attribute text so codegen can emit it verbatim.
        if pragma_name == "ram_style" {
            self.pending_pragma = format!("ram_style = \"{}\"", pragma_value);
        } else if pragma_name == "rom_style" {
            self.pending_pragma = format!("rom_style = \"{}\"", pragma_value);
        } else {
            return Err(format!(
                "Unknown pragma '{}', expected 'ram_style' or 'rom_style'",
                pragma_name
            ));
        }

        if self.current.kind == TokenKind::Semicolon {
            self.advance();
        }
        Ok(())
    }

    fn parse_top_level_decl(&mut self) -> Result<Node, String> {
        let is_pub = self.current.kind == TokenKind::KwPub;

        if is_pub {
            self.advance(); // consume pub
        }

        match self.current.kind {
            // `const (a, b) = f();` is the tuple-destructure STATEMENT, and the
            // corpus writes it inside test bodies. When a braceless block stops
            // on one, the parser hands it here, where `parse_const_decl`
            // demands a name and dies with "Expected identifier after 'const',
            // got LParen" -- a hard error on a form the statement parser has
            // handled all along. Route it to the parser that knows it.
            TokenKind::KwConst if self.peek.kind == TokenKind::LParen => {
                self.parse_let_destructuring()
            }
            TokenKind::KwConst => self.parse_const_decl(is_pub),
            TokenKind::KwVar => self.parse_var_decl(is_pub),
            TokenKind::KwFn => self.parse_fn_decl(is_pub),
            TokenKind::KwEnum => self.parse_enum_decl(is_pub),
            TokenKind::KwStruct => self.parse_struct_decl(is_pub),
            TokenKind::KwTest => self.parse_test_block(),
            TokenKind::KwInvariant => self.parse_invariant_block(),
            TokenKind::KwBench => self.parse_bench_block(),
            _ => {
                // Skip unknown tokens to be resilient
                let tok = format!("{:?}", self.current.kind);
                let line = self.current.line;
                let col = self.current.col;
                let lexeme = self.current.lexeme.clone();
                self.advance();
                Err(format!(
                    "Unexpected top-level token: {} ('{}') at line {}:{}",
                    tok, lexeme, line, col
                ))
            }
        }
    }

    fn parse_const_decl(&mut self, is_pub: bool) -> Result<Node, String> {
        let mut decl = Node::new(NodeKind::ConstDecl);
        decl.extra_pub = is_pub;
        // W457: apply any pending pragma to this declaration and clear it so it
        // is not accidentally reused for a later declaration.
        if !self.pending_pragma.is_empty() {
            decl.extra_pragma = self.pending_pragma.clone();
            self.pending_pragma.clear();
        }

        self.advance(); // consume 'const'

        // Name
        if self.current.kind == TokenKind::Ident {
            decl.name = self.current.lexeme.clone();
            self.advance();
        } else {
            return Err(format!(
                "Expected identifier after 'const', got {:?}",
                self.current.kind
            ));
        }

        // ADR-008 (#2162): optional generic parameter list, as in
        // `pub const Stack(T) = struct { ... };`. The grammar accepted here is
        // exactly `Ident { "," Ident }` with `struct` on the right-hand side and
        // nothing else, because that is the whole of what the corpus attests:
        // 33 declarations in 28 files, every one of them a struct, parameter
        // lists of one to three bare identifiers. Every rejection below has a
        // negative fixture in tests/fixtures/generic_const/.
        if self.current.kind == TokenKind::LParen {
            self.advance(); // consume (

            if self.current.kind == TokenKind::RParen {
                return Err(format!(
                    "ADR-008: empty generic parameter list in 'const {}()'. An empty \
                     list is ambiguous with a plain type declaration; write \
                     'const {}' without parentheses instead",
                    decl.name, decl.name
                ));
            }

            let mut generic_params: Vec<(String, String)> = Vec::new();
            loop {
                if self.current.kind != TokenKind::Ident {
                    return Err(format!(
                        "ADR-008: generic parameter of 'const {}' must be a bare \
                         identifier, got {:?} ('{}'). Parameters are names being \
                         bound, not types being used",
                        decl.name, self.current.kind, self.current.lexeme
                    ));
                }
                // The second element stays empty on purpose: a generic parameter
                // has no type, it IS a type. No new Node field is introduced.
                generic_params.push((self.current.lexeme.clone(), String::new()));
                self.advance();

                if self.current.kind == TokenKind::Comma {
                    self.advance(); // consume ,
                    if self.current.kind == TokenKind::RParen {
                        return Err(format!(
                            "ADR-008: trailing comma in generic parameter list of \
                             'const {}'. Not attested anywhere in the corpus, so \
                             not accepted",
                            decl.name
                        ));
                    }
                    continue;
                }
                break;
            }

            if self.current.kind != TokenKind::RParen {
                return Err(format!(
                    "ADR-008: expected ')' or ',' after generic parameter of \
                     'const {}', got {:?} ('{}'). Constrained parameters such as \
                     '(T: Ord)' are a language feature, not a parser detail",
                    decl.name, self.current.kind, self.current.lexeme
                ));
            }
            self.advance(); // consume )

            if self.current.kind != TokenKind::Equals {
                return Err(format!(
                    "ADR-008: expected '=' after generic parameter list of 'const \
                     {}', got {:?} ('{}'). A parameterised declaration with no \
                     right-hand side is not a type declaration",
                    decl.name, self.current.kind, self.current.lexeme
                ));
            }
            self.advance(); // consume =

            if self.current.kind != TokenKind::KwStruct {
                return Err(format!(
                    "ADR-008: right-hand side of parameterised 'const {}' must be \
                     'struct', got {:?} ('{}'). All 33 attested declarations are \
                     structs; a parameterised enum or value is a separate decision",
                    decl.name, self.current.kind, self.current.lexeme
                ));
            }
            self.advance(); // consume 'struct'

            // Being parameterised does not change the kind: this is a struct
            // declaration, and a non-empty `params` is what marks it as generic.
            decl.kind = NodeKind::StructDecl;
            decl.params = generic_params;
            self.expect(TokenKind::LBrace)?;
            self.parse_struct_body(&mut decl)?;
            self.expect(TokenKind::RBrace)?;
            // Both ';' and no ';' are accepted, matching the non-parameterised
            // `const Name = struct { ... }` path exactly. No new terminator.
            if self.current.kind == TokenKind::Semicolon {
                self.advance();
            }
            return Ok(decl);
        }

        // Optional type annotation `: Type`
        if self.current.kind == TokenKind::Colon {
            self.advance(); // consume :
            // W528: use the shared type parser so multi-dimensional array
            // annotations like `[2][3]Pt` are preserved correctly.
            decl.extra_type = self.parse_type_annotation();
        }

        // = value
        if self.current.kind == TokenKind::Equals {
            self.advance(); // consume =

            // A TAGGED UNION: `pub const Operand = union(enum) { A: struct {...}, ... };`
            // `union` is not a keyword in this lexer, so it arrives as an
            // identifier and `union(enum)` parsed as a CALL -- whose argument
            // is the keyword `enum`, reported as "Unexpected token in
            // expression: KwEnum" pointing into the middle of a type.
            //
            // Captured verbatim rather than lowered to a struct. Its variants
            // carry payload types (`RegOperand: struct { reg_num: u8 }`) and a
            // union is not a struct: emitting one as the other would give every
            // variant its own storage and silently change the layout. A backend
            // that cannot read this text refuses the declaration, which is the
            // outcome to want.
            if self.current.kind == TokenKind::Ident && self.current.lexeme == "union" {
                let mut text = String::new();
                let mut depth = 0i32;
                let mut seen = false;
                while self.current.kind != TokenKind::Eof {
                    match self.current.kind {
                        TokenKind::LBrace => {
                            depth += 1;
                            seen = true;
                        }
                        TokenKind::RBrace => depth -= 1,
                        _ => {}
                    }
                    if !text.is_empty() {
                        text.push(' ');
                    }
                    text.push_str(&self.current.lexeme);
                    self.advance();
                    if seen && depth == 0 {
                        break;
                    }
                }
                decl.value = text;
                if self.current.kind == TokenKind::Semicolon {
                    self.advance();
                }
                return Ok(decl);
            }

            // [BUG 8 FIX] Check what follows: enum(...), struct { }, [N]T{ }, identifier, number, etc.
            if self.current.kind == TokenKind::KwEnum {
                // pub const Trit = enum(i8) { ... };
                decl.kind = NodeKind::EnumDecl;
                self.advance(); // consume 'enum'
                                // Optional backing type: (i8)
                if self.current.kind == TokenKind::LParen {
                    self.advance(); // consume (
                    if self.current.kind == TokenKind::Ident {
                        decl.extra_type = self.current.lexeme.clone();
                        self.advance();
                    }
                    self.expect(TokenKind::RParen)?; // consume )
                }
                // { ... }
                self.expect(TokenKind::LBrace)?;
                // Parse enum body with brace-skip for safety
                self.parse_enum_body(&mut decl)?;
                self.expect(TokenKind::RBrace)?;
            } else if self.current.kind == TokenKind::KwStruct {
                // pub const Foo = struct { ... };
                decl.kind = NodeKind::StructDecl;
                self.advance(); // consume 'struct'
                self.expect(TokenKind::LBrace)?;
                self.parse_struct_body(&mut decl)?;
                self.expect(TokenKind::RBrace)?;
            } else if self.current.kind == TokenKind::LBracket {
                // pub const TernaryWord = [WORD_BYTES]u8; or [_]u8{...} ** N
                // W383: try to parse the bracket expression as an array literal.
                // If it carries element children (e.g. [4]u16{...}), it is a ROM
                // initializer and should be emitted as a Verilog memory. If it
                // has no children (e.g. [WORD_BYTES]u8), it is a type alias and
                // we restore the parser state and preserve the legacy text form.
                // If parse_array_literal cannot handle the shape (e.g. ['T','R']),
                // fall back to the legacy text collection so old specs keep parsing.
                let save = self.save_state();
                let array_literal_result = self.parse_array_literal();
                let use_literal = match &array_literal_result {
                    Ok(lit) => !lit.children.is_empty(),
                    Err(_) => false,
                };
                if use_literal {
                    decl.children.push(array_literal_result.unwrap());
                } else if let Some(bare) = {
                    self.restore_state(save.clone());
                    self.parse_bare_array_literal()
                } {
                    // W568: a BARE bracketed list -- `const A: [3]u32 = [1, 2, 3]`.
                    // `parse_array_literal` only understands the Zig-ish
                    // `[N]T{ ... }` spelling, so it returned a childless node
                    // here and control fell through to the text collector
                    // below, which runs to the next SEMICOLON. t27 top-level
                    // declarations are newline-terminated, so one such const
                    // swallowed every declaration after it -- an entire spec
                    // collapsed into a single unparsable string.
                    decl.children.push(bare);
                } else {
                    self.restore_state(save);
                    // The collector runs to the next SEMICOLON, and t27's
                    // top-level declarations are newline-terminated, so an
                    // unrecognised bracket value used to consume the rest of
                    // the file. Stop as well at a declaration keyword that
                    // OPENS ITS OWN LINE -- the same-line test is what keeps
                    // `[]const u8` (whose `const` follows `[]` on one line)
                    // intact.
                    let mut val_text = String::new();
                    let mut last_line = self.current.line;
                    while self.current.kind != TokenKind::Semicolon
                        && self.current.kind != TokenKind::Eof
                    {
                        if self.current.line > last_line
                            && Self::opens_declaration(self.current.kind)
                        {
                            break;
                        }
                        last_line = self.current.line;
                        val_text.push_str(&self.current.lexeme);
                        self.advance();
                    }
                    let mut val_node = Node::new(NodeKind::ExprIdentifier);
                    val_node.name = val_text;
                    decl.children.push(val_node);
                }
                if self.current.kind == TokenKind::Semicolon {
                    self.advance();
                }
                return Ok(decl);
            } else if self.current.kind == TokenKind::LParen {
                // W652: a PARENTHESISED initialiser -- `const P : u32 = (A + 1) * 2;`
                // reached none of the branches below and fell through to the
                // trailing default, which pushed no child at all. Verilog then
                // emitted `localparam P = 0` and Zig emitted `const P: u32;`
                // with no initialiser -- not even valid Zig.
                let lit = self.parse_expr()?;
                decl.children.push(lit);
            } else if self.current.kind == TokenKind::Minus {
                // [BUG 10 FIX] Negative number: -1 or expression
                // W652: `-<Number>` with nothing after it keeps the cheap path.
                // Anything else -- `-A`, `-A - 1` -- must go through parse_expr.
                // Previously `-A` consumed the `-`, found no Number, and pushed
                // NOTHING: an initialiser silently vanished.
                let simple_negative_literal = self.peek.kind == TokenKind::Number;
                if simple_negative_literal {
                    let save = self.save_state();
                    self.advance(); // consume -
                    let lexeme = self.current.lexeme.clone();
                    self.advance(); // consume the number
                    if Self::token_continues_expr(self.current.kind) {
                        self.restore_state(save);
                        let lit = self.parse_expr()?;
                        decl.children.push(lit);
                    } else {
                        let mut val_node = Node::new(NodeKind::ExprLiteral);
                        val_node.value = format!("-{}", lexeme);
                        decl.children.push(val_node);
                    }
                } else {
                    let lit = self.parse_expr()?;
                    decl.children.push(lit);
                }
            } else if self.current.kind == TokenKind::Number {
                // W652: `const LIT : u32 = 100 / 7;` used to emit `LIT = 100`.
                if Self::token_continues_expr(self.peek.kind) {
                    let lit = self.parse_expr()?;
                    decl.children.push(lit);
                } else {
                    let mut val_node = Node::new(NodeKind::ExprLiteral);
                    val_node.value = self.current.lexeme.clone();
                    decl.children.push(val_node);
                    self.advance();
                }
            } else if self.current.kind == TokenKind::Ident {
                // W533/W543: a scalar struct literal initializer `const x : T = T{...}`
                // or a function-call initializer `const x : T = make(5)` is parsed as
                // a full expression so the AST preserves arguments and field values.
                // Plain identifiers stay as `ExprIdentifier` for type aliases and
                // cross-const references.
                let name = self.current.lexeme.clone();
                // W651: a QUALIFIED path must go through `parse_expr` too.
                // `parse_expr_primary` concatenates `a::b` into one flat name
                // (compiler.rs ~3620); this branch took only
                // `self.current.lexeme` and advanced ONE token, so
                // `const A : u8 = constants::COMPLEXITY_HIGH;` became
                // `A = constants` -- a silently WRONG VALUE, in all four
                // backends, with no error and no warning. 98 such initialisers
                // across 29 specs.
                //
                // The asymmetry is T60's shape exactly: `constants::make(5)`
                // already worked, because `(` routed it through `parse_expr`.
                // Only the bare-path spelling took the truncating branch.
                //
                // W652: the same hole, one operator wider. `const DIV : u32 =
                // A / B;` emitted `DIV = A` -- the divisor was DISCARDED, in
                // all five backends, silently. `A > 5` emitted `A`; `Cfg.width`
                // emitted `Cfg`. The C backend turned each into a `typedef`,
                // so a constant became a TYPE. `f(A) + 1` was correct all
                // along, because `(` routed it through `parse_expr` -- the
                // delimiter, not the meaning, decided correctness.
                let qualified =
                    self.peek.kind == TokenKind::Colon;
                if self.peek.kind == TokenKind::LBrace
                    || self.peek.kind == TokenKind::LParen
                    || qualified
                    || Self::token_continues_expr(self.peek.kind)
                {
                    let lit = self.parse_expr()?;
                    decl.children.push(lit);
                } else {
                    let mut val_node = Node::new(NodeKind::ExprIdentifier);
                    val_node.name = name;
                    decl.children.push(val_node);
                    self.advance();
                }
            } else if self.current.kind == TokenKind::KwTrue
                || self.current.kind == TokenKind::KwFalse
            {
                let mut val_node = Node::new(NodeKind::ExprLiteral);
                val_node.value = self.current.lexeme.clone();
                decl.children.push(val_node);
                self.advance();
            } else if self.current.kind == TokenKind::String {
                let mut val_node = Node::new(NodeKind::ExprLiteral);
                // W458: mark string literals so the Verilog backend can escape
                // newlines/tabs/quotes before emitting them.
                val_node.value = self.current.lexeme.clone();
                val_node.extra_kind = "string".to_string();
                decl.children.push(val_node);
                self.advance();
            } else if self.current.kind == TokenKind::KwFn {
                // W914: `pub const Middleware = fn(Ctx) bool;` -- a function
                // TYPE alias. The counted skip charged it as a discard; the
                // text collector preserves it as the value, uncounted.
                let mut val_text = String::new();
                while self.current.kind != TokenKind::Semicolon
                    && self.current.kind != TokenKind::Eof
                    && !(self.current.line > self.last_line && self.is_top_level_start())
                {
                    if !val_text.is_empty() {
                        val_text.push(' ');
                    }
                    val_text.push_str(&self.current.lexeme);
                    self.advance();
                }
                let mut val_node = Node::new(NodeKind::ExprIdentifier);
                val_node.name = val_text;
                decl.children.push(val_node);
                if self.current.kind == TokenKind::Semicolon {
                    self.advance();
                }
                return Ok(decl);
            } else {
                // Other RHS (tilde, parens, etc.) — skip to semicolon
                self.skip_to_semicolon()?;
                return Ok(decl);
            }

            // After reading the first value token, skip any remaining expression
            // tokens (operators, more operands) until semicolon
            // But don't skip past module body closing brace or next declaration
            if self.current.kind != TokenKind::Semicolon
                && self.current.kind != TokenKind::RBrace
                && !self.is_top_level_start()
                && self.current.kind != TokenKind::Eof
            {
                self.skip_to_semicolon()?;
            }
            // Consume trailing semicolon so the module-body loop is not left
            // pointing at a stray ';' (which would error and skip subsequent
            // const/var declarations via skip_to_next_top_level).
            if self.current.kind == TokenKind::Semicolon {
                self.advance();
            }
            return Ok(decl);
        }

        // Consume trailing semicolon
        if self.current.kind == TokenKind::Semicolon {
            self.advance();
        }
        Ok(decl)
    }

    fn parse_var_decl(&mut self, is_pub: bool) -> Result<Node, String> {
        let mut decl = Node::new(NodeKind::ConstDecl);
        decl.extra_pub = is_pub;
        decl.extra_mutable = true;

        if !self.pending_pragma.is_empty() {
            decl.extra_pragma = self.pending_pragma.clone();
            self.pending_pragma.clear();
        }

        self.advance(); // consume 'var'

        // Name
        if self.current.kind == TokenKind::Ident {
            decl.name = self.current.lexeme.clone();
            self.advance();
        }

        // Type annotation: : Type
        if self.current.kind == TokenKind::Colon {
            self.advance(); // consume :
            decl.extra_type = self.parse_type_annotation();
        }

        // Initial value: = expr
        if self.current.kind == TokenKind::Equals {
            self.advance(); // consume =
            let val_node = self.parse_expr()?;
            decl.children.push(val_node);
        }

        // W903 (0008 v3): var had NO tail-skip, so junk after a recovered
        // `var` (`then v == 2` at module level) hard-errored the whole module
        // where const's tail swallowed it. Mirror const's tail exactly.
        if self.current.kind != TokenKind::Semicolon
            && self.current.kind != TokenKind::RBrace
            && !self.is_top_level_start()
            && self.current.kind != TokenKind::Eof
        {
            self.skip_to_semicolon()?;
        }
        if self.current.kind == TokenKind::Semicolon {
            self.advance();
        }
        Ok(decl)
    }

    fn parse_enum_body(&mut self, decl: &mut Node) -> Result<(), String> {
        // We are inside { ... } of an enum. Parse variant = value pairs.
        while self.current.kind != TokenKind::RBrace && self.current.kind != TokenKind::Eof {
            // A variant whose name is a KEYWORD: `then`, `and`, `assert`,
            // `expect` are all real members of ClauseKind in
            // contrib/backend/zig/legacy/main_zig_handwritten.t27. Requiring
            // Ident dropped them, the loop fell through to the skip below, and
            // the enum's own `}` ended something else -- reported 60 lines on
            // as "Unexpected token in expression: Semicolon".
            //
            // Same predicate the struct-literal parser uses for a keyword field
            // label and the `.Variant` shorthand uses for a keyword value: in a
            // position where only a name can appear, any word-shaped token is a
            // name. A language whose own token names are keywords will keep
            // producing this.
            let word_shaped = !self.current.lexeme.is_empty()
                && self
                    .current
                    .lexeme
                    .chars()
                    .all(|c| c.is_ascii_alphanumeric() || c == '_');
            if self.current.kind == TokenKind::Ident || word_shaped {
                let name = self.current.lexeme.clone();
                self.advance();

                let mut value_str = String::new();
                if self.current.kind == TokenKind::Equals {
                    self.advance(); // consume =
                                    // [BUG 10] Handle negative enum values
                    if self.current.kind == TokenKind::Minus {
                        value_str.push('-');
                        self.advance();
                    }
                    if self.current.kind == TokenKind::Number {
                        value_str.push_str(&self.current.lexeme);
                        self.advance();
                    } else if self.current.kind == TokenKind::Ident {
                        value_str.push_str(&self.current.lexeme);
                        self.advance();
                    }
                }

                let mut variant = Node::new(NodeKind::EnumVariant);
                variant.name = name;
                variant.value = value_str;
                decl.children.push(variant);

                if self.current.kind == TokenKind::Comma {
                    self.advance();
                }
            } else {
                // Skip unexpected tokens inside enum
                self.advance();
            }
        }
        Ok(())
    }

    fn parse_struct_body(&mut self, decl: &mut Node) -> Result<(), String> {
        // We are inside { ... } of a struct. Parse field: Type pairs.
        while self.current.kind != TokenKind::RBrace && self.current.kind != TokenKind::Eof {
            // W657 (T104): a field may carry `pub`. The loop tested only for
            // `Ident`, and `pub` lexes as `KwPub`, so `pub struct P { pub a: u64 }`
            // parsed to a StructDecl with NO CHILDREN. `struct_decls` then held an
            // empty field list, `packed_width` fell through to its 32-bit default,
            // the lowerable-scalar-struct predicate failed, and every `p.a` was
            // emitted as the flattened `p_a` -- a name declared nowhere.
            //
            //   pub struct P { a: u64, ... }      -> input [128:0] p;  p[0 +: 64]
            //   pub struct P { pub a: u64, ... }  -> input  [31:0] p;  p_a
            //
            // Same shape as T60: the obligation met on the spelling without the
            // modifier and missed on the one with it.
            if self.current.kind == TokenKind::KwPub {
                self.advance();
            }
            // A NESTED TYPE declaration: `const Kind = enum { ... };` inside a
            // struct body. Nothing here consumed it, so the walk reached the
            // ENUM's closing brace -- and this loop stops at any RBrace, so the
            // struct ended there. The module then ended at the struct's own
            // brace and the error surfaced sixty lines later on a `;`.
            //
            // Third appearance of one shape: a nested brace group ending the
            // construct that contains it (W577 for methods, gap 5 for an
            // anonymous return type, this for a nested type). Consumed
            // brace-balanced; the members are not lowered, and the point is
            // only that the struct still ends where it should.
            if self.current.kind == TokenKind::KwConst || self.current.kind == TokenKind::KwVar {
                let mut d = 0i32;
                let mut seen = false;
                while self.current.kind != TokenKind::Eof {
                    match self.current.kind {
                        TokenKind::LBrace => {
                            d += 1;
                            seen = true;
                        }
                        TokenKind::RBrace => d -= 1,
                        TokenKind::Semicolon if !seen => {
                            // A plain `const N = 3;` with no brace group.
                            self.advance();
                            break;
                        }
                        _ => {}
                    }
                    self.advance();
                    if seen && d == 0 {
                        if self.current.kind == TokenKind::Semicolon {
                            self.advance();
                        }
                        break;
                    }
                }
                continue;
            }
            if self.current.kind == TokenKind::Ident {
                let field_name = self.current.lexeme.clone();
                self.advance();

                let mut type_str = String::new();
                let mut field_default: Option<Node> = None;
                if self.current.kind == TokenKind::Colon {
                    self.advance(); // consume :

                    // Struct field types were joined LEXEME BY LEXEME with no
                    // separator, so `[]const u8` became `[]constu8` -- "use of
                    // undeclared identifier 'constu8'" in 11 specs (W568). The
                    // parameter side has always used the real type grammar;
                    // only this path did not.
                    //
                    // Prefer `parse_type_annotation`, which keeps the space
                    // after `const`, keeps `(A, B)` from truncating at its
                    // comma, and understands dotted paths. Shapes it cannot
                    // model (generics `Map<K, V>`, field defaults `= 5`) leave
                    // the parser somewhere other than a field boundary; those
                    // restore the checkpoint and use the original token join,
                    // so nothing that parsed before can stop parsing.
                    // The field's type must also END ON ITS OWN LINE. Three
                    // specs in the corpus contain a malformed field whose type
                    // opens a string literal (`tag : [[]Const u8",`); the
                    // bracket loop happily consumes that string across the rest
                    // of the file, and the struct then never finds its closing
                    // brace. The raw join stopped at the first comma, so the
                    // damage stayed inside one field. Requiring the terminator
                    // on the starting line restores that containment.
                    let start_line = self.current.line;
                    let checkpoint = self.save_state();
                    let parsed = self.parse_type_annotation();
                    let type_ends_on_its_own_line = self.current.line == start_line;

                    // A field DEFAULT (`data : [256]u8 = [0, 0, ...]`) used to
                    // be swallowed into the type string, giving Zig
                    // `data: [256]u8=[0,` -- the "expected ']', found ','"
                    // class. Parse it as an expression instead and keep it as
                    // the field's child; the default may legitimately span
                    // lines, so only the TYPE carries the same-line rule.
                    let mut default_value: Option<Node> = None;
                    if !parsed.is_empty()
                        && type_ends_on_its_own_line
                        && self.current.kind == TokenKind::Equals
                    {
                        self.advance(); // consume =
                        default_value = self.parse_expr().ok();
                    }

                    let at_field_boundary = type_ends_on_its_own_line
                        && matches!(
                            self.current.kind,
                            TokenKind::Comma
                                | TokenKind::Semicolon
                                | TokenKind::RBrace
                                | TokenKind::Eof
                                | TokenKind::Ident
                        );
                    if !parsed.is_empty() && at_field_boundary {
                        type_str = parsed;
                        if let Some(v) = default_value {
                            field_default = Some(v);
                        }
                    } else {
                        self.restore_state(checkpoint);
                        // W699 (#2127, third attempt). Collect raw type lexemes, but let
                        // NESTING decide only the SEPARATOR, never the BLOCK TERMINATOR.
                        //
                        // The two reverted attempts both failed the same way: they allowed a
                        // depth counter to suppress `RBrace`/`Eof`, so an unbalanced type ate
                        // the struct's closing brace (attempt a) or spun forever at Eof, where
                        // the lexer yields `Eof` indefinitely (attempt b).
                        //
                        // Invariant enforced here:
                        //   RBrace, Semicolon and Eof terminate UNCONDITIONALLY at any depth;
                        //   only Comma consults `depth`.
                        // Termination therefore does not depend on the input being well-formed:
                        // every iteration consumes exactly one token and Eof always exits.
                        let mut depth: i32 = 0;
                        let mut prev_was_ident = false;
                        loop {
                            let k = self.current.kind.clone();
                            // Unconditional terminators — never gated by depth.
                            if k == TokenKind::RBrace
                                || k == TokenKind::Semicolon
                                || k == TokenKind::Eof
                            {
                                break;
                            }
                            if k == TokenKind::Comma && depth <= 0 {
                                break;
                            }
                            match k {
                                TokenKind::LParen | TokenKind::LBracket => depth += 1,
                                TokenKind::RParen | TokenKind::RBracket => {
                                    if depth > 0 {
                                        depth -= 1;
                                    }
                                }
                                // `<` opens a generic argument list only directly after an
                                // identifier (`Map<`); as an operator it must not open depth.
                                TokenKind::Lt if prev_was_ident => depth += 1,
                                TokenKind::Gt => {
                                    if depth > 0 {
                                        depth -= 1;
                                    }
                                }
                                TokenKind::ShiftRight => {
                                    // `>>` closes two generic levels (`Vec<Vec<u8>>`).
                                    depth = if depth >= 2 { depth - 2 } else { 0 };
                                }
                                _ => {}
                            }
                            prev_was_ident = k == TokenKind::Ident;
                            type_str.push_str(&self.current.lexeme);
                            self.advance();
                        }
                    }
                }

                let mut field = Node::new(NodeKind::ExprIdentifier);
                field.name = field_name;
                field.extra_type = type_str;
                if let Some(v) = field_default {
                    field.children.push(v);
                }
                decl.children.push(field);

                if self.current.kind == TokenKind::Comma
                    || self.current.kind == TokenKind::Semicolon
                {
                    self.advance();
                }
            } else if self.current.kind == TokenKind::KwFn
                || self.current.kind == TokenKind::KwPub
            {
                // W577: a METHOD inside a struct body. The skip below consumed
                // tokens one at a time without tracking braces, so the method's
                // closing `}` ended the struct body and the struct's own `}`
                // then ended the module -- `specs/jit/jit.t27` lost 797 of its
                // 875 lines that way, and `specs/ternary/bigint.t27` 1,359 of
                // 1,445, both while reporting success.
                //
                // The method is skipped, not lowered: struct methods are not
                // part of what the backends emit today. What matters is that
                // the skip is BRACE-BALANCED so the struct still ends where it
                // should.
                // Scan to the method's BODY brace. An anonymous struct type in
                // return position -- `fn f(...) struct { u64, []const u8 } {`
                // -- puts a brace in front of it, and stopping at that one made
                // the balanced skip below close on the TYPE. The struct then
                // ended at its first such method and the module ended at the
                // struct's own `}`: exactly the W577 failure this comment block
                // records, recurring on a construct it did not anticipate. It
                // cost compiler/parser/lexer.t27 everything after line 362
                // while reporting a parse error 144 lines further on.
                loop {
                    if matches!(
                        self.current.kind,
                        TokenKind::Eof | TokenKind::RBrace | TokenKind::LBrace
                    ) {
                        break;
                    }
                    if matches!(self.current.kind, TokenKind::KwStruct | TokenKind::KwEnum) {
                        // Consume the whole type, braces included, so the scan
                        // resumes looking for the body.
                        let mut d = 0i32;
                        let mut seen = false;
                        while self.current.kind != TokenKind::Eof {
                            match self.current.kind {
                                TokenKind::LBrace => {
                                    d += 1;
                                    seen = true;
                                }
                                TokenKind::RBrace => d -= 1,
                                _ => {}
                            }
                            self.advance();
                            if seen && d == 0 {
                                break;
                            }
                        }
                        continue;
                    }
                    self.advance();
                }
                if self.current.kind == TokenKind::LBrace {
                    let mut depth = 0i32;
                    loop {
                        match self.current.kind {
                            TokenKind::LBrace => depth += 1,
                            TokenKind::RBrace => depth -= 1,
                            TokenKind::Eof => break,
                            _ => {}
                        }
                        self.advance();
                        if depth == 0 {
                            break;
                        }
                    }
                }
            } else {
                // Skip unexpected tokens inside struct
                self.advance();
            }
        }
        Ok(())
    }

    /// Parse a type annotation like `Trit`, `*Trit`, `[]u8`, `[N]u8`, `[]const u8`, `anytype`
    fn parse_type_annotation(&mut self) -> String {
        let mut ty = String::new();

        // A leading `&` (Rust-style borrow spelling, used by 103 specs as
        // `&str`) was not consumed here, so parse_type_annotation returned an
        // EMPTY type and the parameter loop then read the type name as the next
        // parameter: `fn g(name: &str)` produced params ["name: ", "str: "] and
        // emitted `fn g(name: , str: )`. t27 has no reference types, so the
        // borrow marker is accepted and dropped -- the Zig/Rust mappers already
        // strip it.
        if self.current.kind == TokenKind::Amp {
            self.advance();
        }

        // Optional type: `?u64`, `?[]const u8`. The mapper downstream expects
        // the `?` to be part of the type text.
        if self.current.kind == TokenKind::Question {
            self.advance();
            let inner = self.parse_type_annotation();
            return if inner.is_empty() {
                String::new()
            } else {
                format!("?{}", inner)
            };
        }

        // Machine-generated specs QUOTE the type in a declaration:
        // `head : "usize"`, `allocator : "std.mem.Allocator"`. A string token
        // is not an identifier, so the type parser returned empty and the raw
        // fallback carried the quotes into the backend. Take the string's
        // contents as the type name.
        if self.current.kind == TokenKind::String {
            let quoted = self.current.lexeme.trim_matches('"').to_string();
            self.advance();
            return quoted;
        }

        // Handle tuple type: (T1, T2, ...). Keep the raw textual form so that
        // named tuples like (a: T, b: T) do not hang the parser and are stored
        // as-is for backends that do not need to unpack them.
        if self.current.kind == TokenKind::LParen {
            ty.push('(');
            self.advance(); // consume (
            while self.current.kind != TokenKind::RParen
                && self.current.kind != TokenKind::Eof
            {
                let before = self.current.kind;
                let elem = self.parse_type_annotation();
                ty.push_str(&elem);
                if self.current.kind == TokenKind::Comma {
                    // Canonical spelling is `(T1, T2)` with a space: the rest of
                    // the codebase and every backend test matches on that form.
                    ty.push_str(", ");
                    self.advance();
                } else if self.current.kind != TokenKind::RParen {
                    // Not a clean tuple-type element (e.g. named-field syntax);
                    // consume the raw token so we cannot spin forever.
                    if self.current.kind == before && elem.is_empty() {
                        ty.push_str(&self.current.lexeme);
                        self.advance();
                    }
                }
            }
            if self.current.kind == TokenKind::RParen {
                ty.push(')');
                self.advance();
            }
            return ty;
        }

        // Handle pointer prefix: *Type or *const Type. Parse the pointee through
        // this same type grammar: `*Name(T)` is a pointer to the application
        // `Name(T)`, not an attempt to apply `T` to a pointer.
        if self.current.kind == TokenKind::Star {
            ty.push('*');
            self.advance();
            if self.current.kind == TokenKind::KwConst {
                ty.push_str("const ");
                self.advance();
            }
            ty.push_str(&self.parse_type_annotation());
            return ty;
        }

        // Handle slice/array prefix: []Type, [N]Type, [[f64; 8]; 8], []const Type
        while self.current.kind == TokenKind::LBracket {
            ty.push('[');
            self.advance(); // consume [
            let mut depth: usize = 1;
            while depth > 0 && self.current.kind != TokenKind::Eof {
                match self.current.kind {
                    TokenKind::LBracket => {
                        depth += 1;
                        ty.push('[');
                        self.advance();
                    }
                    TokenKind::RBracket => {
                        depth -= 1;
                        ty.push(']');
                        self.advance();
                    }
                    _ => {
                        ty.push_str(&self.current.lexeme);
                        self.advance();
                    }
                }
            }
        }

        // Handle 'const' qualifier: []const u8
        if self.current.kind == TokenKind::KwConst {
            if !ty.is_empty() {
                ty.push_str("const ");
            } else {
                ty.push_str("const ");
            }
            self.advance();
        }

        // Handle pointer after brackets
        if self.current.kind == TokenKind::Star {
            ty.push('*');
            self.advance();
            if self.current.kind == TokenKind::KwConst {
                ty.push_str("const ");
                self.advance();
            }
        }

        // Main type identifier with namespace support (lexer::Lexer, base::types)
        if self.current.kind == TokenKind::Ident {
            ty.push_str(&self.current.lexeme);
            self.advance();

            // Handle :: namespace separators
            while self.current.kind == TokenKind::Colon {
                // Check for :: (two colons)
                if self.peek.kind == TokenKind::Colon {
                    ty.push_str("::");
                    self.advance(); // consume first :
                    self.advance(); // consume second :
                    if self.current.kind == TokenKind::Ident {
                        ty.push_str(&self.current.lexeme);
                        self.advance();
                    }
                } else {
                    break;
                }
            }

            // Dotted namespace paths (`std.mem.Allocator`, `base.types.Trit`).
            // Only `::` was handled, so `fn init(allocator: std.mem.Allocator)`
            // returned the type `std` and left `.mem.Allocator` for the
            // parameter loop, which read it as two further parameters and
            // emitted `fn init(allocator: Std, mem: , Allocator: )`. That is
            // the whole "expected type expression, found ','" class measured in
            // W568 (28 of 183 compile failures); 40 specs use dotted types.
            //
            // A dot is only consumed when an identifier actually follows, so a
            // shape this cannot model leaves the parser exactly where it was.
            while self.current.kind == TokenKind::Dot && self.peek.kind == TokenKind::Ident {
                ty.push('.');
                self.advance(); // consume .
                ty.push_str(&self.current.lexeme);
                self.advance(); // consume the segment
            }

            // #2164: `Name(T)` is a type application when the parser has
            // already entered a type position. It is deliberately parsed here,
            // rather than in expression parsing, because the same tokens in an
            // expression position continue to mean a function call.
            self.parse_type_application_args(&mut ty);
        } else if self.current.kind == TokenKind::KwVoid {
            ty.push_str("void");
            self.advance();
        }

        ty
    }

    /// Append one parenthesised type-argument list to a type name.
    ///
    /// The parser reaches this helper only after consuming the base type name.
    /// Thus `Name(T)` in an annotation is an application, whereas `Name(T)` in
    /// an expression remains the expression parser's call syntax. Numeric
    /// arguments are retained verbatim because existing `P(2)`, `Z(1)`, and
    /// `N(0)` applications are part of the accepted type surface.
    fn parse_type_application_args(&mut self, ty: &mut String) {
        if self.current.kind != TokenKind::LParen {
            return;
        }

        ty.push('(');
        self.advance(); // consume (
        let mut first = true;
        while self.current.kind != TokenKind::RParen && self.current.kind != TokenKind::Eof {
            if !first {
                if self.current.kind != TokenKind::Comma {
                    // Keep an unfamiliar shape for the caller's existing
                    // recovery rather than consuming a token without progress.
                    break;
                }
                ty.push_str(", ");
                self.advance(); // consume ,
                if self.current.kind == TokenKind::RParen {
                    break;
                }
            }

            let before = self.current.kind;
            if self.current.kind == TokenKind::Number {
                ty.push_str(&self.current.lexeme);
                self.advance();
            } else {
                let arg = self.parse_type_annotation();
                if arg.is_empty() && self.current.kind == before {
                    // Do not loop forever on a token outside the type grammar.
                    break;
                }
                ty.push_str(&arg);
            }
            first = false;
        }
        if self.current.kind == TokenKind::RParen {
            ty.push(')');
            self.advance(); // consume )
        }
    }

    fn parse_fn_decl(&mut self, is_pub: bool) -> Result<Node, String> {
        let mut decl = Node::new(NodeKind::FnDecl);
        decl.extra_pub = is_pub;
        decl.line = self.current.line as u32;

        self.advance(); // consume 'fn'

        if self.current.kind == TokenKind::Ident {
            decl.name = self.current.lexeme.clone();
            self.advance();
            // Handle dotted names like Parser.new
            while self.current.kind == TokenKind::Dot {
                decl.name.push('.');
                self.advance(); // consume .
                if self.current.kind == TokenKind::Ident {
                    decl.name.push_str(&self.current.lexeme);
                    self.advance();
                }
            }
        }

        // Parse parameter list
        self.expect(TokenKind::LParen)?;
        while self.current.kind != TokenKind::RParen && self.current.kind != TokenKind::Eof {
            // Parse param name
            if self.current.kind != TokenKind::Ident {
                // Skip unexpected token
                self.advance();
                continue;
            }
            let param_name = self.current.lexeme.clone();
            self.advance();

            // Expect colon
            if self.current.kind == TokenKind::Colon {
                self.advance(); // consume :
            }

            // Parse param type
            let param_type = self.parse_type_annotation();

            decl.params.push((param_name, param_type));

            // Consume comma between params
            if self.current.kind == TokenKind::Comma {
                self.advance();
            }
        }
        self.expect(TokenKind::RParen)?;

        // BDD-style fn: `fn name() given ... then ...` -- a keyword-style test
        // spelled as a fn (linker.t27). Detect BEFORE return-type parsing,
        // which would otherwise consume `given` as an identifier return type.
        if self.current.kind == TokenKind::Ident && self.current.lexeme == "given" {
            // W699 rung 5: this arm RECOGNISED the shape by name and then threw
            // it away. `skip_to_next_top_level()` discarded every clause under
            // such a fn -- 2 453 tokens across 19 specs, and `given` is the
            // fourth-largest head token in the whole corpus discard.
            //
            // The shared clause parser already serves `test`, `invariant` and
            // `bench`; a fn spelled as a test is the same body. Detection is
            // unchanged -- same token, same lexeme -- only the action is.
            //
            // The column anchor is what the bench path (W905) had to set for the
            // same reason: continuation statements need an anchor that the head
            // never established, and without it the statement arms stay dark.
            // ... and it is lowered as a TEST, not as a function.
            //
            // The first attempt kept the FnDecl and filled its body. Every
            // backend then treated it as a real function: `gen-verilog` emits
            // synthesizable RTL for functions and deliberately does NOT lower
            // tests, so the recovered clauses became `\assert (...)` inside a
            // task -- "Enable of unknown task ``assert''" -- and the elaboration
            // ratchet caught it, linker 4 -> 6. Correctly: a task body cannot
            // assert, and a test body must not become one.
            //
            // `fn name() given ... then ...` IS a test. Emitting a TestBlock
            // teaches no backend anything new: each already knows whether it
            // lowers tests, and each now does the right thing with this one.
            let mut block = Node::new(NodeKind::TestBlock);
            block.name = decl.name.clone();
            self.bdd_first_col_preset = Some(self.current.col);
            self.parse_bdd_clauses(&mut block);
            return Ok(block);
        }

        // Optional arrow for return type: -> Type
        if self.current.kind == TokenKind::Arrow {
            self.advance(); // consume ->
        }

        // Handle error union prefix: !Type or !void
        let has_error_union = self.current.kind == TokenKind::Bang;
        if has_error_union {
            self.advance(); // consume !
        }

        // Reference types are transparent at the spec level: `&str` / `&T`
        // parse as their referent (t27#1960 fallout -- the old recovery
        // silently dropped whole fns over the `&`).
        if self.current.kind == TokenKind::Amp {
            self.advance(); // consume &
        }

        // Return type (identifier, tuple, or []T / [N]T / [][]const u8 slice/array types, or void)
        // W581: an OPTIONAL return type, `-> ?u32`. The shared type parser
        // handles the `?`; this header has its own paths and needed telling.
        if self.current.kind == TokenKind::KwStruct {
            // An ANONYMOUS STRUCT TYPE in return position: Zig's tuple type,
            // `fn f(...) struct { u64, []const u8 } { ... }`. The dispatch
            // below knows `?`, `(`, an identifier and the slice forms, and
            // nothing else, so `struct` fell through to the body and the
            // header died on "Expected LBrace, got KwStruct" -- which is
            // exactly where compiler/parser/lexer.t27 stopped once the
            // anonymous braced LITERAL was understood. Captured verbatim, the
            // way a local `const T = struct {...}` already is: the backends
            // that can lower it read the text, and the ones that cannot refuse
            // on a type they can see rather than on a header they could not
            // parse.
            let mut text = String::new();
            let mut depth: i32 = 0;
            let mut seen = false;
            loop {
                if self.current.kind == TokenKind::Eof {
                    break;
                }
                match self.current.kind {
                    TokenKind::LBrace => {
                        depth += 1;
                        seen = true;
                    }
                    TokenKind::RBrace => depth -= 1,
                    _ => {}
                }
                if !text.is_empty() {
                    text.push(' ');
                }
                text.push_str(&self.current.lexeme);
                self.advance();
                if seen && depth == 0 {
                    break;
                }
            }
            decl.extra_return_type = text;
        } else if self.current.kind == TokenKind::Question {
            decl.extra_return_type = self.parse_type_annotation();
        } else if self.current.kind == TokenKind::LParen {
            // Tuple return type: (u32, u32)
            decl.extra_return_type = self.parse_type_annotation();
        } else if self.current.kind == TokenKind::Ident {
            let mut rt_name = self.current.lexeme.clone();
            self.advance();
            // W579: a SCOPED return type. This branch read one identifier and
            // stopped, so `-> gf16::GF16` left the `::` behind and the fn
            // header failed with "Expected LBrace, got Colon" -- 899 assertion
            // clauses across 9 specs. The parameter side has handled `::` and
            // `.` since W568.
            loop {
                if self.current.kind == TokenKind::Colon && self.peek.kind == TokenKind::Colon {
                    rt_name.push_str("::");
                    self.advance();
                    self.advance();
                } else if self.current.kind == TokenKind::Dot
                    && self.peek.kind == TokenKind::Ident
                {
                    rt_name.push('.');
                    self.advance();
                } else {
                    break;
                }
                if self.current.kind == TokenKind::Ident {
                    rt_name.push_str(&self.current.lexeme);
                    self.advance();
                } else {
                    break;
                }
            }
            decl.extra_return_type = rt_name;
            self.parse_type_application_args(&mut decl.extra_return_type);
            // Handle generic return types like Option<Foo>
            if self.current.kind == TokenKind::Lt {
                let mut gt_depth = 1;
                self.advance(); // consume <
                while gt_depth > 0 && self.current.kind != TokenKind::Eof {
                    if self.current.kind == TokenKind::Lt {
                        gt_depth += 1;
                    } else if self.current.kind == TokenKind::Gt {
                        gt_depth -= 1;
                        if gt_depth == 0 {
                            break;
                        }
                    }
                    self.advance();
                }
                if self.current.kind == TokenKind::Gt {
                    self.advance(); // consume >
                }
            }
        } else if self.current.kind == TokenKind::LBracket {
            // Handle one or more bracket levels: []Type, [][]const u8, [N]Type, [[f64; 8]; 8]
            let mut rt = String::new();
            while self.current.kind == TokenKind::LBracket {
                rt.push('[');
                self.advance(); // consume [
                let mut depth: usize = 1;
                while depth > 0 && self.current.kind != TokenKind::Eof {
                    match self.current.kind {
                        TokenKind::LBracket => {
                            depth += 1;
                            rt.push('[');
                            self.advance();
                        }
                        TokenKind::RBracket => {
                            depth -= 1;
                            rt.push(']');
                            self.advance();
                        }
                        _ => {
                            rt.push_str(&self.current.lexeme);
                            self.advance();
                        }
                    }
                }
            }
            // Handle 'const' qualifier in return type: []const u8
            if self.current.kind == TokenKind::KwConst {
                rt.push_str("const ");
                self.advance();
            }
            // Handle pointer prefix: *Type
            if self.current.kind == TokenKind::Star {
                rt.push('*');
                self.advance();
            }
            if self.current.kind == TokenKind::Ident {
                rt.push_str(&self.current.lexeme);
                self.advance();
                // W579: a SCOPED return type. This bespoke tail read one
                // identifier and stopped, so `-> gf16::GF16` left the `::`
                // behind and the fn header failed with "Expected LBrace, got
                // Colon" -- 899 assertion clauses across 9 specs. The parameter
                // side has handled `::` and `.` since W568.
                loop {
                    if self.current.kind == TokenKind::Colon
                        && self.peek.kind == TokenKind::Colon
                    {
                        rt.push_str("::");
                        self.advance();
                        self.advance();
                    } else if self.current.kind == TokenKind::Dot
                        && self.peek.kind == TokenKind::Ident
                    {
                        rt.push('.');
                        self.advance();
                    } else {
                        break;
                    }
                    if self.current.kind == TokenKind::Ident {
                        rt.push_str(&self.current.lexeme);
                        self.advance();
                    } else {
                        break;
                    }
                }
            }
            decl.extra_return_type = rt;
        } else if self.current.kind == TokenKind::KwVoid {
            decl.extra_return_type = "void".to_string();
            self.advance();
        } else if self.current.kind == TokenKind::Star {
            // Pointer return type: *Type
            self.advance(); // consume *
            if self.current.kind == TokenKind::KwConst {
                self.advance(); // consume const
            }
            if self.current.kind == TokenKind::Ident {
                decl.extra_return_type = format!("*{}", self.current.lexeme);
                self.advance();
            }
        } else if self.current.kind == TokenKind::LParen {
            // Tuple return type: `(T, U, ...)`. Previously unhandled: the parser
            // fell through, desynced on `(` and silently dropped the whole
            // function. Capture it as a canonical `(T, U)` string so the
            // function survives and backends can lower it.
            let mut rt = String::from("(");
            self.advance(); // consume (
            while self.current.kind != TokenKind::RParen && self.current.kind != TokenKind::Eof {
                if self.current.kind == TokenKind::Comma {
                    rt.push_str(", ");
                } else {
                    rt.push_str(&self.current.lexeme);
                }
                self.advance();
            }
            if self.current.kind == TokenKind::RParen {
                self.advance(); // consume )
            }
            rt.push(')');
            decl.extra_return_type = rt;
        }

        // Skip optional 'const' qualifier before the body
        if self.current.kind == TokenKind::KwConst {
            self.advance();
        }

        // Parse body: real expressions
        self.expect(TokenKind::LBrace)?;
        self.parse_fn_body(&mut decl)?;
        self.expect(TokenKind::RBrace)?;
        Ok(decl)
    }

    /// Parse function body statements until closing brace
    fn parse_fn_body(&mut self, decl: &mut Node) -> Result<(), String> {
        while self.current.kind != TokenKind::RBrace && self.current.kind != TokenKind::Eof {
            // W883 prototype: a NESTED fn is parsed with the ordinary fn parser
            // and HOISTED to module level -- no statement node is produced, so
            // no backend needs a no-op. Sound only when the nested fn captures
            // nothing beyond its own parameters and module-level names; the
            // one corpus instance (gf16's phi_dist) satisfies that, and the
            // proposal text records the capture question as OPEN.
            if self.current.kind == TokenKind::KwFn {
                let nested = self.parse_fn_decl(false)?;
                // CAPTURE CHECK, at the only scope that matters. Hoisting moves
                // the nested fn OUT of the enclosing body, so the one thing it
                // must not reach is the enclosing fn's own bindings -- its
                // parameters and the locals declared before this point. A free
                // name that is NOT such a binding resolves identically before
                // and after hoisting (module scope either way), so external
                // names like an imported PHI_INV are none of this check's
                // business. The first version asked \"is it module-level?\" and
                // rejected gf16 for an IMPORTED constant -- the wrong question.
                let free = free_idents_of(&nested);
                let mut enclosing: Vec<&str> =
                    decl.params.iter().map(|p| p.0.as_str()).collect();
                for c in &decl.children {
                    if c.kind == NodeKind::StmtLocal && !c.name.is_empty() {
                        enclosing.push(c.name.as_str());
                    }
                }
                let captured: Vec<String> = free
                    .into_iter()
                    .filter(|f| enclosing.iter().any(|e| e == f))
                    .collect();
                if !captured.is_empty() {
                    return Err(format!(
                        "nested fn '{}' inside '{}' captures enclosing locals {:?} -- \
                         hoisting would unbind them; lift them to parameters or module consts",
                        nested.name, decl.name, captured
                    ));
                }
                self.hoisted_fns.push(nested);
                continue;
            }
            match self.parse_body_stmt() {
                Ok(stmt) => decl.children.push(stmt),
                Err(e) => {
                    // A malformed statement is a HARD error. The old
                    // statement-level recovery silently DROPPED it and left
                    // the body unimplemented -- three tri-net specs shipped
                    // wrong generated code with no diagnostic (t27#1940).
                    return Err(format!(
                        "parse error in fn '{}' near line {}: {}",
                        decl.name, self.current.line, e
                    ));
                }
            }
        }
        Ok(())
    }

    /// Skip tokens to recover to next statement boundary (semicolon or closing brace)
    #[allow(dead_code)]
    fn recover_to_stmt_boundary(&mut self) {
        let mut brace_depth: i32 = 0;
        loop {
            // W646: statement-level recovery is the second discard channel.
            // Everything it walks past is a statement the AST never sees.
            // W899: record the span too -- see the note in skip_brace_body.
            if self.current.kind != TokenKind::Eof {
                self.dropped_top_level_tokens += 1;
                if self.dropped_spans.len() < 20000 {
                    self.dropped_spans
                        .push((self.current.line as u32, self.current.lexeme.clone()));
                    self.dropped_channels.push("stmt-recovery");
                }
            }
            match self.current.kind {
                TokenKind::Eof => break,
                TokenKind::Semicolon if brace_depth == 0 => {
                    self.advance();
                    break;
                }
                TokenKind::RBrace if brace_depth == 0 => break,
                TokenKind::LBrace => {
                    brace_depth += 1;
                    self.advance();
                }
                TokenKind::RBrace => {
                    brace_depth -= 1;
                    self.advance();
                }
                _ => {
                    self.advance();
                }
            }
        }
    }

    /// Parse a single statement inside a function body
    fn parse_body_stmt(&mut self) -> Result<Node, String> {
        // `defer <stmt>;` / `errdefer <stmt>;` -- Zig's scope-exit hook. Not
        // keywords in this lexer, so the statement parsed as the expression
        // `defer` and whatever followed became "unexpected token after
        // expression statement".
        //
        // ATTACHED, not skipped -- unlike `inline` below. `inline` is a hint a
        // non-unrolling parser can ignore with nothing lost; a dropped `defer`
        // silently removes a release, a close or a free. The distinction is the
        // same one the `while` continue expression got: skip what carries no
        // meaning, keep what does, and let a backend refuse a marker it does
        // not know rather than emit code missing a step.
        if self.current.kind == TokenKind::Ident
            && (self.current.lexeme == "defer" || self.current.lexeme == "errdefer")
        {
            let name = self.current.lexeme.clone();
            let line = self.current.line as u32;
            self.advance();
            let inner = self.parse_body_stmt()?;
            let mut node = Node::new(NodeKind::StmtExpr);
            node.name = name;
            node.extra_op = "scope_exit".to_string();
            node.line = line;
            node.children.push(inner);
            return Ok(node);
        }

        // `inline for (...)` / `inline while (...)` -- Zig's unroll hint. It is
        // not a keyword in this lexer, so it arrived as an identifier, the
        // statement was parsed as the expression `inline`, and the loop keyword
        // behind it became "unexpected token after expression statement".
        //
        // Skipped, not recorded: `inline` asks the compiler to unroll, and a
        // parser that does not unroll loses nothing by ignoring it. The loop
        // itself is parsed normally, which is the part that carries meaning.
        if self.current.kind == TokenKind::Ident
            && self.current.lexeme == "inline"
            && matches!(self.peek.kind, TokenKind::KwFor | TokenKind::KwWhile)
        {
            self.advance();
        }

        // W914: a Rust-dialect `match` block. The grammar has no match; the
        // frozen parser ATE it through an uncounted channel and called the fn
        // parsed, and this parser hard-errored -- both wrong. Capture the
        // whole block verbatim (brace-aware) into a named statement: read,
        // counted as nothing, executed as nothing.
        if self.current.kind == TokenKind::Ident
            && self.current.lexeme == "match"
            && self.peek.kind != TokenKind::Equals
            && self.peek.kind != TokenKind::Dot
            && self.peek.kind != TokenKind::LParen
        {
            let mut text = String::new();
            let mut depth: i32 = 0;
            let mut seen = false;
            loop {
                if self.current.kind == TokenKind::Eof {
                    break;
                }
                match self.current.kind {
                    TokenKind::LBrace => {
                        depth += 1;
                        seen = true;
                    }
                    TokenKind::RBrace => depth -= 1,
                    _ => {}
                }
                if !text.is_empty() {
                    text.push(' ');
                }
                text.push_str(&self.current.lexeme);
                let done = seen && depth == 0;
                self.advance();
                if done {
                    break;
                }
            }
            let mut stmt = Node::new(NodeKind::StmtExpr);
            stmt.name = "match".to_string();
            stmt.value = text;
            return Ok(stmt);
        }
        // W914: `pub const X = ...` inside a body -- Zig-style local pub decl.
        // `pub` is meaningless at statement scope; eat it and parse what it
        // modifies.
        if self.current.kind == TokenKind::KwPub
            && matches!(self.peek.kind, TokenKind::KwConst | TokenKind::KwVar)
        {
            self.advance();
        }
        // const / var declaration
        if self.current.kind == TokenKind::KwConst || self.current.kind == TokenKind::KwVar {
            // `let (a, b) = expr` is handled by parse_local_decl, which stores the
            // comma-joined pattern in extra_field -- the shape every backend
            // (Zig/C/Verilog/Rust) already lowers. The batch merge of w420-w459
            // routed it to parse_let_destructuring instead, which emits a
            // StmtAssign+ExprArrayLiteral form only the Verilog backend reads,
            // silently breaking tuple destructuring in the other three.
            return self.parse_local_decl();
        }

        // return statement
        if self.current.kind == TokenKind::KwReturn {
            return self.parse_return_statement();
        }

        // if statement
        if self.current.kind == TokenKind::KwIf {
            return self.parse_if_stmt();
        }

        // while statement
        if self.current.kind == TokenKind::KwWhile {
            return self.parse_while_stmt();
        }

        // for statement
        if self.current.kind == TokenKind::KwFor {
            return self.parse_for_stmt();
        }

        // break statement
        if self.current.kind == TokenKind::KwBreak {
            self.advance();
            if self.current.kind == TokenKind::Semicolon {
                self.advance();
            }
            return Ok(Node::new(NodeKind::StmtBreak));
        }

        // continue statement
        if self.current.kind == TokenKind::KwContinue {
            self.advance();
            if self.current.kind == TokenKind::Semicolon {
                self.advance();
            }
            return Ok(Node::new(NodeKind::StmtContinue));
        }

        // W569: `assert <expr>` WITHOUT parentheses, as a statement.
        //
        // The braceless clause form (`then x == 1` / `assert x == 1`) has
        // lowered to `assert(expr)` since W559, but inside a brace body the
        // same spelling was a parse error: `assert` parsed as a bare
        // identifier expression and the following token was left dangling
        // ("unexpected token after expression statement: KwTrue").
        //
        // It appears **3,682 times** across the corpus, and it is why 28 specs
        // -- every IGLA CODER and IGLA RACE spec among them -- carried a stray
        // `}` that truncated them: the brace made the parser stop before
        // reaching the unparsable tail, so the file "parsed" and 16,792 lines
        // were silently discarded.
        // W629: `invariant <expr>;` in STATEMENT position, i.e. inside a
        // `test { ... }` or `fn { ... }` body. `invariant` lexes as a keyword
        // and was only handled at module level (`parse_invariant_block`), so
        // the body form failed with "Unexpected token in expression:
        // KwInvariant" -- 30 of the 182 corpus parse failures, the single
        // largest class.
        //
        // This is not an optional nicety: L4 (TESTABILITY) requires every spec
        // to carry `test`/`invariant`/`bench`, so the constitution mandates a
        // form the parser rejected. Semantically an `invariant` inside a body
        // is an assertion, so it lowers to exactly what `assert <expr>` does
        // below. Same safety contract: any shape this cannot model restores
        // the checkpoint, so a spec that parsed before still parses. See T36.
        if self.current.kind == TokenKind::KwInvariant
            && self.peek.kind != TokenKind::LBrace
            && self.peek.kind != TokenKind::Semicolon
            && self.peek.kind != TokenKind::RBrace
            && self.peek.kind != TokenKind::Eof
        {
            let line = self.current.line as u32;
            let checkpoint = self.save_state();
            self.advance(); // consume `invariant`
            // `invariant name: expr` and `invariant name { ... }` are the
            // module-level block forms; only the bare-expression form belongs
            // here, so a following `:` or `{` means we guessed wrong.
            let named = self.current.kind == TokenKind::Ident
                && (self.peek.kind == TokenKind::Colon || self.peek.kind == TokenKind::LBrace);
            if !named {
                match self.parse_expr() {
                    Ok(cond) => {
                        if self.current.kind == TokenKind::Semicolon {
                            self.advance();
                        }
                        let mut call = Node::new(NodeKind::ExprCall);
                        call.name = "assert".to_string();
                        call.line = line;
                        call.children.push(cond);
                        let mut stmt = Node::new(NodeKind::StmtExpr);
                        stmt.line = line;
                        stmt.children.push(call);
                        return Ok(stmt);
                    }
                    Err(_) => self.restore_state(checkpoint),
                }
            } else {
                self.restore_state(checkpoint);
            }
        }

        if self.current.kind == TokenKind::Ident
            && self.current.lexeme == "assert"
            && self.peek.kind != TokenKind::LParen
            && self.peek.kind != TokenKind::Semicolon
            && self.peek.kind != TokenKind::RBrace
            && self.peek.kind != TokenKind::Eof
            && self.peek.kind != TokenKind::Equals
        {
            let line = self.current.line as u32;
            let checkpoint = self.save_state();
            self.advance(); // consume `assert`
            match self.parse_expr() {
                Ok(cond) => {
                    if self.current.kind == TokenKind::Semicolon {
                        self.advance();
                    }
                    let mut call = Node::new(NodeKind::ExprCall);
                    call.name = "assert".to_string();
                    call.line = line;
                    call.children.push(cond);
                    let mut stmt = Node::new(NodeKind::StmtExpr);
                    stmt.line = line;
                    stmt.children.push(call);
                    return Ok(stmt);
                }
                // Anything this cannot model falls back to the original path,
                // so a spec that parsed before still parses.
                Err(_) => self.restore_state(checkpoint),
            }
        }

        // Expression or assignment
        let expr = self.parse_expr()?;

        // Check for assignment: expr = rhs;
        if self.current.kind == TokenKind::Equals {
            self.advance(); // consume =
            let rhs = self.parse_expr()?;
            if self.current.kind == TokenKind::Semicolon {
                self.advance();
            }
            let mut assign = Node::new(NodeKind::StmtAssign);
            assign.line = self.current.line as u32;
            assign.children.push(expr);
            assign.children.push(rhs);
            return Ok(assign);
        }

        // Check for += assignment
        let compound_op = match self.current.kind {
            TokenKind::PlusEquals => Some("+="),
            TokenKind::MinusEquals => Some("-="),
            TokenKind::StarEquals => Some("*="),
            TokenKind::SlashEquals => Some("/="),
            TokenKind::PercentEquals => Some("%="),
            TokenKind::PipeEquals => Some("|="),
            TokenKind::AmpEquals => Some("&="),
            TokenKind::CaretEquals => Some("^="),
            _ => None,
        };
        if let Some(cop) = compound_op {
            self.advance(); // consume the compound operator
            let rhs = self.parse_expr()?;
            if self.current.kind == TokenKind::Semicolon {
                self.advance();
            }
            let mut assign = Node::new(NodeKind::StmtAssign);
            assign.line = self.current.line as u32;
            assign.extra_op = cop.to_string();
            assign.children.push(expr);
            assign.children.push(rhs);
            return Ok(assign);
        }

        // Bare expression statement. A well-formed bare expression is
        // terminated by a semicolon, or sits as the final expression directly
        // before the block's closing brace (or EOF). Any OTHER token here means
        // the statement did not end where it should -- e.g. `frobnicate x`,
        // where `frobnicate` parses as a bare ident expression and the stray
        // `x` is left dangling. Previously such a leftover token was silently
        // ignored and the bare expression accepted, letting malformed input
        // leak into codegen (the #1110 known-gap characterization). Treat the
        // dangling token as a syntax error so the caller's statement-level
        // recovery (`recover_to_stmt_boundary`) drops the malformed statement,
        // consistent with how other malformed statements are handled.
        match self.current.kind {
            TokenKind::Semicolon => {
                self.advance();
            }
            TokenKind::RBrace | TokenKind::Eof => {
                // Final expression of a block, or end of input: no terminator
                // required.
            }
            _ => {
                return Err(format!(
                    "unexpected token after expression statement: {:?}",
                    self.current.kind
                ));
            }
        }
        let mut stmt = Node::new(NodeKind::StmtExpr);
        stmt.children.push(expr);
        Ok(stmt)
    }

    /// Parse local const/var declaration
    fn parse_local_decl(&mut self) -> Result<Node, String> {
        let mut decl = Node::new(NodeKind::StmtLocal);
        decl.line = self.current.line as u32;
        decl.extra_mutable = self.current.kind == TokenKind::KwVar;
        self.advance(); // consume const/var
        // W914: Rust spelling `let mut name` -- the modifier made the NAME
        // "mut" and the real name junk. Consume it as mutability.
        if self.current.kind == TokenKind::Ident
            && self.current.lexeme == "mut"
            && self.peek.kind == TokenKind::Ident
        {
            decl.extra_mutable = true;
            self.advance();
        }

        // Name, or a tuple-destructuring pattern `(a, b, ...)`.
        // W914: `let var = ...` -- a keyword as the bound NAME (the corpus
        // writes it; `var` is the fifth member of the collision family).
        if self.current.kind == TokenKind::Ident
            || (self.current.kind != TokenKind::LParen
                && !self.current.lexeme.is_empty()
                && self
                    .current
                    .lexeme
                    .chars()
                    .all(|c| c.is_ascii_alphanumeric() || c == '_')
                && matches!(self.peek.kind, TokenKind::Equals | TokenKind::Colon))
        {
            decl.name = self.current.lexeme.clone();
            self.advance();
        } else if self.current.kind == TokenKind::LParen {
            // `let (a, b) = expr` — store the comma-joined pattern in
            // extra_field; name stays empty. Previously `(` was not consumed
            // here, so the binding desynced and emitted `let ;`.
            self.advance(); // consume (
            let mut pat = String::new();
            while self.current.kind != TokenKind::RParen && self.current.kind != TokenKind::Eof {
                match self.current.kind {
                    TokenKind::Comma => pat.push_str(", "),
                    TokenKind::Ident => pat.push_str(&self.current.lexeme),
                    _ => {}
                }
                self.advance();
            }
            if self.current.kind == TokenKind::RParen {
                self.advance(); // consume )
            }
            decl.extra_field = pat; // e.g. "a, b"
        }

        // Optional type annotation: : Type
        if self.current.kind == TokenKind::Colon {
            self.advance(); // consume :
            decl.extra_type = self.parse_type_annotation();
        }

        // = initializer
        if self.current.kind == TokenKind::Equals {
            self.advance(); // consume =
            if matches!(self.current.kind, TokenKind::KwStruct | TokenKind::KwEnum) {
                // W914: a LOCAL type definition -- `pub const T = struct {...}`
                // inside a fn (Zig style). Captured verbatim as the value.
                let mut text = String::new();
                let mut depth: i32 = 0;
                let mut seen = false;
                loop {
                    if self.current.kind == TokenKind::Eof { break; }
                    match self.current.kind {
                        TokenKind::LBrace => { depth += 1; seen = true; }
                        TokenKind::RBrace => depth -= 1,
                        _ => {}
                    }
                    if !text.is_empty() { text.push(' '); }
                    text.push_str(&self.current.lexeme);
                    let done = seen && depth == 0;
                    self.advance();
                    if done { break; }
                }
                let mut init = Node::new(NodeKind::ExprIdentifier);
                init.name = text;
                decl.children.push(init);
            } else {
                let init = self.parse_expr()?;
                decl.children.push(init);
            }
        }

        if self.current.kind == TokenKind::Semicolon {
            self.advance();
        }
        Ok(decl)
    }

    /// Parse `let (a, b, c) = expr;` destructuring.
    /// `let` is lexed as KwConst, so this is reached from `parse_body_stmt` when
    /// KwConst is followed by '('. The result is a StmtAssign whose LHS is an
    /// ExprArrayLiteral marker node (extra_kind == "tuple") containing the
    /// bound identifiers, and whose RHS is the initializer expression.
    fn parse_let_destructuring(&mut self) -> Result<Node, String> {
        let mut assign = Node::new(NodeKind::StmtAssign);
        assign.line = self.current.line as u32;
        self.advance(); // consume let/const

        self.expect(TokenKind::LParen)?;

        let mut lhs = Node::new(NodeKind::ExprArrayLiteral);
        lhs.extra_kind = "tuple".to_string();

        while self.current.kind != TokenKind::RParen
            && self.current.kind != TokenKind::Eof
        {
            if self.current.kind == TokenKind::Ident {
                let mut ident = Node::new(NodeKind::ExprIdentifier);
                ident.name = self.current.lexeme.clone();
                lhs.children.push(ident);
                self.advance();
            } else if self.current.kind == TokenKind::Comma {
                self.advance();
            } else {
                break;
            }
        }
        self.expect(TokenKind::RParen)?;

        self.expect(TokenKind::Equals)?;
        let rhs = self.parse_expr()?;
        if self.current.kind == TokenKind::Semicolon {
            self.advance();
        }

        assign.children.push(lhs);
        assign.children.push(rhs);
        Ok(assign)
    }

    /// Parse return statement
    fn parse_return_statement(&mut self) -> Result<Node, String> {
        let mut stmt = Node::new(NodeKind::ExprReturn);
        // The node carried no line, so every diagnostic about a return printed
        // `:?`. Eleven narrowing warnings landed that way and none of them
        // could be looked up. Captured before `advance()`, which is where the
        // `return` keyword still is.
        stmt.line = self.current.line as u32;
        self.advance(); // consume 'return'

        // Optional return value
        if self.current.kind != TokenKind::Semicolon && self.current.kind != TokenKind::RBrace {
            let expr = self.parse_expr()?;
            stmt.children.push(expr);
        }

        if self.current.kind == TokenKind::Semicolon {
            self.advance();
        }
        Ok(stmt)
    }

    /// Parse if / else if / else statement
    /// The condition of an `if`, a `while`, or an `if` expression.
    ///
    /// `body_follows` says whether a `{` block must come next. It is false for
    /// the `if` EXPRESSION, whose then-branch is an expression: `if (c) a else
    /// b` is legitimate and the paren really does close the condition there.
    /// Rewinding in that context re-read `(c) a` as one expression and killed
    /// six specs -- ops, ternary_add, types, gf16, gfternary, tf3 -- which a
    /// before/after parse of the whole corpus caught and the green test did
    /// not.
    ///
    /// Three byte-identical copies of this stood in the parser and all three
    /// carried the same defect, so the fix lives in one place.
    ///
    /// A leading `(` is NOT proof of the parenthesised form: it may be the
    /// first factor of a bare condition, as in `if (i >> j) & 1 == 1 {`
    /// (specs/ar/asp_solver.t27:154). Reading `(i >> j)` as the whole
    /// condition leaves `& 1 == 1` sitting where the body belongs, and the
    /// enclosing function dies at the brace -- which is how one real spec
    /// stopped parsing while a Lean theorem went on asserting it lowerable.
    ///
    /// The two forms are told apart by what FOLLOWS the closing paren: the
    /// body `{`, or a payload capture `|x|`. Anything else means the
    /// condition continued, so the checkpoint rewinds and the bare path
    /// re-reads it whole. Without parentheses, `Name {` would open the BODY,
    /// so struct-literal parsing is suppressed there.
    fn parse_condition(&mut self, body_follows: bool) -> Result<Node, String> {
        if self.current.kind == TokenKind::LParen {
            let checkpoint = self.save_state();
            self.advance();
            let c = self.parse_expr()?;
            self.expect(TokenKind::RParen)?;
            if !body_follows
                || self.current.kind == TokenKind::LBrace
                || self.current.kind == TokenKind::Pipe
            {
                return Ok(c);
            }
            self.restore_state(checkpoint);
        }
        self.no_struct_literal += 1;
        let c = self.parse_expr();
        self.no_struct_literal -= 1;
        c
    }

    fn parse_if_stmt(&mut self) -> Result<Node, String> {
        let mut if_node = Node::new(NodeKind::StmtIf);
        self.advance(); // consume 'if'

        // Condition, with or without parentheses. 46 specs write the Rust form
        // `if cond { ... }` and it was "Expected LParen, got Ident" -- 1,002
        // assertion clauses (W578). Without parentheses, `Name {` opens the
        // BODY, so struct-literal parsing is suppressed for the condition.
        let cond = self.parse_condition(true)?;
        if_node.children.push(cond);

        // PAYLOAD CAPTURE: `if (opt) |value| { ... }` -- Zig's optional
        // unwrap. The for-loop parser has handled `|x|` since W-something;
        // `if` never learned it, so the `|` was read as bitwise-or, its right
        // operand demanded, and the body brace arrived instead. Stored the
        // same way `for` stores its capture -- in params, not lowered -- so
        // this changes what PARSES and nothing about what is emitted.
        if self.current.kind == TokenKind::Pipe {
            self.advance(); // consume |
            while self.current.kind != TokenKind::Pipe && self.current.kind != TokenKind::Eof {
                if self.current.kind == TokenKind::Star {
                    self.advance(); // pointer capture |*x|
                }
                if self.current.kind == TokenKind::Ident {
                    if_node
                        .params
                        .push((self.current.lexeme.clone(), String::new()));
                }
                self.advance();
            }
            if self.current.kind == TokenKind::Pipe {
                self.advance(); // consume closing |
            }
        }

        // Then branch: { ... }
        if self.current.kind == TokenKind::LBrace {
            self.advance(); // consume {
            let mut then_block = Node::new(NodeKind::Module); // reuse Module as block container
            then_block.name = "then".to_string();
            while self.current.kind != TokenKind::RBrace && self.current.kind != TokenKind::Eof {
                match self.parse_body_stmt() {
                    Ok(s) => then_block.children.push(s),
                    Err(e) => {
                        return Err(format!(
                            "parse error near line {}: {}",
                            self.current.line, e
                        ))
                    }
                }
            }
            self.expect(TokenKind::RBrace)?;
            if_node.children.push(then_block);
        } else {
            // single statement: if (cond) return expr;
            let stmt = self.parse_body_stmt()?;
            let mut then_block = Node::new(NodeKind::Module);
            then_block.name = "then".to_string();
            then_block.children.push(stmt);
            if_node.children.push(then_block);
        }

        // else / else if
        if self.current.kind == TokenKind::KwElse {
            self.advance(); // consume 'else'
            if self.current.kind == TokenKind::KwIf {
                // else if -> recurse
                let else_if = self.parse_if_stmt()?;
                let mut else_block = Node::new(NodeKind::Module);
                else_block.name = "else".to_string();
                else_block.children.push(else_if);
                if_node.children.push(else_block);
            } else if self.current.kind == TokenKind::LBrace {
                self.advance(); // consume {
                let mut else_block = Node::new(NodeKind::Module);
                else_block.name = "else".to_string();
                while self.current.kind != TokenKind::RBrace && self.current.kind != TokenKind::Eof
                {
                    match self.parse_body_stmt() {
                        Ok(s) => else_block.children.push(s),
                        Err(e) => {
                            return Err(format!(
                                "parse error near line {}: {}",
                                self.current.line, e
                            ))
                        }
                    }
                }
                self.expect(TokenKind::RBrace)?;
                if_node.children.push(else_block);
            } else {
                // A BRACELESS else body: `} else` newline `x = 2;`.
                //
                // There was no arm here, so the function consumed `else` and
                // returned. The body was then parsed as the next statement of
                // the ENCLOSING block and ran unconditionally: the emitted
                // output was byte-identical to the same spec with the `else`
                // keyword deleted, in all four backends, and different from
                // the braced form. `pick(20)` returned 2 where the spec says 1.
                //
                // Nothing reported it. `parse-complete`, this project's own
                // silent-truncation detector, prints "nothing discarded" for a
                // file whose `else` has vanished.
                //
                // The then-branch has had this arm all along, twenty lines
                // above -- `// single statement: if (cond) return expr;`. Only
                // the else-branch was missing it.
                let stmt = self.parse_body_stmt()?;
                let mut else_block = Node::new(NodeKind::Module);
                else_block.name = "else".to_string();
                else_block.children.push(stmt);
                if_node.children.push(else_block);
            }
        }

        Ok(if_node)
    }

    /// Parse while statement
    fn parse_while_stmt(&mut self) -> Result<Node, String> {
        let mut while_node = Node::new(NodeKind::StmtWhile);
        self.advance(); // consume 'while'

        // W579: the condition may be parenthesised or not, exactly as for `if`
        // (W578). `while e > 0 {` is the Rust form and 22 specs use it. Without
        // parentheses a `Name {` opens the BODY, so struct-literal parsing is
        // suppressed while reading the condition.
        let cond = self.parse_condition(true)?;
        while_node.children.push(cond);

        // Zig's CONTINUE EXPRESSION: `while (i < n) : (i += 1) { ... }`, the
        // step that runs after every iteration. Without it the `:` arrived
        // where the body brace was expected and the fn died on "Expected
        // LBrace, got Colon".
        //
        // Parsed and attached, not discarded: dropping it would leave a loop
        // whose counter never advances, which is a WORSE outcome than refusing
        // the file -- an infinite loop that compiles is the kind of silence
        // this project keeps finding. Backends that do not know the marker
        // refuse the node; they do not quietly emit a loop missing its step.
        if self.current.kind == TokenKind::Colon {
            self.advance(); // consume :
            let step = if self.current.kind == TokenKind::LParen {
                self.advance();
                let e = self.parse_body_stmt()?;
                if self.current.kind == TokenKind::RParen {
                    self.advance();
                }
                e
            } else {
                self.parse_body_stmt()?
            };
            let mut cont = Node::new(NodeKind::Module);
            cont.name = "continue_expr".to_string();
            cont.children.push(step);
            while_node.children.push(cont);
        }

        // Body: { ... }
        self.expect(TokenKind::LBrace)?;
        let mut body_block = Node::new(NodeKind::Module);
        body_block.name = "body".to_string();
        while self.current.kind != TokenKind::RBrace && self.current.kind != TokenKind::Eof {
            match self.parse_body_stmt() {
                Ok(s) => body_block.children.push(s),
                Err(e) => {
                    return Err(format!(
                        "parse error near line {}: {}",
                        self.current.line, e
                    ))
                }
            }
        }
        self.expect(TokenKind::RBrace)?;
        while_node.children.push(body_block);

        Ok(while_node)
    }

    /// Parse for statement: for (iterable) |capture| { body }
    /// Also: for i in start..end { body }  (range for)
    /// Read an identifier that may carry hyphens: `tritype-base`.
    ///
    /// Module NAMES have accepted this since the module-declaration parser was
    /// written; `use` paths never did. `use tritype-base::Trit;` therefore read
    /// the import as `tritype`, left `-base::Trit` behind as a module-level
    /// expression statement, and that phantom reached gen-verilog as
    /// `-base_Trit;` -- a line the simulator rejects and that no diagnostic
    /// mentions, because from the parser's side nothing went wrong.
    ///
    /// Assumes `self.current` is the leading Ident and consumes it.
    fn read_hyphenated_ident(&mut self) -> String {
        let mut name = String::new();
        if self.current.kind != TokenKind::Ident {
            return name;
        }
        name.push_str(&self.current.lexeme);
        self.advance();
        while self.current.kind == TokenKind::Minus
            && matches!(self.peek.kind, TokenKind::Ident | TokenKind::Number)
        {
            name.push('-');
            self.advance(); // consume '-'
            name.push_str(&self.current.lexeme);
            self.advance();
        }
        name
    }

    fn parse_for_stmt(&mut self) -> Result<Node, String> {
        self.advance(); // consume 'for'

        // Range for: for IDENT in expr..expr { body }
        if self.current.kind == TokenKind::Ident && self.peek.kind == TokenKind::KwIn {
            let ident = self.current.lexeme.clone();
            self.advance(); // consume ident
            self.advance(); // consume 'in'
            return self.parse_for_range(ident, false);
        }

        // PARENTHESISED range for: `for (i in a..b) { body }`. `if (...)` and
        // `while (...)` both accept the parenthesised form; `for` did not, and
        // the diagnostic landed on the `(` as "Expected LBrace, got LParen" --
        // which reads as a missing body rather than a rejected spelling.
        //
        // Checkpointed rather than looked ahead: the parser holds only
        // `current` and `peek`, and Zig's capture form `for (xs) |x| { }`
        // opens with the same `(`. On anything but IDENT + `in` the state is
        // restored and that branch runs unchanged.
        if self.current.kind == TokenKind::LParen {
            let checkpoint = self.save_state();
            self.advance(); // consume '('
            if self.current.kind == TokenKind::Ident && self.peek.kind == TokenKind::KwIn {
                let ident = self.current.lexeme.clone();
                self.advance(); // consume ident
                self.advance(); // consume 'in'
                return self.parse_for_range(ident, true);
            }
            self.restore_state(checkpoint);
        }

        let mut for_node = Node::new(NodeKind::StmtFor);

        // Iterable(s) in parentheses
        self.expect(TokenKind::LParen)?;
        // Parse comma-separated iterables
        while self.current.kind != TokenKind::RParen && self.current.kind != TokenKind::Eof {
            let iter_expr = self.parse_expr()?;
            for_node.children.push(iter_expr);
            if self.current.kind == TokenKind::Comma {
                self.advance();
            }
        }
        self.expect(TokenKind::RParen)?;

        // Capture variables: |x| or |x, y| or |*x| (pointer capture)
        if self.current.kind == TokenKind::Pipe {
            self.advance(); // consume |
            while self.current.kind != TokenKind::Pipe && self.current.kind != TokenKind::Eof {
                // Skip pointer prefix *
                if self.current.kind == TokenKind::Star {
                    self.advance();
                }
                if self.current.kind == TokenKind::Ident {
                    for_node
                        .params
                        .push((self.current.lexeme.clone(), String::new()));
                    self.advance();
                } else if self.current.kind == TokenKind::Comma {
                    self.advance();
                } else {
                    // Skip unknown tokens to prevent infinite loop
                    self.advance();
                }
            }
            self.expect(TokenKind::Pipe)?;
        }

        // Body: { ... }
        self.expect(TokenKind::LBrace)?;
        let mut body_block = Node::new(NodeKind::Module);
        body_block.name = "body".to_string();
        while self.current.kind != TokenKind::RBrace && self.current.kind != TokenKind::Eof {
            match self.parse_body_stmt() {
                Ok(s) => body_block.children.push(s),
                Err(e) => {
                    return Err(format!(
                        "parse error near line {}: {}",
                        self.current.line, e
                    ))
                }
            }
        }
        self.expect(TokenKind::RBrace)?;
        for_node.children.push(body_block);

        Ok(for_node)
    }

    /// Parse range for body: start_expr .. end_expr { body }
    /// `paren` -- the caller consumed a `(` before the loop variable, so the
    /// matching `)` sits immediately before the body brace and must be eaten
    /// on BOTH paths out of this function.
    fn parse_for_range(&mut self, var_name: String, paren: bool) -> Result<Node, String> {
        let mut node = Node::new(NodeKind::StmtForRange);
        node.name = var_name;

        // W734: a range BOUND is not a general expression -- `parse_range_bound`
        // stops at `db` in `db.facts` and the error lands on the dot. A
        // collection needs the full expression grammar, and `..` terminates an
        // expression, so parsing an expression first serves both forms.
        // W914: the loop BODY brace is not a struct literal --
        // `for i in 0..max_iterations {` ate the body as a literal and the
        // whole fn fell. Same suppression as if/while conditions.
        self.no_struct_literal += 1;
        self.no_range += 1;
        let start = self.parse_expr();
        self.no_range -= 1;
        self.no_struct_literal -= 1;
        let start = start?;

        // W733/W734: `for x in a..b` is a RANGE; `for fact in db.facts` is a
        // loop over a COLLECTION, which five specs use and the parser answered
        // with "Expected DotDot, got Dot". The grammar simply lagged its own
        // corpus. When no `..` follows, the bound just parsed IS the iterable,
        // and the node becomes the same StmtFor the parenthesised form builds --
        // one iterable, one capture -- so no backend needs a new shape.
        if self.current.kind != TokenKind::DotDot {
            let mut coll = Node::new(NodeKind::StmtFor);
            coll.children.push(start);
            coll.name = node.name.clone();
            // Captures live in `params`, exactly as the parenthesised
            // `for (xs) |x| { ... }` form stores them.
            coll.params.push((node.name.clone(), String::new()));
            if paren {
                self.expect(TokenKind::RParen)?;
            }
            self.expect(TokenKind::LBrace)?;
            let mut body_block = Node::new(NodeKind::Module);
            body_block.name = "body".to_string();
            while self.current.kind != TokenKind::RBrace && self.current.kind != TokenKind::Eof {
                match self.parse_body_stmt() {
                    Ok(st) => body_block.children.push(st),
                    Err(e) => {
                        return Err(format!(
                            "parse error near line {}: {}",
                            self.current.line, e
                        ))
                    }
                }
            }
            self.expect(TokenKind::RBrace)?;
            coll.children.push(body_block);
            return Ok(coll);
        }

        node.children.push(start);

        self.expect(TokenKind::DotDot)?;

        // `for i in a..=b`. With `no_range` active the chain no longer eats the
        // `..`, so the inclusive `=` arrives here. Lowered to the exclusive
        // range over `b + 1`: every backend lowers `..` already and none would
        // know `..=`.
        let inclusive = self.current.kind == TokenKind::Equals;
        if inclusive {
            self.advance();
        }
        // The END bound is a full expression: `for i in 0..len(s)` is real and
        // `parse_range_bound` is deliberately restricted (it stops at `db` in
        // `db.facts`). Both suppressions apply -- `no_range` so a following
        // `..` is left alone, `no_struct_literal` because the `{` after the
        // bound opens the loop BODY, not a struct literal.
        self.no_struct_literal += 1;
        self.no_range += 1;
        let end = self.parse_expr();
        self.no_range -= 1;
        self.no_struct_literal -= 1;
        let end = end?;
        let end = if inclusive {
            let mut plus = Node::new(NodeKind::ExprBinary);
            plus.extra_op = "+".to_string();
            plus.children.push(end);
            let mut one = Node::new(NodeKind::ExprLiteral);
            one.value = "1".to_string();
            plus.children.push(one);
            plus
        } else {
            end
        };
        node.children.push(end);

        if paren {
            self.expect(TokenKind::RParen)?;
        }
        self.expect(TokenKind::LBrace)?;
        let mut body_block = Node::new(NodeKind::Module);
        body_block.name = "body".to_string();
        while self.current.kind != TokenKind::RBrace && self.current.kind != TokenKind::Eof {
            match self.parse_body_stmt() {
                Ok(s) => body_block.children.push(s),
                Err(e) => {
                    return Err(format!(
                        "parse error near line {}: {}",
                        self.current.line, e
                    ))
                }
            }
        }
        self.expect(TokenKind::RBrace)?;
        node.children.push(body_block);

        Ok(node)
    }

    fn parse_range_bound(&mut self) -> Result<Node, String> {
        match self.current.kind {
            TokenKind::Number => {
                let (val, num_suffix) = split_number_suffix(&self.current.lexeme);
                self.advance();
                Ok(Node {
                    kind: NodeKind::ExprLiteral,
                    value: val,
                    extra_type: num_suffix,
                    ..Default::default()
                })
            }
            TokenKind::Ident => {
                let name = self.current.lexeme.clone();
                self.advance();
                Ok(Node {
                    kind: NodeKind::ExprIdentifier,
                    name,
                    ..Default::default()
                })
            }
            _ => self.parse_expr_additive(),
        }
    }

    // ========================================================================
    // Expression parser (Pratt-style, operates on current token)
    // ========================================================================

    /// Parse a full expression
    fn parse_expr(&mut self) -> Result<Node, String> {
        self.parse_expr_or()
    }

    /// Parse `or` expressions
    fn parse_expr_or(&mut self) -> Result<Node, String> {
        let mut left = self.parse_expr_and()?;
        while self.current.kind == TokenKind::KwOr
            || (self.current.kind == TokenKind::Pipe && self.current.lexeme == "||")
        {
            self.advance();
            let right = self.parse_expr_and()?;
            left = Node {
                kind: NodeKind::ExprBinary,
                extra_op: "or".to_string(),
                children: vec![left, right],
                ..Default::default()
            };
        }
        Ok(left)
    }

    /// Parse `and` expressions
    fn parse_expr_and(&mut self) -> Result<Node, String> {
        let mut left = self.parse_expr_comparison()?;
        while self.current.kind == TokenKind::KwAnd
            || (self.current.kind == TokenKind::Amp && self.current.lexeme == "&&")
        {
            // W898 (0005): `given c = 1` newline `and x = f(c)` -- the greedy
            // and-loop consumed the NEXT CLAUSE as a conjunction, stopped on its
            // `=`, and the whole block fell back. Every mid-block `and` clause in
            // the corpus died this way. In clause-value mode, an `and` followed
            // by `ident =` is the next clause, not an operand: probe ahead with
            // save/restore, which the parser already uses for exactly such looks.
            if self.in_bdd_clause_value && self.current.kind == TokenKind::KwAnd {
                // W901 (0007 v2): the panel folded `given f(0x55)` +
                // `and g(0x66)` into ONE conjunction statement -- the `ident =`
                // look below only catches and-BINDINGS. In the BDD layout a
                // line-leading `and` IS a clause; a genuine operator lives on
                // the line it operates on. Break on newline-`and` too.
                if self.current.line > self.last_line {
                    break;
                }
                let look = self.save_state();
                self.advance();
                let is_clause = self.current.kind == TokenKind::Ident && {
                    let name_ok = true;
                    self.advance();
                    name_ok && self.current.kind == TokenKind::Equals
                };
                self.restore_state(look);
                if is_clause {
                    break;
                }
            }
            self.advance();
            let right = self.parse_expr_comparison()?;
            left = Node {
                kind: NodeKind::ExprBinary,
                extra_op: "and".to_string(),
                children: vec![left, right],
                ..Default::default()
            };
        }
        Ok(left)
    }

    /// Parse comparison expressions (==, !=, <, >, <=, >=)
    fn parse_expr_comparison(&mut self) -> Result<Node, String> {
        let mut left = self.parse_expr_bitor()?;
        // W903: `value in [-1, 0, 1]` / `x in {0, 1, 2}` -- list/set membership.
        // KwIn only ever appeared in for-loop headers, so the clause forms that
        // used it as an OPERATOR dropped their blocks. Same-line only: a `for
        // .. in` never reaches expression position, and a line-leading `in`
        // does not exist in the corpus. The brace-set RHS is parsed here
        // directly ({ is otherwise W578 territory).
        while self.in_bdd_clause_value
            && self.current.kind == TokenKind::KwIn
            && self.current.line == self.last_line
        {
            self.advance();
            let right = if self.current.kind == TokenKind::LBrace {
                let mut set = Node::new(NodeKind::ExprArrayLiteral);
                set.extra_kind = "set".to_string();
                self.advance();
                if self.current.kind != TokenKind::RBrace {
                    set.children.push(self.parse_expr_bitor()?);
                    while self.current.kind == TokenKind::Comma {
                        self.advance();
                        if self.current.kind == TokenKind::RBrace {
                            break;
                        }
                        set.children.push(self.parse_expr_bitor()?);
                    }
                }
                self.expect(TokenKind::RBrace)?;
                set
            } else {
                self.parse_expr_bitor()?
            };
            left = Node {
                kind: NodeKind::ExprBinary,
                extra_op: "in".to_string(),
                children: vec![left, right],
                ..Default::default()
            };
        }
        while matches!(
            self.current.kind,
            TokenKind::Eq
                | TokenKind::Neq
                | TokenKind::Lt
                | TokenKind::Gt
                | TokenKind::Lte
                | TokenKind::Gte
                | TokenKind::DotDot
        ) {
            // `..` is in this chain as a range operator, which makes the
            // OPEN-ENDED slice `x[a..]` unparseable: the operator is consumed,
            // a right operand is demanded, and the `]` arrives instead --
            // reported as "Unexpected token in expression: RBracket" pointing
            // at a bracket that is exactly where it belongs. Leave the `..` for
            // the slice parser when nothing can follow it.
            if self.current.kind == TokenKind::DotDot
                && matches!(self.peek.kind, TokenKind::RBracket | TokenKind::RParen)
            {
                break;
            }
            // A range BOUND must not swallow its own `..`; see `no_range`.
            if self.current.kind == TokenKind::DotDot && self.no_range > 0 {
                break;
            }
            let op = self.current.lexeme.clone();
            self.advance();
            // `a..=b` -- the INCLUSIVE range. The lexer emits `..` and then a
            // separate `=`, so the right operand parser met `=b` and answered
            // "Unexpected token in expression: Equals". 12 specs write this
            // form, one of them specs/math/constants.t27, which 259 of 746
            // specs import.
            //
            // Lowered to the EXCLUSIVE range over `b + 1` rather than carried
            // as a new operator: every backend already lowers `..`, and none
            // would know `..=`. For the integer loops this grammar has the two
            // are the same range, and the alternative is a fifth spelling that
            // four emitters must each be taught.
            let inclusive = op == ".." && self.current.kind == TokenKind::Equals;
            if inclusive {
                self.advance();
            }
            let right = self.parse_expr_bitor()?;
            let right = if inclusive {
                let mut plus = Node::new(NodeKind::ExprBinary);
                plus.extra_op = "+".to_string();
                plus.children.push(right);
                let mut one = Node::new(NodeKind::ExprLiteral);
                one.value = "1".to_string();
                plus.children.push(one);
                plus
            } else {
                right
            };
            left = Node {
                kind: NodeKind::ExprBinary,
                extra_op: op,
                children: vec![left, right],
                ..Default::default()
            };
        }
        Ok(left)
    }

    /// Parse bitwise or (|)
    fn parse_expr_bitor(&mut self) -> Result<Node, String> {
        let mut left = self.parse_expr_bitxor()?;
        while self.current.kind == TokenKind::Pipe && self.current.lexeme == "|" {
            let op = self.current.lexeme.clone();
            self.advance();
            let right = self.parse_expr_bitxor()?;
            left = Node {
                kind: NodeKind::ExprBinary,
                extra_op: op,
                children: vec![left, right],
                ..Default::default()
            };
        }
        Ok(left)
    }

    /// Parse bitwise xor (^)
    fn parse_expr_bitxor(&mut self) -> Result<Node, String> {
        let mut left = self.parse_expr_bitand()?;
        while self.current.kind == TokenKind::Caret {
            let op = self.current.lexeme.clone();
            self.advance();
            let right = self.parse_expr_bitand()?;
            left = Node {
                kind: NodeKind::ExprBinary,
                extra_op: op,
                children: vec![left, right],
                ..Default::default()
            };
        }
        Ok(left)
    }

    /// Parse bitwise and (&)
    fn parse_expr_bitand(&mut self) -> Result<Node, String> {
        let mut left = self.parse_expr_shift()?;
        while self.current.kind == TokenKind::Amp && self.current.lexeme == "&" {
            let op = self.current.lexeme.clone();
            self.advance();
            let right = self.parse_expr_shift()?;
            left = Node {
                kind: NodeKind::ExprBinary,
                extra_op: op,
                children: vec![left, right],
                ..Default::default()
            };
        }
        Ok(left)
    }

    /// Parse shift expressions (<<, >>)
    fn parse_expr_shift(&mut self) -> Result<Node, String> {
        let mut left = self.parse_expr_additive()?;
        while matches!(
            self.current.kind,
            TokenKind::ShiftLeft | TokenKind::ShiftRight
        ) {
            let op = self.current.lexeme.clone();
            self.advance();
            let right = self.parse_expr_additive()?;
            left = Node {
                kind: NodeKind::ExprBinary,
                extra_op: op,
                children: vec![left, right],
                ..Default::default()
            };
        }
        Ok(left)
    }

    /// Parse additive expressions (+, -, +%)
    fn parse_expr_additive(&mut self) -> Result<Node, String> {
        let mut left = self.parse_expr_multiplicative()?;
        while matches!(
            self.current.kind,
            TokenKind::Plus
                | TokenKind::Minus
                | TokenKind::PlusPercent
                | TokenKind::MinusPercent
                // W580: `++` is CONCATENATION here, not increment --
                // `return "SOP(" ++ truth_table ++ ")";`. It lexed as a token
                // and had no grammar rule, so the expression died with
                // "Unexpected token in expression: PlusPlus" (682 assertion
                // clauses across 5 specs). Zig spells concatenation `++` too,
                // so it emits unchanged.
                | TokenKind::PlusPlus
        ) {
            let op = self.current.lexeme.clone();
            self.advance();
            let right = self.parse_expr_multiplicative()?;
            left = Node {
                kind: NodeKind::ExprBinary,
                extra_op: op,
                children: vec![left, right],
                ..Default::default()
            };
        }
        Ok(left)
    }

    /// Parse multiplicative expressions (*, /, %, **, *%)
    fn parse_expr_multiplicative(&mut self) -> Result<Node, String> {
        let mut left = self.parse_expr_unary()?;
        while matches!(
            self.current.kind,
            TokenKind::Star
                | TokenKind::Slash
                | TokenKind::Percent
                | TokenKind::Power
                | TokenKind::StarPercent
        ) {
            let op = self.current.lexeme.clone();
            self.advance();
            let right = self.parse_expr_unary()?;
            left = Node {
                kind: NodeKind::ExprBinary,
                extra_op: op,
                children: vec![left, right],
                ..Default::default()
            };
        }
        Ok(left)
    }

    /// Parse unary expressions (-x, !x, ~x, &x)
    fn parse_expr_unary(&mut self) -> Result<Node, String> {
        if matches!(
            self.current.kind,
            TokenKind::Minus | TokenKind::Bang | TokenKind::Tilde | TokenKind::Amp
        ) {
            let op = self.current.lexeme.clone();
            self.advance();
            let operand = self.parse_expr_unary()?;
            return Ok(Node {
                kind: NodeKind::ExprUnary,
                extra_op: op,
                children: vec![operand],
                ..Default::default()
            });
        }
        let mut expr = self.parse_expr_postfix()?;
        // Cast operator `expr as Type`. `as` is lexed as an identifier (it is not
        // a reserved keyword), so we match on the lexeme. The target type is
        // recorded for diagnostics but the lowering keeps only the inner operand
        // (Verilog/C/Rust backends rely on width inference, not on a textual
        // cast token). Casts left-associate and bind looser than unary/postfix.
        while self.current.kind == TokenKind::Ident && self.current.lexeme == "as" {
            self.advance(); // consume `as`
            let target_type = self.parse_cast_target_type()?;
            let mut cast = Node::new(NodeKind::ExprCast);
            cast.extra_type = target_type;
            cast.children.push(expr);
            expr = cast;
        }
        Ok(expr)
    }

    /// Consume the type that follows an `as` cast, e.g. `u32`, `i8`, or an
    /// array form like `u8[4]`. Returns the textual type for diagnostics.
    /// The base type name is validated against the known scalar type set so
    /// that a typo like `x as u3` or `x as banana` is rejected at parse time
    /// instead of silently lowering to a 32-bit default.
    fn parse_cast_target_type(&mut self) -> Result<String, String> {
        if self.current.kind != TokenKind::Ident {
            return Err(format!(
                "expected a type after `as`, found {:?}",
                self.current.kind
            ));
        }
        let base = self.current.lexeme.clone();
        // f32/f64 are first-class elsewhere in the compiler -- TypeInfo::F32
        // exists, they are accepted as parameter and return types, and the
        // Zig/Rust/C emitters handle them -- but they were missing from this
        // cast whitelist, so `x as f32` was a parse error while `fn f(x: f32)`
        // was fine. That inconsistency blocked three IGLA specs at the parser.
        // W915 MERGE-SEMANTICS NOTE, flagged in docs/NOW.md for the owner:
        // master refuses f32/f64 casts with a truthful message (its C backend
        // emits the literal token); this branch accepted them at W830 and 38
        // corpus specs parse through them. The merge keeps the branch's
        // acceptance (removing it fails 39 specs) and DROPS W914's untracked
        // `float`/`int` aliases; master's refusal branch below stays as the
        // documented owner position for the day a backend decision lands.
        const VALID_CAST_TYPES: &[&str] = &[
            "bool", "u8", "i8", "u16", "i16", "u32", "i32", "u64", "i64", "usize",
            "f32", "f64",
        ];
        if !VALID_CAST_TYPES.contains(&base.as_str()) {
            // f32/f64 parse in DECLARATIONS, so "unknown type" would be a lie here.
            // The truth is narrower: no backend lowers float arithmetic -- the C
            // generator emits the literal token `f32`, which is not a C type, and
            // Verilog treats it as 32 plain bits. A cast that parses and then
            // produces uncompilable C would be worse than this error, which is why
            // f32/f64 are named here rather than added to the list.
            if matches!(base.as_str(), "f32" | "f64") {
                return Err(format!(
                    "cast to `{}` is not supported: the language accepts float \
                     declarations, but no backend lowers float arithmetic (the C \
                     generator emits `{}` verbatim, which is not a C type). This spec \
                     assumes a float-capable target that does not exist yet.",
                    base, base
                ));
            }
            return Err(format!(
                "unknown cast target type `{}`; expected one of {:?}",
                base, VALID_CAST_TYPES
            ));
        }
        let mut ty = base;
        self.advance();
        // Optional array suffix: `[N]`.
        if self.current.kind == TokenKind::LBracket {
            ty.push('[');
            self.advance();
            while self.current.kind != TokenKind::RBracket
                && self.current.kind != TokenKind::Eof
            {
                ty.push_str(&self.current.lexeme);
                self.advance();
            }
            if self.current.kind == TokenKind::RBracket {
                ty.push(']');
                self.advance();
            }
        }
        Ok(ty)
    }

    /// Parse postfix expressions: field access (.field), deref (.*), indexing ([i]), call (f(args))
    fn parse_expr_postfix(&mut self) -> Result<Node, String> {
        let mut expr = self.parse_expr_primary()?;

        loop {
            if self.current.kind == TokenKind::Dot {
                self.advance(); // consume .
                if self.current.kind == TokenKind::Star {
                    // Dereference: expr.*
                    self.advance(); // consume *
                    let mut deref = Node::new(NodeKind::ExprFieldAccess);
                    deref.name = "*".to_string();
                    deref.children.push(expr);
                    expr = deref;
                } else if self.current.kind == TokenKind::Question {
                    // W581: `expr.?` -- Zig's optional unwrap. Now that `?` is
                    // a real token it reaches here; before W581 the lexer
                    // dropped it and `x.?` silently became a field access to
                    // nothing.
                    self.advance(); // consume ?
                    let mut unwrap = Node::new(NodeKind::ExprFieldAccess);
                    unwrap.name = "?".to_string();
                    unwrap.children.push(expr);
                    expr = unwrap;
                } else if self.current.kind == TokenKind::Number {
                    // Tuple index access: expr.0 / expr.1 -- previously the dot
                    // was consumed and the index token silently DROPPED, so
                    // `two().0` parsed as `two()` (wrong value, no diagnostic).
                    let mut fa = Node::new(NodeKind::ExprFieldAccess);
                    fa.name = self.current.lexeme.clone();
                    self.advance();
                    fa.children.push(expr);
                    expr = fa;
                } else if self.current.kind == TokenKind::Ident
                    || Self::is_identifier_like(&self.current)
                {
                    // W580: a KEYWORD used as a field name. `contract.invariant`
                    // lexes `invariant` as KwInvariant, so the postfix loop saw
                    // no identifier and the expression died with "Unexpected
                    // token in expression: KwInvariant" -- 307 assertion
                    // clauses across 31 specs. After a `.` the token is a field
                    // name whatever else it might mean; the backends already
                    // escape a field that collides with a target keyword.
                    let field = self.current.lexeme.clone();
                    self.advance();
                    // Check if this is a method/field call: expr.field(args)
                    if self.current.kind == TokenKind::LParen {
                        // Method-style call: expr.field(args).
                        //
                        // The name-flattening path walks a chain of identifiers
                        // and field accesses. When the receiver is something
                        // else -- a CALL or an INDEX -- it used to stop and
                        // SILENTLY DROP it, so
                        // `ternary_gemm(a, w).len()` parsed as `len()`: no
                        // receiver, no diagnostic. 198 no-argument method calls
                        // and ~40 with arguments sit on such receivers in this
                        // corpus. Keep the receiver as a child instead.
                        if Self::is_flattenable_receiver(&expr) {
                            let full_name = Self::flatten_field_access_name(&expr, &field);
                            let call = self.parse_call_args(full_name)?;
                            expr = call;
                        } else {
                            let mut call = self.parse_call_args(field)?;
                            call.extra_kind = "method".to_string();
                            call.children.insert(0, expr);
                            expr = call;
                        }
                    } else {
                        let mut fa = Node::new(NodeKind::ExprFieldAccess);
                        fa.name = field;
                        fa.children.push(expr);
                        expr = fa;
                    }
                } else {
                    break;
                }
            } else if self.current.kind == TokenKind::Question {
                // Rust's error-propagation postfix, `f()?`. Zig spells the same
                // thing `try f()`, and the parser already has that node shape.
                self.advance();
                let mut t = Node::new(NodeKind::ExprUnary);
                t.extra_op = "try ".to_string();
                t.children.push(expr);
                expr = t;
            } else if self.current.kind == TokenKind::LBracket {
                self.advance(); // consume [
                let index = self.parse_expr()?;
                // W605: `x[a:b]` -- a slice. 33 sites in code across five
                // specs, every one of them in IGLA CODER, and it is what
                // `eval.t27` fails on at line 1394 (`stdout[0:5]`). Zig spells
                // it `x[a..b]`, so the only difference is the separator.
                //
                // The corpus ALSO contains 78 `[7:0]` bit-ranges -- Verilog,
                // inside string literals -- which are not slices and are not
                // reached here, because a string literal is one token.
                // Zig spells the same slice `x[a..b]`, and also has an
                // OPEN-ENDED form `x[a..]` with no end index -- which is what
                // `for (ident[1..]) |c|` uses in the lexer's own spec. Without
                // it the `..` was consumed as a binary operator, the end
                // operand was demanded, and the parser reported "Unexpected
                // token in expression: RBracket" pointing at the `]`.
                //
                // The open form gets its own marker rather than a synthesised
                // end. A backend that has never heard of it then refuses on a
                // node it does not recognise, instead of lowering a bounded
                // slice whose bound nobody wrote.
                if self.current.kind == TokenKind::Colon
                    || self.current.kind == TokenKind::DotDot
                {
                    self.advance(); // consume : or ..
                    let open = self.current.kind == TokenKind::RBracket;
                    let end = if open { None } else { Some(self.parse_expr()?) };
                    self.expect(TokenKind::RBracket)?;
                    let mut slice_node = Node::new(NodeKind::ExprIndex);
                    slice_node.extra_op =
                        if open { "slice_open" } else { "slice" }.to_string();
                    slice_node.children.push(expr);
                    slice_node.children.push(index);
                    if let Some(e) = end {
                        slice_node.children.push(e);
                    }
                    expr = slice_node;
                    continue;
                }
                self.expect(TokenKind::RBracket)?;
                let mut idx_node = Node::new(NodeKind::ExprIndex);
                idx_node.children.push(expr);
                idx_node.children.push(index);
                expr = idx_node;
            } else if self.current.kind == TokenKind::LBrace
                && self.no_struct_literal == 0
                && expr.kind == NodeKind::ExprCall
            {
                // `Type(args){}` -- a call that RETURNS a type, initialised on
                // the spot: `GeneralPurposeAllocator(.{}){}`. The call itself is
                // built in primary, so this has to live in the postfix chain to
                // see it; putting it beside the expression-call branch missed,
                // because `ident(...)` never reaches that branch.
                //
                // Two guards, both load-bearing. `no_struct_literal` is the
                // same counter that stops `if cond {` being read as a struct
                // literal -- inside a paren-less condition this brace opens the
                // BODY. And the left side must already BE a call: a bare
                // `name {` is a struct literal or a block and is not this.
                let mut init = String::new();
                let mut depth = 0i32;
                let mut seen = false;
                while self.current.kind != TokenKind::Eof {
                    match self.current.kind {
                        TokenKind::LBrace => {
                            depth += 1;
                            seen = true;
                        }
                        TokenKind::RBrace => depth -= 1,
                        _ => {}
                    }
                    if !init.is_empty() {
                        init.push(' ');
                    }
                    init.push_str(&self.current.lexeme);
                    self.advance();
                    if seen && depth == 0 {
                        break;
                    }
                }
                expr.value = init;
            } else if self.current.kind == TokenKind::LParen {
                // A call on an ARBITRARY expression. The comment this replaces
                // said it "shouldn't normally happen", and `func.?(a, b)` in
                // specs/jit/jit.t27 is exactly it: the optional is unwrapped by
                // the branch above, and the call on the result arrived here and
                // was left unconsumed -- so the statement parser met a bare
                // `(` and reported "unexpected token after expression
                // statement: LParen", pointing past the construct rather than
                // at it.
                self.advance(); // consume (
                let mut call = Node::new(NodeKind::ExprCall);
                call.children.push(expr);
                call.extra_op = "callee_expr".to_string();
                while self.current.kind != TokenKind::RParen
                    && self.current.kind != TokenKind::Eof
                {
                    call.children.push(self.parse_expr()?);
                    if self.current.kind == TokenKind::Comma {
                        self.advance();
                    }
                }
                self.expect(TokenKind::RParen)?;
                expr = call;
            } else {
                break;
            }
        }

        Ok(expr)
    }

    /// Flatten a chain of ExprFieldAccess nodes into a dotted name
    /// e.g. ExprFieldAccess("expectEqual", ExprFieldAccess("testing", ExprIdentifier("std")))
    /// becomes "std.testing.expectEqual"
    /// A token whose lexeme reads as an identifier -- true for every keyword.
    /// Used where the grammar guarantees a name, such as immediately after `.`.
    fn is_identifier_like(t: &Token) -> bool {
        let mut cs = t.lexeme.chars();
        match cs.next() {
            Some(c) if c.is_ascii_alphabetic() || c == '_' => {
                cs.all(|c| c.is_ascii_alphanumeric() || c == '_')
            }
            _ => false,
        }
    }

    /// Whether a receiver is a pure chain of identifiers and field accesses,
    /// and can therefore be folded into a dotted callee NAME without losing
    /// anything. A call or an index in the chain cannot.
    fn is_flattenable_receiver(expr: &Node) -> bool {
        let mut current = expr;
        loop {
            match current.kind {
                NodeKind::ExprIdentifier => return true,
                NodeKind::ExprFieldAccess => {
                    if current.children.is_empty() {
                        return true;
                    }
                    current = &current.children[0];
                }
                _ => return false,
            }
        }
    }

    fn flatten_field_access_name(expr: &Node, trailing_field: &str) -> String {
        let mut parts = vec![trailing_field.to_string()];
        let mut current = expr;
        loop {
            match current.kind {
                NodeKind::ExprFieldAccess => {
                    parts.push(current.name.clone());
                    if !current.children.is_empty() {
                        current = &current.children[0];
                    } else {
                        break;
                    }
                }
                NodeKind::ExprIdentifier => {
                    parts.push(current.name.clone());
                    break;
                }
                _ => break,
            }
        }
        parts.reverse();
        parts.join(".")
    }

    /// Parse primary expressions
    fn parse_expr_primary(&mut self) -> Result<Node, String> {
        // W906 (0013): `var` as a NAME inside clause values -- the binding
        // `given var = 5` lowers, but `then var == 5` died on KwVar in operand
        // position. In clause-value mode only, a var/const keyword NOT opening
        // a declaration (no `Ident =`/`Ident :` after it) reads as an
        // identifier.
        // W907 (0014): inline lambda in clause values -- `fn(x) x >= 0.0` as
        // a call argument in a then-clause felled its whole block (convicted
        // by replacing it with a named predicate). Represented WITHOUT a new
        // node kind: ExprCall named "fn", parameters joined in extra_field,
        // single-expression body as the only child -- backends that meet it
        // see an ordinary call node.
        if self.in_bdd_clause_value
            && self.current.kind == TokenKind::KwFn
            && self.peek.kind == TokenKind::LParen
        {
            self.advance(); // fn
            self.advance(); // (
            let mut params: Vec<String> = Vec::new();
            while self.current.kind == TokenKind::Ident {
                params.push(self.current.lexeme.clone());
                self.advance();
                if self.current.kind == TokenKind::Comma {
                    self.advance();
                }
            }
            self.expect(TokenKind::RParen)?;
            let body = self.parse_expr()?;
            let mut node = Node::new(NodeKind::ExprCall);
            node.name = "fn".to_string();
            node.extra_field = params.join(", ");
            node.children.push(body);
            return Ok(node);
        }
        if matches!(
            self.current.kind,
            TokenKind::KwVar | TokenKind::KwConst | TokenKind::KwModule
        ) && !(self.peek.kind == TokenKind::Ident)
        {
            // W914: fall THROUGH as an identifier -- the Ident arm below owns
            // calls/fields/indexing, and an early return here stranded
            // `module(name).exists` at its `(`.
            self.current.kind = TokenKind::Ident;
        }
        match self.current.kind {
            // Number literal
            TokenKind::Number => {
                let (val, num_suffix) = split_number_suffix(&self.current.lexeme);
                self.advance();
                Ok(Node {
                    kind: NodeKind::ExprLiteral,
                    value: val,
                    extra_type: num_suffix,
                    ..Default::default()
                })
            }

            // Character literal
            TokenKind::CharLiteral => {
                let val = self.current.lexeme.clone();
                self.advance();
                Ok(Node {
                    kind: NodeKind::ExprLiteral,
                    value: format!("'{}'", val),
                    ..Default::default()
                })
            }

            // String literal
            TokenKind::String => {
                let val = self.current.lexeme.clone();
                self.advance();
                Ok(Node {
                    kind: NodeKind::ExprLiteral,
                    value: val,
                    extra_kind: "string".to_string(),
                    ..Default::default()
                })
            }

            // W577: an unterminated literal carries the rest of the file as its
            // lexeme. Accepting it as a value is how `const S = "oops` absorbed
            // every declaration after it and still reported success.
            TokenKind::UnterminatedString => Err(format!(
                "unterminated string literal opened at line {}:{}",
                self.current.line, self.current.col
            )),

            // Boolean literals
            TokenKind::KwTrue => {
                self.advance();
                Ok(Node {
                    kind: NodeKind::ExprLiteral,
                    value: "true".to_string(),
                    ..Default::default()
                })
            }
            TokenKind::KwFalse => {
                self.advance();
                Ok(Node {
                    kind: NodeKind::ExprLiteral,
                    value: "false".to_string(),
                    ..Default::default()
                })
            }

            // Enum value: .variant
            TokenKind::Dot => {
                self.advance(); // consume .
                if self.current.kind == TokenKind::LBrace {
                    return self.parse_anon_braced();
                }
                // An enum-value shorthand whose name is a KEYWORD: `.use`,
                // `.const`, `.data`. The lexer classifies those as keywords,
                // so requiring Ident here rejected them -- and a language
                // whose own token names are keywords will keep producing this.
                // Same predicate the struct-literal parser already uses for a
                // keyword FIELD LABEL (W906): any word-shaped token in a
                // position where only a name can appear is a name.
                let word_shaped = !self.current.lexeme.is_empty()
                    && self
                        .current
                        .lexeme
                        .chars()
                        .all(|c| c.is_ascii_alphanumeric() || c == '_');
                if self.current.kind == TokenKind::Ident || word_shaped {
                    let name = self.current.lexeme.clone();
                    self.advance();
                    Ok(Node {
                        kind: NodeKind::ExprEnumValue,
                        name,
                        ..Default::default()
                    })
                } else {
                    Err(format!(
                        "Expected identifier after '.', got {:?}",
                        self.current.kind
                    ))
                }
            }

            // Identifier, function call, @builtin call, or struct literal
            TokenKind::Ident => {
                let mut name = self.current.lexeme.clone();
                self.advance();

                // Handle namespace-qualified names: lexer::next_token
                while self.current.kind == TokenKind::Colon {
                    // Check for :: (two colons)
                    if self.peek.kind == TokenKind::Colon {
                        name.push_str("::");
                        self.advance(); // consume first :
                        self.advance(); // consume second :
                        if self.current.kind == TokenKind::Ident {
                            name.push_str(&self.current.lexeme);
                            self.advance();
                        }
                    } else {
                        break;
                    }
                }

                // Check for struct literal: Name{ .field = expr, ... }
                if self.current.kind == TokenKind::LBrace && self.no_struct_literal == 0 {
                    return self.parse_struct_literal(name);
                }

                // Check for function call: name(args) or namespace::func(args)
                if self.current.kind == TokenKind::LParen {
                    return self.parse_call_args(name);
                }

                Ok(Node {
                    kind: NodeKind::ExprIdentifier,
                    name,
                    ..Default::default()
                })
            }

            // Parenthesized expression or tuple literal
            TokenKind::LParen => {
                self.advance(); // consume (
                let inner = self.parse_expr()?;
                if self.current.kind == TokenKind::Comma {
                    // Tuple literal `(e0, e1, ...)`. Without this the parser
                    // errored on the comma and the enclosing expression (e.g. a
                    // tuple `return`) was dropped.
                    let mut elems = vec![inner];
                    while self.current.kind == TokenKind::Comma {
                        self.advance(); // consume ,
                        if self.current.kind == TokenKind::RParen {
                            break; // trailing comma
                        }
                        elems.push(self.parse_expr()?);
                    }
                    self.expect(TokenKind::RParen)?;
                    Ok(Node {
                        kind: NodeKind::ExprTuple,
                        children: elems,
                        ..Default::default()
                    })
                } else {
                    self.expect(TokenKind::RParen)?;
                    Ok(inner)
                }
            }

            // if expression: if (cond) expr else expr
            TokenKind::KwIf => self.parse_if_expr(),

            // switch expression: switch (val) { ... }
            TokenKind::KwSwitch => self.parse_switch_expr(),

            // try expression (skip 'try' and parse inner)
            TokenKind::KwTry => {
                self.advance(); // consume 'try'
                let inner = self.parse_expr_postfix()?;
                Ok(Node {
                    kind: NodeKind::ExprUnary,
                    extra_op: "try ".to_string(),
                    children: vec![inner],
                    ..Default::default()
                })
            }

            // Array literal: [_]Type{ values } or [N]Type{ values }.
            // A BARE list (`[a, b, c]`) is tried first: `parse_array_literal`
            // captures its elements as raw TEXT, so a struct-literal element
            // reached the backend unlowered -- `TernaryWeight{code:0}` instead
            // of `TernaryWeight{ .code = 0 }`. Parsing the elements as
            // expressions lowers them like any other.
            TokenKind::LBracket => {
                let save = self.save_state();
                if let Some(bare) = self.parse_bare_array_literal() {
                    Ok(bare)
                } else {
                    self.restore_state(save);
                    self.parse_array_literal()
                }
            }

            _ => Err(format!(
                "Unexpected token in expression: {:?} ('{}') at line {}:{}",
                self.current.kind, self.current.lexeme, self.current.line, self.current.col
            )),
        }
    }

    /// Parse function/builtin call arguments: name(arg1, arg2, ...)
    fn parse_call_args(&mut self, name: String) -> Result<Node, String> {
        // W574: call nodes carried no line, so a diagnostic about a call site
        // could only say which FILE it was in.
        let line = self.current.line as u32;
        self.advance(); // consume (
        let mut call = Node::new(NodeKind::ExprCall);
        call.name = name;
        call.line = line;

        while self.current.kind != TokenKind::RParen && self.current.kind != TokenKind::Eof {
            let arg = self.parse_expr()?;
            call.children.push(arg);
            if self.current.kind == TokenKind::Comma {
                self.advance();
            }
        }
        self.expect(TokenKind::RParen)?;
        Ok(call)
    }

    /// Parse the anonymous braced literal `.{ ... }` -- Zig's anonymous struct
    /// and its tuple, which share one spelling:
    ///
    /// ```text
    /// .{}                       empty
    /// .{ a, b }                 positional tuple
    /// .{ .field = a, ... }      named anonymous struct
    /// ```
    ///
    /// Primary-expression position understood `.Variant` and nothing else, so
    /// every spec using this form died at its first occurrence: seven of them,
    /// including the lexer's own `return .{ value, buf[0..i] }`. They had been
    /// failing on master since 9 August without anything reporting it, because
    /// the compile-debt ledger that would have named them was measured on a
    /// branch whose compiler predated the change that broke them.
    ///
    /// The two shapes are separated by the token after `{`. A named field opens
    /// with `.`, and a positional element cannot -- except for a bare enum
    /// value, `.{ .Variant, x }`, where the two are genuinely ambiguous at two
    /// tokens of lookahead and this parser has no third and no backtracking.
    /// That shape is therefore read as a struct literal and rejected by the
    /// closing `expect(RBrace)` with a parse error naming the position. Loud is
    /// the requirement here: a silently wrong parse of a literal would emit
    /// wrong code for every backend, which is worse than not compiling.
    fn parse_anon_braced(&mut self) -> Result<Node, String> {
        // Positioned on `{`; `peek` is the first token inside it.
        if self.peek.kind == TokenKind::Dot {
            // `parse_struct_literal` consumes the brace itself and handles the
            // `.field = expr` loop. An empty name is what makes it anonymous --
            // the Zig emitter writes the leading `.` when the name is empty.
            return self.parse_struct_literal(String::new());
        }
        self.advance(); // consume {
        let mut tup = Node::new(NodeKind::ExprTuple);
        while self.current.kind != TokenKind::RBrace && self.current.kind != TokenKind::Eof {
            tup.children.push(self.parse_expr()?);
            if self.current.kind == TokenKind::Comma {
                self.advance();
            }
        }
        self.expect(TokenKind::RBrace)?;
        Ok(tup)
    }

    /// Parse struct literal: Name{ .field = expr, ... }
    fn parse_struct_literal(&mut self, name: String) -> Result<Node, String> {
        self.advance(); // consume {
        let mut lit = Node::new(NodeKind::ExprStructLit);
        lit.name = name;

        while self.current.kind != TokenKind::RBrace && self.current.kind != TokenKind::Eof {
            // Expect .field = expr  OR  field = expr (dot-prefix optional)
            let field_name;
            if self.current.kind == TokenKind::Dot {
                self.advance(); // consume .
                field_name = if self.current.kind == TokenKind::Ident {
                    let n = self.current.lexeme.clone();
                    self.advance();
                    n
                } else {
                    String::new()
                };
            } else if self.current.kind == TokenKind::Ident
                || (self.current.lexeme.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
                    && !self.current.lexeme.is_empty()
                    && (self.peek.kind == TokenKind::Equals || self.peek.kind == TokenKind::Colon))
            {
                // Allow field = expr without dot prefix.
                // W906 (0013): a KEYWORD as a field label -- `Contract { ...,
                // invariant: "..." }` -- broke out of this loop and the whole
                // block fell. Any word-shaped token followed by `=`/`:` is a
                // field label here; `invariant` the keyword never appears in
                // that position otherwise.
                let n = self.current.lexeme.clone();
                if self.peek.kind == TokenKind::Equals || self.peek.kind == TokenKind::Colon {
                    field_name = n;
                    self.advance(); // consume field name
                } else {
                    break;
                }
            } else {
                break;
            }

            if self.current.kind == TokenKind::Equals || self.current.kind == TokenKind::Colon {
                self.advance(); // consume = or :
            }

            let val = self.parse_expr()?;
            let mut field = Node::new(NodeKind::ExprFieldAccess);
            field.name = field_name;
            field.children.push(val);
            lit.children.push(field);

            if self.current.kind == TokenKind::Comma {
                self.advance();
            }
        }
        self.expect(TokenKind::RBrace)?;
        Ok(lit)
    }

    /// W568: parse a BARE bracketed element list -- `[1, 2, 3]`, the spelling
    /// 11 specs use for a typed const initializer:
    ///
    /// ```text
    /// const COPTIC_ALPHABET : [27]u32 = [0x03B1, 0x03B2, ...]
    /// ```
    ///
    /// `parse_array_literal` only understands `[N]T{ ... }`, so this shape
    /// produced a childless node and the caller's text fallback ran to the next
    /// semicolon -- which, in a newline-terminated language, is end of file.
    ///
    /// Returns `None` for everything else, leaving it to the caller's
    /// checkpoint: the slice type `[]T`, the dimension `[N]`, the type alias
    /// `[N]T`, and the literal form `[N]T{ ... }` all bail out here.
    fn parse_bare_array_literal(&mut self) -> Option<Node> {
        if self.current.kind != TokenKind::LBracket {
            return None;
        }

        // Cheap structural rejection BEFORE any scanning. A bare list needs at
        // least two elements, so `[` followed by one token and then `]` is a
        // dimension (`[5]Pt`, `[_]u8`) and cannot be one.
        //
        // This guard is what keeps the pass linear. Without it, every level of
        // `[5][2][2]...Pt{...}` scanned its entire subtree into a String before
        // rejecting it, and the corpus's 16-deep benchmark specs went from
        // seconds to minutes.
        if self.peek.kind == TokenKind::RBracket {
            return None;
        }

        // Collect the element TEXT. The Zig emitter reads children, but the
        // Verilog emitter reads `extra_size`, and returning a node with
        // children alone made it print an empty element list where it used to
        // print `[c00,c01,c10,c11]`. Both representations are populated.
        let entry = self.save_state();
        let raw_elements = {
            self.advance(); // consume [
            let mut text = String::new();
            let mut depth = 0i32;
            while !(self.current.kind == TokenKind::RBracket && depth == 0)
                && self.current.kind != TokenKind::Eof
            {
                match self.current.kind {
                    TokenKind::LBracket => depth += 1,
                    TokenKind::RBracket => depth -= 1,
                    _ => {}
                }
                text.push_str(&self.current.lexeme);
                self.advance();
            }
            text
        };
        self.restore_state(entry);

        self.advance(); // consume [
        if self.current.kind == TokenKind::RBracket {
            return None; // `[]T` -- a slice type, not a list
        }

        let mut node = Node::new(NodeKind::ExprArrayLiteral);
        node.extra_size = raw_elements.trim().trim_end_matches(',').to_string();
        loop {
            node.children.push(self.parse_expr().ok()?);
            if self.current.kind != TokenKind::Comma {
                break;
            }
            self.advance(); // consume ,
            if self.current.kind == TokenKind::RBracket {
                break; // trailing comma
            }
        }
        if self.current.kind != TokenKind::RBracket {
            return None;
        }
        let close_line = self.current.line;
        self.advance(); // consume ]

        // A type name or another dimension after the bracket means this was
        // `[N]T` / `[N][M]T`, not a list of values -- but only when it is on
        // the SAME LINE as the closing bracket. Without that test, a clause
        // like
        //
        //     given a = [1, 2, 3]
        //     then a.len() == 3
        //
        // saw the `then` on the next line as a type name, rejected the literal,
        // and the whole test block fell back to being discarded.
        if self.current.line == close_line
            && matches!(self.current.kind, TokenKind::Ident | TokenKind::LBracket)
        {
            return None;
        }
        // A single element is normally indistinguishable from an array
        // DIMENSION (`[SIZE]`, `[4]`), so it is left to the existing path --
        // unless the element is plainly not one. `[cast_i8(42)]` is a list;
        // without this, its contents stayed raw TEXT and the calls inside were
        // never lowered ("use of undeclared identifier 'cast_i8'" from inside
        // an emitted `.{ cast_i8(42) }`).
        if node.children.len() < 2 {
            let sole_is_a_dimension = node
                .children
                .first()
                .map(|c| {
                    matches!(
                        c.kind,
                        NodeKind::ExprLiteral | NodeKind::ExprIdentifier
                    )
                })
                .unwrap_or(true);
            if sole_is_a_dimension {
                return None;
            }
        }
        Some(node)
    }

    /// Parse array literal: [_]Type{ values }, [N]Type{ values }, or
    /// [N][M]Type{ values } (multi-dimensional). W527: consumes all leading
    /// bracket dimensions and the element type before the brace.
    fn parse_array_literal(&mut self) -> Result<Node, String> {
        let mut node = Node::new(NodeKind::ExprArrayLiteral);
        self.advance(); // consume first '['

        let mut dims: Vec<String> = Vec::new();
        let mut rbracket_line = self.current.line;
        loop {
            // Collect the contents of the current bracket pair.
            if self.current.kind == TokenKind::RBracket {
                dims.push(String::new());
                rbracket_line = self.current.line;
                self.advance();
            } else {
                let mut bracket_content = String::new();
                // Depth-count nested brackets: an element like `array[1]`
                // used to cut the capture at ITS closing bracket, truncating
                // the literal's element text (t27#1940).
                let mut depth: i32 = 0;
                while !(self.current.kind == TokenKind::RBracket && depth == 0)
                    && self.current.kind != TokenKind::Eof
                {
                    match self.current.kind {
                        TokenKind::LBracket => depth += 1,
                        TokenKind::RBracket => depth -= 1,
                        _ => {}
                    }
                    bracket_content.push_str(&self.current.lexeme);
                    self.advance();
                }
                dims.push(bracket_content.trim().to_string());
                rbracket_line = self.current.line;
                self.expect(TokenKind::RBracket)?;
            }
            // Another leading bracket -> multi-dimensional literal.
            if self.current.kind == TokenKind::LBracket {
                self.advance(); // consume next '['
            } else {
                break;
            }
        }
        node.extra_size = dims.join("][");

        // W900 (0006): an Ident here was consumed as the element type
        // UNCONDITIONALLY, so `given params = [1.0]` followed by
        // `when result = ...` ate the clause keyword `when` as a "type" and
        // the whole block fell back. The Zig typed form is only real when an
        // initialiser brace follows -- `[3]u8{1, 2, 3}`, `[]T{}` -- so look
        // one token past the Ident and take it as a type ONLY then. (`and`
        // clauses survived this all along because KwAnd is not an Ident --
        // which is why 0005's fix made the bug look like a struct-literal
        // problem one clause earlier.)
        // W900 panel: in clause-value mode a clause KEYWORD is never an
        // element type, on either line. Without this, `given xs = [1] then
        // {1} == xs` forged the brace test -- `then` became the "type",
        // `{1}` its initialiser, and the assertion vanished under a green
        // "nothing discarded"; the same-line arm ate one-line
        // `given xs = [1, 2] then ...` pairs the same way.
        let clause_kw = self.in_bdd_clause_value
            && matches!(
                self.current.lexeme.as_str(),
                "given" | "when" | "then" | "assert" | "and"
            );
        if self.current.kind == TokenKind::Ident && !clause_kw {
            // Same line as the `]`: the legacy reading stands -- the corpus
            // holds same-line shapes (`[_]provider-schema::ToolCall{}`) whose
            // parse, however odd, predates this rung. A DIFFERENT line means
            // the Ident is the next clause's keyword unless an initialiser
            // brace proves otherwise.
            if self.current.line == rbracket_line {
                node.extra_type = self.current.lexeme.clone();
                self.advance();
            } else {
                let look = self.save_state();
                let ty = self.current.lexeme.clone();
                self.advance();
                if self.current.kind == TokenKind::LBrace {
                    node.extra_type = ty;
                } else {
                    self.restore_state(look);
                }
            }
        }

        if self.current.kind == TokenKind::LBrace {
            self.advance();
            if self.current.kind != TokenKind::RBrace {
                let elem = self.parse_expr()?;
                node.children.push(elem);
                while self.current.kind == TokenKind::Comma {
                    self.advance();
                    if self.current.kind == TokenKind::RBrace {
                        break;
                    }
                    let elem = self.parse_expr()?;
                    node.children.push(elem);
                }
            }
            self.expect(TokenKind::RBrace)?;
        }

        if self.current.kind == TokenKind::Power {
            self.advance();
            let count = self.parse_expr()?;
            let mut repeat_node = Node::new(NodeKind::ExprBinary);
            repeat_node.extra_op = "**".to_string();
            repeat_node.children.push(node);
            repeat_node.children.push(count);
            return Ok(repeat_node);
        }

        Ok(node)
    }

    /// A branch of an `if` used as an EXPRESSION.
    ///
    /// W578: the corpus writes the branches braced --
    /// `let x = if (c) { a } else { b };` -- and `parse_expr` has no rule for a
    /// `{` in expression position, so this was
    /// "Unexpected token in expression: LBrace". It is the largest single class
    /// of parse failure in the corpus: **29 specs, 4,465 assertion clauses**,
    /// measured in W549 and untouched since.
    ///
    /// A brace holding exactly ONE expression is that expression; Zig spells
    /// the same thing `if (c) a else b`. Anything else -- statements, several
    /// expressions, an empty block -- restores the checkpoint and falls back to
    /// the original path, so a shape this cannot model still parses the way it
    /// did before.
    fn parse_branch_value(&mut self) -> Result<Node, String> {
        if self.current.kind != TokenKind::LBrace {
            return self.parse_expr();
        }
        let checkpoint = self.save_state();
        self.advance(); // consume {
        if self.current.kind == TokenKind::RBrace {
            self.restore_state(checkpoint);
            return self.parse_expr();
        }
        match self.parse_expr() {
            Ok(inner) if self.current.kind == TokenKind::RBrace => {
                self.advance(); // consume }
                Ok(inner)
            }
            _ => {
                self.restore_state(checkpoint);
                self.parse_expr()
            }
        }
    }

    fn parse_if_expr(&mut self) -> Result<Node, String> {
        self.advance(); // consume 'if'

        // Condition, with or without parentheses -- the same rule
        // `parse_if_stmt` was given in W578, applied to expression position,
        // which was left behind. 14 specs still failed with the identical
        // "Expected LParen, got Ident" the comment up there says was fixed,
        // so a reader who greps that diagnostic finds a note claiming the
        // opposite of what the code does.
        //
        // Without parentheses, `Name {` opens the THEN branch, so
        // struct-literal parsing is suppressed for the condition exactly as
        // it is for the statement form.
        let cond = self.parse_condition(false)?;

        // Then expression
        let then_expr = self.parse_branch_value()?;

        // else expression
        let mut if_node = Node::new(NodeKind::ExprIf);
        if_node.children.push(cond);
        if_node.children.push(then_expr);

        if self.current.kind == TokenKind::KwElse {
            self.advance(); // consume 'else'
            let else_expr = self.parse_branch_value()?;
            if_node.children.push(else_expr);
        }

        Ok(if_node)
    }

    /// Parse switch expression: switch (val) { .arm => expr, ... }
    fn parse_switch_expr(&mut self) -> Result<Node, String> {
        self.advance(); // consume 'switch'

        // Value in parentheses
        self.expect(TokenKind::LParen)?;
        let val = self.parse_expr()?;
        self.expect(TokenKind::RParen)?;

        self.expect(TokenKind::LBrace)?;

        let mut sw = Node::new(NodeKind::ExprSwitch);
        sw.children.push(val);

        while self.current.kind != TokenKind::RBrace && self.current.kind != TokenKind::Eof {
            let mut arm = Node::new(NodeKind::ConstDecl);

            // Pattern
            if self.current.kind == TokenKind::Dot {
                self.advance(); // consume .
                if self.current.kind == TokenKind::Ident {
                    arm.name = self.current.lexeme.clone();
                    self.advance();
                }
            } else if self.current.kind == TokenKind::KwElse {
                arm.name = "else".to_string();
                self.advance();
            } else if self.current.kind == TokenKind::Minus {
                // Negative number pattern: -1, -2, etc.
                arm.name = "-".to_string();
                self.advance(); // consume -
                if self.current.kind == TokenKind::Number {
                    arm.name.push_str(&self.current.lexeme);
                    self.advance();
                }
            } else if self.current.kind == TokenKind::CharLiteral {
                arm.name = format!("'{}'", self.current.lexeme);
                self.advance();
            } else if self.current.kind == TokenKind::Ident
                || self.current.kind == TokenKind::Number
            {
                arm.name = self.current.lexeme.clone();
                self.advance();
            } else {
                break;
            }

            // =>
            if self.current.kind == TokenKind::FatArrow {
                self.advance();
            }

            // Arm expression
            let arm_expr = self.parse_expr()?;
            arm.children.push(arm_expr);

            if self.current.kind == TokenKind::Comma {
                self.advance();
            }

            sw.children.push(arm);
        }

        self.expect(TokenKind::RBrace)?;
        Ok(sw)
    }

    fn parse_enum_decl(&mut self, is_pub: bool) -> Result<Node, String> {
        let mut decl = Node::new(NodeKind::EnumDecl);
        decl.line = self.current.line as u32;
        decl.extra_pub = is_pub;

        self.advance(); // consume 'enum'

        if self.current.kind == TokenKind::Ident {
            decl.name = self.current.lexeme.clone();
            self.advance();
        }

        if self.current.kind == TokenKind::LParen {
            self.advance(); // consume (
            while self.current.kind != TokenKind::RParen && self.current.kind != TokenKind::Eof {
                self.advance();
            }
            self.expect(TokenKind::RParen)?;
        }

        self.expect(TokenKind::LBrace)?;
        self.parse_enum_body(&mut decl)?;
        self.expect(TokenKind::RBrace)?;
        Ok(decl)
    }

    fn parse_struct_decl(&mut self, is_pub: bool) -> Result<Node, String> {
        let mut decl = Node::new(NodeKind::StructDecl);
        decl.line = self.current.line as u32;
        decl.extra_pub = is_pub;

        self.advance(); // consume 'struct'

        if self.current.kind == TokenKind::Ident {
            decl.name = self.current.lexeme.clone();
            self.advance();
        }

        self.expect(TokenKind::LBrace)?;
        self.parse_struct_body(&mut decl)?;
        self.expect(TokenKind::RBrace)?;
        Ok(decl)
    }

    fn parse_block_name(&mut self) -> String {
        // Block names can be string literals ("name") or bare identifiers (name_with_underscores)
        if self.current.kind == TokenKind::String || self.current.kind == TokenKind::Ident {
            let name = self.current.lexeme.clone();
            self.advance();
            // Handle hyphenated names like "some-name"
            let mut full_name = name;
            while self.current.kind == TokenKind::Minus {
                full_name.push('-');
                self.advance();
                if self.current.kind == TokenKind::Ident {
                    full_name.push_str(&self.current.lexeme);
                    self.advance();
                }
            }
            full_name
        } else {
            String::new()
        }
    }

    fn parse_test_block(&mut self) -> Result<Node, String> {
        let mut block = Node::new(NodeKind::TestBlock);

        self.advance(); // consume 'test'
        block.name = self.parse_block_name();

        if self.current.kind == TokenKind::LBrace {
            // Brace-style test: test "name" { ... }
            self.advance(); // consume {
            self.parse_fn_body(&mut block)?;
            self.expect(TokenKind::RBrace)?;
        } else {
            // Keyword-style test: test name given ... when ... then ...
            self.parse_bdd_clauses(&mut block);
        }
        Ok(block)
    }

    /// Lower a braceless clause body into ordinary statements so the backends
    /// emit it like any brace-form test.
    ///
    ///   given|when|and  x = expr   ->  StmtLocal x = expr
    ///   then|assert        expr    ->  StmtExpr( assert(expr) )
    ///
    /// Before this, the body was discarded by `skip_to_next_top_level()`: a spec
    /// asserting `2 == 999` generated `test "..." {}` and passed. That affected
    /// 7,623 test blocks across 318 specs.
    ///
    /// Safety contract: this may only ADD assertions, never break a file. Any
    /// shape it does not fully understand restores the entry checkpoint and
    /// falls back to the original skip, so a spec that parsed before still
    /// parses.
    fn parse_bdd_clauses(&mut self, block: &mut Node) {
        let entry = self.save_state();
        let start_children = block.children.len();
        let mut lowered = 0usize;
        let mut first_clause_col: Option<usize> = self.bdd_first_col_preset.take();
        // W903: callers that already lowered an assertion head (bench-colon)
        // pre-set the role; everyone else starts a fresh block.
        if !self.bdd_role_preset {
            self.bdd_last_was_assertion = false;
        }
        self.bdd_role_preset = false;

        loop {
            // A non-identifier here is normally the end of the block, because
            // the next construct (`test`, `fn`, `invariant`, ...) lexes as a
            // keyword. But it can also mean we stopped mid-clause -- e.g. on the
            // comma of `given clk = true, rst_n = false`. Only a real boundary
            // ends the block; anything else falls back.
            // W898 (0005): `and` lexes as the LOGICAL OPERATOR token, not as an
            // identifier -- so the `and` clause the line below claims to accept
            // was unreachable for this function's whole life, and every block
            // containing one fell back wholesale. Found by ddmin: an 80-line
            // contextual repro reduced to four lines, and the "context" was one
            // `and` clause. Accept the keyword token at clause position.
            let and_kw = self.current.kind == TokenKind::KwAnd
                || (self.current.kind != TokenKind::Ident
                    && self.current.lexeme == "and");
            // W904 (0012): `const h = 5` / `var v : u32 = 7` BETWEEN clauses.
            // KwConst sits in is_block_boundary, so the block ENDED there and
            // the binding parsed at MODULE scope -- a test-local name became a
            // global for every backend, and the block's remaining clauses
            // dropped. Scope guards: only after at least one accepted clause,
            // and only at that clause's indent or deeper -- a shallower
            // const/var is a real module declaration and still ends the block.
            // (A body OPENING with const keeps the old hoist edge, documented.)
            // W905 panel: a blank line before the const meant "module scope"
            // to every reader, and the arm captured it into the block anyway.
            // Statement clauses must sit on the line immediately after the
            // previous clause; a gap returns the old boundary reading.
            // W699 rung 2: a blank line INSIDE an indented block. The rule above
            // reads a gap as "module scope", and that is right for a body that
            // has not started -- but once a statement HAS lowered, the block's
            // column is known, and a statement at or deeper than it is a
            // continuation no matter how many blank lines precede it.
            //
            // What the old reading produced, measured: the block ended at the
            // blank line, the head lowered INSIDE the invariant's `comptime {}`
            // and the tail hoisted to module scope OUTSIDE it --
            //
            //     comptime { var valid_trits: [3]i32 = .{...}; }
            //     const valid_info = get_encoding_info(&valid_trits, 3);
            //
            // -- which references a name that no longer exists, and collides
            // with the next invariant's `const result` in specs that reuse the
            // name. Zig rejected two specs for exactly this.
            //
            // `c > 1` keeps the W905 guard: in an UNINDENTED block, column
            // cannot tell a body statement from a module declaration, and the
            // arm must not steal module consts other tests read.
            let indented_continuation = lowered > 0
                && first_clause_col.is_some_and(|c| c > 1 && self.current.col >= c);
            let adjacent = self.current.line <= self.last_line + 1
                || self.only_comment_lines_between(self.last_line, self.current.line)
                || indented_continuation;
            let eff_col = if lowered == 0 && self.peek.kind == TokenKind::Ident {
                first_clause_col.or(Some(self.current.col))
            } else {
                first_clause_col
            };
            // A body that OPENS with `var`/`const` has no earlier clause to
            // take a column from, so `first_clause_col` was still None, this
            // arm was skipped, and the whole braceless body fell back to the
            // discard -- silently, and with no marker in the output. Seed the
            // column from this statement itself: when it is the first thing in
            // the block, it IS the first clause.
            if matches!(self.current.kind, TokenKind::KwConst | TokenKind::KwVar)
                && adjacent
                // The arm models `const NAME ...` only. `const (a, b) = f()` is the
                // tuple-destructure statement, and letting the arm swallow the
                // keyword leaves the parser on `(` at module level, where
                // parse_const_decl demands a name and dies -- a hard error where the
                // old path fell back safely.
                && self.peek.kind == TokenKind::Ident
                && eff_col.map_or(false, |c| c > 1 && self.current.col >= c)
            {
                if first_clause_col.is_none() {
                    first_clause_col = eff_col;
                }
                let st_entry = self.save_state();
                let _st_line = self.current.line;
                let mutable = self.current.kind == TokenKind::KwVar;
                self.advance();
                let mut ok_stmt = false;
                if self.current.kind == TokenKind::Ident {
                    let name = self.current.lexeme.clone();
                    self.advance();
                    let ty = if self.current.kind == TokenKind::Colon {
                        self.advance();
                        self.parse_type_annotation()
                    } else {
                        String::new()
                    };
                    if self.current.kind == TokenKind::Equals {
                        self.advance();
                        self.in_bdd_clause_value = true;
                        let r = self.parse_expr();
                        self.in_bdd_clause_value = false;
                        if let Ok(expr) = r {
                            // W904: parse_expr can return Ok having consumed
                            // only PART of the line (a brace-if value, W578) --
                            // accepting that "success" left the loop on
                            // mid-line junk and cost the whole block. A
                            // statement counts only if it ends CLEANLY: at a
                            // semicolon, a new line, a boundary, or EOF.
                            // W905 panel: `line > st_line` blessed a MID-LINE
                            // landing on a later line -- `x = a +` newline
                            // `2 y = 3` split one physical line into two
                            // minted statements. Clean means current OPENS its
                            // line: its line is beyond the last CONSUMED
                            // token's line.
                            // W699: the boundary disjunct CONTRADICTED the rule
                            // stated right above it, and `[]const u8` is where
                            // that showed. `const backends = [_][]const u8{...}`
                            // parses as `[_][]`, stops on the KwConst INSIDE the
                            // type -- a block boundary -- and the statement was
                            // minted as clean while the parser stood mid-type.
                            // The next turn then read `const u8{` as a second
                            // statement, failed, and left the wreckage at module
                            // level, where a const is a HARD error. Because one
                            // statement had already lowered, the whole-block
                            // fallback below never fired.
                            // A boundary keyword is a boundary only when it OPENS
                            // its line; mid-line it is somebody's type.
                            let clean = self.current.kind == TokenKind::Semicolon
                                || self.current.kind == TokenKind::Eof
                                || self.current.line > self.last_line;
                            if clean {
                                if self.current.kind == TokenKind::Semicolon {
                                    self.advance();
                                }
                                let mut decl = Node::new(NodeKind::StmtLocal);
                                decl.name = name;
                                decl.extra_type = ty;
                                decl.extra_mutable = mutable;
                                decl.children.push(expr);
                                block.children.push(decl);
                                ok_stmt = true;
                            }
                        }
                    }
                }
                if ok_stmt {
                    lowered += 1;
                    continue;
                }
                // W904: a statement this arm cannot read (a brace-if value,
                // W578 territory) must NOT cost the whole block -- restore and
                // END the block, exactly what the boundary did before this
                // rung: module-level statement parsing reads what it can and
                // the accounting stays per-line. (`let` lexes as KwVar, so
                // this arm sees every let-statement too.)
                self.restore_state(st_entry);
                break;
            }
            // W699 rung 9: a STATEMENT at clause position.
            //
            //     test t1
            //         var n : usize = 0;
            //         for (i in 0..3) { n = n + 1; }   <- block gives up here
            //         assert n == 3                    <- and this goes with it
            //
            // `for` and `while` are keywords, so they are neither a clause head
            // nor a block boundary, and the loop fell through to the whole-block
            // fallback. Measured before the fix: 110 fallback events across ~25
            // specs, the largest non-`forall` shape in the distribution.
            //
            // Rung 2 accepted these after a `then`; this accepts them where a
            // clause head is expected. Same guards as the const/var and bare-call
            // arms: only once the block's column is known, only at or deeper than
            // it, never at column 1.
            if matches!(
                self.current.kind,
                TokenKind::KwFor | TokenKind::KwWhile | TokenKind::KwIf
            ) && adjacent
                && first_clause_col.is_some_and(|c| c > 1 && self.current.col >= c)
            {
                let st_stmt = self.save_state();
                match self.parse_body_stmt() {
                    Ok(stmt) => {
                        block.children.push(stmt);
                        lowered += 1;
                        self.last_line = self.current.line;
                        continue;
                    }
                    Err(_) => self.restore_state(st_stmt),
                }
            }
            // W699 rung 4: a bare CALL statement in a braceless body.
            //
            //     test deque_init_empty
            //         var data : [10]i32 = undefined;
            //         deque_init(&data, &front, &back, &count);   <- discarded
            //         assert count == 0                           <- and this
            //
            // `deque_init` is an Ident, so it was read as a CLAUSE HEAD and its
            // argument list as the clause's value. That shape is not a clause,
            // the lowering failed, and the whole block fell to the discard --
            // taking the assertions after it. `specs/isa/ternary_deque.t27`
            // alone loses 1873 tokens this way, the largest single entry in the
            // ledger, and the calls are what SET UP the state the assertions
            // then check: without them the asserts could not run even if they
            // survived.
            //
            // Same guards as the const/var arm: only after the block's column is
            // known, only at or deeper than it, never at column 1 where a body
            // statement and a module declaration are indistinguishable (W905).
            // W699 rung 12: a body that OPENS with a call has no earlier clause
            // to take a column from, so `first_clause_col` was still None and
            // this arm never ran. A `bench` beginning
            //
            //     bench ternary_not_performance
            //         @setEvalBranchQuota(10000);
            //         var result : i32 = 0;
            //
            // lost the whole block for that reason. The const/var arm already
            // seeds the column from the statement itself when it is the first
            // thing in the block (W904); this is the same seed, and the `c > 1`
            // guard against unindented blocks is unchanged.
            let call_col = if lowered == 0 {
                first_clause_col.or(Some(self.current.col))
            } else {
                first_clause_col
            };
            // ... and a CLAUSE KEYWORD is never a call, however much it looks
            // like one. `given (exp, mant) = f(15)` is an Ident followed by `(`,
            // and before the column was seeded the arm could not reach a block's
            // FIRST token, so nothing had ever tested that. Seeding it exposed
            // the hole immediately: two specs went from lowering cleanly to
            // stopping mid-clause, +120 discarded tokens, while the corpus total
            // still fell. The per-entry ratchet named both; the total hid them.
            let clause_head = matches!(
                self.current.lexeme.as_str(),
                "given" | "when" | "then" | "assert" | "and" | "measure" | "target"
            );
            if self.current.kind == TokenKind::Ident
                && !clause_head
                && self.peek.kind == TokenKind::LParen
                && adjacent
                && call_col.is_some_and(|c| c > 1 && self.current.col >= c)
            {
                if first_clause_col.is_none() {
                    first_clause_col = call_col;
                }
                let st_call = self.save_state();
                match self.parse_body_stmt() {
                    Ok(stmt) => {
                        block.children.push(stmt);
                        lowered += 1;
                        self.last_line = self.current.line;
                        continue;
                    }
                    // A shape this cannot read must cost only itself: restore and
                    // fall through to the clause reading, exactly as before.
                    Err(_) => {
                        // Restore the column too: a seed that survives a failed
                        // parse would let a LATER shallower statement pass the
                        // `>= c` guard on a column this block never established.
                        self.restore_state(st_call);
                        if lowered == 0 {
                            first_clause_col = None;
                        }
                    }
                }
            }
            if self.current.kind != TokenKind::Ident && !and_kw {
                if Self::is_block_boundary(self.current.kind) {
                    break;
                }
                self.bdd_fail_why = "stopped mid-clause";
                self.restore_bdd_fallback(block, start_children, entry);
                return;
            }
            // W894 (0003): checkpoint PER CLAUSE. The whole-block fallback made
            // one unsupported clause lose its siblings -- most of the corpus's
            // dropped test lines were collateral, not themselves unsupported.
            let clause_entry = self.save_state();
            let clause_col = self.current.col;
            let clause = self.current.lexeme.clone();
            // W901 (0007 v2): Gherkin semantics -- `and` inherits the ROLE of
            // the clause before it, but CONTENT WINS: `and ident = ...` is a
            // binding wherever it stands (the panel's sandwich probe bound a
            // variable right after a then). Anything else after an assertion
            // clause asserts.
            let and_binds = clause == "and" && {
                let look = self.save_state();
                self.advance();
                let is_bind = self.current.kind == TokenKind::Ident && {
                    self.advance();
                    self.current.kind == TokenKind::Equals
                };
                self.restore_state(look);
                is_bind
            };
            let is_binding = clause == "given"
                || clause == "when"
                || (clause == "and" && (and_binds || !self.bdd_last_was_assertion));
            let is_assertion = clause == "then"
                || clause == "assert"
                || (clause == "and" && !and_binds && self.bdd_last_was_assertion);
            // W901 (0007): bench clause pair in keyword form -- `measure f(x)` /
            // `target latency_us < 5.0`. Lowered to expression STATEMENTS named
            // by their clause, never to asserts: a bench target is a goal, not
            // a hard invariant, and inventing check semantics here is exactly
            // what FORALL-DECISION.md declines to do. The colon-prose form
            // (`measure: nanoseconds to ...`) stays a fallback -- prose is not
            // an expression.
            // W903 panel: in a TEST block a stray `measure:` captured the
            // block's only then-assert into inert prose -- a vacuous test
            // under a green light. The clause pair belongs to bench blocks.
            let is_expr_clause = (clause == "measure" || clause == "target")
                && block.kind == NodeKind::BenchBlock;

            if !is_binding && !is_assertion && !is_expr_clause {
                // W904 (0012): a bare ASSIGNMENT statement between clauses --
                // `sum = if (...) ...;` -- is an Ident that is no clause, and
                // the whole-block fallback here cost every already-lowered
                // sibling. `Ident =` at clause indent parses as a statement
                // clause under the same clean-termination rule as const/var,
                // in the fn-body StmtAssign shape (lhs expr child, rhs child).
                if first_clause_col.map_or(false, |c| c > 1 && clause_col >= c)
                    && self.current.line <= self.last_line + 1
                    && self.peek.kind == TokenKind::Equals
                {
                    let st_entry = self.save_state();
                    let _st_line = self.current.line;
                    let mut lhs = Node::new(NodeKind::ExprIdentifier);
                    lhs.name = self.current.lexeme.clone();
                    self.advance(); // ident
                    self.advance(); // =
                    self.in_bdd_clause_value = true;
                    let r = self.parse_expr();
                    self.in_bdd_clause_value = false;
                    let mut ok_stmt = false;
                    if let Ok(expr) = r {
                        let clean = self.current.kind == TokenKind::Semicolon
                            || self.current.kind == TokenKind::Eof
                            || self.current.line > self.last_line
                            || Self::is_block_boundary(self.current.kind);
                        if clean {
                            if self.current.kind == TokenKind::Semicolon {
                                self.advance();
                            }
                            let mut assign = Node::new(NodeKind::StmtAssign);
                            assign.line = _st_line as u32;
                            assign.children.push(lhs);
                            assign.children.push(expr);
                            block.children.push(assign);
                            ok_stmt = true;
                        }
                    }
                    if ok_stmt {
                        lowered += 1;
                        continue;
                    }
                    self.restore_state(st_entry);
                }
                // An identifier that is not a clause means this body has a shape
                // we do not model. Falling through with the parser positioned
                // mid-block is what broke 19 specs on the first attempt.
                // But when clauses BEFORE it lowered, throwing them away is a second
                // loss on top of the one that is defensible. An invariant reading
                //
                //     assert g(1) == 111
                //     forall x: i32 . g(x) == x
                //     assert g(2) == 222
                //
                // lost BOTH asserts to the `forall` between them. Skipping an unbounded
                // `forall` is a language decision; taking its neighbours with it is not.
                // Keep them, and MARK the block -- the emitter's NOT CHECKED notice keys
                // on `children.is_empty()`, so without the mark a partial block would
                // report as fully verified.
                if block.children.len() > start_children {
                    block.extra_field = "partial".to_string();
                    self.restore_state(entry);
                    self.skip_to_next_top_level();
                    return;
                }
                // NOT "not an identifier": the comment above says it plainly, this
                // arm is reached for an identifier that is not a CLAUSE. The
                // first name I gave it was wrong and the table read as though
                // `forall` lexed as something other than an Ident.
                self.bdd_fail_why = "unmodelled clause head";
                self.restore_bdd_fallback(block, start_children, entry);
                return;
            }

            let ok = if is_expr_clause {
                self.advance();
                if self.current.kind == TokenKind::Colon {
                    // W902 (0009): the colon-form pair -- `measure: nanoseconds
                    // to f(x)` / `target: < 50ns`. The intervention map
                    // convicted the FORM (a trivial expression after the colon
                    // drops too), and the content is frequently PROSE, so no
                    // expression grammar can read it honestly. Capture the
                    // rest of the LINE verbatim into the node's value: the
                    // tokens are READ and preserved, and no semantics are
                    // invented for them.
                    // W903 panel: the capture stops at a same-line CLAUSE WORD
                    // -- `measure: 5 target: 6` was one node with target
                    // flattened into prose, and a same-line `then x == 1`
                    // lost its assert into the value. Prose keeps its words;
                    // sibling clauses keep their nodes.
                    let line = self.current.line;
                    self.advance(); // consume ':'
                    let mut text = String::new();
                    while self.current.kind != TokenKind::Eof
                        && self.current.line == line
                    {
                        // W914: the stop-set shrinks to the words that START
                        // sibling clauses in real corpora -- `when`/`and`/
                        // `given` are ordinary ENGLISH inside prose
                        // ("nanoseconds to f() when 2 bytes available"), and
                        // stopping there felled five fpga specs.
                        if !text.is_empty()
                            && matches!(
                                self.current.lexeme.as_str(),
                                "measure" | "target" | "then" | "assert"
                            )
                        {
                            break;
                        }
                        if !text.is_empty() {
                            text.push(' ');
                        }
                        text.push_str(&self.current.lexeme);
                        self.advance();
                    }
                    let mut stmt = Node::new(NodeKind::StmtExpr);
                    stmt.name = format!("{}:", clause);
                    stmt.value = text;
                    block.children.push(stmt);
                    true
                } else {
                    self.in_bdd_clause_value = true;
                    let r = self.parse_expr();
                    self.in_bdd_clause_value = false;
                    match r {
                        Ok(expr) => {
                            let mut stmt = Node::new(NodeKind::StmtExpr);
                            stmt.name = clause.clone();
                            stmt.children.push(expr);
                            // W906 (0013): a UNIT PHRASE after the bound --
                            // `target throughput > 1000 steps/sec` -- left
                            // `steps/sec` as junk that felled the block. The
                            // same-line residue is captured verbatim into the
                            // node's value, like the colon form's prose.
                            let mut unit = String::new();
                            while self.current.kind != TokenKind::Eof
                                && self.current.line == self.last_line
                            {
                                if !unit.is_empty() {
                                    unit.push(' ');
                                }
                                unit.push_str(&self.current.lexeme);
                                self.advance();
                            }
                            stmt.value = unit;
                            block.children.push(stmt);
                            true
                        }
                        Err(_) => false,
                    }
                }
            } else if is_assertion {
                self.advance();
                // `then` takes an EXPRESSION, and specs write a STATEMENT after it:
                //
                //     then for (i in 0..100) {
                //         assert t1 == -t2;
                //     }
                //
                // `parse_expr` cannot read a `for`, so the clause returned false and the
                // whole braceless block fell to the top-level discard -- taking the
                // asserts INSIDE the loop with it. `then <expr>` alone was always fine,
                // which is why this survived: the failing shape is `then` plus a block.
                //
                // The statement is pushed as itself rather than wrapped in `assert`: the
                // assertions live inside the loop body, and asserting a `for` is not a
                // thing.
                if matches!(
                    self.current.kind,
                    TokenKind::KwFor | TokenKind::KwWhile | TokenKind::KwIf | TokenKind::LBrace
                ) {
                    let st = self.save_state();
                    match self.parse_body_stmt() {
                        Ok(stmt) => {
                            block.children.push(stmt);
                            lowered += 1;
                            self.bdd_last_was_assertion = is_assertion;
                            self.last_line = self.current.line;
                            continue;
                        }
                        Err(_) => self.restore_state(st),
                    }
                }
                self.in_bdd_clause_value = true;
                let r = self.parse_expr();
                self.in_bdd_clause_value = false;
                match r {
                    Ok(expr) => {
                        let mut call = Node::new(NodeKind::ExprCall);
                        call.name = "assert".to_string();
                        call.children.push(expr);
                        let mut stmt = Node::new(NodeKind::StmtExpr);
                        stmt.children.push(call);
                        block.children.push(stmt);
                        true
                    }
                    Err(_) => false,
                }
            } else {
                self.advance();
                // W894 (0003): `when (a_out, psum) = pe(...)` -- a tuple pattern.
                // This single unsupported shape accounted for ~60% of every
                // dropped when-line in the corpus, and the whole-block fallback
                // then lost the sibling clauses too. Mirrors parse_local_decl's
                // tuple path exactly: StmtLocal, empty name, comma-joined
                // pattern in extra_field.
                if self.current.kind == TokenKind::LParen {
                    self.advance(); // consume (
                    let mut pat = String::new();
                    while self.current.kind != TokenKind::RParen
                        && self.current.kind != TokenKind::Eof
                    {
                        match self.current.kind {
                            TokenKind::Comma => pat.push_str(", "),
                            TokenKind::Ident => pat.push_str(&self.current.lexeme),
                            _ => {}
                        }
                        self.advance();
                    }
                    if self.current.kind == TokenKind::RParen {
                        self.advance();
                    }
                    if self.current.kind != TokenKind::Equals || pat.is_empty() {
                        // W901 (0007 v2): not a tuple binding -- the panel
                        // showed `given (x + 1) == 2` dying here while the
                        // SAME value parsed fine under measure/target. Restore
                        // and lower the value as an expression statement.
                        self.restore_state(clause_entry);
                        self.advance();
                        self.in_bdd_clause_value = true;
                        let r = self.parse_expr();
                        self.in_bdd_clause_value = false;
                        match r {
                            Ok(expr) => {
                                let mut stmt = Node::new(NodeKind::StmtExpr);
                                stmt.name = clause.clone();
                                stmt.children.push(expr);
                                block.children.push(stmt);
                                true
                            }
                            Err(_) => false,
                        }
                    } else {
                        self.advance();
                        self.in_bdd_clause_value = true;
                        let r = self.parse_expr();
                        self.in_bdd_clause_value = false;
                        match r {
                            Ok(expr) => {
                                let mut decl = Node::new(NodeKind::StmtLocal);
                                decl.extra_field = pat;
                                decl.children.push(expr);
                                block.children.push(decl);
                                true
                            }
                            Err(_) => false,
                        }
                    }
                } else if self.current.kind != TokenKind::Ident
                    && !self.current.lexeme.is_empty()
                    && self
                        .current
                        .lexeme
                        .chars()
                        .all(|c| c.is_ascii_alphanumeric() || c == '_')
                    && self.peek.kind == TokenKind::Equals
                {
                    // W906 (0013): `given var = 5` -- `var` as a binding NAME.
                    // The keyword collision felled the block; a keyword
                    // directly before `=` in a binding clause is a name.
                    let name = self.current.lexeme.clone();
                    self.advance();
                    self.advance();
                    self.in_bdd_clause_value = true;
                    let r = self.parse_expr();
                    self.in_bdd_clause_value = false;
                    match r {
                        Ok(expr) => {
                            let mut decl = Node::new(NodeKind::StmtLocal);
                            decl.name = name;
                            decl.children.push(expr);
                            block.children.push(decl);
                            true
                        }
                        Err(_) => false,
                    }
                } else if self.current.kind != TokenKind::Ident {
                    false
                } else {
                    // W901 (0007): `given uart_tx_send(0x55)` -- a side-effect
                    // call with no binding -- and `given f() == 1` -- a bare
                    // comparison -- are not `ident =` bindings. Peek past the
                    // identifier; anything but `=` restores and lowers the
                    // whole clause value as an expression statement.
                    let bind_look = self.save_state();
                    let name = self.current.lexeme.clone();
                    self.advance();
                    // W699 rung 11: a TYPED binding.
                    //
                    //     given crossings: [i32] = []
                    //
                    // The arm below peeks for `=` immediately after the name, so
                    // an annotation between them read as "not a binding" and the
                    // clause -- and its whole block -- went to the discard. 17
                    // fallback events across 4 specs, all of them `given`.
                    //
                    // The type is parsed and kept on the declaration, the way
                    // `var x : T = v` already does in the statement arm. If no `=`
                    // follows the annotation this restores and changes nothing.
                    let mut typed = String::new();
                    if self.current.kind == TokenKind::Colon {
                        let ty_look = self.save_state();
                        self.advance(); // :
                        let ty = self.parse_type_annotation();
                        if self.current.kind == TokenKind::Equals && !ty.is_empty() {
                            typed = ty;
                        } else {
                            self.restore_state(ty_look);
                        }
                    }
                    if self.current.kind != TokenKind::Equals {
                        self.restore_state(bind_look);
                        // W906 (0013): a DOTTED/INDEXED LVALUE step --
                        // `and state.gamma[0] = 2.0`, `when buffers.scores[0..4]
                        // = scores` -- is an assignment, not an expression; the
                        // expression path parsed the lvalue, stopped on `=`,
                        // and the over-consumption guard felled the block.
                        // Parse the lvalue, and if the cursor lands on a plain
                        // `=`, lower the clause as StmtAssign.
                        if self.current.kind == TokenKind::Ident
                            && (self.peek.kind == TokenKind::Dot
                                || self.peek.kind == TokenKind::LBracket)
                        {
                            let lv_look = self.save_state();
                            self.in_bdd_clause_value = true;
                            let lv = self.parse_expr();
                            self.in_bdd_clause_value = false;
                            let mut done = false;
                            if let Ok(lhs) = lv {
                                if self.current.kind == TokenKind::Equals {
                                    self.advance();
                                    self.in_bdd_clause_value = true;
                                    let rv = self.parse_expr();
                                    self.in_bdd_clause_value = false;
                                    if let Ok(rhs) = rv {
                                        let clean = self.current.kind
                                            == TokenKind::Semicolon
                                            || self.current.kind == TokenKind::Eof
                                            || self.current.line > self.last_line
                                            || Self::is_block_boundary(
                                                self.current.kind,
                                            );
                                        if clean {
                                            if self.current.kind
                                                == TokenKind::Semicolon
                                            {
                                                self.advance();
                                            }
                                            let mut assign =
                                                Node::new(NodeKind::StmtAssign);
                                            assign.children.push(lhs);
                                            assign.children.push(rhs);
                                            block.children.push(assign);
                                            done = true;
                                        }
                                    }
                                }
                            }
                            if !done {
                                self.restore_state(lv_look);
                            } else {
                                self.bdd_last_was_assertion = false;
                                lowered += 1;
                                continue;
                            }
                        }
                        self.in_bdd_clause_value = true;
                        let r = self.parse_expr();
                        self.in_bdd_clause_value = false;
                        match r {
                            Ok(expr) => {
                                let mut stmt = Node::new(NodeKind::StmtExpr);
                                stmt.name = clause.clone();
                                stmt.children.push(expr);
                                block.children.push(stmt);
                                true
                            }
                            Err(_) => false,
                        }
                    } else {
                        self.advance();
                        self.in_bdd_clause_value = true;
                        let r = self.parse_expr();
                        self.in_bdd_clause_value = false;
                        match r {
                            Ok(expr) => {
                                let mut decl = Node::new(NodeKind::StmtLocal);
                                decl.name = name;
                                decl.children.push(expr);
                                // W907 (0014): a COMPREHENSION SUFFIX --
                                // `given encoded = encode(x) for x in {...}`
                                // -- felled its block. The same-line `for ...`
                                // tail is captured verbatim into extra_field:
                                // read and preserved, no semantics invented.
                                if self.current.kind == TokenKind::KwFor
                                    && self.current.line == self.last_line
                                {
                                    let mut tail = String::new();
                                    let line = self.current.line;
                                    while self.current.kind != TokenKind::Eof
                                        && self.current.line == line
                                    {
                                        if !tail.is_empty() {
                                            tail.push(' ');
                                        }
                                        tail.push_str(&self.current.lexeme);
                                        self.advance();
                                    }
                                    decl.extra_field = tail;
                                }
                                decl.extra_type = typed.clone();
                                block.children.push(decl);
                                // W699 rung 10: COMMA-SEPARATED bindings in one
                                // clause.
                                //
                                //     given clk = true, rst_n = false, angle = 4096
                                //
                                // The loop's own comment at the top of this
                                // function names the shape -- "it can also mean we
                                // stopped mid-clause -- e.g. on the comma of
                                // `given clk = true, rst_n = false`" -- and nothing
                                // ever acted on it. 19 fallback events in
                                // specs/igla/race/cordic_top.t27 alone, each one
                                // taking a whole block of clauses with it.
                                //
                                // Same line only: a comma opening the next line is
                                // somebody else's punctuation. Anything this cannot
                                // read restores to the comma and leaves the clause
                                // as it stands, so a partial list still lowers what
                                // it understood.
                                while self.current.kind == TokenKind::Comma
                                    && self.current.line == self.last_line
                                    && self.peek.kind == TokenKind::Ident
                                {
                                    let cm = self.save_state();
                                    self.advance(); // ,
                                    let n2 = self.current.lexeme.clone();
                                    self.advance(); // name
                                    if self.current.kind != TokenKind::Equals {
                                        self.restore_state(cm);
                                        break;
                                    }
                                    self.advance(); // =
                                    self.in_bdd_clause_value = true;
                                    let r2 = self.parse_expr();
                                    self.in_bdd_clause_value = false;
                                    match r2 {
                                        Ok(e2) => {
                                            let mut d2 = Node::new(NodeKind::StmtLocal);
                                            d2.name = n2;
                                            d2.children.push(e2);
                                            block.children.push(d2);
                                        }
                                        Err(_) => {
                                            self.restore_state(cm);
                                            break;
                                        }
                                    }
                                }
                                true
                            }
                            Err(_) => false,
                        }
                    }
                }
            };

            // `parse_expr` is greedy across newlines, so a binding value can
            // swallow the next clause's name (`FPGA_PART_35T and p100`) and
            // leave us on its `=`. That is over-consumption; the clause-level
            // recovery below cannot help because the damage crosses clauses --
            // keep the whole-block fallback for exactly this case.
            if self.current.kind == TokenKind::Equals {
                self.bdd_fail_why = "clause value over-consumed";
                self.bdd_fail_clause = clause.clone();
                self.restore_bdd_fallback(block, start_children, entry);
                return;
            }
            if !ok {
                // W898 revision: the per-clause SKIP is withdrawn. Its boundary
                // set stopped at `}` and `fn` inside clause junk (a lambda in a
                // then-expr, a struct literal in a given) and handed fragments to
                // module level, which errors HARD where the old path skipped
                // safely -- four files that parsed before regressed. On a failed
                // clause the whole block falls back exactly as before 0003; the
                // collateral win survives because the and-fix makes most blocks
                // lower COMPLETELY, never reaching this arm.
                let _ = clause_entry;
                self.bdd_fail_why = "clause not lowerable";
                self.bdd_fail_clause = clause.clone();
                self.restore_bdd_fallback(block, start_children, entry);
                return;
            }
            if clause != "and" {
                self.bdd_last_was_assertion = is_assertion;
            }
            // W905 panel: the anchor is the MINIMUM accepted clause column
            // (an over-indented first given at col 9 made a col-5 statement
            // look "shallower" and hoisted it); and at a column-1 tie the
            // statement arms are DISABLED entirely -- an unindented block
            // makes module declarations and body statements indistinguishable
            // by column, and the arm stole module consts other tests read.
            first_clause_col = Some(match first_clause_col {
                Some(c) if c <= clause_col => c,
                _ => clause_col,
            });
            // A clause may end with a semicolon: `given p = 0;`. Nothing
            // consumed it, so the next loop turn met `;` where it expects a
            // clause head, read that as "stopped mid-clause", and restored the
            // fallback -- discarding the WHOLE block over one character. The
            // same body without the semicolon lowered fine, which is what made
            // it invisible: two spellings of one clause, one of them silently
            // emptying every assertion after it.
            if self.current.kind == TokenKind::Semicolon {
                self.advance();
            }
            lowered += 1;
        }

        if lowered == 0 {
            self.bdd_fail_why = "nothing lowered";
            self.restore_bdd_fallback(block, start_children, entry);
        }
    }

    /// Tokens that can legitimately follow a braceless clause body. Anything
    /// else means the loop stopped mid-clause, not at the end of the block.
    /// Tokens that can only OPEN a new top-level declaration. Used to bound a
    /// raw token collector that would otherwise run to end-of-file, and
    /// deliberately narrower than `is_block_boundary`: callers pair it with a
    /// "starts its own line" test, because `const` and `struct` also appear
    /// mid-type (`[]const u8`, `= struct {`).
    /// W652: does this token mean the const initialiser CONTINUES past the
    /// primary we just looked at?
    ///
    /// `parse_const_decl` has fast paths that take a bare `Number` or `Ident`
    /// and advance exactly one token. Any binary operator sitting after that
    /// primary was therefore DISCARDED, silently, in all five backends:
    /// `const DIV : u32 = A / B;` emitted `DIV = A`. `100 / 7` emitted `100`.
    /// The only spellings that survived were the ones a delimiter happened to
    /// route through `parse_expr` -- `f(A) + 1` was correct because `(` did it.
    ///
    /// This predicate is the semantic test the fast paths were missing: it asks
    /// "is there more expression here", not "does the next token look like a
    /// delimiter I recognise".
    fn token_continues_expr(kind: TokenKind) -> bool {
        matches!(
            kind,
            TokenKind::Plus
                | TokenKind::Minus
                | TokenKind::Star
                | TokenKind::Slash
                | TokenKind::Percent
                | TokenKind::Amp
                | TokenKind::Pipe
                | TokenKind::Caret
                | TokenKind::Lt
                | TokenKind::Gt
                | TokenKind::Lte
                | TokenKind::Gte
                | TokenKind::Eq
                | TokenKind::Neq
                | TokenKind::ShiftLeft
                | TokenKind::ShiftRight
                | TokenKind::Power
                | TokenKind::PlusPlus
                | TokenKind::PlusPercent
                | TokenKind::MinusPercent
                | TokenKind::StarPercent
                | TokenKind::KwAnd
                | TokenKind::KwOr
                | TokenKind::Dot
        )
    }

    /// W655 (T95): is this a floating type? Verilog's synthesizable subset has
    /// no float, and lowering `f32` to an integer vector produced a value that
    /// COMPILES, SYNTHESIZES, RUNS and is wrong for every non-integral input
    /// (T84/T85). Verilog `real` is IEEE double and is correct in simulation;
    /// synthesis rejects it, which is truthful because `f32` arithmetic was
    /// never synthesizable.
    fn type_is_float(ty: &str) -> bool {
        matches!(ty.trim(), "f32" | "f64")
    }

    fn opens_declaration(kind: TokenKind) -> bool {
        matches!(
            kind,
            TokenKind::KwPub
                | TokenKind::KwConst
                | TokenKind::KwFn
                | TokenKind::KwTest
                | TokenKind::KwInvariant
                | TokenKind::KwBench
                | TokenKind::KwUse
                | TokenKind::KwModule
        )
    }

    fn is_block_boundary(kind: TokenKind) -> bool {
        matches!(
            kind,
            TokenKind::Eof
                | TokenKind::RBrace
                | TokenKind::KwTest
                | TokenKind::KwFn
                | TokenKind::KwInvariant
                | TokenKind::KwBench
                | TokenKind::KwPub
                | TokenKind::KwConst
                | TokenKind::KwUse
                | TokenKind::KwModule
        )
    }

    fn restore_bdd_fallback(
        &mut self,
        block: &mut Node,
        start_children: usize,
        entry: ParserCheckpoint,
    ) {
        if std::env::var("T27_BDD_DEBUG").is_ok() {
            eprintln!(
                "BDD-FALLBACK at line {} kind {:?} lexeme {:?}",
                self.current.line, self.current.kind, self.current.lexeme
            );
        }
        // W699 rung 9: record BEFORE the restore, while `current` is still the
        // token the block gave up on. After `restore_state` it is the block's
        // first token again, which is the same for every failure and says
        // nothing.
        self.bdd_fallbacks.push((
            self.current.line as u32,
            self.bdd_fail_why,
            if self.bdd_fail_clause.is_empty() {
                self.current.lexeme.clone()
            } else {
                std::mem::take(&mut self.bdd_fail_clause)
            },
        ));
        self.bdd_fail_why = "unset";
        block.children.truncate(start_children);
        self.restore_state(entry);
        // W699: nested fallbacks are possible, so save and restore rather than
        // clearing -- an inner block finishing must not tell the outer one's
        // remaining tokens they came from a plain resync.
        let outer = self.in_bdd_fallback;
        self.in_bdd_fallback = true;
        self.skip_to_next_top_level();
        self.in_bdd_fallback = outer;
    }

    fn parse_invariant_block(&mut self) -> Result<Node, String> {
        let mut block = Node::new(NodeKind::InvariantBlock);

        self.advance(); // consume 'invariant'
        block.name = self.parse_block_name();

        if self.current.kind == TokenKind::LBrace {
            // Brace-style invariant: invariant "name" { ... }
            self.advance(); // consume {
            self.parse_fn_body(&mut block)?;
            self.expect(TokenKind::RBrace)?;
        } else {
            self.parse_invariant_clause(&mut block);
        }
        Ok(block)
    }

    /// Lower a keyword-form invariant into an assertion, mirroring what W559
    /// did for tests. The body was discarded by `skip_to_next_top_level()`, so
    /// codegen emitted `// invariant: X verified (no statements)` -- a comment
    /// claiming verification. 5,163 invariants are in this form.
    ///
    /// `forall`-quantified statements (837) are not runtime-checkable and fall
    /// back to the original skip, as does anything else this cannot model.
    /// Same contract as the test lowering: may only ADD assertions.
    fn parse_invariant_clause(&mut self, block: &mut Node) {
        let entry = self.save_state();
        let start_children = block.children.len();

        // Two spellings exist. `invariant name: <expr>` carries the predicate
        // inline; `invariant name` is followed by indented clauses in exactly
        // the same style as a braceless test:
        //
        //     invariant board_name_not_empty
        //         assert BOARD_NAME != ""
        //
        // The clause form is the common one -- 76 of 81 in the currently
        // compiling specs -- so it goes to the shared clause parser.
        if self.current.kind != TokenKind::Colon {
            self.parse_bdd_clauses(block);
            return;
        }
        self.advance(); // consume ':'

        if self.current.kind == TokenKind::Ident && self.current.lexeme == "forall" {
            // The quantified-invariant arm: recognised by name, discarded on
            // purpose. What `forall` MEANS at codegen is #2774's decision.
            self.bdd_fail_why = "quantified invariant (forall)";
            self.bdd_fail_clause = "forall".to_string();
            self.restore_bdd_fallback(block, start_children, entry);
            return;
        }

        match self.parse_expr() {
            Ok(expr) => {
                let mut call = Node::new(NodeKind::ExprCall);
                call.name = "assert".to_string();
                call.children.push(expr);
                let mut stmt = Node::new(NodeKind::StmtExpr);
                stmt.children.push(call);
                block.children.push(stmt);
            }
            Err(_) => {
                self.bdd_fail_why = "inline predicate does not parse";
                self.restore_bdd_fallback(block, start_children, entry);
                return;
            }
        }

        // W902 (0010): `invariant name : EXPR;` -- the trailing semicolon was
        // the CONVICTED cause (colon, spacing and `||` all exonerated by
        // variant probes): `;` is not a block boundary, so the check below
        // dropped the freshly-lowered assertion. Eat it.
        if self.current.kind == TokenKind::Semicolon {
            self.advance();
        }

        // W903 panel: is_block_boundary omits var/enum/struct/using, so an
        // invariant followed by any of those dropped its OWN assert. They end
        // the block here as cleanly as const/fn do; the GLOBAL boundary set is
        // left alone (adding KwVar there would hoist keyword-test-body vars).
        // `const` opens a module-level DECLARATION and is a boundary -- unless
        // it is followed by `(`, which is the tuple-destructure STATEMENT form
        // `const (a, b) = f();`. Treating that as a clean end hands it to the
        // module parser, which requires a name after `const` and dies with
        // "Expected identifier after 'const', got LParen". The block has not
        // ended; the clause parser simply stopped inside it.
        let const_destructure =
            self.current.kind == TokenKind::KwConst && self.peek.kind == TokenKind::LParen;
        let clean_end = !const_destructure
            && (Self::is_block_boundary(self.current.kind)
                || matches!(
                    self.current.kind,
                    TokenKind::KwVar
                        | TokenKind::KwEnum
                        | TokenKind::KwStruct
                        | TokenKind::KwUsing
                ));
        if !clean_end {
            // A block that lowered SOMETHING and then met a clause it cannot
            // model used to lose the lot: two checkable `assert`s on either
            // side of a `forall` both vanished, and only the `forall` was
            // defensible to skip.
            //
            // Keep what lowered, and MARK the block, because the emitter's
            // "NOT CHECKED" notice keys on `children.is_empty()` -- without
            // the mark a partial block would report as fully verified, which
            // is the exact claim W635 was written to stop.
            if block.children.len() > start_children {
                block.extra_field = "partial".to_string();
                self.restore_state(entry);
                self.skip_to_next_top_level();
            } else {
                self.bdd_fail_why = "bench head not lowerable";
                self.restore_bdd_fallback(block, start_children, entry);
            }
        }
    }

    fn parse_bench_block(&mut self) -> Result<Node, String> {
        let mut block = Node::new(NodeKind::BenchBlock);

        self.advance(); // consume 'bench'
        block.name = self.parse_block_name();

        if self.current.kind == TokenKind::LBrace {
            // Brace-style bench: bench "name" { ... }
            self.advance(); // consume {
            self.parse_fn_body(&mut block)?;
            self.expect(TokenKind::RBrace)?;
        } else if self.current.kind == TokenKind::Colon {
            // W902 (0009): `bench name: expr` -- the one-line colon body that
            // parses under `invariant` dropped under `bench` (the intervention
            // map convicted the FORM: a trivial expression dropped too). Same
            // lowering as invariant-colon, which 0004a already gave bench
            // then-clauses: the predicate becomes an assertion.
            let entry = self.save_state();
            let start_children = block.children.len();
            self.advance(); // consume ':'
            // W903 panel: without the clause flag, a next-line `and y == 3`
            // was absorbed under `or` precedence into a strictly WEAKER
            // assertion. Same flag as every clause value.
            self.in_bdd_clause_value = true;
            let head = self.parse_expr();
            self.in_bdd_clause_value = false;
            match head {
                Ok(expr) => {
                    let mut call = Node::new(NodeKind::ExprCall);
                    call.name = "assert".to_string();
                    call.children.push(expr);
                    let mut stmt = Node::new(NodeKind::StmtExpr);
                    stmt.children.push(call);
                    block.children.push(stmt);
                    if self.current.kind == TokenKind::Semicolon {
                        self.advance();
                    }
                    // W903 panel: `bench b: x >= 0` followed by indented
                    // measure:/then clauses lost EVERYTHING to the boundary
                    // check. A clause word here continues the block in the
                    // shared clause parser.
                    if self.current.kind == TokenKind::Ident
                        || self.current.kind == TokenKind::KwAnd
                        || self.current.kind == TokenKind::KwConst
                        || self.current.kind == TokenKind::KwVar
                    {
                        self.bdd_last_was_assertion = true;
                        self.bdd_role_preset = true;
                        // W905 panel: continuation statements need the column
                        // anchor the head never set -- without it the arms
                        // stayed dark and a `let` after the head minted a
                        // module const holding a conjunction.
                        self.bdd_first_col_preset = Some(self.current.col);
                        self.parse_bdd_clauses(&mut block);
                    } else if !Self::is_block_boundary(self.current.kind) {
                        self.restore_bdd_fallback(&mut block, start_children, entry);
                    }
                }
                Err(_) => {
                    self.restore_bdd_fallback(&mut block, start_children, entry);
                }
            }
        } else {
            // W896 (0004a): keyword-style bench went to skip_to_next_top_level
            // wholesale -- every assert under `bench name` was discarded while
            // tests and invariants had lowerings. The same shared clause parser
            // serves here: assert clauses lower; `measure:`/`target:` metadata
            // lines are not clauses and are skipped PER-CLAUSE with honest
            // token accounting (0003's granularity), instead of taking the
            // whole block down.
            self.parse_bdd_clauses(&mut block);
        }
        Ok(block)
    }
}

// ============================================================================
// Code Generator
// ============================================================================

pub struct Codegen {
    output: String,
    indent: u32,
    /// Locals reassigned somewhere in the current fn/test/bench body: Zig needs
    /// them declared `var`, and it ERRORS both on a mutated `const` and on a
    /// never-mutated `var` -- so the choice must be inferred, exactly like the
    /// Rust backend's collect_mutable_names.
    mut_names: std::collections::HashSet<String>,
    /// Names that already received `_ = &name;`. Zig treats that as a USE, so a
    /// later bare `_ = name;` is a "pointless discard of local variable" and the
    /// file stops compiling. W730 measured 9 of 130 generating specs hitting it.
    discarded_by_ref: std::collections::HashSet<String>,
    /// Names the enclosing Zig CONTAINER declares. A Zig parameter may not
    /// shadow one; t27 permits it (W734: fanout, clock_cfg, slack, diff_text
    /// each name a parameter after a FUNCTION in the same module).
    module_decl_names: std::collections::HashSet<String>,
    /// Parameter renames in force for the function being emitted. The `_arg`
    /// re-binding used for MUTABLE parameters cannot serve the shadow case --
    /// `var fanout = fanout_arg;` recreates the very collision it was meant to
    /// remove ("local variable shadows declaration"). So a shadowing parameter
    /// is renamed all the way through: signature AND every body reference.
    param_renames: std::collections::HashMap<String, String>,
    /// Functions the spec declares itself. Bare `abs(`/`sqrt(`/... are mapped
    /// to Zig builtins ONLY when absent from this set, so a spec that defines
    /// its own `fn max(...)` still calls its own.
    declared_fns: std::collections::HashSet<String>,
    /// How many times each test name has already been emitted. Zig requires
    /// test names to be unique within a file and rejects the whole file
    /// otherwise; four IGLA RACE specs accumulated colliding names across
    /// waves (`cordic_fixed_sin_zero_angle` appears seven times). Suffixing
    /// repeats keeps every test runnable instead of losing the file.
    test_name_counts: std::collections::HashMap<String, u32>,
    /// Declared parameter types, by function name. An anonymous list `.{ … }`
    /// coerces to `[N]T` but NOT to `[]T`, so an array-literal argument passed
    /// where the callee declares a slice needs `&[_]T{ … }` -- and the element
    /// type is only knowable from the callee's signature.
    declared_fn_params: std::collections::HashMap<String, Vec<String>>,
    /// Declared return type by function name, so a positional destructure of a
    /// NAMED-tuple return can be lowered to field accesses (W596).
    declared_fn_returns: std::collections::HashMap<String, String>,
    /// Locals bound to an array literal and later passed where a callee
    /// declares a SLICE, mapped to the element type the callee requires. Such a
    /// local must be a real `[_]T{ … }` array and be passed by reference; an
    /// anonymous `.{ … }` cannot coerce to `[]T`.
    slice_locals: std::collections::HashMap<String, String>,
    /// Locals bound to the undefined scaffold helpers `default_input()` /
    /// `valid_input()`, mapped to the Zig type their consumer declares.
    scaffold_locals: std::collections::HashMap<String, String>,
    /// W625: UNTYPED locals whose initializer is `.len`-tainted, so the binding
    /// is `usize` in Zig. Found by forcing analysis of the 14% of generated
    /// bodies nothing referenced (T21): `estimate_10k_size` in `coder/dataset`
    /// carries a length through FOUR untyped `const`s before returning it under
    /// `-> u32`, and W624's expression-local taint could not see it. A local
    /// with a DECLARED type never enters this set -- the W624 `let` rule
    /// already casts at the binding, so the name really is that type. See T23.
    len_locals: std::collections::HashSet<String>,
    /// Enum types the spec declares. Used to lower `<`/`>` on enum variants to
    /// a tag comparison -- Zig has no ordering on enums.
    declared_enums: std::collections::HashSet<String>,
    /// W609: `(struct, field) -> declared type`. The Zig backend collected
    /// struct field NAMES (for `string_names` / `float_names` / `signed_names`)
    /// but never their types, so a slice-typed field receiving an array literal
    /// got `.{ a, b }` -- which Zig rejects with "type '[]T' does not support
    /// array initialization syntax". 589 sites across 20 specs.
    struct_field_types: std::collections::HashMap<(String, String), String>,
    /// Field and parameter names the spec declares with a string type. Zig has
    /// no `==` for slices, and the literal-operand test cannot see
    /// `a.name == b.name`, where BOTH sides are `[]const u8` expressions.
    string_names: std::collections::HashSet<String>,
    /// Field and parameter names the spec declares with a float type, so a cast
    /// can pick `@floatCast` over `@floatFromInt` (W592).
    float_names: std::collections::HashSet<String>,
    /// Names the spec declares with a SIGNED integer type. Zig refuses `/` on
    /// signed integers -- the rounding mode must be explicit -- so a division
    /// with a known-signed operand is emitted as `@divTrunc` (W593).
    signed_names: std::collections::HashSet<String>,
    /// Declared return type of the function currently being emitted, so a
    /// returned array literal can be given the element type the signature
    /// requires (W593).
    current_return_type: String,
    /// W566: param/typed-local name -> t27 type, scoped to the current fn body.
    /// Lets ExprCast tell a narrowing integer cast (needs `@truncate`) from a
    /// widening one (needs `@intCast`) without a full type checker.
    zig_var_types: std::collections::HashMap<String, String>,
}

impl Codegen {
    pub fn new() -> Self {
        Self {
            output: String::new(),
            indent: 0,
            mut_names: std::collections::HashSet::new(),
            discarded_by_ref: std::collections::HashSet::new(),
            module_decl_names: std::collections::HashSet::new(),
            param_renames: std::collections::HashMap::new(),
            declared_fns: std::collections::HashSet::new(),
            test_name_counts: std::collections::HashMap::new(),
            declared_fn_params: std::collections::HashMap::new(),
            declared_fn_returns: std::collections::HashMap::new(),
            slice_locals: std::collections::HashMap::new(),
            scaffold_locals: std::collections::HashMap::new(),
            len_locals: std::collections::HashSet::new(),
            declared_enums: std::collections::HashSet::new(),
            struct_field_types: std::collections::HashMap::new(),
            string_names: std::collections::HashSet::new(),
            float_names: std::collections::HashSet::new(),
            signed_names: std::collections::HashSet::new(),
            current_return_type: String::new(),
            zig_var_types: std::collections::HashMap::new(),
        }
    }

    /// W566: bit-width of a t27 UNSIGNED integer type, or None otherwise.
    /// Restricted to unsigned because Zig's `@truncate` only lowers a narrowing
    /// cast cleanly when both sides are unsigned; signed narrowing stays on the
    /// checked `@intCast` path (its previous, working behaviour).
    fn zig_uint_bits(ty: &str) -> Option<u32> {
        match ty.trim() {
            "u8" => Some(8),
            "u16" => Some(16),
            "u32" => Some(32),
            "u64" | "usize" => Some(64),
            _ => None,
        }
    }

    /// W566: best-effort bit-width of an expression that is provably an UNSIGNED
    /// integer, using the param/typed-local map. Returns None when the type is
    /// signed or unknown, so the cast emission falls back to `@intCast`.
    fn zig_expr_uint_bits(&self, node: &Node) -> Option<u32> {
        match node.kind {
            NodeKind::ExprIdentifier => {
                let ty = self.zig_var_types.get(&node.name)?;
                Self::zig_uint_bits(ty)
            }
            NodeKind::ExprCast => {
                let target = node.extra_type.split('[').next().unwrap_or("").trim();
                Self::zig_uint_bits(target)
            }
            NodeKind::ExprLiteral => {
                let ty = node.extra_type.as_str();
                if ty.is_empty() {
                    None
                } else {
                    Self::zig_uint_bits(ty)
                }
            }
            NodeKind::ExprBinary => {
                // Shifts keep the left operand's width; other binary ops take the
                // wider of the two. Both operands must be provably unsigned.
                let op = node.extra_op.as_str();
                let l = node.children.first().and_then(|c| self.zig_expr_uint_bits(c));
                if matches!(op, "<<" | ">>") {
                    return l;
                }
                let r = node.children.get(1).and_then(|c| self.zig_expr_uint_bits(c));
                match (l, r) {
                    (Some(a), Some(b)) => Some(a.max(b)),
                    _ => None,
                }
            }
            _ => None,
        }
    }

    /// Find locals bound to an array literal that are later passed where a
    /// callee declares a slice, and record the element type the callee needs.
    ///
    /// `given inputs = [0, 0, 0, 0]` followed by `adder_tree(inputs)` emitted
    /// `const inputs = .{ 0, 0, 0, 0 };` and then
    /// "expected type '[]i32', found 'struct { comptime T = 0, ... }'". The
    /// element type is not in the literal -- only the callee's signature has
    /// it.
    /// W585: `default_input()` / `valid_input()` -- the template scaffold.
    ///
    /// 571 generated tests are shaped
    ///
    /// ```text
    /// test f_basic_case
    ///     given input = default_input()
    ///     when result = f(input)
    ///     then result != undefined
    /// ```
    ///
    /// and neither helper is defined anywhere. It has been the largest single
    /// blocker in three measurement systems at once -- 47 of 216 Zig compile
    /// failures, 75 of 296 C header failures, 29 of 32 `check-calls` findings
    /// -- since W561.
    ///
    /// The helper is not derivable from its own call: `default_input()` takes
    /// no arguments and returns whatever the NEXT line needs. But the next line
    /// is `f(input)`, and `f`'s parameter type is declared. So the binding's
    /// type is recoverable from the use, and the value the tests want is "a
    /// default one" -- `std.mem.zeroes(T)` exactly.
    ///
    /// Only bindings whose consumer is known are resolved; anything else is
    /// left alone and still fails loudly.
    fn collect_scaffold_locals(&mut self, stmts: &[Node]) {
        let mut scaffold: std::collections::HashSet<String> = std::collections::HashSet::new();
        Self::collect_scaffold_names(stmts, &mut scaffold);
        if scaffold.is_empty() {
            return;
        }
        let params = self.declared_fn_params.clone();
        let mut found: Vec<(String, String)> = Vec::new();
        Self::visit_calls(stmts, &mut |call: &Node| {
            let sig = match params.get(&call.name) {
                Some(s) => s,
                None => return,
            };
            for (i, arg) in call.children.iter().enumerate() {
                if arg.kind != NodeKind::ExprIdentifier || !scaffold.contains(&arg.name) {
                    continue;
                }
                if let Some(ty) = sig.get(i) {
                    let zig = Self::t27_array_type_to_zig(ty);
                    if !zig.is_empty() {
                        found.push((arg.name.clone(), zig));
                    }
                }
            }
        });
        for (name, ty) in found {
            self.scaffold_locals.insert(name, ty);
        }
    }

    fn collect_scaffold_names(stmts: &[Node], out: &mut std::collections::HashSet<String>) {
        for stmt in stmts {
            if matches!(stmt.kind, NodeKind::StmtLocal | NodeKind::StmtAssign)
                && !stmt.name.is_empty()
            {
                if let Some(init) = stmt.children.first() {
                    if init.kind == NodeKind::ExprCall
                        && init.children.is_empty()
                        && matches!(init.name.as_str(), "default_input" | "valid_input")
                    {
                        out.insert(stmt.name.clone());
                    }
                }
            }
            Self::collect_scaffold_names(&stmt.children, out);
        }
    }

    fn collect_slice_locals(&mut self, stmts: &[Node]) {
        let mut array_locals: std::collections::HashSet<String> = std::collections::HashSet::new();
        Self::collect_array_locals(stmts, &mut array_locals);
        if array_locals.is_empty() {
            return;
        }
        let params = self.declared_fn_params.clone();
        let mut found: Vec<(String, String)> = Vec::new();
        Self::visit_calls(stmts, &mut |call: &Node| {
            let sig = match params.get(&call.name) {
                Some(s) => s,
                None => return,
            };
            for (i, arg) in call.children.iter().enumerate() {
                if arg.kind != NodeKind::ExprIdentifier || !array_locals.contains(&arg.name) {
                    continue;
                }
                if let Some(ty) = sig.get(i) {
                    let zig = Self::t27_array_type_to_zig(ty);
                    if let Some(elem) = Self::slice_element_type(&zig) {
                        found.push((arg.name.clone(), elem));
                    }
                }
            }
        });
        for (name, elem) in found {
            self.slice_locals.insert(name, elem);
        }
    }

    fn collect_array_locals(stmts: &[Node], out: &mut std::collections::HashSet<String>) {
        for stmt in stmts {
            if matches!(stmt.kind, NodeKind::StmtLocal | NodeKind::StmtAssign)
                && !stmt.name.is_empty()
                && stmt
                    .children
                    .first()
                    .map(|c| c.kind == NodeKind::ExprArrayLiteral)
                    .unwrap_or(false)
            {
                out.insert(stmt.name.clone());
            }
            Self::collect_array_locals(&stmt.children, out);
        }
    }

    fn visit_calls(nodes: &[Node], f: &mut impl FnMut(&Node)) {
        for n in nodes {
            if n.kind == NodeKind::ExprCall {
                f(n);
            }
            Self::visit_calls(&n.children, f);
        }
    }

    /// Emit an array literal's elements as `{ e0, e1 }` -- the braces that
    /// follow an explicit `[_]T` prefix, where `.{ … }` cannot be used.
    fn gen_array_literal_braces(&mut self, node: &Node) {
        self.write("{ ");
        if !node.children.is_empty() {
            for (i, elem) in node.children.iter().enumerate() {
                if i > 0 {
                    self.write(", ");
                }
                self.gen_expr(elem);
            }
        } else {
            let txt = node.extra_size.trim();
            let mut depth = 0i32;
            let mut cur = String::new();
            let mut parts: Vec<String> = Vec::new();
            for ch in txt.chars() {
                match ch {
                    '(' | '[' | '{' => { depth += 1; cur.push(ch); }
                    ')' | ']' | '}' => { depth -= 1; cur.push(ch); }
                    ',' if depth == 0 => { parts.push(cur.trim().to_string()); cur.clear(); }
                    _ => cur.push(ch),
                }
            }
            if !cur.trim().is_empty() {
                parts.push(cur.trim().to_string());
            }
            self.write(&parts.join(", "));
        }
        self.write(" }");
    }

    /// Locals a block declares with one of the given explicit types.
    fn collect_typed_locals(stmts: &[Node], types: &[&str]) -> Vec<String> {
        let mut out = Vec::new();
        for stmt in stmts {
            if stmt.kind == NodeKind::StmtLocal
                && !stmt.name.is_empty()
                && types.contains(&stmt.extra_type.trim())
            {
                out.push(stmt.name.clone());
            }
            out.extend(Self::collect_typed_locals(&stmt.children, types));
        }
        out
    }

    /// Locals a block declares with an explicit float type.
    fn collect_float_locals(stmts: &[Node]) -> Vec<String> {
        let mut out = Vec::new();
        for stmt in stmts {
            if stmt.kind == NodeKind::StmtLocal
                && !stmt.name.is_empty()
                && matches!(
                    stmt.extra_type.trim(),
                    "f16" | "f32" | "f64" | "float" | "double"
                )
            {
                out.push(stmt.name.clone());
            }
            out.extend(Self::collect_float_locals(&stmt.children));
        }
        out
    }

    /// The slice element types a return type requires, one per tuple position
    /// (`None` where that position is not a slice). Returns `None` when the
    /// return type is not a slice or a tuple.
    fn return_slice_elements(ret: &str) -> Option<Vec<Option<String>>> {
        let t = ret.trim();
        if t.starts_with('(') && t.ends_with(')') && t.contains(',') {
            let inner = &t[1..t.len() - 1];
            let elems: Vec<Option<String>> = inner
                .split(',')
                .map(|e| Self::slice_element_type(&Self::t27_array_type_to_zig(e.trim())))
                .collect();
            return if elems.iter().any(|e| e.is_some()) {
                Some(elems)
            } else {
                None
            };
        }
        Self::slice_element_type(&Self::t27_array_type_to_zig(t)).map(|e| vec![Some(e)])
    }

    /// `[]T` / `[]const T` -> `T`, for an argument that must be a real slice.
    fn slice_element_type(ty: &str) -> Option<String> {
        let t = ty.trim();
        let rest = t.strip_prefix("[]")?;
        let rest = rest.trim();
        let rest = rest.strip_prefix("const ").unwrap_or(rest).trim();
        // W607: a STRING element is itself a slice, so `[][]const u8` has
        // element type `[]const u8` -- which contains `[` and was rejected by
        // the nested-array guard below. That made every array-of-strings skip
        // the `@constCast(&[_]T{...})` lowering that array-of-numbers gets.
        if rest == "[]const u8" || rest == "[]u8" {
            return Some(rest.to_string());
        }
        if rest.is_empty() || rest.contains('[') || rest.contains('(') {
            return None;
        }
        Some(rest.to_string())
    }

    /// The trailing segment of an identifier / field-access path, i.e. the
    /// field actually being read: `a.b.name` -> `name`.
    fn trailing_name(node: &Node) -> Option<String> {
        match node.kind {
            NodeKind::ExprIdentifier => node
                .name
                .rsplit(['.', ':'])
                .next()
                .filter(|s| !s.is_empty())
                .map(|s| s.to_string()),
            NodeKind::ExprFieldAccess => Some(node.name.clone()).filter(|s| !s.is_empty()),
            _ => None,
        }
    }

    /// Whether an expression is definitely floating-point: a literal with a
    /// decimal point, or a name the spec declared `f32`/`f64`. Used to pick the
    /// right Zig cast builtin; anything undecidable is treated as integer,
    /// which is what the corpus overwhelmingly casts FROM.
    fn is_float_expr(&self, node: &Node) -> bool {
        match node.kind {
            NodeKind::ExprLiteral => {
                node.extra_kind != "string" && node.value.contains('.')
            }
            NodeKind::ExprIdentifier | NodeKind::ExprFieldAccess => {
                Self::trailing_name(node)
                    .map(|n| self.float_names.contains(&n))
                    .unwrap_or(false)
            }
            NodeKind::ExprBinary => node
                .children
                .iter()
                .any(|c| self.is_float_expr(c)),
            _ => false,
        }
    }

    /// Whether an expression is definitely a signed integer: a name the spec
    /// declared `i8`..`isize`, or a cast to one. Undecidable cases are treated
    /// as not-signed, which leaves `/` untouched.
    fn is_signed_int_expr(&self, node: &Node) -> bool {
        match node.kind {
            NodeKind::ExprIdentifier | NodeKind::ExprFieldAccess => {
                Self::trailing_name(node)
                    .map(|n| self.signed_names.contains(&n))
                    .unwrap_or(false)
            }
            NodeKind::ExprCast => matches!(
                node.extra_type.trim(),
                "i8" | "i16" | "i32" | "i64" | "isize"
            ),
            NodeKind::ExprBinary => node
                .children
                .iter()
                .any(|c| self.is_signed_int_expr(c)),
            _ => false,
        }
    }

    fn is_string_typed(&self, node: &Node) -> bool {
        Self::trailing_name(node)
            .map(|n| self.string_names.contains(&n))
            .unwrap_or(false)
    }

    /// True for `Enum::Variant` / `Enum.Variant` where `Enum` is declared in
    /// this spec, and for a bare `.Variant` enum-value node.
    fn is_enum_variant(&self, node: &Node) -> bool {
        if node.kind == NodeKind::ExprEnumValue {
            return true;
        }
        // `Enum.Variant` also parses as a field access on the type name.
        if node.kind == NodeKind::ExprFieldAccess {
            return node
                .children
                .first()
                .map(|base| self.is_enum_type_name(base))
                .unwrap_or(false);
        }
        if node.kind != NodeKind::ExprIdentifier {
            return false;
        }
        let root = node.name.split("::").next().unwrap_or("");
        let root = root.split('.').next().unwrap_or("");
        !root.is_empty() && self.declared_enums.contains(root)
    }

    fn is_enum_type_name(&self, node: &Node) -> bool {
        node.kind == NodeKind::ExprIdentifier && self.declared_enums.contains(&node.name)
    }

    /// W599: render an expression to its generated text WITHOUT emitting it.
    /// Used to label an assertion's operands with the code the author wrote.
    fn render_expr(&mut self, node: &Node) -> String {
        let mark = self.output.len();
        self.gen_expr(node);
        let text = self.output[mark..].to_string();
        self.output.truncate(mark);
        text
    }

    /// W599: the comparisons at the leaves of an assertion condition, in source
    /// order. `a < b && c == d` yields both. A condition with no comparison at
    /// all yields nothing, and the caller falls back to the bare panic.
    fn assert_comparisons<'a>(node: &'a Node, out: &mut Vec<&'a Node>) {
        if node.kind != NodeKind::ExprBinary || node.children.len() < 2 {
            return;
        }
        match node.extra_op.as_str() {
            "and" | "or" | "&&" | "||" => {
                for c in &node.children {
                    Self::assert_comparisons(c, out);
                }
            }
            "==" | "!=" | "<" | ">" | "<=" | ">=" => out.push(node),
            _ => {}
        }
    }

    /// Escape generated Zig source so it can sit inside a Zig format string.
    fn escape_for_fmt(s: &str) -> String {
        let mut out = String::with_capacity(s.len() + 8);
        for c in s.chars() {
            match c {
                '{' => out.push_str("{{"),
                '}' => out.push_str("}}"),
                '"' => out.push_str("\\\""),
                '\\' => out.push_str("\\\\"),
                '\n' | '\r' | '\t' => out.push(' '),
                c => out.push(c),
            }
        }
        out
    }

    fn write(&mut self, s: &str) {
        self.output.push_str(s);
    }

    fn write_line(&mut self, s: &str) {
        self.write(s);
        self.write("\n");
    }

    fn indent(&mut self) {
        self.indent += 1;
    }

    fn dedent(&mut self) {
        if self.indent > 0 {
            self.indent -= 1;
        }
    }

    fn write_indent(&mut self) {
        for _ in 0..self.indent {
            self.write("    ");
        }
    }

    pub fn gen_zig(&mut self, ast: &Node) {
        // Collect the spec's own function names before emitting anything, so
        // the builtin mapping below can never shadow a user-defined function.
        self.declared_fns.clear();
        self.test_name_counts.clear();
        self.declared_enums.clear();
        self.declared_fn_params.clear();
        self.declared_fn_returns.clear();
        self.string_names.clear();
        self.float_names.clear();
        self.signed_names.clear();
        for d in &ast.children {
            match d.kind {
                NodeKind::FnDecl if !d.name.is_empty() => {
                    self.declared_fns.insert(d.name.clone());
                    self.declared_fn_params.insert(
                        d.name.clone(),
                        d.params.iter().map(|(_, ty)| ty.clone()).collect(),
                    );
                    self.declared_fn_returns
                        .insert(d.name.clone(), d.extra_return_type.clone());
                    // W594: parameters are per-FUNCTION facts. Collecting them
                    // corpus-wide meant a parameter `a: i32` in one function
                    // made every `a` signed everywhere -- harmless for
                    // `@divTrunc`, which is valid for unsigned operands too,
                    // but not a property the next predicate can rely on. They
                    // are now collected in `gen_fn_decl` and dropped on exit;
                    // struct FIELDS stay global, because a field name belongs
                    // to a type that is itself global.
                }
                NodeKind::EnumDecl if !d.name.is_empty() => {
                    self.declared_enums.insert(d.name.clone());
                }
                NodeKind::StructDecl => {
                    for f in &d.children {
                        // W609: record the field's declared type, keyed by the
                        // OWNING struct -- unlike the name sets beside it, which
                        // are global and therefore cannot tell two structs'
                        // same-named fields apart.
                        if !d.name.is_empty() && !f.name.is_empty() && !f.extra_type.is_empty() {
                            self.struct_field_types
                                .insert((d.name.clone(), f.name.clone()), f.extra_type.clone());
                        }
                        if Self::t27_array_type_to_zig(&f.extra_type) == "[]const u8" {
                            self.string_names.insert(f.name.clone());
                        }
                        if matches!(
                            f.extra_type.trim(),
                            "f16" | "f32" | "f64" | "float" | "double"
                        ) {
                            self.float_names.insert(f.name.clone());
                        }
                        if matches!(f.extra_type.trim(), "i8" | "i16" | "i32" | "i64" | "isize") {
                            self.signed_names.insert(f.name.clone());
                        }
                    }
                }
                _ => {}
            }
        }

        // Header with module name
        let module_name = if !ast.name.is_empty() {
            &ast.name
        } else {
            "unknown"
        };
        self.write_line(&format!(
            "// Generated from t27 spec: {} (module name)",
            module_name
        ));
        self.write_line("// DO NOT EDIT — generated by t27c");
        self.write_line("// phi^2 + 1/phi^2 = 3 | TRINITY");
        self.write_line("");

        // Check if file has test blocks — emit std import if so
        // W601: an INVARIANT block emits assertions too, and a spec may have
        // invariants and no tests -- specs/numeric/gf*.t27 are exactly that.
        // Gating the helper on TestBlock alone left those files referencing an
        // `__t27_assert_fail` that was never emitted. The condition must match
        // "will this file contain an assertion", not "does it have tests".
        let has_tests = ast
            .children
            .iter()
            .any(|d| d.kind == NodeKind::TestBlock || d.kind == NodeKind::InvariantBlock);
        if has_tests {
            self.write_line("const std = @import(\"std\");");
            // W599: a failing assertion must report the VALUES it saw, not only
            // that it failed. This is a fn rather than an inline block because
            // the assert site is emitted as an expression and a `{ ... };` is
            // not a Zig statement; `noreturn` keeps it usable in that position.
            self.write_line(
                "fn __t27_assert_fail(comptime fmt: []const u8, args: anytype) noreturn {",
            );
            // W599 (second attempt): `std.debug.print` is not callable at
            // comptime, and this corpus DOES fold assertions there -- T4's and
            // T5's disproved invariants are exactly that. The first version
            // turned their clear `encountered @panic at comptime` into an
            // opaque error inside std.Io.Threaded. @inComptime() keeps each
            // context's own diagnostic.
            self.write_line("    if (@inComptime()) {");
            self.write_line("        @compileError(\"assertion failed\");");
            self.write_line("    } else {");
            self.write_line("        std.debug.print(fmt, args);");
            self.write_line("        @panic(\"assertion failed\");");
            self.write_line("    }");
            self.write_line("}");
            self.write_line("");
        }

        // Emit @import for UseDecl nodes first -- but only when the module body
        // actually references `<name>.something`. `use base::types` is semantic
        // noise for the Zig backend, and an import of a file that is never
        // shipped alongside the gen (types.zig) made every generated file fail
        // `zig test` with FileNotFound before a single test ran.
        fn module_referenced(nodes: &[Node], module: &str) -> bool {
            nodes.iter().any(|n| {
                (n.kind == NodeKind::ExprFieldAccess
                    && n.children
                        .first()
                        .is_some_and(|b| b.kind == NodeKind::ExprIdentifier && b.name == module))
                    || (n.kind == NodeKind::ExprCall && n.name.starts_with(&format!("{}.", module)))
                    || module_referenced(&n.children, module)
            })
        }
        let mut has_imports = false;
        for decl in &ast.children {
            if decl.kind == NodeKind::UseDecl {
                if module_referenced(&ast.children, &decl.name) {
                    self.write_line(&format!(
                        "const {} = @import(\"{}.zig\");",
                        decl.name, decl.name
                    ));
                    has_imports = true;
                } else {
                    self.write_line(&format!("// use {}: no references in this module", decl.name));
                }
            }
        }
        if has_imports {
            self.write_line("");
        }

        // W735: know the container's declarations BEFORE emitting any function.
        self.collect_module_decl_names(&ast.children);

        // Emit other declarations
        for decl in &ast.children {
            if decl.kind != NodeKind::UseDecl {
                self.gen_decl(decl);
            }
        }
    }

    /// Generate Zig code with project-aware import resolution.
    /// `current_rel_path` is e.g. "base/types" (the file being generated).
    /// `module_map` maps "namespace::module" → "namespace/module".
    pub fn gen_zig_project(
        &mut self,
        ast: &Node,
        current_rel_path: &str,
        module_map: &std::collections::HashMap<String, String>,
    ) {
        // Header
        let module_name = if !ast.name.is_empty() {
            &ast.name
        } else {
            "unknown"
        };
        self.write_line(&format!(
            "// Generated from t27 spec: {} (module name)",
            module_name
        ));
        self.write_line("// DO NOT EDIT — generated by t27c compile-project");
        self.write_line("// phi^2 + 1/phi^2 = 3 | TRINITY");
        self.write_line("");

        // Check if file has test blocks — emit std import if so
        // W601: an INVARIANT block emits assertions too, and a spec may have
        // invariants and no tests -- specs/numeric/gf*.t27 are exactly that.
        // Gating the helper on TestBlock alone left those files referencing an
        // `__t27_assert_fail` that was never emitted. The condition must match
        // "will this file contain an assertion", not "does it have tests".
        let has_tests = ast
            .children
            .iter()
            .any(|d| d.kind == NodeKind::TestBlock || d.kind == NodeKind::InvariantBlock);
        if has_tests {
            self.write_line("const std = @import(\"std\");");
            // W599: a failing assertion must report the VALUES it saw, not only
            // that it failed. This is a fn rather than an inline block because
            // the assert site is emitted as an expression and a `{ ... };` is
            // not a Zig statement; `noreturn` keeps it usable in that position.
            self.write_line(
                "fn __t27_assert_fail(comptime fmt: []const u8, args: anytype) noreturn {",
            );
            // W599 (second attempt): `std.debug.print` is not callable at
            // comptime, and this corpus DOES fold assertions there -- T4's and
            // T5's disproved invariants are exactly that. The first version
            // turned their clear `encountered @panic at comptime` into an
            // opaque error inside std.Io.Threaded. @inComptime() keeps each
            // context's own diagnostic.
            self.write_line("    if (@inComptime()) {");
            self.write_line("        @compileError(\"assertion failed\");");
            self.write_line("    } else {");
            self.write_line("        std.debug.print(fmt, args);");
            self.write_line("        @panic(\"assertion failed\");");
            self.write_line("    }");
            self.write_line("}");
            self.write_line("");
        }

        // Emit @import for UseDecl nodes with resolved paths
        let mut has_imports = false;
        for decl in &ast.children {
            if decl.kind == NodeKind::UseDecl {
                let import_path = resolve_import_path(
                    &decl.value, // e.g. "base::types"
                    &decl.name,  // e.g. "types"
                    current_rel_path,
                    module_map,
                );
                self.write_line(&format!(
                    "const {} = @import(\"{}\");",
                    decl.name, import_path
                ));
                has_imports = true;
            }
        }
        if has_imports {
            self.write_line("");
        }

        // Emit other declarations
        for decl in &ast.children {
            if decl.kind != NodeKind::UseDecl {
                self.gen_decl(decl);
            }
        }
    }

    pub fn into_string(self) -> String {
        self.output
    }

    /// Collect the names the Zig container will declare, so a parameter cannot
    /// silently shadow one. Called once per module walk.
    fn collect_module_decl_names(&mut self, decls: &[Node]) {
        self.module_decl_names.clear();
        for d in decls {
            if matches!(
                d.kind,
                NodeKind::FnDecl | NodeKind::ConstDecl | NodeKind::StructDecl | NodeKind::EnumDecl
            ) && !d.name.is_empty()
            {
                self.module_decl_names.insert(d.name.clone());
            }
        }
    }

    /// Apply any rename in force for the function being emitted.
    fn renamed(&self, n: &str) -> String {
        self.param_renames.get(n).cloned().unwrap_or_else(|| n.to_string())
    }

    /// Local declarations in a FN BODY whose name collides with a container
    /// declaration. W736 measured ten specs where Zig answers "local variable
    /// shadows declaration of 'x'". Renaming every occurrence inside the
    /// function is safe precisely BECAUSE Zig forbids the shadow: the spec
    /// cannot also be calling the module-level name from here.
    ///
    /// SCOPE, and it is a real limit: only `StmtLocal` is collected. Inside a
    /// test or bench block the same source line parses as `StmtAssign`, and
    /// extending this to cover that was attempted and REVERTED -- it renamed
    /// references while the binding site kept its old name, turning a shadow
    /// error into "use of undeclared identifier", which is worse. Nine specs
    /// still carry the defect and they are named in T271.
    fn collect_shadowing_locals(
        decls: &[Node],
        module_names: &std::collections::HashSet<String>,
        out: &mut Vec<String>,
    ) {
        for d in decls {
            if matches!(d.kind, NodeKind::StmtLocal)
                && !d.name.is_empty()
                && module_names.contains(d.name.as_str())
                && !out.contains(&d.name)
            {
                out.push(d.name.clone());
            }
            Self::collect_shadowing_locals(&d.children, module_names, out);
        }
    }

    fn gen_decl(&mut self, node: &Node) {
        match node.kind {
            NodeKind::ConstDecl => self.gen_const_decl(node),
            NodeKind::EnumDecl => self.gen_enum_decl(node),
            NodeKind::StructDecl => self.gen_struct_decl(node),
            NodeKind::FnDecl => self.gen_fn_decl(node),
            NodeKind::TestBlock => self.gen_test_block(node),
            NodeKind::InvariantBlock => self.gen_invariant_block(node),
            NodeKind::BenchBlock => self.gen_bench_block(node),
            _ => {}
        }
    }

    fn gen_const_decl(&mut self, node: &Node) {
        if node.extra_pub {
            self.write("pub ");
        }

        // W729: `pub const GFTernary = u8;` is a TYPE ALIAS, and the identifier
        // on the right is the builtin type, not a name to look up. `zig_ident`
        // escapes primitives as `@"u8"` -- correct for something NAMED u8,
        // fatal here: Zig reports `use of undeclared identifier 'u8'` and the
        // whole spec stops compiling, so its 18 test blocks had never run.
        // The C backend has detected this pattern since it was written
        // (`typedef uint8_t GFTernary;`); the Zig backend never did.
        if node.children.len() == 1
            && node.children[0].kind == NodeKind::ExprIdentifier
            && {
                // Same predicate `zig_ident` uses to decide something is a
                // builtin type name -- uN/iN/fN plus the named primitives.
                let n = &node.children[0].name;
                matches!(
                    n.as_str(),
                    "bool" | "void" | "type" | "usize" | "isize"
                        | "comptime_int" | "comptime_float"
                ) || (n.len() >= 2
                    && (n.starts_with('u') || n.starts_with('i') || n.starts_with('f'))
                    && n[1..].chars().all(|c| c.is_ascii_digit()))
            }
        {
            self.write_line(&format!("const {} = {};", node.name, node.children[0].name));
            return;
        }

        // A module-level `var` is MUTABLE. The parser records that in
        // `extra_mutable`, and the Zig local path already branches on it
        // (`var` vs `const`); this path never did, so a spec that assigns to a
        // module-level name emitted `const` and Zig refused the assignment.
        // gen-verilog got this right all along -- it emits a `reg`.
        let kw = if node.extra_mutable { "var" } else { "const" };
        self.write(&format!("{} {}", kw, node.name));

        if !node.extra_type.is_empty() {
            self.write(&format!(": {}", Self::t27_array_type_to_zig(&node.extra_type)));
        }

        if !node.children.is_empty() {
            self.write(" = ");
            self.gen_expr(&node.children[0]);
        }

        self.write_line(";");
    }

    fn gen_enum_decl(&mut self, node: &Node) {
        if node.extra_pub {
            self.write("pub ");
        }

        self.write(&format!("const {} = enum", node.name));

        if !node.extra_type.is_empty() {
            self.write(&format!("({})", node.extra_type));
        } else if node.children.iter().any(|v| !v.value.is_empty()) {
            // Zig requires an integer tag type as soon as ANY variant carries
            // an explicit value ("explicitly valued enum missing integer tag
            // type"). t27 lets the backing type be omitted, so supply the
            // widest safe default rather than dropping the values.
            self.write("(i32)");
        }

        self.write_line(" {");
        self.indent();

        for value_node in node.children.iter() {
            self.write_indent();
            // Enum variant names need the same keyword escaping as any other
            // identifier: a variant literally called `error` emitted
            // `error = 4,` and Zig reported "expected '.', found '='".
            if !value_node.value.is_empty() {
                self.write(&format!(
                    "{} = {},",
                    Self::zig_ident(&value_node.name),
                    value_node.value
                ));
            } else {
                self.write(&format!("{},", Self::zig_ident(&value_node.name)));
            }
            self.write_line("");
        }

        self.dedent();
        self.write_line("};");
    }

    fn gen_struct_decl(&mut self, node: &Node) {
        if node.extra_pub {
            self.write("pub ");
        }

        self.write_line(&format!("const {} = struct {{", node.name));
        self.indent();

        for field in &node.children {
            self.write_indent();
            // Struct field types were emitted RAW, so `str` and `&str` reached
            // Zig unchanged -- the remaining "expected type expression, found
            // '&'" class after the W561 parameter-side fix. Route them through
            // the same mapper.
            let ty = if !field.extra_type.is_empty() {
                Self::t27_array_type_to_zig(&field.extra_type)
            } else {
                "void".to_string()
            };
            self.write(&format!("{}: {}", Self::zig_ident(&field.name), ty));
            // A field default is stored as the field's only child (W568).
            if let Some(default) = field.children.first() {
                self.write(" = ");
                self.gen_expr(default);
            }
            self.write_line(",");
        }

        self.dedent();
        self.write_line("};");
    }

    /// Map a t27 tuple type `(T, U, ...)` to a Zig anonymous tuple-struct type
    /// `struct { T, U, ... }`. Returns None for non-tuple types.
    /// Convert a t27/Rust-style array type `[T; N]` (N a literal or const name)
    /// to Zig's `[N]T`. Nested arrays convert recursively; other types pass
    /// through unchanged.
    // Default integer type for a bare integer literal initializing an untyped
    // mutable local (Zig rejects `var x = <comptime_int>`). u32 is the t27
    // default width; u64 only when the literal does not fit u32. Non-integer
    // literals (bool, string) already carry a concrete Zig type.
    // A spec identifier that collides with a Zig primitive type name (sha
    // round locals like f16/f32/f64) must be emitted as @"name" -- Zig
    // rejects the bare name with "name shadows primitive". Applied at every
    // value-identifier emission site so declarations and uses stay consistent.
    fn is_integer_type_suffix(t: &str) -> bool {
        matches!(
            t,
            "i8" | "i16" | "i32" | "i64" | "isize" | "u8" | "u16" | "u32" | "u64" | "usize"
        )
    }

    fn is_numeric_type_suffix(t: &str) -> bool {
        Self::is_integer_type_suffix(t) || matches!(t, "f32" | "f64")
    }

    /// Re-escape a string the lexer already unescaped, so it can be written
    /// back between quotes.
    fn zig_escape(raw: &str) -> String {
        let mut out = String::with_capacity(raw.len());
        for c in raw.chars() {
            match c {
                '\\' => out.push_str("\\\\"),
                '"' => out.push_str("\\\""),
                '\n' => out.push_str("\\n"),
                '\r' => out.push_str("\\r"),
                '\t' => out.push_str("\\t"),
                _ => out.push(c),
            }
        }
        out
    }

    fn zig_ident(name: &str) -> String {
        // t27 spells scoped names Rust-style (`Severity::Error`,
        // `base::types`). Zig has no `::`, and emitting it verbatim gave
        // "expected ';' after statement" pointing at the second colon -- the
        // whole remaining `expected ';'` class in W568. Each segment is
        // escaped on its own so `Foo::error` still becomes `Foo.@"error"`.
        if name.contains("::") {
            return name
                .split("::")
                .map(Self::zig_ident)
                .collect::<Vec<_>>()
                .join(".");
        }

        let is_primitive = matches!(
            name,
            "bool"
                | "void"
                | "type"
                | "anyerror"
                | "anyframe"
                | "noreturn"
                | "usize"
                | "isize"
                | "comptime_int"
                | "comptime_float"
        ) || (name.len() >= 2
            && (name.starts_with('u') || name.starts_with('i') || name.starts_with('f'))
            && name[1..].chars().all(|c| c.is_ascii_digit()));
        // Zig KEYWORDS also need escaping, not just primitive type names.
        // `error` is the one that actually appears in these specs -- as an enum
        // variant and as a struct field -- and it produced
        // "expected '.', found '='" / "expected '.', found ':'".
        let is_keyword = matches!(
            name,
            "align" | "allowzero" | "and" | "anyframe" | "anytype" | "asm" | "async"
                | "await" | "break" | "callconv" | "catch" | "comptime" | "const"
                | "continue" | "defer" | "else" | "enum" | "errdefer" | "error"
                | "export" | "extern" | "fn" | "for" | "if" | "inline" | "linksection"
                | "noalias" | "noinline" | "nosuspend" | "opaque" | "or" | "orelse"
                | "packed" | "pub" | "resume" | "return" | "struct" | "suspend"
                | "switch" | "test" | "threadlocal" | "try" | "union"
                | "unreachable" | "usingnamespace" | "var" | "volatile" | "while"
        );
        // W730: primitives are NOT escaped. `@"f64"` and `@"u8"` are lookups of
        // an identifier that does not exist, so `@as(@"f64", ...)` and
        // `pub const X = @"u8";` both stop the file compiling -- measured on 8
        // of 130 generating specs. Escaping would only be right for a spec that
        // NAMES a field or variant after a primitive, and a corpus-wide search
        // found none. Zig KEYWORDS still need it: `error` appears as an enum
        // variant and as a struct field, and produced "expected '.', found '='".
        let _ = is_primitive;
        if is_keyword {
            format!("@\"{}\"", name)
        } else {
            name.to_string()
        }
    }

    fn zig_int_literal_default_type(init: &Node) -> Option<&'static str> {
        if !matches!(init.kind, NodeKind::ExprLiteral) {
            return None;
        }
        if init.extra_kind == "string" {
            return None;
        }
        // A DECLARED width beats an inferred one. `1u64 << mant_bits` was
        // lowered as `@as(u32, 1) << ...` because the suffix was consumed by
        // the lexer and never recorded, so the width was re-invented from the
        // literal's magnitude: `1` fits in u32, therefore u32. Zig accepts the
        // result -- the u32 coerces to the u64 return type -- and `mask(39)`
        // panics with `integer does not fit in destination type` instead of
        // returning 549755813887.
        match init.extra_type.as_str() {
            "u8" => return Some("u8"),
            "u16" => return Some("u16"),
            "u32" => return Some("u32"),
            "u64" => return Some("u64"),
            "usize" => return Some("usize"),
            "i8" => return Some("i8"),
            "i16" => return Some("i16"),
            "i32" => return Some("i32"),
            "i64" => return Some("i64"),
            "isize" => return Some("isize"),
            _ => {}
        }
        let v = init.value.as_str();
        if v == "true" || v == "false" {
            return None;
        }
        let digits = v.replace('_', "");
        let parsed = if let Some(hex) = digits.strip_prefix("0x").or(digits.strip_prefix("0X")) {
            u64::from_str_radix(hex, 16)
        } else if let Some(bin) = digits.strip_prefix("0b").or(digits.strip_prefix("0B")) {
            u64::from_str_radix(bin, 2)
        } else {
            digits.parse::<u64>()
        };
        match parsed {
            Ok(n) if n <= u32::MAX as u64 => Some("u32"),
            Ok(_) => Some("u64"),
            Err(_) => None,
        }
    }

    fn t27_array_type_to_zig(ty: &str) -> String {
        let t = ty.trim();
        // W590: a slice OF a mapped scalar -- `[]string`, `[]str`. The scalar
        // mapping below only ever saw the whole type, so `string` was mapped
        // and `[]string` was not, and Zig received `[]string` -> "use of
        // undeclared identifier 'string'". Found by decomposing the largest
        // failure class: it looked like a missing import and was a mapper gap.
        if let Some(inner) = t.strip_prefix("[]") {
            let inner = inner.trim();
            if !inner.is_empty() && !inner.starts_with('[') {
                let mapped_inner = Self::t27_array_type_to_zig(inner);
                if mapped_inner != inner {
                    return format!("[]{}", mapped_inner);
                }
            }
        }
        // W732: t27 spells a slice `[T]`; Zig spells it `[]T`. The bare form was
        // emitted VERBATIM into parameter and return positions, where Zig
        // answers "expected type expression" -- 11 of the 12 specs in that
        // class, measured by decomposing it rather than guessing: `[string]`,
        // `[u8]`, `[BootStage]`, `[ConnEdge]`, `[TimingArc]`, `[str]`, `[Item]`.
        // `[T; N]` (sized) and `[]T` (already Zig) are handled below and above.
        if t.starts_with('[') && t.ends_with(']') && !t.contains(';') {
            let inner = t[1..t.len() - 1].trim();
            // `[str:str]` is a MAP in t27, not a slice; leave it alone rather
            // than emit a slice of something that does not exist.
            if !inner.is_empty() && !inner.contains(':') {
                return format!("[]{}", Self::t27_array_type_to_zig(inner));
            }
        }
        if t.starts_with('[') && t.ends_with(']') && t.contains(';') {
            let inner = &t[1..t.len() - 1];
            if let Some(semi) = inner.rfind(';') {
                let elem = Self::t27_array_type_to_zig(&inner[..semi]);
                let len = inner[semi + 1..].trim();
                return format!("[{}]{}", len, elem);
            }
        }

        // Scalar mapping. Everything else (u8, i32, bool, []T, user types) is
        // already spelled the same in Zig and passes through unchanged -- but
        // `str` is not a Zig type, and emitting it verbatim produced
        // `use of undeclared identifier 'str'`, the single largest gen-zig
        // defect class measured in Wave 560. The Rust emitter has always mapped
        // it (`str` -> `String`); the Zig emitter never did.
        //
        // `&str` additionally leaked Rust's borrow syntax into Zig output,
        // giving `expected type expression, found '&'`.
        let (prefix, core) = if let Some(rest) = t.strip_prefix('?') {
            ("?", rest.trim())
        } else {
            ("", t)
        };
        let core = core.strip_prefix('&').unwrap_or(core).trim();
        let mapped = match core {
            // `str` and `string` are both spelled in the corpus; neither is a
            // Zig type. `string` alone appears 952 times as a declared type.
            "str" | "string" => "[]const u8",
            // W591: `float` is not a Zig type. Same family as the `f32`/`f64`
            // gap W583 found on the C side -- a scalar the corpus spells and
            // the mapper never learned, so it passed through the `other` arm
            // and reached the backend verbatim.
            "float" => "f64",
            "double" => "f64",
            "int" => "i32",
            "uint" => "u32",
            other => other,
        };
        // W588: a SCOPED type name in a type position -- `const PHI: gf16::GF16`.
        // `zig_ident` has mapped `::` to `.` for identifiers since W580, but the
        // type path never went through it, so Zig received `gf16::GF16` and
        // reported "expected ';' after declaration" pointing at the second colon.
        if mapped.contains("::") {
            return format!("{}{}", prefix, mapped.replace("::", "."));
        }
        if mapped == core && prefix.is_empty() && !t.starts_with('&') {
            return t.to_string();
        }
        format!("{}{}", prefix, mapped)
    }

    fn t27_tuple_type_to_zig(ty: &str) -> Option<String> {
        let t = ty.trim();
        if t.starts_with('(') && t.ends_with(')') && t.contains(',') {
            let inner = &t[1..t.len() - 1];
            let elems: Vec<&str> = inner.split(',').map(|e| e.trim()).collect();
            // W596: a NAMED tuple -- `(sin: []f32, cos: []f32)`. t27 has had the
            // syntax since at least W584, and the backend dropped the names, so
            // a spec declaring one and accessing `result.sin` failed with "no
            // field named 'sin' in tuple". Zig spells the named form
            // `struct { sin: []f32, cos: []f32 }`, which is the same
            // declaration with its element types mapped.
            if let Some(fields) = Self::tuple_field_names(t) {
                let decls: Vec<String> = fields
                    .iter()
                    .map(|(n, ty)| {
                        format!("{}: {}", Self::zig_ident(n), Self::t27_array_type_to_zig(ty))
                    })
                    .collect();
                return Some(format!("struct {{ {} }}", decls.join(", ")));
            }
            let mapped: Vec<String> = elems
                .iter()
                .map(|e| Self::t27_array_type_to_zig(e))
                .collect();
            Some(format!("struct {{ {} }}", mapped.join(", ")))
        } else {
            None
        }
    }

    /// `(sin: f32, cos: f32)` -> `[("sin", "f32"), ("cos", "f32")]`.
    /// `None` unless EVERY element carries a name, so a positional tuple and a
    /// half-named one both keep their existing lowering.
    fn tuple_field_names(ty: &str) -> Option<Vec<(String, String)>> {
        let t = ty.trim();
        if !(t.starts_with('(') && t.ends_with(')')) {
            return None;
        }
        let inner = &t[1..t.len() - 1];
        let mut out = Vec::new();
        for e in inner.split(',') {
            let e = e.trim();
            let (name, ty) = e.split_once(':')?;
            let name = name.trim();
            if name.is_empty()
                || ty.trim().is_empty()
                || !name.chars().all(|c| c.is_alphanumeric() || c == '_')
                || name.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(true)
            {
                return None;
            }
            out.push((name.to_string(), ty.trim().to_string()));
        }
        if out.is_empty() {
            None
        } else {
            Some(out)
        }
    }

    // W623: `.len()` is `usize` in Zig, but a t27 signature that consumes or
    // returns a length declares a SIZED integer (`u32` throughout the corpus).
    // The backend emitted `.len` bare, so `return s.len;` under `-> u32` and
    // `f(line, kw_pos + keyword.len)` under `f(_, idx: u32)` both failed with
    // "expected type 'u32', found 'usize'". Nine sites across five specs; each
    // is fixed by a cast the SPEC CANNOT SPELL, which is what makes it a
    // compiler defect rather than a specification decision (refutes P12).
    fn is_len_access(&self, n: &Node) -> bool {
        if n.kind != NodeKind::ExprCall {
            return false;
        }
        // The three spellings gen_expr lowers to a bare `.len` field read.
        (n.extra_kind == "method" && n.name == "len" && n.children.len() == 1)
            || (n.children.is_empty() && n.name.ends_with(".len"))
            || (n.name == "len"
                && n.children.len() == 1
                && !self.declared_fns.contains("len"))
    }

    /// True when `n` reads a `.len` and the whole expression is integer
    /// arithmetic, so wrapping it in `@intCast` is type-correct. Deliberately
    /// narrow: a call or a float operand anywhere makes it false, because
    /// `@intCast` of a non-integer is itself an error.
    fn len_tainted_int_expr(&self, n: &Node) -> bool {
        if self.is_len_access(n) {
            return true;
        }
        // W625: a bare name bound earlier to a len-tainted initializer. Without
        // this, taint dies at the first `const`, and `estimate_10k_size`
        // carries a length through four of them.
        if n.kind == NodeKind::ExprIdentifier && self.len_locals.contains(&n.name) {
            return true;
        }
        if n.kind == NodeKind::ExprBinary
            // W625: `<<`/`>>` join the set because the corpus site shifts
            // twice. Shifts of an integer stay integral, so `@intCast` is as
            // sound here as it is for `+`.
            && matches!(
                n.extra_op.as_str(),
                "+" | "-" | "*" | "/" | "%" | "<<" | ">>"
            )
            && n.children.len() == 2
        {
            let ok = |c: &Node| {
                self.len_tainted_int_expr(c)
                    || c.kind == NodeKind::ExprIdentifier
                    || (c.kind == NodeKind::ExprLiteral && !c.name.contains('.'))
            };
            return (self.len_tainted_int_expr(&n.children[0])
                || self.len_tainted_int_expr(&n.children[1]))
                && ok(&n.children[0])
                && ok(&n.children[1]);
        }
        false
    }

    /// The sized Zig integer a t27 type names, or `None` for `usize`/`isize`
    /// (already the type of `.len`) and for everything non-integral.
    pub(crate) fn sized_int_type(ty: &str) -> Option<String> {
        let t = ty.trim();
        let (head, rest) = t.split_at(if t.starts_with('u') || t.starts_with('i') {
            1
        } else {
            return None;
        });
        if !matches!(head, "u" | "i") || rest.is_empty() {
            return None;
        }
        if !rest.chars().all(|c| c.is_ascii_digit()) {
            return None; // usize / isize / u8x4 / anything else
        }
        Some(t.to_string())
    }

    /// Emit `expr`, cast to `ty` when `ty` is a sized integer and `expr` reads
    /// a `.len`. Returns true when the cast was emitted.
    fn gen_len_cast(&mut self, expr: &Node, ty: &str) -> bool {
        let target = match Self::sized_int_type(ty) {
            Some(t) => t,
            None => return false,
        };
        if !self.len_tainted_int_expr(expr) {
            return false;
        }
        self.write(&format!("@as({}, @intCast(", target));
        self.gen_expr(expr);
        self.write("))");
        true
    }

    fn gen_fn_decl(&mut self, node: &Node) {
        // W566: fresh param/local type scope for this fn body (used by ExprCast
        // to pick @truncate vs @intCast).
        self.zig_var_types.clear();
        for (pname, ptype) in &node.params {
            if pname != "self" {
                self.zig_var_types.insert(pname.clone(), ptype.clone());
            }
        }
        if node.extra_pub {
            self.write("pub ");
        }

        // T27 method syntax: fn foo(self: *Type, ...) -> ReturnType
        // Zig syntax: fn foo(self: *Type, ...) ReturnType
        // For methods, we put return type after ) without arrow

        let return_type = if node.extra_return_type.is_empty() {
            "void".to_string()
        } else {
            // A tuple return type `(T, U)` lowers to a Zig anonymous tuple
            // struct; scalar/other types pass through unchanged.
            Self::t27_tuple_type_to_zig(&node.extra_return_type)
                .unwrap_or_else(|| Self::t27_array_type_to_zig(&node.extra_return_type))
        };

        // Check if this is a method (first param is "self")
        let is_method = node.params.iter().any(|(name, _)| name == "self");

        // Zig parameters are immutable; a spec body that assigns to a
        // parameter needs a mutable shadow. The parameter is renamed to
        // `<name>_arg` and `var <name> = <name>_arg;` opens the body, so
        // every body reference keeps its spec name.
        let mut body_muts: std::collections::HashSet<String> = std::collections::HashSet::new();
        collect_mutable_names(&node.children, &mut body_muts);
        let shadowed: Vec<String> = node
            .params
            .iter()
            .filter(|(pname, _)| pname != "self" && body_muts.contains(pname))
            .map(|(pname, _)| pname.clone())
            .collect();

        // W735: a parameter shadowing a container declaration is renamed all the
        // way -- signature and body -- because the `_arg` RE-BINDING used for
        // mutable parameters would recreate the collision as a local.
        self.param_renames.clear();
        for (pname, _) in node.params.iter() {
            if pname != "self"
                && !shadowed.contains(pname)
                && self.module_decl_names.contains(pname.as_str())
            {
                self.param_renames
                    .insert(pname.clone(), format!("{}_arg", pname));
            }
        }

        // W736: locals shadowing a container declaration are renamed with the
        // same map and the same reference hook the parameters use.
        let mut shadow_locals: Vec<String> = Vec::new();
        Self::collect_shadowing_locals(&node.children, &self.module_decl_names, &mut shadow_locals);
        for l in shadow_locals {
            self.param_renames.entry(l.clone()).or_insert(format!("{}_lv", l));
        }

        self.write(&format!("fn {}(", node.name));
        for (i, (pname, ptype)) in node.params.iter().enumerate() {
            if i > 0 {
                self.write(", ");
            }
            let arg_name = if shadowed.contains(pname) {
                format!("{}_arg", pname)
            } else if let Some(r) = self.param_renames.get(pname) {
                r.clone()
            } else {
                pname.clone()
            };
            self.write(&format!("{}: {}", arg_name, Self::t27_array_type_to_zig(ptype)));
        }
        self.write(")");

        // T27 methods: return type after ) without arrow. Zig REQUIRES a
        // return type on every fn -- a bare `) {` does not parse -- so a
        // spec fn with no declared return emits `void`.
        self.write(&format!(" {}", return_type));

        self.write_line(" {");

        self.indent();

        self.mut_names.clear();
        collect_mutable_names(&node.children, &mut self.mut_names);
        self.slice_locals.clear();
        self.collect_slice_locals(&node.children);
        self.scaffold_locals.clear();
        self.collect_scaffold_locals(&node.children);
        // W625: len-taint is per-function; a name reused in the next function
        // must not inherit it.
        self.len_locals.clear();
        self.current_return_type = node.extra_return_type.clone();
        // W593: float-typed LOCALS. `float_names` held only parameters and
        // struct fields, so a cast of a local declared `let x: f32` took the
        // `@floatFromInt` branch. Collected per function, and removed again on
        // exit so one function's locals cannot leak into the next.
        let local_floats = Self::collect_float_locals(&node.children);
        for n in &local_floats {
            self.float_names.insert(n.clone());
        }
        let local_signed = Self::collect_typed_locals(&node.children, &[
            "i8", "i16", "i32", "i64", "isize",
        ]);
        for n in &local_signed {
            self.signed_names.insert(n.clone());
        }
        // W594: this function's own parameters, scoped to it.
        let mut param_float = Vec::new();
        let mut param_signed = Vec::new();
        let mut param_string = Vec::new();
        for (pname, pty) in &node.params {
            let t = pty.trim();
            if Self::t27_array_type_to_zig(pty) == "[]const u8" {
                if self.string_names.insert(pname.clone()) {
                    param_string.push(pname.clone());
                }
            }
            if matches!(t, "f16" | "f32" | "f64" | "float" | "double") {
                if self.float_names.insert(pname.clone()) {
                    param_float.push(pname.clone());
                }
            }
            if matches!(t, "i8" | "i16" | "i32" | "i64" | "isize") {
                if self.signed_names.insert(pname.clone()) {
                    param_signed.push(pname.clone());
                }
            }
        }

        for pname in &shadowed {
            self.write_indent();
            self.write_line(&format!("var {} = {}_arg;", Self::zig_ident(pname), pname));
        }

        // Zig errors on unused function parameters; a spec is free to keep one
        // for interface symmetry (e.g. a lane the body ignores). Discard any
        // parameter the body never reads so the generated Zig compiles.
        fn param_referenced(nodes: &[Node], name: &str) -> bool {
            // Array literals carry their element text in extra_size with no
            // child nodes, so an identifier used only inside `[a, b, c]`
            // must be found textually (word-boundary match).
            fn text_has_ident(text: &str, name: &str) -> bool {
                let bytes = text.as_bytes();
                let is_ident = |b: u8| b.is_ascii_alphanumeric() || b == b'_';
                text.match_indices(name).any(|(i, _)| {
                    let before_ok = i == 0 || !is_ident(bytes[i - 1]);
                    let end = i + name.len();
                    let after_ok = end >= bytes.len() || !is_ident(bytes[end]);
                    before_ok && after_ok
                })
            }
            // A dotted callee keeps the whole path in `name`, so
            // `model.weights.len()` never matched the parameter `model` and
            // the emitter discarded a parameter the body reads -- Zig then
            // reported "pointless discard of function parameter".
            let root_is = |n: &Node, name: &str| {
                n.name.split('.').next().map(|r| r == name).unwrap_or(false)
            };
            nodes.iter().any(|n| {
                ((n.name == name || (n.kind == NodeKind::ExprCall && root_is(n, name)))
                    && !matches!(
                        n.kind,
                        NodeKind::FnDecl | NodeKind::TestBlock | NodeKind::BenchBlock
                    ))
                    || (n.kind == NodeKind::ExprArrayLiteral
                        && text_has_ident(&n.extra_size, name))
                    || param_referenced(&n.children, name)
            })
        }
        for (pname, _) in &node.params {
            if pname != "self" && !param_referenced(&node.children, pname) {
                self.write_indent();
                // W735: an unused parameter that was RENAMED must be discarded
                // under its new name, or Zig reports "unused function
                // parameter" for the one it actually declared.
                let dn = self
                    .param_renames
                    .get(pname)
                    .cloned()
                    .unwrap_or_else(|| pname.clone());
                self.write_line(&format!("_ = {}; // unused by the spec body", Self::zig_ident(&dn)));
            }
        }

        if node.children.is_empty() {
            self.write_indent();
            self.write_line("@compileError(\"not yet implemented\");");
        } else {
            // The CSE pass can leave its `_cse*` temp declarations AFTER their
            // first use in this backend's statement order (the Rust path hoists
            // them). They are pure expressions over consts/params, so emitting
            // them first is always safe -- and required: Zig resolves locals
            // lexically.
            for stmt in node.children.iter() {
                if stmt.kind == NodeKind::StmtLocal && stmt.name.starts_with("_cse") {
                    self.gen_stmt(stmt);
                }
            }
            for stmt in node.children.iter() {
                if !(stmt.kind == NodeKind::StmtLocal && stmt.name.starts_with("_cse")) {
                    self.gen_stmt(stmt);
                }
            }
        }

        self.dedent();
        self.write_line("}");
        for n in &local_floats {
            self.float_names.remove(n);
        }
        for n in &local_signed {
            self.signed_names.remove(n);
        }
        for n in &param_float {
            self.float_names.remove(n);
        }
        for n in &param_signed {
            self.signed_names.remove(n);
        }
        for n in &param_string {
            self.string_names.remove(n);
        }
    }

    fn gen_test_block(&mut self, node: &Node) {
        // Zig rejects a file that declares the same test name twice. Repeats
        // get a deterministic `__dupN` suffix so the duplication stays VISIBLE
        // in the output while the file still compiles and every test runs.
        let seen = self
            .test_name_counts
            .entry(node.name.clone())
            .or_insert(0);
        *seen += 1;
        let unique = if *seen == 1 {
            node.name.clone()
        } else {
            format!("{}__dup{}", node.name, *seen)
        };
        self.write(&format!("test \"{}\"", unique));
        self.write_line(" {");

        // The parser marks a block it could only lower in part --
        // `extra_field == "partial"` -- and every assertion after the
        // statement it gave up on is gone. `gen_invariant_block` honours that
        // mark and says so; this function never read it, so a truncated test
        // was emitted as an ordinary one. It is valid Zig, `zig test`
        // compiles it and reports OK, and a dropped assertion becomes
        // indistinguishable from a passing one -- in the one backend that
        // actually runs the spec's tests. 17 blocks across 11 specs.
        //
        // `error.SkipZigTest` is Zig's own signal for a test that did not run.
        // Reporting it as SKIPPED rather than passed is the whole point: the
        // surviving prefix still compiles, so the loss stays visible without
        // costing the file.
        let truncated = node.extra_field == "partial";
        self.indent();

        self.mut_names.clear();
        collect_mutable_names(&node.children, &mut self.mut_names);
        self.slice_locals.clear();
        self.collect_slice_locals(&node.children);
        self.scaffold_locals.clear();
        self.collect_scaffold_locals(&node.children);
        // W625: len-taint is per-function; a name reused in the next function
        // must not inherit it.
        self.len_locals.clear();


        // Test-block bindings (`b0 = f(...);`) parse as StmtAssign, not
        // StmtLocal, so a verbatim assignment referenced an undeclared name in
        // Zig (the same defect the Verilog testbench had, gHashTag/t27#1894).
        // Emit the FIRST assignment to each plain identifier as a `const`
        // binding -- or `var` when the test reassigns the name later (a
        // `const` shadow made every reassignment "cannot assign to constant").
        // Later statements go through the normal path.
        let mut assign_counts: std::collections::HashMap<String, u32> =
            std::collections::HashMap::new();
        count_ident_assigns(&node.children, &mut assign_counts);
        let mut bound: std::collections::HashSet<String> = std::collections::HashSet::new();
        for stmt in &node.children {
            let fresh_binding = stmt.kind == NodeKind::StmtAssign
                && stmt.children.len() >= 2
                && stmt.children[0].kind == NodeKind::ExprIdentifier
                && !stmt.children[0].name.is_empty()
                && bound.insert(stmt.children[0].name.clone());
            let tuple_binding = stmt.kind == NodeKind::StmtAssign
                && stmt.children.len() >= 2
                && stmt.children[0].kind == NodeKind::ExprTuple
                && stmt.children[0]
                    .children
                    .iter()
                    .all(|e| e.kind == NodeKind::ExprIdentifier && !e.name.is_empty());
            if fresh_binding {
                let name = &stmt.children[0].name;
                let kw = if assign_counts.get(name).copied().unwrap_or(0) >= 2 {
                    "var"
                } else {
                    "const"
                };
                self.write_indent();
                self.write(&format!("{} {} = ", kw, Self::zig_ident(name)));
                self.gen_expr(&stmt.children[1]);
                self.write_line(";");
            } else if tuple_binding {
                // Zig destructuring needs a binding keyword per element:
                // `const n, const valid = f(...);` -- a verbatim `.{ n, valid } = ...`
                // is an invalid assignment target.
                let binds: Vec<String> = stmt.children[0]
                    .children
                    .iter()
                    .map(|e| {
                        bound.insert(e.name.clone());
                        if e.name == "_" {
                            "_".to_string()
                        } else if count_ident_refs(&node.children, &e.name) <= 1 {
                            // Bound but never read in this block: a named
                            // binding would be an "unused local constant".
                            "_".to_string()
                        } else {
                            format!("const {}", Self::zig_ident(&e.name))
                        }
                    })
                    .collect();
                self.write_indent();
                self.write(&binds.join(", "));
                self.write(" = ");
                self.gen_expr(&stmt.children[1]);
                self.write_line(";");
            } else {
                self.gen_stmt(stmt);
            }
        }

        // Emitted LAST, not first: Zig rejects `unreachable code` after an
        // early return, so the surviving prefix runs and the test then
        // reports SKIPPED rather than passed.
        if truncated {
            self.write_indent();
            self.write_line(&format!(
                "// test {} was NOT fully lowered -- assertions after the first",
                node.name
            ));
            self.write_indent();
            self.write_line("// unmodelled statement are absent from this body.");
            self.write_indent();
            self.write_line("return error.SkipZigTest;");
        }
        self.dedent();
        self.write_line("}");
    }

    fn gen_invariant_block(&mut self, node: &Node) {
        self.write_line("comptime {");

        self.indent();
        self.write_indent();
        self.write_line(&format!("// invariant: {}", node.name));

        for stmt in &node.children {
            self.gen_stmt(stmt);
        }

        if node.children.is_empty() || node.extra_field == "partial" {
            self.write_indent();
            // A comment, not @compileLog: @compileLog is a hard compile error
            // under `zig test` ("found compile log statement"), so the marker
            // must stay out of the compiled program.
            //
            // W635: this used to read "verified (no statements)". It is emitted
            // exactly when the clause BODY was discarded and nothing was
            // lowered -- so `verified` was a predicate on the compiler having
            // reached the end of the clause HEADER, not on the clause. 1,087 of
            // 6,148 invariants (18%) took this path, including
            // `ternary_mul_no_star`, the spec's own statement of the
            // multiplier-free property T2 is about. Skipping an unbounded
            // `forall` is a defensible language decision; reporting it as
            // verification is not. See T43/T44.
            self.write_line(&format!(
                "// invariant: {} NOT CHECKED -- body was not lowered (T43)",
                node.name
            ));
        }

        self.dedent();
        self.write_line("}");
    }

    fn gen_bench_block(&mut self, node: &Node) {
        // Convert bench block name to valid Zig identifier
        let fn_name = node.name.replace('-', "_");
        let fn_name = if fn_name.starts_with("bench_") {
            fn_name
        } else {
            format!("bench_{}", fn_name)
        };

        // W588: a bench block declared twice emits two functions with the same
        // name, and Zig rejects the file with "duplicate struct member name".
        // Same defect and same remedy as the duplicate TEST names in W568:
        // suffix repeats deterministically so the duplication stays visible and
        // every bench still emits.
        let seen = self.test_name_counts.entry(fn_name.clone()).or_insert(0);
        *seen += 1;
        let fn_name = if *seen == 1 {
            fn_name
        } else {
            format!("{}__dup{}", fn_name, *seen)
        };

        self.write_line(&format!("fn {}() void {{", fn_name));

        self.indent();
        self.write_indent();
        self.write_line(&format!("// bench: {}", node.name));

        // Same first-assignment-as-const lowering as gen_test_block: bench
        // bindings parse as StmtAssign and would reference undeclared names.
        let mut bound: std::collections::HashSet<String> = std::collections::HashSet::new();
        for stmt in &node.children {
            let fresh_binding = stmt.kind == NodeKind::StmtAssign
                && stmt.children.len() >= 2
                && stmt.children[0].kind == NodeKind::ExprIdentifier
                && !stmt.children[0].name.is_empty()
                && bound.insert(stmt.children[0].name.clone());
            let tuple_binding = stmt.kind == NodeKind::StmtAssign
                && stmt.children.len() >= 2
                && stmt.children[0].kind == NodeKind::ExprTuple
                && stmt.children[0]
                    .children
                    .iter()
                    .all(|e| e.kind == NodeKind::ExprIdentifier && !e.name.is_empty());
            if fresh_binding {
                self.write_indent();
                // W608: `_` is Zig's DISCARD, not a name. `let _ = f();` was
                // lowered to `const _ = f();`, which Zig rejects outright --
                // 31 sites across 5 specs plus the bare `_ = x;` form. The
                // discard spelling is the whole statement.
                if stmt.children[0].name == "_" {
                    // W730: the SPEC writes `_ = result;` by hand and it is
                    // correct Zig for a var assigned in a loop and never read.
                    // The generator then adds `_ = &result;` at the declaration
                    // (compiler.rs, `as_var` path), and THAT makes the author's
                    // line a "pointless discard of local variable". The spec is
                    // not wrong; the extra discard is. Drop ours by dropping
                    // theirs -- either one alone compiles, both do not.
                    if stmt.children[1].kind == NodeKind::ExprIdentifier
                        && self.discarded_by_ref.contains(&stmt.children[1].name)
                    {
                        continue;
                    }
                    self.write("_ = ");
                } else {
                    self.write(&format!("const {} = ", Self::zig_ident(&stmt.children[0].name)));
                }
                self.gen_expr(&stmt.children[1]);
                self.write_line(";");
            } else if tuple_binding {
                // Zig destructuring needs a binding keyword per element:
                // `const n, const valid = f(...);` -- a verbatim `.{ n, valid } = ...`
                // is an invalid assignment target.
                let binds: Vec<String> = stmt.children[0]
                    .children
                    .iter()
                    .map(|e| {
                        bound.insert(e.name.clone());
                        if e.name == "_" {
                            "_".to_string()
                        } else {
                            format!("const {}", Self::zig_ident(&e.name))
                        }
                    })
                    .collect();
                self.write_indent();
                self.write(&binds.join(", "));
                self.write(" = ");
                self.gen_expr(&stmt.children[1]);
                self.write_line(";");
            } else {
                self.gen_stmt(stmt);
            }
        }

        if node.children.is_empty() {
            self.write_indent();
            self.write_line("// TODO: implement benchmark");
        }

        self.dedent();
        self.write_line("}");
    }

    fn gen_stmt(&mut self, node: &Node) {
        match node.kind {
            NodeKind::ExprReturn => {
                self.write_indent();
                self.write("return ");
                if !node.children.is_empty() {
                    // W593: an array literal in RETURN position. `.{ s }` does
                    // not initialise a `[]f32` ("type '[]f32' does not support
                    // array initialization syntax"); the element type is in the
                    // signature, exactly as it is for a call argument (W571).
                    // A tuple return distributes over its element types.
                    let ret = self.current_return_type.clone();
                    let v = &node.children[0];
                    // W596: under a NAMED tuple return type, a positional tuple
                    // value must be written with its field names.
                    if let Some(fields) = Self::tuple_field_names(&ret) {
                        if v.kind == NodeKind::ExprTuple && v.children.len() == fields.len() {
                            self.write(".{ ");
                            for (i, (c, (n, ft))) in
                                v.children.iter().zip(fields.iter()).enumerate()
                            {
                                if i > 0 {
                                    self.write(", ");
                                }
                                self.write(&format!(".{} = ", Self::zig_ident(n)));
                                let elem = if c.kind == NodeKind::ExprArrayLiteral {
                                    Self::slice_element_type(&Self::t27_array_type_to_zig(ft))
                                } else {
                                    None
                                };
                                match elem {
                                    Some(t) => {
                                        self.write(&format!("@constCast(&[_]{}", t));
                                        self.gen_array_literal_braces(c);
                                        self.write(")");
                                    }
                                    None => self.gen_expr(c),
                                }
                            }
                            self.write(" }");
                            self.write_line(";");
                            return;
                        }
                    }
                    let elem_types = Self::return_slice_elements(&ret);
                    if let Some(elems) = elem_types {
                        if v.kind == NodeKind::ExprTuple
                            && v.children.len() == elems.len()
                        {
                            self.write(".{ ");
                            for (i, (c, t)) in
                                v.children.iter().zip(elems.iter()).enumerate()
                            {
                                if i > 0 {
                                    self.write(", ");
                                }
                                match (c.kind == NodeKind::ExprArrayLiteral, t) {
                                    (true, Some(t)) => {
                                        self.write(&format!("@constCast(&[_]{}", t));
                                        self.gen_array_literal_braces(c);
                                        self.write(")");
                                    }
                                    _ => self.gen_expr(c),
                                }
                            }
                            self.write(" }");
                            self.write_line(";");
                            return;
                        }
                        if v.kind == NodeKind::ExprArrayLiteral && elems.len() == 1 {
                            if let Some(t) = &elems[0] {
                                self.write(&format!("@constCast(&[_]{}", t));
                                self.gen_array_literal_braces(v);
                                self.write(")");
                                self.write_line(";");
                                return;
                            }
                        }
                    }
                    // W623: `return s.len;` under a `-> u32` signature.
                    if !self.gen_len_cast(v, &ret) {
                        self.gen_expr(v);
                    }
                }
                self.write_line(";");
            }
            NodeKind::StmtLocal => {
                self.write_indent();
                if node.name.is_empty() && !node.extra_field.is_empty() {
                    // Tuple-destructuring `let (s, d) = init`. Zig destructuring
                    // needs a binding keyword per element:
                    // `const s, const d = init;`.
                    // W596: destructuring a NAMED-tuple return. Zig cannot
                    // destructure a named struct, and the spec that made the
                    // return type named (because its other consumers access
                    // `.sin` / `.cos`) still destructures it here. The
                    // positional order IS the field order, so the binding
                    // lowers to one field access per name.
                    let named_fields = node
                        .children
                        .first()
                        .filter(|init| init.kind == NodeKind::ExprCall)
                        .and_then(|init| self.declared_fn_returns.get(&init.name))
                        .and_then(|ret| Self::tuple_field_names(ret));
                    if let Some(fields) = named_fields {
                        let names: Vec<&str> = node
                            .extra_field
                            .split(',')
                            .map(|s| s.trim())
                            .filter(|s| !s.is_empty())
                            .collect();
                        if names.len() == fields.len() {
                            let tmp = format!("__t{}", node.line);
                            self.write(&format!("const {} = ", tmp));
                            self.gen_expr(&node.children[0]);
                            self.write_line(";");
                            for (bind, (fname, _)) in names.iter().zip(fields.iter()) {
                                if *bind == "_" {
                                    continue;
                                }
                                self.write_indent();
                                self.write_line(&format!(
                                    "const {} = {}.{};",
                                    Self::zig_ident(bind),
                                    tmp,
                                    Self::zig_ident(fname)
                                ));
                            }
                            return;
                        }
                    }
                    let kw = if node.extra_mutable { "var" } else { "const" };
                    let binds: Vec<String> = node
                        .extra_field
                        .split(',')
                        .map(|s| s.trim())
                        .filter(|s| !s.is_empty())
                        .map(|s| {
                            if s == "_" {
                                // Zig: a discarded destructure element is a bare `_`,
                                // never `const _`.
                                "_".to_string()
                            } else {
                                format!("{} {}", kw, Self::zig_ident(s))
                            }
                        })
                        .collect();
                    self.write(&binds.join(", "));
                    if !node.children.is_empty() {
                        self.write(" = ");
                        self.gen_expr(&node.children[0]);
                    }
                    self.write_line(";");
                } else {
                    // A slice-typed local must be `var`: `&const_array` is
                    // `*const [N]T`, which coerces to `[]const T` but not to
                    // the mutable `[]T` most signatures declare.
                    // W608: `_` is Zig's DISCARD, not a binding name.
                    // `let _ = f();` lowered to `const _ = f();`, which Zig
                    // rejects outright -- 31 sites across 5 specs. The discard
                    // takes no keyword and no type annotation.
                    if node.name == "_" {
                        self.write("_ = ");
                        if let Some(init) = node.children.first() {
                            self.gen_expr(init);
                        }
                        self.write_line(";");
                        return;
                    }
                    let as_var = node.extra_mutable
                        || self.mut_names.contains(&node.name)
                        || self.slice_locals.contains_key(&node.name);
                    if as_var {
                        self.write("var ");
                    } else {
                        self.write("const ");
                    }
                    self.write(&Self::zig_ident(&self.renamed(&node.name)));
                    if !node.extra_type.is_empty() {
                        // W566: record the local's declared type for cast width inference.
                        self.zig_var_types
                            .insert(node.name.clone(), node.extra_type.clone());
                        self.write(&format!(": {}", Self::t27_array_type_to_zig(&node.extra_type)));
                    } else if as_var {
                        // An untyped mutable initialized with a bare integer
                        // literal would be comptime_int, which Zig rejects for
                        // `var`. Pin the default integer width (u64 only when
                        // the literal does not fit u32).
                        if let Some(lit_ty) = node
                            .children
                            .first()
                            .and_then(Self::zig_int_literal_default_type)
                        {
                            self.write(&format!(": {}", lit_ty));
                        }
                    }
                    if !node.children.is_empty() {
                        self.write(" = ");
                        // W572: a local bound to an array literal and later
                        // passed where a callee declares `[]T` must be a real
                        // `[_]T{ … }` array; `.{ … }` does not coerce to a
                        // slice. The element type comes from the callee.
                        // W585: the scaffold helper, resolved to a zero value
                        // of the type its consumer declares.
                        if let Some(ty) = self.scaffold_locals.get(&node.name).cloned() {
                            let is_scaffold = node.children[0].kind == NodeKind::ExprCall
                                && matches!(
                                    node.children[0].name.as_str(),
                                    "default_input" | "valid_input"
                                );
                            if is_scaffold {
                                // A non-optional pointer has no zero value in
                                // Zig ("Only nullable and allowzero pointers
                                // can be set to zero"), and a scaffold input of
                                // pointer type has no meaningful default at
                                // all -- the tests that use it assert only
                                // `result != undefined`.
                                // `std.mem.zeroes(T)` is the better value, but
                                // it is a COMPILE error for any type reachable
                                // from a non-optional pointer -- and a compile
                                // error kills the whole file, which is the
                                // thing this lowering exists to prevent.
                                // `undefined` always compiles, and the tests
                                // that use the scaffold constrain the value not
                                // at all: their assertion is
                                // `result != undefined`, which is trivially
                                // true. The type is still recorded, so the
                                // binding is correctly typed.
                                let _ = &ty;
                                self.write("undefined");
                                self.write_line(";");
                                if as_var {
                                    self.write_indent();
                                    self.write_line(&format!(
                                        "_ = &{};",
                                        Self::zig_ident(&node.name)
                                    ));
                                }
                                return;
                            }
                        }
                        let slice_elem = if node.children[0].kind == NodeKind::ExprArrayLiteral {
                            self.slice_locals.get(&node.name).cloned()
                        } else {
                            None
                        };
                        match slice_elem {
                            Some(t) => {
                                self.write(&format!("[_]{}", t));
                                let lit = node.children[0].clone();
                                self.gen_array_literal_braces(&lit);
                            }
                            None => {
                                // W624: `let n : u32 = s.len();`. Third of the
                                // five positions a length can reach a sized-int
                                // context; W623 closed two. See T20.
                                let lty = node.extra_type.clone();
                                let init = node.children[0].clone();
                                if self.gen_len_cast(&init, &lty) {
                                    // The cast fired, so the binding really is
                                    // `lty`. It must NOT carry taint onward.
                                    self.len_locals.remove(&node.name);
                                } else {
                                    // W625: no cast -- either untyped, or
                                    // declared `usize`. Either way the binding
                                    // is `usize` when its initializer is, and
                                    // the taint has to survive the `const`.
                                    if self.len_tainted_int_expr(&init) {
                                        self.len_locals.insert(node.name.clone());
                                    }
                                    self.gen_expr(&node.children[0]);
                                }
                            }
                        }
                    } else {
                        // Zig has no uninitialized declarations.
                        self.write(" = undefined");
                    }
                    self.write_line(";");
                    if as_var {
                        // Mutability is inferred fn-wide, but the same name may be
                        // declared in several branches and mutated in only one;
                        // Zig then errors "local variable is never mutated" on the
                        // others. `_ = &name;` is the canonical silencer and is a
                        // harmless extra use on genuinely mutated paths.
                        self.write_indent();
                        self.write_line(&format!("_ = &{};", Self::zig_ident(&self.renamed(&node.name))));
                        self.discarded_by_ref.insert(node.name.clone());
                    }
                }
            }
            NodeKind::StmtAssign => {
                // W730: `_ = name;` after `_ = &name;` is a POINTLESS DISCARD and
                // Zig rejects the file. The comment at the `_ = &name;` site called
                // it "a harmless extra use"; it is not. Suppress the second one --
                // the by-reference discard already satisfies the use check, and
                // dropping it instead would resurrect "never mutated" on the
                // branches that motivated it.
                if node.children.len() >= 2
                    && node.children[0].kind == NodeKind::ExprIdentifier
                    && node.children[0].name == "_"
                    && node.children[1].kind == NodeKind::ExprIdentifier
                    && self.discarded_by_ref.contains(&node.children[1].name)
                {
                    return;
                }
                self.write_indent();
                if node.children.len() >= 2 {
                    self.gen_expr(&node.children[0]);
                    self.write(&assign_op_text(&node.extra_op));
                    self.gen_expr(&node.children[1]);
                }
                self.write_line(";");
            }
            NodeKind::StmtIf => {
                self.gen_if_stmt(node);
            }
            NodeKind::StmtWhile => {
                self.gen_while_stmt(node);
            }
            NodeKind::StmtFor => {
                self.gen_for_stmt(node);
            }
            NodeKind::StmtForRange => {
                self.gen_for_range_stmt(node);
            }
            NodeKind::StmtBreak => {
                self.write_line("break;");
            }
            NodeKind::StmtContinue => {
                self.write_line("continue;");
            }
            NodeKind::StmtExpr => {
                self.write_indent();
                if !node.children.is_empty() {
                    self.gen_expr(&node.children[0]);
                }
                self.write_line(";");
            }
            _ => {
                // Fallback: treat as expression
                self.write_indent();
                self.gen_expr(node);
                self.write_line(";");
            }
        }
    }

    fn gen_if_stmt(&mut self, node: &Node) {
        // children[0] = condition, children[1] = then block, children[2] = optional else block
        self.write_indent();
        self.write("if (");
        if !node.children.is_empty() {
            self.gen_expr(&node.children[0]);
        }
        self.write_line(") {");

        self.indent();
        if node.children.len() > 1 {
            for stmt in &node.children[1].children {
                self.gen_stmt(stmt);
            }
        }
        self.dedent();

        if node.children.len() > 2 {
            let else_block = &node.children[2];
            // Check if this is an else-if chain
            if else_block.children.len() == 1 && else_block.children[0].kind == NodeKind::StmtIf {
                self.write_indent();
                self.write("} else ");
                // Generate inline (no indent prefix for the nested if)
                self.gen_if_stmt_inline(&else_block.children[0]);
            } else {
                self.write_indent();
                self.write_line("} else {");
                self.indent();
                for stmt in &else_block.children {
                    self.gen_stmt(stmt);
                }
                self.dedent();
                self.write_indent();
                self.write_line("}");
            }
        } else {
            self.write_indent();
            self.write_line("}");
        }
    }

    fn gen_if_stmt_inline(&mut self, node: &Node) {
        // Same as gen_if_stmt but without leading indent (for else if)
        self.write("if (");
        if !node.children.is_empty() {
            self.gen_expr(&node.children[0]);
        }
        self.write_line(") {");

        self.indent();
        if node.children.len() > 1 {
            for stmt in &node.children[1].children {
                self.gen_stmt(stmt);
            }
        }
        self.dedent();

        if node.children.len() > 2 {
            let else_block = &node.children[2];
            if else_block.children.len() == 1 && else_block.children[0].kind == NodeKind::StmtIf {
                self.write_indent();
                self.write("} else ");
                self.gen_if_stmt_inline(&else_block.children[0]);
            } else {
                self.write_indent();
                self.write_line("} else {");
                self.indent();
                for stmt in &else_block.children {
                    self.gen_stmt(stmt);
                }
                self.dedent();
                self.write_indent();
                self.write_line("}");
            }
        } else {
            self.write_indent();
            self.write_line("}");
        }
    }

    /// A statement written where Zig expects an expression: the continue
    /// expression of a `while ... : (...)`. Rendered without indent, without a
    /// trailing semicolon and without a newline.
    fn gen_expr_inline_stmt(&mut self, node: &Node) {
        // The continue expression arrives wrapped in whatever block node the
        // parser built for it, so unwrap a single-child container first.
        let n = unwrap_single(node);
        if n.kind == NodeKind::StmtAssign && n.children.len() >= 2 {
            self.gen_expr(&n.children[0]);
            self.write(&assign_op_text(&n.extra_op));
            self.gen_expr(&n.children[1]);
        } else {
            self.gen_expr(n);
        }
    }

    fn gen_while_stmt(&mut self, node: &Node) {
        // `while (cond) : (step) { body }` parses to THREE children -- the
        // condition, the continue expression, and the body -- and this function
        // read children[1] as the body and never looked at children[2]. So the
        // step became the entire loop body and the real body was dropped:
        //
        //     while (i < corpus.len) : (i += 1) {
        //         scores[i] = compute_similarity(...);
        //     }
        //
        // emitted `while (i < corpus.len) { i += 1; }` -- a loop that advances
        // a counter and computes nothing, in Zig that compiles clean.
        //
        // The body is the LAST child, which is the rule `gen_for_stmt` already
        // uses for the same shape.
        self.write_indent();
        self.write("while (");
        if !node.children.is_empty() {
            self.gen_expr(&node.children[0]);
        }
        self.write(")");
        let body_idx = node.children.len().saturating_sub(1);
        if body_idx > 1 {
            self.write(" : (");
            self.gen_expr_inline_stmt(&node.children[1]);
            self.write(")");
        }
        self.write_line(" {");

        self.indent();
        if node.children.len() > 1 {
            for stmt in &node.children[body_idx].children {
                self.gen_stmt(stmt);
            }
        }
        self.dedent();
        self.write_indent();
        self.write_line("}");
    }

    fn gen_for_stmt(&mut self, node: &Node) {
        self.write_indent();
        self.write("for (");

        // Iterables are children[0..n-1], last child is the body block
        let body_idx = node.children.len().saturating_sub(1);
        for (i, child) in node.children.iter().enumerate() {
            if i == body_idx {
                break; // body block
            }
            if i > 0 {
                self.write(", ");
            }
            self.gen_expr(child);
        }
        self.write(")");

        // Capture variables from params
        if !node.params.is_empty() {
            self.write(" |");
            for (i, (name, _)) in node.params.iter().enumerate() {
                if i > 0 {
                    self.write(", ");
                }
                self.write(name);
            }
            self.write("|");
        }

        self.write_line(" {");

        self.indent();
        if !node.children.is_empty() {
            for stmt in &node.children[body_idx].children {
                self.gen_stmt(stmt);
            }
        }
        self.dedent();
        self.write_indent();
        self.write_line("}");
    }

    fn gen_for_range_stmt(&mut self, node: &Node) {
        self.write_indent();
        // children[0] is the range START expression; the old emitter wrote
        // the LOOP VARIABLE there (`for (i..10) |i|`) -- an undeclared
        // identifier in Zig for any range not starting at the variable name.
        self.write("for (");
        if node.children.len() >= 2 {
            self.gen_expr(&node.children[0]);
            self.write("..");
            self.gen_expr(&node.children[1]);
            self.write(") |");
            self.write(&Self::zig_ident(&node.name));
            self.write("|");
        }
        self.write_line(" {");
        self.indent();
        if node.children.len() > 2 {
            for stmt in &node.children[2].children {
                self.gen_stmt(stmt);
            }
        }
        self.dedent();
        self.write_indent();
        self.write_line("}");
    }

    fn gen_expr_maybe_paren(&mut self, node: &Node) {
        if node.kind == NodeKind::ExprBinary {
            self.write("(");
            self.gen_expr(node);
            self.write(")");
        } else {
            self.gen_expr(node);
        }
    }

    fn gen_expr(&mut self, node: &Node) {
        match node.kind {
            NodeKind::ExprLiteral => {
                // The lexer strips the surrounding quotes and stores the raw
                // text, tagging the node `extra_kind == "string"`. Writing the
                // value back unquoted turned every string literal into a bare
                // identifier: `const x = "world"` emitted `const x = world;`,
                // and `name == "Digilent Arty A7-35T"` became a run of
                // identifiers. That is a large share of the
                // `use of undeclared identifier` class measured in W560.
                if node.extra_kind == "string" {
                    // The lexer UNESCAPES as it reads, so `"a\nb"` in a spec
                    // arrives here holding a real newline. Writing that back
                    // between quotes produced "string literal contains invalid
                    // byte: '\n'" -- a Zig string literal cannot span lines.
                    // 154 escape sequences across 19 specs. The W576 lexer
                    // conformance table records the unescaping as a boundary,
                    // which is how this was found.
                    self.write(&format!("\"{}\"", Self::zig_escape(&node.value)));
                } else {
                    self.write(&node.value);
                }
            }
            NodeKind::ExprIdentifier => {
                // W735: a shadowing parameter carries its rename into the body.
                let nm = self
                    .param_renames
                    .get(&node.name)
                    .cloned()
                    .unwrap_or_else(|| node.name.clone());
                self.write(&Self::zig_ident(&nm));
            }
            NodeKind::ExprEnumValue => {
                self.write(".");
                self.write(&node.name);
            }
            NodeKind::ExprCall => {
                // W572: a method call whose receiver could not be folded into
                // the name keeps it as children[0].
                if node.extra_kind == "method" && !node.children.is_empty() {
                    self.gen_expr_maybe_paren(&node.children[0]);
                    if node.name == "len" && node.children.len() == 1 {
                        self.write(".len");
                        return;
                    }
                    self.write(&format!(".{}(", Self::zig_ident(&node.name)));
                    for (i, arg) in node.children.iter().skip(1).enumerate() {
                        if i > 0 {
                            self.write(", ");
                        }
                        self.gen_expr(arg);
                    }
                    self.write(")");
                    return;
                }

                // W570: `x.len()` and `len(x)`. Zig exposes a slice length as
                // the FIELD `.len`, so the call form emitted `a.len()` and
                // failed. 1,356 method calls and 318 free calls across 51
                // specs.
                if node.children.is_empty() && node.name.ends_with(".len") {
                    self.write(&Self::zig_ident(&node.name));
                    return;
                }
                if node.name == "len"
                    && node.children.len() == 1
                    && !self.declared_fns.contains("len")
                {
                    self.gen_expr_maybe_paren(&node.children[0]);
                    self.write(".len");
                    return;
                }

                // W570: the TYPED spellings of the math builtins and of an
                // integer cast. `cast_i8(` alone appears 1,100 times and is
                // defined nowhere in the corpus; `abs_f32`/`abs_f64`/`abs_i16`
                // 39 times. Guarded by declared_fns like the bare forms.
                if !self.declared_fns.contains(&node.name) && node.children.len() == 1 {
                    if let Some(sized) = node.name.strip_prefix("abs_") {
                        if Self::is_numeric_type_suffix(sized) {
                            self.write("@abs(");
                            self.gen_expr(&node.children[0]);
                            self.write(")");
                            return;
                        }
                    }
                    if let Some(target) = node.name.strip_prefix("cast_") {
                        // Integers only: a float cast needs @floatCast or
                        // @intFromFloat, and guessing between them would be a
                        // silent semantic choice.
                        if Self::is_integer_type_suffix(target) {
                            self.write(&format!("@as({}, @intCast(", target));
                            self.gen_expr(&node.children[0]);
                            self.write("))");
                            return;
                        }
                    }
                }

                // Zig spells these as builtins. Specs call them bare -- `abs(`
                // appears 425 times, `sqrt(` 111, `floor(` 99, `round(` 92 --
                // and emitting the bare name gives
                // "use of undeclared identifier 'abs'". Guarded by
                // declared_fns so a spec's own `fn max(...)` still wins.
                if !self.declared_fns.contains(&node.name) {
                    let builtin = match node.name.as_str() {
                        "abs" => Some("@abs"),
                        "sqrt" => Some("@sqrt"),
                        "floor" => Some("@floor"),
                        "ceil" => Some("@ceil"),
                        "round" => Some("@round"),
                        "min" => Some("@min"),
                        "max" => Some("@max"),
                        _ => None,
                    };
                    if let Some(b) = builtin {
                        self.write(b);
                        self.write("(");
                        for (i, arg) in node.children.iter().enumerate() {
                            if i > 0 {
                                self.write(", ");
                            }
                            self.gen_expr(arg);
                        }
                        self.write(")");
                        return;
                    }
                }
                if node.name == "@compileAssert" || node.name == "assert" {
                    if !node.children.is_empty() {
                        // @compileError fires whenever the branch is ANALYZED,
                        // so a runtime-condition assert made every generated
                        // file fail `zig test` at compile time. @panic is the
                        // honest runtime failure and still dies at comptime
                        // when the condition folds to false.
                        let msg = node
                            .children
                            .get(1)
                            .map(|m| m.value.trim_matches('"').replace('\\', "").replace('"', ""))
                            .unwrap_or_else(|| "assertion failed".to_string());
                        // W599: a failing assertion used to say only "assertion
                        // failed". Finding W598's swapped sin/cos took a probe
                        // program written by hand, because the panic reported
                        // the FACT of failure and never the values -- and a
                        // swap is invisible in any report that omits them.
                        // When the condition compares printable operands, print
                        // them. The operands are re-evaluated inside the failure
                        // branch: `then` clauses are pure, and the branch only
                        // runs once, immediately before the process dies.
                        let mut cmps: Vec<&Node> = Vec::new();
                        Self::assert_comparisons(&node.children[0], &mut cmps);
                        // Beyond a handful the output stops being a diagnostic
                        // and starts being a dump; and the rendered text must
                        // not itself be enormous.
                        let cmps: Vec<&Node> = cmps.into_iter().take(4).collect();
                        let mut fmt = String::new();
                        let mut args = String::new();
                        let mut shown: Vec<String> = Vec::new();
                        for c in &cmps {
                            for side in 0..2 {
                                // A literal's text already IS its value, and
                                // `0.01 = 0.01` is noise; so is the same name
                                // twice, which `g > lo && g < hi` would give.
                                if c.children[side].kind == NodeKind::ExprLiteral {
                                    continue;
                                }
                                let t = self.render_expr(&c.children[side]);
                                if t.len() > 120 || shown.contains(&t) {
                                    continue;
                                }
                                // W739: `undefined` has no type, so `{any}` on it
                                // is `unable to format type '@TypeOf(undefined)'`
                                // -- and that error fires BEFORE the
                                // `@compileError("not yet implemented")` in the
                                // body it is testing. 101 unwritten specs were
                                // counted as the corpus's second-largest CODEGEN
                                // defect class because of this one operand
                                // (T274). Printing it says nothing anyway: the
                                // value is the absence of a value.
                                if t.trim() == "undefined" {
                                    continue;
                                }
                                fmt.push_str(&format!(
                                    "\\n    {} = {{any}}",
                                    Self::escape_for_fmt(&t)
                                ));
                                if !args.is_empty() {
                                    args.push_str(", ");
                                }
                                args.push_str(&t);
                                shown.push(t);
                            }
                        }
                        self.write("if (!(");
                        self.gen_expr(&node.children[0]);
                        if args.is_empty() {
                            self.write(&format!(")) @panic(\"{}\")", msg));
                        } else {
                            self.write(&format!(
                                ")) __t27_assert_fail(\"\\n  {}:{}\\n\", .{{ {} }})",
                                Self::escape_for_fmt(&msg),
                                fmt,
                                args
                            ));
                        }
                    }
                } else if node.name == "gf16_encode_f32" {
                    self.write("gf16_encode_f32(");
                    for (i, arg) in node.children.iter().enumerate() {
                        if i > 0 {
                            self.write(", ");
                        }
                        self.gen_expr(arg);
                    }
                    self.write(")");
                } else if node.name == "gf16_decode_f32" {
                    self.write("gf16_decode_f32(");
                    for (i, arg) in node.children.iter().enumerate() {
                        if i > 0 {
                            self.write(", ");
                        }
                        self.gen_expr(arg);
                    }
                    self.write(")");
                } else if node.name == "gf16_extract_sign"
                    || node.name == "gf16_extract_exponent"
                    || node.name == "gf16_extract_mantissa"
                {
                    self.write(&node.name);
                    self.write("(");
                    for (i, arg) in node.children.iter().enumerate() {
                        if i > 0 {
                            self.write(", ");
                        }
                        self.gen_expr(arg);
                    }
                    self.write(")");
                } else {
                    // A scoped callee (`TernaryWeight::minus()`) needs the same
                    // `::` -> `.` rewrite the identifier path gets.
                    self.write(&Self::zig_ident(&node.name));
                    self.write("(");
                    // W571: an array-literal argument where the callee declares
                    // a SLICE. `.{ 0, 0, 0, 0 }` coerces to `[4]i32` but not to
                    // `[]i32` ("expected type '[]i32', found 'struct { comptime
                    // T = 0, ... }'"), and only the callee's signature says what
                    // the element type is.
                    let param_types = self.declared_fn_params.get(&node.name).cloned();
                    for (i, arg) in node.children.iter().enumerate() {
                        if i > 0 {
                            self.write(", ");
                        }
                        let elem = if arg.kind == NodeKind::ExprArrayLiteral {
                            param_types
                                .as_ref()
                                .and_then(|ps| ps.get(i))
                                .map(|ty| Self::t27_array_type_to_zig(ty))
                                .and_then(|ty| Self::slice_element_type(&ty))
                        } else {
                            None
                        };
                        // A local materialised as `[_]T{ … }` is passed by
                        // reference; that is what makes it a slice.
                        let by_ref = arg.kind == NodeKind::ExprIdentifier
                            && self.slice_locals.contains_key(&arg.name)
                            && param_types
                                .as_ref()
                                .and_then(|ps| ps.get(i))
                                .map(|ty| {
                                    Self::slice_element_type(&Self::t27_array_type_to_zig(ty))
                                        .is_some()
                                })
                                .unwrap_or(false);
                        match elem {
                            Some(t) => {
                                // `&[_]T{ … }` is `*const [N]T`, which coerces
                                // to `[]const T` but not to the mutable `[]T`
                                // most signatures declare. A literal argument
                                // has no addressable `var` to point at, so the
                                // const-ness is cast away explicitly.
                                self.write(&format!("@constCast(&[_]{}", t));
                                self.gen_array_literal_braces(arg);
                                self.write(")");
                            }
                            None if by_ref => {
                                self.write("&");
                                self.gen_expr(arg);
                            }
                            None => {
                                // W623: `f(line, kw_pos + keyword.len)` where the
                                // callee declares `idx: u32`.
                                let pty = param_types
                                    .as_ref()
                                    .and_then(|ps| ps.get(i))
                                    .cloned()
                                    .unwrap_or_default();
                                if !self.gen_len_cast(arg, &pty) {
                                    self.gen_expr(arg);
                                }
                            }
                        }
                    }
                    self.write(")");
                }
            }
            NodeKind::ExprBinary => {
                if node.children.len() >= 2 {
                    let op = node.extra_op.as_str();
                    // Zig has no `==` for slices. Once W562 started emitting
                    // string literals with their quotes, `name == "clk"` began
                    // failing with "cannot compare strings with ==". When either
                    // side is a string literal the comparison is a string
                    // comparison, so lower it to std.mem.eql.
                    let is_str = |n: &Node| {
                        n.kind == NodeKind::ExprLiteral && n.extra_kind == "string"
                    };
                    // ... and when neither side is a literal but one names a
                    // field the spec DECLARED as a string (`a.name == b.name`),
                    // which the literal test alone could not see.
                    if matches!(op, "==" | "!=")
                        && (is_str(&node.children[0])
                            || is_str(&node.children[1])
                            || self.is_string_typed(&node.children[0])
                            || self.is_string_typed(&node.children[1]))
                    {
                        if op == "!=" {
                            self.write("!");
                        }
                        self.write("std.mem.eql(u8, ");
                        self.gen_expr(&node.children[0]);
                        self.write(", ");
                        self.gen_expr(&node.children[1]);
                        self.write(")");
                        return;
                    }
                    // Zig has no ordering on enums either. When a side is a
                    // variant of an enum this spec declares (`BitWidth::Int4`),
                    // compare the tags.
                    if matches!(op, "<" | ">" | "<=" | ">=")
                        && (self.is_enum_variant(&node.children[0])
                            || self.is_enum_variant(&node.children[1]))
                    {
                        self.write("@intFromEnum(");
                        self.gen_expr(&node.children[0]);
                        self.write(&format!(") {} @intFromEnum(", op));
                        self.gen_expr(&node.children[1]);
                        self.write(")");
                        return;
                    }
                    // W593: Zig refuses `/` on SIGNED integers -- the rounding
                    // mode must be explicit ("signed integers must use
                    // @divTrunc, @divFloor or @divExact"). 218 division sites
                    // in the corpus. `@divTrunc` is C's and Rust's semantics,
                    // which is what the specs assume.
                    if op == "/"
                        && (self.is_signed_int_expr(&node.children[0])
                            || self.is_signed_int_expr(&node.children[1]))
                        && !self.is_float_expr(&node.children[0])
                        && !self.is_float_expr(&node.children[1])
                    {
                        self.write("@divTrunc(");
                        self.gen_expr(&node.children[0]);
                        self.write(", ");
                        self.gen_expr(&node.children[1]);
                        self.write(")");
                        return;
                    }
                    // Zig shift RHS must be Log2(LHS-width)-typed (u5 for u32);
                    // a runtime u32/usize amount needs @intCast, and a bare
                    // integer-literal LHS (comptime_int) needs a pinned width
                    // once the amount is not comptime-known. Literal amounts
                    // are left untouched so existing gens stay byte-identical.
                    let shift_runtime_rhs = matches!(op, "<<" | ">>")
                        && !matches!(node.children[1].kind, NodeKind::ExprLiteral);
                    if shift_runtime_rhs {
                        if let Some(ty) = Self::zig_int_literal_default_type(&node.children[0]) {
                            self.write(&format!("@as({}, ", ty));
                            self.gen_expr_maybe_paren(&node.children[0]);
                            self.write(")");
                        } else {
                            self.gen_expr_maybe_paren(&node.children[0]);
                        }
                        self.write(&format!(" {} ", op));
                        self.write("@intCast(");
                        self.gen_expr(&node.children[1]);
                        self.write(")");
                    } else {
                        self.gen_expr_maybe_paren(&node.children[0]);
                        self.write(&format!(" {} ", op));
                        self.gen_expr_maybe_paren(&node.children[1]);
                    }
                }
            }
            NodeKind::ExprUnary => {
                self.write(&node.extra_op);
                if !node.children.is_empty() {
                    self.gen_expr(&node.children[0]);
                }
            }
            NodeKind::ExprFieldAccess => {
                // children[0] is the base expression
                if !node.children.is_empty() {
                    self.gen_expr(&node.children[0]);
                }
                self.write(".");
                if node.name.chars().all(|c| c.is_ascii_digit()) {
                    // Tuple index: Zig tuple fields are named "0"/"1"/...,
                    // reachable only through the @"" identifier syntax.
                    self.write(&format!("@\"{}\"", node.name));
                } else {
                    self.write(&node.name);
                }
            }
            NodeKind::ExprIndex => {
                // children[0] = base, children[1] = index
                // W605: a slice carries a third child (the end) and lowers to
                // Zig's `[a..b]` -- the same half-open range the source means.
                if node.extra_op == "slice" && node.children.len() >= 3 {
                    self.gen_expr(&node.children[0]);
                    self.write("[");
                    self.gen_expr(&node.children[1]);
                    self.write("..");
                    self.gen_expr(&node.children[2]);
                    self.write("]");
                } else if node.children.len() >= 2 {
                    self.gen_expr(&node.children[0]);
                    self.write("[");
                    self.gen_expr(&node.children[1]);
                    self.write("]");
                }
            }
            NodeKind::ExprSwitch => {
                self.write("switch (");
                if !node.children.is_empty() {
                    self.gen_expr(&node.children[0]);
                }
                self.write_line(") {");

                self.indent();
                for case_node in &node.children[1..] {
                    if case_node.kind == NodeKind::ConstDecl {
                        self.write_indent();
                        if !case_node.name.is_empty() && case_node.name != "else" {
                            // Don't prefix with '.' if the arm is a numeric literal or negative number
                            let is_numeric = case_node
                                .name
                                .starts_with(|c: char| c.is_ascii_digit())
                                || (case_node.name.starts_with('-') && case_node.name.len() > 1);
                            if is_numeric {
                                self.write(&case_node.name);
                            } else {
                                self.write(&format!(".{}", case_node.name));
                            }
                        } else {
                            self.write("else");
                        }
                        self.write(" => ");
                        if !case_node.children.is_empty() {
                            self.gen_expr(&case_node.children[0]);
                        }
                        self.write_line(",");
                    }
                }
                self.dedent();
                self.write_indent();
                self.write("}");
            }
            NodeKind::ExprIf => {
                // children[0] = cond, children[1] = then, children[2] = else (optional)
                self.write("if (");
                if !node.children.is_empty() {
                    self.gen_expr(&node.children[0]);
                }
                self.write(") ");
                if node.children.len() > 1 {
                    self.gen_expr(&node.children[1]);
                }
                if node.children.len() > 2 {
                    self.write(" else ");
                    self.gen_expr(&node.children[2]);
                }
            }
            NodeKind::ExprArrayLiteral => {
                // Real element CHILDREN win when the parser captured them --
                // `[N]T{ a, b }` and the bare `[a, b]` both carry them, and
                // reading extra_size instead emitted the array's DIMENSION as
                // its only element (`[4]u16{1,2,3}` -> `.{ 4 }`).
                if !node.children.is_empty() {
                    self.write(".{ ");
                    for (i, elem) in node.children.iter().enumerate() {
                        if i > 0 {
                            self.write(", ");
                        }
                        self.gen_expr(elem);
                    }
                    self.write(" }");
                    return;
                }

                // Otherwise the parser stored the literal's ELEMENT TEXT in
                // extra_size ("1,2,3" for a list, "0;4" for a repeat).
                // Emit Zig anonymous-list forms, which coerce to the typed
                // array target: `.{ e1, e2, .. }` and `.{ v } ** n`.
                let txt = node.extra_size.trim().to_string();
                if let Some((val, count)) = txt.rsplit_once(';') {
                    self.write(&format!(".{{ {} }} ** {}", val.trim(), count.trim()));
                } else {
                    // Split on TOP-LEVEL commas only -- elements may be calls
                    // with their own commas.
                    let mut elems: Vec<String> = Vec::new();
                    let mut depth = 0i32;
                    let mut cur = String::new();
                    for ch in txt.chars() {
                        match ch {
                            '(' | '[' => {
                                depth += 1;
                                cur.push(ch);
                            }
                            ')' | ']' => {
                                depth -= 1;
                                cur.push(ch);
                            }
                            ',' if depth == 0 => {
                                elems.push(cur.trim().to_string());
                                cur.clear();
                            }
                            _ => cur.push(ch),
                        }
                    }
                    if !cur.trim().is_empty() {
                        elems.push(cur.trim().to_string());
                    }
                    self.write(&format!(".{{ {} }}", elems.join(", ")));
                }
            }
            NodeKind::ExprStructLit => {
                // An anonymous struct carries no type name and MUST keep the
                // leading dot: `.{ .x = 1 }`. Writing an empty name produced
                // `{ .x = 1 }`, which is a block, not a value.
                if node.name.is_empty() {
                    self.write(".");
                } else {
                    self.write(&node.name);
                }
                self.write("{ ");
                for (i, field) in node.children.iter().enumerate() {
                    if i > 0 {
                        self.write(", ");
                    }
                    self.write(&format!(".{} = ", field.name));
                    if !field.children.is_empty() {
                        // W609: an array literal assigned to a SLICE-typed field
                        // needs the same lowering W607 gave slice RETURNS --
                        // `.{ a, b }` is an anonymous struct and Zig will not
                        // coerce it to `[]T`. `&[_]T{...}` is `*const [N]T`, so
                        // the mutable `[]T` that most fields declare needs
                        // @constCast as well.
                        let slice_elem = self
                            .struct_field_types
                            .get(&(node.name.clone(), field.name.clone()))
                            .map(|t| Self::t27_array_type_to_zig(t))
                            .and_then(|t| Self::slice_element_type(&t));
                        let is_array_lit =
                            field.children[0].kind == NodeKind::ExprArrayLiteral;
                        match (slice_elem, is_array_lit) {
                            (Some(elem), true) => {
                                // W609: the REPEAT form `[v; n]` is stored as
                                // element text `v;n` and `gen_array_literal_braces`
                                // splits on commas only, so it emitted the raw
                                // `{ 0;21 }`. Zig spells it `[_]T{v} ** n`.
                                // Caught by the corpus check, not by reasoning.
                                let lit = &field.children[0];
                                let repeat = if lit.children.is_empty() {
                                    lit.extra_size
                                        .trim()
                                        .rsplit_once(';')
                                        .map(|(v, n)| (v.trim().to_string(), n.trim().to_string()))
                                } else {
                                    None
                                };
                                match repeat {
                                    Some((v, n)) => self.write(&format!(
                                        "@constCast(&[_]{}{{ {} }} ** {})",
                                        elem, v, n
                                    )),
                                    None => {
                                        self.write(&format!("@constCast(&[_]{}", elem));
                                        self.gen_array_literal_braces(lit);
                                        self.write(")");
                                    }
                                }
                            }
                            _ => {
                                // W624: `Box { n: s.len() }` where the field
                                // declares a sized int. The W623 fix covered
                                // return and argument position only, because
                                // those are the two the corpus happened to
                                // exercise -- the same population-selection
                                // trap T16 names. Measured by probe, not by
                                // reading the corpus. See T20.
                                let fty = self
                                    .struct_field_types
                                    .get(&(node.name.clone(), field.name.clone()))
                                    .cloned()
                                    .unwrap_or_default();
                                if !self.gen_len_cast(&field.children[0], &fty) {
                                    self.gen_expr(&field.children[0]);
                                }
                            }
                        }
                    }
                }
                self.write(" }");
            }
            NodeKind::ExprCast => {
                if !node.children.is_empty() {
                    let target = node
                        .extra_type
                        .split('[')
                        .next()
                        .unwrap_or("")
                        .trim()
                        .to_string();
                    // MERGE W592+W566: floats keep their dedicated
                    // builtins; integer narrowing lowers to @truncate.
                    let target_is_float = matches!(target.as_str(), "f16" | "f32" | "f64");
                    let src_is_float = self.is_float_expr(&node.children[0]);
                    let builtin = if target_is_float || src_is_float {
                        match (target_is_float, src_is_float) {
                            (true, true) => "@floatCast",
                            (true, false) => "@floatFromInt",
                            (false, true) => "@intFromFloat",
                            (false, false) => unreachable!(),
                        }
                    } else {
                        let target_bits = Self::zig_uint_bits(&target);
                        let src_bits = self.zig_expr_uint_bits(&node.children[0]);
                        let narrowing = match (src_bits, target_bits) {
                            (Some(s), Some(t)) => s > t,
                            _ => false,
                        };
                        if narrowing { "@truncate" } else { "@intCast" }
                    };
                    self.write(&format!("@as({}, {}(", target, builtin));
                    self.gen_expr(&node.children[0]);
                    self.write("))");
                }
            }
            NodeKind::ExprTuple => {
                // Zig anonymous tuple value: `(e0, e1)` -> `.{ e0, e1 }`.
                self.write(".{ ");
                for (i, elem) in node.children.iter().enumerate() {
                    if i > 0 {
                        self.write(", ");
                    }
                    self.gen_expr(elem);
                }
                self.write(" }");
            }
            _ => {}
        }
    }
}

// ============================================================================
// Verilog Code Generator
// ============================================================================

pub struct VerilogCodegen {
    output: String,
    indent: u32,
    /// W700: makes each unrolled `while`'s fuel variable unique within a module.
    /// Two loops in one function would otherwise both declare `__t27_fuel`, and
    /// Verilog rejects the redeclaration -- turning a synthesis repair into a
    /// compile failure.
    while_fuel_counter: u32,
    module_name: String,
    current_fn_name: String,
    current_fn_return_type: String,
    // When true, top-level function-body local declarations have already been
    // hoisted to the top of the body block, so a direct-child StmtLocal must
    // emit only its assignment (Init phase), not a fresh `reg` declaration.
    hoist_fn_locals: bool,
    // When true, `StmtAssign` inside a function body emits a nonblocking
    // assignment (`<=`) instead of a blocking one, so a clocked `fn on_clock`
    // body lowers to correct sequential logic inside an `always @(posedge clk)`.
    clocked_nonblocking: bool,
    // Scalar module-level `var`s exposed as `output reg` data ports (only in a
    // clocked module -- one with an `on_clock` fn). Their body `reg` declaration
    // is suppressed because the ANSI port header already declares them.
    exposed_output_vars: std::collections::HashSet<String>,
    // Width of the parameters of the function currently being lowered, keyed by
    // parameter name. Populated in `gen_verilog_fn`. Used by `ExprCast` lowering
    // to skip a redundant truncation mask when the operand is a parameter that is
    // no wider than the cast target (a widening or same-width cast).
    param_widths: std::collections::HashMap<String, usize>,
    // W527: top-level struct declarations -> field names and types, for
    // packed-vector scalar-struct array lowering.
    struct_decls: std::collections::HashMap<String, Vec<(String, String)>>,
    // W527: function-local variable names -> declared type string, used to
    // resolve multi-dimensional array-of-struct indexing and field access.
    local_types: std::collections::HashMap<String, String>,
    // W528: module-level const/var names -> declared type string.
    module_types: std::collections::HashMap<String, String>,
    // W528: function parameter names -> declared type string.
    param_types: std::collections::HashMap<String, String>,
    // W533: top-level function names -> declared return type string, used to
    // resolve field access on scalar-struct function-call results.
    fn_return_types: std::collections::HashMap<String, String>,
    // W545: module-level const/var primitive scalar arrays that are stored as
    // packed vectors (key: name, value: (dims, elem_type)).  These are created
    // when the initializer is a function call returning the array; indexing is
    // lowered as bit-slices instead of unpacked array access.
    module_packed_primitive_arrays: std::collections::HashMap<String, (Vec<usize>, String)>,
    // W546: function-local primitive scalar arrays that are stored as packed
    // vectors.  The same bit-slice access path applies inside the function scope.
    local_packed_primitive_arrays: std::collections::HashMap<String, (Vec<usize>, String)>,
    // W530: when true, emit active test assertions for Icarus simulation
    // instead of commented-out placeholders.
    emit_test_assertions: bool,
    /// W653 (T74): how many failure checks the CURRENT test block actually
    /// emitted. The block's final verdict must depend on this, not on a flag
    /// set once at construction -- a block can hold statements and still lower
    /// zero checks, which is T45's shape reached by a different route.
    verilog_checks_emitted: usize,
    // W538: monotonic probe index for assert_eq VCD probes inside test blocks.
    probe_counter: usize,
    // W539: per-test-block probe metadata: (probe_name, width_bits, is_signed).
    // W540: extended to include an optional slice offset for multi-signal probes.
    probe_specs: Vec<(String, u32, bool, Option<u32>)>,
    // W553: pre-declared packed-vector temporaries for function calls that return
    // primitive scalar arrays. Key is the call expression text; value is the
    // generated temporary name. The associated packed width/signedness and array
    // info are stored in call_array_tmp_info.
    call_array_tmp_names: std::collections::HashMap<String, String>,
    call_array_tmp_info: std::collections::HashMap<String, (Vec<usize>, String, u32, bool)>,
    // W553: set of call-array temporaries already assigned in the current block.
    call_array_tmp_materialized: std::collections::HashSet<String>,
    // W557: while true, gen_verilog_expr substitutes pre-declared call temporaries
    // for raw ExprCall nodes. This is set only while emitting test/bench blocks.
    use_call_array_temps: bool,
    // W586: true while emitting the left-hand side of an assignment. Signed packed
    // slice expressions must not be wrapped with `$signed(...)` in lvalue position.
    in_lvalue: bool,
    // Restored from Wave Loop 455/458 (batch merge w420-w459 kept the call
    // sites but dropped these declarations, leaving master uncompilable).
    current_fn_name_original: String,
    let_tmp_counter: u32,
    local_arrays: std::collections::HashSet<String>,
    array_param_bindings: std::collections::HashMap<String, std::collections::HashMap<String, String>>,
    array_param_indices: std::collections::HashMap<String, std::collections::HashSet<usize>>,
    array_param_errors: std::collections::HashMap<String, String>,
    // Enums declared by a spec this one `use`s, as (enum, [(variant, value)]).
    // `Enum.variant` has always lowered to the identifier `Enum_variant`, and a
    // `localparam` was declared for it only when the enum was declared in the
    // SAME spec -- so an imported enum produced a reference with no
    // declaration, which no Verilog standard accepts. Populated only through
    // `Compiler::compile_verilog_at`, since resolving `use base::ops;` needs
    // the path of the spec being compiled and a source string does not carry
    // one. Empty everywhere else, which is exactly the old behaviour.
    imported_enums: Vec<(String, Vec<(String, String)>)>,
    imported_structs: Vec<(String, Vec<(String, String)>)>,
}

#[derive(Clone, Copy, PartialEq)]
enum LocalEmitPhase {
    Decl,
    Init,
    Full,
}

impl VerilogCodegen {
    pub fn new() -> Self {
        Self::with_options(false)
    }

    pub fn with_options(emit_test_assertions: bool) -> Self {
        Self {
            while_fuel_counter: 0,
            output: String::new(),
            indent: 0,
            module_name: String::new(),
            current_fn_name: String::new(),
            current_fn_return_type: String::new(),
            hoist_fn_locals: false,
            clocked_nonblocking: false,
            exposed_output_vars: std::collections::HashSet::new(),
            param_widths: std::collections::HashMap::new(),
            struct_decls: std::collections::HashMap::new(),
            local_types: std::collections::HashMap::new(),
            module_types: std::collections::HashMap::new(),
            param_types: std::collections::HashMap::new(),
            fn_return_types: std::collections::HashMap::new(),
            module_packed_primitive_arrays: std::collections::HashMap::new(),
            local_packed_primitive_arrays: std::collections::HashMap::new(),
            emit_test_assertions,
            verilog_checks_emitted: 0,
            probe_counter: 0,
            probe_specs: Vec::new(),
            call_array_tmp_names: std::collections::HashMap::new(),
            call_array_tmp_info: std::collections::HashMap::new(),
            call_array_tmp_materialized: std::collections::HashSet::new(),
            use_call_array_temps: false,
            in_lvalue: false,
            current_fn_name_original: String::new(),
            let_tmp_counter: 0,
            local_arrays: std::collections::HashSet::new(),
            array_param_bindings: std::collections::HashMap::new(),
            array_param_indices: std::collections::HashMap::new(),
            array_param_errors: std::collections::HashMap::new(),
            imported_enums: Vec::new(),
            imported_structs: Vec::new(),
        }
    }

    /// Hand the backend the enums it reaches through `use`.
    ///
    /// Nothing is emitted for an enum the module never names; see
    /// `imported_enum_nodes`.
    /// #2275: imported structs join `struct_decls` so a `param.field` on an
    /// imported struct type resolves to a part-select instead of flattening to
    /// an unbound identifier. Local declarations always win: entries are only
    /// added for names the module does not declare itself.
    pub fn set_imported_structs(&mut self, structs: Vec<(String, Vec<(String, String)>)>) {
        self.imported_structs = structs;
    }

    pub fn set_imported_enums(&mut self, enums: Vec<(String, Vec<(String, String)>)>) {
        self.imported_enums = enums;
    }

    // Restored from Wave Loop 455 (same botched merge).
    fn is_simple_tuple_type(ty: &str) -> bool {
        ty.starts_with('(')
            && ty.ends_with(')')
            && !ty.contains(':')
            && !ty.is_empty()
    }

    // Restored from Wave Loop 455 (same botched merge).
    fn tuple_element_widths(ty: &str) -> Vec<u32> {
        if Self::is_simple_tuple_type(ty) {
            let inner = &ty[1..ty.len() - 1];
            if inner.is_empty() {
                return Vec::new();
            }
            inner
                .split(',')
                .map(|t| Self::type_to_width(t.trim()))
                .collect()
        } else {
            Vec::new()
        }
    }

    // Restored from Wave Loop 458 (batch merge w420-w459 dropped the definition
    // while keeping its call sites).
    fn type_is_float(ty: &str) -> bool {
        matches!(ty, "f32" | "f64")
    }

    // Restored from Wave Loop 455 (same botched merge).
    fn gen_verilog_let_destructuring(
        &mut self,
        lhs_tuple: &Node,
        rhs: &Node,
    ) {
        // W379: infer binding count and per-binding width from the LHS pattern.
        // W380: when a binding has no explicit type, try to infer its width from
        // the callee's tuple return type so mixed-width tuples lower correctly.
        let mut callee_return_type: Option<String> = None;
        if rhs.kind == NodeKind::ExprCall && !rhs.name.is_empty() {
            callee_return_type = self.fn_return_types.get(&rhs.name).cloned();
        }
        let tuple_widths: Vec<u32> = if let Some(ref rt) = callee_return_type {
            Self::tuple_element_widths(rt)
        } else {
            Vec::new()
        };

        let bindings: Vec<(String, u32)> = lhs_tuple
            .children
            .iter()
            .enumerate()
            .map(|(i, c)| {
                let name = Self::verilog_safe_identifier(&c.name,
                );
                let width = if !c.extra_type.is_empty() {
                    Self::type_to_width(&c.extra_type)
                } else if let Some(w) = tuple_widths.get(i).copied() {
                    w
                } else {
                    32u32
                };
                (name, width)
            })
            .collect();
        let tmp = Self::verilog_safe_identifier(
            &format!("_let_tmp_{}", self.let_tmp_counter),
        );
        self.let_tmp_counter += 1;
        let total_width: u32 = bindings.iter().map(|(_, w)| w).sum();

        // Declare the packed temporary and evaluate the RHS call into it.
        self.write_indent();
        self.write_line(&format!(
            "reg [{}:0] {}; // packed temporary for let destructuring",
            total_width.saturating_sub(1),
            tmp
        ));
        self.write_indent();
        self.write(&format!("{} = ", tmp));
        self.gen_verilog_expr(rhs);
        self.write_line(";");

        // Declare scalar regs and assign slices for each binding.
        let mut cursor = total_width;
        for (name, width) in bindings.iter() {
            let high = cursor.saturating_sub(1);
            let low = cursor.saturating_sub(*width);
            self.write_indent();
            self.write_line(&format!(
                "reg [{}:0] {};",
                width.saturating_sub(1),
                name
            ));
            self.write_indent();
            self.write_line(&format!("{} = {}[{}:{}];", name, tmp, high, low));
            cursor = low;
        }
    }

    fn sanitize_identifier(name: &str) -> String {
        name.replace('-', "_")
            .replace(|c: char| !c.is_alphanumeric() && c != '_', "_")
    }

    /// Verilog-2001 reserved keywords. If a user identifier collides with one,
    /// escape it with the \\identifier<space> form so it is treated as an
    /// ordinary identifier and not parsed as a keyword.
    pub(crate) fn verilog_keywords() -> &'static [&'static str] {
        &[
            "always", "and", "assign", "automatic", "begin", "buf", "bufif0", "bufif1",
            "case", "casex", "casez", "cell", "cmos", "config", "deassign", "default",
            "defparam", "design", "disable", "edge", "else", "end", "endcase", "endconfig",
            "endfunction", "endgenerate", "endmodule", "endprimitive", "endspecify",
            "endtable", "endtask", "event", "for", "force", "forever", "fork", "function",
            "generate", "genvar", "highz0", "highz1", "if", "ifnone", "incdir", "include",
            "initial", "inout", "input", "instance", "integer", "join", "large", "liblist",
            "library", "localparam", "macromodule", "medium", "module", "nand", "negedge",
            "nmos", "nor", "noshowcancelled", "not", "notif0", "notif1", "or", "output",
            "parameter", "pmos", "posedge", "primitive", "pull0", "pull1", "pulldown",
            "pullup", "pulsestyle_onevent", "pulsestyle_ondetect", "rcmos", "real", "realtime",
            "reg", "release", "repeat", "rnmos", "rpmos", "rtran", "rtranif0", "rtranif1",
            "scalared", "showcancelled", "signed", "small", "specify", "specparam", "strong0",
            "strong1", "supply0", "supply1", "table", "task", "time", "tran", "tranif0",
            "tranif1", "tri", "tri0", "tri1", "triand", "trior", "trireg", "unsigned", "use",
            "vectored", "wait", "wand", "weak0", "weak1", "while", "wire", "wor", "xnor", "xor",
            // W650: the list above is Verilog-2001, but every Icarus invocation
            // in this repository passes `-g2012`, where these are ALSO reserved.
            // 8 corpus specs declare identifiers named `priority`, `logic`,
            // `string` and friends, and iverilog rejects them with a bare
            // "syntax error". The keyword table was for the wrong language
            // VERSION -- a totality claim (T55) about the wrong universe. T63.
            "alias", "always_comb", "always_ff", "always_latch", "assert", "assume", "before",
            "bind", "bins", "binsof", "bit", "break", "byte", "chandle", "class", "clocking",
            "const", "constraint", "context", "continue", "cover", "covergroup", "coverpoint",
            "cross", "dist", "do", "endclass", "endclocking", "endgroup", "endinterface",
            "endpackage", "endprogram", "endproperty", "endsequence", "enum", "expect",
            "export", "extends", "extern", "final", "first_match", "foreach", "forkjoin",
            "iff", "ignore_bins", "illegal_bins", "import", "inside", "int", "interface",
            "intersect", "join_any", "join_none", "local", "logic", "longint", "matches",
            "modport", "new", "null", "package", "packed", "priority", "program", "property",
            "protected", "pure", "rand", "randc", "randcase", "randsequence", "ref", "restrict", "return",
            "sequence", "shortint", "shortreal", "solve", "static", "string", "struct",
            "super", "tagged", "this", "throughout", "timeprecision", "timeunit", "type",
            "typedef", "union", "unique", "var", "virtual", "void", "wait_order", "wildcard",
            "with", "within",
        ]
    }

    /// Escape identifiers that collide with Verilog keywords. Returns the
    /// escaped form \\name<space> when the name is a keyword, otherwise the
    /// original name. The trailing space is part of the escaped identifier
    /// syntax and must be preserved wherever the identifier is emitted.
    /// Normalize Rust/t27 integer literals embedded in element TEXT (the
    /// array-literal concat path works on raw source text, not AST nodes) to
    /// plain Verilog decimal: `0x20`/`0b1010` and `_` separators are illegal
    /// Verilog (t27#1948). Non-literal text (calls, idents) passes through.
    fn verilog_normalize_literal_text(txt: &str) -> String {
        let t = txt.trim();
        let clean: String = t.chars().filter(|&c| c != '_').collect();
        if let Some(hex) = clean.strip_prefix("0x").or_else(|| clean.strip_prefix("0X")) {
            if !hex.is_empty() && hex.chars().all(|c| c.is_ascii_hexdigit()) {
                if let Ok(n) = u128::from_str_radix(hex, 16) {
                    return n.to_string();
                }
            }
        } else if let Some(bin) = clean.strip_prefix("0b").or_else(|| clean.strip_prefix("0B")) {
            if !bin.is_empty() && bin.chars().all(|c| c == '0' || c == '1') {
                if let Ok(n) = u128::from_str_radix(bin, 2) {
                    return n.to_string();
                }
            }
        } else if !clean.is_empty() && clean.chars().all(|c| c.is_ascii_digit()) {
            return clean;
        }
        t.to_string()
    }

    fn verilog_safe_identifier(name: &str) -> String {
        // W664: a namespaced path reaches here as ONE identifier -- the parser
        // stores `Severity::Error` as a single `ExprIdentifier` whose name
        // contains `::`. The enum DECLARATION is already lowered correctly:
        //
        //     localparam ErrorCode_ParseError = 1000;
        //
        // but every USE site emitted `ErrorCode::ParseError`, which is not
        // Verilog and produced `syntax error` in 23 of the 444 specs that
        // generate. Declaration and use only ever disagreed on the separator.
        //
        // Done here rather than at the expression emitter because this is the
        // single chokepoint every identifier passes through -- the same reason
        // T118 moved keyword escaping to the final name. `::` cannot occur in a
        // legal Verilog identifier, so the substitution can never collide with
        // something that was already correct.
        let name = if name.contains("::") {
            std::borrow::Cow::Owned(name.replace("::", "_"))
        } else {
            std::borrow::Cow::Borrowed(name)
        };
        if Self::verilog_keywords().contains(&name.as_ref()) {
            format!("\\{} ", name)
        } else {
            name.into_owned()
        }
    }

    fn write(&mut self, s: &str) {
        self.output.push_str(s);
    }

    fn write_line(&mut self, s: &str) {
        self.write(s);
        self.write("\n");
    }

    fn indent(&mut self) {
        self.indent += 1;
    }

    fn dedent(&mut self) {
        if self.indent > 0 {
            self.indent -= 1;
        }
    }

    fn write_indent(&mut self) {
        for _ in 0..self.indent {
            self.write("    ");
        }
    }

    pub fn into_string(self) -> String {
        self.output
    }

    /// Map t27 type to Verilog type width. Returns bit width.
    fn type_to_width(ty: &str) -> u32 {
        match ty {
            "bool" => 1,
            "u8" | "i8" => 8,
            "u16" | "i16" => 16,
            "u32" | "i32" => 32,
            "u64" | "i64" => 64,
            "usize" => 32,
            // W655 (T85): `f64` fell through to the 32-bit default and silently
            // narrowed to half its width. Named explicitly so the width is a
            // decision rather than a fallthrough.
            "f32" => 32,
            "f64" => 64,
            _ => 32, // default width
        }
    }

    /// W703: one place that knows how a t27 integer literal spells its radix.
    ///
    /// `0x`/`0X` hex, `0b`/`0B` binary, `_` separators, plain decimal. Returns
    /// `None` for anything else -- including a malformed literal such as
    /// `0xT27B007`, whose `T` is not a hex digit.
    ///
    /// It exists because the conversion had been written twice and only one copy
    /// was complete: `gen_verilog_expr` converted, and the sized-literal path
    /// used by struct and array initializers emitted the raw text, producing
    /// `32'd0x8000`. Two emitters, one of them wrong, and nothing in the corpus
    /// distinguished them until a synthesis sweep did.
    fn literal_value(v: &str) -> Option<u128> {
        let clean: String = v.chars().filter(|&c| c != '_').collect();
        if let Some(hex) = clean.strip_prefix("0x").or_else(|| clean.strip_prefix("0X")) {
            return u128::from_str_radix(hex, 16).ok();
        }
        if let Some(bin) = clean.strip_prefix("0b").or_else(|| clean.strip_prefix("0B")) {
            return u128::from_str_radix(bin, 2).ok();
        }
        if !clean.is_empty() && clean.chars().all(|c| c.is_ascii_digit()) {
            return clean.parse::<u128>().ok();
        }
        None
    }

    /// W699: the width of an entry-point port, or `None` -- never a default.
    ///
    /// `type_to_width` ends in `_ => 32`, which is right for a local register
    /// whose declared type the rest of the lowering also treats as 32 bits, and
    /// WRONG for a module boundary, where the number becomes a contract with
    /// whatever is on the other side. A 512-bit value entering through a 32-bit
    /// port loses 15/16 of itself, and no stage downstream can tell.
    ///
    /// `[N]T` is accepted because N*width(T) is arithmetic. A slice is refused
    /// because its length is not in the type. `f64` is refused because 64 bits is
    /// its SIZE, not its ENCODING -- whether a float port carries raw IEEE bits
    /// or fixed point is a design decision this function does not get to make.
    fn entry_port_width(ty: &str) -> Option<u32> {
        let t = ty.trim();
        match t {
            "bool" => return Some(1),
            "u8" | "i8" => return Some(8),
            "u16" | "i16" => return Some(16),
            "u32" | "i32" | "usize" | "isize" => return Some(32),
            "u64" | "i64" => return Some(64),
            "trit" | "tri" => return Some(2),
            _ => {}
        }
        // `[N]T`
        if let Some(rest) = t.strip_prefix('[') {
            if let Some(close) = rest.find(']') {
                let count = rest[..close].trim();
                if !count.is_empty() && count.chars().all(|c| c.is_ascii_digit()) {
                    let n: u32 = count.parse().ok()?;
                    let inner = Self::entry_port_width(&rest[close + 1..])?;
                    return n.checked_mul(inner);
                }
            }
        }
        None
    }

    /// Map t27 type to Verilog signedness
    fn type_is_signed(ty: &str) -> bool {
        // W655 (T85): `f32`/`f64` were absent here, so a float lowered to an
        // UNSIGNED vector and every comparison against zero inverted. Measured:
        //   f(-1.0)      = 4294967295      the real -1.0 narrowed to [31:0]
        //   (-1.0 < 0.0) = 1               the real comparison is correct
        //   f(-1.0)<0.0  = 0               after narrowing, the sign is GONE
        // A float is signed; saying so removes the inversion. It does NOT make
        // the lowering float arithmetic -- see `f32` in `type_to_width`.
        matches!(ty, "i8" | "i16" | "i32" | "i64" | "f32" | "f64")
    }

    /// W532: total bit width of a scalar-struct field that may be a bare scalar
    /// or a fixed-size array of scalars (e.g. `[3]i16` -> 48).
    fn scalar_field_width(ty: &str) -> u32 {
        let trimmed = ty.trim();
        if let Some(close) = trimmed.find(']') {
            let inner = trimmed[1..close].trim();
            // W670: sound ONLY because `is_lowerable_scalar_struct` rejects a
            // field with EMPTY brackets, so no unsized slice reaches this
            // arithmetic. Verified: `struct Bad { data: []u8, n: u8 }` and a
            // holder containing `[4]Bad` are both UNSUPPORTED_ICARUS.
            // Widen that predicate and this line silently sizes an unsized
            // array as ONE element, moving every later field (T134). The
            // property is stated here because a soundness argument that
            // lives only in another function is a refactor away from being
            // wrong (T115).
            let count: u32 = inner.parse().unwrap_or(1);
            let base = trimmed[close + 1..].trim();
            count * Self::type_to_width(base)
        } else {
            Self::type_to_width(trimmed)
        }
    }

    /// W532: true if a scalar-struct field is signed (bare signed scalar or fixed-
    /// size array of signed scalars).
    fn scalar_field_is_signed(ty: &str) -> bool {
        let trimmed = ty.trim();
        let base = if let Some(close) = trimmed.find(']') {
            trimmed[close + 1..].trim()
        } else {
            trimmed
        };
        Self::type_is_signed(base)
    }

    /// W532: if `ty` is a fixed-size array of primitive scalars, return
    /// (count, element_width, signed).
    fn scalar_array_info(ty: &str) -> Option<(usize, u32, bool)> {
        let trimmed = ty.trim();
        let close = trimmed.find(']')?;
        let inner = trimmed[1..close].trim();
        let count: usize = inner.parse().ok()?;
        let base = trimmed[close + 1..].trim();
        if !Self::is_primitive_scalar_type(base) {
            return None;
        }
        Some((count, Self::type_to_width(base), Self::type_is_signed(base)))
    }

    /// W532: emit a single scalar value (literal or expression) as a Verilog
    /// expression string of the given width and signedness.
    fn emit_packed_scalar_value(&self,
        val: &Node,
        width: u32,
        signed: bool,
    ) -> String {
        // Helper: signed negative literal as a sized expression accepted by
        // Icarus (e.g. -16'sd2) so the result occupies exactly `width` bits.
        let signed_negative = |n: i128| {
            let abs = (-n) as u128;
            format!("-{}'sd{}", width, abs)
        };

        if val.kind == NodeKind::ExprLiteral {
            match val.value.as_str() {
                "true" => return "1'b1".to_string(),
                "false" => return "1'b0".to_string(),
                v => {
                    if signed {
                        if let Ok(n) = v.parse::<i128>() {
                            if n < 0 {
                                return signed_negative(n);
                            } else {
                                return format!("{}'sd{}", width, n.to_string());
                            }
                        }
                        if let Some(n) = Self::literal_value(v) {
                            return format!("{}'sd{}", width, n);
                        }
                        return format!("{}'sd{}", width, v);
                    }
                    // W703: normalise the RADIX here too.
                    //
                    // This site wrote the literal verbatim, so a spec constant
                    // `0x8000` inside a struct initializer became
                    //
                    //     localparam [127:0] SYS_CONFIG = {32'd8, 32'd0x8000, ...}
                    //
                    // and yosys answered `Invalid use of [a-fxz?] in decimal
                    // constant`. The main literal path (`gen_verilog_expr`) has
                    // converted hex and binary since it was written; this one --
                    // reached only from sized contexts such as struct and array
                    // initializers -- never did. One emitter fixed, its sibling
                    // missed: the T53 shape, which is why the repair is a SHARED
                    // helper rather than a second copy of the conversion.
                    if let Some(n) = Self::literal_value(v) {
                        return format!("{}'d{}", width, n);
                    }
                    return format!("{}'d{}", width, v);
                }
            }
        }

        // Unary minus on a numeric literal is common for negative initializers
        // and is not parsed as a single ExprLiteral in t27.
        if signed
            && val.kind == NodeKind::ExprUnary
            && val.extra_op.trim() == "-"
            && val.children.len() == 1
            && val.children[0].kind == NodeKind::ExprLiteral
        {
            let v = val.children[0].value.as_str();
            if let Ok(n) = v.parse::<i128>() {
                return signed_negative(-n);
            }
        }

        let mut buf = String::new();
        self.collect_expr_text(val, &mut buf);
        // W583: non-literal expressions inside packed concatenations need an
        // explicit width context. SystemVerilog `width'(expr)` gives the
        // expression a self-determined size of exactly `width` bits, which
        // prevents Icarus/Yosys from reporting "indefinite width" in a
        // concatenation. For signed fields the result is then reinterpreted with
        // $signed so the packed bits represent a two's-complement value.
        if signed {
            format!("$signed({}'({}))", width, buf)
        } else {
            format!("{}'({})", width, buf)
        }
    }

    /// W532: emit the value for one scalar-struct field (bare scalar or fixed-
    /// size scalar array) as a Verilog expression string suitable for a packed
    /// concatenation.
    fn emit_packed_struct_field_value(&self,
        val: &Node,
        ftype: &str,
    ) -> String {
        if let Some((count, elem_w, signed)) = Self::scalar_array_info(ftype) {
            if val.kind == NodeKind::ExprArrayLiteral {
                let mut parts = Vec::new();
                for elem in val.children.iter().take(count) {
                    parts.push(
                        self.emit_packed_scalar_value(elem, elem_w, signed),
                    );
                }
                while parts.len() < count {
                    parts.push(format!("{}'d0", elem_w));
                }
                // Verilog concatenation is MSB-first; t27 element [0] is LSB.
                parts.reverse();
                return format!("{{{}}}", parts.join(", "));
            }
            return format!("{}'d0", count as u32 * elem_w);
        }
        let fwidth = Self::scalar_field_width(ftype);
        let signed = Self::scalar_field_is_signed(ftype);
        self.emit_packed_scalar_value(val, fwidth, signed)
    }

    /// W532: emit a scalar array-literal element (primitive scalar or scalar
    /// struct) as a Verilog expression string for a packed concatenation.
    fn emit_packed_array_element_value(&self,
        val: &Node,
        elem_type: &str,
    ) -> String {
        if self.struct_decls.contains_key(elem_type) {
            let mut buf = String::new();
            self.collect_expr_text(val, &mut buf);
            return buf;
        }
        let width = Self::type_to_width(elem_type.trim());
        let signed = Self::type_is_signed(elem_type.trim());
        self.emit_packed_scalar_value(val, width, signed)
    }

    /// W459: recursively collect `ExprCall` nodes under `node` whose callee name
    /// matches `name`. Used to discover array-parameter call sites inside
    /// test/invariant/bench blocks as well as module-level statements.
    fn collect_expr_calls<'n>(node: &'n Node, name: &str, out: &mut Vec<&'n Node>) {
        if node.kind == NodeKind::ExprCall && node.name == name {
            out.push(node);
        }
        for child in &node.children {
            Self::collect_expr_calls(child, name, out);
        }
    }

    /// Format a Verilog range declaration like [31:0]
    fn range_decl(width: u32) -> String {
        // A width of 0 is not a narrow signal; it is `field_type_width`'s poison
        // value arriving here, and `width - 1` has no case for it. What that
        // produced depended on a build flag, and CI builds the quiet one:
        //
        //   debug   (overflow-checks on)   panic, "subtract with overflow"
        //   release (overflow-checks off)  `[4294967295:0]`, exit 0, no stderr
        //
        // Ten specs emitted a four-billion-bit range past every green gate
        // (#2566). `struct CoverPoint { name: &str, condition: &str, clock:
        // &str, description: &str }` is the shape: a string field contributes 0
        // by design -- correct in a MIXED struct, where the other fields carry
        // the width -- and there is no other field.
        //
        // Clamped rather than refused. Making such a struct non-lowerable was
        // tried first and cost 17 new elaboration errors in `hir`: the
        // non-lowerable path declares per-field registers at some sites and not
        // at function locals, so `result.assign_count` emitted a reference to a
        // `result_assign_count` that nothing declares. Elaboration errors
        // measured, not guessed: 176 before, 193 after, on the same iverilog.
        //
        // A 1-bit placeholder for a type that occupies no bits keeps every
        // packing and slicing path exactly as it was -- there are no field
        // offsets to disturb, since every field is zero-width -- and emits a
        // legal declaration instead of an impossible one.
        if width <= 1 {
            String::new()
        } else {
            format!("[{}:0]", width - 1)
        }
    }

    /// W528/W533: total packed bit width of any t27 type. Multi-dimensional
    /// arrays of scalar structs and bare scalar structs are expanded into a
    /// packed-vector width; primitive arrays (and all other types) preserve the
    /// legacy scalar width so existing parameter/return signatures stay stable.
    fn packed_width(&self, ty: &str) -> u32 {
        let t = ty.trim();
        if t.starts_with('(') && t.ends_with(')') && t.contains(',') {
            // Tuple type `(T, U, ...)`: packed width is the sum of element widths.
            let inner = &t[1..t.len() - 1];
            return inner.split(',').map(|e| self.packed_width(e.trim())).sum();
        }
        if let Some((dims, elem_type)) = Self::parse_array_type(ty) {
            if self.is_lowerable_scalar_struct_type(&elem_type) {
                let elem_w = self.element_width(&elem_type) as u32;
                return dims.iter().fold(elem_w, |acc, d| acc * (*d as u32));
            }
            // W545: primitive scalar arrays (e.g. [3]u8) are lowered as a single
            // packed vector whose width is the product of dimensions and element
            // width.  This aligns function return declarations with the packed
            // concatenation emitted for array literals.
            if Self::is_primitive_scalar_type(&elem_type) {
                let elem_w = Self::type_to_width(&elem_type);
                return dims.iter().fold(elem_w, |acc, d| acc * (*d as u32));
            }
        }
        if self.is_lowerable_scalar_struct_type(ty) {
            return self.element_width(&Self::base_type_name(ty));
        }
        Self::type_to_width(ty)
    }

    /// W528/W533: signedness of the packed representation of a t27 type. Scalar
    /// structs and scalar-struct arrays are emitted as unsigned packed vectors;
    /// primitive arrays keep the scalar signedness of their element type;
    /// non-array types keep their original signedness.
    fn packed_signed(&self, ty: &str) -> bool {
        if let Some((_dims, elem_type)) = Self::parse_array_type(ty) {
            if self.is_lowerable_scalar_struct_type(&elem_type) {
                return false;
            }
            return Self::type_is_signed(&elem_type);
        }
        if self.is_lowerable_scalar_struct_type(ty) {
            return false;
        }
        Self::type_is_signed(ty)
    }

    /// W553/W557: if `node` is a function call whose return type is a primitive
    /// scalar (including fixed-size scalar arrays), return a temporary descriptor
    /// and a stable textual key for the call.
    fn call_returning_cse_value_info(
        &self,
        node: &Node,
    ) -> Option<(String, Vec<usize>, String, u32, bool)> {
        if node.kind != NodeKind::ExprCall {
            return None;
        }
        let ret_ty = self.fn_return_types.get(&node.name)?;
        let mut key = String::new();
        self.collect_expr_text(node, &mut key);
        if Self::is_primitive_scalar_type(ret_ty) {
            let width = Self::type_to_width(ret_ty);
            let signed = Self::type_is_signed(ret_ty);
            return Some((key, Vec::new(), ret_ty.to_string(), width, signed));
        }
        // W560: packed scalar-struct returns are also lowerable to a single packed
        // vector and can be shared across sites via the call-CSE temporary.
        if self.is_lowerable_scalar_struct_type(ret_ty)
            && Self::parse_array_type(ret_ty).is_none()
        {
            let width = self.packed_width(ret_ty);
            let signed = self.packed_signed(ret_ty);
            return Some((
                key,
                Vec::new(),
                Self::base_type_name(ret_ty),
                width,
                signed,
            ));
        }
        // W563: arrays of lowerable packed scalar structs are treated like packed
        // primitive scalar arrays: one temporary per call, indexed by element/field.
        let (dims, elem_type) = Self::parse_array_type(ret_ty)?;
        if Self::is_primitive_scalar_type(&elem_type)
            || self.is_lowerable_scalar_struct_type(&elem_type)
        {
            let width = self.packed_width(ret_ty);
            let signed = self.packed_signed(ret_ty);
            return Some((key, dims, elem_type, width, signed));
        }
        None
    }

    /// W553/W556: recursively scan an expression subtree and pre-declare
    /// packed-vector temporaries for any primitive-scalar-array value returned by a
    /// function call, whether indexed or used as a whole-array value.
    /// Declarations are emitted in `probe_prelude` before any procedural statement.
    fn predeclare_call_array_tmps(
        &mut self,
        node: &Node,
        block_name: &str,
    ) {
        // If this is an index expression rooted at a function call, register a
        // temporary for the call's packed return value.
        if node.kind == NodeKind::ExprIndex {
            let mut base = node;
            while base.kind == NodeKind::ExprIndex {
                base = match base.children.first() {
                    Some(c) => c,
                    None => break,
                };
            }
            if base.kind == NodeKind::ExprCall {
                if let Some((key, dims, elem_type, width, signed)) =
                    self.call_returning_cse_value_info(base)
                {
                    if !self.call_array_tmp_names.contains_key(&key) {
                        let tmp_name = format!(
                            "_t27_call_tmp_{}_{}",
                            Self::sanitize_identifier(block_name),
                            self.call_array_tmp_names.len()
                        );
                        self.call_array_tmp_names.insert(key.clone(), tmp_name.clone());
                        self.call_array_tmp_info
                            .insert(tmp_name, (dims, elem_type, width, signed));
                    }
                }
            }
        }
        // W556/W557: a bare function call whose return type is a primitive scalar
        // or scalar array also needs a packed-vector / scalar temporary so the
        // same value can be used at multiple sites in one block.
        if node.kind == NodeKind::ExprCall {
            if let Some((key, dims, elem_type, width, signed)) =
                self.call_returning_cse_value_info(node)
            {
                if !self.call_array_tmp_names.contains_key(&key) {
                    let tmp_name = format!(
                        "_t27_call_tmp_{}_{}",
                        Self::sanitize_identifier(block_name),
                        self.call_array_tmp_names.len()
                    );
                    self.call_array_tmp_names.insert(key.clone(), tmp_name.clone());
                    self.call_array_tmp_info
                        .insert(tmp_name, (dims, elem_type, width, signed));
                }
            }
        }
        // Do NOT recurse into loop bodies: a call there runs per iteration and
        // may depend on the loop variable, so it must be emitted inline each
        // pass, never hoisted into one loop-invariant temporary (t27#1948).
        if matches!(
            node.kind,
            NodeKind::StmtForRange | NodeKind::StmtWhile | NodeKind::StmtFor
        ) {
            return;
        }
        for child in &node.children {
            self.predeclare_call_array_tmps(child, block_name);
        }
    }

    /// W553/W557: emit the temporary assignment for a call returning a primitive
    /// scalar or scalar array if it has not already been materialized in this
    /// block.
    fn materialize_call_array_tmp(
        &mut self,
        call_node: &Node,
    ) {
        let Some((key, _dims, _elem_type, _width, _signed)) =
            self.call_returning_cse_value_info(call_node)
        else {
            return;
        };
        let Some(tmp_name) = self.call_array_tmp_names.get(&key).cloned() else {
            return;
        };
        if self.call_array_tmp_materialized.contains(&tmp_name) {
            return;
        }
        let mut call_text = String::new();
        self.collect_expr_text(call_node, &mut call_text);
        self.write_indent();
        self.write_line(&format!("{} = {};", tmp_name, call_text),
        );
        self.call_array_tmp_materialized.insert(tmp_name);
    }

    /// W557: enable call-temporary substitution while emitting a test/bench
    /// block, then disable it again so synthesizable code paths keep raw calls.
    fn with_call_array_temps_enabled<F, R>(&mut self,
        f: F,
    ) -> R
    where
        F: FnOnce(&mut Self) -> R,
    {
        self.use_call_array_temps = true;
        let result = f(self);
        self.use_call_array_temps = false;
        result
    }

    /// W553/W556: recursively scan an expression and materialize every
    /// packed-vector temporary that backs a function-call-return array value,
    /// whether indexed or used as a whole-array value.
    fn materialize_call_array_tmps_in_expr(
        &mut self,
        node: &Node,
    ) {
        if node.kind == NodeKind::ExprIndex {
            let mut base = node;
            while base.kind == NodeKind::ExprIndex {
                base = match base.children.first() {
                    Some(c) => c,
                    None => break,
                };
            }
            if base.kind == NodeKind::ExprCall {
                self.materialize_call_array_tmp(base);
            }
        }
        // W556: materialize the temporary for a bare call returning a primitive
        // scalar array before the statement that uses it.
        if node.kind == NodeKind::ExprCall {
            self.materialize_call_array_tmp(node);
        }
        for child in &node.children {
            self.materialize_call_array_tmps_in_expr(child);
        }
    }

    /// W539: infer the scalar bit width and signedness of an expression in the
    /// Icarus-lowerable subset. Returns None for non-scalar or unresolvable
    /// expressions (structs, arrays, strings, etc.).
    /// W565: emit one operand of a signed-aware ordered comparison. A signed
    /// operand is wrapped in `$signed(...)` (Verilog sign-extends it into the
    /// wider signed comparison context); an unsigned operand is zero-extended by
    /// one bit and reinterpreted as signed, `$signed({1'b0, ...})`, so its value
    /// stays non-negative and the comparison follows C integer-promotion rules.
    fn emit_verilog_signed_rel_operand(&mut self, node: &Node, is_signed: bool) {
        if is_signed {
            self.write("$signed(");
            self.gen_verilog_expr(node);
            self.write(")");
        } else {
            self.write("$signed({1'b0, ");
            self.gen_verilog_expr(node);
            self.write("})");
        }
    }

    fn expr_width_signed(&self, node: &Node) -> Option<(u32, bool)> {
        match node.kind {
            NodeKind::ExprLiteral => {
                // Booleans are scalar; numeric literals default to the width of
                // their inferred type when the literal carries an explicit type
                // annotation, otherwise to the platform int width.
                let lit = node.value.as_str();
                if lit == "true" || lit == "false" {
                    return Some((1, false));
                }
                let ty = node.extra_type.as_str();
                if !ty.is_empty() {
                    return Some((Self::type_to_width(ty), Self::type_is_signed(ty)));
                }
                // Untyped integer literal: default to 32-bit signed (matches
                // the Verilog expression context).
                Some((32, true))
            }
            NodeKind::ExprIdentifier => {
                let ty = self.local_types.get(&node.name)
                    .or_else(|| self.param_types.get(&node.name))
                    .or_else(|| self.module_types.get(&node.name))?;
                // Primitive scalar identifiers are probe-able as before.
                if Self::is_primitive_scalar_type(ty) {
                    Some((Self::type_to_width(ty), Self::type_is_signed(ty)))
                } else if self.is_lowerable_scalar_struct_type(ty)
                    || Self::is_primitive_array_type(ty)
                {
                    // W541/W555/W564: lowerable packed scalar structs, arrays of
                    // scalar structs, and primitive scalar arrays all lower to a
                    // single packed vector that can be probed / compared directly.
                    Some((self.packed_width(ty), self.packed_signed(ty)))
                } else {
                    None
                }
            }
            NodeKind::ExprCall => {
                // Parameterless function calls whose return type is scalar, a
                // lowerable packed scalar struct (W540 wide probe path), or a
                // primitive scalar array (W555 whole-array bench assert_eq), or
                // a packed 1-D array of lowerable scalar structs (W564).
                let ret_ty = self.fn_return_types.get(&node.name)?;
                if Self::is_primitive_scalar_type(ret_ty) {
                    Some((Self::type_to_width(ret_ty), Self::type_is_signed(ret_ty)))
                } else if self.is_lowerable_scalar_struct_type(ret_ty) {
                    // W564: this also covers arrays of scalar structs because
                    // packed_width folds array dimensions into the total width.
                    Some((self.packed_width(ret_ty), self.packed_signed(ret_ty)))
                } else if Self::is_primitive_array_type(ret_ty) {
                    Some((self.packed_width(ret_ty), self.packed_signed(ret_ty)))
                } else {
                    None
                }
            }
            NodeKind::ExprFieldAccess => {
                if node.children.is_empty() {
                    return None;
                }
                let child = &node.children[0];
                // W527/W533/W586: field access on packed scalar struct or array
                // element. The base may be a bare identifier or a chain of
                // ExprIndex nodes for multi-dimensional array access.
                let base_name = match child.kind {
                    NodeKind::ExprIdentifier => child.name.clone(),
                    NodeKind::ExprIndex => {
                        let mut current = child;
                        while current.kind == NodeKind::ExprIndex {
                            current = match current.children.first() {
                                Some(c) => c,
                                None => return None,
                            };
                        }
                        if current.kind == NodeKind::ExprIdentifier {
                            current.name.clone()
                        } else {
                            return None;
                        }
                    }
                    _ => return None,
                };
                let local_ty = self.local_types.get(&base_name)
                    .or_else(|| self.param_types.get(&base_name))
                    .or_else(|| self.module_types.get(&base_name))?;
                let base_ty = Self::base_type_name(local_ty);
                let struct_name = if self.is_lowerable_scalar_struct_type(local_ty) {
                    base_ty
                } else if Self::parse_array_type(local_ty).is_some()
                    && self.is_lowerable_scalar_struct_type(&base_ty)
                {
                    base_ty
                } else {
                    return None;
                };
                let fields = self.struct_decls.get(&struct_name)?;
                let ftype = fields.iter()
                    .find(|(n, _)| n == &node.name)
                    .map(|(_, t)| t.clone())?;
                if Self::is_primitive_scalar_type(&ftype) {
                    Some((Self::type_to_width(&ftype), Self::type_is_signed(&ftype)))
                } else {
                    Self::scalar_array_info(&ftype)
                        .map(|(count, w, signed)| (count as u32 * w, signed))
                }
            }
            NodeKind::ExprIndex => {
                if node.children.len() < 2 {
                    return None;
                }
                // Try to resolve the base as a primitive scalar array.
                let mut current = &node.children[0];
                while current.kind == NodeKind::ExprIndex {
                    current = current.children.first()?;
                }
                if current.kind == NodeKind::ExprCall {
                    // W553: indexing the packed primitive scalar array returned by a
                    // function call (e.g. seq()[0]).
                    if let Some((_key, _dims, elem_type, _width, _signed)) =
                        self.call_returning_cse_value_info(current)
                    {
                        return Some((
                            Self::type_to_width(&elem_type),
                            Self::type_is_signed(&elem_type),
                        ));
                    }
                    return None;
                }
                if current.kind != NodeKind::ExprIdentifier {
                    return None;
                }
                let local_ty = self.local_types.get(&current.name)
                    .or_else(|| self.param_types.get(&current.name))
                    .or_else(|| self.module_types.get(&current.name))?;
                if let Some((_, elem_type)) = Self::parse_array_type(local_ty) {
                    if Self::is_primitive_scalar_type(&elem_type) {
                        return Some((
                            Self::type_to_width(&elem_type),
                            Self::type_is_signed(&elem_type),
                        ));
                    }
                }
                // Scalar-struct array field element access: base is a field
                // access, the field is a fixed-size scalar array.
                if node.children[0].kind == NodeKind::ExprFieldAccess {
                    if let Some(info) = self.field_scalar_array_info(&node.children[0]
                    ) {
                        return Some((info.1, info.2));
                    }
                }
                None
            }
            NodeKind::ExprBinary => {
                if node.children.len() < 2 {
                    return None;
                }
                let op = node.extra_op.as_str();
                // Logical operators return bool (1 bit unsigned).
                if matches!(op, "&&" | "||" | "and" | "or") {
                    return Some((1, false));
                }
                if matches!(op, "==" | "!=" | "<" | "<=" | ">" | ">=") {
                    return Some((1, false));
                }
                // Arithmetic / bitwise operators inherit width/sign from the
                // left operand when both operands are scalar; otherwise fall back.
                let left = self.expr_width_signed(&node.children[0])?;
                let right = self.expr_width_signed(&node.children[1])?;
                // Result width is the max operand width for non-shift ops.
                if matches!(op, "<<" | ">>") {
                    // Shift result width equals the left operand width.
                    return Some(left);
                }
                let width = left.0.max(right.0);
                let signed = left.1 || right.1;
                Some((width, signed))
            }
            NodeKind::ExprUnary => {
                if node.children.is_empty() {
                    return None;
                }
                let op = node.extra_op.as_str();
                let child = self.expr_width_signed(&node.children[0])?;
                // Logical negation returns bool.
                if op == "!" || op == "not" {
                    return Some((1, false));
                }
                // Bitwise/arithmetic negation preserves width/sign.
                Some(child)
            }
            NodeKind::ExprCast => {
                if node.children.is_empty() {
                    return None;
                }
                let base_ty = node
                    .extra_type
                    .split('[')
                    .next()
                    .unwrap_or("")
                    .to_string();
                let width = Self::type_to_width(&base_ty);
                let signed = Self::type_is_signed(&base_ty);
                Some((width, signed))
            }
            NodeKind::ExprArrayLiteral => {
                // W555/W564: a primitive scalar array literal or a lowerable packed
                // scalar-struct array literal has the packed width of its element
                // type times all dimensions.
                let elem = node.extra_type.trim();
                let dims: Vec<usize> = node.extra_size.split("][")
                    .filter_map(|s| s.parse().ok())
                    .collect();
                let dims_count = node.extra_size.split("][").count();
                if !dims.is_empty()
                    && dims.len() == dims_count
                    && (Self::is_primitive_scalar_type(elem)
                        || self.is_lowerable_scalar_struct_type(elem))
                {
                    let ty = format!("[{}]{}", node.extra_size, elem);
                    Some((self.packed_width(&ty), self.packed_signed(&ty)))
                } else {
                    None
                }
            }
            NodeKind::ExprSwitch => {
                // Result type is the type of any case result; use the first one.
                node.children.get(1)
                    .and_then(|c| self.expr_width_signed(c))
            }
            NodeKind::ExprStructLit => {
                // A literal of a lowerable packed scalar struct has the packed
                // vector width of that struct (W540 wide probe path).
                let ty = node.extra_type.as_str();
                let struct_name = if !ty.is_empty() {
                    ty.to_string()
                } else {
                    node.name.clone()
                };
                if self.is_lowerable_scalar_struct_type(&struct_name) {
                    Some((self.element_width(&struct_name), false))
                } else {
                    None
                }
            }
            _ => None,
        }
    }

    /// W539: helper to extract (count, element_width, signed) for a scalar-array
    /// field inside a scalar struct, given a field-access expression node.
    fn field_scalar_array_info(
        &self,
        field_access: &Node,
    ) -> Option<(usize, u32, bool)> {
        if field_access.kind != NodeKind::ExprFieldAccess || field_access.children.is_empty() {
            return None;
        }
        let child = &field_access.children[0];
        let base_name = match child.kind {
            NodeKind::ExprIdentifier => child.name.clone(),
            NodeKind::ExprIndex => {
                let mut current = child;
                while current.kind == NodeKind::ExprIndex {
                    current = match current.children.first() {
                        Some(c) => c,
                        None => return None,
                    };
                }
                if current.kind == NodeKind::ExprIdentifier {
                    current.name.clone()
                } else {
                    return None;
                }
            }
            _ => return None,
        };
        let local_ty = self.local_types.get(&base_name)
            .or_else(|| self.param_types.get(&base_name))
            .or_else(|| self.module_types.get(&base_name))?;
        let base_ty = Self::base_type_name(local_ty);
        let struct_name = if self.is_lowerable_scalar_struct_type(local_ty) {
            base_ty
        } else if Self::parse_array_type(local_ty).is_some()
            && self.is_lowerable_scalar_struct_type(&base_ty)
        {
            base_ty
        } else {
            return None;
        };
        let fields = self.struct_decls.get(&struct_name)?;
        let ftype = fields.iter()
            .find(|(n, _)| n == &field_access.name)
            .map(|(_, t)| t.clone())?;
        Self::scalar_array_info(&ftype)
    }

    /// W527: parse a t27 array type string like "[2][3]Pt" into a list of
    /// dimension sizes and the element type name. Returns None for malformed or
    /// non-array types.
    fn parse_array_type(ty: &str) -> Option<(Vec<usize>, String)> {
        let trimmed = ty.trim();
        // Rust-style `[T; N]`: the whole packed-array machinery (widths,
        // literals, indexing) keys off this parser, and it only understood
        // the legacy `[N]T` spelling -- every `[u32; 4]` fn param lowered as
        // a single 32-bit input (t27#1948 tail).
        if trimmed.starts_with('[') && trimmed.ends_with(']') {
            let inner = &trimmed[1..trimmed.len() - 1];
            if let Some(semi) = inner.rfind(';') {
                let elem = inner[..semi].trim();
                let size_txt = inner[semi + 1..].trim();
                if let Ok(size) = size_txt.parse::<usize>() {
                    if !elem.is_empty() && !elem.contains(';') {
                        return Some((vec![size], elem.to_string()));
                    }
                }
            }
        }
        let mut rest = trimmed;
        let mut dims = Vec::new();
        while rest.starts_with('[') {
            let close = rest.find(']')?;
            let inner = rest[1..close].trim();
            let size: usize = inner.parse().ok()?;
            dims.push(size);
            rest = rest[close + 1..].trim();
        }
        if dims.is_empty() || rest.is_empty() {
            return None;
        }
        Some((dims, rest.to_string()))
    }

    /// W533: strip array brackets from a type string, returning the base type
    /// name. For non-array types the input is returned unchanged.
    fn base_type_name(ty: &str) -> String {
        let trimmed = ty.trim();
        if let Some((_, elem)) = Self::parse_array_type(trimmed) {
            return elem;
        }
        trimmed.to_string()
    }

    /// W681: the single depth bound shared by the lowerability predicate and the
    /// width computation. `field_type_width` and `packed_struct_width` recurse
    /// once EACH per nesting level, so a cap of 8 admits four levels of nesting;
    /// the predicate therefore counts `depth * 2` to stay in step.
    const DEPTH_CAP: u32 = 8;

    /// W671: width of one field's type, consulting `struct_decls` for a nested
    /// struct instead of falling back to `type_to_width`'s default of 32.
    ///
    /// W667 accepted nested structs and the safety test caught the consequence
    /// immediately: `struct Cfg { width: usize, depth: u8, inner: Inner }` was
    /// reported as **72** bits rather than 56, because `Inner` (a real 16 bits)
    /// was sized at the unknown-type default. Every field after the nested one
    /// would then be sliced from the wrong offset. The acceptance was reverted
    /// and the width computation named as the prerequisite (T132).
    ///
    /// This is that prerequisite. `depth` bounds the walk so a struct that
    /// transitively contains itself cannot loop; such a type has no finite
    /// packed width and 0 is returned, which the callers surface as a width of
    /// zero rather than a plausible wrong number.
    /// #2241/#2425: a `&str` field has NO hardware representation. Until now one
    /// such field made the whole struct unlowerable, so every NUMERIC field of it
    /// became unaddressable too -- measured across the corpus: 100 of 438 structs
    /// are blocked this way while all their other fields are primitive scalars.
    ///
    /// Strings are therefore packed at ZERO width and skipped when accumulating
    /// offsets. This cannot shift any existing layout, because a struct with a
    /// string field does not lower today at all; and READING a string field stays
    /// exactly as broken as it is now (it flattens to an unbound name), which is
    /// the honest outcome for a value hardware cannot hold.
    fn is_string_field_type(ty: &str) -> bool {
        let t = ty.trim();
        t == "str" || t == "&str" || t.starts_with("&str") || t.starts_with("[]u8")
    }

    fn field_type_width(&self, ty: &str, depth: u32) -> u32 {
        // W681: 0 is a POISON value, not a width.
        //
        // Measured before this comment existed: a five-level chain of
        // `struct Ln { p: [4]L(n-1), n: u8 }` reported **2,728** bits where the
        // arithmetic gives 10,920. The guard fired, this function returned 0,
        // and `packed_struct_width`'s `sum()` swallowed it -- so the struct was
        // declared at a plausible-looking width that is wrong, and every field
        // after the over-deep one is sliced from the wrong bits.
        //
        // That is the T134 shape again: a default that is never obviously wrong.
        // The repair is not a larger cap; it is that
        // `is_lowerable_scalar_struct_d` must refuse any struct this function
        // cannot size, so the failure is loud. Both guards now use DEPTH_CAP so
        // they cannot drift apart.
        if depth > Self::DEPTH_CAP {
            return 0;
        }
        let t = ty.trim();
        if Self::is_string_field_type(t) {
            return 0;
        }
        if let Some(close) = t.find(']') {
            let inner = t[1..close].trim();
            // Unsized slices are rejected by `is_lowerable_scalar_struct`
            // (T134); if one reaches here the width is genuinely unknown.
            let Ok(count) = inner.parse::<u32>() else {
                return 0;
            };
            let base = t[close + 1..].trim();
            return count * self.field_type_width(base, depth + 1);
        }
        if self.struct_decls.contains_key(t) {
            return self.packed_struct_width(t, depth + 1);
        }
        Self::type_to_width(t)
    }

    /// W671: total packed width of a struct, summing `field_type_width`.
    fn packed_struct_width(&self, name: &str, depth: u32) -> u32 {
        if depth > Self::DEPTH_CAP {
            return 0;
        }
        let Some(fields) = self.struct_decls.get(name) else {
            return 0;
        };
        fields
            .iter()
            .map(|(_, ft)| self.field_type_width(ft, depth))
            .sum()
    }

    /// W527: total bit width of a scalar struct element, or of a primitive
    /// element type. Fixed-size scalar-array fields are counted as
    /// `width * count`.
    fn element_width(&self,
        elem_type: &str,
    ) -> u32 {
        // W671: delegated so a nested struct field is sized by its own packed
        // width rather than type_to_width's default of 32. The inline loop this
        // replaces produced 72 bits for a 56-bit struct (T132).
        if self.struct_decls.contains_key(elem_type) {
            return self.packed_struct_width(elem_type, 0);
        }
        Self::type_to_width(elem_type)
    }

    /// W527: for a scalar struct, return the bit offset (from the LSB of the
    /// element) and width of the named field.
    fn struct_field_offset(&self,
        struct_name: &str,
        field_name: &str,
    ) -> Option<(u32, u32)> {
        // W671: every field is sized by `field_type_width`, which consults
        // `struct_decls` for a nested struct instead of taking type_to_width's
        // default of 32. Before this, a struct containing a 16-bit nested struct
        // reported its successor fields at offsets 16 bits too high (T132).
        let fields = self.struct_decls.get(struct_name)?;
        let mut offset = 0u32;
        for (name, ftype) in fields {
            let fw = self.field_type_width(ftype, 0);
            if name == field_name {
                // A string field has no bits to select. Returning None keeps the
                // old (already broken) flatten-to-unbound-name path for reads of
                // it, instead of inventing a zero-width slice.
                if Self::is_string_field_type(ftype) {
                    return None;
                }
                return Some((offset, fw));
            }
            offset += fw;
        }
        None
    }

    /// W527/W586: emit a Verilog part-select expression for one element of a packed
    /// multi-dimensional array-of-struct local. `linear_expr` is the pre-quoted
    /// textual expression for the linearized element index. If `signed` is true the
    /// resulting slice is reinterpreted with `$signed(...)` so that Icarus treats
    /// the packed bits as two's-complement instead of unsigned.
    fn emit_packed_struct_element_slice(
        &mut self,
        var: &str,
        linear_expr: &str,
        elem_width: u32,
        field_offset: u32,
        field_width: u32,
        signed: bool,
    ) {
        if field_offset == 0 && field_width == elem_width {
            // Whole element: no inner offset needed.
            self.write(&format!(
                "{}[({}) * {} +: {}]",
                var, linear_expr, elem_width, elem_width
            ));
        } else {
            let slice = format!(
                "{}[(({}) * {} + {}) +: {}]",
                var, linear_expr, elem_width, field_offset, field_width
            );
            if signed && !self.in_lvalue {
                self.write(&format!("$signed({})", slice));
            } else {
                self.write(&slice);
            }
        }
    }

    /// W527/W563: walk a chain of ExprIndex nodes rooted at a local
    /// array-of-struct identifier or a call returning an array of scalar structs,
    /// and emit the corresponding packed slice. `trailing_field` is Some("x")
    /// for `m[i][j].x`, None for `m[i][j]`. Returns true if the chain was
    /// recognized and emitted.
    fn try_emit_struct_array_access(
        &mut self,
        node: &Node,
        trailing_field: Option<&str>,
    ) -> bool {
        // Walk down ExprIndex nodes to find the base identifier or call.
        let mut current = node;
        let mut indices: Vec<String> = Vec::new();
        while current.kind == NodeKind::ExprIndex {
            if current.children.len() >= 2 {
                let mut idx_buf = String::new();
                self.collect_expr_text(&current.children[1], &mut idx_buf);
                indices.push(idx_buf);
            }
            current = match current.children.first() {
                Some(c) => c,
                None => return false,
            };
        }

        // Resolve the base expression, dimensions, and element struct type.
        let (base_expr, dims, elem_type) = match current.kind {
            NodeKind::ExprIdentifier if !current.name.is_empty() => {
                let base_name = current.name.clone();
                let local_ty = match self.local_types.get(&base_name)
                    .or_else(|| self.param_types.get(&base_name))
                    .or_else(|| self.module_types.get(&base_name))
                {
                    Some(t) => t.clone(),
                    None => return false,
                };
                let (dims, elem_type) = match Self::parse_array_type(&local_ty) {
                    Some(v) => v,
                    None => return false,
                };
                if !self.struct_decls.contains_key(&elem_type) {
                    return false;
                }
                // T64: `base_name` stops being a lookup key here and becomes
                // emitted TEXT. A parameter named for a Verilog keyword is
                // escaped at its declaration (`\\cross `) and must be escaped
                // at every use too, or the part-select below emits a bare
                // keyword and iverilog reports a plain "syntax error".
                (Self::verilog_safe_identifier(&base_name), dims, elem_type)
            }
            NodeKind::ExprCall if !current.name.is_empty() => {
                let ret_ty = match self.fn_return_types.get(&current.name) {
                    Some(t) => t.clone(),
                    None => return false,
                };
                let (dims, elem_type) = match Self::parse_array_type(&ret_ty) {
                    Some(v) => v,
                    None => return false,
                };
                if !self.struct_decls.contains_key(&elem_type) {
                    return false;
                }
                let mut call_key = String::new();
                self.collect_expr_text(current, &mut call_key);
                let base_expr = if self.use_call_array_temps
                    && !self.call_array_tmp_names.is_empty()
                {
                    self.call_array_tmp_names
                        .get(&call_key)
                        .cloned()
                        .unwrap_or_else(|| format!("({})", call_key))
                } else {
                    format!("({})", call_key)
                };
                (base_expr, dims, elem_type)
            }
            _ => return false,
        };

        // Indices were collected from outermost to innermost; reverse to row-major.
        indices.reverse();
        if indices.len() != dims.len() {
            return false;
        }

        let elem_width = self.element_width(&elem_type);
        let linear = if dims.len() == 1 {
            indices[0].clone()
        } else {
            let mut expr = indices[0].clone();
            for (i, dim) in dims.iter().enumerate().skip(1) {
                expr = format!("(({}) * {} + {})", expr, dim, indices[i]);
            }
            expr
        };

        let (field_offset, field_width, signed) = if let Some(fname) = trailing_field {
            let (off, fw) = match self.struct_field_offset(&elem_type, fname) {
                Some(v) => v,
                None => return false,
            };
            let ftype = self.struct_decls.get(&elem_type)
                .and_then(|fs| fs.iter().find(|(n, _)| n == fname).map(|(_, t)| t.clone()))
                .unwrap_or_default();
            (off, fw, Self::scalar_field_is_signed(&ftype))
        } else {
            (0u32, elem_width, false)
        };

        self.emit_packed_struct_element_slice(
            &base_expr,
            &linear,
            elem_width,
            field_offset,
            field_width,
            signed,
        );
        true
    }

    /// W532/W562: emit a packed slice for `base[outer...].field[inner]` where
    /// `field` is a fixed-size scalar array inside a scalar struct. Handles both
    /// single scalar structs (`p.data[k]`) and arrays of scalar structs
    /// (`grid[i][j].data[k]`). Also handles the case where the base is a call
    /// returning a scalar struct with a scalar-array field, slicing a
    /// pre-declared packed-vector temporary if one exists. Returns true if the
    /// access was recognised.
    fn try_emit_struct_array_field_element_access(
        &mut self,
        node: &Node,
    ) -> bool {
        if node.kind != NodeKind::ExprIndex || node.children.len() < 2 {
            return false;
        }
        let field_access = match node.children.first() {
            Some(fa) if fa.kind == NodeKind::ExprFieldAccess => fa,
            _ => return false,
        };
        let field_name = &field_access.name;
        if field_access.children.is_empty() {
            return false;
        }

        // W562: the base may be a function call returning a scalar struct.
        // Determine the base expression text, optional call temporary, and the
        // struct element type that owns the scalar-array field.
        let base_child = &field_access.children[0];
        let mut base_expr = String::new();
        let mut elem_type = String::new();
        let mut needs_parens = true;
        let mut base_is_array_of_struct = false;
        let mut outer_indices: Vec<String> = Vec::new();

        match base_child.kind {
            NodeKind::ExprCall if !base_child.name.is_empty() => {
                self.collect_expr_text(base_child, &mut base_expr);
                if let Some(ret_ty) = self.fn_return_types.get(&base_child.name) {
                    elem_type = Self::base_type_name(ret_ty);
                    if !self.is_lowerable_scalar_struct_type(&elem_type)
                        || Self::parse_array_type(ret_ty).is_some()
                    {
                        return false;
                    }
                    // W562: if a call temporary exists, slice it directly.
                    if self.use_call_array_temps
                        && !self.call_array_tmp_names.is_empty()
                    {
                        if let Some(tmp_name) =
                            self.call_array_tmp_names.get(&base_expr).cloned()
                        {
                            base_expr = tmp_name;
                            needs_parens = false;
                        }
                    }
                } else {
                    return false;
                }
            }
            _ => {
                // Walk the outer ExprIndex chain inside the field access to find
                // the base identifier (existing W532 path).
                let mut current = base_child;
                while current.kind == NodeKind::ExprIndex {
                    if current.children.len() >= 2 {
                        let mut idx_buf = String::new();
                        self.collect_expr_text(&current.children[1], &mut idx_buf);
                        outer_indices.push(idx_buf);
                    }
                    current = match current.children.first() {
                        Some(c) => c,
                        None => return false,
                    };
                }
                let base_name = match current.kind {
                    NodeKind::ExprIdentifier if !current.name.is_empty() => {
                        current.name.clone()
                    }
                    _ => return false,
                };
                let local_ty = match self.local_types.get(&base_name)
                    .or_else(|| self.param_types.get(&base_name))
                    .or_else(|| self.module_types.get(&base_name))
                {
                    Some(t) => t.clone(),
                    None => return false,
                };

                // Resolve the element type and outer dimensions.
                let (dims, et) = match Self::parse_array_type(&local_ty) {
                    Some((d, et)) => {
                        base_is_array_of_struct = true;
                        (d, et)
                    }
                    None => (Vec::new(), local_ty.clone()),
                };
                if !self.struct_decls.contains_key(&et) {
                    return false;
                }
                elem_type = et;
                outer_indices.reverse();
                if outer_indices.len() != dims.len() {
                    return false;
                }
                base_expr = base_name;
                needs_parens = false;
            }
        }

        if elem_type.is_empty() {
            return false;
        }

        let field_offset = match self.struct_field_offset(&elem_type, field_name,
        ) {
            Some((off, _)) => off,
            None => return false,
        };
        let field_type = match self.struct_decls.get(&elem_type) {
            Some(fields) => match fields.iter().find(|(n, _)| n == field_name) {
                Some((_, ft)) => ft.clone(),
                None => return false,
            },
            None => return false,
        };
        let (_count, inner_w, signed) = match Self::scalar_array_info(&field_type
        ) {
            Some(v) => v,
            None => return false,
        };
        let mut inner_idx = String::new();
        self.collect_expr_text(&node.children[1], &mut inner_idx);

        let slice_expr = if base_is_array_of_struct {
            let elem_width = self.element_width(&elem_type);
            let linear = if outer_indices.is_empty() {
                "0".to_string()
            } else {
                let mut expr = outer_indices[0].clone();
                for (i, dim) in Self::parse_array_type(
                    &format!("[{}]", outer_indices.iter().map(|_| "1").collect::<Vec<_>>().join("]["))).unwrap_or_default().0.iter().enumerate().skip(1)
                {
                    let _ = dim;
                    expr = format!("(({}) * 1 + {})", expr, outer_indices[i]);
                }
                for (i, dim) in Self::parse_array_type(
                    &format!("[{}]dummy", outer_indices.iter().map(|_| "1").collect::<Vec<_>>().join("]["))).unwrap_or_default().0.iter().enumerate().skip(1)
                {
                    let _ = dim;
                    expr = format!("(({}) * 1 + {})", expr, outer_indices[i]);
                }
                // Reconstruct actual dims from the base type for correct stride.
                let (dims, _et) = Self::parse_array_type(
                    &self.local_types.get(&base_expr).or_else(|| self.param_types.get(&base_expr)).or_else(|| self.module_types.get(&base_expr)).cloned().unwrap_or_default()
                ).unwrap_or_default();
                let mut expr = outer_indices[0].clone();
                for (i, dim) in dims.iter().enumerate().skip(1) {
                    expr = format!("(({}) * {} + {})", expr, dim, outer_indices[i]);
                }
                expr
            };
            format!(
                "{}[(({}) * {} + {} + ({} * {})) +: {}]",
                base_expr, linear, elem_width, field_offset, inner_idx, inner_w, inner_w
            )
        } else {
            // Single scalar-struct base (or call temporary): no outer element
            // stride, just field offset + inner index * element width.
            format!(
                "{}[({} + ({} * {})) +: {}]",
                base_expr, field_offset, inner_idx, inner_w, inner_w
            )
        };

        // W560/W562: parenthesize the base expression only if it is a raw
        // function call; identifiers and temporaries do not need parentheses
        // around a part-select.
        let final_expr = if needs_parens {
            format!("({})[({} + ({} * {})) +: {}]", base_expr, field_offset, inner_idx, inner_w, inner_w)
        } else {
            slice_expr
        };

        if signed && !self.in_lvalue {
            self.write(&format!("$signed({})", final_expr));
        } else {
            self.write(&final_expr);
        }
        true
    }

    /// W527: helper that renders an expression subtree into a buffer without
    /// touching `self.output`. Used to build index expressions for dynamic
    /// part-selects and to build stable textual keys for call CSE.
    fn collect_expr_text(&self,
        node: &Node,
        buf: &mut String,
    ) {
        // Dispatch into a temporary codegen instance so we reuse the existing
        // expression emitter without mutating the real output.
        // W557: the temporary instance must never substitute call temporaries,
        // because this function is used both to build deduplication keys and to
        // render the RHS of the temporary assignment itself.
        let mut tmp = VerilogCodegen {
            output: String::new(),
            indent: 0,
            while_fuel_counter: 0,
            module_name: String::new(),
            current_fn_name: String::new(),
            current_fn_return_type: String::new(),
            hoist_fn_locals: false,
            clocked_nonblocking: false,
            exposed_output_vars: std::collections::HashSet::new(),
            param_widths: self.param_widths.clone(),
            struct_decls: self.struct_decls.clone(),
            local_types: self.local_types.clone(),
            module_types: self.module_types.clone(),
            param_types: self.param_types.clone(),
            fn_return_types: self.fn_return_types.clone(),
            module_packed_primitive_arrays: self.module_packed_primitive_arrays.clone(),
            local_packed_primitive_arrays: self.local_packed_primitive_arrays.clone(),
            emit_test_assertions: self.emit_test_assertions,
            verilog_checks_emitted: 0,
            probe_counter: 0,
            probe_specs: Vec::new(),
            call_array_tmp_names: self.call_array_tmp_names.clone(),
            call_array_tmp_info: self.call_array_tmp_info.clone(),
            call_array_tmp_materialized: std::collections::HashSet::new(),
            use_call_array_temps: false,
            in_lvalue: false,
            current_fn_name_original: String::new(),
            let_tmp_counter: 0,
            local_arrays: std::collections::HashSet::new(),
            array_param_bindings: std::collections::HashMap::new(),
            array_param_indices: std::collections::HashMap::new(),
            array_param_errors: std::collections::HashMap::new(),
            imported_enums: Vec::new(),
            imported_structs: Vec::new(),
        };
        tmp.gen_verilog_expr(node);
        buf.push_str(&tmp.output);
    }

    /// W527: emit procedural assignments that initialize a packed multi-
    /// dimensional array-of-struct local from a nested array literal.
    fn emit_packed_struct_array_init(
        &mut self,
        var: &str,
        ty: &str,
        init: &Node,
    ) {
        let (dims, elem_type) = match Self::parse_array_type(ty) {
            Some(v) => v,
            None => return,
        };
        let elem_width = self.element_width(&elem_type) as usize;
        self.emit_packed_struct_array_init_level(var, &dims, 0, elem_width, init, "");
    }

    fn emit_packed_struct_array_init_level(
        &mut self,
        var: &str,
        dims: &[usize],
        depth: usize,
        elem_width: usize,
        node: &Node,
        base_expr: &str,
    ) {
        if depth + 1 == dims.len() {
            // Innermost dimension: `node` should be an array literal of elements.
            if node.kind != NodeKind::ExprArrayLiteral {
                return;
            }
            let current_dim = dims[depth];
            for (i, elem) in node.children.iter().enumerate() {
                if i >= current_dim {
                    break;
                }
                let idx = if base_expr.is_empty() {
                    i.to_string()
                } else {
                    format!("({}) * {} + {}", base_expr, current_dim, i)
                };
                let mut rhs = String::new();
                self.collect_expr_text(elem, &mut rhs);
                self.write_indent();
                self.write_line(&format!(
                    "{}[({}) * {} +: {}] = {};",
                    var, idx, elem_width, elem_width, rhs
                ));
            }
            return;
        }

        // Outer dimension: `node` is an array literal of sub-arrays.
        if node.kind != NodeKind::ExprArrayLiteral {
            return;
        }
        let current_dim = dims[depth];
        for (i, sub) in node.children.iter().enumerate() {
            if i >= current_dim {
                break;
            }
            let idx = if base_expr.is_empty() {
                i.to_string()
            } else {
                format!("({}) * {} + {}", base_expr, current_dim, i)
            };
            self.emit_packed_struct_array_init_level(
                var, dims, depth + 1, elem_width, sub, &idx,
            );
        }
    }

    /// W528: parse an array-literal text fragment (e.g. the ExprIdentifier
    /// stored for a module-level const like `[2][3]Pt{...}`) into an
    /// ExprArrayLiteral on demand. This avoids changing the shared AST for
    /// other backends.
    fn parse_array_literal_text(&self, text: &str) -> Option<Node> {
        let lexer = Lexer::new(text);
        let mut parser = Parser::new(lexer);
        parser.parse_array_literal().ok()
    }

    /// W528: emit a nested array literal as a single packed concatenation,
    /// suitable for a module-level parameter/localparam initializer. Each
    /// innermost element is rendered through `emit_packed_array_element_value`
    /// so primitive scalars are sized correctly and scalar struct literals lower
    /// to their packed concatenation. Missing entries are padded with sized zero.
    fn emit_packed_array_literal_concat(
        &mut self,
        node: &Node,
        ty: &str,
    ) {
        let (dims, elem_type) = match Self::parse_array_type(ty) {
            Some(v) => v,
            None => {
                self.write("0 /* TODO: packed array literal for non-array type */");
                return;
            }
        };
        let elem_w = self.element_width(&elem_type) as usize;
        self.emit_packed_array_literal_concat_level(
            node, &dims, 0, elem_w, &elem_type,
        );
    }

    fn emit_packed_array_literal_concat_level(
        &mut self,
        node: &Node,
        dims: &[usize],
        depth: usize,
        elem_w: usize,
        elem_type: &str,
    ) {
        let current_dim = dims[depth];
        let mut parts = Vec::new();
        if depth + 1 == dims.len() {
            // Innermost dimension: elements are scalar struct literals or
            // primitive expressions. Render each element to a string.
            let inner = if node.kind == NodeKind::ExprArrayLiteral {
                &node.children[..]
            } else {
                &node.children[..0]
            };
            for elem in inner.iter().take(current_dim) {
                parts.push(self.emit_packed_array_element_value(elem, elem_type));
            }
            // The parser stores list-form element text in extra_size with NO
            // children ("m0, m1, m2, m3"): the children-only path rendered a
            // literal of ZEROS for every element built from parameters or
            // calls (t27#1948 tail). Split top-level commas and give each
            // element the width-cast the packed concatenation needs.
            if inner.is_empty()
                && node.kind == NodeKind::ExprArrayLiteral
                && !node.extra_size.trim().is_empty()
                && !node.extra_size.contains("][")
            {
                let txt = node.extra_size.trim();
                if let Some((val, count)) = txt.rsplit_once(';') {
                    if let Ok(n) = count.trim().parse::<usize>() {
                        for _ in 0..n.min(current_dim) {
                            parts.push(format!("{}'({})", elem_w, Self::verilog_normalize_literal_text(val)));
                        }
                    }
                } else {
                    let mut depth_c = 0i32;
                    let mut cur = String::new();
                    let mut elems_txt: Vec<String> = Vec::new();
                    for ch in txt.chars() {
                        match ch {
                            '(' | '[' => {
                                depth_c += 1;
                                cur.push(ch);
                            }
                            ')' | ']' => {
                                depth_c -= 1;
                                cur.push(ch);
                            }
                            ',' if depth_c == 0 => {
                                elems_txt.push(cur.trim().to_string());
                                cur.clear();
                            }
                            _ => cur.push(ch),
                        }
                    }
                    if !cur.trim().is_empty() {
                        elems_txt.push(cur.trim().to_string());
                    }
                    for e in elems_txt.iter().take(current_dim) {
                        parts.push(format!("{}'({})", elem_w, Self::verilog_normalize_literal_text(e)));
                    }
                }
            }
        } else {
            // Outer dimensions: each child is a sub-array literal.
            let outer = if node.kind == NodeKind::ExprArrayLiteral {
                &node.children[..]
            } else {
                &node.children[..0]
            };
            for sub in outer.iter().take(current_dim) {
                let mut tmp = VerilogCodegen {
                    while_fuel_counter: 0,
                    output: String::new(),
                    indent: 0,
                    module_name: String::new(),
                    current_fn_name: String::new(),
                    current_fn_return_type: String::new(),
                    hoist_fn_locals: false,
                    clocked_nonblocking: false,
                    exposed_output_vars: std::collections::HashSet::new(),
                    param_widths: self.param_widths.clone(),
                    struct_decls: self.struct_decls.clone(),
                    local_types: self.local_types.clone(),
                    module_types: self.module_types.clone(),
                    param_types: self.param_types.clone(),
                    fn_return_types: self.fn_return_types.clone(),
                    module_packed_primitive_arrays: self.module_packed_primitive_arrays.clone(),
                    local_packed_primitive_arrays: self.local_packed_primitive_arrays.clone(),
                    emit_test_assertions: self.emit_test_assertions,
                    verilog_checks_emitted: 0,
                    probe_counter: 0,
                    probe_specs: Vec::new(),
                    call_array_tmp_names: self.call_array_tmp_names.clone(),
                    call_array_tmp_info: self.call_array_tmp_info.clone(),
                    call_array_tmp_materialized: std::collections::HashSet::new(),
                    use_call_array_temps: false,
                    in_lvalue: false,
                    current_fn_name_original: String::new(),
                    let_tmp_counter: 0,
                    local_arrays: std::collections::HashSet::new(),
                    array_param_bindings: std::collections::HashMap::new(),
                    array_param_indices: std::collections::HashMap::new(),
                    array_param_errors: std::collections::HashMap::new(),
                    imported_enums: Vec::new(),
            imported_structs: Vec::new(),
                };
                tmp.emit_packed_array_literal_concat_level(
                    sub, dims, depth + 1, elem_w, elem_type,
                );
                parts.push(tmp.output);
            }
        }
        // Pad missing entries with sized zero.
        while parts.len() < current_dim {
            parts.push(format!("{}'d0", elem_w));
        }
        // Verilog concatenation is MSB-first, but t27 element [0] is stored at
        // the LSB of the packed vector, so emit elements in reverse order.
        parts.reverse();
        self.write(&format!("{{{}}}", parts.join(", ")));
    }

    /// W531: primitive scalar types that can be packed into a bit vector.
    fn is_primitive_scalar_type(ty: &str) -> bool {
        matches!(
            ty.trim(),
            "u8" | "u16" | "u32" | "u64" | "i8" | "i16" | "i32" | "i64" | "bool"
        )
    }

    /// W532: a scalar struct is lowerable to a packed vector iff every field is
    /// either a primitive scalar or a fixed-size array of primitive scalars.
    /// Fields of type string, enum, float, or nested aggregate are rejected.
    fn is_lowerable_scalar_struct(
        name: &str,
        structs: &std::collections::HashMap<String, Vec<(String, String)>>,
    ) -> bool {
        Self::is_lowerable_scalar_struct_d(name, structs, 0)
    }

    /// W667: the same predicate with a recursion depth, so a struct may contain
    /// another lowerable struct.
    ///
    /// WHY THIS WIDENED, AND ONLY THIS FAR. T131 traced the corpus' largest
    /// defect class to this `all()`: one field it rejects drops the whole struct
    /// into a per-field fallback that declares `reg <TypeName>_<field>` at module
    /// level while every use emits `<varname>_<field>`, names that can never
    /// agree.
    ///
    /// The blocking field types were then MEASURED across 1,138 structs, because
    /// the example that motivated the work (`BrainState { arousal: ArousalLevel }`)
    /// pointed at enums and enums are the smallest blocker there is:
    ///
    ///     other 2339 | f32/f64 212 | usize/isize 173 | nested struct 133 | enum 46
    ///
    /// Structs that become lowerable, by extension:
    ///
    ///     + usize/isize ............ 25
    ///     + nested lowerable struct  18
    ///     + f32/f64 ................ 55   <- NOT TAKEN
    ///
    /// **Floats are deliberately still rejected.** `type_to_width` would give
    /// them 32 or 64 bits and the packed path would slice them as raw bits, while
    /// the function that reads the field returns Verilog `real`. That is a
    /// silently wrong value in place of a loud failure -- the trade T124 exists
    /// to forbid. Accepting them is worth 55 structs and is not worth that.
    ///
    /// `usize`/`isize` are safe because they are integers of a fixed width that
    /// `type_to_width` already agrees on (32).
    ///
    /// **NESTED STRUCTS ARE ALSO REJECTED, and the reason was found by the test
    /// written before this change was measured.** Accepting them made
    ///
    ///     struct Inner { lo: u8, hi: u8 }              // 16 bits
    ///     struct Cfg { width: usize, depth: u8, inner: Inner }
    ///
    /// lower as **72** bits rather than 56, because `struct_field_offset` and
    /// `element_width` size an unknown field type with `type_to_width`'s default
    /// of 32 and do not consult the nested struct's own packed width. Every field
    /// after the nested one would then be sliced from the wrong offset, and
    /// `a.inner.lo` from the wrong bits entirely.
    ///
    /// That is silent wrongness in place of a loud failure -- the same trade
    /// refused above for floats, and refusing it for floats while accepting it
    /// here would be incoherent. Nested structs are worth 18 more structs and
    /// need the width computation fixed first; they get their own wave.
    fn is_lowerable_scalar_struct_d(
        name: &str,
        structs: &std::collections::HashMap<String, Vec<(String, String)>>,
        depth: u32,
    ) -> bool {
        // W681: the SAME cap the width computation uses. When these two drifted
        // -- the predicate counting struct levels while `field_type_width`
        // counted field-then-struct, twice per level -- a struct the predicate
        // accepted could be one the width function refused to size, and the
        // refusal was a silent 0. They now share DEPTH_CAP, and the predicate
        // is deliberately the STRICTER of the two: it consumes one level per
        // nesting step against the width function's two, so anything it accepts
        // can be sized.
        if depth * 2 > Self::DEPTH_CAP {
            return false;
        }
        let Some(fields) = structs.get(name) else {
            return false;
        };
        !fields.is_empty()
            && fields.iter().all(|(_, t)| {
                let trimmed = t.trim();
                let base = if let Some(end) = trimmed.find(']') {
                    // W669: an UNSIZED slice has no packed width, and accepting
                    // one is worse than rejecting the struct.
                    //
                    // `struct_field_offset` sizes an array as
                    // `inner.parse().unwrap_or(1)`. For `[]u8` the brackets are
                    // empty, the parse fails, and the field silently becomes ONE
                    // element -- so `struct S { data: []u8, n: u8 }` lowered as
                    // 16 bits with `n` at offset 8. Measured against the sized
                    // forms, which are correct:
                    //
                    //     []u8    -> 16 bits,  n at s[8 +: 8]     <- WRONG
                    //     [4]u8   -> 40 bits,  n at s[32 +: 8]    correct
                    //     [16]u8  -> 136 bits, n at s[128 +: 8]   correct
                    //
                    // Every field after an unsized slice is therefore read from
                    // the wrong bits, and the slice itself yields only its first
                    // element. Measured across the tree: 183 structs, 306 such
                    // fields, 344 fields positioned after one, 58 specs.
                    //
                    // This is the silent-wrongness trade that W667 refused for
                    // floats and for nested structs (T132). It was already
                    // shipping here. Rejecting the struct converts a wrong answer
                    // into a loud one, which is the whole of T124.
                    let inner = trimmed[1..end].trim();
                    if inner.is_empty() {
                        return false;
                    }
                    trimmed[end + 1..].trim()
                } else {
                    trimmed
                };
                Self::is_string_field_type(base)
                    || Self::is_primitive_scalar_type(base)
                    || matches!(base, "usize" | "isize")
                    // W671: a nested struct is admissible now that
                    // `field_type_width` sizes it by its own packed width rather
                    // than type_to_width's default of 32. W667 accepted this and
                    // reverted within the wave because the width was wrong --
                    // `Cfg { width: usize, depth: u8, inner: Inner }` reported 72
                    // bits for a 56-bit struct (T132). The prerequisite is now
                    // in place and verified by that same test.
                    //
                    // `base != name` blocks the direct self-reference; the depth
                    // bound in `field_type_width` blocks an indirect cycle, and
                    // returns width 0 rather than a plausible wrong number.
                    || (base != name
                        && Self::is_lowerable_scalar_struct_d(base, structs, depth + 1))
            })
    }

    /// W533: true if `ty` (possibly an array of scalar structs, or a bare scalar
    /// struct) is lowerable to a packed vector.
    fn is_lowerable_scalar_struct_type(
        &self,
        ty: &str,
    ) -> bool {
        let base = Self::base_type_name(ty);
        Self::is_lowerable_scalar_struct(&base, &self.struct_decls)
    }

    /// W531: true if `ty` is an array whose element type is a primitive scalar.
    fn is_primitive_array_type(ty: &str) -> bool {
        let Some((_, elem_type)) = Self::parse_array_type(ty) else {
            return false;
        };
        Self::is_primitive_scalar_type(&elem_type)
    }

    /// W531: return the dimension sizes and element type of a primitive array.
    fn primitive_array_info(ty: &str) -> Option<(Vec<usize>, String)> {
        let (dims, elem_type) = Self::parse_array_type(ty)?;
        if !Self::is_primitive_scalar_type(&elem_type) {
            return None;
        }
        Some((dims, elem_type))
    }

    /// W531: emit an element access expression for an unpacked primitive array
    /// using Verilog multidimensional indexing (e.g. `m[i][j]`).
    fn emit_unpacked_primitive_array_access(
        &mut self,
        var: &str,
        indices: &[String],
    ) {
        // W643: the init path wrote the name raw while every expression path
        // escaped it, so a local array named after a Verilog keyword was
        // declared and initialised unescaped. See T53.
        self.write(&Self::verilog_safe_identifier(var));
        for idx in indices {
            self.write("[");
            self.write(idx);
            self.write("]");
        }
    }

    /// W531: walk a chain of ExprIndex nodes rooted at a primitive array
    /// identifier and emit the corresponding unpacked element access. Returns
    /// true if the chain was recognized and emitted.
    fn try_emit_primitive_array_access(&mut self, node: &Node) -> bool {
        // Walk down ExprIndex nodes to find the base identifier.
        let mut current = node;
        let mut indices: Vec<String> = Vec::new();
        while current.kind == NodeKind::ExprIndex {
            if current.children.len() >= 2 {
                let mut idx_buf = String::new();
                self.collect_expr_text(&current.children[1], &mut idx_buf);
                indices.push(idx_buf);
            }
            current = match current.children.first() {
                Some(c) => c,
                None => return false,
            };
        }
        let (base_name, packed_info) = match current.kind {
            NodeKind::ExprIdentifier if !current.name.is_empty() => {
                let info = self.module_packed_primitive_arrays.get(&current.name)
                    .or_else(|| self.local_packed_primitive_arrays.get(&current.name))
                    .cloned()
                    .or_else(|| {
                        // #1745: an array-typed parameter is lowered to a single
                        // packed vector, so its elements must be indexed by
                        // element-wide slices too -- otherwise `xs[i]` is a
                        // bit-select and reads one bit instead of the element.
                        self.param_types
                            .get(&current.name)
                            .and_then(|ty| Self::primitive_array_info(ty))
                    });
                (current.name.clone(), info)
            }
            NodeKind::ExprCall => {
                // W553: indexing a function call that returns a packed primitive
                // scalar array. A pre-declared packed-vector temporary is used as
                // the indexing base because Verilog does not allow bit-select on a
                // function-call expression directly.
                let mut call_text = String::new();
                self.collect_expr_text(current, &mut call_text);
                match self.call_array_tmp_names.get(&call_text).cloned() {
                    Some(tmp_name) => {
                        let info = self
                            .call_array_tmp_info
                            .get(&tmp_name)
                            .map(|(dims, elem_type, _width, _signed)| {
                                (dims.clone(), elem_type.clone())
                            });
                        (tmp_name, info)
                    }
                    None => return false,
                }
            }
            _ => return false,
        };

        // W458: a parameter bound to a module-level array is a real UNPACKED
        // Verilog array (`reg [W] rom [0:N]`), so index it as `rom[i]` -- not a
        // packed bit-slice on the param name. (The binding lookup is keyed by the
        // original fn name; see the current_fn_name_original restore in
        // gen_verilog_fn.)
        if let Some(bound) = self
            .array_param_bindings
            .get(&self.current_fn_name_original)
            .and_then(|b| b.get(&base_name))
            .cloned()
        {
            let mut ordered = indices.clone();
            ordered.reverse();
            self.write(&Self::verilog_safe_identifier(&bound));
            for idx in &ordered {
                self.write(&format!("[{}]", idx));
            }
            return true;
        }

        // W545/W546/W553: primitive scalar arrays stored as packed vectors are
        // indexed by bit-slices.
        let packed_info = packed_info.as_ref();
        if let Some((dims, elem_type)) = packed_info {
            let elem_w = Self::type_to_width(elem_type).max(1) as usize;
            if indices.len() != dims.len() {
                return false;
            }
            // Multi-dimensional packed layout: row-major linearization in element
            // units.  For [2][3]u8 with element width 8, element [i][j] is at
            // flat element index (i * 3 + j).  The bit offset is that index times
            // elem_w.
            // W554: indices are collected outermost-first; put them in source order
            // before computing the row-major flat index.
            indices.reverse();
            let flat_idx = if indices.len() == 1 {
                indices[0].clone()
            } else {
                // W548: compute the flat element index first.
                let mut stride = 1usize;
                let mut parts = Vec::new();
                for (idx, dim) in indices.iter().zip(dims.iter()).rev() {
                    if stride == 1 {
                        parts.push(idx.clone());
                    } else {
                        parts.push(format!("({} * {})", idx, stride));
                    }
                    stride *= dim;
                }
                parts.reverse();
                parts.join(" + ")
            };
            // W547: a part-select of a signed packed vector is unsigned in
            // Verilog.  Wrap the slice with $signed(...) when the element type is
            // signed so that comparisons, arithmetic, and probes preserve t27's
            // two's-complement semantics.
            let elem_signed = Self::type_is_signed(&elem_type);
            if elem_signed {
                self.write("$signed(");
            }
            let is_literal_idx = flat_idx.parse::<u32>().is_ok();
            if is_literal_idx {
                // Literal flat index: scale by elem_w to get bit offset.
                let i: usize = flat_idx.parse().unwrap_or(0);
                let hi = (i + 1) * elem_w - 1;
                let lo = i * elem_w;
                self.write(&format!(
                    "{}[{}:{}]",
                    Self::verilog_safe_identifier(&base_name),
                    hi,
                    lo
                ));
            } else {
                // W548: scale the flat element index by elem_w to get the bit
                // offset for the variable part-select.
                self.write(&format!(
                    "{}[(({}) * {}) +: {}]",
                    Self::verilog_safe_identifier(&base_name),
                    flat_idx,
                    elem_w,
                    elem_w
                ));
            }
            if elem_signed {
                self.write(")");
            }
            return true;
        }

        let local_ty = match self.local_types.get(&base_name)
            .or_else(|| self.param_types.get(&base_name))
            .or_else(|| self.module_types.get(&base_name))
        {
            Some(t) => t.clone(),
            None => return false,
        };
        let (dims, _elem_type) = match Self::primitive_array_info(&local_ty) {
            Some(v) => v,
            None => return false,
        };

        // Indices were collected from outermost to innermost; reverse to row-major.
        indices.reverse();
        if indices.len() != dims.len() {
            return false;
        }

        self.emit_unpacked_primitive_array_access(&base_name, &indices);
        true
    }

    /// W531: emit procedural assignments that initialize an unpacked primitive
    /// multi-dimensional array from a nested array literal.
    fn emit_unpacked_primitive_array_init(
        &mut self,
        var: &str,
        ty: &str,
        init: &Node,
    ) {
        let (dims, _elem_type) = match Self::primitive_array_info(ty) {
            Some(v) => v,
            None => return,
        };
        let mut indices: Vec<String> = Vec::new();
        self.emit_unpacked_primitive_array_init_level(
            var, &dims, 0, init, &mut indices,
        );
    }

    fn emit_unpacked_primitive_array_init_level(
        &mut self,
        var: &str,
        dims: &[usize],
        depth: usize,
        node: &Node,
        indices: &mut Vec<String>,
    ) {
        if depth + 1 == dims.len() {
            // Innermost dimension: `node` should be an array literal of elements.
            if node.kind != NodeKind::ExprArrayLiteral {
                return;
            }
            let current_dim = dims[depth];
            for (i, elem) in node.children.iter().enumerate() {
                if i >= current_dim {
                    break;
                }
                indices.push(i.to_string());
                let mut rhs = String::new();
                self.collect_expr_text(elem, &mut rhs);
                self.write_indent();
                self.emit_unpacked_primitive_array_access(var, indices);
                self.write_line(&format!(" = {};", rhs));
                indices.pop();
            }
            return;
        }

        // Outer dimension: `node` is an array literal of sub-arrays.
        if node.kind != NodeKind::ExprArrayLiteral {
            return;
        }
        let current_dim = dims[depth];
        for (i, sub) in node.children.iter().enumerate() {
            if i >= current_dim {
                break;
            }
            indices.push(i.to_string());
            self.emit_unpacked_primitive_array_init_level(
                var, dims, depth + 1, sub, indices,
            );
            indices.pop();
        }
    }

    /// Rewrite const-name array sizes to numeric literals in every type
    /// string so the (literal-only) array-type parser lowers `[u32; N]`
    /// consistently for params, returns, locals and fields. Verilog packing
    /// keys off parse_array_type; an unresolved const name (`[u32; HISTORY_SIZE]`)
    /// silently fell back to a 32-bit scalar, desyncing packed callers from
    /// packed locals (t27#1948).
    fn resolve_array_size_consts(
        ty: &str,
        consts: &std::collections::HashMap<String, String>,
    ) -> String {
        let t = ty.trim();
        if let Some(semi) = t.rfind(';') {
            if t.starts_with('[') && t.ends_with(']') {
                let size = t[semi + 1..t.len() - 1].trim();
                if size.parse::<usize>().is_err() {
                    if let Some(v) = consts.get(size) {
                        if v.parse::<usize>().is_ok() {
                            return format!("{}; {}]", &t[..semi], v);
                        }
                    }
                }
            }
        }
        ty.to_string()
    }

    fn rewrite_type_consts(
        node: &mut Node,
        consts: &std::collections::HashMap<String, String>,
    ) {
        if !node.extra_type.is_empty() {
            node.extra_type = Self::resolve_array_size_consts(&node.extra_type, consts);
        }
        if !node.extra_return_type.is_empty() {
            node.extra_return_type =
                Self::resolve_array_size_consts(&node.extra_return_type, consts);
        }
        for p in node.params.iter_mut() {
            p.1 = Self::resolve_array_size_consts(&p.1, consts);
        }
        for child in node.children.iter_mut() {
            Self::rewrite_type_consts(child, consts);
        }
    }

    pub fn gen_verilog(&mut self, ast_in: &Node) {
        // Resolve const-name array sizes up front, then work off the rewritten
        // clone so array packing is uniform (t27#1948).
        let mut size_consts: std::collections::HashMap<String, String> =
            std::collections::HashMap::new();
        for decl in &ast_in.children {
            if decl.kind == NodeKind::ConstDecl {
                if let Some(v) = decl.children.first() {
                    if v.kind == NodeKind::ExprLiteral && v.value.parse::<usize>().is_ok() {
                        size_consts.insert(decl.name.clone(), v.value.clone());
                    }
                }
            }
        }
        let mut ast_owned = ast_in.clone();
        Self::rewrite_type_consts(&mut ast_owned, &size_consts);
        let ast = &ast_owned;

        self.module_name = if !ast.name.is_empty() {
            Self::sanitize_identifier(&ast.name)
        } else {
            "unknown".to_string()
        };

        // Header
        self.write_line(
            "// ============================================================================",
        );
        self.write_line(&format!("// Generated from t27 spec: {}", self.module_name));
        self.write_line("// DO NOT EDIT - generated by t27c gen-verilog");
        self.write_line("// phi^2 + 1/phi^2 = 3 | TRINITY");
        self.write_line(
            "// ============================================================================",
        );
        self.write_line("");
        self.write_line("`timescale 1ns / 1ps");
        self.write_line("`default_nettype none");
        self.write_line("");

        // Collect declarations by kind for structured emission
        let mut consts: Vec<&Node> = Vec::new();
        let mut enums: Vec<&Node> = Vec::new();
        let mut structs: Vec<&Node> = Vec::new();
        let mut functions: Vec<&Node> = Vec::new();
        let mut tests: Vec<&Node> = Vec::new();
        let mut invariants: Vec<&Node> = Vec::new();
        let mut benches: Vec<&Node> = Vec::new();
        // W458: bare module-level statements (e.g. calls to functions that take
        // array parameters). Emitted inside an always @(*) block.
        let mut module_stmts: Vec<&Node> = Vec::new();
        // W649: module-level `var` names, so the boilerplate port header can
        // avoid colliding with a signal the spec declares and drives.
        let mut module_regs: Vec<String> = Vec::new();

        for decl in &ast.children {
            match decl.kind {
                NodeKind::ConstDecl => consts.push(decl),
                NodeKind::EnumDecl => enums.push(decl),
                NodeKind::StructDecl => structs.push(decl),
                NodeKind::FnDecl => functions.push(decl),
                NodeKind::TestBlock => tests.push(decl),
                NodeKind::InvariantBlock => invariants.push(decl),
                NodeKind::BenchBlock => benches.push(decl),
                NodeKind::StmtLocal => module_regs.push(decl.name.clone()),
                NodeKind::StmtExpr | NodeKind::StmtAssign => module_stmts.push(decl),
                _ => {}
            }
        }

        // W527: cache struct declarations for packed-vector AoS lowering.
        for s in &structs {
            let fields: Vec<(String, String)> = s
                .children
                .iter()
                .map(|f| (f.name.clone(), f.extra_type.clone()))
                .collect();
            self.struct_decls.insert(s.name.clone(), fields);
        }
        // #2275: imported structs fill the gaps -- never shadow a local decl.
        for (name, fields) in &self.imported_structs.clone() {
            self.struct_decls
                .entry(name.clone())
                .or_insert_with(|| fields.clone());
        }

        // W528: cache module-level const/var type annotations so function-local
        // and test-bench code can resolve packed array-of-struct accesses.
        for c in &consts {
            if !c.extra_type.is_empty() {
                self.module_types.insert(c.name.clone(), c.extra_type.clone());
            }
        }

        // W533: cache top-level function return types for field access on call
        // results.
        for f in &functions {
            if !f.extra_return_type.is_empty() {
                self.fn_return_types
                    .insert(f.name.clone(), f.extra_return_type.clone());
            }
        }

        // W458: resolve module-level array parameter bindings. For each
        // function that accepts an array parameter, inspect the single
        // module-level call site (bare StmtExpr -> ExprCall in the module
        // body) to determine which module-level array identifier is passed
        // for that parameter. Multiple call sites or non-identifier
        // arguments are recorded as errors and the function is skipped.
        {
            let mut bindings: std::collections::HashMap<
                String,
                std::collections::HashMap<String, String>,
            > = std::collections::HashMap::new();
            let mut indices: std::collections::HashMap<
                String,
                std::collections::HashSet<usize>,
            > = std::collections::HashMap::new();
            let mut errors: std::collections::HashMap<String, String> =
                std::collections::HashMap::new();

            for f in &functions {
                let array_param_indices: Vec<usize> = f
                    .params
                    .iter()
                    .enumerate()
                    .filter(|(_, (_, ptype))| {
                        // Rust-style primitive [T; N] params are packed-vector
                        // VALUES (declared at packed_width, indexed by
                        // part-select via #1745). The legacy [N]T spelling
                        // keeps the W458 module-array binding contract (ROM
                        // tables bound by name at the call site).
                        let rust_style_primitive = ptype.trim().starts_with('[')
                            && ptype.contains(';')
                            && Self::parse_array_type(ptype)
                                .map_or(false, |(_, elem)| {
                                    Self::is_primitive_scalar_type(&elem)
                                });
                        Self::parse_array_type(ptype).is_some() && !rust_style_primitive
                    })
                    .map(|(i, _)| i)
                    .collect();
                if array_param_indices.is_empty() {
                    continue;
                }

                // W459: collect call sites from module-level statements and from
                // test/invariant/bench blocks. All sites must agree on the same
                // module-level array identifier for each array parameter.
                let mut call_sites: Vec<&Node> = Vec::new();
                for decl in &ast.children {
                    match decl.kind {
                        NodeKind::StmtExpr => {
                            if let Some(expr) = decl.children.first() {
                                if expr.kind == NodeKind::ExprCall && expr.name == f.name {
                                    call_sites.push(expr);
                                }
                            }
                        }
                        NodeKind::TestBlock
                        | NodeKind::InvariantBlock
                        | NodeKind::BenchBlock => {
                            Self::collect_expr_calls(decl, &f.name, &mut call_sites);
                        }
                        _ => {}
                    }
                }

                // NO CALL SITE is not a defect. An array parameter that cannot
                // be bound to a module-level array is simply passed BY VALUE:
                // it stays a real `input [W-1:0]` and the body indexes it by
                // element slice (#1745). Refusing instead skipped the whole
                // function, which is how specs/ternary/bitnet_layer came to
                // print "function on_comb has array parameter(s) but no call
                // site" four lines above `assign result = on_comb(...)` -- the
                // emitter wrote the call and then denied it. t27#2743.
                if call_sites.is_empty() {
                    continue;
                }

                let mut fn_bindings: std::collections::HashMap<String, String> =
                    std::collections::HashMap::new();
                let mut broken = false;
                for idx in &array_param_indices {
                    let (pname, _ptype) = &f.params[*idx];
                    let mut arg_names: Vec<String> = Vec::new();
                    for call in &call_sites {
                        if let Some(arg) = call.children.get(*idx) {
                            if arg.kind == NodeKind::ExprIdentifier && !arg.name.is_empty() {
                                arg_names.push(arg.name.clone());
                            } else {
                                arg_names.push("W458_NON_ID".to_string());
                            }
                        } else {
                            arg_names.push("W458_MISSING".to_string());
                        }
                    }
                    let unique: std::collections::HashSet<String> =
                        arg_names.iter().cloned().collect();
                    // CONFLICTING call sites are not a defect either: one
                    // function used with two different arrays -- `neuronN(acts,
                    // w0, ..)` and `neuronN(acts, w1, ..)` -- cannot be
                    // specialised to one name, so it takes the by-value path
                    // like any other unbindable parameter.
                    if unique.len() != 1 {
                        broken = true;
                        break;
                    }
                    let bound = arg_names.into_iter().next().unwrap();
                    // An argument that is not a plain identifier -- an
                    // expression, or absent -- names no module array to bind
                    // to. Third form of the same situation, and the same
                    // answer: pass the array by value.
                    if bound == "W458_NON_ID" || bound == "W458_MISSING" {
                        broken = true;
                        break;
                    }
                    fn_bindings.insert(pname.clone(), bound);
                }
                if !broken {
                    bindings.insert(f.name.clone(), fn_bindings);
                    indices.insert(
                        f.name.clone(),
                        array_param_indices.into_iter().collect(),
                    );
                }
            }

            self.array_param_bindings = bindings;
            self.array_param_indices = indices;
            self.array_param_errors = errors;
        }

        // Emit top-level module
        let mod_name = self.module_name.clone();
        // #1764: in a clocked module (an `on_clock` fn is present) the registered
        // scalar `var`s ARE the module's observable state. Expose each as an
        // `output reg` data port so the design synthesizes to real flip-flops
        // instead of being dead-code-eliminated (yosys DCEs a port-less design to
        // zero cells). Gated on `on_clock`, so non-clocked specs -- and every
        // existing spec -- keep the byte-identical `(clk,rst_n,en,ready)` header.
        let has_on_clock = functions.iter().any(|f| f.name == "on_clock");
        self.exposed_output_vars.clear();
        let mut exposed_ports: Vec<(String, usize, bool)> = Vec::new();
        if has_on_clock {
            for c in &consts {
                let is_scalar = Self::parse_array_type(&c.extra_type).is_none()
                    && !Self::is_primitive_array_type(&c.extra_type)
                    && !self.struct_decls.contains_key(&c.extra_type);
                if c.extra_mutable && is_scalar {
                    let w = Self::type_to_width(&c.extra_type) as usize;
                    let signed = Self::type_is_signed(&c.extra_type);
                    exposed_ports.push((c.name.clone(), w, signed));
                    self.exposed_output_vars.insert(c.name.clone());
                }
            }
        }
        // #1764: the parameters of `on_clock` (streaming) or `on_comb`
        // (combinational) become INPUT data ports, so a spec can consume data fed
        // in on real ports (`fn on_clock(x: i16) {...}` -> `input signed [15:0] x`).
        // Only present when such a fn takes params -> existing specs unchanged.
        //
        // W699: THE WIDTH IS DERIVED OR THE PORT IS REFUSED. It is never defaulted.
        //
        // This site used `type_to_width`, whose last arm is `_ => 32`. That is
        // correct for every entry signature in the corpus today -- measured: all
        // 74 specs declaring `on_comb`/`on_clock` use only sized primitives, so
        // the default never fires. It is a LATENT defect, and W698 stepped on it:
        // widening the entry-point predicate to accept `[8]u64` produced
        //
        //     input  wire [31:0] acts,       // for a 512-bit parameter
        //
        // and nothing complained -- not the banner, not the census, not the
        // corpus column, not yosys. A silent 16x narrowing.
        //
        // `entry_port_width` returns `None` rather than a plausible number, and a
        // parameter it cannot size makes the whole entry point refuse, loudly, in
        // the generated source. T190b: the accepting side must be the stricter,
        // so anything accepted can be sized.
        let mut input_ports: Vec<(String, u32, bool)> = Vec::new();
        let mut entry_refusal: Option<String> = None;
        if let Some(oc) = functions.iter().find(|f| f.name == "on_clock" || f.name == "on_comb") {
            let mut widths: Vec<(String, u32, bool)> = Vec::new();
            for (pname, ptype) in &oc.params {
                match Self::entry_port_width(ptype) {
                    Some(w) => widths.push((pname.clone(), w, Self::type_is_signed(ptype))),
                    None => {
                        entry_refusal = Some(format!("{pname}: {ptype}"));
                        break;
                    }
                }
            }
            if entry_refusal.is_none() {
                input_ports = widths;
            }
        }
        // `on_comb` is the combinational counterpart of `on_clock`: its return is a
        // continuously-driven `output wire result` (`assign result = on_comb(...)`),
        // so a purely combinational spec (dot27, an adder, a whole MLP) synthesizes
        // to real LUTs instead of being dead-code-eliminated. Only when defined.
        let comb_result: Option<(u32, bool, Vec<String>)> = if entry_refusal.is_some() {
            None
        } else {
            functions.iter().find(|f| f.name == "on_comb").and_then(|f| {
                let w = Self::entry_port_width(&f.extra_return_type)?;
                let signed = Self::type_is_signed(&f.extra_return_type);
                let params: Vec<String> = f.params.iter().map(|(p, _)| p.clone()).collect();
                Some((w, signed, params))
            })
        };
        if comb_result.is_none() && entry_refusal.is_none() {
            if let Some(f) = functions.iter().find(|f| f.name == "on_comb") {
                if Self::entry_port_width(&f.extra_return_type).is_none() {
                    entry_refusal = Some(format!("-> {}", f.extra_return_type));
                }
            }
        }

        // W649: the boilerplate `(clk, rst_n, en)` header was emitted
        // UNCONDITIONALLY, so a spec that declares `var clk : bool = false` --
        // every testbench does, and drives it -- got `clk` as an input PORT and
        // again as `reg clk;` in the same scope. iverilog:
        // "'clk' has already been declared in this scope". 24 corpus specs.
        //
        // The spec's intent is unambiguous: it declares the signal and assigns
        // it, so the `reg` is right and the PORT is wrong. Dropping the reg --
        // the obvious reading of the error -- would have made a driven signal an
        // undrivable input. See T62.
        let declares = |n: &str| {
            consts.iter().any(|c| c.name == n) || module_regs.iter().any(|r| r == n)
        };
        self.write_line(&format!("module {} (", mod_name));
        self.indent();
        for p in ["clk", "rst_n", "en"] {
            if declares(p) {
                continue;
            }
            self.write_indent();
            self.write_line(&format!("input  wire        {},", p));
        }
        for (name, w, signed) in &input_ports {
            let range = Self::range_decl(*w);
            let signed_str = if *signed { "signed " } else { "" };
            // W650: the FOURTH unescaped emit site, and the one T53 predicted.
            // A spec parameter named `priority` produced `input [31:0] priority;`
            // -- reserved under `-g2012`, which is how every Icarus run in this
            // repository invokes iverilog. See T63.
            let name = Self::verilog_safe_identifier(name);
            self.write_indent();
            if range.is_empty() {
                self.write_line(&format!("input  wire {}{},", signed_str, name));
            } else {
                self.write_line(&format!("input  wire {}{} {},", signed_str, range, name));
            }
        }
        self.write_indent();
        let n_extra_out = exposed_ports.len() + if comb_result.is_some() { 1 } else { 0 };
        if n_extra_out == 0 {
            self.write_line("output wire        ready");
        } else {
            self.write_line("output wire        ready,");
            let mut emitted = 0;
            for (name, w, signed) in &exposed_ports {
                let range = Self::range_decl(*w as u32);
                let signed_str = if *signed { "signed " } else { "" };
                emitted += 1;
                let comma = if emitted < n_extra_out { "," } else { "" };
                self.write_indent();
                if range.is_empty() {
                    self.write_line(&format!("output reg {}{}{}", signed_str, name, comma));
                } else {
                    self.write_line(&format!("output reg {}{} {}{}", signed_str, range, name, comma));
                }
            }
            if let Some((w, signed, _)) = &comb_result {
                let range = Self::range_decl(*w);
                let signed_str = if *signed { "signed " } else { "" };
                self.write_indent();
                if range.is_empty() {
                    self.write_line(&format!("output wire {}result", signed_str));
                } else {
                    self.write_line(&format!("output wire {}{} result", signed_str, range));
                }
            }
        }
        self.dedent();
        self.write_line(");");
        // W655 (T96): a module whose header is ONLY the boilerplate
        // `(clk, rst_n, en, ready)` has no way to move a value across its own
        // boundary, so synthesis optimises the entire design away. Measured
        // across the corpus: 800 of 849 generated modules (94.2%) are in this
        // state, and the 49 that are not are all `specs/ternary/gft_*` -- the
        // difference is one naming convention, a function called `on_comb`.
        //
        // We do NOT guess a default. Picking, say, the last `pub fn` would
        // silently promote an internal helper to a public boundary, and a wrong
        // boundary is worse than none. Following T52's remedy, the ABSENCE gets
        // a reserved symbol instead: loud, greppable, and countable.
        if input_ports.is_empty() && exposed_ports.is_empty() && comb_result.is_none() {
            self.write_line(
                "// NO DATA PORTS -- this module cannot move a value across its boundary.",
            );
            self.write_line(
                "// Synthesis will optimise it to nothing. Add `fn on_comb(...) -> T` to give",
            );
            self.write_line(
                "// it a combinational surface: parameters become inputs, the return becomes",
            );
            self.write_line("// `result`. See T81.");
            // W699: and if there IS an entry point but a type has no derivable
            // width, say which one. The alternative -- the `_ => 32` default --
            // produces a port that looks right and carries a fraction of the
            // value, which is the failure T190a measured: a 512-bit parameter
            // became `input wire [31:0]` and nothing downstream noticed.
            if let Some(what) = &entry_refusal {
                self.write_line(
                    "// ENTRY POINT REFUSED -- a parameter or return has no derivable width:",
                );
                self.write_line(&format!("//     {what}"));
                self.write_line(
                    "// `[N]T` is accepted (N*width(T) is arithmetic). A slice has no length in",
                );
                self.write_line(
                    "// the type; `f64` has a size but not an encoding. Neither is guessed here.",
                );
            }
        }
        self.write_line("");

        self.indent();

        // Section: Parameters from const declarations
        if !consts.is_empty() {
            self.write_indent();
            self.write_line("// -------------------------------------------------------");
            self.write_indent();
            self.write_line("// Parameters (from const declarations)");
            self.write_indent();
            self.write_line("// -------------------------------------------------------");
            for c in &consts {
                self.gen_verilog_const(c);
            }
            self.write_line("");
        }

        // Section: Enum parameters
        //
        // An enum reached through `use` is emitted by the SAME function as a
        // same-spec enum, because the body already spells the reference the
        // same way -- `Enum.variant` lowers to `Enum_variant` whichever spec
        // declared it. Imported ones come first: they are what the local
        // declarations may depend on, never the other way round.
        let imported_enum_nodes = self.imported_enum_nodes(ast, &enums);
        if !enums.is_empty() || !imported_enum_nodes.is_empty() {
            self.write_indent();
            self.write_line("// -------------------------------------------------------");
            self.write_indent();
            self.write_line("// Enum constants");
            self.write_indent();
            self.write_line("// -------------------------------------------------------");
            for e in &imported_enum_nodes {
                self.gen_verilog_enum(e);
            }
            for e in &enums {
                self.gen_verilog_enum(e);
            }
            self.write_line("");
        }

        // Section: R-SI-1 compliant multiplication helper.
        // OpenLane R-SI-1 forbids the `*` operator in synthesizable RTL.
        // t27c emits `__mul_noop(a, b)` instead of `a * b`; this 64-bit
        // shift-and-add ladder is unconditionally injected so any module is
        // self-contained.
        self.write_indent();
        self.write_line("// -------------------------------------------------------");
        self.write_indent();
        self.write_line("// R-SI-1: multiplication helper (no `*` operator)");
        self.write_indent();
        self.write_line("// -------------------------------------------------------");
        self.write_indent();
        self.write_line("function [63:0] __mul_noop; // t27#1886: 64-bit, u64 products no longer truncate");
        self.write_indent();
        self.write_line("    input [63:0] a;");
        self.write_indent();
        self.write_line("    input [63:0] b;");
        self.write_indent();
        self.write_line("    integer i;");
        self.write_indent();
        self.write_line("    reg [127:0] acc;");
        self.write_indent();
        self.write_line("    begin");
        self.write_indent();
        self.write_line("        acc = 128'd0;");
        self.write_indent();
        self.write_line("        for (i = 0; i < 64; i = i + 1) begin");
        self.write_indent();
        self.write_line("            if (b[i]) acc = acc + ({64'd0, a} << i);");
        self.write_indent();
        self.write_line("        end");
        self.write_indent();
        self.write_line("        __mul_noop = acc[63:0];");
        self.write_indent();
        self.write_line("    end");
        self.write_indent();
        self.write_line("endfunction");
        self.write_line("");

        // Section: Struct → register/signal declarations
        if !structs.is_empty() {
            self.write_indent();
            self.write_line("// -------------------------------------------------------");
            self.write_indent();
            self.write_line("// Registers (from struct declarations)");
            self.write_indent();
            self.write_line("// -------------------------------------------------------");
            // Declare struct field regs under the module-level `var` name that
            // holds the struct (e.g. `uart_state_status`), matching exactly what
            // gen_verilog_expr emits for field access. Falling back to the struct
            // type name (`uartstate_status`) leaves every field reference an
            // undeclared identifier and breaks iverilog compilation.
            let mut struct_var: std::collections::HashMap<String, String> =
                std::collections::HashMap::new();
            for c in &consts {
                if c.extra_mutable && !c.extra_type.is_empty() {
                    struct_var
                        .entry(c.extra_type.clone())
                        .or_insert_with(|| c.name.clone());
                }
            }
            for s in &structs {
                let prefix = struct_var
                    .get(&s.name)
                    .cloned()
                    .unwrap_or_else(|| s.name.to_lowercase());
                self.gen_verilog_struct(s, &prefix);
            }
            self.write_line("");
        }

        // Ready signal
        self.write_indent();
        self.write_line("assign ready = 1'b1;");
        self.write_line("");

        // Section: Functions → always blocks or sub-modules
        // A function named `on_clock` is the opt-in clocked process: it lowers to
        // an `always @(posedge clk)` that registers module-level `var` state with
        // reset and `en` gating. Every other function stays combinational. Specs
        // without an `on_clock` fn are unaffected (byte-identical output).
        let (clocked, comb): (Vec<&Node>, Vec<&Node>) =
            functions.iter().partition(|f| f.name == "on_clock");
        if !comb.is_empty() {
            self.write_indent();
            self.write_line("// -------------------------------------------------------");
            self.write_indent();
            self.write_line("// Combinational logic (from function declarations)");
            self.write_indent();
            self.write_line("// -------------------------------------------------------");
            for f in &comb {
                self.gen_verilog_fn(f);
            }
        }
        // Clocked process: register module `var` state on the rising clock edge.
        for f in &clocked {
            self.gen_verilog_clocked_fn(f, &consts);
        }
        // `on_comb`: continuously drive the `result` output port from the
        // combinational function of the input data ports.
        if let Some((_, _, params)) = &comb_result {
            self.write_line("");
            self.write_indent();
            self.write_line(&format!("assign result = on_comb({});", params.join(", ")));
        }

        // Section: Module-level statements (e.g. calls to array-param functions)
        if !module_stmts.is_empty() {
            self.write_indent();
            self.write_line("// -------------------------------------------------------");
            self.write_indent();
            self.write_line("// Module-level statements");
            self.write_indent();
            self.write_line("// -------------------------------------------------------");
            self.write_indent();
            self.write_line("always @(*) begin");
            self.indent();
            for stmt in &module_stmts {
                self.gen_verilog_stmt(stmt);
            }
            self.dedent();
            self.write_indent();
            self.write_line("end");
            self.write_line("");
        }

        // W694: SAY WHAT THIS BACKEND DOES NOT LOWER.
        //
        // W692 gated the three simulation sections below on
        // `emit_test_assertions` -- correctly, because emitting `$display` into
        // output whose own help calls it synthesizable was the defect (T167).
        // But it made `gen-verilog` DROP every declared `test`, `invariant` and
        // `bench` in silence, and `suite.rs`'s honesty gate exists to catch
        // exactly that: it went from `614 declared, 3 silent` to
        // `242 declared, 375 silent`, +372 failures in the one check whose
        // stated purpose is this (T181).
        //
        // The gate accepts any artefact that NAMES its omission. That is the
        // honest repair and it is also the true statement: synthesis does not
        // lower a test. The cheap alternative -- adding 375 rows to the
        // expectations ledger -- would be adjusting the instrument until the
        // reading is comfortable, which is the failure T178b/T180 name.
        if !self.emit_test_assertions
            && (!tests.is_empty() || !invariants.is_empty() || !benches.is_empty())
        {
            self.write_indent();
            self.write_line("// -------------------------------------------------------");
            self.write_indent();
            self.write_line("// NOT LOWERED BY THIS BACKEND");
            self.write_indent();
            self.write_line("//");
            self.write_indent();
            self.write_line("// `gen-verilog` emits synthesizable RTL. A test, an invariant and a");
            self.write_indent();
            self.write_line("// bench are simulation constructs -- yosys turns each `$display` into a");
            self.write_indent();
            self.write_line("// `$print` cell and nextpnr has no BEL to place one. They are carried by");
            self.write_indent();
            self.write_line("// `gen-verilog-for-simulation`, which lowers every declaration below.");
            self.write_indent();
            self.write_line("//");
            for t in &tests {
                self.write_indent();
                self.write_line(&format!("// test      {}", t.name));
            }
            for inv in &invariants {
                self.write_indent();
                self.write_line(&format!("// invariant {}", inv.name));
            }
            for b in &benches {
                self.write_indent();
                self.write_line(&format!("// bench     {}", b.name));
            }
            self.write_indent();
            self.write_line("// -------------------------------------------------------");
            self.write_line("");
        }

        // Section: Tests → assertions (SystemVerilog-style)
        //
        // W692: GATED ON `emit_test_assertions`, and it should always have been.
        //
        // `t27c gen-verilog --help` says "Generate SYNTHESIZABLE Verilog", and a
        // sibling command `gen-verilog-for-simulation` already exists to carry the
        // testbench. The switch that separates them -- `emit_test_assertions` --
        // has existed since the two entry points were written, and it wrapped
        // only the `$dumpfile`/`$dumpvars` pair. The test blocks below were
        // emitted UNCONDITIONALLY, which is why the two commands differed by
        // exactly four lines.
        //
        // Measured before this change (T167): 387 of 444 generating specs -- 87.2%
        // -- emitted `$display`, 43,053 calls corpus-wide, 124 in the MVP alone.
        // yosys turns each into a `$print` cell and nextpnr cannot place one:
        //
        //     ERROR: Unable to place cell '...$display$...', no BELs remaining
        //            to implement cell type '$print'
        //
        // So the command whose entire purpose is synthesis produced output that
        // could not be placed, for seven specs in eight. `t27c silicon` worked
        // around it with `delete t:$print`; this removes the need.
        if !tests.is_empty() && self.emit_test_assertions {
            self.write_indent();
            self.write_line("// -------------------------------------------------------");
            self.write_indent();
            self.write_line("// Test assertions (from test blocks)");
            self.write_indent();
            self.write_line("// -------------------------------------------------------");
            self.write_indent();
            self.write_line("`ifndef SIMULATION");
            // W538: enable VCD waveform capture only in simulation mode (when
            // active test assertions are emitted).  Synthesis-mode output must
            // remain unchanged so seals stay stable.
            if self.emit_test_assertions {
                self.write_indent();
                self.write_line("initial begin");
                self.indent();
                self.write_indent();
                self.write_line("$dumpfile(\"dump.vcd\");");
                self.write_indent();
                self.write_line("$dumpvars(0);");
                self.dedent();
                self.write_indent();
                self.write_line("end");
            }
            for t in &tests {
                self.gen_verilog_test(t);
            }
            self.write_indent();
            self.write_line("`endif");
            self.write_line("");
        }

        // Section: Invariants → parameter assertions
        //
        // W692: same gate. An invariant lowers to a procedural assertion, which
        // is a simulation construct exactly as a test is.
        if !invariants.is_empty() && self.emit_test_assertions {
            self.write_indent();
            self.write_line("// -------------------------------------------------------");
            self.write_indent();
            self.write_line("// Invariant checks (compile-time assertions)");
            self.write_indent();
            self.write_line("// -------------------------------------------------------");
            for inv in &invariants {
                self.gen_verilog_invariant(inv);
            }
            self.write_line("");
        }

        // Section: Bench → initial blocks with timing
        //
        // R-VD-1 (wave-29): variable declarations are NOT allowed inside
        // procedural blocks in Verilog-2005 (Yosys/iverilog reject
        // `integer x = 0;` between `initial begin` and `end`). We therefore
        // hoist each bench's cycle counter to module scope using a unique
        // sanitized name, and reset/increment it inside the initial block.
        // W692: same gate. The section header already called these
        // "simulation only" -- and emitted them into the synthesis output anyway.
        if !benches.is_empty() && self.emit_test_assertions {
            self.write_indent();
            self.write_line("// -------------------------------------------------------");
            self.write_indent();
            self.write_line("// Benchmark blocks (simulation only)");
            self.write_indent();
            self.write_line("// -------------------------------------------------------");
            // Module-scope counter declarations (R-VD-1 fix).
            self.write_indent();
            self.write_line("`ifndef SIMULATION");
            for b in &benches {
                let counter = format!(
                    "_bench_{}_cycles",
                    Self::sanitize_identifier(&b.name)
                );
                self.write_indent();
                self.write_line(&format!("integer {} = 0;", counter));
            }
            self.write_indent();
            self.write_line("`endif");
            for b in &benches {
                let counter = format!(
                    "_bench_{}_cycles",
                    Self::sanitize_identifier(&b.name)
                );
                // W458: use standard `ifndef SIMULATION` / `endif` guards instead
                // of the non-standard `// synthesis translate_off` comments.
                // Keep the guards on STANDALONE lines wrapping the full initial
                // block so Yosys does not consume the matching `end` inside the
                // skipped region.
                self.write_indent();
                self.write_line("`ifndef SIMULATION");
                self.write_indent();
                self.write_line(&format!(
                    "initial begin : {}_bench",
                    Self::sanitize_identifier(&b.name)
                ));
                self.indent();
                // W657 (T106): a BENCH block reaches the SAME statement emitter
                // as a test block, and that emitter sets `t27_failed` at every
                // failure site (T74). The test-block emitter declares the flag;
                // this one did not, so every bench carrying an assertion emitted
                //     t27_failed = 1'b1;
                // against a name declared NOWHERE. Measured on a random sample of
                // fifteen specs in the undeclared-identifier class: ELEVEN failed
                // on exactly this -- a regression introduced by T74's own fix.
                self.write_indent();
                self.write_line("reg t27_failed;");
                let block_locals = self.gen_verilog_probe_prelude(b, &b.name);
                self.write_indent();
                self.write_line("t27_failed = 1'b0;");
                self.write_indent();
                self.write_line(&format!("$display(\"[BENCH] {} : starting\");", b.name));
                self.write_indent();
                self.write_line(&format!("{} = 0;", counter));
                self.with_call_array_temps_enabled(|this| {
                    for child in &b.children {
                        this.gen_verilog_test_stmt(child, &b.name, "BENCH");
                        this.write_indent();
                        this.write_line(&format!("{} = {} + 1;", counter, counter));
                    }
                });
                for name in block_locals {
                    self.local_types.remove(&name);
                }
                self.write_indent();
                self.write_line(&format!(
                    // W646: `%%` is not an escape in Rust's `format!` -- only
                    // `{{`/`}}` are -- so `%%0d` reached Verilog verbatim and
                    // `$display` printed the literal text `%0d cycles` followed
                    // by the value in default format. Verified against iverilog:
                    //   "%%0d cycles", n  ->  `%0d cycles         42`
                    //   "%0d cycles",  n  ->  `42 cycles`
                    // Every [BENCH] cycle line in generated Verilog was
                    // malformed. See T57.
                    "$display(\"[BENCH] {} : %0d cycles\", {});",
                    b.name, counter
                ));
                // W657 (T106): the bench verdict was UNCONDITIONAL -- the same
                // defect T74 fixed for test blocks and left here. A bench that
                // printed FAILED then printed PASSED immediately after.
                self.write_indent();
                self.write_line(&format!(
                    "if (t27_failed) $display(\"[BENCH] {} : FAILED\"); else $display(\"[BENCH] {} : PASSED\");",
                    b.name, b.name
                ));
                self.dedent();
                self.write_indent();
                self.write_line("end");
                self.write_indent();
                self.write_line("`endif");
            }
            self.write_line("");
        }

        self.dedent();
        self.write_line("endmodule");
        self.write_line("");
        self.write_line("`default_nettype wire");
    }

    fn gen_verilog_const(&mut self, node: &Node) {
        self.write_indent();

        if node.extra_mutable {
            self.gen_verilog_var(node);
            return;
        }

        // Type alias (e.g. `const GF16 = u16;`, `const TernaryWord = [N]u8;`).
        // Verilog has no typedef and the alias carries no runtime value, so emitting it
        // as `parameter [31:0] GF16 = u16;` is invalid (non-numeric RHS). Emit a comment.
        if node.children.len() == 1 && node.children[0].kind == NodeKind::ExprIdentifier {
            let target = &node.children[0].name;
            // A pure type (alias). NOT a value: array literals like `[32]u16{0x..}` carry
            // a `{...}` initializer and are LUT constants, not type aliases — exclude those.
            let looks_like_type = !target.contains('{')
                && (target.starts_with('[')
                    || target.chars().next().map(|c| c.is_uppercase()).unwrap_or(false)
                    || matches!(target.as_str(),
                        "u8"|"u16"|"u32"|"u64"|"usize"|"i8"|"i16"|"i32"|"i64"|"bool"|"trit"|"f32"|"f64"));
            if looks_like_type {
                self.write_line(&format!("// type alias: {} = {} (no Verilog typedef)", node.name, target));
                return;
            }
        }

        // W533: bare scalar structs are lowered as a single packed
        // parameter/localparam. Arrays of scalar structs keep the W528 path below.
        if Self::parse_array_type(&node.extra_type).is_none()
            && self.is_lowerable_scalar_struct_type(&node.extra_type)
        {
            let base = Self::base_type_name(&node.extra_type);
            let width = self.element_width(&base);
            let range = Self::range_decl(width);
            self.write_indent();
            if node.extra_pub {
                self.write("parameter ");
            } else {
                self.write("localparam ");
            }
            if !range.is_empty() {
                self.write(&format!("{} ", range));
            }
            self.write(&format!("{} = ", Self::verilog_safe_identifier(&node.name)));
            if !node.children.is_empty() {
                self.gen_verilog_expr(&node.children[0]);
            } else {
                self.write(&format!("{}'d0", width));
            }
            self.write_line(";");
            return;
        }

        // W589: module-level multi-dimensional arrays of scalar structs
        // initialized by a function call are lowered as a single packed
        // parameter/localparam, assigned directly from the function's packed
        // return value.
        if let Some((_dims, elem_type)) = Self::parse_array_type(&node.extra_type) {
            if self.struct_decls.contains_key(&elem_type)
                && !node.children.is_empty()
                && node.children[0].kind == NodeKind::ExprCall
            {
                let width = self.packed_width(&node.extra_type);
                let signed = self.packed_signed(&node.extra_type);
                let range = Self::range_decl(width);
                self.write_indent();
                if node.extra_pub {
                    self.write("parameter ");
                } else {
                    self.write("localparam ");
                }
                if signed {
                    self.write("signed ");
                }
                if !range.is_empty() {
                    self.write(&format!("{} ", range));
                }
                self.write(&format!("{} = ", Self::verilog_safe_identifier(&node.name)));
                self.gen_verilog_expr(&node.children[0]);
                self.write_line(";");
                return;
            }
        }

        // W528: multi-dimensional arrays of scalar structs are lowered as a
        // single packed parameter/localparam, matching the function-local
        // packed-vector AoS layout.
        if let Some((_dims, elem_type)) = Self::parse_array_type(&node.extra_type) {
            if self.struct_decls.contains_key(&elem_type) {
                let width = self.packed_width(&node.extra_type);
                let signed = self.packed_signed(&node.extra_type);
                self.write_indent();
                if node.extra_pub {
                    self.write("parameter ");
                } else {
                    self.write("localparam ");
                }
                if signed {
                    self.write("signed ");
                }
                let range = Self::range_decl(width);
                if !range.is_empty() {
                    self.write(&format!("{} ", range));
                }
                self.write(&format!("{} = ", Self::verilog_safe_identifier(&node.name)));
                let init_node = if !node.children.is_empty() {
                    match node.children[0].kind {
                        NodeKind::ExprArrayLiteral => Some(node.children[0].clone()),
                        NodeKind::ExprIdentifier => {
                            self.parse_array_literal_text(&node.children[0].name)
                        }
                        _ => None,
                    }
                } else {
                    None
                };
                if let Some(init) = init_node {
                    self.emit_packed_array_literal_concat(
                        &init, &node.extra_type);
                } else {
                    self.write(&format!("{}'d0", width));
                }
                self.write_line(";");
                return;
            }
        }

        // W545: module-level primitive scalar arrays initialized by a function
        // call are stored as a packed vector so the function's packed return
        // value can be assigned directly.  Static indexing is lowered as
        // bit-slices in try_emit_primitive_array_access.
        if let Some((dims, elem_type)) = Self::primitive_array_info(&node.extra_type
        ) {
            if !node.children.is_empty()
                && node.children[0].kind == NodeKind::ExprCall
            {
                let width = self.packed_width(&node.extra_type);
                let signed = self.packed_signed(&node.extra_type);
                let range = Self::range_decl(width);
                self.write_indent();
                if node.extra_pub {
                    self.write("parameter ");
                } else {
                    self.write("localparam ");
                }
                if signed {
                    self.write("signed ");
                }
                if !range.is_empty() {
                    self.write(&format!("{} ", range));
                }
                self.write(&format!("{} = ", Self::verilog_safe_identifier(&node.name)));
                self.gen_verilog_expr(&node.children[0]);
                self.write_line(";");
                self.module_packed_primitive_arrays.insert(
                    node.name.clone(),
                    (dims.clone(), elem_type.clone()),
                );
                return;
            }
        }

        // Determine if this is an array constant (LUT)
        // W382/W383: array type may come from the type annotation (e.g. "[4]u16")
        // in addition to the legacy extra_size path. Restored from Wave Loop 455.
        let type_array = Self::parse_array_type(&node.extra_type);
        let is_array = !node.extra_size.is_empty() || type_array.is_some();

        if is_array {
            // W383: array-constant lowering. If the type annotation is an array
            // type (e.g. "[4]u16") and the initializer is an array literal, emit a
            // synthesizable Verilog memory initialized in an initial block.
            let safe_name = Self::verilog_safe_identifier(&node.name);
            let has_array_literal = !node.children.is_empty()
                && node.children[0].kind == NodeKind::ExprArrayLiteral;

            if let Some((array_dims, elem_type)) = type_array {
                // master's parse_array_type returns every dimension; a flat Verilog
                // memory needs the total element count, so fold the dims.
                let array_size: usize = array_dims.iter().product();
                let elem_width = Self::type_to_width(&elem_type);
                let elem_signed = Self::type_is_signed(&elem_type);
                let elem_signed_str = if elem_signed { "signed " } else { "" };
                let elem_range = Self::range_decl(elem_width);
                let elem_range_str = if elem_range.is_empty() {
                    String::new()
                } else {
                    format!("{} ", elem_range)
                };
                self.write_line(&format!("// LUT: {} [{}] {}", safe_name, array_size, elem_type)
                );
                // W459: emit optional ROM-style attribute (block/distributed).
                if !node.extra_pragma.is_empty() {
                    self.write_indent();
                    self.write_line(&format!("(* {} *)", node.extra_pragma));
                }
                self.write_indent();
                self.write_line(&format!(
                    "reg {}{} {} [0:{}];",
                    elem_signed_str, elem_range_str, safe_name, array_size - 1
                ));
                if has_array_literal {
                    self.write_indent();
                    self.write_line("initial begin");
                    self.indent();
                    let child = &node.children[0];
                    for (i, elem) in child.children.iter().enumerate() {
                        if i >= array_size {
                            break;
                        }
                        self.write_indent();
                        self.write(&format!("{}[{}] = ", safe_name, i));
                        self.gen_verilog_expr(elem);
                        self.write_line(";");
                    }
                    self.dedent();
                    self.write_indent();
                    self.write_line("end");
                }
            } else if !node.children.is_empty() {
                // Legacy extra_size path: emit as individual localparams for each element
                let child = &node.children[0];
                // R-CA-1 (Wave 28): array-of-struct / array-of-array initializers
                // currently degrade into `/* array ... */` block-comments through
                // gen_verilog_expr, producing `localparam ... = /* comment */;`
                // which is not parseable by Yosys ("syntax error, unexpected ';'").
                // Replace the initializer with literal `0` and a TODO comment so
                // the declaration is syntactically valid Verilog. Downstream
                // emitter passes that reference this symbol still resolve; the
                // semantic gap (true per-element initialization) is tracked as a
                // separate emitter follow-up.
                let is_unsupported_aggregate = matches!(
                    child.kind,
                    NodeKind::ExprArrayLiteral | NodeKind::ExprStructLit
                );
                if child.kind == NodeKind::ExprLiteral && child.value.contains(',') {
                    // Multiple values packed into a single literal — just comment
                    self.write_indent();
                    self.write(&format!("// localparam {} = ", node.name));
                    self.gen_verilog_expr(child);
                    self.write_line(";");
                } else {
                    self.write_indent();
                    if node.extra_pub {
                        self.write("parameter ");
                    } else {
                        self.write("localparam ");
                    }
                    // Determine width from type
                    let width = Self::type_to_width(&node.extra_type);
                    let signed = Self::type_is_signed(&node.extra_type);
                    if signed {
                        self.write("signed ");
                    }
                    let range = Self::range_decl(width);
                    if !range.is_empty() {
                        self.write(&format!("{} ", range));
                    }
                    self.write(&format!(
                        "{} = ",
                        Self::verilog_safe_identifier(&node.name)
                    ));
                    if is_unsupported_aggregate {
                        // R-CA-1 fix: emit a synthesizable scalar zero in place
                        // of the unsupported aggregate initializer.
                        self.write("0");
                        let kind_label = match child.kind {
                            NodeKind::ExprArrayLiteral => "array literal",
                            NodeKind::ExprStructLit => "struct literal",
                            _ => "aggregate literal",
                        };
                        self.write(&format!(
                            " /* TODO: {} initializer not yet lowered to Verilog */",
                            kind_label
                        ));
                    } else {
                        self.gen_verilog_expr(&node.children[0]);
                    }
                    self.write_line(";");
                }
            } else {
                self.write_indent();
                self.write_line(&format!("// localparam {} (array — see spec)", node.name));
            }
        } else {
            // Simple scalar constant
            let is_float = Self::type_is_float(&node.extra_type);
            if node.extra_pub {
                self.write("parameter ");
            } else {
                self.write("localparam ");
            }

            if is_float {
                // W458: real-valued constants must use the `real` keyword, not a
                // bit-vector range, or Yosys emits "real-value assignment
                // to non-real variable" warnings.
                self.write("real ");
            } else {
                // Determine width from type
                let width = Self::type_to_width(&node.extra_type);
                let signed = Self::type_is_signed(&node.extra_type);
                if signed {
                    self.write("signed ");
                }
                let range = Self::range_decl(width);
                if !range.is_empty() {
                    self.write(&format!("{} ", range));
                }
            }

            self.write(&format!(
                "{} = ",
                Self::verilog_safe_identifier(&node.name)
            ));
            if !node.children.is_empty() {
                let child = &node.children[0];
                // R-CA-1 (Wave 28): aggregate literals (ExprArrayLiteral /
                // ExprStructLit) emit as `/* ... */` block-comments, which
                // produces `localparam ... = /* ... */;` — invalid Verilog.
                // Replace with synthesizable `0` and a TODO comment.
                if matches!(
                    child.kind,
                    NodeKind::ExprArrayLiteral | NodeKind::ExprStructLit
                ) {
                    let kind_label = match child.kind {
                        NodeKind::ExprArrayLiteral => "array literal",
                        NodeKind::ExprStructLit => "struct literal",
                        _ => "aggregate literal",
                    };
                    self.write(&format!(
                        "0 /* TODO: {} initializer not yet lowered to Verilog */",
                        kind_label
                    ));
                } else {
                    self.gen_verilog_expr(child);
                }
            } else {
                self.write("0");
            }
            self.write_line(";");
        }
    }

    fn gen_verilog_var(&mut self, node: &Node) {
        // W533: bare scalar structs are lowered as a single packed-vector register
        // with procedural whole-struct init.
        if Self::parse_array_type(&node.extra_type).is_none()
            && self.is_lowerable_scalar_struct_type(&node.extra_type)
        {
            let base = Self::base_type_name(&node.extra_type);
            let width = self.element_width(&base);
            self.write_indent();
            self.write_line(&format!("reg [{}:0] {};", width.saturating_sub(1), node.name),
            );
            if !node.children.is_empty() {
                self.write_indent();
                self.write_line("initial begin");
                self.indent();
                self.write_indent();
                self.write(&format!("{} = ", Self::verilog_safe_identifier(&node.name)));
                self.gen_verilog_expr(&node.children[0]);
                self.write_line(";");
                self.dedent();
                self.write_indent();
                self.write_line("end");
            }
            self.write_line("");
            return;
        }

        // W589: module-level multi-dimensional arrays of scalar structs
        // initialized by a function call are lowered as a single packed-vector
        // register, assigned wholesale from the function's packed return value.
        if let Some((_dims, elem_type)) = Self::parse_array_type(&node.extra_type) {
            if self.struct_decls.contains_key(&elem_type)
                && !node.children.is_empty()
                && node.children[0].kind == NodeKind::ExprCall
            {
                let width = self.packed_width(&node.extra_type);
                let signed = self.packed_signed(&node.extra_type);
                let signed_str = if signed { "signed " } else { "" };
                let range = Self::range_decl(width);
                self.write_indent();
                self.write(&format!("reg {}{}", signed_str, range));
                if !range.is_empty() {
                    self.write(" ");
                }
                self.write_line(&format!("{};", node.name),
                );
                self.write_indent();
                self.write_line("initial begin");
                self.indent();
                self.write_indent();
                self.write(&format!("{} = ", Self::verilog_safe_identifier(&node.name)));
                self.gen_verilog_expr(&node.children[0]);
                self.write_line(";");
                self.dedent();
                self.write_indent();
                self.write_line("end");
                self.write_line("");
                return;
            }
        }

        // W528: multi-dimensional arrays of scalar structs are lowered as a
        // single packed-vector register with procedural per-element init.
        if let Some((_dims, elem_type)) = Self::parse_array_type(&node.extra_type) {
            if self.struct_decls.contains_key(&elem_type) {
                let width = self.packed_width(&node.extra_type);
                self.write_indent();
                self.write_line(
                    &format!("reg [{}:0] {};", width.saturating_sub(1), node.name),
                );
                if !node.children.is_empty() {
                    self.write_indent();
                    self.write_line("initial begin");
                    self.indent();
                    let init_node = match node.children[0].kind {
                        NodeKind::ExprArrayLiteral => node.children[0].clone(),
                        NodeKind::ExprIdentifier => {
                            self.parse_array_literal_text(&node.children[0].name)
                                .unwrap_or_else(|| node.children[0].clone())
                        }
                        _ => node.children[0].clone(),
                    };
                    self.emit_packed_struct_array_init(
                        &Self::verilog_safe_identifier(&node.name),
                        &node.extra_type,
                        &init_node,
                    );
                    self.dedent();
                    self.write_indent();
                    self.write_line("end");
                }
                self.write_line("");
                return;
            }
        }

        // W545: module-level primitive scalar arrays initialized by a function
        // call are stored as a packed vector so the function's packed return
        // value can be assigned directly in an initial block.
        if let Some((dims, elem_type)) = Self::primitive_array_info(
            &node.extra_type
        ) {
            if !node.children.is_empty()
                && node.children[0].kind == NodeKind::ExprCall
            {
                let width = self.packed_width(&node.extra_type);
                let signed = self.packed_signed(&node.extra_type);
                let signed_str = if signed { "signed " } else { "" };
                let range = Self::range_decl(width);
                self.write_indent();
                self.write(&format!("reg {}{}", signed_str, range));
                if !range.is_empty() {
                    self.write(" ");
                }
                self.write_line(&format!("{};", node.name));
                self.write_indent();
                self.write_line("initial begin");
                self.indent();
                self.write_indent();
                self.write(&format!("{} = ", Self::verilog_safe_identifier(&node.name)));
                self.gen_verilog_expr(&node.children[0]);
                self.write_line(";");
                self.dedent();
                self.write_indent();
                self.write_line("end");
                self.write_line("");
                self.module_packed_primitive_arrays.insert(
                    node.name.clone(),
                    (dims.clone(), elem_type.clone()),
                );
                return;
            }
        }

        // W531: module-level arrays of primitive scalars are lowered as
        // unpacked Verilog arrays so that signed widths and variable indices
        // are preserved.
        if Self::is_primitive_array_type(&node.extra_type) {
            let (dims, elem_type) = Self::primitive_array_info(&node.extra_type
            ).unwrap_or((Vec::new(), "u32".to_string()));
            let elem_w = Self::type_to_width(&elem_type).max(1) as usize;
            let signed = Self::type_is_signed(
                &Self::parse_array_type(&node.extra_type)
                    .map(|(_, et)| et)
                    .unwrap_or_default(),
            );
            let signed_str = if signed { "signed " } else { "" };
            let dims_str = dims
                .iter()
                .map(|d| format!("[0:{}]", d - 1))
                .collect::<String>();
            self.write_indent();
            // W457: a `pragma ram_style/rom_style` attached to this array `var`
            // is emitted as a Verilog attribute on the memory declaration.
            let pragma = if !node.extra_pragma.is_empty() {
                format!("(* {} *) ", node.extra_pragma)
            } else {
                String::new()
            };
            self.write_line(
                &format!(
                    "{}reg {}{}[{}:0] {}{};",
                    pragma, signed_str, "", elem_w - 1, node.name, dims_str
                ),
            );
            if !node.children.is_empty() {
                self.write_indent();
                self.write_line("initial begin");
                self.indent();
                let init_node = match node.children[0].kind {
                    NodeKind::ExprArrayLiteral => node.children[0].clone(),
                    NodeKind::ExprIdentifier => {
                        self.parse_array_literal_text(&node.children[0].name
                        ).unwrap_or_else(|| node.children[0].clone())
                    }
                    _ => node.children[0].clone(),
                };
                self.emit_unpacked_primitive_array_init(
                    &node.name,
                    &node.extra_type,
                    &init_node,
                );
                self.dedent();
                self.write_indent();
                self.write_line("end");
            }
            self.write_line("");
            return;
        }

        let width = Self::type_to_width(&node.extra_type);
        let signed = Self::type_is_signed(&node.extra_type);
        let signed_str = if signed { "signed " } else { "" };
        let range = Self::range_decl(width);
        let range_str = if range.is_empty() {
            String::new()
        } else {
            format!("{} ", range)
        };
        // W382: array type may come from the type annotation (e.g. "[4]u16") in
        // addition to the legacy extra_size path used by array literals.
        let type_array = Self::parse_array_type(&node.extra_type);
        // W382/W383: array type may come from the type annotation (e.g. "[4]u16")
        // in addition to the legacy extra_size path. Restored from Wave Loop 455.
        let type_array = Self::parse_array_type(&node.extra_type);
        let is_array = !node.extra_size.is_empty() || type_array.is_some();
        let safe_name = Self::verilog_safe_identifier(&node.name);

        if let Some((array_dims, elem_type)) = type_array {
            // master's parse_array_type returns every dimension; a flat Verilog
            // memory needs the total element count, so fold the dims.
            let array_size: usize = array_dims.iter().product();
            // W382: emit a true synthesizable Verilog memory so that indexing
            // expressions like mem[i] resolve to memory access, not bit-select.
            let elem_width = Self::type_to_width(&elem_type);
            let elem_signed = Self::type_is_signed(&elem_type);
            let elem_signed_str = if elem_signed { "signed " } else { "" };
            let elem_range = Self::range_decl(elem_width);
            let elem_range_str = if elem_range.is_empty() {
                String::new()
            } else {
                format!("{} ", elem_range)
            };
            if !node.extra_pragma.is_empty() {
                self.write_line(&format!("(* {} *)", node.extra_pragma));
            }
            self.write_line(&format!(
                "reg {}{} {} [0:{}];",
                elem_signed_str, elem_range_str, safe_name, array_size - 1
            ));
            if !node.children.is_empty() {
                self.write_indent();
                self.write_line("initial begin");
                self.indent();
                let child = &node.children[0];
                if child.kind == NodeKind::ExprArrayLiteral {
                    for (i, elem) in child.children.iter().enumerate() {
                        if i < array_size {
                            self.write_indent();
                            self.write(&format!("{}[{}] = ", safe_name, i));
                            self.gen_verilog_expr(elem);
                            self.write_line(";");
                        }
                    }
                } else {
                    self.write_indent();
                    self.write("// initializer: ");
                    self.gen_verilog_expr(child);
                    self.write_line("");
                }
                self.dedent();
                self.write_indent();
                self.write_line("end");
            }
        } else if is_array {
            self.write_line(&format!("// var: {} [{}]", node.name, node.extra_size));
            let array_size: usize = node.extra_size.parse().unwrap_or(1);
            for i in 0..array_size {
                self.write_indent();
                self.write_line(&format!(
                    "reg {}{}{}_{};",
                    signed_str, range_str, safe_name, i
                ));
            }
            if !node.children.is_empty() {
                self.write_indent();
                self.write_line("initial begin");
                self.indent();
                let child = &node.children[0];
                if child.kind == NodeKind::ExprArrayLiteral {
                    for (i, elem) in child.children.iter().enumerate() {
                        if i < array_size {
                            self.write_indent();
                            self.write(&format!("{}_{} = ", safe_name, i));
                            self.gen_verilog_expr(elem);
                            self.write_line(";");
                        }
                    }
                } else {
                    self.write_indent();
                    self.write(&format!("// initializer: "));
                    self.gen_verilog_expr(child);
                    self.write_line("");
                }
                self.dedent();
                self.write_indent();
                self.write_line("end");
            }
        } else {
            // An exposed output-reg var is already declared in the ANSI port
            // header; emit only its power-on initializer here.
            if self.exposed_output_vars.contains(&node.name) {
                self.write_line(&format!("// {} exposed as output reg port", node.name));
            } else {
                self.write(&format!(
                    "reg {}{}{};",
                    signed_str, range_str, safe_name
                ));
                self.write_line("");
            }
            if !node.children.is_empty() {
                self.write_indent();
                self.write_line("initial begin");
                self.indent();
                self.write_indent();
                self.write(&format!("{} = ", safe_name));
                self.gen_verilog_expr(&node.children[0]);
                self.write_line(";");
                self.dedent();
                self.write_indent();
                self.write_line("end");
            }
        }
        self.write_line("");
    }

    /// The enums this module imports AND actually names, as `EnumDecl` nodes
    /// so they go through the same emitter as a same-spec enum.
    ///
    /// Two filters, both deliberate:
    ///
    /// * **Referenced only.** An unused `localparam` is harmless to a
    ///   simulator, but emitting one per imported enum would rewrite the
    ///   generated Verilog of every spec that merely imports a module with an
    ///   enum in it. Only `Enum.variant` references pull anything in.
    /// * **Never shadow.** If the module already declares that name, or
    ///   already declares the `Enum_variant` identifier by another route, the
    ///   import is dropped. A redeclaration is a compile error, so this pass
    ///   must only ever ADD a declaration that nothing else provides.
    fn imported_enum_nodes(&self, ast: &Node, local_enums: &[&Node]) -> Vec<Node> {
        if self.imported_enums.is_empty() {
            return Vec::new();
        }
        let mut referenced: std::collections::HashSet<String> =
            std::collections::HashSet::new();
        Self::collect_field_access_bases(ast, &mut referenced);
        if referenced.is_empty() {
            return Vec::new();
        }

        let mut taken: std::collections::HashSet<String> = std::collections::HashSet::new();
        for decl in &ast.children {
            if !decl.name.is_empty() {
                taken.insert(decl.name.clone());
            }
        }
        for e in local_enums {
            for v in &e.children {
                taken.insert(format!("{}_{}", e.name, v.name));
            }
        }

        let mut out: Vec<Node> = Vec::new();
        for (name, variants) in &self.imported_enums {
            if !referenced.contains(name) || taken.contains(name) {
                continue;
            }
            if variants
                .iter()
                .any(|(variant, _)| taken.contains(&format!("{}_{}", name, variant)))
            {
                continue;
            }
            let mut node = Node::new(NodeKind::EnumDecl);
            node.name = name.clone();
            for (variant, value) in variants {
                let mut child = Node::new(NodeKind::EnumVariant);
                child.name = variant.clone();
                child.value = value.clone();
                taken.insert(format!("{}_{}", name, variant));
                node.children.push(child);
            }
            out.push(node);
        }
        out
    }

    /// The `Enum` half of every `Enum.variant`-shaped reference in the tree.
    ///
    /// This is the same shape `gen_verilog_expr` lowers to `Enum_variant`, so
    /// asking it what the body names is asking exactly the right question.
    fn collect_field_access_bases(node: &Node, out: &mut std::collections::HashSet<String>) {
        if node.kind == NodeKind::ExprFieldAccess {
            if let Some(base) = node.children.first() {
                if base.kind == NodeKind::ExprIdentifier {
                    out.insert(base.name.clone());
                }
            }
        }
        for child in &node.children {
            Self::collect_field_access_bases(child, out);
        }
    }

    fn gen_verilog_enum(&mut self, node: &Node) {
        self.write_indent();
        self.write_line(&format!("// enum {}", node.name));
        for (i, variant) in node.children.iter().enumerate() {
            self.write_indent();
            if !variant.value.is_empty() {
                self.write_line(&format!(
                    "localparam {}_{} = {};",
                    node.name, variant.name, variant.value
                ));
            } else {
                self.write_line(&format!(
                    "localparam {}_{} = {};",
                    node.name, variant.name, i
                ));
            }
        }
    }

    fn gen_verilog_struct(&mut self, node: &Node, reg_prefix: &str) {
        self.write_indent();
        self.write_line(&format!("// struct {}", node.name));
        if Self::is_lowerable_scalar_struct(&node.name, &self.struct_decls) {
            // W533: lowerable scalar structs are emitted as packed vectors at their
            // use sites (module-level const/var or function-local reg). No per-field
            // registers are needed.
            self.write_indent();
            self.write_line(&format!(
                "// struct {} lowered as packed vector ({} bits)",
                node.name,
                self.element_width(&node.name)
            ));
            return;
        }
        self.write_indent();
        self.write_line(&format!(
                "// UNSUPPORTED_ICARUS: struct {} contains non-lowerable fields",
                node.name
            ));
        for field in &node.children {
            self.write_indent();
            let width = Self::type_to_width(&field.extra_type);
            let signed = Self::type_is_signed(&field.extra_type);

            let signed_str = if signed { "signed " } else { "" };
            let range = Self::range_decl(width);
            let range_str = if range.is_empty() {
                String::new()
            } else {
                format!("{} ", range)
            };

            // Check if field type is an array (has extra_size)
            let array_suffix = if !field.extra_size.is_empty() {
                // For array fields, we can't easily determine the size at this point
                // Use a comment indicating the array dimension
                format!(" /* [{}] */", field.extra_size)
            } else {
                String::new()
            };

            self.write_line(&format!(
                "reg {}{}{}_{}; // {}.{}{}",
                signed_str,
                range_str,
                reg_prefix,
                field.name,
                node.name,
                field.name,
                array_suffix,
            ));
        }
    }

    fn gen_verilog_fn(&mut self, node: &Node) {
        self.current_fn_name = node.name.clone();
        // W458: keyed by the original (unsanitized) fn name -- the
        // array_param_bindings map is keyed by it. Dropped by batch merge #1783,
        // which left the binding lookup consulting an empty key.
        self.current_fn_name_original = node.name.clone();
        self.current_fn_return_type = node.extra_return_type.clone();
        self.param_widths.clear();
        self.local_types.clear();
        self.param_types.clear();
        self.local_packed_primitive_arrays.clear();
        // W657 (T103): register this function's PARAMETER types.
        //
        // `param_types` is read at nine sites to decide whether a `base.field`
        // access can take the PACKED path -- `base[off +: w]` against the
        // `input [W-1:0] base` that is actually declared. It was populated in
        // `gen_verilog_clocked_fn` and NOT here, so every ordinary function
        // cleared the map and left it empty. Every struct-typed parameter then
        // fell through to the flatten fallback and emitted `base_field`, a name
        // declared NOWHERE:
        //
        //     input [31:0] debouncer;            <- declared PACKED
        //     ...
        //     result_last_exec_ms = ...;         <- emitted FLATTENED
        //
        // iverilog: "Could not find variable `result_last_exec_ms'". Measured as
        // 489 of 618 non-compiling specs -- 79.1%, the largest single cause in
        // the corpus (T102).
        //
        // This is T75's and T78's shape a third time: two branches of one
        // feature, one populated and one not, with nothing in the type system
        // constraining the divergence to the concern the branch is named for.
        for (pname, ptype) in &node.params {
            self.param_types.insert(pname.clone(), ptype.clone());
        }
        // W527: cache local variable types for array-of-struct resolution.
        for stmt in &node.children {
            if stmt.kind == NodeKind::StmtLocal && !stmt.name.is_empty() {
                // #2325: an UNANNOTATED local (`var result = make_config(...)`)
                // recorded an empty type, so `result.port_count` fell past the
                // part-select branch and flattened to the unbound
                // `result_port_count` (hir.v, memory.v, timing.v). Recover the
                // type from the callee when the initializer is a call, exactly
                // as the test-block binding path does since #2413. Only walks
                // top-level statements, matching the existing registration.
                let ty = if stmt.extra_type.is_empty() {
                    match stmt.children.first() {
                        // `var x = make_thing(...)` -- the callee's return type.
                        Some(c) if c.kind == NodeKind::ExprCall => self
                            .fn_return_types
                            .get(&c.name)
                            .cloned()
                            .unwrap_or_default(),
                        // `var result = mem;` -- copy of a param or an earlier
                        // local. This is the shape that actually dominates the
                        // corpus (hir.t27's mem_add_port and its siblings): the
                        // call-only version measured ZERO change over the fpga
                        // set before this arm was added.
                        Some(c) if c.kind == NodeKind::ExprIdentifier => self
                            .param_types
                            .get(&c.name)
                            .or_else(|| self.local_types.get(&c.name))
                            .cloned()
                            .unwrap_or_default(),
                        _ => String::new(),
                    }
                } else {
                    stmt.extra_type.clone()
                };
                self.local_types.insert(stmt.name.clone(), ty);
            }
        }
        for (pname, ptype) in &node.params {
            // W528: packed width for array-of-struct parameters; primitive width
            // for scalar parameters.
            self.param_widths
                .insert(pname.clone(), self.packed_width(ptype) as usize);
            self.param_types
                .insert(pname.clone(), ptype.clone());
        }
        self.write_line("");
        self.write_indent();
        self.write_line(&format!("// function: {}", node.name));

        // W458: if this function has array parameter(s) and the binding could
        // not be resolved from the module-level call site, emit an error
        // comment and skip the function entirely.
        let array_param_error = self.array_param_errors.get(&node.name).cloned();
        if let Some(err) = array_param_error {
            self.write_indent();
            self.write_line(&format!("// ERROR: {}", err));
            self.write_indent();
            self.write_line("// (skipping function due to unsupported array parameter binding)");
            self.current_fn_name.clear();
            self.current_fn_name_original.clear();
            self.current_fn_return_type.clear();
            self.param_widths.clear();
            self.local_arrays.clear();
            return;
        }

        // Emit as a Verilog function declaration
        // W380: tuple return types are packed; non-tuple types keep scalar width.
        let ret_width = if !node.extra_return_type.is_empty() {
            self.packed_width(&node.extra_return_type)
        } else {
            32
        };
        let ret_signed = if !node.extra_return_type.is_empty() {
            self.packed_signed(&node.extra_return_type)
        } else {
            false
        };

        // W655 (T95): a float return becomes Verilog `real`, not an integer
        // vector. See `type_is_float`.
        let ret_is_float = Self::type_is_float(&node.extra_return_type);
        let signed_str = if ret_is_float {
            ""
        } else if ret_signed {
            "signed "
        } else {
            ""
        };
        let range_str = if ret_is_float {
            "real ".to_string()
        } else {
            let range = Self::range_decl(ret_width);
            if range.is_empty() {
                String::new()
            } else {
                format!("{} ", range)
            }
        };

        let fn_name = Self::verilog_safe_identifier(&node.name);

        // void functions → task; others → function
        //
        // W705: THERE ARE TWO SPELLINGS OF VOID AND THIS TESTED ONE.
        //
        // `fn f() -> void` sets the field to "void"; `fn f()` with no arrow
        // leaves it EMPTY, and the display path a few lines below prints that
        // empty string as "auto". So a parameterless, returnless `fn tick()`
        // was emitted as
        //
        //     function [31:0] tick;   // -> auto
        //
        // and called in statement position as `tick(1'b0);` -- a task enable
        // naming a function, with an argument invented for a function that
        // takes none.
        //
        // iverilog ACCEPTS this, with a warning:
        //     User function 'tick' is being called as a task.
        // yosys does not:
        //     ERROR: Can't resolve task name `\tick'.
        //
        // That divergence is why it survived: the corpus metric compiles with
        // iverilog, so a construct only yosys rejects is invisible to it. 28
        // specs are in this shape, every one a testbench declaring `fn tick()`.
        if node.extra_return_type == "void" || node.extra_return_type.is_empty() {
            self.write_indent();
            self.write_line(&format!("task {};", fn_name));
        } else {
            self.write_indent();
            self.write_line(&format!(
                "function {}{}{}; // -> {}",
                signed_str,
                range_str,
                fn_name,
                if node.extra_return_type.is_empty() {
                    "auto"
                } else {
                    &node.extra_return_type
                },
            ));
        }

        self.indent();

        // Emit parameters as input declarations. W458: array parameters that
        // are bound to a module-level array are not emitted as scalar inputs;
        // the function body references the module array by name directly.
        for (pname, ptype) in &node.params {
            if Self::parse_array_type(ptype).is_some() {
                if self
                    .array_param_bindings
                    .get(&node.name)
                    .map_or(false, |b| b.contains_key(pname))
                {
                    continue;
                }
            }
            self.write_indent();
            // W655 (T95): a float parameter becomes `real` too, or the
            // argument is narrowed at the boundary and the sign is lost.
            let p_is_float = Self::type_is_float(ptype);
            let pw = self.packed_width(ptype);
            let ps = self.packed_signed(ptype);
            let ps_str = if p_is_float || !ps { "" } else { "signed " };
            let pr_str = if p_is_float {
                "real ".to_string()
            } else {
                let pr = Self::range_decl(pw);
                if pr.is_empty() {
                    String::new()
                } else {
                    format!("{} ", pr)
                }
            };
            let safe_pname = Self::verilog_safe_identifier(pname);
            self.write_line(&format!("input {}{}{};", ps_str, pr_str, safe_pname));
        }
        // Verilog requires a function to have at least one input port. A
        // zero-argument function reads module state and returns a value; give it
        // an unused dummy input so iverilog/Yosys accept the declaration.
        if node.params.is_empty() && node.extra_return_type != "void" {
            self.write_indent();
            self.write_line("input _unused;");
        }

        // Emit body
        if node.children.is_empty() {
            self.write_indent();
            self.write_line("// TODO: implement");
        } else {
            // Name the body block: Verilog-2001 forbids local declarations in an
            // UNNAMED begin/end (a function that declares a local `reg` inside its
            // body would need SystemVerilog otherwise).
            self.write_indent();
            self.write_line(&format!("begin : {}_body", node.name));
            self.indent();
            // #1741: Verilog forbids a declaration after a procedural statement
            // (iverilog rejects it, in the body block AND in nested loop/if
            // blocks), so hoist every local's `reg` declaration -- at any depth
            // -- to the top of the function body block, then emit the body with
            // each StmtLocal reduced to its assignment (Init phase). A reg
            // declared inside a loop is fine to declare once and reassign each
            // iteration.
            let mut decls: Vec<&Node> = Vec::new();
            let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();
            Self::collect_fn_local_decls(&node.children, &mut decls, &mut seen);
            for d in decls {
                self.emit_local(d, LocalEmitPhase::Decl);
            }
            // W648: loop variables, hoisted the same way and for the same
            // reason. See T60.
            let mut loop_vars: Vec<String> = Vec::new();
            Self::collect_fn_loop_vars(&node.children, &mut loop_vars);
            for v in &loop_vars {
                self.write_indent();
                self.write_line(&format!("integer {};", v));
            }
            // Early-return guard (t27#1948): a `return` sets it and every
            // remaining statement region is wrapped in `if (!__t27_ret)`.
            self.write_indent();
            self.write_line("reg __t27_ret;");
            self.write_indent();
            self.write_line("__t27_ret = 1'b0;");
            self.hoist_fn_locals = true;
            self.gen_verilog_fn_body(&node.children);
            self.hoist_fn_locals = false;
            self.dedent();
            self.write_indent();
            self.write_line("end");
        }

        self.dedent();

        // W705: the SAME predicate as the header, or the two disagree and the
        // output is `task tick; ... endfunction`. They were written apart and
        // tested apart; one accepted an empty return type and the other did not.
        if node.extra_return_type == "void" || node.extra_return_type.is_empty() {
            self.write_indent();
            self.write_line("endtask");
        } else {
            self.write_indent();
            self.write_line("endfunction");
        }
        self.current_fn_name.clear();
        self.current_fn_name_original.clear();
        self.current_fn_return_type.clear();
        self.param_widths.clear();
        self.local_arrays.clear();
    }

    /// #1764: emit a clocked `always @(posedge clk)` process for a `fn on_clock`.
    /// Module-level `var`s are the registered state: on `!rst_n` they take their
    /// declared init value, and while `en` is asserted the function body runs
    /// with nonblocking (`<=`) assignments. This is the opt-in sequential path;
    /// specs without an `on_clock` fn never reach it, so their output is
    /// byte-identical to before.
    fn gen_verilog_clocked_fn(&mut self, node: &Node, consts: &[&Node]) {
        self.current_fn_name = node.name.clone();
        self.local_types.clear();
        self.param_types.clear();
        self.param_widths.clear();
        // `on_clock` params are streaming input data ports; register their widths
        // and types so body references (casts, width-aware ops) resolve.
        for (pname, ptype) in &node.params {
            self.param_widths
                .insert(pname.clone(), self.packed_width(ptype) as usize);
            self.param_types.insert(pname.clone(), ptype.clone());
        }
        // Mirror gen_verilog_fn: cache any body-local variable types.
        for stmt in &node.children {
            if stmt.kind == NodeKind::StmtLocal && !stmt.name.is_empty() {
                self.local_types
                    .insert(stmt.name.clone(), stmt.extra_type.clone());
            }
        }
        self.write_line("");
        self.write_indent();
        self.write_line("// -------------------------------------------------------");
        self.write_indent();
        self.write_line("// Sequential logic (from clocked function `on_clock`)");
        self.write_indent();
        self.write_line("// -------------------------------------------------------");
        self.write_indent();
        self.write_line("always @(posedge clk or negedge rst_n) begin");
        self.indent();
        self.write_indent();
        self.write_line("if (!rst_n) begin");
        self.indent();
        // Reset each scalar module-level `var` to its declared init value.
        for c in consts {
            let is_scalar = Self::parse_array_type(&c.extra_type).is_none()
                && !Self::is_primitive_array_type(&c.extra_type)
                && !self.struct_decls.contains_key(&c.extra_type);
            if c.extra_mutable && is_scalar && !c.children.is_empty() {
                self.write_indent();
                self.write(&format!("{} <= ", c.name));
                self.gen_verilog_expr(&c.children[0]);
                self.write_line(";");
            }
        }
        self.dedent();
        self.write_indent();
        self.write_line("end else if (en) begin");
        self.indent();
        self.clocked_nonblocking = true;
        self.gen_verilog_fn_body(&node.children);
        self.clocked_nonblocking = false;
        self.dedent();
        self.write_indent();
        self.write_line("end");
        self.dedent();
        self.write_indent();
        self.write_line("end");
        self.current_fn_name.clear();
        self.local_types.clear();
        self.param_types.clear();
        self.param_widths.clear();
    }

    /// Emit a Verilog function body statement list, rewriting the
    /// `if (c) { return A }  <rest>` shape (guarded early return with no
    /// else) into `if (c) begin ... end else begin <rest> end`. Because a
    /// Verilog `return` is lowered to a blocking assignment to the function
    /// name, a bare fall-through would let the trailing statements clobber
    /// the guarded assignment (last write wins). Wrapping the remainder in an
    /// else preserves the early-return semantics.
    /// #1741: recursively collect every `StmtLocal` in a function body (at any
    /// nesting depth) so its `reg` declaration can be hoisted to the top of the
    /// body block. Deduped by binding name (tuple-pattern locals by their
    /// comma-joined field list) so a name declared once is emitted once.
    /// W648: every `for` a function body emits needs its loop variable
    /// declared, and neither `gen_verilog_for_stmt` nor
    /// `gen_verilog_for_range_stmt` did it -- the comment at the first site
    /// even reads "Emit: integer iter_var; for (...)", so the intent was
    /// recorded and only the `for` was written.
    ///
    /// It stayed invisible because a constant-bound loop is UNROLLED and needs
    /// no variable; only a loop over a parameter emits a real `for`. Same
    /// conjunctive shape as T53: the obligation was met on the path that is
    /// usually taken and missed on the one that is not. See T60.
    ///
    /// Verilog forbids a declaration after a procedural statement, so these
    /// hoist to the top of the function body alongside the local `reg`s.
    fn collect_fn_loop_vars(stmts: &[Node], out: &mut Vec<String>) {
        for s in stmts {
            match s.kind {
                NodeKind::StmtFor => {
                    let v = if !s.params.is_empty() {
                        s.params[0].0.clone()
                    } else {
                        "__i".to_string()
                    };
                    let v = Self::verilog_safe_identifier(&v);
                    if !out.contains(&v) {
                        out.push(v);
                    }
                }
                NodeKind::StmtForRange => {
                    let v = Self::verilog_safe_identifier(&s.name);
                    if !out.contains(&v) {
                        out.push(v);
                    }
                }
                _ => {}
            }
            Self::collect_fn_loop_vars(&s.children, out);
        }
    }

    fn collect_fn_local_decls<'a>(
        stmts: &'a [Node],
        out: &mut Vec<&'a Node>,
        seen: &mut std::collections::HashSet<String>,
    ) {
        for s in stmts {
            if s.kind == NodeKind::StmtLocal {
                let key = if s.name.is_empty() {
                    s.extra_field.clone()
                } else {
                    s.name.clone()
                };
                if !key.is_empty() && seen.insert(key) {
                    out.push(s);
                }
            }
            Self::collect_fn_local_decls(&s.children, out, seen);
        }
    }

    fn gen_verilog_fn_body(&mut self, stmts: &[Node]) {
        for (idx, stmt) in stmts.iter().enumerate() {
            let is_guarded_return = stmt.kind == NodeKind::StmtIf
                && stmt.children.len() == 2 // [cond, then]; no else block
                && stmt.children[1]
                    .children
                    .last()
                    .map_or(false, |s| s.kind == NodeKind::ExprReturn);
            if is_guarded_return && idx + 1 < stmts.len() {
                // Emit: if (cond) begin <then> end else begin <rest> end
                self.write_indent();
                self.write("if (");
                self.gen_verilog_expr(&stmt.children[0]);
                self.write_line(") begin");
                self.indent();
                // Recurse so a `return` NESTED inside this then-block (e.g.
                // `if(inner){return 0} return X`) is also lowered as an early
                // return (if/else), not two sequential assigns where the last
                // wins -- the latter silently discards the guarded value.
                self.gen_verilog_fn_body(&stmt.children[1].children);
                self.dedent();
                self.write_indent();
                self.write_line("end else begin");
                self.indent();
                self.gen_verilog_fn_body(&stmts[idx + 1..]);
                self.dedent();
                self.write_indent();
                self.write_line("end");
                return;
            }
            // A final bare expression is a Rust-style tail expression --
            // the function's implicit return value. Verilog has no tail
            // expressions, so it emitted `expr;` (a bare statement iverilog
            // reads as a task-enable). Lower the LAST StmtExpr to an implicit
            // return assignment `<fn> = <expr>;` (t27#1948).
            let is_tail_expr = idx + 1 == stmts.len()
                && stmt.kind == NodeKind::StmtExpr
                && !stmt.children.is_empty()
                && !self.current_fn_name.is_empty()
                && self.current_fn_return_type != "void";
            if is_tail_expr {
                self.write_indent();
                let asn = if self.clocked_nonblocking { " <= " } else { " = " };
                // A Verilog function returns by assigning to its own name; if that name is
                // a keyword the lvalue must be escaped exactly like the declaration.
                self.write(&Self::verilog_safe_identifier(&self.current_fn_name.clone()));
                self.write(asn);
                self.gen_verilog_expr(&stmt.children[0]);
                self.write_line(";");
                continue;
            }
            // #1741: top-level locals had their `reg` declaration hoisted, so
            // emit only the assignment here.
            if self.hoist_fn_locals && stmt.kind == NodeKind::StmtLocal {
                self.emit_local(stmt, LocalEmitPhase::Init);
            } else {
                self.gen_verilog_stmt(stmt);
            }
            // General early-return barrier: if this statement's subtree can
            // return (if/else-if chains, loops with returns -- shapes the
            // pretty if/else rewrite above does not cover), the remaining
            // statements must not run after a taken return.
            if idx + 1 < stmts.len()
                && !self.clocked_nonblocking
                && !self.current_fn_name.is_empty()
                && Self::subtree_has_return(stmt)
            {
                self.write_indent();
                self.write_line("if (!__t27_ret) begin");
                self.indent();
                self.gen_verilog_fn_body(&stmts[idx + 1..]);
                self.dedent();
                self.write_indent();
                self.write_line("end");
                return;
            }
        }
    }

    fn subtree_has_return(node: &Node) -> bool {
        if node.kind == NodeKind::ExprReturn {
            return true;
        }
        node.children.iter().any(Self::subtree_has_return)
    }

    // W551: hoist probe registers and block-local variable declarations for
    // any simulation block (test or deterministic bench) that contains
    // assert_eq statements. Returns the names of block-local variables whose
    // types were cached so the caller can clean them up after the block.
    fn gen_verilog_probe_prelude(&mut self, node: &Node, block_name: &str) -> Vec<String> {
        // W538: probe indices are per-block.
        self.probe_counter = 0;
        // W533: cache block-local variable types for packed scalar-struct
        // field access (e.g. `var tmp : Pt = make(...); assert_eq(tmp.x, 1);`).
        let mut block_locals: Vec<String> = Vec::new();
        for child in &node.children {
            if child.kind == NodeKind::StmtLocal
                && !child.name.is_empty()
                && !child.extra_type.is_empty()
            {
                self.local_types
                    .insert(child.name.clone(), child.extra_type.clone());
                block_locals.push(child.name.clone());
            }
        }
        // W533: hoist block-local variable declarations to the top of the
        // initial block. Verilog requires all `reg` declarations before any
        // procedural statements.
        // W538: also hoist scalar assert_eq probe registers for VCD capture.
        // W539: probe width/signedness is inferred from the actual expression.
        self.probe_specs.clear();
        // W553: each test/bench block gets its own set of call-return packed-array
        // temporaries. They are declared here and assigned on first use.
        self.call_array_tmp_names.clear();
        self.call_array_tmp_info.clear();
        self.call_array_tmp_materialized.clear();
        // W653 (T75): this hoist WAS gated on `emit_test_assertions`, which
        // `VerilogCodegen::new()` sets to **false** -- and `main.rs:4858`, the
        // CLI `gen-verilog` path, calls `new()`. So every CLI-generated module
        // emitted the assertion bodies (those come from an ungated path) while
        // emitting NO declarations for the names they read. `given v = f()`
        // produced `v = f();` with `v` undeclared, and iverilog answered
        // "Could not find variable `v'" -- 87 errors on a 29-test spec.
        //
        // The two halves of one feature sat behind different conditions. A reg
        // declaration is harmless when unused, so the declaration half is now
        // unconditional; only the *checks* remain a choice.
        {
            self.predeclare_call_array_tmps(node, block_name);
            // t27#1894: named test-block bindings (`h = f(...);`) parse as
            // StmtAssign, not StmtLocal, so they never got a reg declaration
            // and iverilog could not bind them. Declare every plain-identifier
            // assign target once, width-inferred from its value (64-bit
            // fallback), before any procedural statement.
            {
                let mut declared: std::collections::HashSet<String> =
                    block_locals.iter().cloned().collect();
                // Top-level TYPED locals are declared by the emit_local(Decl)
                // loop below; keep them out of this pass.
                for child in &node.children {
                    if child.kind == NodeKind::StmtLocal
                        && !child.name.is_empty()
                        && !child.extra_type.is_empty()
                    {
                        declared.insert(child.name.clone());
                    }
                }
                fn reg_decl(width: u32, signed: bool) -> String {
                    let signed_kw = if signed { " signed" } else { "" };
                    // A zero width reaches here and `width - 1` underflows: the suite
                    // panics outright in a debug build and emits
                    // `reg [18446744073709551615:0]` in release.
                    if width <= 1 {
                        format!("reg{}", signed_kw)
                    } else {
                        format!("reg{} [{}:0]", signed_kw, width - 1)
                    }
                }
                let mut stack: Vec<&Node> = node.children.iter().collect();
                while let Some(stmt) = stack.pop() {
                    if stmt.kind == NodeKind::StmtAssign && stmt.children.len() >= 2 {
                        let target = &stmt.children[0];
                        if target.kind == NodeKind::ExprIdentifier
                            && !target.name.is_empty()
                            && declared.insert(target.name.clone())
                        {
                            let (width, signed) = self
                                .expr_width_signed(&stmt.children[1])
                                .unwrap_or((64, false));
                            let name = Self::verilog_safe_identifier(&target.name);
                            self.write_indent();
                            self.write_line(&format!(
                                "{} {}; // t27#1894 test-block binding",
                                reg_decl(width, signed),
                                name
                            ));
                            // #2413: the binding declared a reg but recorded no
                            // TYPE, so `r0.raw` on a struct-returning call fell
                            // past the part-select branch and flattened to the
                            // unbound `r0_raw`. Register the callee's return
                            // type; the block-end cleanup removes it with the
                            // other block locals.
                            if let Some(rt) = stmt
                                .children
                                .get(1)
                                .filter(|c| c.kind == NodeKind::ExprCall)
                                .and_then(|c| self.fn_return_types.get(&c.name))
                                .cloned()
                            {
                                if self.is_lowerable_scalar_struct_type(&rt) {
                                    self.local_types.insert(target.name.clone(), rt);
                                    block_locals.push(target.name.clone());
                                }
                            }
                        }
                        // Tuple-destructure binding `(a, b) = call()`: every
                        // element identifier needs a reg at its ELEMENT width.
                        // A 64-bit default made `{d,c,b,a} = call()` slice the
                        // 32-bit packed return wrongly (t27#1948).
                        if target.kind == NodeKind::ExprTuple {
                            // Element types from the callee's tuple return type.
                            let elem_types: Vec<String> = stmt
                                .children
                                .get(1)
                                .filter(|c| c.kind == NodeKind::ExprCall)
                                .and_then(|c| self.fn_return_types.get(&c.name))
                                .map(|rt| {
                                    let t = rt.trim();
                                    if t.starts_with('(') && t.ends_with(')') {
                                        t[1..t.len() - 1]
                                            .split(',')
                                            .map(|e| e.trim().to_string())
                                            .collect()
                                    } else {
                                        Vec::new()
                                    }
                                })
                                .unwrap_or_default();
                            for (idx, e) in target.children.iter().enumerate() {
                                if e.kind != NodeKind::ExprIdentifier || e.name.is_empty() {
                                    continue;
                                }
                                let (w, signed) = elem_types
                                    .get(idx)
                                    .map(|t| (self.packed_width(t).max(1), self.packed_signed(t)))
                                    .unwrap_or((64, false));
                                // A `_` element is a discard: Verilog has no
                                // wildcard, so give the position a throwaway reg
                                // keyed by (line, index) so it is stable across
                                // the decl pass and the assignment (t27#1948).
                                let decl_name = if e.name == "_" {
                                    format!("__t27_disc_{}_{}", target.line, idx)
                                } else {
                                    e.name.clone()
                                };
                                if declared.insert(decl_name.clone()) {
                                    self.write_indent();
                                    self.write_line(&format!(
                                        "{} {}; // t27#1948 tuple binding",
                                        reg_decl(w, signed),
                                        Self::verilog_safe_identifier(&decl_name)
                                    ));
                                }
                            }
                        }
                    }
                    // A `for i in ..` loop variable needs an `integer`
                    // declaration at the block top (t27#1948, TB for-loop
                    // support). The body statements are walked via `stack`.
                    if stmt.kind == NodeKind::StmtForRange
                        && !stmt.name.is_empty()
                        && declared.insert(stmt.name.clone())
                    {
                        self.write_indent();
                        self.write_line(&format!(
                            "integer {}; // t27#1948 loop variable",
                            Self::verilog_safe_identifier(&stmt.name)
                        ));
                    }
                    // Untyped (or nested) `let` locals never reached a reg
                    // declaration either -- iverilog cannot bind them
                    // (t27#1948, the biggest testbench compile class).
                    if stmt.kind == NodeKind::StmtLocal
                        && !stmt.name.is_empty()
                        && declared.insert(stmt.name.clone())
                    {
                        let (width, signed) = stmt
                            .children
                            .first()
                            .and_then(|i| self.expr_width_signed(i))
                            .unwrap_or((64, false));
                        // W644: T53 predicted "a third unescaped emit site is
                        // the way to bet", and the artefact gate found it on its
                        // first corpus run: `let input = …` emitted
                        // `reg [63:0] input;` -- `input` is a Verilog keyword.
                        // 171 specs, against the 4 iverilog had surfaced, because
                        // simulation only sees the specs it reaches (T21) while
                        // the artefact check is total (T54).
                        let name = Self::verilog_safe_identifier(&stmt.name);
                        self.write_indent();
                        self.write_line(&format!(
                            "{} {}; // t27#1948 let binding",
                            reg_decl(width, signed),
                            name
                        ));
                        // #2413: same type registration as the assign-binding
                        // path -- a struct-returning call bound by `given`/`and`
                        // needs its TYPE on record or `r0.raw` flattens to the
                        // unbound `r0_raw`.
                        if let Some(rt) = stmt
                            .children
                            .first()
                            .filter(|c| c.kind == NodeKind::ExprCall)
                            .and_then(|c| self.fn_return_types.get(&c.name))
                            .cloned()
                        {
                            if self.is_lowerable_scalar_struct_type(&rt) {
                                self.local_types.insert(stmt.name.clone(), rt);
                                block_locals.push(stmt.name.clone());
                            }
                        }
                    }
                    stack.extend(stmt.children.iter());
                }
            }
            let mut probe_idx = 0usize;
            for child in &node.children {
                if child.kind == NodeKind::StmtLocal
                    && !child.name.is_empty()
                    && !child.extra_type.is_empty()
                {
                    self.write_indent();
                    self.emit_local(child, LocalEmitPhase::Decl);
                }
                // Tuple-destructure local `let (a, b) = call()`: the packed temp
                // (__tup_l{line}) and the element regs are declared only in the
                // Decl phase, which the TB Init-only path skips -- so the temp
                // was referenced undeclared ("Could not find variable
                // __tup_l242"). Declare them at the top of the block here.
                if child.kind == NodeKind::StmtLocal
                    && child.name.is_empty()
                    && !child.extra_field.is_empty()
                {
                    self.emit_local(child, LocalEmitPhase::Decl);
                }
                // Pre-declare a probe for every assert_eq in the block.
                let stmt = if child.kind == NodeKind::StmtExpr {
                    child.children.first()
                } else {
                    None
                };
                let is_assert = stmt.map_or(false, |s| {
                    s.kind == NodeKind::ExprCall
                        && s.name == "assert_eq"
                        && s.children.len() == 2
                });
                if is_assert {
                    let actual = &stmt.unwrap().children[0];
                    let (width, signed) = self.expr_width_signed(actual)
                        .unwrap_or((64, false));
                    if width <= 64 {
                        let probe_name = format!(
                            "_t27_probe_{}_{}",
                            Self::sanitize_identifier(block_name),
                            probe_idx
                        );
                        let signed_kw = if signed { " signed" } else { "" };
                        let decl = if width == 1 {
                            format!("reg{}", signed_kw)
                        } else {
                            format!("reg{} [{}:0]", signed_kw, width - 1)
                        };
                        self.write_indent();
                        self.write_line(&format!(
                            "{} {}; // W539 typed probe w={} signed={}",
                            decl, probe_name, width, signed
                        ));
                        self.probe_specs.push((probe_name, width, signed, None));
                        probe_idx += 1;
                    } else {
                        // W540: split the wide expression into 64-bit (or final
                        // partial) slice probes.  Declare a temporary packed reg
                        // here so all variable declarations precede procedural
                        // statements in the test block.
                        let tmp_name = format!(
                            "_t27_probe_tmp_{}_{}",
                            Self::sanitize_identifier(block_name),
                            probe_idx
                        );
                        self.write_indent();
                        self.write_line(&format!(
                            "reg [{}:0] {}; // W540 wide probe tmp",
                            width - 1,
                            tmp_name
                        ));
                        let mut offset = 0u32;
                        let mut slice_idx = 0usize;
                        while offset < width {
                            let slice_width = (width - offset).min(64);
                            let slice_name = format!(
                                "_t27_probe_{}_{}_s{}",
                                Self::sanitize_identifier(block_name),
                                probe_idx,
                                slice_idx
                            );
                            let range = Self::range_decl(slice_width);
                            self.write_indent();
                            self.write_line(&format!(
                                "reg {}{} {}; // W540 slice offset={} w={} signed={}",
                                range,
                                if range.is_empty() { "" } else { " " },
                                slice_name,
                                offset,
                                slice_width,
                                signed
                            ));
                            self.probe_specs.push((slice_name, slice_width, signed, Some(offset)));
                            offset += slice_width;
                            slice_idx += 1;
                        }
                        probe_idx += 1;
                    }
                }
            }
            // W553/W557: after probe registers, declare temporaries for any
            // function calls returning primitive scalars or scalar arrays that are
            // used at multiple sites in this block.
            let tmp_decls: Vec<(String, u32, bool)> = self
                .call_array_tmp_info
                .iter()
                .map(|(n, (_, _, w, s))| (n.clone(), *w, *s))
                .collect();
            for (tmp_name, width, signed) in tmp_decls {
                let range = Self::range_decl(width);
                let signed_kw = if signed { " signed" } else { "" };
                self.write_indent();
                if range.is_empty() {
                    self.write_line(&format!(
                        "reg{} {}; // W557 packed/scalar call tmp w={} signed={}",
                        signed_kw, tmp_name, width, signed
                    ));
                } else {
                    self.write_line(&format!(
                        "reg{} [{}:0] {}; // W557 packed/scalar call tmp w={} signed={}",
                        signed_kw, width - 1, tmp_name, width, signed
                    ));
                }
            }
        }
        block_locals
    }

    /// W459: true if the test block contains any bare function-call statement
    /// (other than `assert` / `assert_eq`, which are emitted as SV assertions).
    /// Recursively scans nested statements for calls that need a dummy result
    /// register.
    fn test_block_has_bare_call(node: &Node) -> bool {
        fn scan(n: &Node) -> bool {
            if n.kind == NodeKind::StmtExpr {
                if let Some(expr) = n.children.first() {
                    if expr.kind == NodeKind::ExprCall
                        && expr.name != "assert"
                        && expr.name != "assert_eq"
                    {
                        return true;
                    }
                }
            }
            n.children.iter().any(scan)
        }
        node.children.iter().any(scan)
    }

    fn gen_verilog_test(&mut self, node: &Node) {
        let safe_test_name = Self::sanitize_identifier(&node.name);
        self.write_indent();
        self.write_line(&format!("// test: {}", node.name));
        // W459: declare a module-scope dummy register for consuming the return
        // value of bare function calls in this test block. Verilog-2001 requires
        // function-call results to be used in an expression; assigning to a
        // local reg keeps the call legal while preserving the side effect.
        if Self::test_block_has_bare_call(node) {
            self.write_indent();
            self.write_line(&format!(
                "reg [31:0] {}_w459_tmp;",
                safe_test_name
            ));
        }
        self.write_indent();
        self.write_line(&format!(
            "initial begin : {}_test",
            safe_test_name
        ));
        self.indent();
        // W653 (T74): a test block printed PASSED **unconditionally**, after any
        // number of failing assertions. The emitted shape was
        //     if (!(cond)) begin $display("... FAILED"); end
        //     $display("... PASSED");
        // so a failing test printed FAILED *and* PASSED, and any log scraper
        // counting PASSED counted it as a success. W640 fixed the EMPTY-body
        // case (T45) and left this one -- the third instance of T52's shape in
        // this one emitter. A block-scoped flag makes the final verdict depend
        // on what actually happened.
        self.write_indent();
        self.write_line("reg t27_failed;");
        self.verilog_checks_emitted = 0;
        let block_locals = self.gen_verilog_probe_prelude(node, &node.name);
        self.write_indent();
        self.write_line("t27_failed = 1'b0;");
        self.write_indent();
        self.write_line(&format!("$display(\"[TEST] {} : starting\");", node.name));
        self.with_call_array_temps_enabled(|this| {
            for child in &node.children {
                this.gen_verilog_test_stmt(child, &node.name, "TEST");
                // W560: a call-return temp is CSE'd by call TEXT, but a test
                // block mutates its bindings between statements
                // (`st = on_ack(st);` repeated). Caching the temp across a
                // reassignment reused a STALE value, so the state never
                // advanced. After any statement that rebinds a variable,
                // invalidate the materialized set so the next use re-assigns the
                // temp from the current values. Nested-call temps inside a
                // single (non-mutating) statement are unaffected — they still
                // materialize once, in dependency order.
                if matches!(child.kind, NodeKind::StmtAssign)
                    || (child.kind == NodeKind::StmtLocal && !child.name.is_empty())
                {
                    this.call_array_tmp_materialized.clear();
                }
            }
        });
        for name in block_locals {
            self.local_types.remove(&name);
        }
        self.write_indent();
        // W640 (fixes T45): a test block with no lowered statements printed
        // PASSED unconditionally -- 3,429 of 12,067 blocks (28%), of which 1,792
        // come from authored-empty `test X { /* verify baseline */ }`. The Zig
        // backend emits `test "X" {}` for the same node and claims nothing; the
        // same source was honest in one backend and false in the other. A
        // simulation log must not report a check that never ran.
        if node.children.is_empty() {
            self.write_line(&format!(
                "$display(\"[TEST] {} : NOT CHECKED (empty body)\");",
                node.name
            ));
        } else if self.verilog_checks_emitted == 0 {
            // W653: when assertion emission is off, `gen_verilog_test_stmt`
            // lowers nothing, so the block has statements but checks nothing.
            // That is the T45 case reached by a different route, and it must
            // report the reserved symbol rather than a verdict.
            self.write_line(&format!(
                "$display(\"[TEST] {} : NOT CHECKED (no checks lowered)\");",
                node.name
            ));
        } else {
            self.write_line(&format!(
                "if (t27_failed) $display(\"[TEST] {} : FAILED\"); else $display(\"[TEST] {} : PASSED\");",
                node.name, node.name
            ));
        }
        self.dedent();
        self.write_indent();
        self.write_line("end");
    }

    fn gen_verilog_test_stmt(&mut self, node: &Node, test_name: &str, block_tag: &str) {
        if self.emit_test_assertions {
            match node.kind {
                NodeKind::StmtExpr => {
                    // W553: materialize any call-return packed-array temporaries
                    // before the statement that uses them.
                    self.materialize_call_array_tmps_in_expr(node);
                    if let Some(expr) = node.children.first() {
                        if expr.kind == NodeKind::ExprCall
                            && expr.name == "assert_eq"
                            && expr.children.len() == 2
                        {
                            // W538: assign the scalar probe that captures the
                            // actual expression value for independent VCD cross-check.
                            // W539: probe metadata was recorded during hoisting.
                            // W540: wide expressions are split into slice probes.
                            let probe_idx = self.probe_counter;
                            self.probe_counter += 1;
                            let base_name = format!(
                                "_t27_probe_{}_{}",
                                Self::sanitize_identifier(test_name),
                                probe_idx
                            );
                            let slice_prefix = format!("{}_s", base_name);
                            let specs: Vec<(String, u32, bool, Option<u32>)> = self
                                .probe_specs
                                .iter()
                                .filter(|(n, _, _, _)| {
                                    n == &base_name || n.starts_with(&slice_prefix)
                                })
                                .cloned()
                                .collect();
                            let is_wide = specs.iter().any(|(_, _, _, off)| off.is_some());
                            if is_wide {
                                // W540: multi-slice probe.  Determine the full
                                // packed width from the slice coverage.
                                let full_width = specs
                                    .iter()
                                    .map(|(_, w, _, off)| off.unwrap_or(0) + w)
                                    .max()
                                    .unwrap_or(64);
                                // The packed temporary reg was declared with
                                // the probe slices; just assign it here.
                                let tmp_name = format!(
                                    "_t27_probe_tmp_{}_{}",
                                    Self::sanitize_identifier(test_name),
                                    probe_idx
                                );
                                self.write_indent();
                                self.write(&format!("{} = (", tmp_name));
                                self.gen_verilog_expr(&expr.children[0]);
                                self.write_line(");");
                                for (slice_name, slice_width, _signed, offset) in &specs {
                                    let off = offset.unwrap_or(0);
                                    self.write_indent();
                                    self.write_line(&format!(
                                        "{} = {}[{} +: {}];",
                                        slice_name, tmp_name, off, slice_width
                                    ));
                                    self.write_indent();
                                    self.write_line(&format!(
                                        "$display(\"[PROBE] {} {} = %0d\", {});",
                                        test_name, probe_idx, slice_name
                                    ));
                                }
                            } else {
                                self.write_indent();
                                self.write(&format!("{} = (", base_name));
                                self.gen_verilog_expr(&expr.children[0]);
                                self.write_line(");");
                                self.write_indent();
                                self.write_line(&format!(
                                    "$display(\"[PROBE] {} {} = %0d\", {});",
                                    test_name, probe_idx, base_name
                                ));
                            }
                            self.write_indent();
                            self.write("if (((");
                            self.gen_verilog_expr(&expr.children[0]);
                            self.write(") != (");
                            self.gen_verilog_expr(&expr.children[1]);
                            self.write("))) begin\n");
                            self.indent();
                            self.write_indent();
                            self.write_line(&format!(
                                "$display(\"[{}] {} : FAILED\");",
                                block_tag, test_name
                            ));
                            // W653 (T74): record it, or the block-final verdict
                            // cannot see that this assertion failed.
                            self.write_indent();
                            self.write_line("t27_failed = 1'b1;");
                            self.verilog_checks_emitted += 1;
                            self.write_indent();
                            self.write("$display(\"  expected %0d, got %0d\", (");
                            self.gen_verilog_expr(&expr.children[1]);
                            self.write("), (");
                            self.gen_verilog_expr(&expr.children[0]);
                            self.write_line("));");
                            self.dedent();
                            self.write_indent();
                            self.write_line("end");
                        } else if expr.kind == NodeKind::ExprCall
                            && expr.name == "assert"
                            && !expr.children.is_empty()
                        {
                            // Plain `assert(cond, "msg")`: `assert` is not a
                            // Verilog-2005 keyword and the two-argument form is
                            // not SystemVerilog either, so emitting it verbatim
                            // made iverilog reject the whole testbench. Lower it
                            // to the same if-based check assert_eq gets.
                            let msg = expr
                                .children
                                .get(1)
                                .map(|m| m.value.trim_matches('"').replace('%', "%%"))
                                .unwrap_or_default();
                            self.write_indent();
                            self.write("if (!(");
                            self.gen_verilog_expr(&expr.children[0]);
                            self.write(")) begin\n");
                            self.indent();
                            self.write_indent();
                            self.write_line(&format!(
                                "$display(\"[{}] {} : FAILED\");",
                                block_tag, test_name
                            ));
                            // W653 (T74): record it, or the block-final verdict
                            // cannot see that this assertion failed.
                            self.write_indent();
                            self.write_line("t27_failed = 1'b1;");
                            self.verilog_checks_emitted += 1;
                            self.write_indent();
                            self.write_line(&format!(
                                "$display(\"  assert failed: {}\");",
                                msg
                            ));
                            self.dedent();
                            self.write_indent();
                            self.write_line("end");
                        } else {
                            // #2413(3): a bare call in statement position whose
                            // value was hoisted into a W557 temp would emit the
                            // RESIDUAL temp name as a statement -- and a bare
                            // identifier statement is a task enable in Verilog
                            // ("Enable of unknown task _t27_call_tmp_...").
                            // The materialized assignment above already
                            // performed the call; the residual says nothing.
                            let hoisted_bare_call = self.use_call_array_temps
                                && expr.kind == NodeKind::ExprCall
                                && self
                                    .call_returning_cse_value_info(expr)
                                    .map(|(key, _, _, _, _)| {
                                        self.call_array_tmp_names.contains_key(&key)
                                    })
                                    .unwrap_or(false);
                            if !hoisted_bare_call {
                                self.write_indent();
                                self.gen_verilog_expr(expr);
                                self.write_line(";");
                            }
                        }
                    }
                }
                NodeKind::StmtLocal => {
                    // W553: materialize any call-return packed-array temporaries
                    // before the local initializer that uses them.
                    self.materialize_call_array_tmps_in_expr(node);
                    self.write_indent();
                    self.emit_local(node, LocalEmitPhase::Init);
                }
                NodeKind::StmtAssign => {
                    // W553: materialize any call-return packed-array temporaries
                    // before the assignment that uses them.
                    self.materialize_call_array_tmps_in_expr(node);
                    self.write_indent();
                    self.gen_verilog_stmt(node);
                }
                NodeKind::StmtForRange
                | NodeKind::StmtWhile
                // t27#1948's comment below names `for`/`while`/`if`, and `if`
                // was never in this arm. `if (es_prestandard(8) != 0) { ok =
                // false; }` at the top level of a test block became
                // `// (stmt: StmtIf)`, so `ok` was set true and never set
                // false: the test could not fail and reported PASSED.
                | NodeKind::StmtFor
                | NodeKind::StmtIf => {
                    self.materialize_call_array_tmps_in_expr(node);
                    self.gen_verilog_stmt(node);
                }
                _ => {
                    self.write_indent();
                    self.write_line(&format!("// (stmt: {:?})", node.kind));
                }
            }
        } else {
            match node.kind {
                NodeKind::StmtExpr => {
                    if let Some(expr) = node.children.first() {
                        if expr.kind == NodeKind::ExprCall
                            && expr.name == "assert_eq"
                            && expr.children.len() == 2
                        {
                            // W459: emit assert_eq as a REAL comparison. The whole
                            // test section is `ifndef SIMULATION`-guarded, so it is
                            // excluded from synthesis regardless; keeping the check
                            // real makes the test bench meaningful.
                            self.materialize_call_array_tmps_in_expr(node);
                            self.write_indent();
                            self.write("if (!((");
                            self.gen_verilog_expr(&expr.children[0]);
                            self.write(") == (");
                            self.gen_verilog_expr(&expr.children[1]);
                            self.write_line("))) begin");
                            self.indent();
                            self.write_indent();
                            self.write_line(&format!(
                                "$display(\"[{}] {} : FAILED\");",
                                block_tag, test_name
                            ));
                            // W653 (T74): record it, or the block-final verdict
                            // cannot see that this assertion failed.
                            self.write_indent();
                            self.write_line("t27_failed = 1'b1;");
                            self.verilog_checks_emitted += 1;
                            self.dedent();
                            self.write_indent();
                            self.write_line("end");
                        } else if expr.kind == NodeKind::ExprCall
                            && expr.name == "assert"
                            && !expr.children.is_empty()
                        {
                            // Same lowering as in the assertions path: a verbatim
                            // `assert(cond, "msg")` is not compilable Verilog.
                            let msg = expr
                                .children
                                .get(1)
                                .map(|m| m.value.trim_matches('"').replace('%', "%%"))
                                .unwrap_or_default();
                            self.materialize_call_array_tmps_in_expr(node);
                            self.write_indent();
                            // W653 (T76): `if (!(cond))` is FALSE when cond is
                            // x, so an assertion on an unknown value skipped the
                            // failure branch and the block printed PASSED. Case
                            // inequality `!== 1'b1` treats x as not-true, so an
                            // unknown now FAILS. Unknown is not verified.
                            self.write("if ((");
                            self.gen_verilog_expr(&expr.children[0]);
                            self.write_line(") !== 1'b1) begin");
                            self.indent();
                            self.write_indent();
                            self.write_line(&format!(
                                "$display(\"[{}] {} : FAILED\");",
                                block_tag, test_name
                            ));
                            // W653 (T74): record it, or the block-final verdict
                            // cannot see that this assertion failed.
                            self.write_indent();
                            self.write_line("t27_failed = 1'b1;");
                            self.verilog_checks_emitted += 1;
                            self.write_indent();
                            self.write_line(&format!(
                                "$display(\"  assert failed: {}\");",
                                msg
                            ));
                            self.dedent();
                            self.write_indent();
                            self.write_line("end");
                        } else if expr.kind == NodeKind::ExprCall {
                            // A bare side-effecting call (e.g. `set(1, v)`) is a
                            // real statement.
                            self.materialize_call_array_tmps_in_expr(node);
                            self.write_indent();
                            self.gen_verilog_expr(expr);
                            self.write_line(";");
                        }
                    }
                }
                NodeKind::StmtLocal => {
                    // Regs are declared up front (typed: emit_local(Decl);
                    // untyped: the t27#1948 pass); emit only the assignment.
                    // W653 (T78): materialize first -- see the StmtAssign arm.
                    self.materialize_call_array_tmps_in_expr(node);
                    if !node.children.is_empty() {
                        self.emit_local(node, LocalEmitPhase::Init);
                    }
                }
                NodeKind::StmtAssign => {
                    // t27#1894 declared the target regs; the assignment itself
                    // was still emitted COMMENTED OUT, so every binding built
                    // from a call (`array = create(...)`) stayed X in the TB.
                    //
                    // W653 (T78): and this arm never MATERIALIZED the call
                    // temporary, while the `emit_test_assertions == true` arm
                    // (above) always did. So `given v = two()` emitted
                    //     reg v; reg _t27_call_tmp_..._0;   // declared
                    //     v = _t27_call_tmp_..._0;          // never assigned
                    // and every assertion downstream compared against X. In
                    // Verilog `if (!(x))` is FALSE, so no test could fail --
                    // T76's root cause. The flag is named for assertions and was
                    // silently gating materialization too, exactly as in T75.
                    self.materialize_call_array_tmps_in_expr(node);
                    self.gen_verilog_stmt(node);
                }
                NodeKind::StmtForRange
                | NodeKind::StmtWhile
                | NodeKind::StmtFor
                | NodeKind::StmtIf => {
                    // Control flow in a test block: a `for`/`while`/`if` was
                    // dropped as `// (stmt: StmtForRange)`, silently voiding
                    // loop bodies that accumulate assertions (t27#1948).
                    self.gen_verilog_stmt(node);
                }
                _ => {
                    self.write_indent();
                    self.write_line(&format!("// (stmt: {:?})", node.kind));
                }
            }
        }
    }

    fn gen_verilog_invariant(&mut self, node: &Node) {
        self.write_indent();
        if node.children.is_empty() && node.extra_type.is_empty() {
            self.write_line(&format!("// invariant: {}", node.name));
        } else if !node.children.is_empty() {
            self.write(&format!(
                "// invariant {} : ",
                Self::sanitize_identifier(&node.name)
            ));
            // The predicate arrives wrapped in a statement node, and the
            // expression printer answers `/* unsupported expr: StmtExpr */`.
            // All 4702 invariants in the self-checking testbench rendered that
            // and not one rendered a predicate.
            self.gen_verilog_expr(unwrap_single(&node.children[0]));
            self.write_line("");
        } else {
            self.write_line(&format!("// invariant: {}", node.name));
        }
    }

    /// Resolve the element types of a tuple-destructuring local
    /// `let (a, b) = expr`. The tuple type comes from an explicit annotation
    /// when present, otherwise from the return type of the initializing call.
    fn tuple_local_elem_types(&self, node: &Node) -> Option<Vec<String>> {
        if !node.extra_type.trim().is_empty() {
            let t = node.extra_type.trim();
            if t.starts_with('(') && t.ends_with(')') && t.contains(',') {
                let inner = &t[1..t.len() - 1];
                return Some(inner.split(',').map(|e| e.trim().to_string()).collect());
            }
            return None;
        }
        let init = node.children.first()?;
        // Tuple LITERAL init `let (a, b) = (4, 3)`: infer each element's type
        // from the count of bindings (all default u32). Previously only
        // call-returning inits were handled, so a literal-tuple destructure
        // emitted a nameless `reg [31:0] ;` (t27#1948).
        if init.kind == NodeKind::ExprTuple {
            let n = node
                .extra_field
                .split(',')
                .filter(|s| !s.trim().is_empty())
                .count();
            if n > 0 && n == init.children.len() {
                return Some(vec!["u32".to_string(); n]);
            }
            return None;
        }
        if init.kind != NodeKind::ExprCall {
            return None;
        }
        let ty = self.fn_return_types.get(&init.name)?.clone();
        let t = ty.trim();
        if t.starts_with('(') && t.ends_with(')') && t.contains(',') {
            let inner = &t[1..t.len() - 1];
            Some(inner.split(',').map(|e| e.trim().to_string()).collect())
        } else {
            None
        }
    }

    /// Emit a local variable declaration and/or initialization. `phase` selects
    /// whether to output only the `reg` declaration, only the procedural
    /// assignment, or the full original combined form.
    fn emit_local(&mut self, node: &Node, phase: LocalEmitPhase) {
        // Tuple-destructuring local `let (s, d) = call(...)`: the binding names
        // live in extra_field (comma-joined) with an empty node.name. Lower to a
        // packed temp holding the callee's tuple, then slice each binding out
        // with element 0 in the LSB -- matching the ExprTuple concatenation and
        // the packed_width sum.
        if node.name.is_empty() && !node.extra_field.is_empty() {
            if let Some(elem_types) = self.tuple_local_elem_types(node) {
                let names: Vec<String> = node
                    .extra_field
                    .split(',')
                    .map(|s| s.trim().to_string())
                    .filter(|s| !s.is_empty())
                    .collect();
                if !names.is_empty() && names.len() == elem_types.len() {
                    let widths: Vec<u32> =
                        elem_types.iter().map(|t| self.packed_width(t).max(1)).collect();
                    let total: u32 = widths.iter().sum();
                    // Deterministic temp name (stable across Decl/Init phases).
                    let tmp = format!("__tup_l{}", node.line);
                    if phase != LocalEmitPhase::Init {
                        self.write_indent();
                        self.write_line(&format!("reg [{}:0] {};", total - 1, tmp));
                        for (nm, w) in names.iter().zip(widths.iter()) {
                            self.write_indent();
                            self.write_line(&format!("reg [{}:0] {};", w - 1, nm));
                        }
                    }
                    if phase != LocalEmitPhase::Decl && !node.children.is_empty() {
                        self.write_indent();
                        self.write(&format!("{} = ", tmp));
                        // A tuple LITERAL RHS `(4, 3, 1)` emits bare unsized
                        // literals in the concatenation ("indefinite width").
                        // Width-cast each element to its binding width; other
                        // RHS forms (calls) keep the plain emission.
                        let init = &node.children[0];
                        if init.kind == NodeKind::ExprTuple
                            && init.children.len() == widths.len()
                        {
                            let parts: Vec<String> = init
                                .children
                                .iter()
                                .zip(widths.iter())
                                .rev()
                                .map(|(c, w)| self.emit_packed_scalar_value(c, *w, false))
                                .collect();
                            self.write(&format!("{{{}}}", parts.join(", ")));
                        } else {
                            self.gen_verilog_expr(init);
                        }
                        self.write_line(";");
                        let mut off = 0u32;
                        for (nm, w) in names.iter().zip(widths.iter()) {
                            self.write_indent();
                            self.write_line(&format!(
                                "{} = {}[{}:{}];",
                                nm,
                                tmp,
                                off + w - 1,
                                off
                            ));
                            off += w;
                        }
                    }
                    return;
                }
            }
        }
        // W533: bare scalar structs are lowered as a single packed-vector
        // register with whole-struct initialization.
        if Self::parse_array_type(&node.extra_type).is_none()
            && self.is_lowerable_scalar_struct_type(&node.extra_type)
        {
            let base = Self::base_type_name(&node.extra_type);
            let width = self.element_width(&base);
            if phase != LocalEmitPhase::Init {
                self.write_indent();
                self.write_line(&format!("reg [{}:0] {};", width - 1, Self::verilog_safe_identifier(&node.name)));
            }
            if phase != LocalEmitPhase::Decl && !node.children.is_empty() {
                if phase == LocalEmitPhase::Full {
                    self.write_line("");
                }
                self.write_indent();
                self.write(&format!("{} = ", Self::verilog_safe_identifier(&node.name)));
                self.gen_verilog_expr(&node.children[0]);
                self.write_line(";");
            } else if phase == LocalEmitPhase::Full {
                self.write_line("");
            }
            return;
        }

        // W563: one-dimensional arrays of scalar structs are lowered as a single
        // packed-vector register and assigned wholesale (from a call or from a
        // packed array literal).
        if let Some((dims, elem_type)) = Self::parse_array_type(&node.extra_type) {
            if dims.len() == 1 && self.struct_decls.contains_key(&elem_type) {
                let elem_w = self.element_width(&elem_type) as usize;
                let total_width = dims[0] * elem_w;
                if phase != LocalEmitPhase::Init {
                    self.write_indent();
                    // A zero-length array has no bits, and `0 - 1` on a usize is
                    // 18446744073709551615. `[0]Notebook` is a legal spec
                    // construct -- an empty list -- and it emitted
                    // `reg [18446744073709551615:0] notebooks;` at exit 0
                    // (#2566). Clamped the way `range_decl` clamps: a one-bit
                    // placeholder for a type that occupies none, which is a legal
                    // declaration rather than an impossible one.
                    self.write_line(&format!("reg [{}:0] {};", total_width.saturating_sub(1), Self::verilog_safe_identifier(&node.name)));
                }
                if phase != LocalEmitPhase::Decl && !node.children.is_empty() {
                    let child = &node.children[0];
                    self.write_indent();
                    self.write(&format!("{} = ", Self::verilog_safe_identifier(&node.name)));
                    if child.kind == NodeKind::ExprArrayLiteral {
                        self.emit_packed_array_literal_concat(child, &node.extra_type);
                    } else {
                        self.gen_verilog_expr(child);
                    }
                    self.write_line(";");
                } else if phase == LocalEmitPhase::Full {
                    self.write_line("");
                }
                return;
            }
        }

        // W527: multi-dimensional arrays of scalar structs are lowered as a
        // single packed-vector register with procedural per-element
        // initialization.
        if let Some((dims, elem_type)) = Self::parse_array_type(&node.extra_type) {
            if dims.len() >= 2 && self.struct_decls.contains_key(&elem_type) {
                let elem_w = self.element_width(&elem_type) as usize;
                let total_width: usize = dims.iter().product::<usize>() * elem_w;
                if phase != LocalEmitPhase::Init {
                    self.write_indent();
                    // A zero-length array has no bits, and `0 - 1` on a usize is
                    // 18446744073709551615. `[0]Notebook` is a legal spec
                    // construct -- an empty list -- and it emitted
                    // `reg [18446744073709551615:0] notebooks;` at exit 0
                    // (#2566). Clamped the way `range_decl` clamps: a one-bit
                    // placeholder for a type that occupies none, which is a legal
                    // declaration rather than an impossible one.
                    self.write_line(&format!("reg [{}:0] {};", total_width.saturating_sub(1), Self::verilog_safe_identifier(&node.name)));
                }
                if phase != LocalEmitPhase::Decl && !node.children.is_empty() {
                    let child = &node.children[0];
                    // W566: a 2-D array of scalar structs initialized from a packed-vector
                    // expression (function call or other non-literal) can be assigned
                    // wholesale because the layout matches the packed-vector register.
                    if child.kind != NodeKind::ExprArrayLiteral {
                        self.write_indent();
                        self.write(&format!("{} = ", Self::verilog_safe_identifier(&node.name)));
                        self.gen_verilog_expr(child);
                        self.write_line(";");
                    } else {
                        self.write_indent();
                        self.write_line("begin");
                        self.indent();
                        self.emit_packed_struct_array_init(
                            &Self::verilog_safe_identifier(&node.name),
                            &node.extra_type,
                            child,
                        );
                        self.dedent();
                        self.write_indent();
                        self.write_line("end");
                    }
                } else if phase == LocalEmitPhase::Full {
                    self.write_line("");
                }
                return;
            }
        }

        // W531/W546: 1-D and multi-D arrays of primitive scalars are lowered as
        // unpacked Verilog arrays when initialized by an array literal, so that
        // variable-index writes are preserved.  When initialized by a function call
        // (or any other packed-vector expression), they are stored as a packed
        // vector and assigned wholesale.
        if Self::is_primitive_array_type(&node.extra_type) {
            let (dims, elem_type) = Self::primitive_array_info(&node.extra_type
            ).unwrap_or((Vec::new(), "u32".to_string()));
            let child = node.children.first();
            // A primitive [T; N] local passed WHOLE to a function must be a
            // packed vector -- fn params lower packed since t27#1952, so an
            // unpacked memory init (the array-literal path) desynced and
            // iverilog reported "Array needs an array index" (t27#1948 tail).
            // Pack the literal init too: the concat text path (t27#1953) and
            // part-select indexing (#1745) both already support it.
            let is_packed_init = child.is_some();
            if is_packed_init {
                let width = self.packed_width(&node.extra_type) as usize;
                let signed = self.packed_signed(&node.extra_type);
                let signed_str = if signed { "signed " } else { "" };
                let range = Self::range_decl(width as u32);
                let range_str = if range.is_empty() {
                    String::new()
                } else {
                    format!("{} ", range)
                };
                if phase != LocalEmitPhase::Init {
                    self.write_indent();
                    self.write_line(&format!(
                        "reg {}{}{};",
                        signed_str, range_str, Self::verilog_safe_identifier(&node.name)
                    ));
                }
                if phase != LocalEmitPhase::Decl && child.is_some() {
                    let c = child.unwrap();
                    self.write_indent();
                    self.write(&format!("{} = ", Self::verilog_safe_identifier(&node.name)));
                    if c.kind == NodeKind::ExprArrayLiteral {
                        self.emit_packed_array_literal_concat(c, &node.extra_type);
                    } else {
                        self.gen_verilog_expr(c);
                    }
                    self.write_line(";");
                } else if phase == LocalEmitPhase::Full {
                    self.write_line("");
                }
                self.local_packed_primitive_arrays.insert(
                    node.name.clone(),
                    (dims.clone(), elem_type.clone()),
                );
                return;
            }
            let elem_w = Self::type_to_width(&elem_type).max(1) as usize;
            let signed = Self::type_is_signed(
                &Self::parse_array_type(&node.extra_type)
                    .map(|(_, et)| et)
                    .unwrap_or_default(),
            );
            let signed_str = if signed { "signed " } else { "" };
            let dims_str = dims
                .iter()
                .map(|d| format!("[0:{}]", d - 1))
                .collect::<String>();
            if phase != LocalEmitPhase::Init {
                self.write_indent();
                // W643: this site emitted `node.name` RAW while every expression
                // path already went through `verilog_safe_identifier`. A local
                // array named `buf` -- a Verilog primitive gate -- produced
                // `reg [15:0] buf[0:3];`, which iverilog rejects with a bare
                // "syntax error". Four of the ten real Icarus rejections are
                // this one unescaped site. See T53.
                self.write_line(&format!(
                    "reg {}{}[{}:0] {}{};",
                    signed_str,
                    "",
                    elem_w - 1,
                    Self::verilog_safe_identifier(&node.name),
                    dims_str
                ));
            }
            if phase != LocalEmitPhase::Decl && child.is_some() {
                let child = child.unwrap();
                self.write_indent();
                self.write_line("begin");
                self.indent();
                self.emit_unpacked_primitive_array_init(
                    &node.name,
                    &node.extra_type,
                    child,
                );
                self.dedent();
                self.write_indent();
                self.write_line("end");
            } else if phase == LocalEmitPhase::Full {
                self.write_line("");
            }
            return;
        }

        if phase != LocalEmitPhase::Init {
            self.write_indent();
            let kw = "reg";
            let width = Self::type_to_width(&node.extra_type);
            let signed = Self::type_is_signed(&node.extra_type);
            let signed_str = if signed { "signed " } else { "" };
            let range = Self::range_decl(width);
            let range_str = if range.is_empty() {
                String::new()
            } else {
                format!("{} ", range)
            };
            // Escape a local name that collides with a Verilog keyword (e.g.
            // `task`) in both declaration and assignment, matching how reference
            // sites are already escaped, so the emitted Verilog is consistent.
            let safe = Self::verilog_safe_identifier(&node.name);
            self.write(&format!("{} {}{}{};", kw, signed_str, range_str, safe));
            if phase != LocalEmitPhase::Init {
                self.write_line("");
            }
        }
        if phase != LocalEmitPhase::Decl && !node.children.is_empty() {
            self.write_indent();
            self.write(&Self::verilog_safe_identifier(&node.name));
            self.write(" = ");
            self.gen_verilog_expr(&node.children[0]);
            self.write_line(";");
        }
    }

    fn gen_verilog_stmt(&mut self, node: &Node) {
        match node.kind {
            NodeKind::ExprReturn => {
                self.write_indent();
                if node.children.is_empty() {
                    // Bare `return;` in a function: set the early-return guard.
                    if !self.current_fn_name.is_empty() && !self.clocked_nonblocking {
                        self.write_line("__t27_ret = 1'b1;");
                    }
                }
                if !node.children.is_empty() {
                    // In Verilog functions, return is done by assigning to function name
                    let fn_name = if self.current_fn_name.is_empty() {
                        "/* return */".to_string()
                    } else {
                        Self::verilog_safe_identifier(&self.current_fn_name)
                    };
                    self.write(&format!("{} = ", fn_name));
                    // W528: when returning a nested array literal of scalar structs,
                    // lower it to a single packed concatenation matching the
                    // function's declared return width.
                    // W545: extend the same treatment to primitive scalar arrays so
                    // that [3]u8{...} is returned as a 24-bit packed vector.
                    let return_type = self.current_fn_return_type.clone();
                    let is_packed_array_return = node.children[0].kind
                        == NodeKind::ExprArrayLiteral
                        && Self::parse_array_type(&return_type)
                            .map(|(_, et)| {
                                self.struct_decls.contains_key(&et)
                                    || Self::is_primitive_scalar_type(&et)
                            })
                            .unwrap_or(false);
                    if is_packed_array_return {
                        self.emit_packed_array_literal_concat(
                            &node.children[0],
                            &return_type,
                        );
                    } else {
                        self.gen_verilog_expr(&node.children[0]);
                    }
                    self.write_line(";");
                    // EARLY RETURN: without this, execution falls through and
                    // later statements OVERWRITE the result -- a fn ending in
                    // `return 0;` returned 0 on every path (t27#1948 runtime
                    // divergence class). A guard register is used instead of
                    // `disable`, which corrupts recursive static functions.
                    if !self.current_fn_name.is_empty() && !self.clocked_nonblocking {
                        self.write_indent();
                        self.write_line("__t27_ret = 1'b1;");
                    }
                }
            }
            NodeKind::StmtLocal => {
                // #1741: inside a function body being hoisted, the declaration
                // was already emitted at the top; emit only the assignment.
                let phase = if self.hoist_fn_locals {
                    LocalEmitPhase::Init
                } else {
                    LocalEmitPhase::Full
                };
                self.emit_local(node, phase);
            }
            NodeKind::StmtAssign => {
                // W378/W379: detect tuple destructuring on the LHS of an
                // assignment: `let (a, b, c) = f(...)` is parsed as a
                // StmtAssign whose LHS is an ExprArrayLiteral with
                // extra_kind == "tuple" containing identifier children.
                if node.children.len() >= 2
                    && node.children[0].kind == NodeKind::ExprArrayLiteral
                    && node.children[0].extra_kind == "tuple"
                    && !node.children[0].children.is_empty()
                {
                    self.gen_verilog_let_destructuring(
                        &node.children[0],
                        &node.children[1],
                    );
                    return;
                }
                self.write_indent();
                if node.children.len() >= 2 {
                    let lhs = &node.children[0];
                    let rhs = &node.children[1];
                    // W546: detect assignment of a packed-vector expression to a
                    // function-local primitive scalar array.  The target identifier
                    // must be tracked as packed, and the RHS must be a call or
                    // array literal that produces a packed vector of the same width.
                    let is_packed_array_assign = lhs.kind == NodeKind::ExprIdentifier
                        && !lhs.name.is_empty()
                        && Self::is_primitive_array_type(&lhs.extra_type)
                        && (rhs.kind == NodeKind::ExprCall
                            || rhs.kind == NodeKind::ExprArrayLiteral);
                    if is_packed_array_assign {
                        let (dims, elem_type) = Self::primitive_array_info(&lhs.extra_type
                        ).unwrap_or((Vec::new(), "u32".to_string()));
                        self.write(&format!("{} = ", lhs.name));
                        if rhs.kind == NodeKind::ExprArrayLiteral {
                            self.emit_packed_array_literal_concat(rhs, &lhs.extra_type);
                        } else {
                            self.gen_verilog_expr(rhs);
                        }
                        self.write_line(";");
                        self.local_packed_primitive_arrays.insert(
                            lhs.name.clone(),
                            (dims.clone(), elem_type.clone()),
                        );
                    } else {
                        // Clocked bodies (`fn on_clock`) assign registered state
                        // with nonblocking `<=`; combinational code keeps `=`.
                        let asn = if self.clocked_nonblocking { " <= " } else { " = " };
                        self.in_lvalue = true;
                        self.gen_verilog_expr(lhs);
                        self.in_lvalue = false;
                        if let Some(op) = compound_binop(&node.extra_op) {
                            self.write(asn);
                            self.gen_verilog_expr(lhs);
                            self.write(&format!(" {} ", op));
                        } else {
                            self.write(asn);
                        }
                        self.gen_verilog_expr(rhs);
                    }
                }
                self.write_line(";");
            }
            NodeKind::StmtIf => {
                self.gen_verilog_if_stmt(node);
            }
            NodeKind::StmtWhile => {
                self.gen_verilog_while_stmt(node);
            }
            NodeKind::StmtFor => {
                self.gen_verilog_for_stmt(node);
            }
            NodeKind::StmtForRange => {
                self.gen_verilog_for_range_stmt(node);
            }
            NodeKind::StmtBreak => {
                self.write_line("disable fork;");
            }
            NodeKind::StmtContinue => {
                self.write_line("/* continue */;");
            }
            NodeKind::StmtExpr => {
                self.write_indent();
                if !node.children.is_empty() {
                    self.gen_verilog_expr(&node.children[0]);
                }
                self.write_line(";");
            }
            _ => {
                self.write_indent();
                self.gen_verilog_expr(node);
                self.write_line(";");
            }
        }
    }

    fn gen_verilog_if_stmt(&mut self, node: &Node) {
        self.write_indent();
        self.write("if (");
        if !node.children.is_empty() {
            self.gen_verilog_expr(&node.children[0]);
        }
        self.write_line(") begin");

        self.indent();
        if node.children.len() > 1 {
            for stmt in &node.children[1].children {
                self.gen_verilog_stmt(stmt);
            }
        }
        self.dedent();

        if node.children.len() > 2 {
            let else_block = &node.children[2];
            if else_block.children.len() == 1 && else_block.children[0].kind == NodeKind::StmtIf {
                self.write_indent();
                self.write("end else ");
                // Inline else-if
                self.gen_verilog_if_stmt_inline(&else_block.children[0]);
            } else {
                self.write_indent();
                self.write_line("end else begin");
                self.indent();
                for stmt in &else_block.children {
                    self.gen_verilog_stmt(stmt);
                }
                self.dedent();
                self.write_indent();
                self.write_line("end");
            }
        } else {
            self.write_indent();
            self.write_line("end");
        }
    }

    fn gen_verilog_if_stmt_inline(&mut self, node: &Node) {
        self.write("if (");
        if !node.children.is_empty() {
            self.gen_verilog_expr(&node.children[0]);
        }
        self.write_line(") begin");

        self.indent();
        if node.children.len() > 1 {
            for stmt in &node.children[1].children {
                self.gen_verilog_stmt(stmt);
            }
        }
        self.dedent();

        if node.children.len() > 2 {
            let else_block = &node.children[2];
            if else_block.children.len() == 1 && else_block.children[0].kind == NodeKind::StmtIf {
                self.write_indent();
                self.write("end else ");
                self.gen_verilog_if_stmt_inline(&else_block.children[0]);
            } else {
                self.write_indent();
                self.write_line("end else begin");
                self.indent();
                for stmt in &else_block.children {
                    self.gen_verilog_stmt(stmt);
                }
                self.dedent();
                self.write_indent();
                self.write_line("end");
            }
        } else {
            self.write_indent();
            self.write_line("end");
        }
    }

    /// W700: a `while` with a LITERAL bound becomes a bounded `for`.
    ///
    /// T192 measured it: a `while` body lowers to ZERO LOGIC, even when its
    /// bound is a compile-time constant.
    ///
    ///     if (a > b) return 1;                    132 LUT
    ///     return a + b;                            96 LUT
    ///     while (i < 4) { acc = acc + a; ... }       0 LUT
    ///
    /// `ternary_mac` reaches 951 LUT and contains no `while` at all. yosys
    /// elaborates a `while` inside a combinational `function` by discarding it:
    /// there is no static trip count, so there is nothing to unroll, and the
    /// whole body disappears without a warning.
    ///
    /// The transform is the standard fuel bound, and it preserves semantics for
    /// any loop that terminates within N iterations:
    ///
    ///     for (fuel = 0; fuel < N; fuel = fuel + 1)
    ///         if (<cond>) begin <body> end
    ///
    /// N is taken from the condition when it is `expr < LITERAL` or
    /// `expr <= LITERAL`. **When the bound is not a literal the loop is left
    /// alone and SAID SO**, because a runtime trip count cannot be unrolled by
    /// anything -- and a silently-vanishing body is what this repair exists to
    /// remove. Same discipline as W699's port width: derive it or refuse it,
    /// never default it.
    fn while_literal_bound(node: &Node) -> Option<u64> {
        let cond = node.children.first()?;
        if cond.kind != NodeKind::ExprBinary {
            return None;
        }
        let op = cond.extra_op.trim();
        if op != "<" && op != "<=" {
            return None;
        }
        let rhs = cond.children.get(1)?;
        if rhs.kind != NodeKind::ExprLiteral {
            return None;
        }
        let n: u64 = rhs.value.trim().parse().ok()?;
        // `<=` runs one more time than `<`.
        Some(if op == "<=" { n.saturating_add(1) } else { n })
    }

    fn gen_verilog_while_stmt(&mut self, node: &Node) {
        if let Some(bound) = Self::while_literal_bound(node) {
            let n = self.while_fuel_counter;
            self.while_fuel_counter += 1;
            let fuel = format!("__t27_fuel_{n}");
            let blk = format!("__t27_loop_{n}");
            self.write_indent();
            self.write_line(&format!(
                "// W700: bounded `while` unrolled to a static trip count of {bound}."
            ));
            // The counter MUST be declared, and Verilog allows a declaration only
            // at the start of a NAMED block -- so the loop gets one. The first
            // version of this transform emitted the `for` with an undeclared
            // variable, which turned a silently-empty module into a hard error:
            //   iverilog: register `__t27_fuel_0' unknown
            //   yosys:    Left hand side of 1st expression of procedural
            //             for-loop is not a register!
            // Louder, and still broken. The named block fixes both.
            self.write_indent();
            self.write_line(&format!("begin : {blk}"));
            self.indent();
            self.write_indent();
            self.write_line(&format!("integer {fuel};"));
            self.write_indent();
            self.write_line(&format!("for ({fuel} = 0; {fuel} < {bound}; {fuel} = {fuel} + 1) begin"));
            self.indent();
            self.write_indent();
            self.write("if (");
            if !node.children.is_empty() {
                self.gen_verilog_expr(&node.children[0]);
            }
            self.write_line(") begin");
            self.indent();
            if node.children.len() > 1 {
                for stmt in &node.children[node.children.len() - 1].children {
                    self.gen_verilog_stmt(stmt);
                }
                // W-27: body is the LAST child; a `while (c) : (step)` puts the step at [1].
                if node.children.len() > 2 {
                    self.gen_verilog_stmt(unwrap_single(&node.children[1]));
                }
            }
            self.dedent();
            self.write_indent();
            self.write_line("end");
            self.dedent();
            self.write_indent();
            self.write_line("end");
            self.dedent();
            self.write_indent();
            self.write_line("end");
            return;
        }

        self.write_indent();
        self.write_line(
            "// W700/W702: NOT UNROLLED -- the bound is not a literal, so there is no",
        );
        self.write_indent();
        self.write_line(
            "// static trip count and nothing can unroll it.",
        );
        self.write_indent();
        self.write_line("//");
        self.write_indent();
        self.write_line(
            "// W702 measured the consequence, which is NOT a silent zero: yosys rejects",
        );
        self.write_indent();
        self.write_line("// the enclosing function outright --");
        self.write_indent();
        self.write_line(
            "//     ERROR: Function \\<name> can only be called with constant arguments.",
        );
        self.write_indent();
        self.write_line(
            "// -- because a Verilog `function` is combinational by definition and a",
        );
        self.write_indent();
        self.write_line(
            "// data-dependent trip count is not. NINE of the thirteen entry-point specs",
        );
        self.write_indent();
        self.write_line("// that fail synthesis fail exactly here.");
        self.write_indent();
        self.write_line("//");
        self.write_indent();
        self.write_line(
            "// The fix is a DESIGN decision this compiler does not make: either give the",
        );
        self.write_indent();
        self.write_line(
            "// loop a compile-time bound, or move the entry point to `fn on_clock` and let",
        );
        self.write_indent();
        self.write_line(
            "// it be the multi-cycle operation it actually is. A loop whose length depends",
        );
        self.write_indent();
        self.write_line("// on data is sequential; naming it combinational is the error.");
        self.write_indent();
        self.write("while (");
        if !node.children.is_empty() {
            self.gen_verilog_expr(&node.children[0]);
        }
        self.write_line(") begin");

        self.indent();
        if node.children.len() > 1 {
            for stmt in &node.children[node.children.len() - 1].children {
                self.gen_verilog_stmt(stmt);
            }
            // W-27: body is the LAST child; a `while (c) : (step)` puts the step at [1].
            if node.children.len() > 2 {
                self.gen_verilog_stmt(unwrap_single(&node.children[1]));
            }
        }
        self.dedent();
        self.write_indent();
        self.write_line("end");
    }

    fn gen_verilog_for_stmt(&mut self, node: &Node) {
        // Emit as integer for loop: for (i = 0; i < N; i = i + 1)
        let body_idx = node.children.len().saturating_sub(1);

        // Use capture variable name if available, else default to __i
        let iter_var_raw = if !node.params.is_empty() {
            node.params[0].0.clone()
        } else {
            "__i".to_string()
        };
        let iter_var = Self::verilog_safe_identifier(&iter_var_raw);

        // Try to extract the range/iterable from children[0]
        // For range-based: for (iter_var = 0; iter_var < upper; iter_var = iter_var + 1)
        self.write_indent();
        if body_idx > 0 {
            let iterable = &node.children[0];
            // Emit: integer iter_var; for (iter_var = 0; iter_var < iterable; iter_var = iter_var + 1)
            self.write_line("// for-each over iterable");
            self.write_indent();
            self.write(&format!("for ({} = 0; {} < ", iter_var, iter_var));
            self.gen_verilog_expr(iterable);
            self.write(&format!("; {} = {} + 1)", iter_var, iter_var));
        } else {
            self.write(&format!("for ({0} = 0; {0} < 1; {0} = {0} + 1)", iter_var));
        }
        self.write_line(" begin");

        self.indent();
        if !node.children.is_empty() {
            for stmt in &node.children[body_idx].children {
                self.gen_verilog_stmt(stmt);
            }
        }
        self.dedent();
        self.write_indent();
        self.write_line("end");
    }

    fn gen_verilog_for_range_stmt(&mut self, node: &Node) {
        let var = Self::verilog_safe_identifier(&node.name);
        self.write_indent();
        if node.children.len() >= 2 {
            self.write(&format!("for ({var} = "));
            self.gen_verilog_expr(&node.children[0]);
            self.write(&format!("; {var} < "));
            self.gen_verilog_expr(&node.children[1]);
            self.write(&format!("; {var} = {var} + 1)"));
        }
        self.write_line(" begin");
        self.indent();
        if node.children.len() > 2 {
            for stmt in &node.children[2].children {
                self.gen_verilog_stmt(stmt);
            }
        }
        self.dedent();
        self.write_indent();
        self.write_line("end");
    }

    fn gen_verilog_expr(&mut self, node: &Node) {
        match node.kind {
            NodeKind::ExprLiteral => {
                let val = &node.value;
                // W458: string literals must escape newlines (and tabs / embedded
                // quotes) before they are written into a Verilog string literal,
                // otherwise Yosys emits "unterminated string" / "unknown escape
                // sequence" warnings.
                if node.extra_kind == "string" {
                    let escaped = val
                        .replace('\\', "\\\\")
                        .replace('\n', "\\n")
                        .replace('\t', "\\t")
                        .replace('"', "\\\"");
                    self.write(&format!("\"{}\"", escaped));
                    return;
                }
                // Render integer literals as plain decimal (valid Verilog).
                // Verilog rejects `0x..`/`0b..` and Rust-style `_` separators,
                // so parse the numeric value and print it in base 10.
                let clean: String = val.chars().filter(|&c| c != '_').collect();
                if let Some(hex) = clean.strip_prefix("0x").or_else(|| clean.strip_prefix("0X")) {
                    match u128::from_str_radix(hex, 16) {
                        Ok(n) => self.write(&n.to_string()),
                        Err(_) => self.write(val),
                    }
                } else if let Some(bin) = clean.strip_prefix("0b").or_else(|| clean.strip_prefix("0B")) {
                    match u128::from_str_radix(bin, 2) {
                        Ok(n) => self.write(&n.to_string()),
                        Err(_) => self.write(val),
                    }
                } else if val == "true" {
                    self.write("1'b1");
                } else if val == "false" {
                    self.write("1'b0");
                } else if !clean.is_empty() && clean.chars().all(|c| c.is_ascii_digit()) {
                    // Plain decimal, possibly with `_` separators — normalize.
                    self.write(&clean);
                } else {
                    self.write(val);
                }
            }
            NodeKind::ExprIdentifier => {
                // W458: if this identifier is a function parameter bound to a
                // module-level array, emit the module array name instead.
                if let Some(bindings) = self
                    .array_param_bindings
                    .get(&self.current_fn_name_original)
                {
                    if let Some(bound) = bindings.get(&node.name) {
                        self.write(&Self::verilog_safe_identifier(bound));
                    } else {
                        self.write(&Self::verilog_safe_identifier(&node.name));
                    }
                } else {
                    self.write(&Self::verilog_safe_identifier(&node.name));
                }
            }
            NodeKind::ExprEnumValue => {
                self.write(&Self::verilog_safe_identifier(&node.name));
            }
            NodeKind::ExprCall => {
                // W660: `default_input()` / `valid_input()` are TEMPLATE SCAFFOLD,
                // not functions. 571 generated tests are shaped
                //
                //     test f_basic_case
                //         given input = default_input()
                //         when result = f(input)
                //         then result != undefined
                //
                // and neither helper is defined anywhere. The Zig backend has
                // resolved them since W585 (see collect_scaffold_locals, which
                // recovers the type from the consumer's declared parameter and
                // emits `std.mem.zeroes(T)`). The VERILOG backend never did, so
                // every one of these specs died at
                //
                //     error: No function named `default_input' found
                //
                // Measured before this fix: 141 of the 444 specs that generate
                // Verilog carried a scaffold call -- 32% -- and it was the single
                // largest cause in a 60-spec sample, 15 of 46 failures.
                //
                // Verilog needs no type recovery: the binding is already declared
                // as a `reg` of the right width by the local emitter, so the zero
                // value is the literal 0 and the width follows the declaration.
                // The tests using these bindings assert only `result != undefined`,
                // so a defined default is exactly what they want.
                if matches!(node.name.as_str(), "default_input" | "valid_input")
                    && node.children.is_empty()
                {
                    self.write("0");
                    return;
                }

                // #2413(2): `.len()` on an array folds to its declared length.
                // The Rust backend has resolved this shape since 7172; Verilog
                // emitted the method call VERBATIM (`MAC_LUT.len(1'b0)`) and
                // iverilog rejected it: arrays have no methods in Verilog.
                // Three parse shapes reach here for the same source text:
                // method-kind (assert path), a call whose child is the
                // field-access `RECV.len` (given-binding path), and a call
                // carrying the qualified name itself.
                let len_receiver: Option<String> = if node.name == "len"
                    && node.extra_kind == "method"
                    && node.children.len() == 1
                    && node.children[0].kind == NodeKind::ExprIdentifier
                {
                    Some(node.children[0].name.clone())
                } else if node.name == "len"
                    && !node.children.is_empty()
                    && node.children[0].kind == NodeKind::ExprFieldAccess
                    && node.children[0].name == "len"
                    && node.children[0]
                        .children
                        .first()
                        .map(|b| b.kind == NodeKind::ExprIdentifier)
                        .unwrap_or(false)
                {
                    Some(node.children[0].children[0].name.clone())
                } else if let Some(base) = node.name.strip_suffix(".len") {
                    if !base.is_empty() && !base.contains('.') {
                        Some(base.to_string())
                    } else {
                        None
                    }
                } else {
                    None
                };
                if let Some(recv) = len_receiver {
                    let ty = self
                        .local_types
                        .get(&recv)
                        .or_else(|| self.param_types.get(&recv))
                        .or_else(|| self.module_types.get(&recv))
                        .cloned();
                    if let Some(ty) = ty {
                        if let Some((dims, _)) = Self::parse_array_type(&ty) {
                            let n: usize = dims.iter().product();
                            self.write(&n.to_string());
                            return;
                        }
                    }
                }


                // W663: Zig builtins must not reach Verilog.
                //
                // `CCodegen` has handled these since its own wave (see the
                // `@compileAssert` / `@setEvalBranchQuota` arms around line
                // 14520); the Verilog backend never did, and emitted them raw:
                //
                //     @setEvalBranchQuota(10000);
                //     base = @as(f64, @floatFromInt(timing[0 +: 64]));
                //
                // Measured across the 444 specs that generate Verilog: 21 carry
                // a leaked builtin, 12 of them carry ONLY the quota hint. By
                // occurrence: @setEvalBranchQuota 83, @as 27, @floatFromInt 18,
                // @intFromEnum 14, @enumFromInt 5, @intFromFloat 4, @intCast 4.
                //
                // Two shapes, both mechanical:
                //   * a comptime HINT with no runtime meaning -> a comment, as
                //     the C backend already does;
                //   * an identity-shaped CONVERSION -> its value operand, since
                //     Verilog is untyped at this level and the conversion is a
                //     no-op once the width is fixed by the declaration.
                //
                // Anything else `@`-prefixed is left alone deliberately: it will
                // still fail loudly rather than be silently mistranslated.
                if node.name.starts_with('@') {
                    match node.name.as_str() {
                        // Comptime hint: no value, no runtime effect.
                        "@setEvalBranchQuota" => {
                            self.write("/* ");
                            self.write(&node.name);
                            self.write(" */");
                            return;
                        }
                        // `@as(T, x)` -- the value is the SECOND operand.
                        "@as" if node.children.len() == 2 => {
                            self.gen_verilog_expr(&node.children[1]);
                            return;
                        }
                        // Identity-shaped conversions: pass the value through.
                        "@intCast" | "@intFromEnum" | "@enumFromInt" | "@intFromFloat"
                        | "@floatFromInt" | "@truncate" | "@bitCast"
                            if node.children.len() == 1 =>
                        {
                            self.gen_verilog_expr(&node.children[0]);
                            return;
                        }
                        _ => {}
                    }
                }

                // W557: inside test/bench blocks, reference a pre-declared temporary
                // for pure calls instead of re-invoking them. The temporary was
                // assigned earlier in the block by materialize_call_array_tmp.
                if self.use_call_array_temps && !self.call_array_tmp_names.is_empty() {
                    let mut call_text = String::new();
                    self.collect_expr_text(node, &mut call_text);
                    if let Some(tmp_name) = self.call_array_tmp_names.get(&call_text).cloned() {
                        self.write(&tmp_name);
                        return;
                    }
                }
                // The declaration at gen_verilog_fn already escapes keyword names; the call
                // site must match, or `function \assume ;` is declared and `assume(...)`
                // is called -- two different identifiers. formal.v:187.
                // W664: a namespaced path in CALL position -- `TernaryWeight::minus(x)`
                // -- reaches here as the call's name and never passes through
                // `verilog_safe_identifier`, so the `::` substitution applied
                // there missed it. Two specs, eleven sites, after the identifier
                // path fixed twenty-one specs.
                self.write(&Self::verilog_safe_identifier(&node.name));
                self.write("(");
                // W458: drop module-level array arguments from the emitted
                // Verilog argument list. The function body references the bound
                // module array by name directly, so the array value is not passed
                // through a scalar input port.
                let skip_indices = self
                    .array_param_indices
                    .get(&node.name)
                    .cloned()
                    .unwrap_or_default();
                let mut first = true;
                for (i, arg) in node.children.iter().enumerate() {
                    if skip_indices.contains(&i) {
                        continue;
                    }
                    if !first {
                        self.write(", ");
                    }
                    first = false;
                    self.gen_verilog_expr(arg);
                }
                // W530: zero-argument functions are emitted with a dummy `_unused`
                // input by gen_verilog_fn, so Icarus Verilog needs a placeholder
                // argument at call sites.
                if node.children.is_empty() {
                    self.write("1'b0");
                }
                self.write(")");
            }
            NodeKind::ExprBinary => {
                if node.children.len() >= 2 {
                    // R-SI-1: Multiplication must not appear as `*` operator in
                    // synthesizable RTL. Emit `__mul_noop(a, b)` instead — the
                    // function definition is injected once per module preamble.
                    if matches!(node.extra_op.as_str(), "*" | "*%") {
                        self.write("__mul_noop(");
                        self.gen_verilog_expr(&node.children[0]);
                        self.write(", ");
                        self.gen_verilog_expr(&node.children[1]);
                        self.write(")");
                    } else {
                        // Map operators. Wrapping operators (+% -%) collapse to the
                        // plain operator: Verilog arithmetic already wraps by width.
                        let op = match node.extra_op.as_str() {
                            "&&" | "and" => "&&",
                            "||" | "or" => "||",
                            "==" => "==",
                            "!=" => "!=",
                            ">=" => ">=",
                            "<=" => "<=",
                            ">" => ">",
                            "<" => "<",
                            "+" | "+%" => "+",
                            "-" | "-%" => "-",
                            "/" => "/",
                            "%" => "%",
                            "&" => "&",
                            "|" => "|",
                            "^" => "^",
                            "<<" => "<<",
                            ">>" => ">>",
                            other => other,
                        };
                        // W565: signed-aware ordered comparison. Verilog makes an
                        // ordered comparison UNSIGNED if either operand is unsigned,
                        // so a signed i8 (e.g. trend = -16 = 8'hF0) meeting an
                        // unsigned const reads as 240 and the test diverges from
                        // Rust/Zig/C (which promote both to a signed int). When at
                        // least one operand is signed, compare in the signed domain
                        // with C-promotion semantics: the signed operand is wrapped
                        // in $signed() (Verilog sign-extends it into the wider signed
                        // context) and the unsigned operand is zero-extended one bit,
                        // $signed({1'b0, x}), so it stays non-negative.
                        // W-27: a RIGHT SHIFT of a signed value needs `>>>`.
                        // Verilog's `>>` fills with zeros whatever the operand
                        // is declared, and the repair below fires only on
                        // ordered relations, so no shift was ever fixed up. On
                        // `specs/igla/race/cordic_fixed.t27:42`, `x - (y >> shift)`
                        // with x=100, y=-64, shift=2 simulates to -16268 where
                        // the spec, C and Zig all say 116: y = 16'hFFC0 = 65472,
                        // 65472 >> 2 = 16368, 100 - 16368 = -16268.
                        //
                        // This project's own hand-written golden CORDIC RTL
                        // writes `y0 >>> 1` for the identical rotation, so the
                        // right operator was known and the expression path
                        // emitted it zero times across 559 generated modules.
                        let shift_signed = node.extra_op == ">>"
                            && matches!(
                                self.expr_width_signed(&node.children[0]),
                                Some((_, true))
                            );
                        let op = if shift_signed { ">>>" } else { op };
                        let ordered_rel = matches!(op, "<" | "<=" | ">" | ">=");
                        let rel_signed = ordered_rel
                            && match (
                                self.expr_width_signed(&node.children[0]),
                                self.expr_width_signed(&node.children[1]),
                            ) {
                                (Some((_, ls)), Some((_, rs))) => ls || rs,
                                _ => false,
                            };
                        if rel_signed {
                            let (_, ls) = self
                                .expr_width_signed(&node.children[0])
                                .unwrap_or((0, false));
                            let (_, rs) = self
                                .expr_width_signed(&node.children[1])
                                .unwrap_or((0, false));
                            self.write("(");
                            self.emit_verilog_signed_rel_operand(&node.children[0], ls);
                            self.write(&format!(" {} ", op));
                            self.emit_verilog_signed_rel_operand(&node.children[1], rs);
                            self.write(")");
                        } else {
                            self.write("(");
                            self.gen_verilog_expr(&node.children[0]);
                            self.write(&format!(" {} ", op));
                            self.gen_verilog_expr(&node.children[1]);
                            self.write(")");
                        }
                    }
                }
            }
            NodeKind::ExprUnary => {
                let op = match node.extra_op.as_str() {
                    "!" | "not" => "!",
                    "-" => "-",
                    "~" => "~",
                    other => other,
                };
                self.write(op);
                if !node.children.is_empty() {
                    self.gen_verilog_expr(&node.children[0]);
                }
            }
            NodeKind::ExprFieldAccess => {
                if !node.children.is_empty() {
                    // W527: packed array-of-struct field access (e.g. m[i][j].x).
                    if self.try_emit_struct_array_access(&node.children[0], Some(&node.name)) {
                        return;
                    }
                    let child = &node.children[0];
                    // #2240: NESTED scalar-struct field access (e.g. state.flags.empty).
                    // The single-level branch below matches only identifier/index/call
                    // bases, so a field-access base fell through to name-flattening and
                    // emitted `state[96 +: 4]_empty` -- an identifier fragment glued onto
                    // a part-select, invalid Verilog (fifo.v, 6 sites). Resolve the whole
                    // chain to ONE cumulative part-select on the base identifier.
                    if child.kind == NodeKind::ExprFieldAccess {
                        let mut names = vec![node.name.clone()];
                        let mut cur = child;
                        while cur.kind == NodeKind::ExprFieldAccess && !cur.children.is_empty() {
                            names.push(cur.name.clone());
                            cur = &cur.children[0];
                        }
                        if cur.kind == NodeKind::ExprIdentifier {
                            names.reverse();
                            let chain_base = cur.name.clone();
                            if let Some(local_ty) = self.local_types
                                .get(&chain_base)
                                .or_else(|| self.param_types.get(&chain_base))
                                .or_else(|| self.module_types.get(&chain_base))
                            {
                                if self.is_lowerable_scalar_struct_type(local_ty)
                                    && Self::parse_array_type(local_ty).is_none()
                                {
                                    let mut cur_ty = Self::base_type_name(local_ty);
                                    let mut total_off = 0u32;
                                    let mut fw = 0u32;
                                    let mut ftype = String::new();
                                    let mut ok = true;
                                    for fname in &names {
                                        match self.struct_field_offset(&cur_ty, fname) {
                                            Some((off, w)) => {
                                                total_off += off;
                                                fw = w;
                                                ftype = self.struct_decls.get(&cur_ty)
                                                    .and_then(|fs| {
                                                        fs.iter()
                                                            .find(|(n, _)| n == fname)
                                                            .map(|(_, t)| t.clone())
                                                    })
                                                    .unwrap_or_default();
                                                cur_ty = Self::base_type_name(&ftype);
                                            }
                                            None => { ok = false; break; }
                                        }
                                    }
                                    if ok && fw > 0 {
                                        let signed = Self::scalar_field_is_signed(&ftype);
                                        let slice = format!("{}[{} +: {}]", Self::verilog_safe_identifier(&chain_base), total_off, fw);
                                        if signed && !self.in_lvalue {
                                            self.write(&format!("$signed({})", slice));
                                        } else {
                                            self.write(&slice);
                                        }
                                        return;
                                    }
                                }
                            }
                        }
                    }
                    // W533: packed single scalar-struct field access (e.g. p.x).
                    let base_name = match child.kind {
                        NodeKind::ExprIdentifier => child.name.clone(),
                        NodeKind::ExprIndex if !child.children.is_empty() => {
                            match child.children[0].kind {
                                NodeKind::ExprIdentifier => child.children[0].name.clone(),
                                _ => String::new(),
                            }
                        }
                        _ => String::new(),
                    };
                    if !base_name.is_empty() {
                        if let Some(local_ty) = self.local_types
                            .get(&base_name)
                            .or_else(|| self.param_types.get(&base_name))
                            .or_else(|| self.module_types.get(&base_name))
                        {
                            let base_ty = Self::base_type_name(local_ty);
                            if self.is_lowerable_scalar_struct_type(local_ty)
                                && Self::parse_array_type(local_ty).is_none()
                            {
                                if let Some((off, fw)) =
                                    self.struct_field_offset(&base_ty, &node.name)
                                {
                                    let ftype = self.struct_decls.get(&base_ty)
                                        .and_then(|fs| {
                                            fs.iter()
                                                .find(|(n, _)| n == &node.name)
                                                .map(|(_, t)| t.clone())
                                        })
                                        .unwrap_or_default();
                                    let signed = Self::scalar_field_is_signed(&ftype);
                                    let slice = format!("{}[{} +: {}]", Self::verilog_safe_identifier(&base_name), off, fw);
                                    if signed && !self.in_lvalue {
                                        self.write(&format!("$signed({})", slice));
                                    } else {
                                        self.write(&slice);
                                    }
                                    return;
                                }
                            }
                        }
                    }
                    // W533: packed scalar-struct field access on a function-call
                    // result (e.g. make().x).
                    if child.kind == NodeKind::ExprCall && !child.name.is_empty() {
                        if let Some(ret_ty) = self.fn_return_types.get(&child.name) {
                            let base_ty = Self::base_type_name(ret_ty);
                            if self.is_lowerable_scalar_struct_type(ret_ty)
                                && Self::parse_array_type(ret_ty).is_none()
                            {
                                if let Some((off, fw)) =
                                    self.struct_field_offset(&base_ty, &node.name)
                                {
                                    let ftype = self.struct_decls.get(&base_ty)
                                        .and_then(|fs| {
                                            fs.iter()
                                                .find(|(n, _)| n == &node.name)
                                                .map(|(_, t)| t.clone())
                                        })
                                        .unwrap_or_default();
                                    let signed = Self::scalar_field_is_signed(&ftype);
                                    let mut call_key = String::new();
                                    self.collect_expr_text(child, &mut call_key);
                                    // W560: if a call temporary has been pre-declared
                                    // for this scalar-struct return, slice the temporary
                                    // instead of re-invoking the function.
                                    let (base_expr, needs_parens) =
                                        if self.use_call_array_temps
                                            && !self.call_array_tmp_names.is_empty()
                                        {
                                            if let Some(tmp_name) =
                                                self.call_array_tmp_names.get(&call_key).cloned()
                                            {
                                                // W560: slice the pre-declared temporary
                                                // directly; parentheses are unnecessary and
                                                // some simulators reject them around a part-
                                                // select of a temporary identifier.
                                                (tmp_name, false)
                                            } else {
                                                (call_key, true)
                                            }
                                        } else {
                                            (call_key, true)
                                        };
                                    let slice = if needs_parens {
                                        format!("({})[{} +: {}]", base_expr, off, fw)
                                    } else {
                                        format!("{}[{} +: {}]", base_expr, off, fw)
                                    };
                                    if signed && !self.in_lvalue {
                                        self.write(&format!("$signed({})", slice));
                                    } else {
                                        self.write(&slice);
                                    }
                                    return;
                                }
                            }
                        }
                    }

                    // W659: FLATTEN FIRST, ESCAPE LAST.  An escaped Verilog
                    // identifier is `\name<space>` and the trailing space is
                    // part of the token -- so escaping a PREFIX and then
                    // concatenating a suffix puts that space in the middle of
                    // the name.  A field access on a parameter called `cross`
                    // (a SystemVerilog keyword) emitted
                    //     \cross _data_width
                    // which iverilog reads as the identifier `\cross` followed
                    // by a stray `_data_width`: "Malformed statement".
                    //
                    // The flattened name is what actually appears in the
                    // netlist, so it is the only string whose keyword-ness
                    // matters -- and `cross_data_width` is not a keyword, so
                    // the correct output carries no escape at all.
                    //
                    // Measured before the fix: 87 broken escapes across 13 of
                    // 617 specs, `systolic_ternary.t27` among them.
                    // #2325: `outer.arr[i].f1.f2...` -- fields of an element of a
                    // struct's ARRAY field -- resolved the base to nothing and
                    // flattened to `_f2`, a name with an empty base that can never
                    // bind (memory.v `_kind`, hir.v `_name`).
                    //
                    // The chain must be resolved WHOLE. A first version handled
                    // exactly one trailing field and emitted `cat[...]_luts` for a
                    // two-field tail: a part-select with an identifier glued to it,
                    // which is the #2240 defect in a new place. yosys caught it as a
                    // syntax error in stdlib.v within one smoke run.
                    {
                        let mut tail: Vec<String> = vec![node.name.clone()];
                        let mut cur = child;
                        while cur.kind == NodeKind::ExprFieldAccess && !cur.children.is_empty() {
                            tail.push(cur.name.clone());
                            cur = &cur.children[0];
                        }
                        tail.reverse();
                        if cur.kind == NodeKind::ExprIndex
                            && cur.children.len() >= 2
                            && cur.children[0].kind == NodeKind::ExprFieldAccess
                            && cur.children[0]
                                .children
                                .first()
                                .map(|b| b.kind == NodeKind::ExprIdentifier)
                                .unwrap_or(false)
                        {
                            let outer = cur.children[0].children[0].name.clone();
                            let arr_field = cur.children[0].name.clone();
                            if let Some(outer_ty) = self
                                .local_types
                                .get(&outer)
                                .or_else(|| self.param_types.get(&outer))
                                .or_else(|| self.module_types.get(&outer))
                                .cloned()
                            {
                                let outer_base = Self::base_type_name(&outer_ty);
                                let arr_ty = self
                                    .struct_decls
                                    .get(&outer_base)
                                    .and_then(|fs| {
                                        fs.iter()
                                            .find(|(n, _)| n == &arr_field)
                                            .map(|(_, t)| t.clone())
                                    })
                                    .unwrap_or_default();
                                if let (Some((arr_off, _)), Some((_, elem_ty))) = (
                                    self.struct_field_offset(&outer_base, &arr_field),
                                    Self::parse_array_type(&arr_ty),
                                ) {
                                    let elem_w = self.field_type_width(&elem_ty, 0);
                                    let mut ty = Self::base_type_name(&elem_ty);
                                    let mut off = 0u32;
                                    let mut w = 0u32;
                                    let mut ok = elem_w > 0;
                                    for f in &tail {
                                        match self.struct_field_offset(&ty, f) {
                                            Some((o, fw)) => {
                                                off += o;
                                                w = fw;
                                                ty = self
                                                    .struct_decls
                                                    .get(&ty)
                                                    .and_then(|fs| {
                                                        fs.iter()
                                                            .find(|(n, _)| n == f)
                                                            .map(|(_, t)| {
                                                                Self::base_type_name(t)
                                                            })
                                                    })
                                                    .unwrap_or_default();
                                            }
                                            None => {
                                                ok = false;
                                                break;
                                            }
                                        }
                                    }
                                    if ok && w > 0 {
                                        let mut idx = String::new();
                                        self.collect_expr_text(&cur.children[1], &mut idx);
                                        let base_id = Self::verilog_safe_identifier(&outer);
                                        self.write(&format!(
                                            "{}[({} + (({}) * {}) + {}) +: {}]",
                                            base_id, arr_off, idx, elem_w, off, w
                                        ));
                                        return;
                                    }
                                }
                            }
                        }
                    }
                    if child.kind == NodeKind::ExprIndex && !child.children.is_empty() {
                        let base_name = match child.children[0].kind {
                            NodeKind::ExprIdentifier => {
                                // Escape AFTER flattening, not before: escaping the base first produced
                                // `\cross _data_width` -- the space that terminates an escaped identifier
                                // split the flattened name in two. clock_domain.v:221.
                                child.children[0].name.clone()
                            }
                            _ => String::new(),
                        };
                        let flat_name = format!("{}_{}", base_name, node.name);
                        self.write(&Self::verilog_safe_identifier(&flat_name));
                    } else if child.kind == NodeKind::ExprIdentifier {
                        let flat_name = format!("{}_{}", child.name, node.name);
                        self.write(&Self::verilog_safe_identifier(&flat_name));
                        // (escape applied to the flattened name; see comment above)
                    } else {
                        self.gen_verilog_expr(child);
                        self.write("_");
                        self.write(&node.name);
                    }
                } else {
                    self.write(&Self::verilog_safe_identifier(&node.name));
                }
            }
            NodeKind::ExprIndex => {
                if node.children.len() >= 2 {
                    // W532: packed scalar-struct field-with-index access
                    // (e.g. p.data[k] or grid[i][j].data[k]).
                    if self.try_emit_struct_array_field_element_access(node) {
                        return;
                    }
                    // W527: packed array-of-struct element access (e.g. m[i][j]).
                    if self.try_emit_struct_array_access(node, None) {
                        return;
                    }
                    // W531: packed primitive array element access (e.g. temps[i]).
                    if self.try_emit_primitive_array_access(node) {
                        return;
                    }
                    let base = &node.children[0];
                    let idx = &node.children[1];
                    // W383: function-local arrays are emitted as per-element regs
                    // (tmp_0, tmp_1, ...). If the index is a numeric literal, rewrite
                    // the access to the flattened reg name so it synthesizes inside a
                    // Verilog function. Restored from Wave Loop 458.
                    if base.kind == NodeKind::ExprIdentifier {
                        let safe_base = Self::verilog_safe_identifier(&base.name);
                        if self.local_arrays.contains(&safe_base) {
                            if let Ok(idx_val) = idx.value.parse::<usize>() {
                                let flat_name = format!("{}_{}", base.name, idx_val);
                                self.write(&Self::verilog_safe_identifier(&flat_name));
                                return;
                            }
                        }
                    }
                    self.gen_verilog_expr(base);
                    self.write("[");
                    self.gen_verilog_expr(idx);
                    self.write("]");
                }
            }
            NodeKind::ExprArrayLiteral => {
                // W544/W555/W564: fixed-size scalar array literals in expression
                // context (e.g. function return values and assert_eq expected
                // values) lower to a packed concatenation when the element type is
                // a primitive scalar or a lowerable packed scalar struct.
                // Multi-dimensional literals are handled by splitting extra_size
                // on "][".
                let elem = node.extra_type.trim();
                let dims: Vec<usize> = node.extra_size.split("][")
                    .filter_map(|s| s.parse().ok())
                    .collect();
                let dims_count = node.extra_size.split("][").count();
                if !dims.is_empty()
                    && dims.len() == dims_count
                    && (Self::is_primitive_scalar_type(elem)
                        || self.is_lowerable_scalar_struct_type(elem))
                {
                    let ty = format!("[{}]{}", node.extra_size, elem);
                    self.emit_packed_array_literal_concat(node, &ty);
                } else {
                    self.write(&format!(
                        "0 /* TODO: array literal [{}]{} not yet lowered to Verilog */",
                        node.extra_size, node.extra_type
                    ));
                }
            }
            NodeKind::ExprTuple => {
                // Tuple literal -> packed concatenation with element 0 in the
                // LSB: `(e0, e1)` -> `{e1, e0}`. Matches the packed_width sum and
                // the destructuring slice order. Each element is WIDTH-CAST to
                // its declared type: a bare literal (`return (1, true)`) is
                // unsized in Verilog and iverilog rejects it in a concatenation
                // ("operand has indefinite width", t27#1948).
                let elem_types: Option<Vec<String>> = {
                    let t = self.current_fn_return_type.trim();
                    if t.starts_with('(') && t.ends_with(')') && t.contains(',') {
                        Some(
                            t[1..t.len() - 1]
                                .split(',')
                                .map(|e| e.trim().to_string())
                                .collect(),
                        )
                    } else {
                        None
                    }
                };
                self.write("{");
                let last = node.children.len().saturating_sub(1);
                for (i, child) in node.children.iter().enumerate().rev() {
                    if i != last {
                        self.write(", ");
                    }
                    // LHS `_` discard: reference the throwaway reg declared for
                    // this (line, index) position (t27#1948).
                    if self.in_lvalue
                        && child.kind == NodeKind::ExprIdentifier
                        && child.name == "_"
                    {
                        self.write(&format!("__t27_disc_{}_{}", node.line, i));
                        continue;
                    }
                    let cast = elem_types
                        .as_ref()
                        .filter(|ts| ts.len() == node.children.len())
                        .map(|ts| {
                            let ty = ts[i].trim();
                            (self.packed_width(ty).max(1), self.packed_signed(ty))
                        });
                    if let Some((w, signed)) = cast {
                        let v = self.emit_packed_scalar_value(child, w, signed);
                        self.write(&v);
                    } else {
                        self.gen_verilog_expr(child);
                    }
                }
                self.write("}");
            }
            NodeKind::ExprStructLit => {
                // W527/W532: scalar struct literals lower to a concatenation of
                // their field values in reverse declaration order (last field
                // becomes MSB), matching the packed-vector AoS layout used for
                // arrays. Fixed-size scalar-array fields are rendered as nested
                // concatenations of their elements.
                if let Some(fields) = self.struct_decls.get(&node.name) {
                    let all_scalar = !fields.is_empty()
                        && fields.iter().all(|(_, ft)| {
                            let trimmed = ft.trim();
                            let base = if let Some(close) = trimmed.find(']') {
                                trimmed[close + 1..].trim()
                            } else {
                                trimmed
                            };
                            Self::is_primitive_scalar_type(base)
                        });
                    if all_scalar {
                        let mut parts = Vec::new();
                        for (fname, ftype) in fields.iter().rev() {
                            let child = node.children.iter().find(|c| {
                                c.kind == NodeKind::ExprFieldAccess
                                    && c.name == *fname
                                    && !c.children.is_empty()
                            });
                            if let Some(c) = child {
                                let val = &c.children[0];
                                parts.push(
                                    self.emit_packed_struct_field_value(val, ftype),
                                );
                            } else {
                                let fwidth = Self::scalar_field_width(ftype);
                                parts.push(format!("{}'d0", fwidth));
                            }
                        }
                        self.write(&format!("{{{}}}", parts.join(", ")));
                        return;
                    }
                }
                // Fallback for non-scalar structs.
                self.write(&format!("0 /* {} {{...}} */", node.name));
            }
            NodeKind::ExprSwitch => {
                // Emit as nested ternary: (expr == val1) ? res1 : (expr == val2) ? res2 : default
                let cases = &node.children[1..];
                if cases.is_empty() {
                    self.write("0 /* empty switch */");
                } else {
                    let last_idx = cases.len() - 1;
                    for (i, case) in cases.iter().enumerate() {
                        if case.kind == NodeKind::ConstDecl {
                            let is_else = case.name.is_empty() || case.name == "else";
                            let is_last = i == last_idx;

                            if is_else {
                                if !case.children.is_empty() {
                                    self.gen_verilog_expr(&case.children[0]);
                                } else {
                                    self.write("0");
                                }
                            } else {
                                self.write("(");
                                self.gen_verilog_expr(&node.children[0]);
                                self.write(" == ");
                                let is_numeric =
                                    case.name.starts_with(|c: char| c.is_ascii_digit())
                                        || (case.name.starts_with('-') && case.name.len() > 1);
                                if is_numeric {
                                    self.write(&case.name);
                                } else {
                                    self.write(&case.name);
                                }
                                self.write(") ? (");
                                if !case.children.is_empty() {
                                    self.gen_verilog_expr(&case.children[0]);
                                } else {
                                    self.write("0");
                                }
                                self.write(")");

                                if !is_last {
                                    self.write(" : ");
                                } else {
                                    self.write(" : 0");
                                }
                            }
                        }
                    }
                }
            }
            NodeKind::ExprIf => {
                // Ternary operator
                self.write("(");
                if !node.children.is_empty() {
                    self.gen_verilog_expr(&node.children[0]);
                }
                self.write(") ? (");
                if node.children.len() > 1 {
                    self.gen_verilog_expr(&node.children[1]);
                }
                self.write(") : (");
                if node.children.len() > 2 {
                    self.gen_verilog_expr(&node.children[2]);
                } else {
                    self.write("0");
                }
                self.write(")");
            }
            NodeKind::ExprCast => {
                // Width-correct cast lowering. `extra_type` holds the target type
                // (possibly with a trailing `[N]` array suffix). We derive the
                // target bit width and signedness and emit a Verilog form that is
                // valid regardless of the operand's source width:
                //   * signed target -> `$signed(op)` so the value sign-extends
                //     when it feeds a wider expression context;
                //   * unsigned scalar target of width W < 64 -> `(op & {W{1'b1}})`
                //     which truncates a wider operand to exactly W bits.  When the
                //     operand is signed and narrower than W, emit an explicit
                //     W-bit concatenation `({(W-N){($signed(op) < 0)}}, op)` that
                //     sign-extends without relying on Icarus' mixed signed/unsigned
                //     expression-context semantics;
                //   * 64-bit / array / unknown -> emit the operand verbatim.
                if node.children.is_empty() {
                    return;
                }
                let base_ty = node
                    .extra_type
                    .split('[')
                    .next()
                    .unwrap_or("")
                    .to_string();
                let signed = Self::type_is_signed(&base_ty);
                let width = Self::type_to_width(&base_ty) as usize;
                let is_array = node.extra_type.contains('[');
                // Infer the operand's scalar width/signedness so we can decide
                // whether to emit a mask, sign-extend, or skip the mask for a
                // widening unsigned cast.
                let operand = &node.children[0];
                let operand_ws = self.expr_width_signed(operand);
                let operand_signed = operand_ws.map(|(_, s)| s).unwrap_or(false);
                let operand_width = operand_ws.map(|(w, _)| w as usize);
                let is_widening_unsigned =
                    operand_width.map(|ow| ow <= width).unwrap_or(false) && !operand_signed;
                let needs_sign_ext =
                    operand_signed && operand_width.map(|ow| ow < width).unwrap_or(false);
                if signed {
                    self.write("$signed(");
                    self.gen_verilog_expr(operand);
                    self.write(")");
                } else if !is_array && width >= 1 && width < 64 && !is_widening_unsigned {
                    if needs_sign_ext {
                        let ext = width - operand_width.unwrap();
                        // Explicit sign-extension: replicate the sign bit (computed
                        // via comparison so it works for any operand expression)
                        // and concatenate with the original operand.
                        self.write("({{");
                        self.write(&ext.to_string());
                        self.write("{($signed(");
                        self.gen_verilog_expr(operand);
                        self.write(") < 0)}}, ");
                        self.gen_verilog_expr(operand);
                        self.write("})");
                    } else {
                        self.write("(");
                        self.gen_verilog_expr(operand);
                        self.write(&format!(" & {{{}{{1'b1}}}})", width));
                    }
                } else {
                    self.gen_verilog_expr(operand);
                }
            }
            _ => {
                self.write(&format!("/* unsupported expr: {:?} */", node.kind));
            }
        }
    }
}

// ============================================================================
// C Code Generator
// ============================================================================

pub struct CCodegen {
    output: String,
    indent: u32,
    module_name: String,
    /// Function name -> t27 return type, used to resolve tuple element types at
    /// a `let (a, b) = call()` destructuring site.
    fn_return_types: std::collections::HashMap<String, String>,
    /// t27 tuple return type of the function currently being emitted, so an
    /// `ExprTuple` in a `return` can be cast to the right C compound-literal type.
    current_ret_tuple_type: Option<String>,
    /// C struct typedef name of the current function's [T; N] return type,
    /// so a returned array literal can be cast to the right compound literal.
    current_ret_array_type: Option<String>,
    /// Identifiers (params + locals) of [T; N] struct type in the item being
    /// emitted: indexing them must go through the .v member.
    array_typed_names: std::collections::HashSet<String>,
    /// Module const name -> literal value text, used to canonicalize [T; N]
    /// sizes ([u32; MAX_METRICS] and [u32; 16] must be the SAME struct type;
    /// C typing is nominal).
    const_defs: std::collections::HashMap<String, String>,
    local_tuple_counter: u32,
}

impl CCodegen {
    pub fn new() -> Self {
        Self {
            output: String::new(),
            indent: 0,
            module_name: String::new(),
            fn_return_types: std::collections::HashMap::new(),
            current_ret_tuple_type: None,
            current_ret_array_type: None,
            array_typed_names: std::collections::HashSet::new(),
            const_defs: std::collections::HashMap::new(),
            local_tuple_counter: 0,
        }
    }

    /// Map a t27 array type `[T; N]` to (typedef name, element C type, size
    /// text). C cannot return arrays by value, so [T; N] lowers uniformly to
    /// a by-value struct `typedef struct { T v[N]; } t27_arr_T_N;` -- params,
    /// returns, locals, literals and indexing all move together (t27#1944).
    fn c_array_info(ty: &str) -> Option<(String, String, String)> {
        let t = ty.trim();
        if !t.starts_with('[') || !t.contains(';') {
            return None;
        }
        let bracket_end = t.rfind(']')?;
        if bracket_end <= 1 {
            return None;
        }
        let inner = &t[1..bracket_end];
        // W584: split on the semicolon at bracket depth ZERO. `find(';')` took
        // the first one, so a NESTED array `[[u8; 16]; 16]` split as
        // elem=`[u8` / size=`16]; 16` and the typedef came out as
        // `typedef struct { [u8 v[16];16]; } ...` -- not C. 70 headers.
        let mut depth = 0i32;
        let mut semi = None;
        for (i, ch) in inner.char_indices() {
            match ch {
                '[' | '(' => depth += 1,
                ']' | ')' => depth -= 1,
                ';' if depth == 0 => {
                    semi = Some(i);
                    break;
                }
                _ => {}
            }
        }
        let semi = semi?;
        let elem = inner[..semi].trim();
        let size = inner[semi + 1..].trim();
        if elem.is_empty() || size.is_empty() {
            return None;
        }
        let c_elem = if Self::is_primitive(elem) {
            Self::type_to_c(elem).to_string()
        } else if let Some((inner_name, _, _)) = Self::c_array_info(elem) {
            // An array OF arrays: the element is the inner array's hoisted
            // struct, not its t27 spelling.
            inner_name
        } else {
            Self::type_to_c(elem).to_string()
        };
        let sane = |x: &str| x.replace(|c: char| !c.is_alphanumeric(), "_");
        let name = format!("t27_arr_{}_{}", sane(&c_elem), sane(size));
        Some((name, c_elem, size.to_string()))
    }

    /// Const-resolving wrapper: canonicalizes the size (a const name resolves
    /// to its numeric value) so nominally-equal array types share one struct.
    fn c_array_info_r(&self, ty: &str) -> Option<(String, String, String)> {
        let (_, elem, size) = Self::c_array_info(ty)?;
        let resolved = self
            .const_defs
            .get(size.trim())
            .cloned()
            .unwrap_or_else(|| size.clone());
        let sane = |x: &str| x.replace(|c: char| !c.is_alphanumeric(), "_");
        let name = format!("t27_arr_{}_{}", sane(&elem), sane(resolved.trim()));
        Some((name, elem, resolved))
    }

    fn param_type_to_c_r(&self, ty: &str) -> String {
        if let Some((name, _, _)) = self.c_array_info_r(ty) {
            return name;
        }
        Self::param_type_to_c(ty)
    }

    fn c_return_type_r(&self, ty: &str) -> String {
        if let Some((name, _)) = Self::c_tuple_info(ty) {
            name
        } else {
            self.param_type_to_c_r(ty)
        }
    }

    /// Map a t27 tuple type `(T, U, ...)` to a deterministic C typedef name and
    /// its element C types. Returns None for non-tuple types.
    fn c_tuple_info(ty: &str) -> Option<(String, Vec<String>)> {
        let t = ty.trim();
        if t.starts_with('(') && t.ends_with(')') && t.contains(',') {
            let inner = &t[1..t.len() - 1];
            // W584: a NAMED tuple element -- `(added: u32, deleted: u32)`. The
            // whole `added: u32` was taken as the type, so C received
            // `typedef struct { added:u32 f0; ... }`. The name is
            // documentation; only the type crosses into C.
            let elems: Vec<String> = inner
                .split(',')
                .map(|e| {
                    let e = e.trim();
                    // W585: the colon must NOT be part of a `::` scope path.
                    // W584's name-stripping split `gf16::GF16` at the first
                    // colon, took `gf16` for a field name, and emitted
                    // `typedef struct { :GF16 f0; ... }`. Found by the C gate
                    // built in this wave, one wave after the fix that caused it.
                    let ty = match e.split_once(':') {
                        Some((name, rest))
                            if !name.trim().is_empty()
                                && !rest.starts_with(':')
                                && name
                                    .trim()
                                    .chars()
                                    .all(|c| c.is_alphanumeric() || c == '_') =>
                        {
                            rest.trim()
                        }
                        _ => e,
                    };
                    Self::param_type_to_c(ty)
                })
                .collect();
            let sanitized: String = elems
                .iter()
                .map(|c| {
                    c.chars()
                        .map(|ch| if ch.is_alphanumeric() { ch } else { '_' })
                        .collect::<String>()
                })
                .collect::<Vec<_>>()
                .join("_");
            Some((format!("t27_tuple_{}", sanitized), elems))
        } else {
            None
        }
    }

    fn write(&mut self, s: &str) {
        self.output.push_str(s);
    }

    fn write_line(&mut self, s: &str) {
        self.write(s);
        self.write("\n");
    }

    fn indent(&mut self) {
        self.indent += 1;
    }

    fn dedent(&mut self) {
        if self.indent > 0 {
            self.indent -= 1;
        }
    }

    fn write_indent(&mut self) {
        for _ in 0..self.indent {
            self.write("    ");
        }
    }

    pub fn into_string(self) -> String {
        self.output
    }

    /// Map t27 type to C type string
    fn type_to_c(ty: &str) -> &str {
        match ty {
            "bool" => "bool",
            "u8" => "uint8_t",
            "i8" => "int8_t",
            "u16" => "uint16_t",
            "i16" => "int16_t",
            "u32" => "uint32_t",
            "i32" => "int32_t",
            "u64" => "uint64_t",
            "i64" => "int64_t",
            "usize" => "size_t",
            "void" => "void",
            // W583: floats and strings were simply absent from this match, so
            // they took the pass-through arm and reached C as `f32 x;` and
            // `str name;`. Compiling the generated headers for the first time
            // reported 46 `unknown type name 'f32'`, 34 `f64`, 29 `str` and 9
            // `string`.
            "f32" => "float",
            "f64" => "double",
            "str" | "string" => "const char*",
            "GF16" | "gf16" => "uint16_t",
            "isize" => "ptrdiff_t",
            "u128" => "unsigned __int128",
            "i128" => "__int128",
            "char" => "char",
            // W585: a scoped type name (`gf16::GF16`) is not a C identifier.
            // C has no namespaces, and the generated header flattens every
            // module into one scope, so the separator becomes an underscore.
            _ if ty.contains("::") => Box::leak(
                ty.replace("::", "_").into_boxed_str(),
            ),
            _ => ty, // pass through custom types
        }
    }

    /// Check if a type is a primitive (maps to stdint)
    fn is_primitive(ty: &str) -> bool {
        matches!(
            ty,
            "bool" | "u8" | "i8" | "u16" | "i16" | "u32" | "i32" | "u64" | "i64" | "usize" | "void"
        )
    }

    pub fn gen_c(&mut self, ast: &Node) {
        self.module_name = if !ast.name.is_empty() {
            ast.name.clone()
        } else {
            "unknown".to_string()
        };

        // Header
        self.write_line(
            "/* ============================================================================",
        );
        self.write_line(&format!("   Generated from t27 spec: {}", self.module_name));
        self.write_line("   DO NOT EDIT - generated by t27c gen-c");
        let mn = self.module_name.clone();
        self.write_line("   phi^2 + 1/phi^2 = 3 | TRINITY");
        self.write_line(
            "   ============================================================================ */",
        );
        self.write_line("");

        // Includes
        self.write_line("#include <stdint.h>");
        self.write_line("#include <stdbool.h>");
        self.write_line("#include <stddef.h>");

        // Check if tests exist — add assert.h
        let has_tests = ast.children.iter().any(|d| d.kind == NodeKind::TestBlock);
        if has_tests {
            self.write_line("#include <assert.h>");
            // t27's two-argument assert(cond, "msg") is not C's assert; lower it
            // to a self-contained macro (message kept for readability, unused).
            self.write_line(
                "#define t27_assert(c, m) do { if (!(c)) { __builtin_trap(); } } while (0)",
            );
            // W583: the backend emits calls to `assert_eq` in test bodies (59
            // headers) and never defined it, so the C output could not compile
            // even in principle.
            self.write_line(
                "#define assert_eq(a, b) do { if ((a) != (b)) { __builtin_trap(); } } while (0)",
            );
        }
        self.write_line("");

        // Guard macro
        let guard = mn.replace('-', "_").to_uppercase();
        self.write_line(&format!("#ifndef {}_H", guard));
        self.write_line(&format!("#define {}_H", guard));
        self.write_line("");

        // Collect declarations by kind
        let mut consts: Vec<&Node> = Vec::new();
        let mut enums: Vec<&Node> = Vec::new();
        let mut structs: Vec<&Node> = Vec::new();
        let mut functions: Vec<&Node> = Vec::new();
        let mut tests: Vec<&Node> = Vec::new();
        let mut invariants: Vec<&Node> = Vec::new();
        let mut benches: Vec<&Node> = Vec::new();

        for decl in &ast.children {
            match decl.kind {
                NodeKind::ConstDecl => consts.push(decl),
                NodeKind::EnumDecl => enums.push(decl),
                NodeKind::StructDecl => structs.push(decl),
                NodeKind::FnDecl => functions.push(decl),
                NodeKind::TestBlock => tests.push(decl),
                NodeKind::InvariantBlock => invariants.push(decl),
                NodeKind::BenchBlock => benches.push(decl),
                _ => {}
            }
        }

        // Record function return types so tuple-destructuring sites can resolve
        // the element types of a called function.
        for f in &functions {
            if !f.extra_return_type.is_empty() {
                self.fn_return_types
                    .insert(f.name.clone(), f.extra_return_type.clone());
            }
        }

        // Hoist a C struct typedef for every distinct tuple shape used as a
        // function return type or produced by a destructured call. C has no
        // anonymous tuples, so `(u32, u32)` becomes a named struct with fields
        // f0, f1, ....
        {
            let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();
            let mut typedefs: Vec<(String, Vec<String>)> = Vec::new();
            let mut consider = |ty: &str,
                                seen: &mut std::collections::HashSet<String>,
                                typedefs: &mut Vec<(String, Vec<String>)>| {
                if let Some((name, elems)) = Self::c_tuple_info(ty) {
                    if seen.insert(name.clone()) {
                        typedefs.push((name, elems));
                    }
                }
            };
            for f in &functions {
                consider(&f.extra_return_type, &mut seen, &mut typedefs);
                for stmt in &f.children {
                    if stmt.kind == NodeKind::StmtLocal
                        && stmt.name.is_empty()
                        && !stmt.extra_field.is_empty()
                    {
                        if let Some(init) = stmt.children.first() {
                            if init.kind == NodeKind::ExprCall {
                                if let Some(rt) = self.fn_return_types.get(&init.name) {
                                    consider(&rt.clone(), &mut seen, &mut typedefs);
                                }
                            }
                        }
                    }
                }
            }
            if !typedefs.is_empty() {
                self.write_line("/* -------------------------------------------------------");
                self.write_line("   Tuple types");
                self.write_line("   ------------------------------------------------------- */");
                self.write_line("");
                for (name, elems) in &typedefs {
                    self.write("typedef struct { ");
                    for (i, e) in elems.iter().enumerate() {
                        self.write(&format!("{} f{}; ", e, i));
                    }
                    self.write_line(&format!("}} {};", name));
                }
                self.write_line("");
            }
        }

        // Section: Constants
        if !consts.is_empty() {
            self.write_line("/* -------------------------------------------------------");
            self.write_line("   Constants");
            self.write_line("   ------------------------------------------------------- */");
            self.write_line("");
            for c in &consts {
                self.gen_c_const(c);
            }
            self.write_line("");
        }

        // Canonical [T; N] sizes: record numeric const values so a size
        // spelled as a const name and its literal value share one struct type.
        self.const_defs.clear();
        for c in &consts {
            if let Some(v) = c.children.first() {
                if v.kind == NodeKind::ExprLiteral {
                    self.const_defs.insert(c.name.clone(), v.value.clone());
                }
            }
        }

        // Section: [T; N] value structs. Emitted AFTER constants because a
        // size can be a const name (v[MAX_METRICS] needs the #define first).
        {
            let mut tys: Vec<String> = Vec::new();
            fn walk(nodes: &[Node], tys: &mut Vec<String>) {
                for n in nodes {
                    if n.kind == NodeKind::StmtLocal && !n.extra_type.is_empty() {
                        tys.push(n.extra_type.clone());
                    }
                    walk(&n.children, tys);
                }
            }
            for f in &functions {
                tys.push(f.extra_return_type.clone());
                for (_, ptype) in &f.params {
                    tys.push(ptype.clone());
                }
                walk(&f.children, &mut tys);
            }
            for t in &tests {
                walk(&t.children, &mut tys);
            }
            for b in &benches {
                walk(&b.children, &mut tys);
            }
            let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();
            let mut defs: Vec<(String, String, String)> = Vec::new();
            for ty in &tys {
                if let Some(info) = self.c_array_info_r(ty) {
                    if seen.insert(info.0.clone()) {
                        defs.push(info);
                    }
                }
            }
            if !defs.is_empty() {
                self.write_line("/* -------------------------------------------------------");
                self.write_line("   Array value types ([T; N] lowers to a by-value struct)");
                self.write_line("   ------------------------------------------------------- */");
                self.write_line("");
                for (name, elem, size) in &defs {
                    self.write_line(&format!(
                        "typedef struct {{ {} v[{}]; }} {};",
                        elem, size, name
                    ));
                }
                self.write_line("");
            }
        }

        // Section: Enums
        if !enums.is_empty() {
            self.write_line("/* -------------------------------------------------------");
            self.write_line("   Enums");
            self.write_line("   ------------------------------------------------------- */");
            self.write_line("");
            for e in &enums {
                self.gen_c_enum(e);
            }
            self.write_line("");
        }

        // Section: Structs
        if !structs.is_empty() {
            self.write_line("/* -------------------------------------------------------");
            self.write_line("   Structs");
            self.write_line("   ------------------------------------------------------- */");
            self.write_line("");
            for s in &structs {
                self.gen_c_struct(s);
            }
            self.write_line("");
        }

        // Section: Function prototypes
        if !functions.is_empty() {
            self.write_line("/* -------------------------------------------------------");
            self.write_line("   Function prototypes");
            self.write_line("   ------------------------------------------------------- */");
            self.write_line("");
            for f in &functions {
                self.gen_c_fn_prototype(f);
            }
            self.write_line("");
        }

        // Section: Function implementations
        if !functions.is_empty() {
            self.write_line("/* -------------------------------------------------------");
            self.write_line("   Function implementations");
            self.write_line("   ------------------------------------------------------- */");
            self.write_line("");
            for f in &functions {
                self.gen_c_fn(f);
            }
        }

        // Section: Invariants as _Static_assert
        if !invariants.is_empty() {
            self.write_line("/* -------------------------------------------------------");
            self.write_line("   Invariants (compile-time assertions)");
            self.write_line("   ------------------------------------------------------- */");
            self.write_line("");
            for inv in &invariants {
                self.gen_c_invariant(inv);
            }
            self.write_line("");
        }

        // Section: Tests
        if !tests.is_empty() {
            self.write_line("/* -------------------------------------------------------");
            self.write_line("   Tests");
            self.write_line("   ------------------------------------------------------- */");
            self.write_line("");
            for t in &tests {
                self.gen_c_test(t);
            }
            self.write_line("");
        }

        // Section: Benchmarks
        if !benches.is_empty() {
            self.write_line("/* -------------------------------------------------------");
            self.write_line("   Benchmarks");
            self.write_line("   ------------------------------------------------------- */");
            self.write_line("");
            for b in &benches {
                self.gen_c_bench(b);
            }
            self.write_line("");
        }

        // Section: guarded test runner. The test fns above are emitted but
        // nothing CALLS them -- without a runner the C backend has no
        // execution level (a failed t27_assert can never fire in CI).
        // Guarded behind T27_TEST_MAIN so the header stays includable.
        if !tests.is_empty() {
            self.write_line("/* -------------------------------------------------------");
            self.write_line("   Test runner (compile with -DT27_TEST_MAIN to execute)");
            self.write_line("   ------------------------------------------------------- */");
            self.write_line("");
            self.write_line("#ifdef T27_TEST_MAIN");
            self.write_line("#include <stdio.h>");
            self.write_line("int main(void) {");
            self.indent();
            for t in &tests {
                let fn_name = t.name.replace(|c: char| !c.is_alphanumeric(), "_");
                self.write_indent();
                self.write_line(&format!("test_{}();", fn_name));
            }
            self.write_indent();
            // W640 (fixes T48's inflated count): `tests.len()` counted
            // authored-empty blocks, so the runner reported successes for
            // functions whose body is `/* TODO: implement test */`. The claim
            // itself is sound -- the emitted `assert(...)` traps, so this line
            // is only REACHED when nothing failed -- but the denominator was
            // wrong, which misleads about coverage rather than correctness.
            let checked = tests.iter().filter(|t| !t.children.is_empty()).count();
            let empty = tests.len() - checked;
            if empty > 0 {
                self.write_line(&format!(
                    "printf(\"All %d checked tests passed (%d empty, NOT CHECKED).\\n\", {}, {});",
                    checked, empty
                ));
            } else {
                self.write_line(&format!(
                    "printf(\"All %d tests passed.\\n\", {});",
                    checked
                ));
            }
            self.write_indent();
            self.write_line("return 0;");
            self.dedent();
            self.write_line("}");
            self.write_line("#endif /* T27_TEST_MAIN */");
            self.write_line("");
        }

        // Close guard
        self.write_line(&format!("#endif /* {}_H */", guard));
    }

    /// Check if identifier name looks like a type (for type alias detection)
    fn is_type_name(name: &str) -> bool {
        // Primitive types
        if Self::is_primitive(name) {
            return true;
        }
        // Array types: [SIZE]TYPE
        if name.starts_with('[') {
            return true;
        }
        // Custom types: start with uppercase letter
        name.chars()
            .next()
            .map(|c| c.is_uppercase())
            .unwrap_or(false)
    }

    /// Does this rendered C expression contain a function call?
    ///
    /// A call is what makes an expression unusable in `_Static_assert`; a
    /// parenthesis is not. Spelled as an identifier immediately followed by `(`,
    /// with the C keywords that wear the same shape excluded -- `sizeof` above all,
    /// which is an integer constant expression.
    /// Can this rendered C expression stand inside `_Static_assert`?
    ///
    /// Two things disqualify one, and BOTH are needed. Requiring only the call
    /// test raises the corpus error count by 693 and drops ten specs out of
    /// compiling:
    ///
    /// - A FUNCTION CALL. 1065 of the 2078 discarded invariants have one.
    /// - AN IDENTIFIER THIS FILE DOES NOT DECLARE. A quantified invariant
    ///   renders as `(x <= y)`, and `x` and `y` are its bound variables: no
    ///   call, no parenthesis problem, and no existence in C.
    ///   `_Static_assert((x <= y), ...)` is `use of undeclared identifier 'x'`.
    fn is_c_constant_expr(&self, text: &str) -> bool {
        if Self::contains_call(text) {
            return false;
        }
        // A rendered expression with a missing operand -- `(BOARD_NAME != )`,
        // which is what a string literal that lost its quotes leaves behind
        // (#2846) -- must not be promoted from a comment to code. The comment
        // was hiding it; making it a `_Static_assert` turns one silent defect
        // into a syntax error that cascades through the rest of the file.
        if Self::has_empty_operand(text) {
            return false;
        }
        // `const_defs` alone is too narrow: requiring it rejects 1742
        // invariants that were compiling as `_Static_assert` before, because
        // enum constants and constants emitted through other paths never reach
        // that map. The question is whether the NAME EXISTS IN THIS
        // TRANSLATION UNIT, so the emitted text is what to ask.
        // `const_defs` alone is too narrow in two ways, both measured.
        //
        // C's own words are identifier-shaped: the expression `true` is one
        // token and it is not a constant this file declared. Rejecting it lost
        // `_Static_assert(true, "invariant: bridge_modes_mutable")`, which had
        // been compiling.
        //
        // And enum constants and constants emitted through other paths never
        // reach `const_defs`, so the emitted text is asked as well.
        Self::identifiers_in(text)
            .iter()
            .all(|n| Self::is_c_word(n) || self.declares(n))
    }

    /// Does an operator in this rendered expression have nothing after it?
    ///
    /// `(BOARD_NAME != )` is the shape: the renderer dropped the right-hand
    /// side. Ten specs in `boards/` and `fpga/` carry one.
    fn has_empty_operand(text: &str) -> bool {
        let b = text.as_bytes();
        let mut i = 0;
        while i < b.len() {
            if matches!(b[i], b'+' | b'-' | b'*' | b'/' | b'%' | b'<' | b'>' | b'=' | b'!' | b'&' | b'|' | b'^') {
                let mut j = i + 1;
                while j < b.len()
                    && matches!(b[j], b'=' | b'<' | b'>' | b'&' | b'|' | b' ')
                {
                    j += 1;
                }
                if j >= b.len() || b[j] == b')' {
                    return true;
                }
                i = j;
                continue;
            }
            i += 1;
        }
        false
    }

    /// A literal as C must read it: the `_` separators Zig and Rust allow are
    /// not part of a C numeric constant.
    fn c_literal(v: &str) -> String {
        if Self::is_separated_number(v) {
            v.replace('_', "")
        } else {
            v.to_string()
        }
    }

    /// Is this literal a number written with `_` separators?
    ///
    /// Only digits, separators and the usual radix or exponent letters, so a
    /// string or an identifier holding an underscore is left alone.
    fn is_separated_number(v: &str) -> bool {
        if !v.contains('_') {
            return false;
        }
        if !v.starts_with(|c: char| c.is_ascii_digit()) {
            return false;
        }
        v.chars().all(|c| {
            c.is_ascii_alphanumeric() || c == '_' || c == '.'
        }) && v.chars().filter(|c| c.is_ascii_alphabetic()).all(|c| {
            matches!(c, 'x' | 'X' | 'b' | 'B' | 'o' | 'O' | 'e' | 'E')
                || c.is_ascii_hexdigit()
        })
    }

    /// A word C itself supplies: a literal, a type, or an operator spelled as
    /// a name. None of these needs a declaration in this file.
    fn is_c_word(name: &str) -> bool {
        const WORDS: &[&str] = &[
            "true", "false", "NULL", "sizeof", "_Static_assert",
            "char", "short", "int", "long", "float", "double", "void",
            "signed", "unsigned", "_Bool", "bool", "size_t", "ptrdiff_t",
            "int8_t", "int16_t", "int32_t", "int64_t",
            "uint8_t", "uint16_t", "uint32_t", "uint64_t",
        ];
        WORDS.contains(&name)
    }

    /// Does this translation unit declare this name?
    fn declares(&self, name: &str) -> bool {
        // A `#define` and an enum member are integer constant expressions. A
        // `static const` is NOT one in C, however constant it looks, and
        // `const_defs` holds both -- which is why asking that map promoted
        // `_Static_assert((CLOCK_FREQ_HZ > 0), ...)` into nine specs that then
        // failed on a name C will not accept there.
        self.output.contains(&format!("#define {} ", name))
            || self.output.contains(&format!("    {},", name))
    }

    /// Every identifier-shaped token in a rendered expression.
    fn identifiers_in(text: &str) -> Vec<String> {
        let b = text.as_bytes();
        let mut out = Vec::new();
        let mut i = 0;
        while i < b.len() {
            if !(b[i].is_ascii_alphabetic() || b[i] == b'_') {
                i += 1;
                continue;
            }
            let start = i;
            while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'_') {
                i += 1;
            }
            out.push(text[start..i].to_string());
        }
        out
    }

    fn contains_call(text: &str) -> bool {
        const NOT_CALLS: &[&str] = &[
            "sizeof", "if", "while", "for", "switch", "return", "_Static_assert",
        ];
        let b = text.as_bytes();
        let mut i = 0;
        while i < b.len() {
            if !(b[i].is_ascii_alphabetic() || b[i] == b'_') {
                i += 1;
                continue;
            }
            let start = i;
            while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'_') {
                i += 1;
            }
            let name = &text[start..i];
            let mut j = i;
            while j < b.len() && b[j] == b' ' {
                j += 1;
            }
            if j < b.len() && b[j] == b'(' && !NOT_CALLS.contains(&name) {
                return true;
            }
        }
        false
    }

    fn gen_c_const(&mut self, node: &Node) {
        // Detect type alias pattern: ConstDecl with single ExprIdentifier child
        // that looks like a type name (e.g., pub const PackedTrit = u8;)
        //
        // #2830: `is_type_name` is "a primitive, or starts with `[`, or STARTS
        // WITH AN UPPERCASE LETTER", so `const ARG0 : u8 = R1;` was read as a
        // type alias and emitted `typedef R1 ARG0;` -- the declared `u8`
        // discarded and a value used as a type name. 23 of those in
        // `specs/isa/registers.t27` alone.
        //
        // A declaration that STATES ITS TYPE is not a type alias. A type alias
        // has no annotation to state: `pub const PackedTrit = u8;` carries
        // none, `const ARG0 : u8 = R1;` carries one, and that single bit
        // separates them without guessing anything about the spelling of the
        // right-hand side.
        if node.extra_type.is_empty()
            && node.children.len() == 1
            && node.children[0].kind == NodeKind::ExprIdentifier
        {
            let target = &node.children[0].name;
            if Self::is_type_name(target) {
                // Check for array type alias: [SIZE]TYPE
                if target.starts_with('[') {
                    // Parse [SIZE]TYPE pattern
                    if let Some(bracket_end) = target.find(']') {
                        let size = &target[1..bracket_end];
                        let elem_type = &target[bracket_end + 1..];
                        let c_elem = Self::type_to_c(elem_type);
                        self.write_line(&format!("typedef {} {}[{}];", c_elem, node.name, size));
                    } else {
                        self.write_line(&format!("/* type alias: {} = {} */", node.name, target));
                    }
                } else if Self::is_primitive(target) {
                    let c_type = Self::type_to_c(target);
                    self.write_line(&format!("typedef {} {};", c_type, node.name));
                } else {
                    self.write_line(&format!("typedef {} {};", target, node.name));
                }
                return;
            }
        }

        // Regular constant with expression value
        // A module-level `var` is MUTABLE, and neither spelling below can hold
        // an assignment: `#define counter 0` turns `counter = counter + 1`
        // into `0 = (0 + 1)`, which is not C at all, and `static const` is
        // rejected by the compiler. The parser records mutability in
        // `extra_mutable`; this path never read it. gen-verilog has always
        // emitted a `reg` here.
        let c_type = if !node.extra_type.is_empty() {
            Self::type_to_c(&node.extra_type).to_string()
        } else {
            "int".to_string()
        };
        if node.extra_mutable {
            self.write(&format!("static {} {} = ", c_type, node.name));
            if let Some(child) = node.children.first() {
                self.gen_c_expr(child);
            } else if !node.value.is_empty() {
                self.write(&node.value);
            } else {
                self.write("0");
            }
            self.write_line(";");
            return;
        }
        if !node.children.is_empty() {
            let child = &node.children[0];
            // Simple literal → #define
            if child.kind == NodeKind::ExprLiteral {
                self.write_line(&format!(
                        "#define {} {}",
                        node.name,
                        Self::c_literal(&child.value)
                    ));
            } else {
                // Complex expression → static const
                self.write(&format!("static const {} {} = ", c_type, node.name));
                self.gen_c_expr(child);
                self.write_line(";");
            }
        } else if !node.value.is_empty() {
            // Constant with a direct value (no child node)
            self.write_line(&format!(
                "#define {} {}",
                node.name,
                Self::c_literal(&node.value)
            ));
        }
    }

    fn gen_c_enum(&mut self, node: &Node) {
        // typedef enum { ... } Name;
        self.write_line("typedef enum {");
        self.indent();

        for (i, variant) in node.children.iter().enumerate() {
            self.write_indent();
            let prefix = node.name.to_uppercase();
            if !variant.value.is_empty() {
                self.write(&format!(
                    "{}_{} = {}",
                    prefix,
                    variant.name.to_uppercase(),
                    variant.value
                ));
            } else {
                self.write(&format!("{}_{}", prefix, variant.name.to_uppercase()));
            }
            if i < node.children.len() - 1 {
                self.write(",");
            }
            self.write_line("");
        }

        self.dedent();
        self.write_line(&format!("}} {};", node.name));
        self.write_line("");
    }

    fn gen_c_struct(&mut self, node: &Node) {
        self.write_line("typedef struct {");
        self.indent();

        for field in &node.children {
            self.write_indent();
            // W582: struct fields used `type_to_c`, which passes anything it
            // does not recognise through verbatim -- so a slice was `[]u8` and
            // an optional `?[]u8`, neither of which is C. `param_type_to_c`
            // already lowers both.
            let c_type = Self::param_type_to_c(&field.extra_type);
            let c_type = c_type.as_str();
            if !field.extra_size.is_empty() {
                // Array field
                self.write_line(&format!("{} {}[{}];", c_type, field.name, field.extra_size));
            } else {
                self.write_line(&format!("{} {};", c_type, field.name));
            }
        }

        self.dedent();
        self.write_line(&format!("}} {};", node.name));
        self.write_line("");
    }

    /// C return type for a t27 return type: a tuple lowers to its hoisted
    /// struct typedef name, everything else to the usual C type.
    fn c_return_type(ty: &str) -> String {
        if let Some((name, _)) = Self::c_tuple_info(ty) {
            name
        } else {
            Self::param_type_to_c(ty)
        }
    }

    fn gen_c_fn_prototype(&mut self, node: &Node) {
        let ret_type = self.c_return_type_r(&node.extra_return_type);
        let ret_type = if ret_type.is_empty() {
            "void".to_string()
        } else {
            ret_type
        };

        self.write(&format!("{} {}(", ret_type, node.name));
        for (i, (pname, ptype)) in node.params.iter().enumerate() {
            if i > 0 {
                self.write(", ");
            }
            let c_type = self.param_type_to_c_r(ptype);
            self.write(&format!("{} {}", c_type, pname));
        }
        if node.params.is_empty() {
            self.write("void");
        }
        self.write_line(");");
    }

    fn gen_c_fn(&mut self, node: &Node) {
        let ret_type = self.c_return_type_r(&node.extra_return_type);
        let ret_type = if ret_type.is_empty() {
            "void".to_string()
        } else {
            ret_type
        };
        // Track a tuple return type so an `ExprTuple` in a `return` can be
        // emitted as the matching C compound literal.
        self.current_ret_tuple_type =
            Self::c_tuple_info(&node.extra_return_type).map(|_| node.extra_return_type.clone());
        // Track the [T; N] return struct and every array-struct-typed name
        // (params now; locals join as their declarations are emitted).
        self.current_ret_array_type =
            self.c_array_info_r(&node.extra_return_type).map(|(n, _, _)| n);
        self.array_typed_names.clear();
        for (pname, ptype) in &node.params {
            if Self::c_array_info(ptype).is_some() {
                self.array_typed_names.insert(pname.clone());
            }
        }

        self.write(&format!("{} {}(", ret_type, node.name));
        for (i, (pname, ptype)) in node.params.iter().enumerate() {
            if i > 0 {
                self.write(", ");
            }
            let c_type = self.param_type_to_c_r(ptype);
            self.write(&format!("{} {}", c_type, pname));
        }
        if node.params.is_empty() {
            self.write("void");
        }
        self.write_line(") {");

        self.indent();

        if node.children.is_empty() {
            self.write_indent();
            self.write_line("/* TODO: implement */");
        } else {
            for stmt in &node.children {
                self.gen_c_stmt(stmt);
            }
        }

        self.dedent();
        self.write_line("}");
        self.write_line("");
    }

    fn gen_c_test(&mut self, node: &Node) {
        // Convert test name to valid C identifier
        let fn_name = node.name.replace(|c: char| !c.is_alphanumeric(), "_");
        let fn_name = format!("test_{}", fn_name);
        self.current_ret_array_type = None;
        self.array_typed_names.clear();

        self.write_line(&format!("void {}(void) {{", fn_name));
        self.indent();

        // Test-block bindings ('b0 = f(...);') parse as StmtAssign, not
        // StmtLocal -- the same defect fixed for Verilog (#1894) and Zig.
        // Declare the FIRST assignment to each plain identifier (uint64_t holds
        // every t27 scalar); a tuple target binds the struct return once via
        // GNU __auto_type (gcc and clang) and peels .f0/.f1/...
        let mut bound: std::collections::HashSet<String> = std::collections::HashSet::new();
        // #2834: seeded EMPTY, this set did not know about the locals the block
        // already declares, so the FIRST assignment to an existing variable was
        // read as a fresh binding and emitted a SECOND declaration:
        //
        //     var packed: PackedTrit = 0;      ->  PackedTrit packed = 0;
        //     packed = pack_trit(.zero, 0, packed);
        //                                      ->  uint64_t packed = pack_trit(...);
        //     packed = pack_trit(.zero, 1, packed);
        //                                      ->  packed = pack_trit(...);
        //
        // One spurious declaration per variable, and the emitter contradicting
        // itself two lines later. `cc` calls it "redefinition of 'packed' with a
        // different type".
        //
        // The Verilog path has done this correctly since #1894 and says so in a
        // comment above its own seeding loop. Only the C path was missing it.
        for stmt in &node.children {
            if stmt.kind == NodeKind::StmtLocal && !stmt.name.is_empty() {
                bound.insert(stmt.name.clone());
            }
        }
        let mut tuple_ctr = 0u32;
        for stmt in &node.children {
            let fresh = stmt.kind == NodeKind::StmtAssign
                && stmt.children.len() >= 2
                && stmt.children[0].kind == NodeKind::ExprIdentifier
                && !stmt.children[0].name.is_empty()
                && bound.insert(stmt.children[0].name.clone());
            let tuple = stmt.kind == NodeKind::StmtAssign
                && stmt.children.len() >= 2
                && stmt.children[0].kind == NodeKind::ExprTuple
                && stmt.children[0]
                    .children
                    .iter()
                    .all(|e| e.kind == NodeKind::ExprIdentifier && !e.name.is_empty());
            if fresh {
                self.write_indent();
                // A binding whose RHS calls a [T; N]-returning fn is a struct
                // value, not a uint64_t.
                let arr_ty = if stmt.children[1].kind == NodeKind::ExprCall {
                    self.fn_return_types
                        .get(&stmt.children[1].name)
                        .cloned()
                        .and_then(|rt| self.c_array_info_r(&rt))
                        .map(|(n, _, _)| n)
                } else {
                    None
                };
                if let Some(n) = arr_ty {
                    self.array_typed_names.insert(stmt.children[0].name.clone());
                    self.write(&format!("{} {} = ", n, stmt.children[0].name));
                } else {
                    self.write(&format!("uint64_t {} = ", stmt.children[0].name));
                }
                self.gen_c_expr(&stmt.children[1]);
                self.write(";");
                self.write_line("");
                self.write_indent();
                self.write(&format!("(void){};", stmt.children[0].name));
                self.write_line("");
            } else if tuple {
                tuple_ctr += 1;
                let tmp = format!("__t27_tup{}", tuple_ctr);
                self.write_indent();
                self.write(&format!("__auto_type {} = ", tmp));
                self.gen_c_expr(&stmt.children[1]);
                self.write(";");
                self.write_line("");
                for (fi, e) in stmt.children[0].children.iter().enumerate() {
                    if e.name == "_" {
                        continue; // discarded element: never bind (a second `_` would redefine)
                    }
                    bound.insert(e.name.clone());
                    self.write_indent();
                    self.write(&format!("__auto_type {} = {}.f{};", e.name, tmp, fi));
                    self.write_line("");
                    self.write_indent();
                    self.write(&format!("(void){};", e.name));
                    self.write_line("");
                }
            } else {
                self.gen_c_stmt(stmt);
            }
        }

        if node.children.is_empty() {
            self.write_indent();
            self.write_line("/* TODO: implement test */");
        }

        self.dedent();
        self.write_line("}");
        self.write_line("");
    }

    fn gen_c_invariant(&mut self, node: &Node) {
        self.write_line(&format!("/* invariant: {} */", node.name));
        // W699 rung 9: an invariant BODY, not a single predicate.
        //
        // This function emits at MODULE SCOPE, which is right for the
        // `_Static_assert` it is built around and invalid for anything else. It
        // never mattered while braceless bodies were being discarded; once they
        // lower, C got
        //
        //     int32_t vals[3] = {...};        <- redefined by the next invariant
        //     while ((i < 3)) { ... }         <- "while loop outside of a function"
        //
        // A body with any statement that is not a bare expression goes in a
        // function, the way `gen_c_test` already does. The `_Static_assert` path
        // below is untouched: it still serves the single-predicate spelling,
        // which is what it was written for.
        let has_statements = node
            .children
            .iter()
            .any(|c| c.kind != NodeKind::StmtExpr);
        if has_statements {
            let fn_name = format!(
                "invariant_{}",
                node.name.replace(|c: char| !c.is_alphanumeric(), "_")
            );
            self.write_line(&format!("void {}(void) {{", fn_name));
            self.indent();
            for stmt in &node.children {
                self.gen_c_stmt(stmt);
            }
            self.dedent();
            self.write_line("}");
            return;
        }
        if node.children.is_empty() {
            self.write_line(&format!(
                "/* _Static_assert(1, \"invariant: {}\"); */",
                node.name
            ));
        } else {
            for stmt in &node.children {
                // Try to emit as _Static_assert if it's a simple expression
                self.write_indent();
                match stmt.kind {
                    NodeKind::StmtExpr => {
                        if !stmt.children.is_empty() {
                            // W583: `_Static_assert` needs a CONSTANT
                            // expression, and the W567 lowering wraps the
                            // condition in `assert(...)` -- so this emitted
                            // `_Static_assert(assert(f(x) == 3), "...")`, which
                            // is invalid twice over: `assert` is a runtime
                            // macro, and a function call is not constant.
                            //
                            // The condition is unwrapped, and an invariant that
                            // calls anything becomes a comment rather than
                            // invalid code. C cannot check it; saying so is
                            // better than emitting something that does not
                            // compile.
                            let cond = match &stmt.children[0] {
                                c if c.kind == NodeKind::ExprCall
                                    && c.name == "assert"
                                    && !c.children.is_empty() =>
                                {
                                    &c.children[0]
                                }
                                c => c,
                            };
                            let mut probe = CCodegen::new();
                            probe.gen_c_expr(cond);
                            let text = probe.output.clone();
                            // The test used to be "the text contains a
                            // parenthesis", which is not what makes an
                            // expression non-constant -- and `gen_c_expr`
                            // parenthesises its own binary expressions, so the
                            // verdict was largely triggered by the emitter one
                            // line above. `(MAX_STEPS > 0)` and
                            // `(DEBOUNCE_DELAY_MS == 618)` are integer constant
                            // expressions and were thrown away as if they were
                            // not: 1013 of the 2078 discarded invariants
                            // contain no call at all.
                            //
                            // What actually disqualifies an expression here is
                            // a FUNCTION CALL. `sizeof` is spelled like one and
                            // is constant, so it is excluded by name.
                            if !self.is_c_constant_expr(&text) {
                                self.write(&format!(
                                    "/* invariant {} is not a C constant expression: {} */\n",
                                    node.name,
                                    text.replace("/*", "").replace("*/", "")
                                ));
                            } else {
                                self.write("_Static_assert(");
                                self.write(&text);
                                self.write(&format!(", \"invariant: {}\");\n", node.name));
                            }
                        }
                    }
                    _ => {
                        self.gen_c_stmt(stmt);
                    }
                }
            }
        }
        self.write_line("");
    }

    fn gen_c_bench(&mut self, node: &Node) {
        let fn_name = node.name.replace(|c: char| !c.is_alphanumeric(), "_");
        let fn_name = if fn_name.starts_with("bench_") {
            fn_name
        } else {
            format!("bench_{}", fn_name)
        };

        self.write_line(&format!("void {}(void) {{", fn_name));
        self.indent();
        self.write_indent();
        self.write_line(&format!("/* bench: {} */", node.name));

        for stmt in &node.children {
            self.gen_c_stmt(stmt);
        }

        if node.children.is_empty() {
            self.write_indent();
            self.write_line("/* TODO: implement benchmark */");
        }

        self.dedent();
        self.write_line("}");
        self.write_line("");
    }

    fn gen_c_stmt(&mut self, node: &Node) {
        match node.kind {
            NodeKind::ExprReturn => {
                self.write_indent();
                self.write("return ");
                if !node.children.is_empty() {
                    // A returned array literal needs the compound-literal cast
                    // to the fn's [T; N] struct; bare braces are not a C
                    // expression.
                    if node.children[0].kind == NodeKind::ExprArrayLiteral {
                        if let Some(name) = self.current_ret_array_type.clone() {
                            self.write(&format!("({})", name));
                        }
                    }
                    self.gen_c_expr(&node.children[0]);
                }
                self.write_line(";");
            }
            NodeKind::StmtLocal
                if node.name.is_empty() && !node.extra_field.is_empty() =>
            {
                // Tuple-destructuring `let (s, d) = call()`: bind the call result
                // through a temp of the callee's hoisted tuple struct, then copy
                // each field (f0, f1, ...) into a typed local.
                let names: Vec<String> = node
                    .extra_field
                    .split(',')
                    .map(|s| s.trim().to_string())
                    .filter(|s| !s.is_empty())
                    .collect();
                let tuple_ty = node.children.first().and_then(|init| {
                    if init.kind == NodeKind::ExprCall {
                        self.fn_return_types.get(&init.name).cloned()
                    } else {
                        None
                    }
                });
                let info = tuple_ty.as_deref().and_then(Self::c_tuple_info);
                match info {
                    Some((tname, elems)) if elems.len() == names.len() => {
                        let tmp = format!("__t_c{}", node.line);
                        self.write_indent();
                        self.write(&format!("{} {} = ", tname, tmp));
                        if let Some(init) = node.children.first() {
                            self.gen_c_expr(init);
                        }
                        self.write_line(";");
                        for (i, (nm, ety)) in names.iter().zip(elems.iter()).enumerate() {
                            self.write_indent();
                            self.write_line(&format!("{} {} = {}.f{};", ety, nm, tmp, i));
                        }
                    }
                    _ => {
                        let names: Vec<String> = node
                            .extra_field
                            .split(',')
                            .map(|n| n.trim().to_string())
                            .filter(|n| !n.is_empty())
                            .collect();
                        let init_is_tuple = node
                            .children
                            .first()
                            .is_some_and(|i| i.kind == NodeKind::ExprTuple);
                        if init_is_tuple {
                            // `let (a, b, c) = (x, y, z);` -- bind element-wise;
                            // discarded `_` elements are skipped.
                            let init = node.children.first().unwrap();
                            for (nm, val) in names.iter().zip(init.children.iter()) {
                                if nm == "_" {
                                    continue;
                                }
                                self.write_indent();
                                self.write(&format!("__auto_type {} = ", nm));
                                self.gen_c_expr(val);
                                self.write_line(";");
                                self.write_indent();
                                self.write_line(&format!("(void){};", nm));
                            }
                        } else {
                            // Unresolvable callee type: bind once via GNU
                            // __auto_type and peel .f0/.f1.
                            self.local_tuple_counter += 1;
                            let tmp = format!("__t27_lt{}", self.local_tuple_counter);
                            self.write_indent();
                            self.write(&format!("__auto_type {} = ", tmp));
                            if let Some(init) = node.children.first() {
                                self.gen_c_expr(init);
                            }
                            self.write_line(";");
                            for (fi, nm) in names.iter().enumerate() {
                                if nm == "_" {
                                    continue;
                                }
                                self.write_indent();
                                self.write_line(&format!(
                                    "__auto_type {} = {}.f{}; (void){};",
                                    nm, tmp, fi, nm
                                ));
                            }
                        }
                    }
                }
            }
            NodeKind::StmtLocal => {
                self.write_indent();
                // Tuple destructure: `let (a, b) = init;` -- C has no
                // destructuring, so bind the tuple struct once via GNU
                // __auto_type and peel .f0/.f1 (discarded `_` elements skipped).
                if node.name.is_empty() && !node.extra_field.is_empty() {
                    self.local_tuple_counter += 1;
                    let tmp = format!("__t27_lt{}", self.local_tuple_counter);
                    self.write(&format!("__auto_type {} = ", tmp));
                    if !node.children.is_empty() {
                        self.gen_c_expr(&node.children[0]);
                    }
                    self.write_line(";");
                    for (fi, ename) in node
                        .extra_field
                        .split(',')
                        .map(|e| e.trim())
                        .filter(|e| !e.is_empty())
                        .enumerate()
                    {
                        if ename == "_" {
                            continue;
                        }
                        self.write_indent();
                        self.write_line(&format!(
                            "__auto_type {} = {}.f{}; (void){};",
                            ename, tmp, fi, ename
                        ));
                    }
                    return;
                }
                let raw_type = &node.extra_type;
                // Rust-style array local: [T; N] name -> by-value struct local.
                if let Some((sname, _, _)) = self.c_array_info_r(raw_type) {
                    self.array_typed_names.insert(node.name.clone());
                    self.write(&format!("{} {}", sname, node.name));
                    if !node.children.is_empty() {
                        self.write(" = ");
                        self.gen_c_expr(&node.children[0]);
                    }
                    self.write_line(";");
                    return;
                }
                // Handle array local vars: [SIZE]TYPE name
                if raw_type.starts_with('[') {
                    if let Some(bracket_end) = raw_type.find(']') {
                        let size = &raw_type[1..bracket_end];
                        let elem = &raw_type[bracket_end + 1..];
                        let c_elem = if Self::is_primitive(elem) {
                            Self::type_to_c(elem).to_string()
                        } else {
                            elem.to_string()
                        };
                        self.write(&format!("{} {}[{}]", c_elem, node.name, size));
                    } else {
                        self.write(&format!("int {}", node.name));
                    }
                } else if raw_type.is_empty()
                    && node
                        .children
                        .first()
                        .is_some_and(|c| {
                            c.kind == NodeKind::ExprArrayLiteral
                                && !c.extra_type.is_empty()
                                && !c.children.is_empty()
                        })
                {
                    // W699 rung 3: `const vals = [_]i32{...}` has no annotation,
                    // so the arm below reached for GNU `__auto_type` -- and
                    // `__auto_type x = { ... }` is not C: "cannot use
                    // '__auto_type' with initializer list". The literal carries
                    // its own element type and its own length; use them.
                    let lit = node.children.first().unwrap();
                    let elem = &lit.extra_type;
                    let c_elem = if Self::is_primitive(elem) {
                        Self::type_to_c(elem).to_string()
                    } else {
                        elem.to_string()
                    };
                    self.write(&format!("{} {}[{}]", c_elem, node.name, lit.children.len()));
                } else {
                    let inferred_arr = if raw_type.is_empty() {
                        node.children
                            .first()
                            .filter(|c| c.kind == NodeKind::ExprCall)
                            .and_then(|c| self.fn_return_types.get(&c.name).cloned())
                            .and_then(|rt| self.c_array_info_r(&rt))
                            .map(|(n, _, _)| n)
                    } else {
                        None
                    };
                    let c_type = if let Some(n) = inferred_arr {
                        self.array_typed_names.insert(node.name.clone());
                        n
                    } else if !raw_type.is_empty() {
                        self.param_type_to_c_r(raw_type)
                    } else if let Some(w) = node
                        .children
                        .first()
                        .and_then(Codegen::zig_int_literal_default_type)
                    {
                        // Untyped integer-literal locals must not default to
                        // C's signed int: 0xFFFFFFFF as int is -1 and every
                        // unsigned comparison against it inverts (the same
                        // class the Zig backend fixed as comptime_int).
                        if w == "u64" { "uint64_t".to_string() } else { "uint32_t".to_string() }
                    } else if !node.children.is_empty() {
                        // GNU `__auto_type`: the type follows the INITIALISER,
                        // which is what Rust's `let` and Zig's `const` do.
                        // The `int` fallback below caught everything the two
                        // arms above miss -- a CALL among them -- and silently
                        // truncated it: `const v = big()` with `big() -> u64`
                        // made C print 1 where Rust and Zig print 4294967297,
                        // and the C compiled without a diagnostic.
                        //
                        // Same builtin the tuple-destructure paths above
                        // already emit, so it costs no new portability.
                        "__auto_type".to_string()
                    } else {
                        // No initialiser: `__auto_type` has nothing to follow.
                        "int".to_string()
                    };
                    self.write(&format!("{} {}", c_type, node.name));
                }
                if !node.children.is_empty() {
                    self.write(" = ");
                    self.gen_c_expr(&node.children[0]);
                }
                self.write_line(";");
            }
            NodeKind::StmtAssign => {
                self.write_indent();
                if node.children.len() >= 2 {
                    // Check for _ = expr (discard) pattern
                    let is_discard = node.children[0].kind == NodeKind::ExprIdentifier
                        && node.children[0].name == "_";
                    if is_discard {
                        self.write("(void)");
                        self.gen_c_expr(&node.children[1]);
                    } else {
                        self.gen_c_expr(&node.children[0]);
                        self.write(&assign_op_text(&node.extra_op));
                        self.gen_c_expr(&node.children[1]);
                    }
                }
                self.write_line(";");
            }
            NodeKind::StmtIf => {
                self.gen_c_if_stmt(node);
            }
            NodeKind::StmtWhile => {
                self.gen_c_while_stmt(node);
            }
            NodeKind::StmtFor => {
                self.gen_c_for_stmt(node);
            }
            NodeKind::StmtForRange => {
                self.gen_c_for_range_stmt(node);
            }
            NodeKind::StmtBreak => {
                self.write_line("break;");
            }
            NodeKind::StmtContinue => {
                self.write_line("continue;");
            }
            NodeKind::StmtExpr => {
                self.write_indent();
                if !node.children.is_empty() {
                    self.gen_c_expr(&node.children[0]);
                }
                self.write_line(";");
            }
            _ => {
                self.write_indent();
                self.gen_c_expr(node);
                self.write_line(";");
            }
        }
    }

    fn gen_c_if_stmt(&mut self, node: &Node) {
        self.write_indent();
        self.write("if (");
        if !node.children.is_empty() {
            self.gen_c_expr(&node.children[0]);
        }
        self.write_line(") {");

        self.indent();
        if node.children.len() > 1 {
            for stmt in &node.children[1].children {
                self.gen_c_stmt(stmt);
            }
        }
        self.dedent();

        if node.children.len() > 2 {
            let else_block = &node.children[2];
            if else_block.children.len() == 1 && else_block.children[0].kind == NodeKind::StmtIf {
                self.write_indent();
                self.write("} else ");
                self.gen_c_if_stmt_inline(&else_block.children[0]);
            } else {
                self.write_indent();
                self.write_line("} else {");
                self.indent();
                for stmt in &else_block.children {
                    self.gen_c_stmt(stmt);
                }
                self.dedent();
                self.write_indent();
                self.write_line("}");
            }
        } else {
            self.write_indent();
            self.write_line("}");
        }
    }

    fn gen_c_if_stmt_inline(&mut self, node: &Node) {
        self.write("if (");
        if !node.children.is_empty() {
            self.gen_c_expr(&node.children[0]);
        }
        self.write_line(") {");

        self.indent();
        if node.children.len() > 1 {
            for stmt in &node.children[1].children {
                self.gen_c_stmt(stmt);
            }
        }
        self.dedent();

        if node.children.len() > 2 {
            let else_block = &node.children[2];
            if else_block.children.len() == 1 && else_block.children[0].kind == NodeKind::StmtIf {
                self.write_indent();
                self.write("} else ");
                self.gen_c_if_stmt_inline(&else_block.children[0]);
            } else {
                self.write_indent();
                self.write_line("} else {");
                self.indent();
                for stmt in &else_block.children {
                    self.gen_c_stmt(stmt);
                }
                self.dedent();
                self.write_indent();
                self.write_line("}");
            }
        } else {
            self.write_indent();
            self.write_line("}");
        }
    }

    fn gen_c_while_stmt(&mut self, node: &Node) {
            // `while (cond) : (step) { body }` has THREE children: condition,
            // continue expression, body. Reading children[1] as the body made
            // the step the whole loop and dropped the real one. C has no
            // continue expression, so the step is emitted as the LAST statement
            // of the body -- correct for every site in the corpus, none of
            // which contains a `continue`, and stated here because a `continue`
            // would skip it.
        self.write_indent();
        self.write("while (");
        if !node.children.is_empty() {
            self.gen_c_expr(&node.children[0]);
        }
        self.write_line(") {");

        self.indent();
        let body_idx = node.children.len().saturating_sub(1);
        if node.children.len() > 1 {
            for stmt in &node.children[body_idx].children {
                self.gen_c_stmt(stmt);
            }
            if body_idx > 1 {
                self.gen_c_stmt(unwrap_single(&node.children[1]));
            }
        }
        self.dedent();
        self.write_indent();
        self.write_line("}");
    }

    fn gen_c_for_stmt(&mut self, node: &Node) {
        // The comment here used to say "emit as a for loop with index" and the
        // code emitted `{ body }` -- no induction variable, no bound, no
        // increment. `for (0..1000) |_| { ... }` ran its body ONCE, in output
        // `cc` accepts without a diagnostic. 373 of the 531 `for` statements in
        // the corpus iterate a literal range, so that is the case worth
        // lowering properly.
        let body_idx = node.children.len().saturating_sub(1);
        // The range is an ExprBinary whose extra_op is "..", NOT the ExprRange
        // variant -- that variant is declared in NodeKind and constructed
        // nowhere, so matching on it matched nothing and the block below kept
        // running.
        if body_idx == 1
            && node.children[0].kind == NodeKind::ExprBinary
            && node.children[0].extra_op == ".."
            && node.children[0].children.len() == 2
        {
            // A capture of `_` names nothing the body can read, so the counter
            // gets a reserved name instead; anything else is the body's own
            // variable and must keep its spelling.
            let cap = node
                .params
                .first()
                .map(|(n, _)| n.clone())
                .unwrap_or_default();
            let var = if cap.is_empty() || cap == "_" {
                "__t27_i".to_string()
            } else {
                cap
            };
            self.write_indent();
            self.write(&format!("for (int {var} = "));
            self.gen_c_expr(&node.children[0].children[0]);
            self.write(&format!("; {var} < "));
            self.gen_c_expr(&node.children[0].children[1]);
            self.write_line(&format!("; {var}++) {{"));
            self.indent();
            for stmt in &node.children[body_idx].children {
                self.gen_c_stmt(stmt);
            }
            self.dedent();
            self.write_indent();
            self.write_line("}");
            return;
        }
        // Everything else still becomes a bare block, and the comment now says
        // so rather than describing a loop that is not there.
        self.write_indent();
        self.write_line("/* for-each over a non-range iterable: body emitted ONCE, not looped */");
        self.write_indent();
        self.write_line("{");
        self.indent();

        // Emit body
        let body_idx = node.children.len().saturating_sub(1);
        if !node.children.is_empty() {
            for stmt in &node.children[body_idx].children {
                self.gen_c_stmt(stmt);
            }
        }

        self.dedent();
        self.write_indent();
        self.write_line("}");
    }

    fn gen_c_for_range_stmt(&mut self, node: &Node) {
        let var = &node.name;
        self.write_indent();
        if node.children.len() >= 2 {
            self.write(&format!("for (int {var} = "));
            self.gen_c_expr(&node.children[0]);
            self.write(&format!("; {var} < "));
            self.gen_c_expr(&node.children[1]);
            self.write(&format!("; {var}++)"));
        }
        self.write_line(" {");
        self.indent();
        if node.children.len() > 2 {
            for stmt in &node.children[2].children {
                self.gen_c_stmt(stmt);
            }
        }
        self.dedent();
        self.write_indent();
        self.write_line("}");
    }

    /// Map a t27/Zig type to C for use in parameter/return positions
    fn param_type_to_c(ty: &str) -> String {
        // A dotted foreign type (`std.mem.Allocator`) has no C spelling at all.
        // It reached the header as `std.mem.Allocator x;`, which is not C;
        // `void*` is the honest lowering and what a hand-written binding uses.
        if ty.contains('.') && !ty.starts_with('[') {
            return "void*".to_string();
        }

        // Optional: C has no such type, and NULL is its conventional encoding.
        // Before W581 the `?` never reached here (the lexer dropped it) and an
        // optional silently became a plain value; now it arrives, and emitting
        // it verbatim produced `?[]u8 field;`, which is not C.
        if let Some(inner) = ty.strip_prefix('?') {
            let base = Self::param_type_to_c(inner.trim());
            return if base.ends_with('*') {
                base
            } else {
                format!("{}*", base)
            };
        }
        // Prefix pointer: t27 spells it `*T`, C spells it `T*`. There was no
        // arm for this, so the text passed through verbatim and the header read
        //
        //     uint64_t set(*Bitmap bitmap);
        //
        // where C parses `Bitmap` as the declared NAME with an implicit-int
        // type, then finds a second identifier: "type specifier missing" and
        // "expected ')'". 52 generated files carried it.
        if let Some(inner) = ty.strip_prefix('*') {
            let base = Self::param_type_to_c(inner.trim());
            return format!("{}*", base);
        }
        // Slice types: []Type → Type*, including the `[]const T` spelling --
        // without stripping `const` the inner type was the literal string
        // "const u8" and C received `[]const u8* positional;`.
        if let Some(inner) = ty.strip_prefix("[]") {
            let inner = inner.trim();
            let inner = inner.strip_prefix("const ").unwrap_or(inner).trim();
            let c_inner = if inner.starts_with("[]") || inner.starts_with('?') {
                // A slice of slices (`[][]const u8`) or of optionals: map the
                // inner type properly instead of passing t27 syntax through.
                Self::param_type_to_c(inner)
            } else {
                Self::type_to_c(inner).to_string()
            };
            return format!("{}*", c_inner);
        }
        // Rust-style array types: [T; N] → by-value struct (t27#1944). The
        // old T* lowering could not survive a return position and split the
        // type system in two.
        if let Some((name, _, _)) = Self::c_array_info(ty) {
            return name;
        }
        // Array types: [SIZE]Type → Type* (pointer in param position)
        if ty.starts_with('[') {
            if let Some(bracket_end) = ty.find(']') {
                let elem = ty[bracket_end + 1..].trim();
                if !elem.is_empty() {
                    return format!("{}*", Self::type_to_c(elem));
                }
                // W584: `[T]` -- the element is INSIDE the brackets, a
                // Rust-style slice spelling. Taking the text after `]` gave an
                // empty type and C received `* resources;`.
                let inner = ty[1..bracket_end].trim();
                if !inner.is_empty() {
                    return format!("{}*", Self::param_type_to_c(inner));
                }
            }
        }
        // W583: this used to be gated on `is_primitive`, which lists only the
        // integer scalars -- so `f32`, `f64`, `str`, `string` and `gf16` took
        // the pass-through arm and reached C unmapped even after `type_to_c`
        // learned them. `type_to_c` already passes genuinely custom types
        // through, so the gate only ever suppressed correct mappings.
        Self::type_to_c(ty).to_string()
    }

    fn gen_c_expr(&mut self, node: &Node) {
        match node.kind {
            NodeKind::ExprLiteral => {
                // Zig and Rust write `100_000_000`; C does not. The separator
                // reached the output verbatim and `cc` reads it as a suffix:
                // `invalid suffix '_000_000' on integer constant`. 97 lines
                // across 35 specs.
                let stripped;
                let val = if Self::is_separated_number(&node.value) {
                    stripped = node.value.replace('_', "");
                    &stripped
                } else {
                    &node.value
                };
                if val == "true" {
                    self.write("true");
                } else if val == "false" {
                    self.write("false");
                } else if val.starts_with("[_]") || val.starts_with("[") && val.contains('{') {
                    // Zig array literal: [_]u8{ 0xFF, 0x55, ... } → { 0xFF, 0x55, ... }
                    if let Some(brace_start) = val.find('{') {
                        self.write(&val[brace_start..]);
                    } else {
                        self.write(val);
                    }
                } else {
                    self.write(val);
                }
            }
            NodeKind::ExprIdentifier => {
                let name = &node.name;
                // Map Zig-specific identifiers to C equivalents
                if name == "undefined" {
                    self.write("{0}");
                } else if name.starts_with("[_]") || (name.starts_with('[') && name.contains(']')) {
                    // Array type used as value (shouldn't happen, but fallback)
                    self.write(&format!("/* {} */", name));
                } else {
                    self.write(name);
                }
            }
            NodeKind::ExprEnumValue => {
                // In C enums, we use ENUM_VARIANT style
                self.write(&node.name.to_uppercase());
            }
            NodeKind::ExprCall => {
                let fname = &node.name;
                if fname == "assert" && node.children.len() == 2 {
                    // t27 assert(cond, "msg"): C's assert macro takes ONE argument
                    // and the message literal must be re-quoted (the parser stores
                    // string contents unquoted).
                    self.write("t27_assert(");
                    self.gen_c_expr(&node.children[0]);
                    let msg = node.children[1]
                        .value
                        .trim_matches('"')
                        .replace('\\', "\\\\")
                        .replace('"', "\\\"");
                    self.write(", \"");
                    self.write(&msg);
                    self.write("\")");
                } else if fname == "@compileAssert" {
                    self.write("_Static_assert(");
                    if !node.children.is_empty() {
                        self.gen_c_expr(&node.children[0]);
                    }
                    self.write(", \"compile assert\")");
                } else if fname.starts_with("@setEvalBranchQuota") || fname == "@setEvalBranchQuota"
                {
                    // Zig comptime hint — emit as comment
                    self.write("/* @setEvalBranchQuota(");
                    for (i, arg) in node.children.iter().enumerate() {
                        if i > 0 {
                            self.write(", ");
                        }
                        self.gen_c_expr(arg);
                    }
                    self.write(") */");
                } else if fname == "std.testing.expectEqual" {
                    // Zig test assert: std.testing.expectEqual(expected, actual) → assert(expected == actual)
                    self.write("assert(");
                    if node.children.len() >= 2 {
                        self.gen_c_expr(&node.children[0]);
                        self.write(" == ");
                        self.gen_c_expr(&node.children[1]);
                    }
                    self.write(")");
                } else if fname == "std.testing.expect" {
                    // Zig test expect: std.testing.expect(cond) → assert(cond)
                    self.write("assert(");
                    if !node.children.is_empty() {
                        self.gen_c_expr(&node.children[0]);
                    }
                    self.write(")");
                } else if fname == "@as" {
                    // Zig @as(Type, value) → (Type)(value) in C
                    //
                    // W699 rung 9: the type argument was emitted as an
                    // EXPRESSION, so `@as(usize, x)` became `(usize)(x)` --
                    // "use of undeclared identifier 'usize'". Every other site
                    // in this backend maps a t27 type name through `type_to_c`;
                    // this one printed the identifier it found. Invisible until
                    // the bodies containing these casts stopped being discarded.
                    if node.children.len() >= 2 {
                        self.write("(");
                        let ty = &node.children[0];
                        if ty.kind == NodeKind::ExprIdentifier && !ty.name.is_empty() {
                            self.write(Self::type_to_c(&ty.name));
                        } else {
                            self.gen_c_expr(ty);
                        }
                        self.write(")(");
                        self.gen_c_expr(&node.children[1]);
                        self.write(")");
                    } else if !node.children.is_empty() {
                        self.gen_c_expr(&node.children[0]);
                    }
                } else if fname == "@intCast" || fname == "@truncate" {
                    // Zig cast builtins → pass through the value argument
                    if !node.children.is_empty() {
                        self.write("(");
                        self.gen_c_expr(&node.children[0]);
                        self.write(")");
                    }
                } else if fname.starts_with("gf16_") {
                    // GF16 builtins — emit as function call
                    self.write(fname);
                    self.write("(");
                    for (i, arg) in node.children.iter().enumerate() {
                        if i > 0 {
                            self.write(", ");
                        }
                        self.gen_c_expr(arg);
                    }
                    self.write(")");
                } else {
                    self.write(fname);
                    self.write("(");
                    for (i, arg) in node.children.iter().enumerate() {
                        if i > 0 {
                            self.write(", ");
                        }
                        self.gen_c_expr(arg);
                    }
                    self.write(")");
                }
            }
            NodeKind::ExprBinary => {
                if node.children.len() >= 2 {
                    let op = node.extra_op.as_str();
                    if op == "**" {
                        // Zig repeat operator: val ** count → memset-style
                        // Emit as comment since C has no direct equivalent
                        self.write("/* repeat: ");
                        self.gen_c_expr(&node.children[0]);
                        self.write(" ** ");
                        self.gen_c_expr(&node.children[1]);
                        self.write(" */ {0}");
                    } else {
                        let c_op = match op {
                            "and" => "&&",
                            "or" => "||",
                            // Wrapping operators collapse to the plain operator:
                            // C unsigned arithmetic already wraps modulo 2^N.
                            "+%" => "+",
                            "-%" => "-",
                            "*%" => "*",
                            other => other,
                        };
                        self.write("(");
                        self.gen_c_expr(&node.children[0]);
                        self.write(&format!(" {} ", c_op));
                        self.gen_c_expr(&node.children[1]);
                        self.write(")");
                    }
                }
            }
            NodeKind::ExprUnary => {
                let op = node.extra_op.trim();
                if op == "try" {
                    // Zig try — just emit the inner expression in C
                    if !node.children.is_empty() {
                        self.gen_c_expr(&node.children[0]);
                    }
                } else {
                    let c_op = match op {
                        "not" => "!",
                        other => other,
                    };
                    self.write(c_op);
                    if !node.children.is_empty() {
                        self.gen_c_expr(&node.children[0]);
                    }
                }
            }
            NodeKind::ExprFieldAccess => {
                if !node.children.is_empty() {
                    self.gen_c_expr(&node.children[0]);
                }
                self.write(".");
                if node.name.chars().all(|c| c.is_ascii_digit()) {
                    // Tuple index: the C tuple structs name their fields f0/f1/...
                    self.write(&format!("f{}", node.name));
                } else {
                    self.write(&node.name);
                }
            }
            NodeKind::ExprIndex => {
                if node.children.len() >= 2 {
                    self.gen_c_expr(&node.children[0]);
                    // [T; N] values are by-value structs: index the .v member.
                    if node.children[0].kind == NodeKind::ExprIdentifier
                        && self.array_typed_names.contains(&node.children[0].name)
                    {
                        self.write(".v");
                    }
                    self.write("[");
                    self.gen_c_expr(&node.children[1]);
                    self.write("]");
                }
            }
            NodeKind::ExprSwitch => {
                // C doesn't have switch expressions. Emit as nested ternary.
                if node.children.len() > 1 {
                    let cases = &node.children[1..];
                    self.gen_c_switch_expr(node, cases);
                } else {
                    self.write("0 /* empty switch */");
                }
            }
            NodeKind::ExprIf => {
                // Ternary operator
                self.write("(");
                if !node.children.is_empty() {
                    self.gen_c_expr(&node.children[0]);
                }
                self.write(") ? (");
                if node.children.len() > 1 {
                    self.gen_c_expr(&node.children[1]);
                }
                self.write(") : (");
                if node.children.len() > 2 {
                    self.gen_c_expr(&node.children[2]);
                } else {
                    self.write("0");
                }
                self.write(")");
            }
            NodeKind::ExprArrayLiteral => {
                // The parser stores the literal's ELEMENT TEXT in extra_size
                // ("1,2,3" for a list, "0;4" for a repeat) with no children.
                // Emit a brace initializer; the repeat form uses a GNU
                // designated range (gcc and clang).
                // W699 rung 3: TWO different nodes reach this arm, and only one
                // of them keeps its elements in `extra_size`.
                //
                //   [1, 2, 3]        -> extra_size "1,2,3", no children
                //   [_]i32{1, 2, 3}  -> extra_size "_" (the DIMENSION),
                //                       extra_type "i32", elements in children
                //
                // Reading `extra_size` for the second form printed the dimension
                // as the element list: `int32_t a[3] = { .v = { _ } };` -- "use
                // of undeclared identifier '_'". The elements were parsed, held,
                // and never emitted.
                //
                // The `{ .v = { ... } }` wrapper goes with them. It initialises a
                // struct with a member `v`, and the declaration beside it is a
                // plain C array. Measured before removing it: of the 156 specs
                // whose generated C `cc` accepts, ZERO contain `.v = {` -- the
                // wrapper has never appeared in a single piece of C this compiler
                // produced that a C compiler would take.
                if !node.children.is_empty() {
                    self.write("{ ");
                    for (i, e) in node.children.iter().enumerate() {
                        if i > 0 {
                            self.write(", ");
                        }
                        self.gen_c_expr(e);
                    }
                    self.write(" }");
                    return;
                }
                let txt = node.extra_size.trim().to_string();
                if let Some((val, count)) = txt.rsplit_once(';') {
                    self.write(&format!(
                        "{{ [0 ... ({}) - 1] = {} }}",
                        count.trim(),
                        val.trim()
                    ));
                } else if !txt.is_empty() {
                    let mut elems: Vec<String> = Vec::new();
                    let mut depth = 0i32;
                    let mut cur = String::new();
                    for ch in txt.chars() {
                        match ch {
                            '(' | '[' => {
                                depth += 1;
                                cur.push(ch);
                            }
                            ')' | ']' => {
                                depth -= 1;
                                cur.push(ch);
                            }
                            ',' if depth == 0 => {
                                elems.push(cur.trim().to_string());
                                cur.clear();
                            }
                            _ => cur.push(ch),
                        }
                    }
                    if !cur.trim().is_empty() {
                        elems.push(cur.trim().to_string());
                    }
                    self.write(&format!("{{ {} }}", elems.join(", ")));
                } else {
                    self.write("{ 0 }");
                }
            }
            NodeKind::ExprStructLit => {
                // C99 compound literal
                self.write(&format!("({}){{ ", node.name));
                for (i, field) in node.children.iter().enumerate() {
                    if i > 0 {
                        self.write(", ");
                    }
                    self.write(&format!(".{} = ", field.name));
                    if !field.children.is_empty() {
                        self.gen_c_expr(&field.children[0]);
                    }
                }
                self.write(" }");
            }
            NodeKind::ExprReturn => {
                self.write("return ");
                if !node.children.is_empty() {
                    // A returned array literal needs the compound-literal cast
                    // to the fn's [T; N] struct type; bare braces are not an
                    // expression in C.
                    if node.children[0].kind == NodeKind::ExprArrayLiteral {
                        if let Some(name) = self.current_ret_array_type.clone() {
                            self.write(&format!("({})", name));
                        }
                    }
                    self.gen_c_expr(&node.children[0]);
                }
            }
            NodeKind::ExprCast => {
                if !node.children.is_empty() {
                    let target = node
                        .extra_type
                        .split('[')
                        .next()
                        .unwrap_or("")
                        .trim();
                    self.write(&format!("(({})(", Self::type_to_c(target)));
                    self.gen_c_expr(&node.children[0]);
                    self.write("))");
                }
            }
            NodeKind::ExprTuple => {
                // Tuple literal -> C99 compound literal of the current
                // function's hoisted tuple struct: `(T){ e0, e1 }`. The field
                // order matches the typedef (f0, f1, ...).
                if let Some((name, _)) = self
                    .current_ret_tuple_type
                    .as_deref()
                    .and_then(Self::c_tuple_info)
                {
                    self.write(&format!("({}){{ ", name));
                } else {
                    self.write("{ ");
                }
                for (i, elem) in node.children.iter().enumerate() {
                    if i > 0 {
                        self.write(", ");
                    }
                    self.gen_c_expr(elem);
                }
                self.write(" }");
            }
            _ => {
                self.write(&format!("/* unsupported: {:?} */", node.kind));
            }
        }
    }

    /// Generate a switch expression as nested ternary operators
    fn gen_c_switch_expr(&mut self, switch_node: &Node, cases: &[Node]) {
        // For each case: (switch_expr == case_val) ? result : next_case
        // The switch_node.children[0] is the expression being switched on
        if cases.is_empty() {
            self.write("0 /* no cases */");
            return;
        }

        let last_idx = cases.len() - 1;
        for (i, case) in cases.iter().enumerate() {
            if case.kind == NodeKind::ConstDecl {
                let is_else = case.name.is_empty() || case.name == "else";
                let is_last = i == last_idx;

                if is_else {
                    // else/default case - just emit the value
                    if !case.children.is_empty() {
                        self.gen_c_expr(&case.children[0]);
                    } else {
                        self.write("0");
                    }
                } else {
                    // Normal case: (switch_expr == val) ? result : ...
                    self.write("(");
                    self.gen_c_expr(&switch_node.children[0]);
                    self.write(" == ");
                    // Enum variant name
                    let is_numeric = case.name.starts_with(|c: char| c.is_ascii_digit())
                        || (case.name.starts_with('-') && case.name.len() > 1);
                    if is_numeric {
                        self.write(&case.name);
                    } else {
                        self.write(&case.name.to_uppercase());
                    }
                    self.write(") ? (");
                    if !case.children.is_empty() {
                        self.gen_c_expr(&case.children[0]);
                    } else {
                        self.write("0");
                    }
                    self.write(")");

                    if !is_last {
                        self.write(" : ");
                    } else {
                        self.write(" : 0");
                    }
                }
            }
        }
    }
}

// ============================================================================
// Import Path Resolution for compile-project
// ============================================================================

/// Resolve a `use X::Y` import to the correct relative .zig path.
///
/// Given:
///   - `use_value`: the full use path, e.g. "base::types"
///   - `use_name`: the short alias, e.g. "types"
///   - `current_rel_path`: relative path of the file being compiled, e.g. "ar/asp_solver"
///   - `module_map`: maps "base::types" → "base/types"
///
/// Returns a relative .zig path like "../base/types.zig"
fn resolve_import_path(
    use_value: &str,
    use_name: &str,
    current_rel_path: &str,
    module_map: &std::collections::HashMap<String, String>,
) -> String {
    // Try to find the target in the module map
    let target_rel = if let Some(rel) = module_map.get(use_value) {
        rel.clone()
    } else if let Some(rel) = module_map.get(use_name) {
        rel.clone()
    } else {
        // Fallback: convert use_value "base::types" → "base/types"
        use_value.replace("::", "/")
    };

    // Compute relative path from current file's directory to the target
    let current_dir = if let Some(pos) = current_rel_path.rfind('/') {
        &current_rel_path[..pos]
    } else {
        ""
    };

    let target_dir = if let Some(pos) = target_rel.rfind('/') {
        &target_rel[..pos]
    } else {
        ""
    };

    let target_file = if let Some(pos) = target_rel.rfind('/') {
        &target_rel[pos + 1..]
    } else {
        &target_rel
    };

    // Split directories into components
    let current_parts: Vec<&str> = if current_dir.is_empty() {
        Vec::new()
    } else {
        current_dir.split('/').collect()
    };

    let target_parts: Vec<&str> = if target_dir.is_empty() {
        Vec::new()
    } else {
        target_dir.split('/').collect()
    };

    // Find common prefix length
    let mut common = 0;
    for (a, b) in current_parts.iter().zip(target_parts.iter()) {
        if a == b {
            common += 1;
        } else {
            break;
        }
    }

    // Build relative path: go up from current, then down to target
    let mut rel_parts: Vec<String> = Vec::new();
    let ups = current_parts.len() - common;
    for _ in 0..ups {
        rel_parts.push("..".to_string());
    }
    for part in &target_parts[common..] {
        rel_parts.push(part.to_string());
    }
    rel_parts.push(format!("{}.zig", target_file));

    rel_parts.join("/")
}

// ============================================================================
// Compiler Interface
// ============================================================================

/// The binary operator inside a compound assignment: "|=" -> "|".
/// All three backends tested `extra_op == "+="` and fell through to " = " otherwise,
/// so accepting a new compound operator without touching them would have emitted
/// `x = rhs` for `x |= rhs` -- a miscompilation rather than an error.
fn compound_binop(extra_op: &str) -> Option<&'static str> {
    match extra_op {
        "+=" => Some("+"),
        "-=" => Some("-"),
        "*=" => Some("*"),
        // `/=` was missing, and the three call sites all fall back to a plain
        // ` = `. So `scaled /= 2.0;` was emitted as `scaled = 2.0;` -- the
        // division dropped and the variable overwritten with the divisor -- by
        // the Zig, C AND Rust backends alike. Five occurrences in three specs
        // (numeric/tf3.t27:139 and :253, ternary/hybrid_bigint.t27:168 and
        // :235, server/sse.t27:265), every one of them valid output in the
        // target language and none of them the stated program.
        //
        // `%=`, `<<=` and `>>=` do not occur in the corpus today. They are
        // here because the failure mode of a missing entry is silence, and the
        // next spec to use one must not pay for that.
        "/=" => Some("/"),
        "%=" => Some("%"),
        "<<=" => Some("<<"),
        ">>=" => Some(">>"),
        "|=" => Some("|"),
        "&=" => Some("&"),
        "^=" => Some("^"),
        _ => None,
    }
}

/// A numeric lexeme split into its digits and its declared width.
///
/// `1u64` -> `("1", "u64")`. The suffix rides in the lexeme so that `value`
/// stays exactly what every emitter already prints, and the declared width
/// becomes available in `extra_type` for the one place that needs it.
fn split_number_suffix(lexeme: &str) -> (String, String) {
    const SUFFIXES: &[&str] = &[
        "usize", "isize", "comptime_int", "u8", "u16", "u32", "u64", "i8", "i16", "i32",
        "i64", "f16", "f32", "f64",
    ];
    for suf in SUFFIXES {
        if let Some(head) = lexeme.strip_suffix(suf) {
            if !head.is_empty() && head.starts_with(|c: char| c.is_ascii_digit()) {
                return (head.to_string(), (*suf).to_string());
            }
        }
    }
    (lexeme.to_string(), String::new())
}

/// The statement inside whatever block node the parser wrapped it in.
///
/// A `while (c) : (step)` puts its continue expression at `children[1]`, but
/// wrapped: emitting that node directly prints `/* unsupported expr: Module */`
/// in C and Verilog alike. Descend through single-child containers until a real
/// statement appears.
fn unwrap_single(node: &Node) -> &Node {
    let mut n = node;
    while n.kind != NodeKind::StmtAssign && n.children.len() == 1 {
        n = &n.children[0];
    }
    n
}

/// The assignment operator to emit for a statement, as source text.
///
/// A compound operator this compiler does not know must not become a plain
/// store. Every spelling in the three targets is the same as t27's, so an
/// unrecognised one is passed through verbatim: it either compiles and means
/// what the spec said, or the target compiler refuses it by name. Both are
/// better than ` = `, which compiles and means something else.
fn assign_op_text(extra_op: &str) -> String {
    if let Some(op) = compound_binop(extra_op) {
        return format!(" {}= ", op);
    }
    let t = extra_op.trim();
    if t.len() >= 2 && t.ends_with('=') && !matches!(t, "==" | "!=" | "<=" | ">=") {
        return format!(" {} ", t);
    }
    " = ".to_string()
}

pub struct Compiler;

#[allow(dead_code)]
impl Compiler {
    /// W644: expose the keyword predicate so a gate can check the ARTEFACT
    /// rather than the emit sites, which T53 showed cannot be enumerated.
    pub fn is_verilog_keyword(name: &str) -> bool {
        VerilogCodegen::verilog_keywords().contains(&name)
    }

    pub fn compile(source: &str) -> Result<String, String> {
        let lexer = Lexer::new(source);
        let mut parser = Parser::new(lexer);
        let mut ast = parser.parse()?;
        optimize(&mut ast, &OptConfig::default());
        let mut codegen = Codegen::new();
        codegen.gen_zig(&ast);
        Ok(Self::zig_discard_dead_locals(codegen.into_string()))
    }

    /// Zig errors on unused locals AND on pointless discards of used ones, and
    /// whether a binding is used can only be decided on the EMITTED text (the
    /// optimizer const-inlines uses while leaving the declarations behind). So:
    /// post-pass over the generated Zig, per top-level block (fn/test), count
    /// identifier occurrences; a `const NAME = ...;` whose name never occurs
    /// again in its block gets `_ = NAME;` inserted right after it.
    fn zig_discard_dead_locals(src: String) -> String {
        fn ident_count(hay: &str, needle: &str) -> usize {
            let bytes = hay.as_bytes();
            let mut count = 0;
            let mut start = 0;
            while let Some(pos) = hay[start..].find(needle) {
                let at = start + pos;
                let before_ok = at == 0
                    || !(bytes[at - 1].is_ascii_alphanumeric() || bytes[at - 1] == b'_');
                let end = at + needle.len();
                let after_ok = end >= bytes.len()
                    || !(bytes[end].is_ascii_alphanumeric() || bytes[end] == b'_');
                if before_ok && after_ok {
                    count += 1;
                }
                start = at + needle.len().max(1);
            }
            count
        }
        let lines: Vec<&str> = src.lines().collect();
        // Top-level blocks start at column 0 and end at the next column-0 line.
        let mut block_end = vec![lines.len(); lines.len()];
        let mut next_top = lines.len();
        for i in (0..lines.len()).rev() {
            block_end[i] = next_top;
            let l = lines[i];
            if !l.is_empty() && !l.starts_with(' ') && !l.starts_with('}') {
                next_top = i;
            }
        }
        let mut out: Vec<String> = Vec::with_capacity(lines.len() + 16);
        for (i, line) in lines.iter().enumerate() {
            out.push((*line).to_string());
            let t = line.trim_start();
            let Some(rest) = t.strip_prefix("const ") else {
                continue;
            };
            if !t.contains('=') || !line.starts_with(' ') {
                continue; // module-level consts (column 0) are exempt in Zig
            }
            // One or more bindings on the line: `const a = ...` or the
            // destructuring form `const a, const b = ...`.
            let decl_part = t.split('=').next().unwrap_or("");
            let names: Vec<String> = decl_part
                .split("const ")
                .skip(1)
                .map(|seg| {
                    // Plain `name` or the primitive-shadow form `@"name"` --
                    // keep the wrapper so use-counting matches emitted text.
                    if let Some(rest) = seg.strip_prefix("@\"") {
                        let inner: String = rest.chars().take_while(|c| *c != '"').collect();
                        if inner.is_empty() {
                            String::new()
                        } else {
                            format!("@\"{}\"", inner)
                        }
                    } else {
                        seg.chars()
                            .take_while(|c| c.is_ascii_alphanumeric() || *c == '_')
                            .collect::<String>()
                    }
                })
                // W608: `_` is the discard, never a binding to inline. Without
                // this the pass emitted `_ = _;` -- discarding the discard and
                // losing the statement's actual operand.
                .filter(|n| !n.is_empty() && n != "_")
                .collect();
            let indent: String = line.chars().take_while(|c| *c == ' ').collect();
            for name in names {
                // Scan only until the NAME is redeclared (shadowed) -- a later
                // `const name = ...` line is a new binding, not a use.
                let mut scan_end = block_end[i];
                for (j, later) in lines[i + 1..block_end[i]].iter().enumerate() {
                    let lt = later.trim_start();
                    if lt.strip_prefix("const ").map_or(false, |r| {
                        r.starts_with(&name)
                            && !r[name.len()..]
                                .chars()
                                .next()
                                .is_some_and(|c| c.is_ascii_alphanumeric() || c == '_')
                    }) || lt.strip_prefix("var ").map_or(false, |r| {
                        r.starts_with(&name)
                            && !r[name.len()..]
                                .chars()
                                .next()
                                .is_some_and(|c| c.is_ascii_alphanumeric() || c == '_')
                    }) {
                        scan_end = i + 1 + j;
                        break;
                    }
                }
                let block_rest = lines[i + 1..scan_end].join("\n");
                if ident_count(&block_rest, &name) == 0 {
                    out.push(format!("{}_ = {}; // dead after const-inlining", indent, name));
                }
            }
        }
        let mut joined = out.join("\n");
        if src.ends_with('\n') {
            joined.push('\n');
        }
        joined
    }

    /// W526/W527: reject multi-dimensional arrays of aggregate types that the
    /// Verilog backend cannot yet lower cleanly. Scalar-struct arrays with only
    /// primitive scalar fields are allowed through because W527 adds packed-vector
    /// AoS lowering for them. Returns a clear diagnostic the caller can surface.
    fn detect_unsupported_verilog_locals(
        ast: &Node,
        structs: &std::collections::HashMap<String, Vec<(String, String)>>,
    ) -> Result<(), String> {
        static PRIMITIVE_TYPES: &[&str] = &[
            "u8", "u16", "u32", "u64", "i8", "i16", "i32", "i64", "f32", "f64",
            "bool", "void", "string",
        ];
        fn is_primitive(t: &str) -> bool {
            PRIMITIVE_TYPES.contains(&t.trim())
        }

        for child in &ast.children {
            if child.kind != NodeKind::StmtLocal {
                continue;
            }
            let ty = &child.extra_type;
            // Only multi-dimensional array types trigger this boundary.
            if !ty.contains("][") {
                continue;
            }
            // Extract element type after the last closing bracket.
            let elem = ty.rsplit_once(']').map(|(_, e)| e).unwrap_or(ty).trim();
            if elem.is_empty() || is_primitive(elem) {
                continue;
            }
            if VerilogCodegen::is_lowerable_scalar_struct(elem, structs) {
                continue;
            }
            return Err(format!(
                "unsupported multi-dimensional array of aggregate type `{}` for local variable `{}` at line {}: 2-D array-of-struct lowering is not yet implemented for non-scalar structs/enums (see docs/reports/W469_2D_STRUCT_ARRAY_DESIGN.md)",
                ty, child.name, child.line
            ));
        }
        // Module-level declarations live directly under the Module node; nested
        // bodies (functions) are also scanned recursively with the same struct map.
        for child in &ast.children {
            Self::detect_unsupported_verilog_locals(child, structs)?;
        }
        Ok(())
    }

    /// #2275: rewrite `[CONST_NAME]` array dimensions to their literal values
    /// in every `extra_type`/`extra_size` string. Only module-level consts whose
    /// initializer is a bare integer literal participate; anything else is left
    /// exactly as written.
    fn resolve_symbolic_dims(ast: &mut Node) {
        let mut consts: std::collections::HashMap<String, String> =
            std::collections::HashMap::new();
        fn literal_value(decl: &Node) -> Option<String> {
            let mut v = decl.value.trim().to_string();
            if v.is_empty() {
                for c in &decl.children {
                    let cv = c.value.trim();
                    if !cv.is_empty() {
                        v = cv.to_string();
                        break;
                    }
                }
            }
            let cleaned: String = v.chars().filter(|c| *c != '_').collect();
            cleaned.parse::<usize>().ok().map(|n| n.to_string())
        }
        fn collect(node: &Node, out: &mut std::collections::HashMap<String, String>) {
            if node.kind == NodeKind::ConstDecl && !node.name.is_empty() {
                if let Some(v) = literal_value(node) {
                    out.entry(node.name.clone()).or_insert(v);
                }
            }
            for c in &node.children {
                collect(c, out);
            }
        }
        collect(ast, &mut consts);
        if consts.is_empty() {
            return;
        }
        fn subst(text: &str, consts: &std::collections::HashMap<String, String>) -> String {
            if !text.contains('[') {
                return text.to_string();
            }
            let mut out = String::with_capacity(text.len());
            let mut rest = text;
            while let Some(open) = rest.find('[') {
                let Some(close_rel) = rest[open..].find(']') else {
                    break;
                };
                let close = open + close_rel;
                let inner = rest[open + 1..close].trim();
                out.push_str(&rest[..open + 1]);
                match consts.get(inner) {
                    Some(v) if !inner.is_empty() => out.push_str(v),
                    _ => out.push_str(&rest[open + 1..close]),
                }
                out.push(']');
                rest = &rest[close + 1..];
            }
            out.push_str(rest);
            out
        }
        fn walk(node: &mut Node, consts: &std::collections::HashMap<String, String>) {
            if node.extra_type.contains('[') {
                node.extra_type = subst(&node.extra_type, consts);
            }
            if !node.extra_size.is_empty() {
                node.extra_size = subst(&format!("[{}]", node.extra_size), consts)
                    .trim_start_matches('[')
                    .trim_end_matches(']')
                    .to_string();
            }
            for c in &mut node.children {
                walk(c, consts);
            }
        }
        walk(ast, &consts);
    }

    fn collect_struct_decls(
        ast: &Node,
    ) -> std::collections::HashMap<String, Vec<(String, String)>> {
        let mut structs = std::collections::HashMap::new();
        fn walk(node: &Node, structs: &mut std::collections::HashMap<String, Vec<(String, String)>>) {
            if node.kind == NodeKind::StructDecl {
                let fields: Vec<(String, String)> = node
                    .children
                    .iter()
                    .map(|f| (f.name.clone(), f.extra_type.clone()))
                    .collect();
                structs.insert(node.name.clone(), fields);
            }
            for child in &node.children {
                walk(child, structs);
            }
        }
        walk(ast, &mut structs);
        structs
    }

    pub fn compile_verilog(source: &str) -> Result<String, String> {
        Self::compile_verilog_with_options(source, false, None)
    }

    /// `compile_verilog`, told where the spec lives.
    ///
    /// Only a caller holding the path can resolve `use base::ops;` to a file,
    /// and until it is resolved the backend cannot know that `Trit.neg` --
    /// which it lowers to the identifier `Trit_neg` -- needs a `localparam`.
    /// Callers holding only a source string keep the old behaviour.
    pub fn compile_verilog_at(
        source: &str,
        spec_path: &std::path::Path,
    ) -> Result<String, String> {
        Self::compile_verilog_with_options(source, false, Some(spec_path))
    }

    pub fn compile_verilog_for_simulation(source: &str) -> Result<String, String> {
        Self::compile_verilog_with_options(source, true, None)
    }

    /// #2241: the simulation path passed `None` as the spec path, so the
    /// import-aware registries (enums, structs) never loaded and every
    /// `Enum.variant` or imported-struct field in a TEST BLOCK emitted an
    /// unbound name -- icarus-simulate failed with 95 elaboration errors on
    /// mac while the plain gen-verilog of the same spec elaborated clean.
    pub fn compile_verilog_for_simulation_at(
        source: &str,
        spec_path: &std::path::Path,
    ) -> Result<String, String> {
        Self::compile_verilog_with_options(source, true, Some(spec_path))
    }

    fn compile_verilog_with_options(
        source: &str,
        emit_test_assertions: bool,
        spec_path: Option<&std::path::Path>,
    ) -> Result<String, String> {
        let lexer = Lexer::new(source);
        let mut parser = Parser::new(lexer);
        let mut ast = parser.parse()?;
        // W526: catch unsupported multi-dimensional aggregate arrays before the
        // optimizer drops the declaration or before we emit broken placeholders.
        // Build the struct map from the *full* module AST so nested function bodies
        // can still recognize module-level scalar structs as lowerable.
        let structs = Self::collect_struct_decls(&ast);
        // #2275 half two, layer one: array dimensions spelled as CONST NAMES
        // ([NUM_MAC_UNITS]MACUnit) never parsed -- parse_array_type wants
        // digits, so the whole packed-array machinery (decl width, literal
        // lowering, element access) fell through to TODO placeholders and
        // flattened names. Substitute integer-literal module consts into
        // every type/dimension string BEFORE codegen, once, here.
        Self::resolve_symbolic_dims(&mut ast);
        Self::detect_unsupported_verilog_locals(&ast, &structs)?;
        optimize(&mut ast, &OptConfig::default());
        let mut codegen = VerilogCodegen::with_options(emit_test_assertions);
        if let Some(path) = spec_path {
            codegen.set_imported_enums(crate::use_resolve::imported_enums(path, source));
            codegen.set_imported_structs(crate::use_resolve::imported_structs(path, source));
        }
        codegen.gen_verilog(&ast);
        Ok(codegen.into_string())
    }

    pub fn compile_c(source: &str) -> Result<String, String> {
        let lexer = Lexer::new(source);
        let mut parser = Parser::new(lexer);
        let ast = parser.parse()?;
        // Emit FAITHFUL C from the AST; the C compiler optimizes downstream. See
        // the note on compile_rust: t27c's optimizer drops reassigned locals and
        // const-inlines `let`, corrupting the source-level output. Fixes #1455.
        let mut codegen = CCodegen::new();
        codegen.gen_c(&ast);
        Ok(codegen.into_string())
    }

    pub fn compile_rust(source: &str) -> Result<String, String> {
        let lexer = Lexer::new(source);
        let mut parser = Parser::new(lexer);
        let ast = parser.parse()?;
        // Emit FAITHFUL Rust from the AST. Do NOT run t27c's own optimizer on the
        // Rust backend: several of its passes (const-propagation and the
        // unconditional copy-propagation / dead-store passes) corrupt a
        // reassigned mutable local -- e.g. `var x = 0; ... x = a;` loses its
        // declaration while its uses remain, producing E0425. rustc/LLVM optimize
        // the emitted code far more reliably, so faithful codegen is both correct
        // and sufficient here. Verilog/Zig/C backends keep their own pipelines.
        // Fixes gHashTag/t27#1455.
        let mut codegen = RustCodegen::new();
        codegen.collect_static_muts(&ast);
        codegen.gen_rust(&ast);
        Ok(codegen.into_string())
    }

    /// Parse, and REQUIRE that the whole input was consumed.
    ///
    /// W577: `parse_ast` returns Ok as soon as the module body loop stops, and
    /// that loop stops on `}` -- so a stray closing brace in a semicolon-form
    /// module silently ends the file. That is how 29 specs, every IGLA CODER
    /// and IGLA RACE spec among them, were truncated for years while reporting
    /// success (W569). An unterminated string does the same thing and discards
    /// the file entirely.
    ///
    /// A parser that stops early and returns Ok is indistinguishable from one
    /// that finished. This is the distinguisher.
    pub fn parse_ast_strict(source: &str) -> Result<Node, String> {
        let lexer = Lexer::new(source);
        let mut parser = Parser::new(lexer);
        let ast = parser.parse()?;
        if parser.current.kind != TokenKind::Eof {
            return Err(format!(
                "input not fully consumed: stopped at {:?} ('{}') at line {}:{}, after {} top-level declaration(s)",
                parser.current.kind,
                parser.current.lexeme,
                parser.current.line,
                parser.current.col,
                ast.children.len()
            ));
        }
        Ok(ast)
    }

    /// W633: parse, and report how many tokens top-level recovery DISCARDED.
    /// `parse_ast_strict` asks "did the parser reach EOF?", which is satisfied
    /// by a parse that reached EOF by dropping tokens on the way. This asks the
    /// question that one meant to ask. See T42.
    pub fn parse_ast_accounted(source: &str) -> Result<(Node, usize), String> {
        let lexer = Lexer::new(source);
        let mut parser = Parser::new(lexer);
        let ast = parser.parse()?;
        Ok((ast, parser.dropped_top_level_tokens()))
    }

    /// W699 rung 9: one record per whole-block fallback, `(line, why, clause)`.
    ///
    /// `bdd-block-fallback` is 93% of everything this parser discards and it is
    /// EIGHT different defects sharing one name. This is the distribution.
    pub fn parse_ast_bdd_fallbacks(
        source: &str,
    ) -> Result<Vec<(u32, &'static str, String)>, String> {
        let lexer = Lexer::new(source);
        let mut parser = Parser::new(lexer);
        let _ = parser.parse()?;
        Ok(parser.bdd_fallbacks.clone())
    }

    /// W699: the discarded tokens with the recovery that threw each away, as
    /// `(line, lexeme, channel)`.
    ///
    /// The channel vector is pushed in lockstep with the spans. If the two
    /// lengths ever disagree this REFUSES rather than zipping to the shorter --
    /// see the note at the check.
    pub fn parse_ast_dropped_records(source: &str) -> Result<Vec<(u32, String, &'static str)>, String> {
        let lexer = Lexer::new(source);
        let mut parser = Parser::new(lexer);
        let _ = parser.parse()?;
        // W699: `zip` truncates to the shorter side, and that is exactly how a
        // missed push site hides. Two sites WERE missed on the first pass -- 27
        // tokens across 27 specs -- and the only reason it surfaced was a total
        // that did not match `parse-complete`'s. Refuse instead of truncating.
        if parser.dropped_spans.len() != parser.dropped_channels.len() {
            return Err(format!(
                "drop accounting is inconsistent: {} span(s) but {} channel(s). \
                 A recovery site records a span without naming its channel; find \
                 it rather than reading the shorter list.",
                parser.dropped_spans.len(),
                parser.dropped_channels.len()
            ));
        }
        Ok(parser
            .dropped_spans
            .iter()
            .cloned()
            .zip(parser.dropped_channels.iter().copied())
            .map(|((l, x), c)| (l, x, c))
            .collect())
    }

    /// W634: the discarded tokens themselves, as `(line, lexeme)`.
    pub fn parse_ast_dropped_spans(source: &str) -> Result<Vec<(u32, String)>, String> {
        let lexer = Lexer::new(source);
        let mut parser = Parser::new(lexer);
        let _ = parser.parse()?;
        Ok(parser.dropped_spans.clone())
    }

    pub fn parse_ast(source: &str) -> Result<Node, String> {
        // [BUG 1 FIX] Do NOT call lexer.tokenize() — let Parser use next_token() directly
        let lexer = Lexer::new(source);

        let mut parser = Parser::new(lexer);
        parser.parse()
    }

    /// Compile a single file as part of a project, resolving imports using the module map.
    /// `current_rel_path` is the relative path of the current file (e.g. "base/types").
    /// `module_map` maps "namespace::module" → "namespace/module" relative paths.
    pub fn compile_project_file(
        source: &str,
        current_rel_path: &str,
        module_map: &std::collections::HashMap<String, String>,
    ) -> Result<String, String> {
        let lexer = Lexer::new(source);
        let mut parser = Parser::new(lexer);
        let ast = parser.parse()?;

        let mut codegen = Codegen::new();
        codegen.gen_zig_project(&ast, current_rel_path, module_map);
        Ok(codegen.into_string())
    }

    pub fn typecheck(source: &str) -> Result<TypeCheckResult, String> {
        let lexer = Lexer::new(source);
        let mut parser = Parser::new(lexer);
        let ast = parser.parse()?;
        Ok(typecheck_ast(&ast))
    }

    pub fn compile_verilog_hir(source: &str) -> Result<String, String> {
        let lexer = Lexer::new(source);
        let mut parser = Parser::new(lexer);
        let ast = parser.parse()?;
        let mut hir = AstToHir::convert(&ast)?;
        let mut opt = HirOptimizer::new();
        opt.optimize(&mut hir);
        let mut emitter = HirVerilogEmitter::new();
        emitter.emit(&hir);
        Ok(emitter.into_string())
    }

    pub fn debug_hir(source: &str) -> Result<String, String> {
        let lexer = Lexer::new(source);
        let mut parser = Parser::new(lexer);
        let ast = parser.parse()?;
        let hir = AstToHir::convert(&ast)?;
        Ok(format!("{:#?}", hir))
    }

    /// W534: structural Icarus-lowerability classifier.
    ///
    /// Returns `Ok(true)` when the source uses only constructs that the Verilog
    /// backend can lower to synthesizable Icarus Verilog.  Returns `Ok(false)`
    /// with a reason string when a non-lowerable construct is found.
    ///
    /// This is the Rust side of the lowerability boundary; it is designed to
    /// align with `Trinity.IcarusLowerable.Module.isLowerable` in Lean 4.
    pub fn is_icarus_lowerable(source: &str) -> Result<bool, String> {
        let ast = Self::parse_ast(source)?;
        let structs = Self::collect_struct_decls(&ast);
        let mut functions = std::collections::HashSet::new();
        Self::collect_function_names(&ast, &mut functions);
        Self::ast_is_icarus_lowerable(&ast, &structs, &functions, false)
    }

    /// W534: reason string version of the structural classifier.
    pub fn icarus_lowerability_reason(source: &str) -> Result<String, String> {
        match Self::is_icarus_lowerable(source) {
            Ok(true) => Ok(String::new()),
            Ok(false) => Err("not lowerable".to_string()),
            Err(e) => Err(e),
        }
    }

    fn collect_function_names(
        node: &Node,
        functions: &mut std::collections::HashSet<String>,
    ) {
        if node.kind == NodeKind::FnDecl && !node.name.is_empty() {
            functions.insert(node.name.clone());
        }
        for child in &node.children {
            Self::collect_function_names(child, functions);
        }
    }

    /// W534: true when `ty` is a scalar primitive or an array of lowerable
    /// scalar primitives / scalar structs.
    fn is_icarus_lowerable_type(
        ty: &str,
        structs: &std::collections::HashMap<String, Vec<(String, String)>>,
    ) -> bool {
        let trimmed = ty.trim();
        if trimmed.is_empty() {
            return true; // untyped / inferred
        }
        if VerilogCodegen::is_primitive_scalar_type(trimmed) {
            return true;
        }
        // Strip array dimensions: "[3][4]Pt" -> "Pt", "[3]i16" -> "i16".
        let mut rest = trimmed;
        while rest.starts_with('[') {
            if let Some(end) = rest.find(']') {
                rest = rest[end + 1..].trim();
            } else {
                return false;
            }
        }
        if rest.is_empty() {
            return false;
        }
        if VerilogCodegen::is_primitive_scalar_type(rest) {
            return true;
        }
        VerilogCodegen::is_lowerable_scalar_struct(rest, structs)
    }

    /// W534: true when `name` refers to a lowerable scalar struct or a primitive
    /// scalar/array type.
    fn is_icarus_lowerable_struct_name(
        name: &str,
        structs: &std::collections::HashMap<String, Vec<(String, String)>>,
    ) -> bool {
        VerilogCodegen::is_lowerable_scalar_struct(name, structs)
    }

    /// W534: structural lowerability check for the whole module AST.
    fn ast_is_icarus_lowerable(
        node: &Node,
        structs: &std::collections::HashMap<String, Vec<(String, String)>>,
        functions: &std::collections::HashSet<String>,
        in_loop: bool,
    ) -> Result<bool, String> {
        match node.kind {
            NodeKind::Module => {
                for child in &node.children {
                    if !Self::ast_is_icarus_lowerable(child, structs, functions, in_loop)? {
                        return Ok(false);
                    }
                }
                Ok(true)
            }
            NodeKind::UseDecl => Ok(true), // imports themselves are not lowerability blockers
            NodeKind::ConstDecl | NodeKind::EnumDecl | NodeKind::EnumVariant => Ok(true),
            NodeKind::StructDecl => {
                if let Some(fields) = structs.get(&node.name) {
                    for (_, ty) in fields {
                        if !Self::is_icarus_lowerable_type(ty, structs) {
                            return Ok(false);
                        }
                    }
                }
                Ok(true)
            }
            NodeKind::FnDecl => {
                // Return type and parameter types must be lowerable.
                if !node.extra_return_type.is_empty()
                    && !Self::is_icarus_lowerable_type(&node.extra_return_type, structs)
                {
                    return Ok(false);
                }
                for (_, ty) in &node.params {
                    if !ty.is_empty() && !Self::is_icarus_lowerable_type(ty, structs) {
                        return Ok(false);
                    }
                }
                // Function body.
                for child in &node.children {
                    if !Self::ast_is_icarus_lowerable(child, structs, functions, in_loop)? {
                        return Ok(false);
                    }
                }
                Ok(true)
            }
            NodeKind::TestBlock | NodeKind::BenchBlock | NodeKind::InvariantBlock => {
                // Tests/benches/invariants are host-side harness code and are not
                // part of the synthesizable Icarus model.
                Ok(true)
            }
            NodeKind::StmtLocal | NodeKind::StmtAssign => {
                if !node.extra_type.is_empty()
                    && !Self::is_icarus_lowerable_type(&node.extra_type, structs)
                {
                    return Ok(false);
                }
                for child in &node.children {
                    if !Self::ast_is_icarus_lowerable(child, structs, functions, in_loop)? {
                        return Ok(false);
                    }
                }
                Ok(true)
            }
            NodeKind::StmtIf => {
                for child in &node.children {
                    if !Self::ast_is_icarus_lowerable(child, structs, functions, in_loop)? {
                        return Ok(false);
                    }
                }
                Ok(true)
            }
            NodeKind::StmtFor => {
                // Iterator-style `for` is not lowerable; only range-for is.
                return Ok(false);
            }
            NodeKind::StmtForRange => {
                for child in &node.children {
                    if !Self::ast_is_icarus_lowerable(child, structs, functions, in_loop)? {
                        return Ok(false);
                    }
                }
                Ok(true)
            }
            NodeKind::StmtWhile => {
                // Unbounded `while (true)` cannot be lowered to a fuel-bounded
                // Icarus model.  Bounded while loops (e.g. `while (i < N)`) are
                // accepted structurally; termination is checked by the Lean
                // soundness layer.
                if let Some(cond) = node.children.first() {
                    if cond.kind == NodeKind::ExprLiteral
                        && matches!(cond.value.as_str(), "true" | "1")
                    {
                        return Ok(false);
                    }
                    if !Self::ast_is_icarus_lowerable(cond, structs, functions, false)? {
                        return Ok(false);
                    }
                }
                for child in node.children.iter().skip(1) {
                    if !Self::ast_is_icarus_lowerable(child, structs, functions, true)? {
                        return Ok(false);
                    }
                }
                Ok(true)
            }
            NodeKind::StmtBreak | NodeKind::StmtContinue => {
                // Break/continue are lowerable only inside a loop body.
                Ok(in_loop)
            }
            NodeKind::StmtExpr => {
                if let Some(expr) = node.children.first() {
                    if !Self::ast_is_icarus_lowerable(expr, structs, functions, in_loop)? {
                        return Ok(false);
                    }
                }
                Ok(true)
            }
            NodeKind::ExprReturn => {
                for child in &node.children {
                    if !Self::ast_is_icarus_lowerable(child, structs, functions, in_loop)? {
                        return Ok(false);
                    }
                }
                Ok(true)
            }
            NodeKind::ExprLiteral | NodeKind::ExprIdentifier | NodeKind::ExprEnumValue => {
                Ok(true)
            }
            NodeKind::ExprBinary | NodeKind::ExprUnary | NodeKind::ExprIndex
            | NodeKind::ExprFieldAccess => {
                for child in &node.children {
                    if !Self::ast_is_icarus_lowerable(child, structs, functions, in_loop)? {
                        return Ok(false);
                    }
                }
                Ok(true)
            }
            NodeKind::ExprCast => {
                if !node.extra_type.is_empty()
                    && !Self::is_icarus_lowerable_type(&node.extra_type, structs)
                {
                    return Ok(false);
                }
                for child in &node.children {
                    if !Self::ast_is_icarus_lowerable(child, structs, functions, in_loop)? {
                        return Ok(false);
                    }
                }
                Ok(true)
            }
            NodeKind::ExprCall => {
                let callee = &node.name;
                // Qualified calls (namespace::name) cannot be resolved in the
                // synthesizable Icarus model.
                if callee.contains("::") {
                    return Ok(false);
                }
                // Calls to functions not defined in this module are rejected,
                // except for a small set of builtins that the Verilog backend
                // injects or handles specially.
                if !functions.contains(callee) && !Self::is_icarus_builtin(callee) {
                    return Ok(false);
                }
                for child in &node.children {
                    if !Self::ast_is_icarus_lowerable(child, structs, functions, in_loop)? {
                        return Ok(false);
                    }
                }
                Ok(true)
            }
            NodeKind::ExprStructLit => {
                // The struct being constructed must itself be lowerable.
                if !Self::is_icarus_lowerable_struct_name(&node.name, structs) {
                    return Ok(false);
                }
                for child in &node.children {
                    if !Self::ast_is_icarus_lowerable(child, structs, functions, in_loop)? {
                        return Ok(false);
                    }
                }
                Ok(true)
            }
            NodeKind::ExprArrayLiteral => {
                if !node.extra_type.is_empty()
                    && !Self::is_icarus_lowerable_type(&node.extra_type, structs)
                {
                    return Ok(false);
                }
                for child in &node.children {
                    if !Self::ast_is_icarus_lowerable(child, structs, functions, in_loop)? {
                        return Ok(false);
                    }
                }
                Ok(true)
            }
            NodeKind::ExprSwitch => {
                for child in &node.children {
                    if !Self::ast_is_icarus_lowerable(child, structs, functions, in_loop)? {
                        return Ok(false);
                    }
                }
                Ok(true)
            }
            _ => Ok(true),
        }
    }

    /// W534: built-in functions that the Verilog backend handles without a
    /// source-level definition.
    fn is_icarus_builtin(name: &str) -> bool {
        matches!(
            name,
            "__mul_noop" // injected R-SI-1 multiplication helper
        )
    }
}

// ============================================================================
// AST Optimizer
// ============================================================================

pub struct OptConfig {
    pub enable_folding: bool,
    pub enable_dce: bool,
    pub opt_level: u32,
}

impl Default for OptConfig {
    fn default() -> Self {
        OptConfig {
            enable_folding: true,
            enable_dce: true,
            opt_level: 1,
        }
    }
}

pub struct OptStats {
    pub folds: u32,
    pub dead_removed: u32,
    pub copies_propagated: u32,
    pub strengths_reduced: u32,
    pub cse_eliminated: u32,
    pub dead_stores: u32,
    pub loops_unrolled: u32,
    pub passes: u32,
}

pub fn optimize(ast: &mut Node, config: &OptConfig) -> OptStats {
    let mut stats = OptStats {
        folds: 0,
        dead_removed: 0,
        copies_propagated: 0,
        strengths_reduced: 0,
        cse_eliminated: 0,
        dead_stores: 0,
        loops_unrolled: 0,
        passes: 0,
    };
    if config.opt_level == 0 {
        return stats;
    }
    for _ in 0..config.opt_level {
        optimize_module(ast, config, &mut stats);
        stats.passes += 1;
    }
    stats
}

/// t27#2363: names of MODULE-level state (`var`/`const` declarations and
/// module-level `StmtLocal` regs). A function body that writes one of these is
/// writing state that OUTLIVES the call and is observable outside it -- in the
/// Verilog backend such a `var` is emitted as an `output reg` port. The
/// dead-store analysis is per-function-body, so without this set it sees the
/// write as having no reader and deletes it.
fn collect_module_state_names(node: &Node) -> std::collections::HashSet<String> {
    let mut out = std::collections::HashSet::new();
    for decl in &node.children {
        if matches!(decl.kind, NodeKind::ConstDecl | NodeKind::StmtLocal) && !decl.name.is_empty() {
            out.insert(decl.name.clone());
        }
    }
    out
}

fn optimize_module(node: &mut Node, config: &OptConfig, stats: &mut OptStats) {
    let module_state = collect_module_state_names(node);
    let mut i = 0;
    while i < node.children.len() {
        if node.children[i].kind == NodeKind::FnDecl {
            optimize_fn_body(&mut node.children[i], config, stats, &module_state);
        }
        i += 1;
    }
}

fn optimize_fn_body(
    fn_node: &mut Node,
    config: &OptConfig,
    stats: &mut OptStats,
    module_state: &std::collections::HashSet<String>,
) {
    for child in &mut fn_node.children {
        if child.kind == NodeKind::Module && child.name == "body" {
            optimize_stmts(&mut child.children, config, stats, module_state);
        }
    }
    optimize_stmts(&mut fn_node.children, config, stats, module_state);
}

fn optimize_stmts(
    stmts: &mut Vec<Node>,
    config: &OptConfig,
    stats: &mut OptStats,
    module_state: &std::collections::HashSet<String>,
) {
    if config.enable_dce {
        // W74 (#950): only remove an uninitialized StmtLocal if no later
        // statement assigns to it AND no later statement reads it. Without
        // this check the optimizer silently drops `var x: i32;` even when a
        // subsequent `x = 5; print(x);` needs the declaration.
        let referenced = collect_local_references(stmts);
        let before = stmts.len();
        stmts.retain(|s| !is_dead_local(s, &referenced));
        stats.dead_removed += (before - stmts.len()) as u32;
    }
    if config.enable_folding {
        const_propagate(stmts, stats);
        for stmt in stmts.iter_mut() {
            fold_stmt(stmt, stats);
        }
    }
    copy_propagate(stmts, stats);
    strength_reduce(stmts, stats);
    common_subexpr_elim(stmts, stats);
    dead_store_elim(stmts, stats, module_state);
    loop_unroll(stmts, stats);
}

fn is_dead_local(node: &Node, referenced: &std::collections::HashSet<String>) -> bool {
    if node.kind == NodeKind::StmtLocal
        && node.children.is_empty()
        && !node.extra_type.is_empty()
        && !referenced.contains(&node.name)
    {
        return true;
    }
    false
}

// W74 (#950): collect every identifier name that is either assigned-to or
// read by any statement in this block. Used by is_dead_local to keep
// uninitialized declarations whose name is needed later.
fn collect_local_references(stmts: &[Node]) -> std::collections::HashSet<String> {
    let mut refs: std::collections::HashSet<String> = std::collections::HashSet::new();
    for stmt in stmts {
        collect_refs_in(stmt, &mut refs);
    }
    refs
}

fn collect_refs_in(node: &Node, refs: &mut std::collections::HashSet<String>) {
    // Do not treat a StmtLocal's own declared name as a reference to itself;
    // walk only its initializer expression (if any).
    if node.kind == NodeKind::StmtLocal {
        for child in &node.children {
            collect_refs_in(child, refs);
        }
        return;
    }
    if node.kind == NodeKind::StmtAssign && !node.children.is_empty() {
        // LHS counts as a reference: if a later statement assigns to x, the
        // declaration of x must survive.
        if node.children[0].kind == NodeKind::ExprIdentifier {
            refs.insert(node.children[0].name.clone());
        }
        // RHS and any LHS sub-expressions are walked normally.
        for child in &node.children {
            collect_refs_in(child, refs);
        }
        return;
    }
    if node.kind == NodeKind::ExprIdentifier {
        refs.insert(node.name.clone());
    }
    for child in &node.children {
        collect_refs_in(child, refs);
    }
}

fn fold_stmt(node: &mut Node, stats: &mut OptStats) {
    if node.kind == NodeKind::StmtLocal && !node.children.is_empty() {
        fold_expr(&mut node.children[0], stats);
    }
    if node.kind == NodeKind::StmtAssign && node.children.len() >= 2 {
        fold_expr(&mut node.children[1], stats);
    }
    if node.kind == NodeKind::ExprReturn && !node.children.is_empty() {
        fold_expr(&mut node.children[0], stats);
    }
    if node.kind == NodeKind::StmtExpr && !node.children.is_empty() {
        fold_expr(&mut node.children[0], stats);
    }
    if node.kind == NodeKind::StmtIf {
        if !node.children.is_empty() {
            fold_expr(&mut node.children[0], stats);
        }
        for child in &mut node.children {
            if child.kind == NodeKind::Module {
                for stmt in &mut child.children {
                    fold_stmt(stmt, stats);
                }
            }
        }
    }
    if node.kind == NodeKind::StmtWhile {
        if !node.children.is_empty() {
            fold_expr(&mut node.children[0], stats);
        }
        if node.children.len() > 1 {
            for stmt in &mut node.children[1].children {
                fold_stmt(stmt, stats);
            }
        }
    }
    if node.kind == NodeKind::StmtFor {
        let body_idx = node.children.len().saturating_sub(1);
        if body_idx > 0 {
            fold_expr(&mut node.children[0], stats);
        }
        if !node.children.is_empty() {
            for stmt in &mut node.children[body_idx].children {
                fold_stmt(stmt, stats);
            }
        }
    }
}

fn fold_expr(node: &mut Node, stats: &mut OptStats) {
    if node.kind == NodeKind::ExprBinary && node.children.len() >= 2 {
        fold_expr(&mut node.children[0], stats);
        fold_expr(&mut node.children[1], stats);
        if is_literal(&node.children[0]) && is_literal(&node.children[1]) {
            if let Some(val) = eval_binary(
                &node.children[0].value,
                &node.extra_op,
                &node.children[1].value,
            ) {
                node.kind = NodeKind::ExprLiteral;
                node.value = val;
                node.children.clear();
                stats.folds += 1;
            }
        }
    }
    if node.kind == NodeKind::ExprUnary && !node.children.is_empty() {
        fold_expr(&mut node.children[0], stats);
        if is_literal(&node.children[0]) {
            if let Some(val) = eval_unary(&node.extra_op, &node.children[0].value) {
                node.kind = NodeKind::ExprLiteral;
                node.value = val;
                node.children.clear();
                stats.folds += 1;
            }
        }
    }
}

fn is_literal(node: &Node) -> bool {
    if node.kind != NodeKind::ExprLiteral {
        return false;
    }
    let v = node.value.trim();
    if v.starts_with("0x") || v.starts_with("0X") {
        i64::from_str_radix(&v[2..], 16).is_ok()
    } else {
        v.parse::<i64>().is_ok()
    }
}

fn parse_int_value(s: &str) -> Option<i64> {
    let v = s.trim();
    if v.starts_with("0x") || v.starts_with("0X") {
        i64::from_str_radix(&v[2..], 16).ok()
    } else {
        v.parse().ok()
    }
}

/// Collect all local names that are reassigned anywhere in a statement list.
/// This includes:
/// - Simple assignments: `x = expr` → x is mutable
/// - Index assignments: `arr[i] = expr` → arr is mutable (Rust requires `let mut`)
/// - Field assignments: `s.f = expr` → s is mutable
/// Recurses into if/while/for bodies.
/// Collect names of functions declared with a `bool` return type, at any depth.
fn collect_bool_fns(node: &Node, out: &mut std::collections::HashSet<String>) {
    if node.kind == NodeKind::FnDecl && node.extra_return_type.trim() == "bool" {
        out.insert(node.name.clone());
    }
    for child in &node.children {
        collect_bool_fns(child, out);
    }
}

/// Collect names of locals declared with an explicit `bool` type.
fn collect_bool_locals(nodes: &[Node], out: &mut std::collections::HashSet<String>) {
    for n in nodes {
        if n.kind == NodeKind::StmtLocal && n.extra_type.trim() == "bool" {
            out.insert(n.name.clone());
        }
        collect_bool_locals(&n.children, out);
    }
}

/// Collect the declared return type of every function, at any depth, keyed by
/// name. Used by the Rust backend to widen/narrow a returned call to the
/// return type of the function doing the returning.
fn collect_fn_ret_types(node: &Node, out: &mut std::collections::HashMap<String, String>) {
    if node.kind == NodeKind::FnDecl && !node.extra_return_type.trim().is_empty() {
        out.insert(
            node.name.clone(),
            RustCodegen::t27_type_to_rust(&node.extra_return_type),
        );
    }
    for child in &node.children {
        collect_fn_ret_types(child, out);
    }
}

/// Collect the Rust type of every explicitly typed constant, at any depth.
/// Constants are module-scoped, so this runs once per module.
fn collect_const_types(node: &Node, out: &mut std::collections::HashMap<String, String>) {
    if node.kind == NodeKind::ConstDecl
        && !node.name.is_empty()
        && !node.extra_type.trim().is_empty()
    {
        out.insert(
            node.name.clone(),
            RustCodegen::t27_type_to_rust(&node.extra_type),
        );
    }
    for child in &node.children {
        collect_const_types(child, out);
    }
}

/// Collect the Rust type of every explicitly typed local in a function body.
fn collect_typed_locals(nodes: &[Node], out: &mut std::collections::HashMap<String, String>) {
    for n in nodes {
        if n.kind == NodeKind::StmtLocal && !n.name.is_empty() && !n.extra_type.trim().is_empty() {
            out.insert(n.name.clone(), RustCodegen::t27_type_to_rust(&n.extra_type));
        }
        collect_typed_locals(&n.children, out);
    }
}

// Recursive count of plain-identifier assignment targets, used by the Zig
// test-block emitter to decide const vs var for the first binding of a name.
// Recursive occurrence count of a value identifier (ExprIdentifier nodes plus
// array-literal element text). A tuple-destructure element whose count is 1
// appears only as its own binding -- i.e. it is never read afterwards.
fn count_ident_refs(nodes: &[Node], name: &str) -> u32 {
    let mut c = 0u32;
    for n in nodes {
        if n.kind == NodeKind::ExprIdentifier && n.name == name {
            c += 1;
        }
        if n.kind == NodeKind::ExprArrayLiteral && n.extra_size.contains(name) {
            c += 1;
        }
        c += count_ident_refs(&n.children, name);
    }
    c
}

fn count_ident_assigns(nodes: &[Node], counts: &mut std::collections::HashMap<String, u32>) {
    for n in nodes {
        if n.kind == NodeKind::StmtAssign
            && !n.children.is_empty()
            && n.children[0].kind == NodeKind::ExprIdentifier
            && !n.children[0].name.is_empty()
        {
            *counts.entry(n.children[0].name.clone()).or_insert(0) += 1;
        }
        count_ident_assigns(&n.children, counts);
    }
}

fn collect_mutable_names(stmts: &[Node], set: &mut std::collections::HashSet<String>) {
    for stmt in stmts {
        collect_mutable_names_one(stmt, set);
    }
}

fn collect_mutable_names_one(stmt: &Node, set: &mut std::collections::HashSet<String>) {
    match stmt.kind {
        NodeKind::StmtAssign if !stmt.children.is_empty() => {
            let lhs = &stmt.children[0];
            // Simple identifier: `x = expr`
            if lhs.kind == NodeKind::ExprIdentifier {
                set.insert(lhs.name.clone());
            }
            // Index assignment: `arr[i] = expr` → arr needs mut
            // The LHS is ExprIndex with children[0] = base identifier
            if lhs.kind == NodeKind::ExprIndex && !lhs.children.is_empty() {
                let base = &lhs.children[0];
                if base.kind == NodeKind::ExprIdentifier {
                    set.insert(base.name.clone());
                }
            }
            // Field assignment: `s.f = expr` → s needs mut
            if lhs.kind == NodeKind::ExprFieldAccess && !lhs.children.is_empty() {
                let base = &lhs.children[0];
                if base.kind == NodeKind::ExprIdentifier {
                    set.insert(base.name.clone());
                }
            }
        }
        NodeKind::StmtIf | NodeKind::StmtWhile | NodeKind::StmtFor | NodeKind::StmtForRange => {
            // Recurse into condition + body blocks
            for c in &stmt.children {
                if c.kind == NodeKind::Module {
                    collect_mutable_names(&c.children, set);
                } else {
                    collect_mutable_names_one(c, set);
                }
            }
        }
        _ => {}
    }
}

fn copy_propagate(stmts: &mut Vec<Node>, stats: &mut OptStats) {
    // Recursive reassignment check: a `let X = Y` where X is reassigned later
    // (including inside if/while/for bodies) must NOT be copy-propagated —
    // doing so leaves dangling `X = ...` reassignments in the emitted Rust
    // with no declaration of X.
    let mut reassigned_set = std::collections::HashSet::new();
    collect_mutable_names(stmts, &mut reassigned_set);

    let mut replacements: Vec<(String, String)> = Vec::new();
    for stmt in stmts.iter() {
        if stmt.kind == NodeKind::StmtLocal
            && stmt.children.len() == 1
            && stmt.children[0].kind == NodeKind::ExprIdentifier
            && stmt.name != stmt.children[0].name
            && !reassigned_set.contains(&stmt.name)
            // A local with an explicit type annotation is the t27 widening
            // idiom (`let lo: u16 = byte_param;`). Propagating the bare
            // source identifier into its uses silently narrows the
            // arithmetic back to the source's type (u8 + (u8 << 8) instead
            // of u16 math) -- so typed aliases must stay materialized.
            && stmt.extra_type.is_empty()
        {
            replacements.push((stmt.name.clone(), stmt.children[0].name.clone()));
        }
    }
    if replacements.is_empty() {
        return;
    }
    for stmt in stmts.iter_mut() {
        for (from, to) in &replacements {
            propagate_ident(stmt, from, to);
        }
    }
    stats.copies_propagated += replacements.len() as u32;
}

fn const_propagate(stmts: &mut Vec<Node>, stats: &mut OptStats) {
    let mut consts: Vec<(String, String)> = Vec::new();
    for stmt in stmts.iter() {
        if stmt.kind == NodeKind::StmtLocal
            && !stmt.extra_mutable
            && stmt.children.len() == 1
            && stmt.children[0].kind == NodeKind::ExprLiteral
            && is_literal(&stmt.children[0])
        {
            let name = stmt.name.clone();
            // Recursive reassignment check: scan into if/while/for/for-range bodies
            // so a `let X = <literal>` that's reassigned INSIDE a control-flow block
            // is not incorrectly inlined (which would leave dangling `X = ...` without
            // a declaration in the emitted Rust).
            let mut reassigned_set = std::collections::HashSet::new();
            collect_mutable_names(stmts, &mut reassigned_set);
            if !reassigned_set.contains(&name) {
                consts.push((name, stmt.children[0].value.clone()));
            }
        }
    }
    if consts.is_empty() {
        return;
    }
    for stmt in stmts.iter_mut() {
        for (name, val) in &consts {
            replace_ident_with_literal(stmt, name, val, stats);
        }
    }
}

fn replace_ident_with_literal(node: &mut Node, name: &str, val: &str, stats: &mut OptStats) {
    if node.kind == NodeKind::ExprIdentifier && node.name == *name {
        node.kind = NodeKind::ExprLiteral;
        node.value = val.to_string();
        node.children.clear();
        stats.copies_propagated += 1;
        return;
    }
    for (i, child) in node.children.iter_mut().enumerate() {
        if node.kind == NodeKind::StmtAssign && i == 0 {
            continue;
        }
        replace_ident_with_literal(child, name, val, stats);
    }
}

fn propagate_ident(node: &mut Node, from: &str, to: &str) {
    if node.kind == NodeKind::ExprIdentifier && node.name == *from {
        node.name = to.to_string();
    }
    for (i, child) in node.children.iter_mut().enumerate() {
        if node.kind == NodeKind::StmtAssign && i == 0 {
            continue;
        }
        propagate_ident(child, from, to);
    }
}

fn strength_reduce(stmts: &mut Vec<Node>, stats: &mut OptStats) {
    for stmt in stmts.iter_mut() {
        if stmt.kind == NodeKind::StmtAssign && stmt.children.len() >= 2 {
            reduce_expr(&mut stmt.children[1], stats);
        }
        if stmt.kind == NodeKind::StmtLocal && !stmt.children.is_empty() {
            reduce_expr(&mut stmt.children[0], stats);
        }
        if stmt.kind == NodeKind::ExprReturn && !stmt.children.is_empty() {
            reduce_expr(&mut stmt.children[0], stats);
        }
    }
}

fn reduce_expr(node: &mut Node, stats: &mut OptStats) {
    if node.kind == NodeKind::ExprBinary && node.children.len() >= 2 {
        reduce_expr(&mut node.children[0], stats);
        reduce_expr(&mut node.children[1], stats);
        // W73 (CRITICAL): strength reduction is only safe in general for
        // `*` against a power-of-two literal -- `x * 2^k == x << k` holds
        // for both signed and unsigned 2's-complement modulo 2^n. Signed
        // DIVISION by a power of two MUST NOT be lowered to an arithmetic
        // right shift: signed `/` rounds toward zero (C, Rust, Zig), but
        // `>>` rounds toward negative infinity. Example with i32:
        //     -7 /  4  == -1
        //     -7 >> 2  == -2
        // The optimizer cannot prove signedness from the AST at this
        // stage (no per-node TypeInfo is attached during the optimizer
        // pass; see `Node` in this file -- it has no type field), so the
        // only safe rule is to skip the `/` -> `>>` rewrite entirely.
        // Backends are free to perform the same rewrite later, after
        // type-checking, where signedness is known and an unsigned-only
        // path can be selected. `*` -> `<<` remains.
        let is_mul = node.extra_op == "*";
        if is_mul && is_power_of_two_literal(&node.children[1]) {
            let shift_val = get_power_of_two(&node.children[1]);
            node.extra_op = "<<".to_string();
            node.children[1].value = shift_val.to_string();
            stats.strengths_reduced += 1;
        }
    }
}

fn is_power_of_two_literal(node: &Node) -> bool {
    if node.kind != NodeKind::ExprLiteral {
        return false;
    }
    if let Ok(v) = node.value.parse::<i64>() {
        v > 1 && (v & (v - 1)) == 0
    } else {
        false
    }
}

fn get_power_of_two(node: &Node) -> u32 {
    let v: i64 = node.value.parse().unwrap_or(1);
    (v as u64).trailing_zeros()
}

fn expr_key(node: &Node) -> Option<String> {
    if node.kind == NodeKind::ExprBinary && node.children.len() >= 2 {
        let lk = child_key(&node.children[0]);
        let rk = child_key(&node.children[1]);
        Some(format!("{} {} {}", lk, node.extra_op, rk))
    } else {
        None
    }
}

fn child_key(node: &Node) -> String {
    // R-OPT-2 fix (#919, W47): a previous version of this function fell
    // through to `format!("{:?}", node.kind)` for every non-binary,
    // non-leaf node. All `ExprCall` nodes therefore produced the literal
    // key `"ExprCall"`, so two distinct calls like `foo() + 1` and
    // `bar() + 1` collided in the CSE table and the second call was
    // silently rewritten as the first one's cached temporary. For calls
    // with side effects (IO, state mutation), that is a wrong-code bug.
    //
    // The safe rule: any node we cannot prove to be a pure, syntactically
    // identical re-occurrence of an earlier expression MUST get a key
    // that is unique per occurrence, so CSE never matches it against
    // anything (including another instance of itself). Pure leaves
    // (literals, identifiers) and pure binary expressions over those
    // remain CSE-able; everything else opts out.
    match node.kind {
        NodeKind::ExprLiteral => format!("LIT:{}", node.value),
        NodeKind::ExprIdentifier => format!("ID:{}", node.name),
        NodeKind::ExprBinary => expr_key(node).unwrap_or_else(unique_uncseable_key),
        // ExprCall and any other unsupported kind are conservatively
        // tagged with a fresh unique key on every call so they never
        // participate in CSE matching.
        _ => unique_uncseable_key(),
    }
}

/// Monotonic counter used to produce keys that are guaranteed unique
/// per call site -- used so impure / unsupported expressions never
/// collide in the CSE seen-table.
fn unique_uncseable_key() -> String {
    use std::sync::atomic::{AtomicU64, Ordering};
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let n = COUNTER.fetch_add(1, Ordering::Relaxed);
    format!("UNCSE:{}", n)
}

fn common_subexpr_elim(stmts: &mut Vec<Node>, stats: &mut OptStats) {
    let mut seen: std::collections::HashMap<String, String> = std::collections::HashMap::new();
    let mut counter: u32 = 0;
    let mut new_stmts: Vec<Node> = Vec::new();
    for stmt in stmts.iter_mut() {
        let mut replacements: Vec<(String, String)> = Vec::new();
        collect_cse_replacements(stmt, &seen, &mut replacements);
        if !replacements.is_empty() {
            for (key, _) in &replacements {
                let var_name = format!("_cse{}", counter);
                counter += 1;
                seen.insert(key.clone(), var_name.clone());
                new_stmts.push(make_cse_local(&var_name, key));
                stats.cse_eliminated += 1;
            }
            apply_cse_replacements(stmt, &seen);
        }
        if let Some(key) = stmt_cse_key(stmt) {
            if !seen.contains_key(&key) {
                let var_name = format!("_cse{}", counter);
                counter += 1;
                seen.insert(key.clone(), var_name);
            }
        }
    }
    let insert_pos = find_first_non_local(stmts);
    for (i, local) in new_stmts.into_iter().enumerate() {
        stmts.insert(insert_pos + i, local);
    }
}

fn stmt_cse_key(stmt: &Node) -> Option<String> {
    let expr = match stmt.kind {
        NodeKind::StmtLocal if !stmt.children.is_empty() => &stmt.children[0],
        NodeKind::StmtAssign if stmt.children.len() >= 2 => &stmt.children[1],
        NodeKind::ExprReturn if !stmt.children.is_empty() => &stmt.children[0],
        _ => return None,
    };
    expr_key(expr)
}

fn collect_cse_replacements(
    node: &Node,
    seen: &std::collections::HashMap<String, String>,
    replacements: &mut Vec<(String, String)>,
) {
    if let Some(key) = expr_key(node) {
        if seen.contains_key(&key) {
            replacements.push((key.clone(), seen.get(&key).unwrap().clone()));
        }
    }
    for child in &node.children {
        collect_cse_replacements(child, seen, replacements);
    }
}

fn apply_cse_replacements(node: &mut Node, seen: &std::collections::HashMap<String, String>) {
    if let Some(key) = expr_key(node) {
        if let Some(var_name) = seen.get(&key) {
            node.kind = NodeKind::ExprIdentifier;
            node.name = var_name.clone();
            node.extra_op.clear();
            node.children.clear();
            return;
        }
    }
    for child in &mut node.children {
        apply_cse_replacements(child, seen);
    }
}

fn make_cse_local(var_name: &str, key: &str) -> Node {
    let parts: Vec<&str> = key.splitn(3, ' ').collect();
    let (op_str, left_str, right_str) = if parts.len() == 3 {
        (parts[1], parts[0], parts[2])
    } else {
        return Node::new(NodeKind::StmtLocal);
    };
    let mut local = Node::new(NodeKind::StmtLocal);
    local.name = var_name.to_string();
    local.extra_mutable = false;
    let mut bin = Node::new(NodeKind::ExprBinary);
    bin.extra_op = op_str.to_string();
    if left_str.starts_with("ID:") {
        let mut lid = Node::new(NodeKind::ExprIdentifier);
        lid.name = left_str[3..].to_string();
        bin.children.push(lid);
    } else if left_str.starts_with("LIT:") {
        let mut lit = Node::new(NodeKind::ExprLiteral);
        lit.value = left_str[4..].to_string();
        bin.children.push(lit);
    }
    if right_str.starts_with("ID:") {
        let mut rid = Node::new(NodeKind::ExprIdentifier);
        rid.name = right_str[3..].to_string();
        bin.children.push(rid);
    } else if right_str.starts_with("LIT:") {
        let mut lit = Node::new(NodeKind::ExprLiteral);
        lit.value = right_str[4..].to_string();
        bin.children.push(lit);
    }
    local.children.push(bin);
    local
}

fn find_first_non_local(stmts: &[Node]) -> usize {
    for (i, s) in stmts.iter().enumerate() {
        if s.kind != NodeKind::StmtLocal {
            return i;
        }
    }
    stmts.len()
}

fn collect_reads_in_stmts(stmts: &[Node], reads: &mut std::collections::HashSet<String>) {
    // Walk each statement and collect every identifier that is READ (RHS of
    // assignment/local, return expression, standalone expression, and any
    // subexpression inside if/while/for/for-range condition + body). Without
    // recursing into control-flow bodies, a `let i = 0;` at the top of a
    // function that is only read inside `while` would be seen as dead and
    // eliminated, leaving `i` reassigned but never declared in the emit.
    for stmt in stmts.iter() {
        match stmt.kind {
            NodeKind::StmtLocal if !stmt.children.is_empty() => {
                collect_reads(&stmt.children[0], reads);
            }
            NodeKind::StmtAssign if stmt.children.len() >= 2 => {
                // LHS may itself contain reads (arr[i] = ..., s.f = ...) but a
                // *simple* identifier LHS is a pure write — counting it as a
                // read would prevent legitimate dead-store elimination.
                let lhs = &stmt.children[0];
                if lhs.kind != NodeKind::ExprIdentifier {
                    collect_reads(lhs, reads);
                }
                collect_reads(&stmt.children[1], reads);
            }
            NodeKind::ExprReturn if !stmt.children.is_empty() => {
                collect_reads(&stmt.children[0], reads);
            }
            NodeKind::StmtExpr if !stmt.children.is_empty() => {
                collect_reads(&stmt.children[0], reads);
            }
            NodeKind::StmtIf | NodeKind::StmtWhile | NodeKind::StmtFor | NodeKind::StmtForRange => {
                for c in &stmt.children {
                    if c.kind == NodeKind::Module {
                        collect_reads_in_stmts(&c.children, reads);
                    } else {
                        // Condition / range expressions live directly as child
                        // nodes (not wrapped in Module) — read them fully.
                        collect_reads(c, reads);
                    }
                }
            }
            _ => {}
        }
    }
}

fn dead_store_elim(
    stmts: &mut Vec<Node>,
    stats: &mut OptStats,
    module_state: &std::collections::HashSet<String>,
) {
    let mut reads: std::collections::HashSet<String> = std::collections::HashSet::new();
    collect_reads_in_stmts(stmts, &mut reads);
    let before = stmts.len();
    stmts.retain(|s| {
        // R-OPT-1 (#918, W46): the target of StmtAssign is the LHS
        // expression stored in `s.children[0]` and `s.name` is the empty
        // string. The previous code tested `reads.contains(&s.name)` on
        // StmtAssign, so the test was `reads.contains("")`, which is always
        // false, and the assignment was unconditionally dropped. This removed
        // every assignment from every optimised program.
        //
        // We must only eliminate an assignment whose LHS is a *simple
        // identifier*: `arr[i] = x` and `s.field = x` write through a base
        // that may be live, and dropping them is unsound. We therefore guard on
        // the LHS kind before consulting `reads`.
        //
        // Initialized local bindings (`let y = x`) are kept even when their
        // only use is inlined by copy-propagation, because the backends emit
        // the declaration as a named register. Tuple-destructuring locals have
        // no name and are still eliminated if they are never read.
        if s.kind == NodeKind::StmtLocal
            && !s.children.is_empty()
            && s.name.is_empty()
            && s.extra_field.is_empty() // keep tuple-destructuring locals (pattern in extra_field)
            && !reads.contains(&s.name)
        {
            return false;
        }
        //
        // t27#2363: a write to MODULE-level state is never dead, whatever this
        // body does afterwards -- the value outlives the call and is read from
        // outside it. `fn on_clock { acc = acc + x }` survived only because its
        // RHS mentions `acc`, which put `acc` in `reads` by accident; the plain
        // register load `fn on_clock { acc = x }` -- `reg <= input`, the
        // commonest sequential idiom there is -- was deleted outright, leaving
        // an `always` block with an EMPTY `en` arm while the input port and the
        // reset value stayed, so the module looked right and did nothing.
        if s.kind == NodeKind::StmtAssign && s.children.len() >= 2 {
            let lhs = &s.children[0];
            if lhs.kind == NodeKind::ExprIdentifier
                && !lhs.name.is_empty()
                && !reads.contains(&lhs.name)
                && !module_state.contains(&lhs.name)
            {
                return false;
            }
        }
        true
    });
    stats.dead_stores += (before - stmts.len()) as u32;
}

fn loop_unroll(stmts: &mut Vec<Node>, stats: &mut OptStats) {
    let mut insertions: Vec<(usize, Vec<Node>)> = Vec::new();
    for (i, stmt) in stmts.iter_mut().enumerate() {
        if stmt.kind == NodeKind::StmtForRange && stmt.children.len() >= 3 {
            let start_val = parse_int_value(&stmt.children[0].value);
            let end_val = parse_int_value(&stmt.children[1].value);
            if let (Some(s), Some(e)) = (start_val, end_val) {
                let count = e.saturating_sub(s);
                if count > 0 && count <= 4 {
                    let body = &stmt.children[2];
                    let iter_var = stmt.name.clone();
                    let mut unrolled = Vec::new();
                    for v in s..e {
                        let mut body_clone = body.clone();
                        replace_iter_var(&mut body_clone, &iter_var, v);
                        for child in body_clone.children.drain(..) {
                            unrolled.push(child);
                        }
                    }
                    insertions.push((i, unrolled));
                    stats.loops_unrolled += 1;
                }
            }
        }
        if stmt.kind == NodeKind::StmtFor && stmt.children.len() >= 3 {
            let iter_expr = &stmt.children[0];
            if iter_expr.kind == NodeKind::ExprBinary && iter_expr.extra_op == ".."
                && iter_expr.children.len() >= 2 {
                    let start = parse_int_value(&iter_expr.children[0].value);
                    let end = parse_int_value(&iter_expr.children[1].value);
                    if let (Some(s), Some(e)) = (start, end) {
                        let count = e - s;
                        if count > 0 && count <= 4 {
                            let body = &stmt.children[2];
                            let iter_var = if stmt.children.len() > 1 {
                                stmt.children[1].name.clone()
                            } else {
                                "_i".to_string()
                            };
                            let mut unrolled = Vec::new();
                            for v in s..e {
                                let mut body_clone = body.clone();
                                replace_iter_var(&mut body_clone, &iter_var, v);
                                for child in body_clone.children.drain(..) {
                                    unrolled.push(child);
                                }
                            }
                            insertions.push((i, unrolled));
                            stats.loops_unrolled += 1;
                        }
                    }
                }
        }
    }
    for (idx, unrolled) in insertions.into_iter().rev() {
        stmts.remove(idx);
        for (j, s) in unrolled.into_iter().enumerate() {
            stmts.insert(idx + j, s);
        }
    }
}

fn replace_iter_var(node: &mut Node, var: &str, val: i64) {
    if node.kind == NodeKind::ExprIdentifier && node.name == var {
        node.kind = NodeKind::ExprLiteral;
        node.value = val.to_string();
        node.name.clear();
        return;
    }
    for child in &mut node.children {
        replace_iter_var(child, var, val);
    }
}

fn collect_reads(node: &Node, reads: &mut std::collections::HashSet<String>) {
    if node.kind == NodeKind::ExprIdentifier {
        reads.insert(node.name.clone());
    }
    for child in &node.children {
        collect_reads(child, reads);
    }
}

fn eval_binary(left: &str, op: &str, right: &str) -> Option<String> {
    let l: i64 = parse_int_value(left)?;
    let r: i64 = parse_int_value(right)?;
    let result = match op {
        "+" => Some(l + r),
        "-" => Some(l - r),
        "*" => Some(l * r),
        "/" if r != 0 => Some(l / r),
        "%" if r != 0 => Some(l % r),
        "&" => Some(l & r),
        "|" => Some(l | r),
        "^" => Some(l ^ r),
        "<<" if (0..64).contains(&r) => Some(l << r),
        ">>" if (0..64).contains(&r) => Some(l >> r),
        "==" => Some(if l == r { 1 } else { 0 }),
        "!=" => Some(if l != r { 1 } else { 0 }),
        "<" => Some(if l < r { 1 } else { 0 }),
        ">" => Some(if l > r { 1 } else { 0 }),
        "<=" => Some(if l <= r { 1 } else { 0 }),
        ">=" => Some(if l >= r { 1 } else { 0 }),
        _ => None,
    };
    result.map(|v| v.to_string())
}

fn eval_unary(op: &str, operand: &str) -> Option<String> {
    let v: i64 = parse_int_value(operand)?;
    match op {
        "-" => Some((-v).to_string()),
        "!" => Some((if v == 0 { 1 } else { 0 }).to_string()),
        "~" => Some((!v).to_string()),
        _ => None,
    }
}

// ============================================================================
// Type Checker
// ============================================================================

#[derive(Debug, Clone, PartialEq)]
#[allow(dead_code)]
pub enum TypeInfo {
    Void,
    Bool,
    I8,
    I16,
    I32,
    I64,
    U8,
    U16,
    U32,
    U64,
    F32,
    F64,
    GF16,
    Str,
    Array(Box<TypeInfo>),
    Pointer(Box<TypeInfo>),
    Optional(Box<TypeInfo>),
    Custom(String),
    Unknown,
    Error,
}

pub struct TypeCheckResult {
    pub ok: bool,
    pub error_count: u32,
    pub warnings: u32,
    pub errors: Vec<String>,
}

#[derive(Clone)]
#[allow(dead_code)]
struct SymbolEntry {
    name: String,
    type_info: TypeInfo,
    is_mutable: bool,
    /// True only for module-level `const` declarations (ROM); fn-local lets
    /// follow t27's inferred-mutability convention.
    is_const: bool,
}

struct FnEntry {
    name: String,
    return_type: TypeInfo,
    params: Vec<(String, TypeInfo)>,
}

pub fn typecheck_ast(ast: &Node) -> TypeCheckResult {
    let mut result = TypeCheckResult {
        ok: true,
        error_count: 0,
        warnings: 0,
        errors: Vec::new(),
    };
    let mut symbols: Vec<SymbolEntry> = Vec::new();
    let mut fns: Vec<FnEntry> = Vec::new();

    for child in &ast.children {
        match child.kind {
            NodeKind::ConstDecl => {
                let t = resolve_type_str(&child.extra_type);
                symbols.push(SymbolEntry {
                    name: child.name.clone(),
                    type_info: t,
                    is_mutable: false,
                    is_const: true,
                });
            }
            NodeKind::StructDecl | NodeKind::EnumDecl => {
                symbols.push(SymbolEntry {
                    name: child.name.clone(),
                    type_info: TypeInfo::Custom(child.name.clone()),
                    is_mutable: false,
                    is_const: false,
                });
            }
            NodeKind::FnDecl => {
                let ret = resolve_type_str(&child.extra_return_type);
                let mut params = Vec::new();
                for (pname, ptype) in &child.params {
                    params.push((pname.clone(), resolve_type_str(ptype)));
                }
                fns.push(FnEntry {
                    name: child.name.clone(),
                    return_type: ret,
                    params,
                });
            }
            _ => {}
        }
    }

    {
        let struct_fields: std::collections::HashMap<String, Vec<String>> = ast
            .children
            .iter()
            .filter(|c| c.kind == NodeKind::StructDecl)
            .map(|c| {
                (
                    c.name.clone(),
                    c.children.iter().map(|f| f.extra_type.clone()).collect(),
                )
            })
            .collect();
        for sname in struct_fields.keys() {
            let mut visited = std::collections::HashSet::new();
            fn has_cycle(
                name: &str,
                structs: &std::collections::HashMap<String, Vec<String>>,
                visited: &mut std::collections::HashSet<String>,
            ) -> bool {
                if visited.contains(name) {
                    return true;
                }
                visited.insert(name.to_string());
                if let Some(fs) = structs.get(name) {
                    for ft in fs {
                        let base = ft
                            .trim()
                            .trim_end_matches('*')
                            .trim()
                            .trim_start_matches("[]")
                            .trim();
                        if structs.contains_key(base) && has_cycle(base, structs, visited) {
                            return true;
                        }
                    }
                }
                visited.take(name).unwrap();
                false
            }
            if has_cycle(sname, &struct_fields, &mut visited) {
                result.warnings += 1;
                result.errors.push(format!(
                    "warning: recursive struct '{}' detected — consider using a pointer/optional field",
                    sname
                ));
            }
        }
    }

    for child in &ast.children {
        if child.kind == NodeKind::FnDecl {
            if child.params.len() > 8 {
                result.warnings += 1;
                let line = if child.line > 0 {
                    format!(":{}", child.line)
                } else {
                    String::new()
                };
                result.errors.push(format!(
                    "warning: function '{}' has {} parameters{} — consider refactoring",
                    child.name,
                    child.params.len(),
                    line
                ));
            }
            let mut fn_symbols = symbols.clone();
            for (pname, ptype) in &child.params {
                fn_symbols.push(SymbolEntry {
                    name: pname.clone(),
                    type_info: resolve_type_str(ptype),
                    is_mutable: true,
                    is_const: false,
                });
            }
            // #920 bug 2: thread an accumulating scope so a StmtLocal declared in
            // the body is visible to subsequent sibling statements (it was being
            // discarded, causing later references to resolve to Unknown).
            let declared_ret = if child.extra_return_type.is_empty() {
                TypeInfo::Unknown
            } else {
                resolve_type_str(&child.extra_return_type)
            };
            for body_child in &child.children {
                check_stmt(body_child, &mut fn_symbols, &fns, &mut result, &declared_ret);
            }

            let mut found_return = false;
            for body_child in &child.children {
                if found_return {
                    result.warnings += 1;
                    let line = if body_child.line > 0 {
                        format!(":{}", body_child.line)
                    } else {
                        String::new()
                    };
                    result.errors.push(format!(
                        "warning: unreachable code in function '{}'{}",
                        child.name, line
                    ));
                    break;
                }
                if body_child.kind == NodeKind::ExprReturn {
                    found_return = true;
                }
            }

            let mut reads: std::collections::HashSet<String> = std::collections::HashSet::new();
            fn collect_reads(node: &Node, reads: &mut std::collections::HashSet<String>) {
                if node.kind == NodeKind::ExprIdentifier {
                    reads.insert(node.name.clone());
                }
                // A BARE bracket literal (`[a0, 99]`, no `[N]Type{...}` prefix)
                // never becomes child nodes: the parser captures the whole
                // bracket body as element TEXT in extra_size. Reading only
                // children therefore missed every identifier used that way and
                // reported it as an unused variable -- a false positive on the
                // idiomatic "bind the elements to locals, then rebuild the
                // array" pattern (health_monitoring::update_health_check,
                // key_management::set_key_slot, and others). Scan the text too.
                // This can only ADD reads, so it removes false warnings and can
                // never introduce one.
                if node.kind == NodeKind::ExprArrayLiteral && !node.extra_size.is_empty() {
                    let mut ident = String::new();
                    for ch in node.extra_size.chars() {
                        if ch.is_alphanumeric() || ch == '_' {
                            ident.push(ch);
                        } else {
                            if !ident.is_empty() && !ident.starts_with(|c: char| c.is_ascii_digit()) {
                                reads.insert(std::mem::take(&mut ident));
                            } else {
                                ident.clear();
                            }
                        }
                    }
                    if !ident.is_empty() && !ident.starts_with(|c: char| c.is_ascii_digit()) {
                        reads.insert(ident);
                    }
                }
                for child in &node.children {
                    collect_reads(child, reads);
                }
            }
            for body_child in &child.children {
                collect_reads(body_child, &mut reads);
            }
            for body_child in &child.children {
                if body_child.kind == NodeKind::StmtLocal && !body_child.name.is_empty()
                    && !reads.contains(&body_child.name) && !body_child.extra_mutable {
                        result.warnings += 1;
                        let line = if body_child.line > 0 {
                            format!(":{}", body_child.line)
                        } else {
                            String::new()
                        };
                        result.errors.push(format!(
                            "warning: unused variable '{}' in function '{}'{}",
                            body_child.name, child.name, line
                        ));
                    }
            }

            fn is_tail_call(fn_body: &[Node], fn_name: &str) -> bool {
                let last = match fn_body.last() {
                    Some(s) => s,
                    None => return false,
                };
                if last.kind == NodeKind::ExprReturn && !last.children.is_empty()
                    && last.children[0].kind == NodeKind::ExprCall
                        && last.children[0].name == fn_name
                    {
                        return true;
                    }
                false
            }

            if is_tail_call(&child.children, &child.name) {
                let line = if child.line > 0 {
                    format!(":{}", child.line)
                } else {
                    String::new()
                };
                result.errors.push(format!(
                    "info: tail call detected in '{}'{} — candidate for optimization",
                    child.name, line
                ));
            }
        }
    }

    let mut enum_variants: std::collections::HashMap<String, Vec<String>> =
        std::collections::HashMap::new();
    for child in &ast.children {
        if child.kind == NodeKind::EnumDecl {
            let variants: Vec<String> = child
                .children
                .iter()
                .filter(|c| c.kind == NodeKind::EnumVariant)
                .map(|c| format!("{}::{}", child.name, c.name))
                .collect();
            enum_variants.insert(child.name.clone(), variants);
        }
    }

    let mut used_variants: std::collections::HashSet<String> = std::collections::HashSet::new();
    fn collect_enum_values(node: &Node, used: &mut std::collections::HashSet<String>) {
        if node.kind == NodeKind::ExprEnumValue {
            used.insert(format!("{}::{}", node.name, node.extra_field));
        }
        for child in &node.children {
            collect_enum_values(child, used);
        }
    }
    collect_enum_values(ast, &mut used_variants);

    for (enum_name, variants) in &enum_variants {
        let unused: Vec<&String> = variants
            .iter()
            .filter(|v| !used_variants.contains(*v))
            .collect();
        if !unused.is_empty() && unused.len() < variants.len() {
            for v in &unused {
                result.warnings += 1;
                result.errors.push(format!(
                    "info: unused enum variant '{}' in enum '{}'",
                    v, enum_name
                ));
            }
        }
    }

    if result.error_count > 0 {
        result.ok = false;
    }
    result
}

/// `ret` is the enclosing function's declared return type, threaded so the
/// RETURN position can be compared like the other three.
///
/// #920 rejects narrowing F64 -> F32. It applied at an assignment (error) and
/// at a call argument (warning); a declaration was added in #2897 and this is
/// the fourth and last position. `TypeInfo::Unknown` means "no annotation", and
/// nothing is claimed for it.
fn check_stmt(
    node: &Node,
    symbols: &mut Vec<SymbolEntry>,
    fns: &[FnEntry],
    result: &mut TypeCheckResult,
    ret: &TypeInfo,
) {
    match node.kind {
        NodeKind::StmtLocal => {
            let t = if node.extra_type.is_empty() {
                if node.children.is_empty() {
                    TypeInfo::Unknown
                } else {
                    infer_expr(&node.children[0], symbols, fns)
                }
            } else {
                resolve_type_str(&node.extra_type)
            };
            // Check the initializer expression against the scope as it stands
            // BEFORE this local is registered (a local cannot reference itself).
            for child in &node.children {
                check_expr(child, symbols, fns, result);
            }
            // #920 rejects narrowing F64 -> F32 in an ASSIGNMENT and nowhere
            // else. Measured: `x = d` is an error, `p(d)` is a warning, and a
            // DECLARATION with an annotation was not compared at all --
            // `var x: f32 = d;` passed in silence. Three treatments of one
            // rule, two of them silent.
            //
            // Reported at the same severity the argument position uses. Making
            // it an error would be the consistent choice and would also fail
            // specs that pass today; that is the owner's call, and a warning
            // makes the hole countable without moving any ratchet.
            if !node.extra_type.is_empty() && !node.children.is_empty() {
                let declared = resolve_type_str(&node.extra_type);
                let init = infer_expr(&node.children[0], symbols, fns);
                if !types_compatible(&declared, &init)
                    && declared != TypeInfo::Unknown
                    && init != TypeInfo::Unknown
                {
                    result.warnings += 1;
                    let line = if node.line > 0 {
                        format!(":{}", node.line)
                    } else {
                        String::new()
                    };
                    result.errors.push(format!(
                        "warning: '{}' is declared {:?} and initialised from {:?}{}",
                        node.name, declared, init, line
                    ));
                }
            }
            // #920 bug 2: register the local in the CURRENT scope so subsequent
            // sibling statements can resolve it (was previously discarded).
            symbols.push(SymbolEntry {
                name: node.name.clone(),
                type_info: t,
                is_mutable: node.extra_mutable,
                is_const: false,
                });
        }
        NodeKind::ExprReturn => {
            for child in &node.children {
                check_expr(child, symbols, fns, result);
            }
            if !node.children.is_empty() && *ret != TypeInfo::Unknown {
                let got = infer_expr(&node.children[0], symbols, fns);
                if !types_compatible(ret, &got) && got != TypeInfo::Unknown {
                    result.warnings += 1;
                    let line = if node.line > 0 {
                        format!(":{}", node.line)
                    } else {
                        String::new()
                    };
                    result.errors.push(format!(
                        "warning: returns {:?} where {:?} is declared{}",
                        got, ret, line
                    ));
                }
            }
        }
        NodeKind::StmtAssign => {
            if !node.children.is_empty() {
                if let Some(sym) = symbols.iter().find(|s| {
                    node.children[0].kind == NodeKind::ExprIdentifier
                        && s.name == node.children[0].name
                }) {
                    if !sym.is_mutable {
                        let name = &node.children[0].name;
                        let line = if node.line > 0 {
                            format!(":{}", node.line)
                        } else {
                            String::new()
                        };
                        result.warnings += 1;
                        result.errors.push(format!(
                            "warning: cannot assign to immutable '{}'{}",
                            name, line
                        ));
                    }
                }
                // W456: assignments into an element of an immutable array (const
                // ROM) are also illegal, even though the LHS is an ExprIndex rather
                // than a bare ExprIdentifier.
                if node.children[0].kind == NodeKind::ExprIndex
                    && !node.children[0].children.is_empty()
                    && node.children[0].children[0].kind == NodeKind::ExprIdentifier
                {
                    let base_name = &node.children[0].children[0].name;
                    if let Some(sym) = symbols.iter().find(|s| s.name == *base_name) {
                        if !sym.is_mutable {
                            let line = if node.line > 0 {
                                format!(":{}", node.line)
                            } else {
                                String::new()
                            };
                            if sym.is_const {
                                // W456: a module-level const array is ROM.
                                result.error_count += 1;
                                result.errors.push(format!(
                                    "error: cannot assign to immutable array element '{}[...]'{}",
                                    base_name, line
                                ));
                            } else {
                                // A fn-local let-array follows the same
                                // inferred-mutability convention as scalars:
                                // the backends promote it to var/mut, so this
                                // is a style warning, not an error.
                                result.warnings += 1;
                                result.errors.push(format!(
                                    "warning: element assignment promotes '{}' to mutable{}",
                                    base_name, line
                                ));
                            }
                        }
                    }
                }
                let target_type = infer_expr(&node.children[0], symbols, fns);
                if node.children.len() > 1 {
                    let value_type = infer_expr(&node.children[1], symbols, fns);
                    if !types_compatible(&target_type, &value_type)
                        && target_type != TypeInfo::Unknown
                        && value_type != TypeInfo::Unknown
                    {
                        result.error_count += 1;
                        result.errors.push(format!(
                            "type mismatch at line {}: cannot assign {:?} to {:?}",
                            if node.line > 0 {
                                node.line.to_string()
                            } else {
                                "?".to_string()
                            },
                            value_type,
                            target_type
                        ));
                    }
                }
            }
        }
        NodeKind::StmtIf | NodeKind::StmtWhile => {
            // Block-scoped: locals declared inside do not leak to outer siblings.
            let mut inner = symbols.clone();
            for child in &node.children {
                check_stmt(child, &mut inner, fns, result, ret);
            }
        }
        NodeKind::StmtFor => {
            let mut inner = symbols.clone();
            for child in &node.children {
                check_stmt(child, &mut inner, fns, result, ret);
            }
        }
        NodeKind::StmtForRange => {
            let mut inner = symbols.clone();
            for child in &node.children {
                check_stmt(child, &mut inner, fns, result, ret);
            }
        }
        NodeKind::Module => {
            let mut inner = symbols.clone();
            for child in &node.children {
                check_stmt(child, &mut inner, fns, result, ret);
            }
        }
        NodeKind::ExprReturn => {
            if !node.children.is_empty() {
                check_expr(&node.children[0], symbols, fns, result);
            }
        }
        NodeKind::StmtExpr => {
            for child in &node.children {
                check_expr(child, symbols, fns, result);
            }
        }
        _ => {}
    }
}

fn check_expr(node: &Node, symbols: &[SymbolEntry], fns: &[FnEntry], result: &mut TypeCheckResult) {
    match node.kind {
        NodeKind::ExprCall => {
            if let Some(fn_entry) = fns.iter().find(|f| f.name == node.name) {
                let call_args: Vec<&Node> = node
                    .children
                    .iter()
                    .filter(|c| c.kind != NodeKind::Module)
                    .collect();
                if call_args.len() != fn_entry.params.len() {
                    // Arity mismatch is a HARD error: two tri-net specs shipped
                    // mismatched calls for months because this only warned and
                    // nothing reads warnings (tri-net#323). Wrong-arity calls
                    // mangle in every backend.
                    result.error_count += 1;
                    result.ok = false;
                    result.errors.push(format!(
                        "function '{}' expects {} args, got {} at line {}",
                        node.name,
                        fn_entry.params.len(),
                        call_args.len(),
                        if node.line > 0 {
                            node.line.to_string()
                        } else {
                            "?".to_string()
                        }
                    ));
                } else {
                    for (i, arg) in call_args.iter().enumerate() {
                        let arg_type = infer_expr(arg, symbols, fns);
                        let param_type = &fn_entry.params[i].1;
                        if !types_compatible(param_type, &arg_type)
                            && *param_type != TypeInfo::Unknown
                            && arg_type != TypeInfo::Unknown
                        {
                            result.warnings += 1;
                            result.errors.push(format!(
                                "arg {} of '{}': expected {:?}, got {:?}",
                                i, node.name, param_type, arg_type
                            ));
                        }
                    }
                }
            }
            for child in &node.children {
                check_expr(child, symbols, fns, result);
            }
        }
        NodeKind::ExprBinary => {
            for child in &node.children {
                check_expr(child, symbols, fns, result);
            }
        }
        NodeKind::ExprUnary => {
            for child in &node.children {
                check_expr(child, symbols, fns, result);
            }
        }
        NodeKind::ExprFieldAccess | NodeKind::ExprIndex => {
            for child in &node.children {
                check_expr(child, symbols, fns, result);
            }
        }
        NodeKind::ExprStructLit => {
            if let Some(_sym) = symbols.iter().find(|s| {
                if let TypeInfo::Custom(ref name) = s.type_info {
                    name == &node.name
                } else {
                    false
                }
            }) {
                // We found the struct type — field validation happens at gen time
            }
            for child in &node.children {
                check_expr(child, symbols, fns, result);
            }
        }
        _ => {}
    }
}

fn infer_expr(node: &Node, symbols: &[SymbolEntry], fns: &[FnEntry]) -> TypeInfo {
    match node.kind {
        NodeKind::ExprLiteral => {
            if node.value == "true" || node.value == "false" {
                return TypeInfo::Bool;
            }
            // The parser marks a string literal with `extra_kind: "string"`.
            // This tested the VALUE for a leading quote instead, and the lexeme
            // does not always carry one -- so `var period_str : &str = "83.333";`
            // fell through to the float branch below and the declaration was
            // typed F64. Measured across the corpus: two such strings, both in
            // specs/pins/emitter_xdc.t27, and neither was reported by anything
            // because the declaration position was not compared at all.
            if node.extra_kind == "string" || node.value.starts_with('"') {
                return TypeInfo::Str;
            }
            if node.value.parse::<i64>().is_ok() {
                // A bare NON-NEGATIVE integer literal is context-polymorphic:
                // t27 specs are u32-dominant, and pinning literals to I32 made
                // every `let x = 0; ... x = u32_expr;` a false type error
                // (27 tri-net specs failed typecheck on exactly this). Only an
                // explicitly negative literal commits to a signed type.
                if node.value.trim_start().starts_with('-') {
                    return TypeInfo::I32;
                }
                return TypeInfo::Unknown;
            }
            // An integer literal ABOVE i64::MAX still an integer. Without this
            // it fails the i64 parse above, reaches the float branch below and
            // becomes F64 -- so `var cleared : u64 = z & 18446744073709551552;`
            // reads as a float initialising an integer. Eight sites across five
            // ternary specs, all of them bit masks: 2^64 - 64 and 2^64 - 16.
            //
            // Unknown, not U64, to match the branch above: a non-negative
            // integer literal is context-polymorphic here, and pinning it would
            // reintroduce the false errors that comment describes.
            if node.value.parse::<u64>().is_ok() || node.value.parse::<u128>().is_ok() {
                return TypeInfo::Unknown;
            }
            // A float literal is CONTEXT-POLYMORPHIC, exactly as the
            // non-negative integer literal above already is. Pinning it to F64
            // made `var x: f32 = 1.0;` a narrowing and `return 1.0` from an f32
            // function a warning -- 255 of them across 31 specs, all noise.
            //
            // #920's rule survives where it was aimed: a COMPUTED F64 assigned
            // to an F32 is still an error, because a binary expression is not a
            // literal. What stops being an error is `x = 2.0`, where the value
            // is known exactly and the narrowing is not a narrowing.
            if node.value.parse::<f64>().is_ok() {
                return TypeInfo::Unknown;
            }
            TypeInfo::Unknown
        }
        NodeKind::ExprIdentifier => symbols
            .iter()
            .rev()
            .find(|s| s.name == node.name)
            .map(|s| s.type_info.clone())
            .unwrap_or(TypeInfo::Unknown),
        NodeKind::ExprCall => fns
            .iter()
            .rev()
            .find(|f| f.name == node.name)
            .map(|f| f.return_type.clone())
            .unwrap_or(TypeInfo::Unknown),
        NodeKind::ExprBinary => {
            if node.children.len() >= 2 {
                let lt = infer_expr(&node.children[0], symbols, fns);
                let rt = infer_expr(&node.children[1], symbols, fns);
                if node.extra_op == "=="
                    || node.extra_op == "!="
                    || node.extra_op == "<"
                    || node.extra_op == ">"
                    || node.extra_op == "<="
                    || node.extra_op == ">="
                    || node.extra_op == "and"
                    || node.extra_op == "or"
                {
                    return TypeInfo::Bool;
                }
                if node.extra_op == "+" && (lt == TypeInfo::Str || rt == TypeInfo::Str) {
                    return TypeInfo::Str;
                }
                // A SHIFT is not a symmetric operation: its result has the type
                // of the value being shifted, and the shift AMOUNT is just a
                // count. `promote_types` treated it like `+` and let the count's
                // type win, so `y >> shift` with `y: i16, shift: u32` was U32.
                //
                // Eight of the eleven remaining narrowing warnings were that --
                // `return x - (y >> shift);` in cordic_fixed and cordic_top --
                // and every one of them read as a defect in the spec when the
                // defect was here. C, Rust and Zig all take the left type.
                if node.extra_op == "<<" || node.extra_op == ">>" {
                    return lt;
                }
                promote_types(&lt, &rt)
            } else {
                TypeInfo::Unknown
            }
        }
        NodeKind::ExprUnary => {
            if !node.children.is_empty() {
                infer_expr(&node.children[0], symbols, fns)
            } else {
                TypeInfo::Unknown
            }
        }
        _ => TypeInfo::Unknown,
    }
}

fn promote_types(a: &TypeInfo, b: &TypeInfo) -> TypeInfo {
    if a == b {
        return a.clone();
    }
    // The KNOWN operand determines the type: `100 - value` where value: u32
    // is a u32 expression, not an unknown one.
    if *a == TypeInfo::Unknown {
        return b.clone();
    }
    if *b == TypeInfo::Unknown {
        return a.clone();
    }
    let a_rank = type_rank(a);
    let b_rank = type_rank(b);
    if a_rank >= b_rank {
        a.clone()
    } else {
        b.clone()
    }
}

fn type_rank(t: &TypeInfo) -> u8 {
    match t {
        TypeInfo::Bool => 0,
        TypeInfo::I8 | TypeInfo::U8 => 1,
        TypeInfo::I16 | TypeInfo::U16 => 2,
        TypeInfo::I32 | TypeInfo::U32 => 3,
        TypeInfo::I64 | TypeInfo::U64 => 4,
        TypeInfo::F32 => 5,
        TypeInfo::GF16 => 5,
        TypeInfo::F64 => 6,
        _ => 0,
    }
}

fn types_compatible(target: &TypeInfo, value: &TypeInfo) -> bool {
    if *target == TypeInfo::Unknown || *value == TypeInfo::Unknown {
        return true;
    }
    if target == value {
        return true;
    }
    // Reject narrowing f64 -> f32 (precision loss). Widening f32 -> f64 is still
    // permitted by the rank check below. Fixes #920 (typechecker unsoundness, bug 1).
    if *target == TypeInfo::GF16 && (*value == TypeInfo::F32 || *value == TypeInfo::F64) {
        return true;
    }
    // Reject implicit cross-sign integer assignment of equal rank (e.g. i32 <-> u32):
    // 0xFFFFFFFF would silently become -1. Fixes #920 (typechecker unsoundness, bug 3).
    if is_integer_type(target) && is_integer_type(value)
        && type_rank(target) == type_rank(value)
        && is_signed_int(target) != is_signed_int(value)
    {
        return false;
    }
    type_rank(target) >= type_rank(value)
}

fn is_integer_type(t: &TypeInfo) -> bool {
    matches!(
        t,
        TypeInfo::I8 | TypeInfo::I16 | TypeInfo::I32 | TypeInfo::I64
            | TypeInfo::U8 | TypeInfo::U16 | TypeInfo::U32 | TypeInfo::U64
    )
}

fn is_signed_int(t: &TypeInfo) -> bool {
    matches!(t, TypeInfo::I8 | TypeInfo::I16 | TypeInfo::I32 | TypeInfo::I64)
}

fn resolve_type_str(s: &str) -> TypeInfo {
    let t = s.trim().trim_end_matches('?');
    let is_opt = s.trim().ends_with('?');
    let base = match t {
        "void" => TypeInfo::Void,
        "bool" => TypeInfo::Bool,
        "i8" => TypeInfo::I8,
        "i16" => TypeInfo::I16,
        "i32" => TypeInfo::I32,
        "i64" => TypeInfo::I64,
        "u8" => TypeInfo::U8,
        "u16" => TypeInfo::U16,
        "u32" => TypeInfo::U32,
        "u64" => TypeInfo::U64,
        "f32" => TypeInfo::F32,
        "f64" => TypeInfo::F64,
        "GF16" | "gf16" => TypeInfo::GF16,
        "str" => TypeInfo::Str,
        "" => TypeInfo::Unknown,
        other => TypeInfo::Custom(other.to_string()),
    };
    if is_opt {
        TypeInfo::Optional(Box::new(base))
    } else {
        base
    }
}

// ============================================================================
// Rust Code Generator
// ============================================================================

pub struct RustCodegen {
    output: String,
    indent: usize,
    /// Names of locals that are reassigned in the current function body
    /// (via simple assignment `x = ...` or index assignment `arr[i] = ...`).
    /// Used to infer `let mut` for locals declared with `let`.
    mut_names: std::collections::HashSet<String>,
    /// Rust return type of the function currently being emitted. Used to
    /// coerce t27's integer-valued booleans into the declared return type.
    fn_ret_type: String,
    /// Functions in this module whose declared return type is `bool`.
    bool_fns: std::collections::HashSet<String>,
    /// Parameters and locals of the current function declared `bool`.
    bool_vars: std::collections::HashSet<String>,
    /// Field names this FILE declares as `bool`.
    ///
    /// `expr_is_bool` had no arm for `ExprFieldAccess`, so a condition on a
    /// bool field fell to the integer default: `!debouncer.enabled` was emitted
    /// as `((debouncer.enabled) == 0)`, which rustc rejects with E0308. The
    /// emitter prints `pub enabled: bool,` into the same file and never
    /// consulted it.
    ///
    /// Keyed by NAME, not by (struct, field): measured over the corpus, zero
    /// of the 650 specs declare one field name as `bool` in one struct and as
    /// something else in another, so within a single generated file the name
    /// is unambiguous. 35 names collide ACROSS files, which is why this is
    /// cleared per file and never shared.
    bool_fields: std::collections::HashSet<String>,
    /// Rust type of every explicitly typed parameter/local of the current
    /// function. Feeds `infer_int_type`.
    var_types: std::collections::HashMap<String, String>,
    /// Rust type of every explicitly typed constant in this module.
    const_types: std::collections::HashMap<String, String>,
    /// Declared Rust return type of every function in this module.
    fn_ret_types: std::collections::HashMap<String, String>,
    /// Names of enums declared in this module.
    ///
    /// t27 writes an enum member as `Verdict.escalate`, which is Zig's
    /// spelling and what the parser produces. Rust spells it
    /// `Verdict::escalate`. Without knowing which identifiers name enums the
    /// emitter cannot tell that access apart from a struct field.
    enum_names: std::collections::HashSet<String>,
    /// Module-level names declared `var`, i.e. MUTABLE.
    ///
    /// Rust has no safe mutable global. gen-verilog lowers this to a `reg`,
    /// gen-c to a `static`, Zig to a `var` -- all three mean SHARED mutable
    /// state, so Rust's answer has to be `static mut`, and every access to one
    /// needs `unsafe`. Collected in a pre-pass because a function may be
    /// emitted before the declaration it reads.
    static_mut_names: std::collections::HashSet<String>,
}

#[allow(dead_code)]
impl RustCodegen {
    pub fn new() -> Self {
        RustCodegen {
            output: String::new(),
            indent: 0,
            mut_names: std::collections::HashSet::new(),
            fn_ret_type: String::new(),
            bool_fns: std::collections::HashSet::new(),
            bool_vars: std::collections::HashSet::new(),
            bool_fields: std::collections::HashSet::new(),
            var_types: std::collections::HashMap::new(),
            const_types: std::collections::HashMap::new(),
            fn_ret_types: std::collections::HashMap::new(),
            enum_names: std::collections::HashSet::new(),
            static_mut_names: std::collections::HashSet::new(),
        }
    }

    pub fn into_string(self) -> String {
        self.output
    }

    fn indent_str(&self) -> String {
        "    ".repeat(self.indent)
    }

    fn write(&mut self, s: &str) {
        self.output.push_str(s);
    }

    fn write_line(&mut self, s: &str) {
        self.output.push_str(&self.indent_str());
        self.output.push_str(s);
        self.output.push('\n');
    }

    fn blank_line(&mut self) {
        self.output.push('\n');
    }

    fn write_indent(&mut self) {
        self.output.push_str(&self.indent_str());
    }

    fn indent(&mut self) {
        self.indent += 1;
    }

    fn dedent(&mut self) {
        if self.indent > 0 {
            self.indent -= 1;
        }
    }

    /// W638: how many `test` / `invariant` blocks this backend will not lower,
    /// counted over the whole tree so the header can declare the omission.
    /// Does this function declaration carry a body this backend can lower?
    ///
    /// Extracted so the BANNER and the emitter cannot drift: the banner counts
    /// what will become `unimplemented!()`, and it must count it with the same
    /// rule that produces it. Two copies of this list is how `StmtAssign` went
    /// missing from one of them (#2875).
    fn fn_has_body(node: &Node) -> bool {
        node.children.iter().any(|c| {
            matches!(
                c.kind,
                NodeKind::ExprReturn
                    | NodeKind::StmtExpr
                    | NodeKind::StmtLocal
                    | NodeKind::StmtAssign
                    | NodeKind::StmtIf
                    | NodeKind::StmtWhile
                    | NodeKind::StmtFor
                    | NodeKind::StmtForRange
            )
        })
    }

    /// Functions this backend will emit as `unimplemented!()`.
    ///
    /// The banner declared the tests and invariants it drops and said nothing
    /// about these, so a file holding 24 stubs read as complete. A declared
    /// omission is not a hidden one, and this category was not declared.
    fn count_stub_fns(ast: &Node) -> usize {
        fn walk(n: &Node, acc: &mut usize) {
            if n.kind == NodeKind::FnDecl && !RustCodegen::fn_has_body(n) {
                *acc += 1;
            }
            for c in &n.children {
                walk(c, acc);
            }
        }
        let mut acc = 0;
        walk(ast, &mut acc);
        acc
    }

    fn count_unlowered(ast: &Node) -> (usize, usize) {
        fn walk(n: &Node, t: &mut usize, i: &mut usize) {
            match n.kind {
                NodeKind::TestBlock => *t += 1,
                NodeKind::InvariantBlock => *i += 1,
                _ => {}
            }
            for c in &n.children {
                walk(c, t, i);
            }
        }
        let (mut t, mut i) = (0, 0);
        walk(ast, &mut t, &mut i);
        (t, i)
    }

    pub fn gen_rust(&mut self, ast: &Node) {
        // Pre-pass over the whole tree: functions declared `-> bool` return a
        // real Rust bool, so a call to one must not get a `!= 0` guard added in
        // condition position. Declarations may sit at file level or inside a
        // module node, so the scan is recursive.
        self.bool_fns.clear();
        collect_bool_fns(ast, &mut self.bool_fns);

        // Same pre-pass, for the integer widths used by `infer_int_type`:
        // callee return types and module-level constants are both visible from
        // any function body, so they are collected once over the whole tree.
        self.fn_ret_types.clear();
        collect_fn_ret_types(ast, &mut self.fn_ret_types);
        self.const_types.clear();
        collect_const_types(ast, &mut self.const_types);

        // Header
        self.write_line("// Generated from .t27 spec");
        self.write_line("// DO NOT EDIT — generated by t27c");
        // W638: this backend lowers declarations only. Over 80 corpus specs
        // that declare tests, the Rust output contained `#[test]` ZERO times,
        // and nothing in the artefact said so -- a reader comparing backends
        // saw a file with no tests and no way to tell "by design" from
        // "dropped". Emitting library code without tests is a defensible
        // policy; emitting it silently is the defect (T44/T48).
        let (n_tests, n_invariants) = Self::count_unlowered(ast);
        let n_stubs = Self::count_stub_fns(ast);
        if n_tests > 0 || n_invariants > 0 || n_stubs > 0 {
            self.write_line(&format!(
                "// NOT LOWERED BY THIS BACKEND: {} test(s), {} invariant(s), {} \
                 function(s) with no body.",
                n_tests, n_invariants, n_stubs
            ));
            self.write_line(
                "// This backend emits declarations only. The spec's checks live in",
            );
            self.write_line("// the Zig and Verilog outputs; do not read this file as verified.");
        }
        self.blank_line();

        // Find module node
        for child in &ast.children {
            match child.kind {
                NodeKind::Module => {
                    let module_name = &child.name;
                    self.write_line(&format!("// Module: {}", module_name));
                    self.blank_line();
                    self.gen_module(child);
                }
                NodeKind::StructDecl => self.gen_struct(child),
                NodeKind::EnumDecl => self.gen_enum(child),
                NodeKind::ConstDecl => self.gen_const(child),
                NodeKind::FnDecl => self.gen_fn(child),
                _ => {}
            }
        }
    }

    fn gen_module(&mut self, node: &Node) {
        for child in &node.children {
            match child.kind {
                NodeKind::UseDecl => {
                    // Skip use declarations for now
                }
                NodeKind::StructDecl => self.gen_struct(child),
                NodeKind::EnumDecl => self.gen_enum(child),
                NodeKind::ConstDecl => self.gen_const(child),
                NodeKind::FnDecl => self.gen_fn(child),
                _ => {}
            }
        }
    }

    fn gen_struct(&mut self, node: &Node) {
        // The serde derives were unconditional, and the corpus compiles this
        // output as a standalone `--crate-type lib` with no `--extern`. Every
        // struct-bearing spec therefore failed with
        //
        //     error[E0433]: cannot find module or crate `serde`
        //
        // measured as the first error in 23 of 38 sampled specs -- the largest
        // single cause in the Rust column. Behind a cfg the default output
        // compiles against std alone, and anyone who wants serialisation turns
        // the feature on and gets exactly what was emitted before.
        self.write_line("#[derive(Debug, Clone)]");
        self.write_line(
            "#[cfg_attr(feature = \"serde\", derive(serde::Serialize, serde::Deserialize))]",
        );
        self.write_line(&format!("pub struct {} {{", node.name));
        self.indent += 1;
        for child in &node.children {
            // Struct fields are stored as ExprIdentifier with name and extra_type
            if child.kind == NodeKind::ExprIdentifier && !child.name.is_empty() {
                let field_name = &child.name;
                let field_type = Self::t27_type_to_rust(&child.extra_type);
                if field_type.trim() == "bool" {
                    self.bool_fields.insert(field_name.clone());
                }
                self.write_line(&format!("pub {}: {},", field_name, field_type));
            }
        }
        self.indent -= 1;
        self.write_line("}");
        self.blank_line();
    }

    /// Record every module-level `var` before anything is emitted.
    fn collect_static_muts(&mut self, node: &Node) {
        if node.kind == NodeKind::ConstDecl && node.extra_mutable && !node.name.is_empty() {
            self.static_mut_names.insert(node.name.clone());
        }
        for c in &node.children {
            self.collect_static_muts(c);
        }
    }

    /// Does this subtree name a module-level mutable? Then its enclosing
    /// function body has to be `unsafe` in Rust.
    fn touches_static_mut(&self, node: &Node) -> bool {
        if self.static_mut_names.contains(&node.name) {
            return true;
        }
        node.children.iter().any(|c| self.touches_static_mut(c))
    }

    fn gen_enum(&mut self, node: &Node) {
        // Recorded before the body is written, so a member referenced inside
        // the same module resolves however the declarations are ordered.
        self.enum_names.insert(node.name.clone());
        self.write_line("#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]");
        self.write_line(&format!("pub enum {} {{", node.name));
        self.indent += 1;
        for child in &node.children {
            if child.kind == NodeKind::EnumVariant {
                let variant_name = &child.name;
                if child.value.is_empty() {
                    self.write_line(&format!("{},", variant_name));
                } else {
                    self.write_line(&format!("{} = {},", variant_name, child.value));
                }
            }
        }
        self.indent -= 1;
        self.write_line("}");
        self.blank_line();
    }

    fn gen_const(&mut self, node: &Node) {
        let const_type = if node.extra_type.is_empty() {
            "i32".to_string()
        } else {
            Self::t27_type_to_rust(node.extra_type.as_str())
        };
        let value = if node.children.is_empty() {
            "()".to_string()
        } else {
            self.expr_to_rust(&node.children[0])
        };
        // A module-level `var` is MUTABLE. gen-verilog lowers it to a `reg`,
        // gen-c to a `static`, Zig to a `var` -- all three mean shared mutable
        // state, so Rust's answer is `static mut`, and accesses need `unsafe`
        // (added around the body of any function that touches one).
        let kw = if node.extra_mutable {
            "pub static mut"
        } else {
            "pub const"
        };
        self.write_line(&format!(
            "{} {}: {} = {};",
            kw, node.name, const_type, value
        ));
        self.blank_line();
    }

    fn gen_fn(&mut self, node: &Node) {
        let fn_name = &node.name;
        let params: Vec<(String, String)> = node.params.clone();
        let params_str = params
            .iter()
            .map(|(n, t)| format!("{}: {}", n, Self::t27_type_to_rust(t)))
            .collect::<Vec<_>>()
            .join(", ");
        let ret_type = if node.extra_return_type.is_empty() {
            "()".to_string()
        } else {
            Self::t27_type_to_rust(node.extra_return_type.as_str())
        };

        self.fn_ret_type = ret_type.clone();
        self.write(&format!(
            "pub fn {}({}) -> {} {{",
            fn_name, params_str, ret_type
        ));

        // Check if there's a body
        let has_body = Self::fn_has_body(node);

        // Infer which locals need `let mut`: scan body for any assignment.
        self.mut_names.clear();
        collect_mutable_names(&node.children, &mut self.mut_names);

        // Same reason as bool_fns, for parameters and locals declared `bool`.
        self.bool_vars.clear();
        for (pname, ptype) in &params {
            if ptype.trim() == "bool" {
                self.bool_vars.insert(pname.clone());
            }
        }
        collect_bool_locals(&node.children, &mut self.bool_vars);

        // Declared widths of this function's parameters and locals, so a
        // `return` of a narrower/wider value can be cast to the return type.
        self.var_types.clear();
        for (pname, ptype) in &params {
            if !ptype.trim().is_empty() {
                self.var_types
                    .insert(pname.clone(), Self::t27_type_to_rust(ptype));
            }
        }
        collect_typed_locals(&node.children, &mut self.var_types);
        // A local declared without a type still has one — `let n = x as u16`
        // is a u16. Recorded after the explicit types above, so a declared
        // type always wins over an inferred one.
        self.record_inferred_locals(&node.children);

        // Any access to a `static mut` is unsafe in Rust. Wrapping the whole
        // body is the smallest correct answer: the alternative is an `unsafe`
        // block around every read and write, which needs the expression
        // emitter to know the set at each site.
        let body_unsafe = node.children.iter().any(|c| self.touches_static_mut(c));
        if has_body {
            self.output.push('\n');
            self.indent += 1;
            if body_unsafe {
                self.write_line("unsafe {");
                self.indent += 1;
            }
            for child in &node.children {
                match child.kind {
                    NodeKind::ExprReturn => {
                        let val = if child.children.is_empty() {
                            "()".to_string()
                        } else {
                            { let rt = self.fn_ret_type.clone(); self.expr_to_rust_as(&child.children[0], &rt) }
                        };
                        self.write_line(&format!("return {};", val));
                    }
                    NodeKind::StmtExpr => {
                        if child.children.len() == 1 {
                            let expr = self.expr_to_rust(&child.children[0]);
                            self.write_line(&format!("{};", expr));
                        }
                    }
                    NodeKind::StmtLocal
                        if child.name.is_empty() && !child.extra_field.is_empty() =>
                    {
                        // Tuple-destructuring binding: `let (a, b) = init`.
                        let val = if child.children.is_empty() {
                            "()".to_string()
                        } else {
                            self.expr_to_rust(&child.children[0])
                        };
                        self.write_line(&format!("let ({}) = {};", child.extra_field, val));
                    }
                    NodeKind::StmtLocal => {
                        let mutable = child.extra_mutable || self.mut_names.contains(&child.name);
                        let kw = if mutable { "let mut" } else { "let" };
                        let var_name = &child.name;
                        let typ = Self::t27_type_to_rust(&child.extra_type);
                        if child.children.is_empty() {
                            if child.extra_type.is_empty() {
                                self.write_line(&format!("{} {};", kw, var_name));
                            } else {
                                self.write_line(&format!("{} {}: {};", kw, var_name, typ));
                            }
                        } else {
                            let val = self.expr_to_rust(&child.children[0]);
                            if child.extra_type.is_empty() {
                                self.write_line(&format!("{} {} = {};", kw, var_name, val));
                            } else {
                                self.write_line(&format!(
                                    "{} {}: {} = {};",
                                    kw, var_name, typ, val
                                ));
                            }
                        }
                    }
                    NodeKind::StmtAssign => {
                        let target = if child.children.is_empty() {
                            child.name.clone()
                        } else {
                            self.expr_to_rust(&child.children[0])
                        };
                        if child.children.len() >= 2 {
                            let val = self.expr_to_rust(&child.children[1]);
                            // Both Rust arms hardcoded " = " and never read `extra_op`,
                            // so EVERY compound assignment became a plain store. Zig and C
                            // emit 33 across the corpus; Rust emitted 0.
                            self.write_line(&format!(
                                "{}{}{};",
                                target,
                                assign_op_text(&child.extra_op),
                                val
                            ));
                        } else {
                            self.write_line(&format!("{};", target));
                        }
                    }
                    NodeKind::StmtIf => {
                        self.write_indent();
                        self.write("if ");
                        if !child.children.is_empty() {
                            self.write(&self.expr_to_rust_cond(&child.children[0]));
                        }
                        self.write(" {\n");
                        self.indent += 1;
                        if child.children.len() > 1 {
                            for stmt in &child.children[1].children {
                                self.gen_rust_stmt(stmt);
                            }
                        }
                        self.indent -= 1;
                        if child.children.len() > 2 {
                            self.write_indent();
                            self.write("} else {\n");
                            self.indent += 1;
                            for stmt in &child.children[2].children {
                                self.gen_rust_stmt(stmt);
                            }
                            self.indent -= 1;
                        }
                        self.write_line("}");
                    }
                    NodeKind::StmtWhile => {
                        self.write_indent();
                        self.write("while ");
                        if !child.children.is_empty() {
                            self.write(&self.expr_to_rust_cond(&child.children[0]));
                        }
                        self.write(" {\n");
                        self.indent += 1;
                        if child.children.len() > 1 {
                            for stmt in &child.children[child.children.len() - 1].children {
                                self.gen_rust_stmt(stmt);
                            }
                            // body is the LAST child; `while (c) : (step)` puts the step at [1],
                            // and Rust has no continue expression, so it becomes the last statement.
                            if child.children.len() > 2 {
                                self.gen_rust_stmt(unwrap_single(&child.children[1]));
                            }
                        }
                        self.indent -= 1;
                        self.write_line("}");
                    }
                    NodeKind::StmtFor => {
                        self.write_indent();
                        self.write("for ");
                        // The capture lives in `params` in BOTH shapes the parser builds:
                        // `for (xs) |x| { }` pushes it there and so does the bare
                        // `for x in xs { }` collection form. This read `children[1].name`,
                        // and for the bare form children[1] is the BODY BLOCK, whose name is
                        // the literal "body" -- so every range loop emitted `for body in ..`.
                        let capture = child
                            .params
                            .first()
                            .map(|(n, _)| n.clone())
                            .unwrap_or_else(|| {
                                if child.children.len() > 1 {
                                    child.children[1].name.clone()
                                } else {
                                    String::new()
                                }
                            });
                        self.write(&capture);
                        self.write(" in ");
                        if !child.children.is_empty() {
                            self.write(&self.expr_to_rust(&child.children[0]));
                        }
                        self.write(" {\n");
                        self.indent += 1;
                        // The body is the LAST child, not children[2]. The bare form builds
                        // two children -- iterable, body -- so the body was dropped entirely
                        // and the loop emitted empty, with exit code 0.
                        if child.children.len() > 1 {
                            if let Some(body) = child.children.last() {
                                for stmt in &body.children {
                                    self.gen_rust_stmt(stmt);
                                }
                            }
                        }
                        self.indent -= 1;
                        self.write_line("}");
                    }
                    NodeKind::StmtForRange => {
                        self.write_indent();
                        self.write(&format!("for {} in ", child.name));
                        if child.children.len() >= 2 {
                            self.write(&self.expr_to_rust(&child.children[0]));
                            self.write("..");
                            self.write(&self.expr_to_rust(&child.children[1]));
                        }
                        self.write(" {\n");
                        self.indent += 1;
                        if child.children.len() > 2 {
                            for stmt in &child.children[2].children {
                                self.gen_rust_stmt(stmt);
                            }
                        }
                        self.indent -= 1;
                        self.write_line("}");
                    }
                    _ => {}
                }
            }
            if body_unsafe {
                self.indent -= 1;
                self.write_line("}");
            }
            self.indent -= 1;
            self.write_line("}");
        } else {
            self.write_line(" unimplemented!() }");
        }
        self.blank_line();
    }

    fn gen_rust_stmt(&mut self, stmt: &Node) {
        match stmt.kind {
            NodeKind::ExprReturn => {
                let val = if stmt.children.is_empty() {
                    "()".to_string()
                } else {
                    { let rt = self.fn_ret_type.clone(); self.expr_to_rust_as(&stmt.children[0], &rt) }
                };
                self.write_line(&format!("return {};", val));
            }
            NodeKind::StmtExpr => {
                if stmt.children.len() == 1 {
                    self.write_line(&format!("{};", self.expr_to_rust(&stmt.children[0])));
                }
            }
            NodeKind::StmtLocal => {
                // Tuple-destructuring binding: `let (a, b) = init` (name empty,
                // pattern stored in extra_field by parse_local_decl).
                if stmt.name.is_empty() && !stmt.extra_field.is_empty() {
                    let val = if stmt.children.is_empty() {
                        "()".to_string()
                    } else {
                        self.expr_to_rust(&stmt.children[0])
                    };
                    self.write_line(&format!("let ({}) = {};", stmt.extra_field, val));
                    return;
                }
                let kw = if stmt.extra_mutable || self.mut_names.contains(&stmt.name) { "let mut" } else { "let" };
                let typ = Self::t27_type_to_rust(&stmt.extra_type);
                if stmt.children.is_empty() {
                    if stmt.extra_type.is_empty() {
                        self.write_line(&format!("{} {};", kw, stmt.name));
                    } else {
                        self.write_line(&format!("{} {}: {};", kw, stmt.name, typ));
                    }
                } else {
                    let val = self.expr_to_rust(&stmt.children[0]);
                    if stmt.extra_type.is_empty() {
                        self.write_line(&format!("{} {} = {};", kw, stmt.name, val));
                    } else {
                        self.write_line(&format!("{} {}: {} = {};", kw, stmt.name, typ, val));
                    }
                }
            }
            NodeKind::StmtAssign => {
                if stmt.children.len() >= 2 {
                    let target = self.expr_to_rust(&stmt.children[0]);
                    let val = self.expr_to_rust(&stmt.children[1]);
                    self.write_line(&format!(
                        "{}{}{};",
                        target,
                        assign_op_text(&stmt.extra_op),
                        val
                    ));
                }
            }
            NodeKind::StmtIf => {
                self.write_indent();
                self.write("if ");
                if !stmt.children.is_empty() {
                    self.write(&self.expr_to_rust_cond(&stmt.children[0]));
                }
                self.write(" {\n");
                self.indent += 1;
                if stmt.children.len() > 1 {
                    for s in &stmt.children[1].children {
                        self.gen_rust_stmt(s);
                    }
                }
                self.indent -= 1;
                if stmt.children.len() > 2 {
                    self.write_indent();
                    self.write("} else {\n");
                    self.indent += 1;
                    for s in &stmt.children[2].children {
                        self.gen_rust_stmt(s);
                    }
                    self.indent -= 1;
                }
                self.write_line("}");
            }
            NodeKind::StmtWhile => {
                self.write_indent();
                self.write("while ");
                if !stmt.children.is_empty() {
                    self.write(&self.expr_to_rust_cond(&stmt.children[0]));
                }
                self.write(" {\n");
                self.indent += 1;
                if stmt.children.len() > 1 {
                    for s in &stmt.children[stmt.children.len() - 1].children {
                        self.gen_rust_stmt(s);
                    }
                    // body is the LAST child; `while (c) : (step)` puts the step at [1],
                    // and Rust has no continue expression, so it becomes the last statement.
                    if stmt.children.len() > 2 {
                        self.gen_rust_stmt(unwrap_single(&stmt.children[1]));
                    }
                }
                self.indent -= 1;
                self.write_line("}");
            }
            NodeKind::StmtBreak => {
                self.write_line("break;");
            }
            NodeKind::StmtContinue => {
                self.write_line("continue;");
            }
            NodeKind::StmtFor => {
                self.write_indent();
                self.write("for ");
                // The capture lives in `params` in BOTH shapes the parser builds:
                // `for (xs) |x| { }` pushes it there and so does the bare
                // `for x in xs { }` collection form. This read `children[1].name`,
                // and for the bare form children[1] is the BODY BLOCK, whose name is
                // the literal "body" -- so every range loop emitted `for body in ..`.
                let capture = stmt
                    .params
                    .first()
                    .map(|(n, _)| n.clone())
                    .unwrap_or_else(|| {
                        if stmt.children.len() > 1 {
                            stmt.children[1].name.clone()
                        } else {
                            String::new()
                        }
                    });
                self.write(&capture);
                self.write(" in ");
                if !stmt.children.is_empty() {
                    self.write(&self.expr_to_rust(&stmt.children[0]));
                }
                self.write(" {\n");
                self.indent += 1;
                // The body is the LAST child, not children[2]. The bare form builds
                // two children -- iterable, body -- so the body was dropped entirely
                // and the loop emitted empty, with exit code 0.
                if stmt.children.len() > 1 {
                    if let Some(body) = stmt.children.last() {
                        for s in &body.children {
                            self.gen_rust_stmt(s);
                        }
                    }
                }
                self.indent -= 1;
                self.write_line("}");
            }
            NodeKind::StmtForRange => {
                self.write_indent();
                self.write(&format!("for {} in ", stmt.name));
                if stmt.children.len() >= 2 {
                    self.write(&self.expr_to_rust(&stmt.children[0]));
                    self.write("..");
                    self.write(&self.expr_to_rust(&stmt.children[1]));
                }
                self.write(" {\n");
                self.indent += 1;
                if stmt.children.len() > 2 {
                    for s in &stmt.children[2].children {
                        self.gen_rust_stmt(s);
                    }
                }
                self.indent -= 1;
                self.write_line("}");
            }
            _ => {}
        }
    }

    /// Zig builtins, in Rust.
    ///
    /// t27's surface is Zig-shaped, so `@as`, `@intCast`, `@min` and friends
    /// appear in specs. The Rust emitter passed them through verbatim -- 27
    /// distinct builtins, ~250 occurrences across 43 specs -- and `@as(u32, x)`
    /// is not Rust, so every one of those files failed to compile. Nothing
    /// reported it, because `corpus` did not measure the Rust backend at all.
    ///
    /// Two groups, and the difference matters. Where Zig names the target type
    /// the translation is exact. Where Zig INFERS it from context (`@intCast`,
    /// `@floatFromInt`) the honest Rust is `as _`, which asks rustc to infer
    /// from the same context -- a `let` with a declared type, or a `return` in
    /// a typed fn. Guessing a concrete width instead would be a silent wrong
    /// answer, which is the defect class this backend has just been cleared of.
    fn zig_builtin_to_rust(name: &str, args: &[String]) -> Option<String> {
        if !name.starts_with('@') {
            return None;
        }
        let a = |i: usize| args.get(i).cloned().unwrap_or_default();
        let two = args.len() == 2;
        let one = args.len() == 1;
        Some(match name {
            // Target named by the source: exact.
            "@as" if two => format!("({} as {})", a(1), Self::t27_type_to_rust(&a(0))),
            "@intCast" | "@floatCast" | "@truncate" if two => {
                format!("({} as {})", a(1), Self::t27_type_to_rust(&a(0)))
            }
            "@intFromFloat" | "@floatFromInt" if two => {
                format!("({} as {})", a(1), Self::t27_type_to_rust(&a(0)))
            }
            // Target inferred from context, exactly as in Zig.
            "@intCast" | "@floatCast" | "@truncate" | "@intFromFloat" | "@floatFromInt"
                if one =>
            {
                format!("({} as _)", a(0))
            }
            // A fieldless enum casts to its discriminant in both languages.
            "@intFromEnum" if one => format!("({} as i32)", a(0)),
            // Method calls in Rust.
            "@min" if two => format!("({}).min({})", a(0), a(1)),
            "@max" if two => format!("({}).max({})", a(0), a(1)),
            "@sqrt" | "@abs" | "@round" | "@floor" | "@ceil" | "@trunc" | "@exp" | "@log"
            | "@sin" | "@cos" | "@tan"
                if one =>
            {
                format!("({}).{}()", a(0), &name[1..])
            }
            // Operators in Rust.
            "@rem" if two => format!("({} % {})", a(0), a(1)),
            "@mod" if two => format!("({}).rem_euclid({})", a(0), a(1)),
            "@divTrunc" if two => format!("({} / {})", a(0), a(1)),
            "@divFloor" if two => format!("({}).div_euclid({})", a(0), a(1)),
            // Anything else keeps its spelling: a wrong translation is worse
            // than an untranslated one, because the first compiles.
            _ => return None,
        })
    }

    fn t27_type_to_rust(t27_type: &str) -> String {
        let t = t27_type.trim();
        // Handle optional types. t27 writes the Zig spelling -- a LEADING `?`
        // (`?u64`, `?[]u8`) -- and only the trailing form was recognised, so
        // W581's newly-visible optionals fell through to the default and Rust
        // received `?[]u8`, which does not compile.
        let (base_type, is_optional) = if let Some(rest) = t.strip_prefix('?') {
            (rest.trim(), true)
        } else if t.ends_with('?') {
            (&t[..t.len() - 1], true)
        } else {
            (t, false)
        };

        let rust_type = match base_type {
            "u8" | "u16" | "u32" | "u64" | "u128" => base_type.to_string(),
            "i8" | "i16" | "i32" | "i64" | "i128" => base_type.to_string(),
            "f32" | "f64" => base_type.to_string(),
            "GF16" | "gf16" => "u16".to_string(),
            "bool" => "bool".to_string(),
            "str" => "String".to_string(),
            "void" => "()".to_string(),
            t if t.starts_with("[]") => {
                // `[]const u8` is the Zig spelling of a slice of const u8, and
                // the `const` qualifies the POINTEE. Rust's `Vec<T>` has no
                // such qualifier, and carrying it through produced
                //
                //     pub reason: Option<Vec<const u8>>,
                //
                // which rustc cannot even parse. 84 of 559 generated files
                // contained one; they were not among the specs any first-error
                // histogram named, because rustc gives up before it reaches a
                // diagnosable error code.
                let inner = t[2..].trim_start();
                let inner = inner.strip_prefix("const ").unwrap_or(inner);
                format!("Vec<{}>", Self::t27_type_to_rust(inner))
            }
            // [T; N] form (Rust-style fixed array). Must stay a real array:
            // dropping the element type produced `Vec<>`, which does not compile.
            t if t.starts_with('[') && t.ends_with(']') && t[1..].contains(';') => {
                let body = &t[1..t.len() - 1];
                match body.split_once(';') {
                    Some((elem, len)) => {
                        let elem_rust = Self::t27_type_to_rust(elem.trim());
                        let len = len.trim();
                        if len.chars().all(|c| c.is_ascii_digit()) {
                            format!("[{}; {}]", elem_rust, len)
                        } else {
                            // Named constants are emitted as u32; array lengths must be usize.
                            format!("[{}; {} as usize]", elem_rust, len)
                        }
                    }
                    None => t.to_string(),
                }
            }
            t if t.starts_with('[') && t.contains(']') => {
                let end = t.rfind(']').unwrap();
                let inside = &t[1..end];
                if let Some(semi) = inside.find(';') {
                    // Rust-style fixed-size array `[T; N]`: element before `;`,
                    // size after. (Previously only the Zig-style `[N]T` form was
                    // handled; `[T; N]` took the empty suffix after `]` and emitted
                    // `Vec<>` -> E0107. #1457.) Array lengths must be `usize`, and
                    // spec size consts are u32, so cast in the const-expr position.
                    let elem = inside[..semi].trim();
                    let size = inside[semi + 1..].trim();
                    format!("[{}; {} as usize]", Self::t27_type_to_rust(elem), size)
                } else {
                    // Zig-style `[N]T`: size in brackets, element after `]`.
                    let after = &t[end + 1..];
                    format!("Vec<{}>", Self::t27_type_to_rust(after))
                }
            }
            t => t.to_string(), // Custom type name
        };

        if is_optional {
            format!("Option<{}>", rust_type)
        } else {
            rust_type
        }
    }

    /// Syntactic test: does this expression already evaluate to a Rust `bool`?
    /// t27 treats comparisons as integers; Rust does not, so every crossing
    /// between the two has to be made explicit.
    fn expr_is_bool(&self, node: &Node) -> bool {
        match node.kind {
            NodeKind::ExprBinary => matches!(
                node.extra_op.as_str(),
                "==" | "!=" | "<" | "<=" | ">" | ">=" | "and" | "or" | "&&" | "||"
            ),
            NodeKind::ExprUnary => node.extra_op == "!" || node.extra_op == "not",
            NodeKind::ExprLiteral => node.value == "true" || node.value == "false",
            NodeKind::ExprIdentifier => self.bool_vars.contains(&node.name),
            NodeKind::ExprCall => self.bool_fns.contains(&node.name),
            NodeKind::ExprFieldAccess => self.bool_fields.contains(&node.name),
            _ => false,
        }
    }

    /// Emit an expression in a condition position (`if`, `while`).
    fn expr_to_rust_cond(&self, node: &Node) -> String {
        let s = self.expr_to_rust(node);
        if self.expr_is_bool(node) {
            s
        } else {
            format!("({}) != 0", s)
        }
    }

    fn is_int_type(ty: &str) -> bool {
        matches!(
            ty.trim(),
            "u8" | "u16" | "u32" | "u64" | "u128" | "i8" | "i16" | "i32" | "i64" | "i128" | "usize" | "isize"
        )
    }

    /// Best-effort width inference for an integer-valued expression, in Rust
    /// type names. `None` means "no declared width to go on" — either the
    /// expression is an unsuffixed literal (which Rust infers at the use site)
    /// or its type was never declared — and callers must not force a cast on
    /// that, since the inference is what makes the existing output compile.
    fn infer_int_type(&self, node: &Node) -> Option<String> {
        let known = |t: &String| {
            if Self::is_int_type(t) {
                Some(t.clone())
            } else {
                None
            }
        };
        match node.kind {
            NodeKind::ExprIdentifier => self
                .var_types
                .get(&node.name)
                .or_else(|| self.const_types.get(&node.name))
                .and_then(known),
            NodeKind::ExprCall => self.fn_ret_types.get(&node.name).and_then(known),
            NodeKind::ExprCast => {
                let target = node.extra_type.split('[').next().unwrap_or("").trim();
                if Self::is_int_type(target) {
                    Some(target.to_string())
                } else {
                    None
                }
            }
            NodeKind::ExprUnary if node.children.len() == 1 => {
                self.infer_int_type(&node.children[0])
            }
            NodeKind::ExprBinary if node.children.len() >= 2 => {
                // Comparisons and logical ops are `bool`, not integers.
                if self.expr_is_bool(node) {
                    return None;
                }
                // A shift takes the width of its left operand.
                let left = self.infer_int_type(&node.children[0]);
                if node.extra_op == "<<" || node.extra_op == ">>" {
                    return left;
                }
                // Otherwise the result is whatever `coerce_binary_operands`
                // widened both sides to; the two must stay in agreement.
                match (left, self.infer_int_type(&node.children[1])) {
                    (Some(a), Some(b)) => Some(Self::join_int_types(&a, &b)),
                    (Some(a), None) => Some(a),
                    (None, right) => right,
                }
            }
            _ => None,
        }
    }

    /// Record the width of every untyped local whose initialiser has one, in
    /// source order so a local may be inferred from an earlier local. Locals
    /// initialised from a bare literal are deliberately left unknown — Rust
    /// infers those at the use site, and pinning a width here could conflict.
    fn record_inferred_locals(&mut self, nodes: &[Node]) {
        for n in nodes {
            if n.kind == NodeKind::StmtLocal
                && !n.name.is_empty()
                && n.extra_type.trim().is_empty()
                && !n.children.is_empty()
                && !self.var_types.contains_key(&n.name)
            {
                if let Some(t) = self.infer_int_type(&n.children[0]) {
                    self.var_types.insert(n.name.clone(), t);
                }
            }
            self.record_inferred_locals(&n.children);
        }
    }

    /// Bit width of a Rust integer type name. `usize`/`isize` are treated as
    /// 64-bit, matching every target this repo builds for.
    fn int_rank(ty: &str) -> u32 {
        match ty.trim() {
            "u8" | "i8" => 8,
            "u16" | "i16" => 16,
            "u32" | "i32" => 32,
            "u64" | "i64" | "usize" | "isize" => 64,
            "u128" | "i128" => 128,
            _ => 0,
        }
    }

    /// Common type for a mixed-width binary operation: the wider operand wins.
    /// Equal ranks that still differ (`u32`/`i32`, `u64`/`usize`) resolve to
    /// the left operand, matching the left-biased inference above.
    fn join_int_types(a: &str, b: &str) -> String {
        if Self::int_rank(a) >= Self::int_rank(b) {
            a.to_string()
        } else {
            b.to_string()
        }
    }

    /// Rust requires both operands of an arithmetic/bitwise/comparison operator
    /// to have the *same* integer type; t27 does not. Cast the narrower side up
    /// so the emitted operator compiles. Shifts are exempt — Rust already
    /// accepts any integer type as the shift amount.
    fn coerce_binary_operands(&self, node: &Node, left: &mut String, right: &mut String) {
        if matches!(node.extra_op.as_str(), "<<" | ">>") {
            return;
        }
        let (lt, rt) = match (
            self.infer_int_type(&node.children[0]),
            self.infer_int_type(&node.children[1]),
        ) {
            (Some(lt), Some(rt)) => (lt, rt),
            _ => return,
        };
        if lt == rt {
            return;
        }
        let common = Self::join_int_types(&lt, &rt);
        if lt != common {
            *left = format!("({} as {})", left, common);
        }
        if rt != common {
            *right = format!("({} as {})", right, common);
        }
    }

    /// Emit an expression in an integer position (return value, typed local).
    fn expr_to_rust_as(&self, node: &Node, ty: &str) -> String {
        let s = self.expr_to_rust(node);
        let ty = ty.trim();
        if !Self::is_int_type(ty) {
            return s;
        }
        if self.expr_is_bool(node) {
            return format!("({}) as {}", s, ty);
        }
        // Rust has no implicit integer widening: returning a `u8` parameter or
        // a `u64` expression from a `-> u32` function is E0308. t27 accepts the
        // mixed widths, so the cast has to be materialised here.
        match self.infer_int_type(node) {
            Some(actual) if actual != ty => format!("({}) as {}", s, ty),
            _ => s,
        }
    }

    fn expr_to_rust(&self, node: &Node) -> String {
        match node.kind {
            NodeKind::ExprLiteral => node.value.clone(),
            NodeKind::ExprIdentifier => node.name.clone(),
            NodeKind::ExprBinary => {
                if node.children.len() >= 2 {
                    let mut left = self.expr_to_rust(&node.children[0]);
                    let mut right = self.expr_to_rust(&node.children[1]);
                    self.coerce_binary_operands(node, &mut left, &mut right);
                    // Zig-style wrapping operators (+% -% *%) have no infix form
                    // in Rust; lower them to the wrapping_* methods. Emitting the
                    // literal operator produced uncompilable Rust. Checked +/-/*
                    // stay infix so the Rust backend keeps the same overflow-panic
                    // semantics as the Zig backend.
                    if let Some(method) = match node.extra_op.as_str() {
                        "+%" => Some("wrapping_add"),
                        "-%" => Some("wrapping_sub"),
                        "*%" => Some("wrapping_mul"),
                        _ => None,
                    } {
                        return format!("({}).{}({})", left, method, right);
                    }
                    let op = match node.extra_op.as_str() {
                        "and" => "&&",
                        "or" => "||",
                        op => op,
                    };
                    format!("({} {} {})", left, op, right)
                } else {
                    "()".to_string()
                }
            }
            NodeKind::ExprCall => {
                let args: Vec<String> = node
                    .children
                    .iter()
                    .map(|c| self.expr_to_rust(c))
                    .collect();
                if let Some(built) = Self::zig_builtin_to_rust(&node.name, &args) {
                    return built;
                }
                format!("{}({})", node.name, args.join(", "))
            }
            NodeKind::ExprArrayLiteral => {
                if node.children.is_empty() && !node.extra_size.trim().is_empty() {
                    // The parser stores the literal's ELEMENT TEXT in
                    // extra_size ("a,b,c" for a list, "v;n" for a repeat)
                    // with no children; emitting from children alone
                    // produced an empty (and Vec-typed) literal for a
                    // [T; N] return. Element text is valid Rust as-is.
                    let txt = node.extra_size.trim();
                    if let Some((val, count)) = txt.rsplit_once(';') {
                        format!("[{}; {}]", val.trim(), count.trim())
                    } else {
                        format!("[{}]", txt)
                    }
                } else {
                    let elems: Vec<String> = node
                        .children
                        .iter()
                        .map(|c| self.expr_to_rust(c))
                        .collect();
                    format!("[{}]", elems.join(", "))
                }
            }
            NodeKind::ExprTuple => {
                let elems: Vec<String> = node
                    .children
                    .iter()
                    .map(|c| self.expr_to_rust(c))
                    .collect();
                format!("({})", elems.join(", "))
            }
            NodeKind::ExprStructLit => {
                let fields: Vec<String> = node
                    .children
                    .iter()
                    .map(|c| {
                        let val = if c.children.is_empty() {
                            "{}".to_string()
                        } else {
                            self.expr_to_rust(&c.children[0])
                        };
                        format!("{}: {}", c.name, val)
                    })
                    .collect();
                format!("{} {{ {} }}", node.name, fields.join(", "))
            }
            NodeKind::ExprEnumValue => {
                if node.extra_field.is_empty() {
                    // Shorthand `.variant`. t27 takes the enum from context the
                    // way Zig does; Rust has no such rule, so the emitter must
                    // supply it. The context available here is the declared
                    // return type of the function being emitted - exactly the
                    // case the shorthand is written for. Without it the variant
                    // was printed on the LEFT of the separator: `escalate::`.
                    if self.enum_names.contains(&self.fn_ret_type) {
                        format!("{}::{}", self.fn_ret_type, node.name)
                    } else {
                        node.name.clone()
                    }
                } else {
                    format!("{}::{}", node.name, node.extra_field)
                }
            }
            NodeKind::ExprUnary => {
                if !node.children.is_empty() {
                    let operand = &node.children[0];
                    // `!x` on an integer is logical negation in t27 but bitwise
                    // negation in Rust; emit an explicit zero test instead.
                    // On an operand that is already a Rust `bool` (comparison,
                    // `bool` parameter/local, or call to a `-> bool` function)
                    // the zero test is itself uncompilable — `bool == {integer}`
                    // is E0308 — so `!` has to stay `!`.
                    if (node.extra_op == "!" || node.extra_op == "not")
                        && !self.expr_is_bool(operand)
                    {
                        format!("(({}) == 0)", self.expr_to_rust(operand))
                    } else {
                        format!("{}({})", node.extra_op, self.expr_to_rust(operand))
                    }
                } else {
                    node.extra_op.clone()
                }
            }
            NodeKind::ExprFieldAccess => {
                if !node.children.is_empty() {
                    let base = self.expr_to_rust(&node.children[0]);
                    // An enum member is a path in Rust and a field access in
                    // t27's Zig-shaped syntax. Only the base tells them apart.
                    if self.enum_names.contains(&base) {
                        format!("{}::{}", base, node.name)
                    } else {
                        format!("{}.{}", base, node.name)
                    }
                } else {
                    node.name.clone()
                }
            }
            NodeKind::ExprIndex => {
                if node.children.len() >= 2 {
                    let base = self.expr_to_rust(&node.children[0]);
                    let idx = &node.children[1];
                    let idx_str = self.expr_to_rust(idx);
                    // Array/Vec indices must be usize. t27 index expressions are
                    // u32, so cast non-literal indices. Integer literals infer
                    // usize in index position, so casting them would trip clippy.
                    if idx.kind == NodeKind::ExprLiteral {
                        format!("{}[{}]", base, idx_str)
                    } else {
                        format!("{}[({}) as usize]", base, idx_str)
                    }
                } else {
                    "()".to_string()
                }
            }
            NodeKind::ExprIf => {
                let mut s = format!("if {} {{ ", self.expr_to_rust(&node.children[0]));
                if node.children.len() > 1 {
                    s.push_str(&self.expr_to_rust(&node.children[1]));
                }
                s.push_str(" }");
                if node.children.len() > 2 {
                    s.push_str(&format!(
                        " else {{ {} }}",
                        self.expr_to_rust(&node.children[2])
                    ));
                }
                s
            }
            NodeKind::ExprSwitch => {
                if node.children.is_empty() {
                    return "/* switch */".to_string();
                }
                let scrutinee = self.expr_to_rust(&node.children[0]);
                // The arms carry Zig-shaped `.variant` shorthand, and Rust has
                // no rule that resolves it from context. The scrutinee's
                // declared type IS the enum, and `var_types` already holds
                // every parameter and local with its Rust type, so a
                // bare-identifier scrutinee resolves exactly. Anything else
                // falls back to the function's return type -- the same rule
                // ExprEnumValue uses for the shorthand a few arms above.
                let arm_enum = self
                    .var_types
                    .get(&scrutinee)
                    .filter(|t| self.enum_names.contains(*t))
                    .cloned()
                    .or_else(|| {
                        if self.enum_names.contains(&self.fn_ret_type) {
                            Some(self.fn_ret_type.clone())
                        } else {
                            None
                        }
                    });
                let mut s = format!("match {} {{\n", scrutinee);
                for i in 1..node.children.len() {
                    let arm = &node.children[i];
                    // The parser builds EVERY arm as ConstDecl. This tested for
                    // Module, which no arm is ever built as, so the loop
                    // matched nothing and the emitter printed `match x { }` --
                    // an empty match, with exit code 0, for a construct the
                    // other three backends lower correctly. Leaving the pattern
                    // unqualified would have been worse than the empty match:
                    // `match a { neg => .. }` is a BINDING in Rust, it compiles
                    // and it matches everything.
                    if arm.kind != NodeKind::ConstDecl {
                        continue;
                    }
                    // `else` is t27's catch-all; numbers and char literals are
                    // patterns in their own right and must not be qualified.
                    let names_a_variant = arm
                        .name
                        .chars()
                        .next()
                        .is_some_and(|c| c.is_alphabetic() || c == '_');
                    let pattern = if arm.name.is_empty() || arm.name == "else" {
                        "_".to_string()
                    } else if names_a_variant {
                        match &arm_enum {
                            Some(e) => format!("{}::{}", e, arm.name),
                            None => arm.name.clone(),
                        }
                    } else {
                        arm.name.clone()
                    };
                    let body = if !arm.children.is_empty() {
                        self.expr_to_rust(&arm.children[0])
                    } else {
                        "()".to_string()
                    };
                    s.push_str(&format!("{} => {},\n", pattern, body));
                }
                s.push('}');
                s
            }
            NodeKind::ExprCast => {
                if node.children.is_empty() {
                    "()".to_string()
                } else {
                    let operand = self.expr_to_rust(&node.children[0]);
                    let target = node
                        .extra_type
                        .split('[')
                        .next()
                        .unwrap_or("")
                        .trim();
                    if target.is_empty() {
                        operand
                    } else {
                        format!("({} as {})", operand, target)
                    }
                }
            }
            _ => "()".to_string(),
        }
    }
}

// ============================================================================
// Hardware IR (HIR) — Phase 0 FPGA foundation
// ============================================================================

#[derive(Debug, Clone, PartialEq)]
// Variant S (#969 dead-code audit, HIR/FPGA grammar layer): the Hardware IR
// node-kind enums below model the full target HDL/FPGA grammar surface
// (clock/reset kinds, edge sensitivity, always-block statement kinds, memory
// kinds, clock-domain-crossing and FIFO strategies). Several variants are not
// yet constructed by the current lowering passes, so each emits a
// `never constructed` dead_code warning -- but they are an intentional,
// spec-complete AST surface kept for the Phase-0 FPGA foundation, not dead
// code. A targeted per-enum allow documents that without removing any variant
// or weakening the type; same conservative annotate-not-delete pattern as the
// #1111 / #1122 host slices. Scoped narrowly to these enums (NOT the file).
#[allow(dead_code)]
pub enum HwType {
    Bits(u32),
    UInt(u32),
    SInt(u32),
    Bool,
    Clock,
    Reset(HwResetKind, HwResetPolarity),
    Vector(Box<HwType>, u32),
    Bundle(Vec<(String, HwType)>),
    Enum(Vec<(String, String)>),
    GF16,
}

#[derive(Debug, Clone, PartialEq)]
#[allow(dead_code)]
pub enum HwResetKind {
    Async,
    Sync,
}

#[derive(Debug, Clone, PartialEq)]
#[allow(dead_code)]
pub enum HwResetPolarity {
    ActiveHigh,
    ActiveLow,
}

impl HwType {
    pub fn hw_width(&self) -> u32 {
        match self {
            HwType::Bits(w) | HwType::UInt(w) | HwType::SInt(w) => *w,
            HwType::Bool | HwType::Clock => 1,
            HwType::Reset(_, _) => 1,
            HwType::Vector(elem, len) => elem.hw_width() * len,
            HwType::Bundle(fields) => fields.iter().map(|(_, t)| t.hw_width()).sum(),
            HwType::Enum(variants) => {
                let n = variants.len() as u32;
                if n <= 2 {
                    1
                } else if n <= 4 {
                    2
                } else if n <= 8 {
                    3
                } else if n <= 16 {
                    4
                } else if n <= 32 {
                    5
                } else if n <= 64 {
                    6
                } else {
                    8
                }
            }
            HwType::GF16 => 16,
        }
    }

    pub fn is_signed(&self) -> bool {
        matches!(self, HwType::SInt(_))
    }

    pub fn is_clock_like(&self) -> bool {
        matches!(self, HwType::Clock)
    }

    pub fn is_reset_like(&self) -> bool {
        matches!(self, HwType::Reset(_, _))
    }

    pub fn verilog_range(&self) -> String {
        let w = self.hw_width();
        if w <= 1 {
            String::new()
        } else {
            format!("[{}:0]", w - 1)
        }
    }
}

