#[derive(Debug, Clone)]
pub struct VcdChange {
    pub timestamp_ps: u64,
    pub ident: String,
    pub value: u32,
    pub bit_width: u32,
}

impl VcdChange {
    pub fn new(ts: u64, ident: &str, value: u32, width: u32) -> Self {
        VcdChange {
            timestamp_ps: ts,
            ident: ident.to_string(),
            value,
            bit_width: width,
        }
    }

    pub fn format_binary(&self) -> String {
        if self.bit_width == 1 {
            // VCD scalar value change is `<value><ident>` with no separator
            // (IEEE 1364 VCD). The ident was previously dropped, producing an
            // invalid dump line. Fix for #969.
            format!("{}{}", self.value & 1, self.ident)
        } else {
            format!(
                "b{:0width$b} {}",
                self.value,
                self.ident,
                width = self.bit_width as usize
            )
        }
    }

    pub fn validate(&self) -> Vec<String> {
        let mut errors = Vec::new();
        if self.ident.is_empty() {
            errors.push("VCD change ident must not be empty".to_string());
        }
        if self.bit_width == 0 {
            errors.push("VCD change bit_width must be positive".to_string());
        }
        errors
    }
}

